const DEFAULT_URL = 'https://docs.google.com/spreadsheets/d/1ZDpcz2ACmG63dUjHLfoHZSW7-dG51FbzaJVcqHYdkEI/edit?usp=sharing';

/**
 * Geometry value objects for paginated (A4) printing of the family tree canvas.
 *
 * Printing slices one large tree canvas into a grid of page-sized tiles. Two
 * distinct concerns were previously expressed as long positional argument lists
 * threaded through half a dozen `FamilyTreeBuilder` statics:
 *
 *   1. "How many pages, and at what zoom?"  -> PrintGridSpec
 *   2. "Which content falls on THIS page?"  -> PrintTileBounds
 *
 * Modelling them as small immutable value objects keeps the tile arithmetic
 * (right/bottom edges, canvas padding offsets, viewBox strings) in one place
 * instead of recomputing it at every call site.
 */

/**
 * Immutable rectangle describing a single printable page tile in canvas coordinates.
 *
 * Layout nodes and connector paths are stored in unpadded canvas space, while the
 * rendered canvas is shifted by (padX, padY). This object owns that offset so callers
 * never have to remember to apply it.
 *
 * @example
 * const tile = new PrintTileBounds(0, 0, 800, 600, 15, 15);
 * tile.right;
 * // => 800
 *
 * @example
 * const secondColumn = PrintTileBounds.forGridCell(0, 1, 800, 600, 15, 15);
 * secondColumn.x;
 * // => 800
 */
class PrintTileBounds {
    /** Default rendered width of a person card, in canvas pixels. */
    static DEFAULT_NODE_WIDTH_PX = 90;

    /** Default rendered height of a person card, in canvas pixels. */
    static DEFAULT_NODE_HEIGHT_PX = 76;

    /**
     * Slack (in canvas pixels) added around a tile when testing connector paths, so a
     * line that merely crosses the page is still drawn rather than clipped away.
     */
    static DEFAULT_PATH_MARGIN_PX = 20;

    /**
     * @param {number} x - Tile left edge in canvas coordinates
     * @param {number} y - Tile top edge in canvas coordinates
     * @param {number} width - Tile width in canvas coordinates
     * @param {number} height - Tile height in canvas coordinates
     * @param {number} padX - Horizontal canvas padding applied to node/path coordinates
     * @param {number} padY - Vertical canvas padding applied to node/path coordinates
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).bottom;
     * // => 100
     *
     * @example
     * new PrintTileBounds(800, 600, 800, 600, 10, 10).right;
     * // => 1600
     */
    constructor(x, y, width, height, padX, padY) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.padX = padX;
        this.padY = padY;
        Object.freeze(this);
    }

    /**
     * Builds the tile covering grid cell (row, col) of a uniform tile grid.
     *
     * @param {number} row - Zero-based grid row index
     * @param {number} col - Zero-based grid column index
     * @param {number} tileWidthPx - Uniform tile width in canvas coordinates
     * @param {number} tileHeightPx - Uniform tile height in canvas coordinates
     * @param {number} padX - Horizontal canvas padding
     * @param {number} padY - Vertical canvas padding
     * @returns {PrintTileBounds} Bounds of the requested grid cell
     *
     * @example
     * PrintTileBounds.forGridCell(0, 0, 800, 600, 15, 15).x;
     * // => 0
     *
     * @example
     * PrintTileBounds.forGridCell(1, 2, 800, 600, 15, 15).y;
     * // => 600
     */
    static forGridCell(row, col, tileWidthPx, tileHeightPx, padX, padY) {
        return new PrintTileBounds(col * tileWidthPx, row * tileHeightPx, tileWidthPx, tileHeightPx, padX, padY);
    }

    /**
     * Right edge of the tile in canvas coordinates.
     *
     * @returns {number} x + width
     *
     * @example
     * new PrintTileBounds(0, 0, 800, 600, 0, 0).right;
     * // => 800
     *
     * @example
     * new PrintTileBounds(800, 0, 800, 600, 0, 0).right;
     * // => 1600
     */
    get right() {
        return this.x + this.width;
    }

    /**
     * Bottom edge of the tile in canvas coordinates.
     *
     * @returns {number} y + height
     *
     * @example
     * new PrintTileBounds(0, 0, 800, 600, 0, 0).bottom;
     * // => 600
     *
     * @example
     * new PrintTileBounds(0, 600, 800, 600, 0, 0).bottom;
     * // => 1200
     */
    get bottom() {
        return this.y + this.height;
    }

    /**
     * SVG `viewBox` attribute string for rendering just this tile, rounded to 1 decimal.
     *
     * @returns {string} "x y width height"
     *
     * @example
     * new PrintTileBounds(0, 0, 800, 600, 0, 0).viewBox;
     * // => '0.0 0.0 800.0 600.0'
     *
     * @example
     * new PrintTileBounds(800, 600, 800, 600, 0, 0).viewBox;
     * // => '800.0 600.0 800.0 600.0'
     */
    get viewBox() {
        return `${this.x.toFixed(1)} ${this.y.toFixed(1)} ${this.width.toFixed(1)} ${this.height.toFixed(1)}`;
    }

    /**
     * Tests whether a person card overlaps this tile (axis-aligned rectangle intersection).
     *
     * The node's stored coordinates are unpadded, so the canvas padding is applied here.
     *
     * @param {Object} node - Layout node exposing `x` and `y` in unpadded canvas coordinates
     * @param {number} [nodeWidth=90] - Card width in canvas pixels
     * @param {number} [nodeHeight=76] - Card height in canvas pixels
     * @returns {boolean} True when any part of the card falls inside the tile
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).containsNode({ x: 50, y: 50 });
     * // => true
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).containsNode({ x: 200, y: 200 });
     * // => false
     */
    containsNode(node, nodeWidth = PrintTileBounds.DEFAULT_NODE_WIDTH_PX, nodeHeight = PrintTileBounds.DEFAULT_NODE_HEIGHT_PX) {
        const nx = node.x + this.padX;
        const ny = node.y + this.padY;
        return nx + nodeWidth > this.x && nx < this.right && ny + nodeHeight > this.y && ny < this.bottom;
    }

    /**
     * Tests whether an SVG connector path has any control point inside this tile (plus margin).
     *
     * Coordinates are recovered by scanning the path's `d` string for numbers and reading them
     * as (x, y) pairs, e.g. "M 50 50 L 80 80" -> [[50, 50], [80, 80]].
     *
     * @param {Object} path - Connector path exposing an SVG path string `d`
     * @param {number} [margin=20] - Slack around the tile so crossing segments are retained
     * @returns {boolean} True when any point falls within the expanded tile
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).intersectsPath({ d: 'M 50 50 L 80 80' });
     * // => true
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).intersectsPath({ d: 'M 200 200 L 250 250' });
     * // => false
     */
    intersectsPath(path, margin = PrintTileBounds.DEFAULT_PATH_MARGIN_PX) {
        const nums = (path.d.match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
        if (nums.length < 2) return false;
        for (let i = 0; i < nums.length; i += 2) {
            const px = nums[i] + this.padX;
            const py = nums[i + 1] + this.padY;
            if (px >= this.x - margin && px <= this.right + margin &&
                py >= this.y - margin && py <= this.bottom + margin) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts the cards on this tile and reports whether the page would print blank.
     *
     * A tile is only "empty" when it holds no cards AND no connector passes through it;
     * a page showing just a long lineage connector is still worth printing.
     *
     * @param {Object} layoutData - Layout exposing `nodes` and `paths` arrays
     * @returns {{ nodeCount: number, isEmpty: boolean }} Occupancy summary
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).inspectOccupancy({ nodes: [], paths: [] });
     * // => { nodeCount: 0, isEmpty: true }
     *
     * @example
     * new PrintTileBounds(0, 0, 100, 100, 0, 0).inspectOccupancy({ nodes: [{ x: 10, y: 10 }], paths: [] });
     * // => { nodeCount: 1, isEmpty: false }
     */
    inspectOccupancy(layoutData) {
        const nodeCount = layoutData.nodes.filter(n => this.containsNode(n)).length;
        const hasPath = layoutData.paths.some(p => this.intersectsPath(p));
        return { nodeCount, isEmpty: nodeCount === 0 && !hasPath };
    }
}

/**
 * Immutable description of the printing problem: how big one printable page is, how big the
 * whole canvas is, and how many pages we are allowed to spend.
 *
 * Owns the search for the (cols x rows) split that keeps text as large as possible while
 * staying within the page budget.
 *
 * @example
 * const spec = new PrintGridSpec(1046, 718, 3000, 2000, 10);
 * spec.maxPages;
 * // => 10
 *
 * @example
 * new PrintGridSpec(1000, 700, 500, 350, 1).findOptimalGrid({ cols: 1, rows: 1, scale: 1 });
 * // => { bestC: 1, bestR: 1, bestScale: 2 }
 */
class PrintGridSpec {
    /**
     * Weight applied to aspect-ratio drift when ranking candidate grids. Deliberately tiny:
     * legibility (scale) dominates, and this only breaks ties between equally legible grids
     * in favour of the one whose shape best matches the canvas.
     */
    static ASPECT_RATIO_PENALTY = 0.0001;

    /**
     * @param {number} printableWidthPx - Printable page width in pixels (page minus margins)
     * @param {number} printableHeightPx - Printable page height in pixels
     * @param {number} totalCanvasWidth - Full tree canvas width in pixels
     * @param {number} totalCanvasHeight - Full tree canvas height in pixels
     * @param {number} maxPages - Maximum number of pages the grid may occupy
     *
     * @example
     * new PrintGridSpec(1046, 718, 3000, 2000, 10).totalCanvasWidth;
     * // => 3000
     *
     * @example
     * new PrintGridSpec(1000, 700, 1500, 1000, 8).maxPages;
     * // => 8
     */
    constructor(printableWidthPx, printableHeightPx, totalCanvasWidth, totalCanvasHeight, maxPages) {
        this.printableWidthPx = printableWidthPx;
        this.printableHeightPx = printableHeightPx;
        this.totalCanvasWidth = totalCanvasWidth;
        this.totalCanvasHeight = totalCanvasHeight;
        this.maxPages = maxPages;
        Object.freeze(this);
    }

    /**
     * Scores one candidate grid shape.
     *
     * `candidateScale` is the zoom at which a canvas slice still fits on a page: bigger is more
     * legible. The score then subtracts a negligible penalty for grids whose overall shape
     * distorts the canvas aspect ratio, measured as |log(candidateRatio / canvasRatio)| so that
     * being 2x too wide and 2x too tall are penalised equally.
     *
     * @param {number} cols - Candidate column count
     * @param {number} rows - Candidate row count
     * @returns {{ candidateScale: number, score: number }} Legibility scale and ranking score
     *
     * @example
     * new PrintGridSpec(1000, 700, 3000, 2000, 10).evaluateCandidate(2, 3).candidateScale;
     * // => 0.6666666666666666
     *
     * @example
     * new PrintGridSpec(1000, 700, 500, 350, 1).evaluateCandidate(1, 1).score;
     * // => 2
     */
    evaluateCandidate(cols, rows) {
        const scaleToFitWidth = this.printableWidthPx / (this.totalCanvasWidth / cols);
        const scaleToFitHeight = this.printableHeightPx / (this.totalCanvasHeight / rows);
        const candidateScale = Math.min(scaleToFitWidth, scaleToFitHeight);

        const candidateRatio = (cols * this.printableWidthPx) / (rows * this.printableHeightPx);
        const canvasRatio = this.totalCanvasWidth / this.totalCanvasHeight;
        const ratioDiff = Math.abs(Math.log(candidateRatio / canvasRatio));

        return { candidateScale, score: candidateScale - (ratioDiff * PrintGridSpec.ASPECT_RATIO_PENALTY) };
    }

    /**
     * Exhaustively searches every (cols x rows) grid within the page budget and returns the
     * highest-scoring one, falling back to `defaultCandidate` if nothing scores.
     *
     * @param {{ cols: number, rows: number, scale: number }} defaultCandidate - Fallback grid
     * @returns {{ bestC: number, bestR: number, bestScale: number }} Winning grid shape and zoom
     *
     * @example
     * new PrintGridSpec(1000, 700, 500, 350, 1).findOptimalGrid({ cols: 1, rows: 1, scale: 1 });
     * // => { bestC: 1, bestR: 1, bestScale: 2 }
     *
     * @example
     * new PrintGridSpec(1046, 718, 3000, 2000, 10).findOptimalGrid({ cols: 3, rows: 4, scale: 1.2 }).bestC;
     * // => 5
     */
    findOptimalGrid(defaultCandidate) {
        let bestScore = -1;
        let bestC = defaultCandidate.cols;
        let bestR = defaultCandidate.rows;
        let bestScale = defaultCandidate.scale;

        for (let c = 1; c <= this.maxPages; c++) {
            for (let r = 1; r <= this.maxPages; r++) {
                if (c * r > this.maxPages) continue;
                const { candidateScale, score } = this.evaluateCandidate(c, r);
                if (score > bestScore) {
                    bestScore = score;
                    bestC = c;
                    bestR = r;
                    bestScale = candidateScale;
                }
            }
        }
        return { bestC, bestR, bestScale };
    }

    /**
     * Returns the grid to actually print: keeps the caller's grid when it already fits the page
     * budget, otherwise re-solves for the most legible grid that does.
     *
     * @param {{ cols: number, rows: number, scale: number }} candidate - Unconstrained grid
     * @returns {{ cols: number, rows: number, scale: number, tileWidthPx: number, tileHeightPx: number }} Final grid
     *
     * @example
     * new PrintGridSpec(1000, 700, 1500, 1000, 8).fitWithinPageBudget({ cols: 2, rows: 2, scale: 1 }).cols;
     * // => 2
     *
     * @example
     * new PrintGridSpec(1046, 718, 3000, 2000, 10).fitWithinPageBudget({ cols: 3, rows: 4, scale: 1.2 }).cols;
     * // => 5
     */
    fitWithinPageBudget(candidate) {
        const { cols, rows, scale } = candidate;
        if (cols * rows <= this.maxPages) return this.#withTileSize(cols, rows, scale);

        const { bestC, bestR, bestScale } = this.findOptimalGrid(candidate);
        return this.#withTileSize(bestC, bestR, bestScale);
    }

    /**
     * Expands a grid shape into a full descriptor by deriving the canvas-space tile size.
     *
     * A page is a fixed number of pixels, so zooming in by `scale` means each page covers
     * proportionally *less* canvas — hence the division.
     *
     * @param {number} cols - Column count
     * @param {number} rows - Row count
     * @param {number} scale - Zoom factor
     * @returns {{ cols: number, rows: number, scale: number, tileWidthPx: number, tileHeightPx: number }} Descriptor
     */
    #withTileSize(cols, rows, scale) {
        return {
            cols,
            rows,
            scale,
            tileWidthPx: this.printableWidthPx / scale,
            tileHeightPx: this.printableHeightPx / scale
        };
    }
}

/**
 * Scratch workspace shared by every stage of relative-reference expansion.
 *
 * Spreadsheet rows routinely name people who have no row of their own:
 * "Rosy Daughter 1 Husband" implies a "Rosy Daughter 1" who was never entered.
 * Expansion therefore has to (a) look a name up across both the real rows and
 * the placeholders invented so far, and (b) invent a new placeholder when the
 * lookup misses.
 *
 * Those two abilities plus the accumulator they share used to travel as three
 * separate positional arguments -- `findByName`, `createGhost`, `newNodes` --
 * threaded through a dozen helpers, re-splatted out of the context object in
 * places, and trivially swappable at call sites. This object bundles them so
 * that a single `ws` parameter replaces the trio everywhere.
 */
class GhostWorkspace {
    /**
     * The lookup and factory strategies are injected rather than hard-coded so that
     * this class stays independent of `FamilyTreeBuilder` (and is trivially fakeable).
     *
     * @param {Object[]} nodes - Real (spreadsheet-backed) person nodes; never mutated by this class
     * @param {Function} findCandidate - `(name, contextNode, pool) => Object|null` name resolver
     * @param {Function} buildGhost - `(name, gender, mom, dad, srcId, sequenceIndex) => Object` factory
     *
     * @example
     * const ws = new GhostWorkspace([{ name: 'Rosy' }], find, build);
     * ws.newNodes.length;
     * // => 0
     *
     * @example
     * const ws = new GhostWorkspace([], () => null, (name) => ({ name }));
     * ws.create('Rosy Husband').name;
     * // => 'Rosy Husband'
     */
    constructor(nodes, findCandidate, buildGhost) {
        /** @type {Object[]} Real person nodes parsed from the sheet. */
        this.nodes = nodes;

        /** @type {Object[]} Ghosts synthesized during this expansion run, in creation order. */
        this.newNodes = [];

        this._findCandidate = findCandidate;
        this._buildGhost = buildGhost;
    }

    /**
     * Every node a lookup may match: real rows first, then ghosts invented so far.
     *
     * Rebuilt on each access because `newNodes` grows throughout expansion and a
     * ghost created by an earlier stage must be visible to later ones.
     *
     * @returns {Object[]} Combined candidate pool
     *
     * @example
     * new GhostWorkspace([{ name: 'Rosy' }], find, build).pool.length;
     * // => 1
     *
     * @example
     * const ws = new GhostWorkspace([{ name: 'Rosy' }], () => null, (n) => ({ name: n }));
     * ws.create('Rosy Husband');
     * ws.pool.map(p => p.name);
     * // => ['Rosy', 'Rosy Husband']
     */
    get pool() {
        return [...this.nodes, ...this.newNodes];
    }

    /**
     * Resolves a name against the current pool, preferring candidates near `contextNode`.
     *
     * @param {string} name - Name to resolve (e.g. 'Rosy Daughter 1')
     * @param {Object|null} [contextNode=null] - Node whose sheet row biases proximity scoring
     * @returns {Object|null} Best matching node, or null when the name is unknown
     *
     * @example
     * ws.find('Rosy');
     * // => { name: 'Rosy', ... }
     *
     * @example
     * ws.find('Mother', childNode);
     * // => the 'Mother' nearest childNode's sheet row, not the first one in the file
     */
    find(name, contextNode = null) {
        return this._findCandidate(name, contextNode, this.pool);
    }

    /**
     * Synthesizes a ghost person and appends it to the accumulator.
     *
     * The ghost's sequence index is `newNodes.length` *before* the push, so ghosts are
     * numbered 0, 1, 2, ... in creation order; this feeds their generated ids.
     *
     * @param {string} name - Ghost's display name
     * @param {string} [gender=''] - 'F', 'M', or '' when undetermined
     * @param {Object} [seed={}] - Facts already known about the ghost
     * @param {string} [seed.mom=''] - Mother's name, if already known
     * @param {string} [seed.dad=''] - Father's name, if already known
     * @param {string} [seed.srcId=''] - Sheet source id inherited from the declaring row
     * @returns {Object} The newly created (and already accumulated) ghost node
     *
     * @example
     * ws.create('Rosy Husband', 'M', { srcId: 'sheet1' });
     * // => { name: 'Rosy Husband', gender: 'M', _isGhost: true, ... }
     *
     * @example
     * ws.create('Mary Son 2', 'M', { mom: 'Mary', dad: 'John', srcId: 's1' });
     * // => ghost appended to ws.newNodes with sequence index equal to its position
     */
    create(name, gender = '', { mom = '', dad = '', srcId = '' } = {}) {
        const ghost = this._buildGhost(name, gender, mom, dad, srcId, this.newNodes.length);
        this.newNodes.push(ghost);
        return ghost;
    }

    /**
     * Returns the existing node for `name`, synthesizing a ghost only if none exists.
     *
     * Deliberately resolves without a context node: these are fully-qualified generated
     * names ('Mary Father'), so proximity scoring would add ambiguity, not remove it.
     *
     * @param {string} name - Name to resolve or invent
     * @param {string} [gender=''] - Gender to stamp on a newly created ghost
     * @param {Object} [seed={}] - Facts to stamp on a newly created ghost (see {@link GhostWorkspace#create})
     * @returns {Object} Existing or newly created node
     *
     * @example
     * ws.resolveOrCreate('Mary Mother', 'F', { srcId: 's1' });
     * // => existing 'Mary Mother' row if the sheet had one
     *
     * @example
     * ws.resolveOrCreate('John Father', 'M', { srcId: 's1' });
     * // => freshly synthesized ghost, appended to ws.newNodes
     */
    resolveOrCreate(name, gender = '', seed = {}) {
        return this.find(name) || this.create(name, gender, seed);
    }
}

// ============================================================================
// MODULE 2: UTILITY CLASSES (Data Loading & Parsing)
// ============================================================================

/**
 * DOM id of the JSON payload embedded in exported standalone `.html` trees.
 *
 * Written by `FamilyTreeBuilder` when it serializes a self-contained export;
 * its presence at runtime is what distinguishes a downloaded standalone file
 * from the live, sheet-backed app.
 */
const STANDALONE_DATA_ELEMENT_ID = 'embedded-tree-data';

/**
 * Detects whether the app is running from an exported standalone HTML file.
 *
 * Standalone exports ship their data inline and have no live spreadsheet to
 * poll, so callers use this to drop chrome that only makes sense in the live
 * app (the timeline gutter, background re-sync, import controls).
 *
 * @returns {boolean} True when running inside a standalone export
 *
 * @example
 * isStandaloneExportMode();
 * // => false (live app served from index.html; no embedded payload)
 *
 * @example
 * isStandaloneExportMode();
 * // => true (downloaded Kochuvareed_Tree.html; payload script present)
 */
function isStandaloneExportMode() {
    return typeof document !== 'undefined' && !!document.getElementById(STANDALONE_DATA_ELEMENT_ID);
}

/**
 * Asynchronous external script loader that injects script tags into the document head
 * and resolves once loaded, preventing duplicate script injection.
 *
 * @example
 * await ScriptLoader.load('https://cdnjs.cloudflare.com/ajax/libs/html-to-image/1.11.11/html-to-image.min.js');
 *
 * @example
 * await ScriptLoader.load('https://unpkg.com/leaflet@1.9.4/dist/leaflet.js');
 */
class ScriptLoader {
    /**
     * Loads an external JavaScript library URL asynchronously.
     *
     * @param {string} src - URL of the script to load
     * @returns {Promise<void>} Resolves when script is loaded or already present
     *
     * @example
     * await ScriptLoader.load('/path/to/lib.js');
     *
     * @example
     * await ScriptLoader.load('https://cdn.jsdelivr.net/npm/chart.js');
     */
    static load(src) {
        return new Promise((resolve, reject) => {
            if (document.querySelector(`script[src="${src}"]`)) return resolve();
            const script = document.createElement('script');
            script.src = src;
            script.crossOrigin = 'anonymous';
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
        });
    }
}

/**
 * Robust CSV parsing and tabular record extraction engine for Google Sheets genealogical exports.
 *
 * Handles quote escaping, multi-line cells, embedded first data rows merged into headers,
 * whitespace sanitization, and 1-based spreadsheet row number tracking.
 *
 * @example
 * const records = CSVParser.parse('Name,Age\nAlice,30\nBob,25');
 * // => [{ name: 'Alice', age: '30', _sheetRow: 2 }, { name: 'Bob', age: '25', _sheetRow: 3 }]
 *
 * @example
 * const rows = CSVParser._tokenizeCsv('A,B\nC,D');
 * // => [{ data: ['A', 'B'], sheetRow: 1 }, { data: ['C', 'D'], sheetRow: 2 }]
 */
class CSVParser {
    static {
        if (typeof window !== 'undefined' && !window.appCode) {
            try {
                const xhr = new XMLHttpRequest();
                xhr.open('GET', 'App.jsx?t=' + Date.now(), false);
                xhr.send(null);
                if (xhr.status === 200 || xhr.status === 0) {
                    window.appCode = xhr.responseText;
                    globalThis.appCode = xhr.responseText;
                }
            } catch (e) {}
        }
    }

    static HEADER_WORDS = new Set([
        'name', 'nickname', 'nick', 'year', 'of', 'birth', 'age', 'death',
        'years', 'after', 'mother', 'mom', 'father', 'dad', 'family',
        'spouse', 'husband', 'wife', 'prefer', 'job', 'profession',
        'location', 'place', 'if', 'not', 'available', 'different',
        'from', 'at', 'the', 'free', 'form', 'freeform', 'sibling',
        'gender', 'sex', 'essential', 'maternal', 'paternal',
        'has', 'it', 'any', 'one', 'them', 'all', 'only', 'either', 'or', 'also', 'as', 'such', 'etc', 'other', 'another'
    ]);

    /**
     * Unescapes and trims a raw CSV cell token, stripping quotes and escaped double quotes.
     * 
     * @param {string} token - Raw cell token
     * @returns {string} Cleaned cell string
     *
     * @example
     * CSVParser._cleanCell('"Hello, World"');
     * // => 'Hello, World'
     *
     * @example
     * CSVParser._cleanCell('""Quoted""');
     * // => '"Quoted"'
     */
    static _cleanCell(token) {
        return token.replace(/(^"|"$)/g, '').replace(/""/g, '"').trim();
    }

    /**
     * Sanitizes trailing carriage returns and commits a non-empty parsed CSV row to the collection.
     * 
     * @param {string[]} row - Cell values for the current row
     * @param {number} sheetRow - 1-based spreadsheet row number
     * @param {Array<{ data: string[], sheetRow: number }>} rows - Destination list of parsed rows
     *
     * @example
     * const rows = [];
     * CSVParser._commitParsedRow(['A', 'B\r'], 1, rows);
     * // => rows contains [{ data: ['A', 'B'], sheetRow: 1 }]
     *
     * @example
     * const rows = [];
     * CSVParser._commitParsedRow(['', ''], 2, rows);
     * // => rows remains empty (no truthy cell values)
     */
    static _commitParsedRow(row, sheetRow, rows) {
        if (row.length > 0 && row[row.length - 1].endsWith('\r')) {
            row[row.length - 1] = row[row.length - 1].slice(0, -1);
        }
        if (row.some(Boolean)) {
            rows.push({ data: row, sheetRow });
        }
    }

    /**
     * Extracts, unescapes, and pushes a cell token into the in-progress row array.
     *
     * @private
     * @param {string} str - Source CSV text
     * @param {number} start - Cell substring start index
     * @param {number} end - Cell substring end index
     * @param {string[]} row - Target in-progress row array
     *
     * @example
     * const row = [];
     * CSVParser._consumeCell('name,age', 0, 4, row);
     * // => row is ['name']
     *
     * @example
     * const row = [];
     * CSVParser._consumeCell(' "Bob" , 30', 0, 7, row);
     * // => row is ['Bob']
     */
    static _consumeCell(str, start, end, row) {
        row.push(CSVParser._cleanCell(str.substring(start, end)));
    }

    /**
     * Breaks raw CSV string into lines and tokens, tracking 1-based sheet row numbers.
     * 
     * @param {string} str - Raw CSV string
     * @returns {Array<{ data: string[], sheetRow: number }>} Array of rows with cell data and 1-based sheet row index
     * 
     * @example
     * CSVParser._tokenizeCsv('Name,Age\nAlice,30');
     * // => [{ data: ['Name', 'Age'], sheetRow: 1 }, { data: ['Alice', '30'], sheetRow: 2 }]
     *
     * @example
     * CSVParser._tokenizeCsv('A,B\n\nC,D');
     * // => [{ data: ['A', 'B'], sheetRow: 1 }, { data: ['C', 'D'], sheetRow: 3 }]
     */
    static _tokenizeCsv(str) {
        str = str.replace(/,\s*"(\r?\n|$)/g, ',$1');
        const rows = [];
        let row = [];
        let start = 0;
        let inQuote = false;
        let currentSheetRow = 1;
        
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            if (c === '"') {
                inQuote = !inQuote;
            } else if (c === ',' && !inQuote) {
                CSVParser._consumeCell(str, start, i, row);
                start = i + 1;
            } else if (c === '\n' && !inQuote) {
                CSVParser._consumeCell(str, start, i, row);
                start = i + 1;
                CSVParser._commitParsedRow(row, currentSheetRow, rows);
                currentSheetRow++;
                row = [];
            }
        }
        
        CSVParser._consumeCell(str, start, str.length, row);
        CSVParser._commitParsedRow(row, currentSheetRow, rows);
        return rows;
    }

    /**
     * Splits a raw header string into non-empty line segments and word tokens.
     *
     * @param {string} h - Raw header string
     * @returns {{ lines: string[], words: string[], lastLineWords: string[] }}
     *
     * @example
     * CSVParser._tokenizeHeaderLines("SPOUSE\r\nPrefer Husband");
     * // => { lines: ['SPOUSE', 'Prefer Husband'], words: ['SPOUSE', 'Prefer', 'Husband'], lastLineWords: ['Prefer', 'Husband'] }
     *
     * @example
     * CSVParser._tokenizeHeaderLines("");
     * // => { lines: [], words: [], lastLineWords: [] }
     */
    static _tokenizeHeaderLines(h) {
        if (!h) return { lines: [], words: [], lastLineWords: [] };
        const lines = h.split(/[\r\n]+/).map(s => s.trim()).filter(Boolean);
        const lastLineWords = lines.length > 0 ? lines[lines.length - 1].split(/\s+/) : [];
        const words = h.split(/\s+/);
        return { lines, words, lastLineWords };
    }

    /**
     * Extracts an embedded data value from a header cell if Google Sheets merged
     * the first data cell into the header text.
     * 
     * @param {string} h - Raw header string
     * @param {Set<string>} headerWords - Set of known header keywords
     * @returns {string} Extracted data value, or empty string if purely a header
     * 
     * @example
     * CSVParser._extractEmbeddedHeaderValue("Name Anthony", CSVParser.HEADER_WORDS);
     * // => "Anthony"
     *
     * @example
     * CSVParser._extractEmbeddedHeaderValue("Year of Birth", CSVParser.HEADER_WORDS);
     * // => ""
     */
    static _extractEmbeddedHeaderValue(h, headerWords) {
        if (!h) return '';
        const { lines, words, lastLineWords } = CSVParser._tokenizeHeaderLines(h);
        const targetWords = lines.length > 1 ? lastLineWords : words;
        if (lines.length > 1 || words.length >= 2) {
            const lastWord = targetWords[targetWords.length - 1]?.toLowerCase().replace(/[^a-z]/g, '');
            if (lastWord && !headerWords.has(lastWord)) {
                return targetWords[targetWords.length - 1];
            }
        }
        return '';
    }

    /**
     * Removes an embedded trailing data value from a header cell string.
     * 
     * @param {string} h - Raw header string
     * @param {string} val - Trailing data value to strip
     * @returns {string} Cleaned, lower-cased header label
     * 
     * @example
     * CSVParser._stripEmbeddedHeaderValue("Name Anthony", "Anthony");
     * // => "name"
     *
     * @example
     * CSVParser._stripEmbeddedHeaderValue("SPOUSE\r\nPrefer Husband Thandammama", "Thandammama");
     * // => "spouse prefer husband"
     */
    static _stripEmbeddedHeaderValue(h, val) {
        const { lines, words, lastLineWords } = CSVParser._tokenizeHeaderLines(h);
        if (lines.length > 1) {
            if (lastLineWords[lastLineWords.length - 1] === val) {
                lastLineWords.pop();
                lines[lines.length - 1] = lastLineWords.join(' ');
                return lines.filter(Boolean).join(' ').trim().toLowerCase();
            }
        } else {
            if (words[words.length - 1] === val) {
                words.pop();
                return words.join(' ').trim().toLowerCase();
            }
        }
        return h.toLowerCase();
    }

    /**
     * Evaluates whether a set of headers exhibits embedded first-row data patterns.
     *
     * @param {string[]} rawHeaders - Original trimmed header cell values
     * @param {string[]} embeddedValues - Candidate data values extracted from each header
     * @param {number} embeddedCount - Total number of candidate values found
     * @returns {boolean} True if headers contain embedded first data row
     *
     * @example
     * CSVParser._hasEmbeddedFirstDataRow(['Name Anthony', 'Job Doctor'], ['Anthony', 'Doctor'], 2)
     * // => true
     *
     * @example
     * CSVParser._hasEmbeddedFirstDataRow(['Name', 'Job'], ['', ''], 0)
     * // => false
     */
    static _hasEmbeddedFirstDataRow(rawHeaders, embeddedValues, embeddedCount) {
        if (embeddedCount < 2) return false;
        const nameColIdx = rawHeaders.findIndex(h => h.toLowerCase().startsWith('name'));
        return nameColIdx >= 0 && Boolean(embeddedValues[nameColIdx] && embeddedValues[nameColIdx].trim());
    }

    /**
     * Analyzes raw headers to detect whether the first row of data was merged into the header
     * row during CSV export, separating the header titles and first data row if detected.
     * 
     * @param {string[]} rawHeaders - Array of trimmed header strings
     * @returns {{ headers: string[], firstDataRow: string[] | null }} Cleaned headers and optional extracted first data row
     * 
     * @example
     * CSVParser._resolveHeadersAndFirstDataRow(["Name Anthony", "Job Doctor"])
     * // => { headers: ["name", "job"], firstDataRow: ["Anthony", "Doctor"] }
     *
     * @example
     * CSVParser._resolveHeadersAndFirstDataRow(["Name", "Age"])
     * // => { headers: ["name", "age"], firstDataRow: null }
     */
    static _resolveHeadersAndFirstDataRow(rawHeaders) {
        const embeddedValues = [];
        let embeddedCount = 0;

        rawHeaders.forEach(h => {
            const val = CSVParser._extractEmbeddedHeaderValue(h, CSVParser.HEADER_WORDS);
            embeddedValues.push(val);
            if (val) embeddedCount++;
        });

        if (CSVParser._hasEmbeddedFirstDataRow(rawHeaders, embeddedValues, embeddedCount)) {
            const headers = rawHeaders.map((h, i) => {
                if (!embeddedValues[i]) return h.toLowerCase();
                return CSVParser._stripEmbeddedHeaderValue(h, embeddedValues[i]);
            });
            return { headers, firstDataRow: embeddedValues };
        }

        return { headers: rawHeaders.map(h => h.toLowerCase()), firstDataRow: null };
    }

    /**
     * Constructs a structured object mapping header names to row cell values, attaching _sheetRow.
     *
     * @param {number} sheetRow - 1-based spreadsheet row number
     * @param {string[]} headers - Cleaned header names
     * @param {string[]} values - Cell string values
     * @returns {Object} Structured record object
     *
     * @example
     * CSVParser._createRowObject(2, ['name', 'age'], ['Bob', '25'])
     * // => { _sheetRow: 2, name: 'Bob', age: '25' }
     *
     * @example
     * CSVParser._createRowObject(1, ['name'], ['Alice'])
     * // => { _sheetRow: 1, name: 'Alice' }
     */
    static _createRowObject(sheetRow, headers, values) {
        const obj = { _sheetRow: sheetRow };
        headers.forEach((h, i) => {
            if (h) obj[h] = (values && values[i]) ? values[i] : '';
        });
        return obj;
    }

    /**
     * Converts tokenized row arrays into structured records keyed by header names,
     * including 1-based spreadsheet row indices.
     * 
     * @param {Array<{ data: string[], sheetRow: number }>} rows - Tokenized rows
     * @param {string[]} headers - Cleaned lower-case header names
     * @param {string[] | null} firstDataRow - Optional embedded first data row
     * @returns {Array<Object>} Parsed objects with header properties and _sheetRow
     * 
     * @example
     * CSVParser._mapRowsToObjects([{ data: ['Name', 'Age'], sheetRow: 1 }, { data: ['Bob', '25'], sheetRow: 2 }], ['name', 'age'], null)
     * // => [{ name: 'Bob', age: '25', _sheetRow: 2 }]
     *
     * @example
     * CSVParser._mapRowsToObjects([{ data: ['Name', 'Age'], sheetRow: 1 }], ['name', 'age'], ['Alice', '30'])
     * // => [{ name: 'Alice', age: '30', _sheetRow: 1 }]
     */
    static _mapRowsToObjects(rows, headers, firstDataRow) {
        const results = [];
        if (firstDataRow) {
            results.push(CSVParser._createRowObject(rows[0].sheetRow, headers, firstDataRow));
        }

        rows.slice(1).forEach((r) => {
            results.push(CSVParser._createRowObject(r.sheetRow, headers, r.data));
        });
        return results;
    }

    /**
     * Parses a raw CSV string into structured record objects keyed by lowercase header names,
     * including 1-based spreadsheet row indices (_sheetRow).
     *
     * @param {string} str - Raw CSV string
     * @returns {Array<Object>} Parsed row objects
     *
     * @example
     * const records = CSVParser.parse("Name,Age\nAlice,30");
     * // => [{ name: "Alice", age: "30", _sheetRow: 2 }]
     *
     * @example
     * const empty = CSVParser.parse("");
     * // => []
     */
    static parse(str) {
        if (!str || typeof str !== 'string') return [];
        const rows = CSVParser._tokenizeCsv(str);
        if (rows.length < 2) return [];

        const rawHeaders = rows[0].data.map(h => h.trim());
        const { headers, firstDataRow } = CSVParser._resolveHeadersAndFirstDataRow(rawHeaders);
        return CSVParser._mapRowsToObjects(rows, headers, firstDataRow);
    }
}

// ============================================================================
// MODULE 3: DOMAIN MODELS (Data Encapsulation)
// ============================================================================

/**
 * Domain model representing a single person in the family tree.
 * Encapsulates logic for formatting, display, and relational queries.
 *
 * @example
 * const person = new Person({ id: 'p1', name: 'John', yob: 1980, gender: 'M' });
 * person.currentAge; // => calculated age
 *
 * @example
 * const nun = new Person({ id: 'p2', name: 'Sr. Mary', yob: 1950 });
 * nun.isNun; // => true
 */
class Person {
    /**
     * Identifies spreadsheet instruction text, relational column subtitles,
     * or non-geographic entries (such as "husband/FATHER" or "if husband/father has it")
     * that should be avoided and never treated as real locations.
     * 
     * @param {string|null} p - Raw location string
     * @returns {boolean} True if the string is invalid / not a real location
     *
     * @example
     * Person.isInvalidLocation("husband/FATHER");
     * // => true
     *
     * @example
     * Person.isInvalidLocation("Chicago, IL");
     * // => false
     */
    static isInvalidLocation(p) {
        if (!p) return true;
        const s = p.toString().trim().toLowerCase();
        if (!s) return true;
        if (/\bhusband\s*[/]\s*father\b/i.test(s)) return true;
        if (/\b(?:if\s+)?(?:different\s+from\s+)?(?:husband|wife|father|mother|spouse|parents?)(?:\s*[/]\s*(?:father|mother|husband|wife))?(?:\s+(?:has\s+it|not\s+available|available))?/i.test(s) && 
            (s.includes('husband') || s.includes('father') || s.includes('mother') || s.includes('spouse'))) {
            const clean = s.replace(/^(?:location\s+)?(?:if\s+)?(?:different\s+from\s+)?/i, '')
                           .replace(/\s+(?:has\s+it|not\s+available|available).*$/i, '')
                           .trim();
            if (/^(?:husband|wife|father|mother|spouse|parents?)(?:\s*[/]\s*(?:father|mother|husband|wife|spouse))?$/i.test(clean)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Infers an estimated death year (at age 90) for individuals born over 100 years ago
     * who have no explicit death year recorded.
     *
     * @param {number|string|null} effectiveYob - Birth year (exact or inferred)
     * @param {number} [currentYear] - Reference year, defaults to current calendar year
     * @returns {number|null} Inferred death year or null if not applicable
     *
     * @example
     * Person.inferCentenarianDeath(1900, 2026);
     * // => 1990
     *
     * @example
     * Person.inferCentenarianDeath(1950, 2026);
     * // => null
     */
    static inferCentenarianDeath(effectiveYob, currentYear = new Date().getFullYear()) {
        const yob = effectiveYob ? parseInt(effectiveYob, 10) : null;
        if (yob && !isNaN(yob) && (currentYear - effectiveYob > 100)) {
            return yob + 90;
        }
        return null;
    }

    /**
     * Applies resolved religious vocation and gender attributes to a person.
     *
     * @param {Person} p - Person instance to mutate
     * @param {'Nun'|'Priest'} vocation - Religious role name
     * @param {'F'|'M'} gender - Associated gender code
     *
     * @example
     * const p = { name: 'Sr. Teresa' };
     * Person._applyReligiousVocation(p, 'Nun', 'F');
     * // => p.isNun === true, p.isCelibate === true, p.job === 'Nun', p.gender === 'F'
     *
     * @example
     * const p = { name: 'Fr. Joseph' };
     * Person._applyReligiousVocation(p, 'Priest', 'M');
     * // => p.isPriest === true, p.isCelibate === true, p.job === 'Priest', p.gender === 'M'
     */
    static _applyReligiousVocation(p, vocation, gender) {
        p.isCelibate = true;
        if (vocation === 'Nun') p.isNun = true;
        else if (vocation === 'Priest') p.isPriest = true;
        if (!p.job) p.job = vocation;
        if (!p.gender) p.gender = gender;
    }

    /**
     * Infers male gender from traditional patriarchal and generational name suffixes.
     *
     * @param {string} lowerName - Normalized lowercase name
     * @returns {boolean} True if name contains a male suffix indicator
     *
     * @example
     * Person._hasMaleNameSuffix('kuttappan');
     * // => true
     *
     * @example
     * Person._hasMaleNameSuffix('george son 2');
     * // => true
     */
    static _hasMaleNameSuffix(lowerName) {
        return lowerName.endsWith('appan') || lowerName.endsWith('son') || /\bson(?:\s+\d+)?$/i.test(lowerName);
    }

    /**
     * Identifies religious title prefix in normalized name or nickname ('sr.' for Nun, 'fr.' for Priest).
     *
     * @param {string} lowerName - Normalized lowercase name
     * @param {string} lowerNick - Normalized lowercase nickname
     * @returns {?{ vocation: string, gender: string }} Vocation object or null
     *
     * @example
     * Person._matchReligiousPrefix('sr. maria', '');
     * // => { vocation: 'Nun', gender: 'F' }
     *
     * @example
     * Person._matchReligiousPrefix('fr. thomas', '');
     * // => { vocation: 'Priest', gender: 'M' }
     */
    static _matchReligiousPrefix(lowerName, lowerNick) {
        if (/^sr(?:\.|\s)\s*/i.test(lowerName) || /^sr(?:\.|\s)\s*/i.test(lowerNick)) {
            return { vocation: 'Nun', gender: 'F' };
        }
        if (/^fr(?:\.|\s)\s*/i.test(lowerName) || /^fr(?:\.|\s)\s*/i.test(lowerNick)) {
            return { vocation: 'Priest', gender: 'M' };
        }
        return null;
    }

    /**
     * Resolves religious vocation, title ontology, and default gender attributes for a person
     * based on their name and nickname patterns.
     *
     * @param {Person} p - Person instance to mutate
     *
     * @example
     * const p = { name: 'Sr. Teresa', nick: '' };
     * Person._resolveTitleAndVocationAttributes(p);
     * // => p.isNun === true, p.gender === 'F', p.job === 'Nun'
     *
     * @example
     * const p = { name: 'Fr. Joseph', nick: '' };
     * Person._resolveTitleAndVocationAttributes(p);
     * // => p.isPriest === true, p.gender === 'M', p.job === 'Priest'
     */
    static _resolveTitleAndVocationAttributes(p) {
        if (!p.name) return;
        const lowerName = p.name.toLowerCase().trim();
        const lowerNick = (p.nick || '').toLowerCase().trim();
        const titleMatch = (typeof FamilyTreeBuilder !== 'undefined' && FamilyTreeBuilder.matchTitleOntology)
            ? FamilyTreeBuilder.matchTitleOntology(lowerName, lowerNick)
            : null;
        if (titleMatch) {
            if (titleMatch.isCelibate) p.isCelibate = true;
            if (titleMatch.isNun) p.isNun = true;
            if (titleMatch.isPriest) p.isPriest = true;
            if (titleMatch.career && !p.job) p.job = titleMatch.career;
            if (titleMatch.gender && !p.gender) p.gender = titleMatch.gender;
        } else {
            const prefix = Person._matchReligiousPrefix(lowerName, lowerNick);
            if (prefix) {
                Person._applyReligiousVocation(p, prefix.vocation, prefix.gender);
            } else if (!p.gender && Person._hasMaleNameSuffix(lowerName)) {
                p.gender = 'M';
            }
        }
    }

    /**
     * Infers death year for centenarian persons when death year is missing.
     *
     * @param {Person} p - Person instance to mutate
     *
     * @example
     * const p = { yob: 1910 };
     * Person._applyCentenarianDeathInference(p);
     * // => p.death === 2000
     *
     * @example
     * const p = { yob: 1980 };
     * Person._applyCentenarianDeathInference(p);
     * // => p.death is undefined
     */
    static _applyCentenarianDeathInference(p) {
        if (p.death) return;
        const effectiveYob = p.yob ? parseInt(p.yob, 10) : (p._inferredYob ? parseInt(p._inferredYob, 10) : null);
        const inferredDeath = Person.inferCentenarianDeath(effectiveYob);
        if (inferredDeath) {
            p.death = inferredDeath;
        }
    }

    /**
     * Constructs a new Person instance, initializing collections and deducing titles and lifespans.
     *
     * @param {Object} data - Raw profile attributes from sheet or JSON
     *
     * @example
     * const p = new Person({ id: 'john', name: 'John Doe', yob: 1970 });
     * p.partners; // => []
     *
     * @example
     * const p = new Person({ id: 'mary', name: 'Mary', place: 'husband/FATHER' });
     * p.place; // => '' (invalid location stripped)
     */
    constructor(data) {
        Object.assign(this, data);
        this.partners = this.partners || [];
        this.children = this.children || [];
        this.ambiguities = this.ambiguities || [];

        if (this.place && Person.isInvalidLocation(this.place)) {
            this.place = '';
        }

        Person._resolveTitleAndVocationAttributes(this);
        Person._applyCentenarianDeathInference(this);
    }

    /**
     * Retrieves array of valid parent IDs (mother and father).
     *
     * @type {string[]}
     *
     * @example
     * const p = new Person({ id: 'c1', momId: 'm1', fatherId: 'f1' });
     * p.parents; // => ['m1', 'f1']
     *
     * @example
     * const p = new Person({ id: 'c2', fatherId: 'f1' });
     * p.parents; // => ['f1']
     */
    get parents() {
        if (this.momId && this.fatherId && this.momId === this.fatherId) {
            return [this.momId];
        }
        const set = new Set([this.momId, this.fatherId, this._namedParentId].filter(Boolean));
        return Array.from(set);
    }

    /**
     * Calculates the current age in years (or age at death for deceased individuals).
     *
     * @type {number|null}
     *
     * @example
     * const p = new Person({ id: 'p1', yob: 1990, death: 2020 });
     * p.currentAge; // => 30
     *
     * @example
     * const p = new Person({ id: 'p2' });
     * p.currentAge; // => null
     */
    get currentAge() {
        const yob = this.yob || this._inferredYob;
        if (!yob) return null;
        const yobNum = parseInt(yob, 10);
        if (isNaN(yobNum)) return null;
        const currentYear = new Date().getFullYear();
        let d = this.death ? parseInt(this.death, 10) : null;
        if (!d) {
            d = Person.inferCentenarianDeath(yobNum, currentYear);
        }
        return (d ? d : currentYear) - yobNum;
    }

    /**
     * Selects an appropriate representative portrait emoji based on age and gender.
     *
     * @type {string}
     *
     * @example
     * const child = new Person({ id: 'c', yob: 2024, gender: 'M' });
     * child.emoji; // => '👶🏻'
     *
     * @example
     * const elder = new Person({ id: 'e', yob: 1950, gender: 'F' });
     * elder.emoji; // => '👵🏻'
     */
    get emoji() {
        const age = this.currentAge;
        const g = this.gender;
        if (age !== null && !isNaN(age)) {
            if (age <= 3) return '👶🏻';
            if (age <= 12) return g === 'M' ? '👦🏻' : g === 'F' ? '👧🏻' : '🧒🏻';
            if (age >= 60) return g === 'M' ? '👴🏻' : g === 'F' ? '👵🏻' : '🧓🏻';
        }
        return g === 'M' ? '👨🏻' : g === 'F' ? '👩🏻' : '🧑🏻';
    }

    /**
     * Resolves the primary 1-based spreadsheet row number for sorting and provenance citations.
     *
     * @type {number}
     *
     * @example
     * const p = new Person({ id: 'p1', _sheetRow: 42 });
     * p.sheetRow; // => 42
     *
     * @example
     * const p = new Person({ id: 'p2' });
     * p.sheetRow; // => 99999
     */
    get sheetRow() {
        if (this._sheetRows) {
            let sRows = this._sheetRows;
            if (typeof sRows === 'string') {
                try { sRows = JSON.parse(sRows); } catch (e) { sRows = null; }
            }
            if (sRows && typeof sRows === 'object' && Object.keys(sRows).length > 0) {
                const vals = Object.values(sRows).map(v => parseInt(v, 10)).filter(v => !isNaN(v));
                if (vals.length > 0) return Math.min(...vals);
            }
        }
        if (this._sheetRow !== undefined && this._sheetRow !== null) {
            return this._sheetRow;
        }
        return 99999;
    }

    /**
     * Returns the most reliable birth year, preferring explicit yob over inferred yob.
     *
     * @type {number|string}
     *
     * @example
     * const p = new Person({ id: 'p1', yob: 1985, _inferredYob: 1983 });
     * p.bestYob; // => 1985
     *
     * @example
     * const p = new Person({ id: 'p2', _inferredYob: 1960 });
     * p.bestYob; // => 1960
     */
    get bestYob() {
        return this.yob || this._inferredYob || 9999;
    }

    /**
     * Formats a lifespan and years-ago recency description for card badges.
     *
     * @param {number} lifespan - Computed lifespan in years
     * @param {number} yrsAgo - Elapsed years since death
     * @param {string} [prefix=''] - Formatting prefix ('~' for deduced dates)
     * @returns {string} Formatted card date text (e.g. "90y, 16y ago" or "~90y, 16y ago")
     *
     * @example
     * Person._formatCardLifespanRecency(90, 16, '');
     * // => "90y, 16y ago"
     *
     * @example
     * Person._formatCardLifespanRecency(90, 16, '~');
     * // => "~90y, 16y ago"
     */
    static _formatCardLifespanRecency(lifespan, yrsAgo, prefix = '') {
        const agoStr = yrsAgo > 0 ? `, ${yrsAgo}y ago` : (yrsAgo === 0 ? ', this year' : '');
        return `${prefix}${lifespan}y${agoStr}`;
    }

    /**
     * Formats a death-only recency description for card badges.
     *
     * @param {number} yrsAgo - Elapsed years since death
     * @param {number} yodNum - Year of death
     * @returns {string} Formatted death recency text (e.g. "16y ago", "this year", or "d. 2010")
     *
     * @example
     * Person._formatCardDeathRecency(16, 2010);
     * // => "16y ago"
     *
     * @example
     * Person._formatCardDeathRecency(0, 2026);
     * // => "this year"
     */
    static _formatCardDeathRecency(yrsAgo, yodNum) {
        return yrsAgo > 0 ? `${yrsAgo}y ago` : (yrsAgo === 0 ? 'this year' : `d. ${yodNum}`);
    }

    /**
     * Formats concise card date labels and tooltip strings for a person's lifespan.
     *
     * @param {number|null} effectiveYob - Concrete or deduced birth year
     * @param {number|null} yodNum - Year of death
     * @param {number} currentYear - Reference calendar year
     * @param {boolean} isDeduced - Whether the birth year was deduced
     * @returns {{ cardText: string, titleText: string, isDeduced: boolean }}
     *
     * @example
     * Person._formatCardDateStrings(1920, 2010, 2026, false);
     * // => { cardText: "90y, 16y ago", titleText: "1920 - 2010", isDeduced: false }
     *
     * @example
     * Person._formatCardDateStrings(1950, null, 2026, true);
     * // => { cardText: "~76y", titleText: "b. ~1950 (deduced)", isDeduced: true }
     */
    static _formatCardDateStrings(effectiveYob, yodNum, currentYear, isDeduced) {
        const prefix = isDeduced ? '~' : '';

        if (effectiveYob && yodNum) {
            const lifespan = Math.max(0, yodNum - effectiveYob);
            const yrsAgo = currentYear - yodNum;
            const cardText = Person._formatCardLifespanRecency(lifespan, yrsAgo, prefix);
            const titleText = `${prefix}${effectiveYob} - ${yodNum}${isDeduced ? ' (deduced birth year)' : ''}`;
            return { cardText, titleText, isDeduced };
        }

        if (effectiveYob) {
            const age = Math.max(0, currentYear - effectiveYob);
            const cardText = `${prefix}${age}y`;
            const titleText = `b. ${prefix}${effectiveYob}${isDeduced ? ' (deduced)' : ''}`;
            return { cardText, titleText, isDeduced };
        }

        if (yodNum) {
            const yrsAgo = currentYear - yodNum;
            const cardText = Person._formatCardDeathRecency(yrsAgo, yodNum);
            const titleText = `d. ${yodNum}`;
            return { cardText, titleText, isDeduced: false };
        }

        return { cardText: '', titleText: '', isDeduced: false };
    }

    /**
     * Formats concise lifespan and recency information for display on the tree node card.
     * 
     * @param {number} [currentYear] - Reference year, defaults to current calendar year
     * @returns {{ cardText: string, titleText: string, isDeduced: boolean }}
     *
     * @example
     * const p = new Person({ id: 'p1', yob: 1920, death: 2010 });
     * p.getCardDateString(2026);
     * // => { cardText: "90y, 16y ago", titleText: "1920 - 2010", isDeduced: false }
     *
     * @example
     * const p = new Person({ id: 'p2', _inferredYob: 1950 });
     * p.getCardDateString(2026);
     * // => { cardText: "~76y", titleText: "b. ~1950 (deduced)", isDeduced: true }
     */
    getCardDateString(currentYear = new Date().getFullYear()) {
        const yobNum = this.yob ? parseInt(this.yob, 10) : null;
        const infYobNum = this._inferredYob ? parseInt(this._inferredYob, 10) : null;
        let yodNum = this.death ? parseInt(this.death, 10) : null;

        const effectiveYob = yobNum || infYobNum;
        let isDeduced = !yobNum && !!infYobNum;

        // If age is deduced (not specified) to be > 100 without death, set lifespan to 90 years and mark as dead
        if (!yodNum && effectiveYob) {
            const inferredDeath = Person.inferCentenarianDeath(effectiveYob, currentYear);
            if (inferredDeath) {
                yodNum = inferredDeath;
                isDeduced = true;
            }
        }

        return Person._formatCardDateStrings(effectiveYob, yodNum, currentYear, isDeduced);
    }

    /**
     * Formats biographical date strings and age/lifespan summaries for a person.
     * 
     * @param {number|null} effectiveYob - Concrete or deduced year of birth
     * @param {number|null} deathNum - Year of death
     * @param {number} currentYear - Current reference year
     * @param {boolean} isDeduced - Whether year of birth is inferred
     * @returns {{ dateStr: string, extraStr: string, isDeduced: boolean }}
     *
     * @example
     * Person._formatLifeSpanDateStrings(1950, 2020, 2026, false);
     * // => { dateStr: '1950 - 2020', extraStr: '70 yrs • 6 yrs ago', isDeduced: false }
     *
     * @example
     * Person._formatLifeSpanDateStrings(1980, null, 2026, false);
     * // => { dateStr: 'b. 1980', extraStr: '46 yrs', isDeduced: false }
     */
    static _formatLifeSpanDateStrings(effectiveYob, deathNum, currentYear, isDeduced) {
        const prefix = isDeduced ? '~' : '';

        if (effectiveYob && deathNum) {
            const dateStr = `${prefix}${effectiveYob} - ${deathNum}`;
            const yrsAgo = currentYear - deathNum;
            const yrsAgoStr = yrsAgo > 0 ? ` • ${yrsAgo} yrs ago` : (yrsAgo === 0 ? ' • this year' : '');
            const extraStr = `${prefix}${deathNum - effectiveYob} yrs${yrsAgoStr}`;
            return { dateStr, extraStr, isDeduced };
        }

        if (effectiveYob) {
            const dateStr = `b. ${prefix}${effectiveYob}`;
            const extraStr = `${prefix}${currentYear - effectiveYob} yrs`;
            return { dateStr, extraStr, isDeduced };
        }

        if (deathNum) {
            const dateStr = `d. ${deathNum}`;
            const yrsAgo = currentYear - deathNum;
            const extraStr = yrsAgo > 0 ? `${yrsAgo} yrs ago` : (yrsAgo === 0 ? 'this year' : '');
            return { dateStr, extraStr, isDeduced: false };
        }

        return { dateStr: '', extraStr: '', isDeduced: false };
    }

    /**
     * Computes biographical date strings and lifespan metrics for this person instance.
     *
     * @returns {{ dateStr: string, extraStr: string, isDeduced: boolean }}
     *
     * @example
     * person.getDateStrings();
     * // => { dateStr: '1920 - 2010', extraStr: '90 yrs • 16 yrs ago', isDeduced: false }
     *
     * @example
     * livingPerson.getDateStrings();
     * // => { dateStr: 'b. ~1960', extraStr: '~66 yrs', isDeduced: true }
     */
    getDateStrings() {
        const currentYear = new Date().getFullYear();
        const yobNum = this.yob ? parseInt(this.yob, 10) : null;
        const infYobNum = this._inferredYob ? parseInt(this._inferredYob, 10) : null;
        let deathNum = this.death ? parseInt(this.death, 10) : null;
        const effectiveYob = yobNum || infYobNum;
        const isDeduced = !yobNum && !!infYobNum;

        // If age is deduced (not specified) to be > 100 without death, set lifespan to 90 years and mark as dead
        if (!deathNum && effectiveYob) {
            deathNum = Person.inferCentenarianDeath(effectiveYob, currentYear);
        }

        return Person._formatLifeSpanDateStrings(effectiveYob, deathNum, currentYear, isDeduced);
    }

    /**
     * Checks if a child is biologically and genealogically compatible with a spousal unit's parents.
     *
     * @param {Person} child - Child node to test
     * @param {Person[]} unitParents - Array of parents (person and their partners) in the display unit
     * @returns {boolean} True if child is compatible with the unit parents
     *
     * @example
     * Person._isChildValidForUnitParents(childNode, [fatherNode, motherNode]);
     * // => true
     *
     * @example
     * Person._isChildValidForUnitParents({ yob: 1980, momId: 'otherMom' }, [{ id: 'unitMom', gender: 'F' }]);
     * // => false (already assigned to different mother)
     */
    static _isChildValidForUnitParents(child, unitParents) {
        if (!child.yob) return true;

        for (const p of unitParents) {
            // If this parent is officially linked, they validate this child
            if (p.id === child.momId || p.id === child.fatherId || p.id === child._namedParentId) continue;
            // Avoid linking a child to a generic parent of the same gender if they already have one
            if (p.gender === 'F' && child.momId) continue;
            if (p.gender === 'M' && child.fatherId) continue;

            // Validate realistic age gaps
            if (p.yob) {
                const ageDiff = child.yob - p.yob;
                if (ageDiff < 10 || (p.gender === 'F' && ageDiff > 55) || (p.gender === 'M' && ageDiff > 80)) return false;
            }
        }
        return true;
    }

    /**
     * Compares two siblings for visual display order under parents based on explicit YOB,
     * spreadsheet row order, best inferred YOB, and name child numbering.
     *
     * @param {Person} a - First sibling
     * @param {Person} b - Second sibling
     * @returns {number} Negative if a precedes b, positive if b precedes a
     *
     * @example
     * Person._compareSiblingDisplayOrder(childA, childB);
     * // => -1 (childA displayed before childB)
     *
     * @example
     * Person._compareSiblingDisplayOrder({ yob: 1990 }, { yob: 1985 });
     * // => 5 (child with earlier birth year sorted first)
     */
    static _compareSiblingDisplayOrder(a, b) {
        const yA = a.bestYob, yB = b.bestYob;
        if (yA && yB && yA !== yB) return yA - yB;
        const rA = a.sheetRow, rB = b.sheetRow;
        if (rA < 99999 && rB < 99999 && rA !== rB && FamilyTreeBuilder.sharesSheet(a, b)) {
            return rA - rB;
        }
        return (a._nameChildNumber || 0) - (b._nameChildNumber || 0);
    }

    /** 
     * Filters and sorts the children of this person to determine the visually valid display children
     * belonging under this family unit (vs. being displayed under a different spouse), sorted in chronological order.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @returns {Person[]} Chronologically ordered display child nodes
     *
     * @example
     * const displayChildren = person.getValidDisplayChildren(tree);
     * // => [firstChildNode, secondChildNode]
     *
     * @example
     * const childless = personWithoutKids.getValidDisplayChildren(tree);
     * // => []
     */
    getValidDisplayChildren(tree) {
        const partners = this.partners.map(id => tree.get(id)).filter(Boolean);
        const unitParents = [this, ...partners];
        
        return this.children.filter(cId => {
            const child = tree.get(cId);
            if (!child) return false;
            return Person._isChildValidForUnitParents(child, unitParents);
        }).map(cId => tree.get(cId)).sort((a, b) => Person._compareSiblingDisplayOrder(a, b));
    }
}

/**
 * Domain model representing the entire Family Tree.
 * Encapsulates graph traversal, statistics, and validation logic.
 *
 * @example
 * const tree = new FamilyTree({ p1: { id: 'p1', name: 'Root' } }, 'p1');
 * tree.root.name; // => 'Root'
 *
 * @example
 * const tree = new FamilyTree();
 * tree.getMaxGenerations(); // => 1
 */
class FamilyTree {
    /**
     * Identifies whether a person entity is a synthetic ghost parent created solely to hold sibling relationships.
     * 
     * @param {Object} person - The person instance to inspect
     * @returns {boolean} True if person is a synthetic sibling ghost parent
     *
     * @example
     * FamilyTree.isSyntheticSiblingParent({ isGhost: true, name: 'Rosa Father' });
     * // => true
     *
     * @example
     * FamilyTree.isSyntheticSiblingParent({ id: 'real', isGhost: false });
     * // => false
     */
    static isSyntheticSiblingParent(person) {
        if (!person || !person.isGhost) return false;
        if (person._isSyntheticSiblingParent) return true;
        if (person.name && (person.name.endsWith(' Father') || person.name.endsWith(' Mother'))) {
            if (!person.momId && !person.fatherId && !person.mom && !person.father) {
                return true;
            }
        }
        return false;
    }

    /**
     * Constructs a FamilyTree populated with Person instances.
     *
     * @param {Object} [nodeMap={}] - Dictionary mapping person IDs to profile objects
     * @param {string|null} [rootId=null] - Primary root node identifier
     * @param {Object} [sheetNames={}] - Dictionary of spreadsheet tab names
     *
     * @example
     * const tree = new FamilyTree({ a: { id: 'a', name: 'Alice' } }, 'a');
     * tree.root.id; // => 'a'
     *
     * @example
     * const emptyTree = new FamilyTree();
     * emptyTree.all; // => []
     */
    constructor(nodeMap = {}, rootId = null, sheetNames = {}) {
        this.nodes = {};
        for (const [id, data] of Object.entries(nodeMap)) {
            this.nodes[id] = new Person(data);
        }
        this.rootId = rootId;
        this.sheetNames = sheetNames;
    }

    /**
     * Looks up a person instance by identifier.
     *
     * @param {string} id - Person ID
     * @returns {Person|null} Person instance or null if absent
     *
     * @example
     * tree.get('p1'); // => Person instance
     *
     * @example
     * tree.get('unknown'); // => null
     */
    get(id) { return this.nodes[id] || null; }

    /**
     * Retrieves the primary root person instance.
     *
     * @type {Person|null}
     *
     * @example
     * tree.root; // => primary root Person
     *
     * @example
     * const empty = new FamilyTree();
     * empty.root; // => null
     */
    get root() { return this.get(this.rootId); }

    /**
     * Retrieves an array of all person instances in the tree.
     *
     * @type {Person[]}
     *
     * @example
     * tree.all.length; // => total count of people
     *
     * @example
     * const names = tree.all.map(p => p.name);
     */
    get all() { return Object.values(this.nodes); }

    /**
     * Determines whether a person node has no concrete parent lineage in the tree (acts as an ancestral root).
     *
     * @param {Person} person - Domain person node
     * @returns {boolean} True if person lacks concrete, non-ghost parents
     *
     * @example
     * tree._isLineageRoot(adam);
     * // => true
     *
     * @example
     * tree._isLineageRoot(childWithParents);
     * // => false
     */
    _isLineageRoot(person) {
        if (!person) return false;
        const mom = this.get(person.momId);
        const dad = this.get(person.fatherId);
        return (!mom || mom.isGhost || mom._isUnknown) && (!dad || dad.isGhost || dad._isUnknown);
    }

    /**
     * Computes the maximum downward generational depth from a starting person node using memoized traversal.
     *
     * @param {string} id - Person ID
     * @param {Map<string, number>} memo - Memoization map for computed subtree depths
     * @param {Set<string>} [visited=new Set()] - Set of visited node IDs to guard against cycles
     * @returns {number} Subtree depth (minimum 1)
     *
     * @example
     * tree._computeSubtreeGenerations('rootId', new Map());
     * // => 3
     *
     * @example
     * tree._computeSubtreeGenerations('leafId', new Map());
     * // => 1
     */
    _computeSubtreeGenerations(id, memo, visited = new Set()) {
        if (!id || visited.has(id)) return 0;
        if (memo.has(id)) return memo.get(id);

        visited.add(id);
        const p = this.get(id);
        if (!p || !p.children || p.children.length === 0) {
            memo.set(id, 1);
            return 1;
        }

        let maxChild = 0;
        for (const cId of p.children) {
            maxChild = Math.max(maxChild, this._computeSubtreeGenerations(cId, memo, new Set(visited)));
        }

        const depth = 1 + maxChild;
        memo.set(id, depth);
        return depth;
    }

    /**
     * Calculates the maximum generational height of the tree using memoized DAG depth traversal.
     * 
     * @returns {number} The maximum generational depth (minimum 1)
     * 
     * @example
     * tree.getMaxGenerations();
     * // => 4 (Great-grandfather -> Grandfather -> Father -> Child)
     *
     * @example
     * const singleNodeTree = new FamilyTree({ a: { id: 'a' } }, 'a');
     * singleNodeTree.getMaxGenerations();
     * // => 1
     */
    getMaxGenerations() {
        const memo = new Map();
        let maxGen = 1;
        const validNodes = this.all.filter(p => !p.isGhost && !p._isUnknown);
        for (const p of validNodes) {
            if (this._isLineageRoot(p)) {
                maxGen = Math.max(maxGen, this._computeSubtreeGenerations(p.id, memo));
            }
        }
        return Math.max(1, maxGen);
    }

    /**
     * Resolves the effective birth year for the root node, falling back to the earliest
     * child's YOB if the root is a synthetic sibling ghost parent.
     *
     * @returns {number} Effective root YOB
     *
     * @example
     * tree._resolveRootDisplayYob();
     * // => 1920
     *
     * @example
     * ghostTree._resolveRootDisplayYob();
     * // => 1945 (derived from earliest child)
     */
    _resolveRootDisplayYob() {
        if (!this.root) return 1900;
        if (FamilyTree.isSyntheticSiblingParent(this.root) && this.root.children && this.root.children.length > 0) {
            const childYobs = this.root.children.map(cid => this.get(cid)?.bestYob).filter(Boolean);
            if (childYobs.length > 0) return Math.min(...childYobs);
        }
        return this.root.bestYob;
    }

    /**
     * Returns aggregate demographic and generational metrics for the tree.
     * 
     * @returns {{ minYear: number, maxYear: number, rootNodeYob: number, generationsCount: number, totalPeople: number }}
     * 
     * @example
     * tree.getStats();
     * // => { minYear: 1850, maxYear: 2024, rootNodeYob: 1850, generationsCount: 5, totalPeople: 120 }
     *
     * @example
     * const empty = new FamilyTree();
     * empty.getStats();
     * // => { minYear: 1900, maxYear: 2026, rootNodeYob: 1900, generationsCount: 1, totalPeople: 0 }
     */
    getStats() {
        const allYobs = this.all.map(p => p.yob || p._inferredYob).filter(y => y > 0);
        const minYear = allYobs.length > 0 ? Math.min(...allYobs) : 1900;
        const maxYear = allYobs.length > 0 ? Math.max(...allYobs) : new Date().getFullYear();
        const generationsCount = this.getMaxGenerations();

        return {
            minYear,
            maxYear,
            rootNodeYob: this._resolveRootDisplayYob(),
            generationsCount,
            totalPeople: this.all.filter(p => !p.isGhost && !p._isUnknown).length
        };
    }

    /**
     * Checks whether a sibling candidate's birth year is biologically compatible with the mother and father.
     * Enforces minimum parental childbirth age, maximum maternal childbirth age (with older child threshold),
     * and maximum paternal childbirth age.
     *
     * @param {Person} sib - Sibling candidate profile
     * @param {Person|null} mom - Mother profile
     * @param {Person|null} dad - Father profile
     * @param {FamilyTree} tree - Family tree instance
     * @returns {boolean} True if age difference is biologically plausible
     *
     * @example
     * // sib.yob = 1950, mom.yob = 1925 (age gap 25 yrs):
     * FamilyTree._isPlausibleSiblingAge({ yob: 1950 }, { yob: 1925 }, null, tree);
     * // => true
     *
     * @example
     * // sib.yob = 1950, mom.yob = 1945 (age gap 5 yrs, below minimum parental age 14):
     * FamilyTree._isPlausibleSiblingAge({ yob: 1950 }, { yob: 1945 }, null, tree);
     * // => false
     */
    static _isPlausibleSiblingAge(sib, mom, dad, tree) {
        if (!sib) return false;
        if (!sib.yob) return true;

        if (mom && mom.yob) {
            const ageDiff = sib.yob - mom.yob;
            if (ageDiff < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE || ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE) return false;
            if (ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD) {
                const hasValidFirstChild = mom.children.some(cId => {
                    const cn = tree ? tree.get(cId) : null;
                    if (!cn || !cn.yob) return false;
                    const cDiff = cn.yob - mom.yob;
                    return cDiff >= FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE && cDiff <= FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD;
                });
                if (!hasValidFirstChild) return false;
            }
        }
        if (dad && dad.yob) {
            const ageDiff = sib.yob - dad.yob;
            if (ageDiff < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE || ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE) return false;
        }
        return true;
    }

    /**
     * Retrieves all valid siblings of a person sharing either mother or father, subject to biological age checks.
     * 
     * @param {string} personId - ID of the target person
     * @returns {Person[]} Array of verified sibling Person entities
     * 
     * @example
     * tree.getSiblings('john_1980');
     * // => [maryPerson, davidPerson]
     *
     * @example
     * tree.getSiblings('onlyChild');
     * // => []
     */
    getSiblings(personId) {
        const p = this.get(personId);
        if (!p) return [];
        
        const siblingsSet = new Set();
        const mom = this.get(p.momId);
        const dad = this.get(p.fatherId);

        if (mom) mom.children.forEach(id => siblingsSet.add(id));
        if (dad) dad.children.forEach(id => siblingsSet.add(id));
        siblingsSet.delete(p.id);
        
        return Array.from(siblingsSet)
            .map(id => this.get(id))
            .filter(sib => FamilyTree._isPlausibleSiblingAge(sib, mom, dad, this));
    }

    /**
     * Traverses upward along parental edges to collect terminal root ancestors, recording for
     * each one how many generations up it sits and whether it was reached purely through
     * father links. Those two facts are properties of the GRAPH, which lets
     * {@link FamilyTree._sortRootAncestors} rank roots without leaning on birth years that may
     * themselves have been synthesised from demographic priors.
     *
     * @param {string} id - Current node ID
     * @param {Set<string>} visited - Visited node IDs
     * @param {Array<Object>} roots - Accumulated `{ person, depth, viaFatherOnly }` records
     * @param {number} [depth=0] - Generations climbed so far from the starting node
     * @param {boolean} [viaFatherOnly=true] - Whether every edge climbed so far was a father link
     *
     * @example
     * // Child -> father Jacob (no parents of his own) and mother Mary (likewise).
     * const roots = [];
     * tree._collectUpwardRoots('neville', new Set(), roots);
     * // => [{ person: Jacob, depth: 1, viaFatherOnly: true },
     * //     { person: Mary,  depth: 1, viaFatherOnly: false }]
     *
     * @example
     * // A node that is already a root reports itself at depth 0.
     * const roots = [];
     * tree._collectUpwardRoots('rootId', new Set(), roots);
     * // => [{ person: rootPerson, depth: 0, viaFatherOnly: true }]
     */
    _collectUpwardRoots(id, visited, roots, depth = 0, viaFatherOnly = true) {
        if (!id || visited.has(id)) return;
        visited.add(id);
        const p = this.get(id);
        if (!p) return;

        const hasValidFather = p.fatherId && this.get(p.fatherId);
        const hasValidMom = p.momId && this.get(p.momId);

        if (!hasValidFather && !hasValidMom) {
            roots.push({ person: p, depth, viaFatherOnly });
        } else {
            if (hasValidFather) this._collectUpwardRoots(p.fatherId, visited, roots, depth + 1, viaFatherOnly);
            // Stepping through a mother permanently marks this path as no longer purely paternal.
            if (hasValidMom) this._collectUpwardRoots(p.momId, visited, roots, depth + 1, false);
        }
    }

    /**
     * Ranks candidate root ancestors, most senior first.
     *
     * Seniority is decided by the SHAPE of the lineage rather than by birth years, because a
     * root's `bestYob` is frequently deduced from demographic priors: ranking on it meant that
     * nudging, say, the husband/wife age offset by one year could silently rename a person's
     * oldest ancestor. Order of precedence:
     *   1. depth        - the root furthest up the lineage wins (an in-law leaf parent must
     *                     never outrank a lineage going back several generations)
     *   2. recorded yob - only when BOTH roots have one; comparing a recorded year against a
     *                     deduced one just ranks the priors that produced the deduced one
     *   3. paternal     - the root reached purely through father links, matching how these
     *                     trees are conventionally rooted
     *   4. concrete     - a real person outranks a ghost/unknown placeholder
     *   5. best yob     - final deterministic tie-break, deduced years included
     *
     * @param {Array<Object>} roots - `{ person, depth, viaFatherOnly }` records from {@link FamilyTree._collectUpwardRoots}
     * @returns {Array<Object>} Same records, most senior ancestor first
     *
     * @example
     * // Depth beats birth year: a great-grandparent outranks a young in-law parent.
     * FamilyTree._sortRootAncestors([
     *     { person: { id: 'jossy', yob: 1942 }, depth: 1, viaFatherOnly: true },
     *     { person: { id: 'rosaSister' },       depth: 3, viaFatherOnly: false }]);
     * // => [rosaSister record, jossy record]
     *
     * @example
     * // Equal depth and only one recorded year: the paternal line wins.
     * FamilyTree._sortRootAncestors([
     *     { person: { id: 'mary', yob: 1949 }, depth: 1, viaFatherOnly: false },
     *     { person: { id: 'jacob' },           depth: 1, viaFatherOnly: true }]);
     * // => [jacob record, mary record]
     */
    static _sortRootAncestors(roots) {
        return [...roots].sort((a, b) => {
            if (a.depth !== b.depth) return b.depth - a.depth;

            const recordedA = a.person.yob;
            const recordedB = b.person.yob;
            if (recordedA && recordedB && recordedA !== recordedB) return recordedA - recordedB;

            if (a.viaFatherOnly !== b.viaFatherOnly) return a.viaFatherOnly ? -1 : 1;

            const aReal = !a.person.isGhost && !a.person._isUnknown ? 1 : 0;
            const bReal = !b.person.isGhost && !b.person._isUnknown ? 1 : 0;
            if (aReal !== bReal) return bReal - aReal;

            return (a.person.bestYob || 9999) - (b.person.bestYob || 9999);
        });
    }

    /**
     * Traverses upward along parental edges to discover the earliest patriarch/matriarch in the lineage.
     * 
     * @param {string} startId - Starting person ID
     * @returns {string} ID of the oldest root ancestor
     * 
     * @example
     * tree.getOldestAncestor('child_2010');
     * // => 'great_grandpa_1920'
     *
     * @example
     * tree.getOldestAncestor('orphan_1950');
     * // => 'orphan_1950'
     */
    getOldestAncestor(startId) {
        const startPerson = this.get(startId);
        if (!startPerson) return startId;
        const roots = [];

        const hasParents = (p) => p && ((p.fatherId && this.get(p.fatherId)) || (p.momId && this.get(p.momId)));

        if (hasParents(startPerson)) {
            this._collectUpwardRoots(startId, new Set(), roots);
        } else {
            // If start person has no parents, check partners for available ancestor trees
            for (const pId of startPerson.partners || []) {
                const partner = this.get(pId);
                if (hasParents(partner)) {
                    this._collectUpwardRoots(pId, new Set([startId]), roots);
                }
            }
            if (roots.length === 0) {
                this._collectUpwardRoots(startId, new Set(), roots);
            }
        }

        if (roots.length === 0) return startId;
        return FamilyTree._sortRootAncestors(roots)[0].person.id;
    }

    /**
     * Enqueues visible display children of a person into the BFS queue.
     *
     * @param {Person} person - Subject person
     * @param {Set<string>} visible - Set of accumulated visible IDs
     * @param {Array<string>} queue - BFS exploration queue
     * @param {Set<string>} collapsedNodes - Set of collapsed person IDs
     *
     * @example
     * this._enqueueDisplayChildren(person, visible, queue, collapsedNodes);
     * // => enqueues children into queue
     *
     * @example
     * this._enqueueDisplayChildren(childlessPerson, visible, queue, collapsedNodes);
     * // => queue remains unchanged
     */
    _enqueueDisplayChildren(person, visible, queue, collapsedNodes) {
        if (!person) return;
        person.getValidDisplayChildren(this).forEach(child => {
            if (child.momId && collapsedNodes.has(child.momId)) return;
            if (child.fatherId && collapsedNodes.has(child.fatherId)) return;
            if (!visible.has(child.id)) queue.push(child.id);
        });
    }

    /**
     * Determines whether a co-spouse node should be expanded as part of the visible tree unit.
     *
     * @param {Person} coSpouse - Candidate co-spouse node
     * @param {Set<string>} visible - Set of visible person IDs
     * @returns {boolean} True if co-spouse should be made visible
     *
     * @example
     * tree._shouldExpandCoSpouse(coSpouse, visible);
     * // => true
     *
     * @example
     * tree._shouldExpandCoSpouse(null, visible);
     * // => false
     */
    _shouldExpandCoSpouse(coSpouse, visible) {
        if (!coSpouse || coSpouse._isUnknown) return false;
        const hasParentsInTree = (coSpouse.momId && visible.has(coSpouse.momId)) ||
                                 (coSpouse.fatherId && visible.has(coSpouse.fatherId));
        return !hasParentsInTree;
    }

    /**
     * Determines whether a valid display child of a co-spouse belongs under the co-spouse
     * within the current matrimonial unit `[person, partner, coSpouse]`.
     * Includes children shared with `partner` as well as single-parent / prior-marriage children
     * of `coSpouse` whose other parent is absent or unknown in the tree.
     *
     * @param {Person} child - Child node of the co-spouse
     * @param {Person} coSpouse - Co-spouse person node
     * @param {Person} partner - Connecting partner node
     * @param {FamilyTree} tree - Family tree instance
     * @returns {boolean} True if child should be displayed under coSpouse in this unit
     *
     * @example
     * // Prior-marriage child of Devasikkutty (fatherId === devasikkutty.id, momId === null):
     * FamilyTree._isCoSpouseChildInUnit(daughter, devasikkutty, anne, tree);
     * // => true
     *
     * @example
     * // Shared child of co-spouse Thankamma and partner Joseph:
     * FamilyTree._isCoSpouseChildInUnit(sherly, thankamma, joseph, tree);
     * // => true
     */
    static _isCoSpouseChildInUnit(child, coSpouse, partner, tree) {
        if (!child || !coSpouse || !partner) return false;
        if (child.momId === partner.id || child.fatherId === partner.id) return true;
        const otherParentId = child.fatherId === coSpouse.id
            ? child.momId
            : (child.momId === coSpouse.id ? child.fatherId : null);
        const otherParent = (otherParentId && tree?.get) ? tree.get(otherParentId) : null;
        return !otherParent || Boolean(otherParent._isUnknown);
    }

    /**
     * Enqueues valid display children of a co-spouse in the marriage unit if not collapsed.
     *
     * @param {Person} coSpouse - Co-spouse person node
     * @param {Person} partner - Common partner node
     * @param {Set<string>} visible - Set of visible person IDs
     * @param {Array<string>} queue - BFS node traversal queue
     * @param {Set<string>} collapsedNodes - Set of collapsed node IDs
     *
     * @example
     * tree._enqueueCoSpouseChildren(coSpouse, partner, visible, queue, collapsedNodes);
     *
     * @example
     * tree._enqueueCoSpouseChildren(emptyCoSpouse, partner, visible, queue, collapsedNodes);
     */
    _enqueueCoSpouseChildren(coSpouse, partner, visible, queue, collapsedNodes) {
        if (collapsedNodes.has(coSpouse.id)) return;
        coSpouse.getValidDisplayChildren(this).forEach(child => {
            if (!FamilyTree._isCoSpouseChildInUnit(child, coSpouse, partner, this)) return;
            if (child.momId && collapsedNodes.has(child.momId)) return;
            if (child.fatherId && collapsedNodes.has(child.fatherId)) return;
            if (!visible.has(child.id)) queue.push(child.id);
        });
    }

    /**
     * Expands partner nodes and reachable co-spouses into the visible node set.
     *
     * @param {Person} person - Subject person node
     * @param {Set<string>} visible - Set of visible person IDs
     * @param {Array<string>} queue - BFS node traversal queue
     * @param {Set<string>} collapsedNodes - Set of collapsed node IDs
     *
     * @example
     * this._expandPartnerAndCoSpouses(person, visible, queue, collapsedNodes);
     * // => partners added to visible Set
     *
     * @example
     * this._expandPartnerAndCoSpouses(singlePerson, visible, queue, collapsedNodes);
     * // => visible remains unchanged
     */
    _expandPartnerAndCoSpouses(person, visible, queue, collapsedNodes) {
        const partners = person.partners.map(id => this.get(id)).filter(Boolean);
        partners.forEach(partner => {
            visible.add(partner.id);
            partner.partners.forEach(coSpouseId => {
                if (coSpouseId === person.id || visible.has(coSpouseId)) return;
                const coSpouse = this.get(coSpouseId);
                if (this._shouldExpandCoSpouse(coSpouse, visible)) {
                    visible.add(coSpouse.id);
                    this._enqueueCoSpouseChildren(coSpouse, partner, visible, queue, collapsedNodes);
                }
            });
        });
    }

    /**
     * Computes the subset of visible nodes in the visual layout via BFS from the root, respecting collapsed subtree states.
     * 
     * @param {Set<string>} collapsedNodes - Set of collapsed person IDs
     * @returns {Set<string>} Set of visible person IDs
     * 
     * @example
     * tree.getVisibleNodes(new Set(['grandpa_1940']));
     * // => Returns root + spouses, omitting grandpa's collapsed descendants
     *
     * @example
     * tree.getVisibleNodes();
     * // => Returns all reachable nodes when nothing is collapsed
     */
    getVisibleNodes(collapsedNodes = new Set()) {
        const visible = new Set();
        if (!this.rootId || !this.root) return visible;
        
        const queue = [this.rootId];
        let qIdx = 0;
        
        while (qIdx < queue.length) {
            const currId = queue[qIdx++];
            if (visible.has(currId)) continue;
            
            const person = this.get(currId);
            if (!person) continue;
            
            visible.add(currId);
            this._expandPartnerAndCoSpouses(person, visible, queue, collapsedNodes);

            if (!collapsedNodes.has(currId)) {
                this._enqueueDisplayChildren(person, visible, queue, collapsedNodes);
            }
        }
        return visible;
    }

    /**
     * Partitions partners and co-spouses around a person based on marriage order / age.
     *
     * @param {Object} person - Bloodline person node
     * @param {Array<Object>} sortedPartners - Sorted partner nodes
     * @param {Array<Object>} coSpouseEntries - Co-spouse entries
     * @returns {{ partnersLeft: Array<Object>, partnersRight: Array<Object> }}
     *
     * @example
     * FamilyTree._partitionPartnersByCoSpouses(person, [p1], []);
     * // => { partnersLeft: [], partnersRight: [p1] }
     *
     * @example
     * FamilyTree._partitionPartnersByCoSpouses(olderWife, [husband], [{ partner: husband, coSpouse: youngerWife }]);
     * // => { partnersLeft: [], partnersRight: [husband, youngerWife] }
     */
    static _partitionPartnersByCoSpouses(person, sortedPartners, coSpouseEntries) {
        const partnersLeft = [];
        const partnersRight = [];
        sortedPartners.forEach(p => {
            const pCoSpouses = coSpouseEntries.filter(e => e.partner.id === p.id).map(e => e.coSpouse);
            const personScore = person.bestYob || 9999;
            const coSpouseScore = pCoSpouses.length > 0 ? (pCoSpouses[0].bestYob || 9999) : 9999;

            if (personScore <= coSpouseScore) {
                // person is older wife: person on left of p, co-spouses on right of p -> [person, p, ...coSpouses]
                partnersRight.push(p, ...pCoSpouses);
            } else {
                // person is younger wife: co-spouses on left of p, person on right of p -> [...coSpouses, p, person]
                partnersLeft.push(...pCoSpouses, p);
            }
        });
        return { partnersLeft, partnersRight };
    }

    /**
     * Determines whether a partner should be positioned to the left of the bloodline person
     * based on gender roles (husbands on left, wives on right) or chronological age.
     *
     * @param {Object} partner - Partner node to place
     * @param {Object} person - Central bloodline person node
     * @returns {boolean} True if partner should be placed to the left
     *
     * @example
     * FamilyTree._isPartnerPlacedOnLeft({ gender: 'M' }, { gender: 'F' });
     * // => true (male partner placed on left)
     *
     * @example
     * FamilyTree._isPartnerPlacedOnLeft({ gender: 'F' }, { gender: 'M' });
     * // => false (female partner placed on right)
     */
    static _isPartnerPlacedOnLeft(partner, person) {
        if (partner.gender === 'M') return true;
        if (partner.gender === 'F') return false;
        if (person.gender === 'M') return false;
        if (person.gender === 'F') return true;
        return partner.bestYob < person.bestYob;
    }

    /**
     * Partitions partners to left or right of a person based on gender and age conventions.
     *
     * @param {Object} person - Bloodline person node
     * @param {Array<Object>} sortedPartners - Sorted partner nodes
     * @returns {{ partnersLeft: Array<Object>, partnersRight: Array<Object> }}
     *
     * @example
     * FamilyTree._partitionPartnersByGender({ gender: 'M' }, [{ gender: 'F' }]);
     * // => { partnersLeft: [], partnersRight: [wife] }
     *
     * @example
     * FamilyTree._partitionPartnersByGender({ gender: 'F' }, [{ gender: 'M' }]);
     * // => { partnersLeft: [husband], partnersRight: [] }
     */
    static _partitionPartnersByGender(person, sortedPartners) {
        const partnersLeft = [];
        const partnersRight = [];
        sortedPartners.forEach(p => {
            if (FamilyTree._isPartnerPlacedOnLeft(p, person)) {
                partnersLeft.push(p);
            } else {
                partnersRight.push(p);
            }
        });
        return { partnersLeft, partnersRight };
    }

    /**
     * Determines the horizontal sequence of family members (person, direct partners, and co-spouses)
     * for a family unit layout, ensuring shared partners bridge their respective spouses without crossing.
     * 
     * @param {Object} person - Bloodline person node
     * @param {Array<Object>} sortedPartners - Partners of person sorted by YOB
     * @param {Array<Object>} coSpouseEntries - Co-spouse entries: { partner, coSpouse }
     * @param {boolean} isMultiSpouseSplit - Whether multi-spouse split layout applies
     * @returns {{ familyMembers: Array<Object>, bloodlineIndex: number }}
     * 
     * @example
     * FamilyTree._orderFamilyMembers(Kochuthresia, [Joseph], [{ partner: Joseph, coSpouse: Thankamma }]);
     * // => { familyMembers: [Thankamma, Joseph, Kochuthresia], bloodlineIndex: 2 }
     *
     * @example
     * FamilyTree._orderFamilyMembers(Joseph, [Kochuthresia, Thankamma], [], true);
     * // => { familyMembers: [Kochuthresia, Joseph, Thankamma], bloodlineIndex: 1 }
     */
    static _orderFamilyMembers(person, sortedPartners, coSpouseEntries = [], isMultiSpouseSplit = false) {
        if (coSpouseEntries.length > 0) {
            const { partnersLeft, partnersRight } = FamilyTree._partitionPartnersByCoSpouses(person, sortedPartners, coSpouseEntries);
            return {
                familyMembers: [...partnersLeft, person, ...partnersRight],
                bloodlineIndex: partnersLeft.length
            };
        }

        if (isMultiSpouseSplit) {
            const mid = Math.ceil(sortedPartners.length / 2);
            const pLeft = sortedPartners.slice(0, mid);
            const pRight = sortedPartners.slice(mid);
            return {
                familyMembers: [...pLeft, person, ...pRight],
                bloodlineIndex: pLeft.length
            };
        }

        const { partnersLeft, partnersRight } = FamilyTree._partitionPartnersByGender(person, sortedPartners);
        return {
            familyMembers: [...partnersLeft, person, ...partnersRight],
            bloodlineIndex: partnersLeft.length
        };
    }

    /**
     * Normalizes a string by folding consecutive duplicate vowels into single instances.
     *
     * @param {string} s - Input string
     * @returns {string} Folded vowel string
     *
     * @example
     * FamilyTree.foldVowels("Ouseph") => "ouseph"
     *
     * @example
     * FamilyTree.foldVowels("Mariam") => "mariam"
     */
    static foldVowels(s) {
        if (!s) return '';
        if (typeof FamilyTreeBuilder !== 'undefined' && typeof FamilyTreeBuilder.foldVowels === 'function') {
            return FamilyTreeBuilder.foldVowels(s);
        }
        return s.toLowerCase().trim().replace(/([aeiou])\1+/g, '$1');
    }

    /**
     * Checks if a candidate co-spouse should be attached to the current family unit.
     * Co-spouses are eligible if they are not already visited, are known entities,
     * and do not have parents visible elsewhere in the tree (which would give them their own tree placement).
     *
     * @example
     * // Husband's second wife without parents in tree:
     * FamilyTree._isEligibleCoSpouse(secondWife, config)
     * // => true
     *
     * @example
     * // Co-spouse with visible parents elsewhere in tree:
     * FamilyTree._isEligibleCoSpouse(secondWifeWithParents, config)
     * // => false
     *
     * @private
     * @param {Person|null} candidate - Candidate co-spouse node
     * @param {Object} layoutConfig - Layout configuration
     * @returns {boolean} True if eligible to attach
     */
    static _isEligibleCoSpouse(candidate, layoutConfig) {
        if (!candidate || candidate._isUnknown) return false;
        const visibleNodes = layoutConfig?.visibleNodes;
        const hasVisibleParents = Boolean(
            (candidate.momId && visibleNodes?.has(candidate.momId)) ||
            (candidate.fatherId && visibleNodes?.has(candidate.fatherId))
        );
        return !hasVisibleParents;
    }

    /**
     * Identifies co-spouses through partners (e.g. husband's other wives) who lack visible parents in the tree.
     *
     * @param {Person} person - Subject bloodline person
     * @param {Array<Person>} partners - Partners of person
     * @param {FamilyTree} tree - Tree instance
     * @param {Object} layoutConfig - Layout configuration
     * @param {Set<string|number>} localVisited - Visited node ID set
     * @returns {Array<{partner: Person, coSpouse: Person}>}
     *
     * @example
     * FamilyTree._findCoSpouseEntries(firstWife, [husband], tree, config, visited)
     * // => [{ partner: husband, coSpouse: secondWife }]
     *
     * @example
     * FamilyTree._findCoSpouseEntries(personWithoutPartners, [], tree, config, visited)
     * // => []
     */
    static _findCoSpouseEntries(person, partners, tree, layoutConfig, localVisited) {
        const coSpouseEntries = [];
        for (const p of partners) {
            for (const coSpouseId of p.partners) {
                if (coSpouseId === person.id || localVisited.has(coSpouseId)) continue;
                const cs = tree.get(coSpouseId);
                if (FamilyTree._isEligibleCoSpouse(cs, layoutConfig)) {
                    coSpouseEntries.push({ partner: p, coSpouse: cs });
                    localVisited.add(cs.id);
                }
            }
        }
        return coSpouseEntries;
    }

    /**
     * Resolves a parent within the family unit whose name is prefixed in a child's descriptive title (e.g. 'Tensy3 Son 1').
     *
     * @param {Person} child - Child profile
     * @param {Array<Person>} unitParents - Available parent profiles in the family unit
     * @returns {Person|null} Matching parent or null
     *
     * @example
     * FamilyTree._findParentNamedInChildTitle({ name: 'Tensy3 Son 1' }, [dad, momTensy])
     * // => momTensy
     *
     * @example
     * FamilyTree._findParentNamedInChildTitle({ name: 'George' }, [dad, mom])
     * // => null
     */
    static _findParentNamedInChildTitle(child, unitParents) {
        const childWordsPattern = '(?:Daughter|Dau|Son|Girl|Boy|Child|Children|Kids)';
        const namedMatch = (child?.name || '').match(new RegExp(`^(.*?)\\s+${childWordsPattern}(?:\\s+\\d+)?$`, 'i'));
        if (!namedMatch) return null;

        const parentNamePart = namedMatch[1].toLowerCase().trim();
        const parentFolded = FamilyTree.foldVowels(parentNamePart);
        return unitParents.find(p => {
            if (!p?.name) return false;
            const pNorm = p.name.toLowerCase().trim();
            return pNorm === parentNamePart || FamilyTree.foldVowels(pNorm) === parentFolded || p._normName === parentNamePart;
        }) || null;
    }

    /**
     * Determines whether a parent node matches a child's declared or linked parental fields (ID or name).
     *
     * @param {Person} child - Child profile
     * @param {Person} parentNode - Candidate parent profile
     * @param {'mother'|'father'|null} [role=null] - Specific parental role to check, or null for either
     * @returns {boolean} True if parentNode matches child's parental link or declaration
     *
     * @example
     * FamilyTree._matchesChildParent({ momId: 'p1' }, { id: 'p1' }, 'mother')
     * // => true
     *
     * @example
     * FamilyTree._matchesChildParent({ father: 'John' }, { name: 'John' }, 'father')
     * // => true
     */
    static _matchesChildParent(child, parentNode, role = null) {
        if (!child || !parentNode) return false;
        const pName = parentNode.name?.toLowerCase().trim();

        if (role === 'mother') {
            return child.momId === parentNode.id || Boolean(child.mom && pName && child.mom.toLowerCase().trim() === pName);
        }
        if (role === 'father') {
            return child.fatherId === parentNode.id || Boolean(child.father && pName && child.father.toLowerCase().trim() === pName);
        }
        return child.momId === parentNode.id ||
               child.fatherId === parentNode.id ||
               child._namedParentId === parentNode.id ||
               Boolean(child.mom && pName && child.mom.toLowerCase().trim() === pName) ||
               Boolean(child.father && pName && child.father.toLowerCase().trim() === pName);
    }

    /**
     * Resolves the primary parent node in a family unit for a child using naming patterns,
     * biological parent IDs, or bloodline fallbacks.
     *
     * @param {Person} child - The child person instance
     * @param {Person} person - The central bloodline person of the family unit
     * @param {Array<Person>} unitParents - All parents in the unit (person, partners, co-spouses)
     * @param {Array<Person>} unitMothers - Mothers in the unit
     * @param {Array<Person>} unitFathers - Fathers in the unit
     * @returns {Person} The resolved parent node to which the child should attach
     *
     * @example
     * FamilyTree._findTargetParentForChild(childWithMotherId, dad, [dad, mom1, mom2], [mom1, mom2], [dad])
     * // => mom1
     *
     * @example
     * FamilyTree._findTargetParentForChild(namedChild, dad, [dad, mom], [mom], [dad])
     * // => dad
     */
    static _findTargetParentForChild(child, person, unitParents, unitMothers, unitFathers) {
        // 1. Primary Rule: Children names containing parent names (e.g. "Tensy3 Son 1") connect to that parent
        const namedParent = FamilyTree._findParentNamedInChildTitle(child, unitParents);
        if (namedParent) return namedParent;

        // 2. If multiple mothers/fathers are present in this unit, assign each child to their biological parent
        if (unitMothers.length > 1) {
            const matchedMother = unitMothers.find(m => FamilyTree._matchesChildParent(child, m, 'mother'));
            if (matchedMother) return matchedMother;
        } else if (unitFathers.length > 1) {
            const matchedFather = unitFathers.find(m => FamilyTree._matchesChildParent(child, m, 'father'));
            if (matchedFather) return matchedFather;
        }

        // 3. Fallback: prioritize the bloodline person if they are a parent, then any matching parent in the unit
        if (FamilyTree._matchesChildParent(child, person)) return person;

        return unitParents.find(m => FamilyTree._matchesChildParent(child, m)) || person;
    }

    /**
     * Initializes the partner-child map with empty arrays for person, partners, and uncollapsed co-spouses.
     *
     * @example
     * // person: P1, partners: [W1], coSpouseEntries: [{ partner: W1, coSpouse: H2 }]
     * FamilyTree._initPartnerChildMap(person, partners, coSpouseEntries, isCollapsed, layoutConfig, tree);
     * // => { 'P1': [], 'W1': [], 'H2': [children of H2 with W1] }
     *
     * @example
     * FamilyTree._initPartnerChildMap(soloPerson, [], [], false, config, tree)
     * // => { 'P1': [] }
     *
     * @param {Object} person - Primary node
     * @param {Array<Object>} partners - List of direct partner nodes
     * @param {Array<{partner: Object, coSpouse: Object}>} coSpouseEntries - Co-spouse pairs
     * @param {boolean} isCollapsed - Whether the family unit is collapsed
     * @param {Object} layoutConfig - Layout options containing collapsedNodes set
     * @param {FamilyTree} tree - Active family tree model
     * @returns {Object.<string, Array<Object>>} Initialized mapping of parent id to child arrays
     */
    static _initPartnerChildMap(person, partners, coSpouseEntries, isCollapsed, layoutConfig, tree) {
        const partnerChildMap = {};
        partnerChildMap[person.id] = [];
        partners.forEach(p => { partnerChildMap[p.id] = []; });
        coSpouseEntries.forEach(({ partner: p, coSpouse: cs }) => {
            partnerChildMap[cs.id] = cs.getValidDisplayChildren(tree).filter(c =>
                FamilyTree._isCoSpouseChildInUnit(c, cs, p, tree)
            );
        });
        return partnerChildMap;
    }

    /**
     * Determines whether children are split across multiple spouses/units,
     * resetting single-parent assignments to the primary person if not split.
     *
     * @example
     * // Only person P1 has children, no co-spouses:
     * FamilyTree._resolveMultiSpouseSplit(partnerChildMap, person, partners, coSpouseEntries, children);
     * // => false (and partnerChildMap[person.id] = children)
     *
     * @example
     * // Multiple partners have children:
     * FamilyTree._resolveMultiSpouseSplit({ 'W1': [c1], 'W2': [c2] }, dad, [mom1, mom2], [], [c1, c2]);
     * // => true
     *
     * @param {Object.<string, Array<Object>>} partnerChildMap - Mapping of parent id to child list
     * @param {Object} person - Primary person node
     * @param {Array<Object>} partners - Direct partner nodes
     * @param {Array<Object>} coSpouseEntries - Co-spouse pairs
     * @param {Array<Object>} children - Complete list of unit children
     * @returns {boolean} True if layout requires multi-spouse splitting, false otherwise
     */
    static _resolveMultiSpouseSplit(partnerChildMap, person, partners, coSpouseEntries, children) {
        const membersWithChildren = Object.entries(partnerChildMap).filter(([id, list]) => list.length > 0);
        if (membersWithChildren.length > 1 || coSpouseEntries.length > 0) {
            return true;
        }
        if (membersWithChildren.length === 1 && membersWithChildren[0][0] !== person.id) {
            return true;
        }
        partners.forEach(p => { partnerChildMap[p.id] = []; });
        partnerChildMap[person.id] = children;
        return false;
    }

    /**
     * Assigns children to their respective parents within a matrimonial unit,
     * determining whether layout requires a multi-spouse split.
     *
     * @param {Object} unitMembers - Matrimonial unit members ({ person, partners, coSpouseEntries })
     * @param {Array<Object>} children - Children of this unit
     * @param {Object} context - Layout and tree context ({ isCollapsed, layoutConfig, tree })
     * @returns {{ partnerChildMap: Object.<string, Array<Object>>, isMultiSpouseSplit: boolean }}
     *
     * @example
     * FamilyTree._assignChildrenToParents({ person: dad, partners: [mom1, mom2], coSpouseEntries: [] }, [child1, child2], { isCollapsed: false, layoutConfig: config, tree })
     * // => { partnerChildMap: { [mom1.id]: [child1], [mom2.id]: [child2] }, isMultiSpouseSplit: true }
     *
     * @example
     * FamilyTree._assignChildrenToParents({ person: dad, partners: [mom], coSpouseEntries: [] }, [child1], { isCollapsed: false, layoutConfig: config, tree })
     * // => { partnerChildMap: { [dad.id]: [child1], [mom.id]: [] }, isMultiSpouseSplit: false }
     */
    static _assignChildrenToParents(unitMembers, children, context) {
        const { person, partners, coSpouseEntries } = unitMembers;
        const { isCollapsed, layoutConfig, tree } = context;
        const partnerChildMap = FamilyTree._initPartnerChildMap(person, partners, coSpouseEntries, isCollapsed, layoutConfig, tree);

        const unitParents = [person, ...partners, ...coSpouseEntries.map(e => e.coSpouse)];
        const unitMothers = unitParents.filter(m => m.gender === 'F' || (!m.gender && m.spouseType === 'husband'));
        const unitFathers = unitParents.filter(m => m.gender === 'M' || (!m.gender && m.spouseType === 'wife'));

        children.forEach(child => {
            const targetParent = FamilyTree._findTargetParentForChild(child, person, unitParents, unitMothers, unitFathers);
            if (!partnerChildMap[targetParent.id]) partnerChildMap[targetParent.id] = [];
            partnerChildMap[targetParent.id].push(child);
        });

        const isMultiSpouseSplit = FamilyTree._resolveMultiSpouseSplit(partnerChildMap, person, partners, coSpouseEntries, children);
        return { partnerChildMap, isMultiSpouseSplit };
    }

    /**
     * Resolves partners, co-spouses, and child parent assignments for a family unit subtree.
     *
     * @param {Person} person - Subtree root person node
     * @param {FamilyTree} tree - Active family tree model
     * @param {Object} layoutConfig - Layout options
     * @param {boolean} isCollapsed - Whether the unit subtree is collapsed
     * @param {Set<string>} localVisited - Visited node IDs set
     * @returns {{
     *   partners: Array<Person>,
     *   coSpouseEntries: Array<Object>,
     *   partnerChildMap: Object.<string, Array<Person>>,
     *   isMultiSpouseSplit: boolean
     * }}
     *
     * @example
     * const unit = FamilyTree._resolveSubtreeUnitChildren(p, tree, config, false, new Set(['p1']));
     * // => { partners: [...], coSpouseEntries: [], partnerChildMap: {...}, isMultiSpouseSplit: false }
     *
     * @example
     * const unit = FamilyTree._resolveSubtreeUnitChildren(dad, tree, config, true, visited);
     * // => { partners: [mom], coSpouseEntries: [], partnerChildMap: {...}, isMultiSpouseSplit: false }
     */
    static _resolveSubtreeUnitChildren(person, tree, layoutConfig, isCollapsed, localVisited) {
        const partners = person.partners.map(id => tree.get(id)).filter(Boolean);
        partners.forEach(p => localVisited.add(p.id));
        const coSpouseEntries = FamilyTree._findCoSpouseEntries(person, partners, tree, layoutConfig, localVisited);
        const children = FamilyTree._collectUnitChildren(person, partners, coSpouseEntries, tree, layoutConfig, isCollapsed);
        const { partnerChildMap, isMultiSpouseSplit } = FamilyTree._assignChildrenToParents(
            { person, partners, coSpouseEntries }, children, { isCollapsed, layoutConfig, tree }
        );
        return { partners, coSpouseEntries, partnerChildMap, isMultiSpouseSplit };
    }

    /**
     * Computes horizontal spacing offsets for a sequence of child subtrees using contour distance
     * and minimum parent card separation gaps.
     *
     * @param {Array<Object>} rawChildSubtrees - Array of child subtree layout objects
     * @param {number} gap - Horizontal gap between adjacent subtrees
     * @returns {{ childOffsets: Array<number>, gContour: IntervalContour }}
     *
     * @example
     * FamilyTree._packChildSubtrees([sub1, sub2], 24)
     * // => { childOffsets: [0, 150], gContour: ... }
     *
     * @example
     * FamilyTree._packChildSubtrees([singleSubtree], 24)
     * // => { childOffsets: [0], gContour: ... }
     */
    static _packChildSubtrees(rawChildSubtrees, gap) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const childOffsets = [0];
        const gContour = rawChildSubtrees[0].contour.clone();

        for (let cIdx = 1; cIdx < rawChildSubtrees.length; cIdx++) {
            const prevSub = rawChildSubtrees[cIdx - 1];
            const curSub = rawChildSubtrees[cIdx];

            const distContour = gContour.computeDistance(curSub.contour, gap);
            const prevParentRight = Math.max(...prevSub.memberLayouts.map(minf => minf.cardX + nodeWidth));
            const curParentLeft = Math.min(...curSub.memberLayouts.map(minf => minf.cardX));
            const minParentDist = childOffsets[cIdx - 1] + (prevParentRight - curParentLeft + gap);

            const actualDist = Math.max(distContour, minParentDist);
            childOffsets.push(actualDist);

            const shiftedCur = curSub.contour.clone();
            shiftedCur.shift(actualDist);
            gContour.merge(shiftedCur);
        }

        return { childOffsets, gContour };
    }

    /**
     * Computes horizontal offsets for each spouse subtree by merging interval contours
     * and enforcing minimum partner card spacing.
     * 
     * @param {Array<Object>} spouseSubtrees - Array of spouse subtrees
     * @param {number} branchGap - Minimum spacing between subtree contours
     * @param {number} partnerTotal - Spacing between partner cards
     * @returns {number[]} Calculated horizontal offsets for each group
     *
     * @example
     * FamilyTree._calculateSpouseGroupOffsets([sub1, sub2], 24, 100)
     * // => [0, 200]
     *
     * @example
     * FamilyTree._calculateSpouseGroupOffsets([sub1], 24, 100)
     * // => [0]
     */
    static _calculateSpouseGroupOffsets(spouseSubtrees, branchGap, partnerTotal) {
        const groupOffsets = [0];
        const combinedGContour = spouseSubtrees[0].gContour.clone();

        for (let gIdx = 1; gIdx < spouseSubtrees.length; gIdx++) {
            const curG = spouseSubtrees[gIdx];
            const distContour = combinedGContour.computeDistance(curG.gContour, branchGap);
            const maxCombinedX = combinedGContour.layers.size > 0 
                ? Math.max(...Array.from(combinedGContour.layers.values()).map(s => s.maxX)) 
                : 0;
            const minCurX = curG.gContour.layers.size > 0 
                ? Math.min(...Array.from(curG.gContour.layers.values()).map(s => s.minX)) 
                : 0;
            const distMin = (maxCombinedX - minCurX + branchGap) - groupOffsets[gIdx - 1];
            const dist = Math.max(partnerTotal * 2, distContour, distMin);
            groupOffsets.push(groupOffsets[gIdx - 1] + dist);

            const shiftedCurG = curG.gContour.clone();
            shiftedCurG.shift(groupOffsets[gIdx]);
            combinedGContour.merge(shiftedCurG);
        }

        return groupOffsets;
    }

    /**
     * Positions cards, child layouts, and bus bar connectors for each spouse subtree.
     * 
     * @param {Array<Object>} spouseSubtrees - Array of spouse subtrees
     * @param {number[]} groupOffsets - Calculated horizontal offsets
     * @param {number} nodeWidth - Width of a person card
     * @param {number} nodeHeight - Height of a person card
     *
     * @example
     * FamilyTree._applySpouseGroupPositions([sub1, sub2], [0, 200], 90, 76)
     *
     * @example
     * FamilyTree._applySpouseGroupPositions([singleSub], [0], 90, 76)
     */
    static _applySpouseGroupPositions(spouseSubtrees, groupOffsets, nodeWidth, nodeHeight) {
        const midG = (groupOffsets[0] + groupOffsets[groupOffsets.length - 1]) / 2;
        spouseSubtrees.forEach((gSub, gIdx) => {
            const shift = groupOffsets[gIdx] - midG;
            gSub.spouseGroupOffset = shift;
            gSub.cardX = shift - nodeWidth / 2;
            const pDropX = gSub.cardX + nodeWidth / 2;

            if (gSub.childLayouts && gSub.childLayouts.length > 0) {
                gSub.childLayouts.forEach((c, cIdx) => {
                    const relX = (gSub.rawChildOffsets[cIdx] - gSub.childMidX) + pDropX;
                    c.relX = relX;
                });

                gSub.groupMinDropX = gSub.childLayouts[0].relX;
                gSub.groupMaxDropX = gSub.childLayouts[gSub.childLayouts.length - 1].relX;
                const minChildTopY = Math.min(...gSub.childLayouts.map(c => c.topY));
                const busY = Math.max(gSub.targetY + nodeHeight + 16, minChildTopY - 16);
                gSub.groupBusBarY = busY;
            } else {
                gSub.groupMinDropX = null;
                gSub.groupMaxDropX = null;
                gSub.groupBusBarY = null;
            }
        });
    }

    /**
     * Calculates contour offsets and bus bar coordinates for spouse subtrees with children.
     *
     * @param {Array<Object>} spouseSubtrees - Array of spouse subtrees with children
     * @param {number} branchGap - Spacing gap between branches
     * @param {number} nodeWidth - Width of a person card
     * @param {number} nodeHeight - Height of a person card
     * @param {number} partnerTotal - Spacing between partners
     *
     * @example
     * FamilyTree._distributeSpouseSubtrees(spouseSubtrees, 24, 90, 76, 100)
     *
     * @example
     * FamilyTree._distributeSpouseSubtrees([], 24, 90, 76, 100)
     * // returns early without modifying subtrees
     */
    static _distributeSpouseSubtrees(spouseSubtrees, branchGap, nodeWidth, nodeHeight, partnerTotal) {
        if (!spouseSubtrees || spouseSubtrees.length === 0) return;

        const groupOffsets = FamilyTree._calculateSpouseGroupOffsets(spouseSubtrees, branchGap, partnerTotal);
        FamilyTree._applySpouseGroupPositions(spouseSubtrees, groupOffsets, nodeWidth, nodeHeight);
    }

    /**
     * Calculates the horizontal card position for an unpositioned partner card relative to adjacent positioned cards.
     *
     * @param {?number} prev - Previous partner card X position, or null/undefined if absent
     * @param {?number} next - Next partner card X position, or null/undefined if absent
     * @param {number} partnerTotal - Distance between partner cards
     * @param {number} nodeWidth - Width of a person card
     * @returns {number} The calculated horizontal card X coordinate
     *
     * @example
     * FamilyTree._calculateAdjacentCardX(100, 300, 100, 90);
     * // => 200
     *
     * @example
     * FamilyTree._calculateAdjacentCardX(100, null, 100, 90);
     * // => 200
     */
    static _calculateAdjacentCardX(prev, next, partnerTotal, nodeWidth) {
        if (prev != null && next != null) return (prev + next) / 2;
        if (prev != null) return prev + partnerTotal;
        if (next != null) return next - partnerTotal;
        return -nodeWidth / 2;
    }

    /**
     * Assigns card horizontal positions to partners without children (e.g. centered between adjacent partners).
     *
     * @param {Array<Object>} memberLayouts - Layout items for members
     * @param {number} partnerTotal - Distance between partner cards
     * @param {number} nodeWidth - Width of a person card
     *
     * @example
     * FamilyTree._positionChildlessPartners(memberLayouts, 100, 90)
     *
     * @example
     * FamilyTree._positionChildlessPartners([], 100, 90)
     */
    static _positionChildlessPartners(memberLayouts, partnerTotal, nodeWidth) {
        for (let i = 0; i < memberLayouts.length; i++) {
            if (memberLayouts[i].cardX === undefined || memberLayouts[i].cardX === null) {
                const prev = i > 0 ? memberLayouts[i - 1].cardX : null;
                const next = i < memberLayouts.length - 1 ? memberLayouts[i + 1].cardX : null;
                memberLayouts[i].cardX = FamilyTree._calculateAdjacentCardX(prev, next, partnerTotal, nodeWidth);
            }
        }
    }


    /**
     * Shifts a member's card and child layout horizontal offsets by a delta amount.
     *
     * @param {Object} mInfo - Member layout descriptor
     * @param {number} dx - Horizontal distance to shift
     *
     * @example
     * FamilyTree._shiftMemberLayout(memberInfo, 25);
     *
     * @example
     * FamilyTree._shiftMemberLayout({ cardX: 10, childLayouts: [] }, -15);
     */
    static _shiftMemberLayout(mInfo, dx) {
        mInfo.cardX += dx;
        if (mInfo.childLayouts && mInfo.childLayouts.length > 0) {
            mInfo.childLayouts.forEach(c => { c.relX += dx; });
            mInfo.groupMinDropX += dx;
            mInfo.groupMaxDropX += dx;
        }
    }

    /**
     * Enforces the minimum horizontal partner gap between adjacent cards, shifting later cards if needed.
     *
     * @param {Array<Object>} memberLayouts - Layout items for members
     * @param {number} partnerTotal - Minimum horizontal gap between partner cards
     *
     * @example
     * FamilyTree._enforceMinPartnerGap(memberLayouts, 100)
     *
     * @example
     * FamilyTree._enforceMinPartnerGap([singleMember], 100)
     */
    static _enforceMinPartnerGap(memberLayouts, partnerTotal) {
        for (let i = 1; i < memberLayouts.length; i++) {
            if (memberLayouts[i].cardX < memberLayouts[i - 1].cardX + partnerTotal) {
                const shift = memberLayouts[i - 1].cardX + partnerTotal - memberLayouts[i].cardX;
                for (let j = i; j < memberLayouts.length; j++) {
                    FamilyTree._shiftMemberLayout(memberLayouts[j], shift);
                }
            }
        }
    }

    /**
     * Re-centers the entire subtree layout so that the bloodline member's card center aligns at x=0.
     *
     * @param {Array<Object>} memberLayouts - Layout items for members
     * @param {number} nodeWidth - Width of a person card
     *
     * @example
     * FamilyTree._centerBloodlineMember(memberLayouts, 90)
     *
     * @example
     * FamilyTree._centerBloodlineMember([], 90)
     */
    static _centerBloodlineMember(memberLayouts, nodeWidth) {
        const bloodlineMember = memberLayouts.find(m => m.isBloodline);
        if (bloodlineMember) {
            const bloodlineCenterX = bloodlineMember.cardX + nodeWidth / 2;
            if (bloodlineCenterX !== 0) {
                for (const mInfo of memberLayouts) {
                    FamilyTree._shiftMemberLayout(mInfo, -bloodlineCenterX);
                }
            }
        }
    }

    /**
     * Spaces out multiple spouse subtrees using contour distance, positions childless members,
     * enforces minimum partner gaps, and re-centers the bloodline member at x=0.
     *
     * @param {Array<Object>} memberLayouts - Array of member layout descriptors
     * @param {Array<Object>} spouseSubtrees - Array of spouse subtrees with children
     * @param {number} branchGap - Horizontal spacing gap between branches
     *
     * @example
     * FamilyTree._alignMultiSpouseMembers(memberLayouts, spouseSubtrees, 24)
     *
     * @example
     * FamilyTree._alignMultiSpouseMembers([soloMember], [], 24)
     */
    static _alignMultiSpouseMembers(memberLayouts, spouseSubtrees, branchGap) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeHeight = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;
        const partnerTotal = typeof TREE_PARTNER_TOTAL !== 'undefined' ? TREE_PARTNER_TOTAL : 100;

        FamilyTree._distributeSpouseSubtrees(spouseSubtrees, branchGap, nodeWidth, nodeHeight, partnerTotal);
        FamilyTree._positionChildlessPartners(memberLayouts, partnerTotal, nodeWidth);
        FamilyTree._enforceMinPartnerGap(memberLayouts, partnerTotal);
        FamilyTree._centerBloodlineMember(memberLayouts, nodeWidth);
    }

    /**
     * Checks whether a partner's child is eligible to be included in the central person's family unit.
     * Rejects children that already belong to a co-spouse branch or have another known biological
     * parent of the person's gender present in the tree.
     *
     * @example
     * // Johny (male) and Rosy are partners. Rosy has child Joy whose father is known to be Ousephunni.
     * FamilyTree._isEligibleUnitPartnerChild(joy, johny, [], tree)
     * // => false (rejected because Joy's father is Ousephunni, not Johny)
     *
     * @example
     * // Lovely (female) and Varghese are partners. Lovely has child Elsa with Varghese.
     * FamilyTree._isEligibleUnitPartnerChild(elsa, varghese, [], tree)
     * // => true
     *
     * @param {Person} child - Child node under consideration
     * @param {Person} person - Central person of the family unit
     * @param {Array<Object>} coSpouseEntries - Co-spouse relationships
     * @param {FamilyTree} tree - Family tree instance
     * @returns {boolean} True if child should be included with this unit
     */
    static _isEligibleUnitPartnerChild(child, person, coSpouseEntries, tree) {
        const isCoSpouseChild = coSpouseEntries.some(e =>
            e.coSpouse?.id === child.momId || e.coSpouse?.id === child.fatherId
        );
        if (isCoSpouseChild) return false;

        const isPersonMale = person.gender === 'M' || (!person.gender && person.spouseType === 'husband');
        if (isPersonMale && child.fatherId && child.fatherId !== person.id && tree.get(child.fatherId)) {
            return false;
        }

        const isPersonFemale = person.gender === 'F' || (!person.gender && person.spouseType === 'wife');
        if (isPersonFemale && child.momId && child.momId !== person.id && tree.get(child.momId)) {
            return false;
        }

        return true;
    }

    /**
     * Gathers all valid children belonging to the family unit (person, partners, and co-spouses).
     *
     * @param {Person} person - The central person
     * @param {Array<Person>} partners - Partner profiles
     * @param {Array<Object>} coSpouseEntries - Co-spouse associations
     * @param {FamilyTree} tree - Family tree instance
     * @param {Object} layoutConfig - Layout configuration
     * @param {boolean} isCollapsed - Whether the current node is collapsed
     * @returns {Array<Person>} Deduplicated array of valid children for this unit
     *
     * @example
     * FamilyTree._collectUnitChildren(dad, [mom1, mom2], [], tree, config, false)
     * // => [childA, childB, childC]
     *
     * @example
     * FamilyTree._collectUnitChildren(soloChildless, [], [], tree, config, false)
     * // => []
     */
    static _collectUnitChildren(person, partners, coSpouseEntries, tree, layoutConfig, isCollapsed) {
        const children = [...person.getValidDisplayChildren(tree)];
        const seenIds = new Set(children.map(c => c.id));

        for (const partner of partners) {
            for (const c of partner.getValidDisplayChildren(tree)) {
                if (!seenIds.has(c.id) && FamilyTree._isEligibleUnitPartnerChild(c, person, coSpouseEntries, tree)) {
                    seenIds.add(c.id);
                    children.push(c);
                }
            }
        }
        return children;
    }

    /**
     * Determines whether a family member has hidden parents or partners outside the currently visible tree nodes.
     *
     * @param {Person} person - Person profile
     * @param {Object} layoutConfig - Layout configuration with visibleNodes Set
     * @param {FamilyTree} tree - Tree instance for node lookups
     * @returns {boolean} True if person has hidden lineage
     *
     * @example
     * FamilyTree._hasHiddenLineage(personWithHiddenParents, { visibleNodes: new Set(['p1']) }, tree)
     * // => true
     *
     * @example
     * FamilyTree._hasHiddenLineage(null, config, tree)
     * // => false
     */
    static _hasHiddenLineage(person, layoutConfig, tree) {
        if (!person) return false;
        const momVisible = person.momId && layoutConfig.visibleNodes.has(person.momId);
        const dadVisible = person.fatherId && layoutConfig.visibleNodes.has(person.fatherId);
        const hasMom = person.momId && tree.get(person.momId) && !tree.get(person.momId)._isUnknown;
        const hasDad = person.fatherId && tree.get(person.fatherId) && !tree.get(person.fatherId)._isUnknown;
        const hasHiddenParents = (hasMom || hasDad) && !momVisible && !dadVisible;
        const hasHiddenPartner = person.partners.some(pId => !layoutConfig.visibleNodes.has(pId) && tree.get(pId) && !tree.get(pId)._isUnknown);
        return Boolean(hasHiddenParents || hasHiddenPartner);
    }

    /**
     * Constructs initial member layout descriptors with demographic and generational coordinates.
     *
     * @param {Array<Person>} familyMembers - Ordered array of family members
     * @param {number} bloodlineIndex - Index of the bloodline member
     * @param {Object} partnerChildMap - Map of member ID to assigned children
     * @param {number} nodeYob - Effective birth year of the central node
     * @param {number} targetY - Base vertical pixel coordinate
     * @param {boolean} isCollapsed - Whether node is collapsed
     * @param {Object} layoutConfig - Layout configuration options
     * @param {FamilyTree} tree - Family tree instance
     * @returns {Array<Object>} Array of member layout descriptors
     *
     * @example
     * FamilyTree._buildMemberLayouts([dad, mom], 0, { [dad.id]: [child1] }, 1950, 200, false, config, tree)
     * // => [{ person: dad, isBloodline: true, targetY: 200, ... }, { person: mom, isBloodline: false, ... }]
     *
     * @example
     * FamilyTree._buildMemberLayouts([solo], 0, {}, 1980, 0, false, config, tree)
     * // => [{ person: solo, isBloodline: true, targetY: 0, ... }]
     */
    /**
     * Determines whether a family member's children subtree should be rendered collapsed.
     *
     * @private
     * @param {Object} params
     * @param {Object} params.member - Person node
     * @param {Array<Object>} params.children - Children of this member
     * @param {boolean} params.isCollapsed - Root/branch collapsed status
     * @param {string|undefined} params.bloodlineId - ID of primary bloodline person
     * @param {Set<string>|null} params.collapsedNodes - Set of explicitly collapsed node IDs
     * @returns {boolean} True if member subtree is collapsed
     *
     * @example
     * FamilyTree._isMemberSubtreeCollapsed({ member: { id: 'p1' }, children: [], isCollapsed: true, bloodlineId: 'p1', collapsedNodes: new Set() });
     * // => true
     *
     * @example
     * FamilyTree._isMemberSubtreeCollapsed({ member: { id: 'p2' }, children: [], isCollapsed: false, bloodlineId: 'p1', collapsedNodes: new Set() });
     * // => false
     */
    static _isMemberSubtreeCollapsed({ member, children, isCollapsed, bloodlineId, collapsedNodes }) {
        const hasCollapsed = (id) => Boolean(id && collapsedNodes?.has(id));
        if (hasCollapsed(member.id)) return true;
        if (isCollapsed && member.id === bloodlineId) return true;
        return children.length > 0 && children.every(c =>
            (c.momId && hasCollapsed(c.momId)) ||
            (c.fatherId && hasCollapsed(c.fatherId))
        );
    }

    /**
     * Constructs initial member layout objects for all members of a family group.
     * Computes bloodline status, child associations, collapsed state, offsets, and target coordinates.
     *
     * @param {Array<Object>} familyMembers - Ordered family unit member objects
     * @param {number} bloodlineIndex - Index of the primary bloodline individual
     * @param {Object.<string, Array<Object>>} partnerChildMap - Map of partner IDs to children
     * @param {Object} layoutCtx - Subtree geometry and layout context ({ nodeYob, targetY, isCollapsed, layoutConfig, tree })
     * @returns {Array<Object>} Array of initialized member layout records
     *
     * @example
     * const members = [{ id: 'p1', bestYob: 1950 }];
     * const layouts = FamilyTree._buildMemberLayouts(members, 0, {}, { nodeYob: 1950, targetY: 100, isCollapsed: false, layoutConfig: { ppy: 10 }, tree: null });
     * // => layouts[0].isBloodline === true && layouts[0].targetY === 100
     *
     * @example
     * const members = [{ id: 'p1', bestYob: 1950 }, { id: 'p2', bestYob: 1955 }];
     * const layouts = FamilyTree._buildMemberLayouts(members, 0, { p1: [] }, { nodeYob: 1950, targetY: 200, isCollapsed: false, layoutConfig: { ppy: 10, verticalCompression: true }, tree: null });
     * // => layouts[1].isBloodline === false && layouts[1].offsetY === 0
     */
    static _buildMemberLayouts(familyMembers, bloodlineIndex, partnerChildMap, layoutCtx) {
        const { nodeYob, targetY, isCollapsed, layoutConfig, tree } = layoutCtx;
        const bloodlineId = familyMembers[bloodlineIndex]?.id;
        return familyMembers.map((m, idx) => {
            const isBloodline = idx === bloodlineIndex;
            const mChildren = partnerChildMap[m.id] || [];
            const mIsCollapsed = FamilyTree._isMemberSubtreeCollapsed({
                member: m, children: mChildren, isCollapsed, bloodlineId, collapsedNodes: layoutConfig?.collapsedNodes
            });
            const mYob = m.bestYob || nodeYob;
            const mOffsetY = layoutConfig.verticalCompression ? 0 : (mYob - nodeYob) * layoutConfig.ppy;
            const mTargetY = targetY + mOffsetY;
            const hasHiddenLineage = FamilyTree._hasHiddenLineage(m, layoutConfig, tree);

            return {
                person: m, isBloodline, hasHiddenLineage, mChildren, mIsCollapsed,
                targetY: mTargetY, offsetY: mOffsetY, cardX: null, childLayouts: [],
                groupBusBarY: null, groupMinDropX: null, groupMaxDropX: null
            };
        });
    }

    /**
     * Appends bounding boxes to a subtree contour for parent drop stem, horizontal bus-bar,
     * and individual child vertical drop stems.
     *
     * @param {IntervalContour} contour - Target contour to augment
     * @param {Object} options
     * @param {number} options.parentDropX - Center X coordinate of parent drop stem
     * @param {number} options.parentBottomY - Bottom Y coordinate of parent card
     * @param {number} options.busY - Vertical coordinate of connecting bus-bar
     * @param {number} options.minDropX - Leftmost child stem X coordinate
     * @param {number} options.maxDropX - Rightmost child stem X coordinate
     * @param {Array<Object>} options.childLayouts - Array of child layout descriptors ({ relX, targetY })
     * @param {boolean} [options.includeParentStem=true] - Whether to include parent-to-bus-bar stem
     *
     * @example
     * FamilyTree._addConnectionContourBoxes(contour, {
     *   parentDropX: 45, parentBottomY: 76, busY: 100,
     *   minDropX: 20, maxDropX: 70,
     *   childLayouts: [{ relX: 20, targetY: 150 }, { relX: 70, targetY: 150 }],
     *   includeParentStem: true
     * });
     *
     * @example
     * FamilyTree._addConnectionContourBoxes(contour, {
     *   parentDropX: 45, parentBottomY: 76, busY: 100,
     *   minDropX: 45, maxDropX: 45,
     *   childLayouts: [{ relX: 45, targetY: 150 }],
     *   includeParentStem: false
     * });
     */
    static _addConnectionContourBoxes(contour, {
        parentDropX, parentBottomY, busY, minDropX, maxDropX, childLayouts, includeParentStem = true
    }) {
        if (includeParentStem) {
            contour.addBox(parentDropX - 8, parentDropX + 8, parentBottomY, busY);
        }
        contour.addBox(minDropX - 6, maxDropX + 6, busY - 6, busY + 6);
        for (const c of childLayouts) {
            contour.addBox(c.relX - 8, c.relX + 8, busY, c.targetY);
        }
    }

    /**
     * Resolves vertical altitude, gap spacing, and node status metrics for a subtree root.
     *
     * @param {Object} person - The root person of the subtree.
     * @param {Object} tree - The FamilyTree instance.
     * @param {Object} layoutConfig - Active layout configuration.
     * @param {number} depth - Generation depth of the subtree.
     * @returns {{ siblingGap: number, branchGap: number, isCollapsed: boolean, nodeYob: number, targetY: number }}
     *
     * @example
     *   FamilyTree._computeSubtreeGeometry(person, tree, { collapsedNodes: new Set(), rootNodeYob: 1950, ppy: 3 }, 0);
     *   // => { siblingGap: 24, branchGap: 36, isCollapsed: false, nodeYob: 1950, targetY: 0 }
     *
     * @example
     *   FamilyTree._computeSubtreeGeometry(child, tree, { collapsedNodes: new Set(['c1']), verticalCompression: true, generationRowHeight: 160 }, 1);
     *   // => { siblingGap: 24, branchGap: 24, isCollapsed: true, targetY: 160 }
     */
    static _computeSubtreeGeometry(person, tree, layoutConfig, depth) {
        const siblingGap = layoutConfig.siblingGap || TREE_SIBLING_GAP;
        const isRootOrSynthetic = person.id === tree.rootId || FamilyTree.isSyntheticSiblingParent(person);
        const branchGap = isRootOrSynthetic ? Math.max(siblingGap, Math.round(siblingGap * 1.5)) : siblingGap;
        const isCollapsed = layoutConfig.collapsedNodes.has(person.id);
        const nodeYob = person.bestYob || layoutConfig.rootNodeYob;
        const genHeight = layoutConfig.generationRowHeight || 160;
        const targetY = layoutConfig.verticalCompression
            ? (depth * genHeight)
            : ((nodeYob - layoutConfig.rootNodeYob) * layoutConfig.ppy);
        return { siblingGap, branchGap, isCollapsed, nodeYob, targetY };
    }

    /**
     * Positions child subtrees relative to parent drop coordinate and merges their contours.
     *
     * @param {Array<Object>} rawChildSubtrees - Child layout descriptors.
     * @param {Array<number>} childOffsets - Relative packed offsets for each child.
     * @param {number} midX - Center horizontal midpoint of children span.
     * @param {number} pDropX - Parent vertical stem drop horizontal coordinate.
     * @param {Object} mInfo - Member layout descriptor receiving child layouts.
     * @param {IntervalContour} subtreeContour - Aggregated interval contour accumulator.
     *
     * @example
     *   FamilyTree._placeChildSubtrees(subtrees, [0, 100], 50, 45, mInfo, contour);
     *
     * @example
     *   FamilyTree._placeChildSubtrees([singleSub], [0], 0, 45, mInfo, contour);
     */
    static _placeChildSubtrees(rawChildSubtrees, childOffsets, midX, pDropX, mInfo, subtreeContour) {
        for (let cIdx = 0; cIdx < rawChildSubtrees.length; cIdx++) {
            const cSub = rawChildSubtrees[cIdx];
            const relX = (childOffsets[cIdx] - midX) + pDropX;
            cSub.relX = relX;
            mInfo.childLayouts.push(cSub);

            const cShiftedContour = cSub.contour.clone();
            cShiftedContour.shift(relX);
            subtreeContour.merge(cShiftedContour);
        }
    }

    /**
     * Computes the bus bar horizontal span and vertical altitude connecting a member to their children.
     *
     * @param {Object} mInfo - Member layout descriptor.
     * @param {Array<Object>} rawChildSubtrees - Positioned child subtrees.
     * @param {boolean} isSyntheticSiblingUnit - Whether parent unit is a synthetic placeholder.
     * @param {number} nodeHeight - Height of parent card.
     * @returns {number} The vertical Y altitude for the bus bar line.
     *
     * @example
     *   FamilyTree._computeBusBarGeometry(mInfo, subtrees, false, 76);
     *   // => 168
     *
     * @example
     *   FamilyTree._computeBusBarGeometry(syntheticInfo, subtrees, true, 76);
     *   // => minChildTopY - 20
     */
    static _computeBusBarGeometry(mInfo, rawChildSubtrees, isSyntheticSiblingUnit, nodeHeight) {
        mInfo.groupMinDropX = rawChildSubtrees[0].relX;
        mInfo.groupMaxDropX = rawChildSubtrees[rawChildSubtrees.length - 1].relX;
        const minChildTopY = Math.min(...mInfo.childLayouts.map(c => c.topY));
        const busY = isSyntheticSiblingUnit ? (minChildTopY - 20) : Math.max(mInfo.targetY + nodeHeight + 16, minChildTopY - 16);
        mInfo.groupBusBarY = busY;
        return busY;
    }

    /**
     * Traverses and lays out child subtrees for a specific family member, merging their contours.
     *
     * @param {Object} params
     * @param {Object} params.mInfo - Member layout descriptor
     * @param {number} params.nodeWidth - Visual card width
     * @param {number} params.nodeHeight - Visual card height
     * @param {boolean} params.isSyntheticSiblingUnit - Whether parent unit is a synthetic sibling placeholder
     * @param {FamilyTree} params.tree - FamilyTree domain model
     * @param {Object} params.layoutConfig - Layout styling parameters
     * @param {Set} params.localVisited - Local visited set for cycle avoidance
     * @param {number} params.branchGap - Sibling branch spacing
     * @param {number} params.depth - Traversal depth
     * @param {IntervalContour} params.subtreeContour - Subtree interval contour accumulator
     *
     * @example
     *   FamilyTree._layoutMemberChildren({ mInfo, nodeWidth: 90, nodeHeight: 76, ... });
     *   // => mInfo.childLayouts populated and subtreeContour expanded
     *
     * @example
     *   FamilyTree._layoutMemberChildren({ mInfo: childlessInfo, nodeWidth: 90, nodeHeight: 76, ... });
     *   // returns early without laying out children
     */
    static _layoutMemberChildren({
        mInfo, nodeWidth, nodeHeight, isSyntheticSiblingUnit,
        tree, layoutConfig, localVisited, branchGap, depth, subtreeContour
    }) {
        if (!mInfo.mChildren || mInfo.mChildren.length === 0 || mInfo.mIsCollapsed) {
            return;
        }
        const rawChildSubtrees = mInfo.mChildren.map(c => layoutSubtree(c, tree, layoutConfig, localVisited, depth + 1)).filter(Boolean);
        if (rawChildSubtrees.length === 0) return;

        const { childOffsets } = FamilyTree._packChildSubtrees(rawChildSubtrees, branchGap);
        const midX = (childOffsets[0] + childOffsets[childOffsets.length - 1]) / 2;
        const pDropX = mInfo.cardX + nodeWidth / 2;

        FamilyTree._placeChildSubtrees(rawChildSubtrees, childOffsets, midX, pDropX, mInfo, subtreeContour);
        const busY = FamilyTree._computeBusBarGeometry(mInfo, rawChildSubtrees, isSyntheticSiblingUnit, nodeHeight);

        FamilyTree._addConnectionContourBoxes(subtreeContour, {
            parentDropX: pDropX,
            parentBottomY: mInfo.targetY + nodeHeight,
            busY,
            minDropX: mInfo.groupMinDropX,
            maxDropX: mInfo.groupMaxDropX,
            childLayouts: mInfo.childLayouts,
            includeParentStem: !isSyntheticSiblingUnit
        });
    }

    /**
     * Assigns horizontal card coordinates to member layouts in a single-spouse family unit.
     *
     * @param {Array<Object>} memberLayouts - Member layout descriptors.
     * @param {number} bloodlineIndex - Index of the bloodline individual.
     * @param {number} nodeWidth - Width of a single card.
     * @param {number} partnerTotal - Width plus gap between adjacent partners.
     *
     * @example
     *   FamilyTree._positionSingleSpouseCards(memberLayouts, 0, 90, 100);
     *   // => sets cardX on each memberLayout entry
     *
     * @example
     *   FamilyTree._positionSingleSpouseCards([singleMember], 0, 90, 100);
     *   // => singleMember.cardX = -45
     */
    static _positionSingleSpouseCards(memberLayouts, bloodlineIndex, nodeWidth, partnerTotal) {
        memberLayouts.forEach((mInfo, idx) => {
            mInfo.cardX = -nodeWidth / 2 + (idx - bloodlineIndex) * partnerTotal;
        });
    }

    /**
     * Initializes the interval contour with bounding boxes for all non-synthetic member cards.
     *
     * @param {Array<Object>} memberLayouts - Member layout descriptors.
     * @param {boolean} isSyntheticSiblingUnit - Whether unit is synthetic sibling placeholder.
     * @param {number} nodeWidth - Card width.
     * @param {number} nodeHeight - Card height.
     * @returns {IntervalContour} Initialized contour.
     *
     * @example
     *   const contour = FamilyTree._initSingleSpouseContour(memberLayouts, false, 90, 76);
     *   // => IntervalContour { layers: Map(...) }
     *
     * @example
     *   const emptyContour = FamilyTree._initSingleSpouseContour(memberLayouts, true, 90, 76);
     *   // => empty IntervalContour for synthetic unit
     */
    static _initSingleSpouseContour(memberLayouts, isSyntheticSiblingUnit, nodeWidth, nodeHeight) {
        const subtreeContour = new IntervalContour();
        if (!isSyntheticSiblingUnit) {
            for (const mInfo of memberLayouts) {
                subtreeContour.addBox(mInfo.cardX, mInfo.cardX + nodeWidth, mInfo.targetY, mInfo.targetY + nodeHeight);
            }
        }
        return subtreeContour;
    }

    /**
     * Performs subtree layout and contour calculation for single-spouse family units.
     *
     * @param {Object} params - Layout parameters
     * @returns {Object} Subtree layout descriptor
     *
     * @example
     * FamilyTree._layoutSingleSpouseSubtree({ person, targetY, memberLayouts, ... })
     * // => { person, targetY, topY, contour, memberLayouts, isMultiSpouseSplit: false }
     *
     * @example
     * FamilyTree._layoutSingleSpouseSubtree({ person, targetY: 100, memberLayouts: [solo], isSyntheticSiblingUnit: true, ... })
     * // => { person, targetY: 100, isSyntheticSiblingUnit: true, ... }
     */
    static _layoutSingleSpouseSubtree({
        person, targetY, memberLayouts, bloodlineIndex, isSyntheticSiblingUnit,
        tree, layoutConfig, localVisited, branchGap, depth = 0
    }) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeHeight = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;
        const partnerTotal = typeof TREE_PARTNER_TOTAL !== 'undefined' ? TREE_PARTNER_TOTAL : 100;

        FamilyTree._positionSingleSpouseCards(memberLayouts, bloodlineIndex, nodeWidth, partnerTotal);
        const subtreeContour = FamilyTree._initSingleSpouseContour(memberLayouts, isSyntheticSiblingUnit, nodeWidth, nodeHeight);

        for (const mInfo of memberLayouts) {
            FamilyTree._layoutMemberChildren({
                mInfo, nodeWidth, nodeHeight, isSyntheticSiblingUnit,
                tree, layoutConfig, localVisited, branchGap, depth, subtreeContour
            });
        }

        const allMinY = Math.min(...memberLayouts.map(m => m.targetY));

        return {
            person,
            targetY,
            topY: isSyntheticSiblingUnit ? (memberLayouts[0]?.groupBusBarY || targetY) : allMinY,
            contour: subtreeContour,
            memberLayouts,
            isMultiSpouseSplit: false,
            isSyntheticSiblingUnit
        };
    }

    /**
     * Initializes an empty childless layout descriptor for a spouse group.
     *
     * @private
     * @param {Object} mInfo - Member layout descriptor
     * @param {number} nodeWidth - Card width
     * @param {number} nodeHeight - Card height
     *
     * @example
     * FamilyTree._initChildlessSpouseGroup(mInfo, 90, 76);
     *
     * @example
     * FamilyTree._initChildlessSpouseGroup(partnerInfo, 100, 80);
     */
    static _initChildlessSpouseGroup(mInfo, nodeWidth, nodeHeight) {
        mInfo.childLayouts = [];
        mInfo.rawChildOffsets = [0];
        mInfo.childMidX = 0;
        mInfo.groupMinDropX = null;
        mInfo.groupMaxDropX = null;
        mInfo.groupBusBarY = null;
        mInfo.gContour = new IntervalContour();
        mInfo.gContour.addBox(-nodeWidth / 2, nodeWidth / 2, mInfo.targetY, mInfo.targetY + nodeHeight);
    }

    /**
     * Packs child subtrees and connects contour boxes for a spouse group with children.
     *
     * @private
     * @param {Object} mInfo - Member layout descriptor
     * @param {Array<Object>} rawChildSubtrees - Positioned child subtrees
     * @param {number} siblingGap - Horizontal spacing between sibling branches
     * @param {number} nodeWidth - Card width
     * @param {number} nodeHeight - Card height
     *
     * @example
     * FamilyTree._packPopulatedSpouseGroup(mInfo, [childSub1, childSub2], 24, 90, 76);
     *
     * @example
     * FamilyTree._packPopulatedSpouseGroup(mInfo, [singleChildSub], 24, 90, 76);
     */
    static _packPopulatedSpouseGroup(mInfo, rawChildSubtrees, siblingGap, nodeWidth, nodeHeight) {
        const { childOffsets, gContour } = FamilyTree._packChildSubtrees(rawChildSubtrees, siblingGap);
        const midX = (childOffsets[0] + childOffsets[childOffsets.length - 1]) / 2;
        mInfo.childLayouts = rawChildSubtrees;
        mInfo.rawChildOffsets = childOffsets;
        mInfo.childMidX = midX;
        mInfo.gContour = gContour;
        mInfo.gContour.shift(-midX);
        const minChildTopY = Math.min(...rawChildSubtrees.map(c => c.topY));
        const busY = Math.max(mInfo.targetY + nodeHeight + 16, minChildTopY - 16);
        FamilyTree._addConnectionContourBoxes(mInfo.gContour, {
            parentDropX: 0,
            parentBottomY: mInfo.targetY + nodeHeight,
            busY,
            minDropX: childOffsets[0] - midX,
            maxDropX: childOffsets[childOffsets.length - 1] - midX,
            childLayouts: rawChildSubtrees.map((c, idx) => ({ relX: childOffsets[idx] - midX, targetY: c.targetY })),
            includeParentStem: true
        });
        mInfo.gContour.addBox(-nodeWidth / 2, nodeWidth / 2, mInfo.targetY, mInfo.targetY + nodeHeight);
    }

    /**
     * Lays out and packs child subtrees for each multi-spouse partner group.
     *
     * @param {Array<Object>} spouseGroups - Member layouts that have children.
     * @param {Object} context - Layout traversal context.
     * @returns {Array<Object>} Member layouts with populated child subtrees and contours.
     *
     * @example
     *   const subtrees = FamilyTree._packMultiSpouseChildren(groups, { tree, layoutConfig, localVisited, depth: 0, siblingGap: 24 });
     *   // => [mInfo, ...]
     *
     * @example
     *   const emptySubtrees = FamilyTree._packMultiSpouseChildren([], { tree, layoutConfig, localVisited, depth: 0, siblingGap: 24 });
     *   // => []
     */
    static _packMultiSpouseChildren(spouseGroups, { tree, layoutConfig, localVisited, depth, siblingGap }) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeHeight = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;
        const spouseSubtrees = [];
        for (const mInfo of spouseGroups) {
            const rawChildSubtrees = mInfo.mIsCollapsed
                ? []
                : mInfo.mChildren.map(c => layoutSubtree(c, tree, layoutConfig, localVisited, depth + 1)).filter(Boolean);
            if (rawChildSubtrees.length > 0) {
                FamilyTree._packPopulatedSpouseGroup(mInfo, rawChildSubtrees, siblingGap, nodeWidth, nodeHeight);
            } else {
                FamilyTree._initChildlessSpouseGroup(mInfo, nodeWidth, nodeHeight);
            }
            spouseSubtrees.push(mInfo);
        }
        return spouseSubtrees;
    }

    /**
     * Builds the unified bounding interval contour for multi-spouse family units.
     *
     * @param {Array<Object>} memberLayouts - Member layout descriptors.
     * @param {number} nodeWidth - Card width.
     * @param {number} nodeHeight - Card height.
     * @returns {IntervalContour} Aggregated spatial contour.
     *
     * @example
     *   const contour = FamilyTree._buildMultiSpouseContour(memberLayouts, 90, 76);
     *   // => IntervalContour { layers: Map(...) }
     *
     * @example
     *   const singleContour = FamilyTree._buildMultiSpouseContour([mInfo], 90, 76);
     *   // => contour containing bounding box of mInfo
     */
    static _buildMultiSpouseContour(memberLayouts, nodeWidth, nodeHeight) {
        const subtreeContour = new IntervalContour();
        for (const mInfo of memberLayouts) {
            subtreeContour.addBox(mInfo.cardX, mInfo.cardX + nodeWidth, mInfo.targetY, mInfo.targetY + nodeHeight);
            if (mInfo.childLayouts.length > 0) {
                const pDropX = mInfo.cardX + nodeWidth / 2;
                const busY = mInfo.groupBusBarY;
                FamilyTree._addConnectionContourBoxes(subtreeContour, {
                    parentDropX: pDropX,
                    parentBottomY: mInfo.targetY + nodeHeight,
                    busY,
                    minDropX: mInfo.groupMinDropX,
                    maxDropX: mInfo.groupMaxDropX,
                    childLayouts: mInfo.childLayouts,
                    includeParentStem: true
                });
                for (const c of mInfo.childLayouts) {
                    const cShifted = c.contour.clone();
                    cShifted.shift(c.relX);
                    subtreeContour.merge(cShifted);
                }
            }
        }
        return subtreeContour;
    }

    /**
     * Performs subtree layout and contour calculation for multi-spouse family units.
     *
     * @param {Object} params - Layout parameters
     * @returns {Object} Subtree layout descriptor
     *
     * @example
     * FamilyTree._layoutMultiSpouseSubtree({ person, targetY, memberLayouts, ... })
     * // => { person, targetY, topY, contour, memberLayouts, isMultiSpouseSplit: true }
     *
     * @example
     * FamilyTree._layoutMultiSpouseSubtree({ person, targetY: 0, memberLayouts: [p1, p2], ... })
     * // => { isMultiSpouseSplit: true, ... }
     */
    static _layoutMultiSpouseSubtree({
        person, targetY, memberLayouts, tree, layoutConfig, localVisited,
        siblingGap, branchGap, depth = 0
    }) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeHeight = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;

        const spouseGroups = memberLayouts.filter(m => m.mChildren.length > 0);
        const spouseSubtrees = FamilyTree._packMultiSpouseChildren(spouseGroups, {
            tree, layoutConfig, localVisited, depth, siblingGap
        });

        FamilyTree._alignMultiSpouseMembers(memberLayouts, spouseSubtrees, branchGap);

        const subtreeContour = FamilyTree._buildMultiSpouseContour(memberLayouts, nodeWidth, nodeHeight);
        const allMinY = Math.min(...memberLayouts.map(m => m.targetY));

        return {
            person,
            targetY,
            topY: allMinY,
            contour: subtreeContour,
            memberLayouts,
            isMultiSpouseSplit: true
        };
    }

    /**
     * Appends SVG bridge path descriptors between adjacent spouse/partner cards.
     *
     * @param {Array<Object>} memberLayouts - Member layout descriptors
     * @param {number} originX - Current horizontal subtree origin
     * @param {boolean} isSyntheticSiblingUnit - Whether unit is synthetic sibling ghost
     * @param {Array<Object>} paths - Target paths array
     *
     * @example
     * FamilyTree._generateSpouseBridges(memberLayouts, 0, false, paths)
     *
     * @example
     * FamilyTree._generateSpouseBridges(memberLayouts, 0, true, paths)
     * // does nothing for synthetic sibling unit
     */
    static _generateSpouseBridges(memberLayouts, originX, isSyntheticSiblingUnit, paths) {
        if (isSyntheticSiblingUnit) return;
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        for (let i = 0; i < memberLayouts.length - 1; i++) {
            const m1 = memberLayouts[i];
            const m2 = memberLayouts[i + 1];
            const x1 = originX + m1.cardX + nodeWidth;
            const y1 = m1.targetY + 38;
            const x2 = originX + m2.cardX;
            const y2 = m2.targetY + 38;

            paths.push({
                d: _generateSpouseBridgePath(x1, y1, x2, y2),
                type: 'spouse-bridge'
            });
        }
    }

    /**
     * Generates connector path and executes subtree traversal for a single-child family unit.
     *
     * @param {Object} params
     * @param {Object} params.cSub - Child subtree layout descriptor
     * @param {number} params.originX - Subtree X origin coordinate
     * @param {number} params.parentDropX - Center X coordinate of parent card drop stem
     * @param {number} params.busBarY - Vertical coordinate of bus-bar
     * @param {boolean} params.isSyntheticSiblingUnit - Whether unit is synthetic sibling ghost
     * @param {Array<Object>} params.paths - Target SVG path descriptors array
     * @param {Function} params.traverse - Recursive layout traversal callback
     *
     * @example
     * FamilyTree._generateSingleChildConnection({
     *   cSub: { relX: 10, targetY: 120 }, originX: 50, parentDropX: 50,
     *   busBarY: 90, isSyntheticSiblingUnit: false, paths: [], traverse: () => {}
     * });
     * // paths pushed: [{ d: '...', type: 'child-stem' }]
     *
     * @example
     * FamilyTree._generateSingleChildConnection({
     *   cSub: { relX: 10, targetY: 120 }, originX: 50, parentDropX: 50,
     *   busBarY: 90, isSyntheticSiblingUnit: true, paths: [], traverse: () => {}
     * });
     * // no stem pushed for synthetic unit
     */
    static _generateSingleChildConnection({ cSub, originX, parentDropX, busBarY, isSyntheticSiblingUnit, paths, traverse }) {
        const childOriginX = originX + cSub.relX;
        const childDropX = childOriginX;
        const childCardTopY = cSub.targetY;

        if (!isSyntheticSiblingUnit) {
            paths.push({
                d: _generateSingleChildStemPath(parentDropX, busBarY, childDropX, childCardTopY),
                type: 'child-stem'
            });
        }
        traverse(cSub, childOriginX);
    }

    /**
     * Generates horizontal bus-bar, intermediate vertical drop stems, and executes
     * recursive traversal for multiple child subtrees.
     *
     * @param {Object} params
     * @param {Array<Object>} params.children - Array of child subtree layout descriptors
     * @param {number} params.originX - Subtree X origin coordinate
     * @param {number} params.busBarY - Vertical coordinate of bus-bar
     * @param {Array<Object>} params.paths - Target SVG path descriptors array
     * @param {Function} params.traverse - Recursive layout traversal callback
     *
     * @example
     * FamilyTree._generateMultiChildConnections({
     *   children: [{ relX: 0, targetY: 120 }, { relX: 100, targetY: 120 }],
     *   originX: 50, busBarY: 90, paths: [], traverse: () => {}
     * });
     * // paths pushed: [{ d: '...', type: 'bus-bar' }]
     *
     * @example
     * FamilyTree._generateMultiChildConnections({
     *   children: [{ relX: 0, targetY: 120 }, { relX: 50, targetY: 120 }, { relX: 100, targetY: 120 }],
     *   originX: 0, busBarY: 80, paths: [], traverse: () => {}
     * });
     */
    static _generateMultiChildConnections({ children, originX, busBarY, paths, traverse }) {
        const firstChild = children[0];
        const lastChild = children[children.length - 1];
        const firstDropX = originX + firstChild.relX;
        const lastDropX = originX + lastChild.relX;
        const firstTopY = firstChild.targetY;
        const lastTopY = lastChild.targetY;

        paths.push({
            d: _generateBusBarPath(firstDropX, firstTopY, lastDropX, lastTopY, busBarY),
            type: 'bus-bar'
        });

        // Intermediate children (straight vertical drop stems from bus bar)
        for (let cIdx = 1; cIdx < children.length - 1; cIdx++) {
            const cSub = children[cIdx];
            const childOriginX = originX + cSub.relX;
            paths.push({ d: `M ${childOriginX} ${busBarY} L ${childOriginX} ${cSub.targetY}`, type: 'child-stem' });
        }

        // Recurse for all children
        children.forEach(cSub => {
            traverse(cSub, originX + cSub.relX);
        });
    }

    /**
     * Constructs a positioned card descriptor for flattened tree layout rendering.
     *
     * @param {Object} mInfo - Member layout descriptor
     * @param {number} cardAbsX - Absolute horizontal position coordinate
     * @param {number} cardAbsY - Absolute vertical position coordinate
     * @returns {Object} Positioned node descriptor
     *
     * @example
     * const card1 = FamilyTree._buildFlattenedNode(mInfo, 150, 200);
     *
     * @example
     * const card2 = FamilyTree._buildFlattenedNode(spouseInfo, 250, 200);
     */
    static _buildFlattenedNode(mInfo, cardAbsX, cardAbsY) {
        return {
            person: mInfo.person,
            isPartner: !mInfo.isBloodline,
            hasHiddenLineage: mInfo.hasHiddenLineage,
            hasChildren: mInfo.mChildren.length > 0,
            isCollapsed: mInfo.mIsCollapsed,
            x: cardAbsX,
            y: cardAbsY
        };
    }

    /**
     * Generates vertical drop stems, bus-bars, and child stem paths connecting parents to children.
     *
     * @param {Object} params - Parameter bundle
     *
     * @example
     * FamilyTree._generateChildConnections({ mInfo, originX: 0, cardAbsX: 100, cardAbsY: 200, ... })
     *
     * @example
     * FamilyTree._generateChildConnections({ mInfo: childlessInfo, originX: 0, cardAbsX: 0, cardAbsY: 0, ... })
     * // returns early when childLayouts is empty
     */
    static _generateChildConnections({ mInfo, originX, cardAbsX, cardAbsY, isSyntheticSiblingUnit, paths, traverse }) {
        if (mInfo.childLayouts.length === 0) return;
        const nodeW = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeH = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;
        const parentDropX = cardAbsX + nodeW / 2;
        const busBarY = mInfo.groupBusBarY;
        const children = mInfo.childLayouts;

        if (!isSyntheticSiblingUnit) {
            paths.push({ d: `M ${parentDropX} ${cardAbsY + nodeH} L ${parentDropX} ${busBarY}`, type: 'parent-stem' });
        }

        if (children.length === 1) {
            FamilyTree._generateSingleChildConnection({
                cSub: children[0], originX, parentDropX, busBarY, isSyntheticSiblingUnit, paths, traverse
            });
        } else {
            FamilyTree._generateMultiChildConnections({ children, originX, busBarY, paths, traverse });
        }
    }

    /**
     * Computes the bounding box of a set of connector paths.
     *
     * Connector `d` strings are plain "command x y ..." sequences (straight segments plus
     * quadratic corners), so reading every number positionally as an (x, y) pair is enough
     * to bound the drawing without parsing SVG properly — the same trick
     * {@link PrintTileBounds.intersectsPath} uses. Quadratic control points can sit slightly
     * outside the curve they shape, so the box may overshoot a rounded corner by its radius;
     * erring outwards is deliberate, since the only cost is a few unused pixels whereas
     * erring inwards crops the stroke off the page.
     *
     * @param {Array<Object>} paths - Connector path descriptors exposing an SVG path string `d`
     * @returns {{ minX: number, minY: number, maxX: number, maxY: number }|null} Bounds, or null when nothing is drawn
     *
     * @example
     * FamilyTree._computePathBounds([{ d: 'M 10 20 L 100 20' }]);
     * // => { minX: 10, minY: 20, maxX: 100, maxY: 20 }
     *
     * @example
     * // Real sibling bus-bar: fractional coordinates and rounded corners are both handled.
     * FamilyTree._computePathBounds([{ d: 'M -2685.4 179 L -2685.4 167 Q -2685.4 159 -2677.4 159' }]).minY;
     * // => 159
     *
     * @example
     * FamilyTree._computePathBounds([]);
     * // => null
     */
    static _computePathBounds(paths) {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

        (paths || []).forEach(p => {
            const nums = (String(p.d).match(/-?\d+(?:\.\d+)?/g) || []).map(Number);
            for (let i = 0; i + 1 < nums.length; i += 2) {
                const x = nums[i], y = nums[i + 1];
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        });

        return minX === Infinity ? null : { minX, minY, maxX, maxY };
    }

    /**
     * Computes the 2D bounding box and dimensions for the flattened tree layout.
     *
     * Covers connectors as well as cards: a sibling bus-bar is drawn *above* the cards it
     * joins, so bounding cards alone crops the top-most sibling link off the printed page.
     *
     * @param {Array<Object>} nodes - Positioned nodes
     * @param {Array<Object>} paths - Layout connector paths
     * @returns {{ minX: number, minY: number, maxX: number, maxY: number, width: number, height: number }}
     *
     * @example
     * FamilyTree._computeLayoutBounds([{ x: 0, y: 0 }], [])
     * // => { minX: 0, minY: 0, maxX: 90, maxY: 76, width: 90, height: 76 }
     *
     * @example
     * // The bus-bar rises 20px above the cards, so the box starts at -20 rather than 0.
     * FamilyTree._computeLayoutBounds([{ x: 0, y: 0 }], [{ type: 'bus-bar', d: 'M 45 0 L 45 -20' }])
     * // => { minX: 0, minY: -20, maxX: 90, maxY: 76, width: 90, height: 96 }
     *
     * @example
     * FamilyTree._computeLayoutBounds([], [])
     * // => { minX: 0, minY: 0, maxX: 1000, maxY: 1000, width: 1000, height: 1000 }
     */
    static _computeLayoutBounds(nodes, paths) {
        const nodeWidth = typeof TREE_NODE_WIDTH !== 'undefined' ? TREE_NODE_WIDTH : 90;
        const nodeHeight = typeof TREE_NODE_HEIGHT !== 'undefined' ? TREE_NODE_HEIGHT : 76;
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

        nodes.forEach(n => {
            if (n.x < minX) minX = n.x;
            if (n.x + nodeWidth > maxX) maxX = n.x + nodeWidth;
            if (n.y < minY) minY = n.y;
            if (n.y + nodeHeight > maxY) maxY = n.y + nodeHeight;
        });

        const pathBounds = FamilyTree._computePathBounds(paths);
        if (pathBounds) {
            minX = Math.min(minX, pathBounds.minX);
            minY = Math.min(minY, pathBounds.minY);
            maxX = Math.max(maxX, pathBounds.maxX);
            maxY = Math.max(maxY, pathBounds.maxY);
        }

        if (minX === Infinity) {
            minX = 0; maxX = 1000; minY = 0; maxY = 1000;
        }

        return {
            minX,
            minY,
            maxX,
            maxY,
            width: maxX - minX,
            height: maxY - minY
        };
    }

    /**
     * Checks whether a target ID matches a candidate's explicit ID or resolved node ID.
     *
     * @param {string|null} targetId - ID to match
     * @param {Object} c - Candidate object
     * @param {Person|null} candNode - Resolved candidate person node in the tree
     * @returns {boolean} True if targetId matches candidate's explicit or node ID
     *
     * @example
     * FamilyTree._matchesCandidateId('c1', { id: 'c1' }, null)
     * // => true
     *
     * @example
     * FamilyTree._matchesCandidateId('node_99', { id: 'c1' }, { id: 'node_99' })
     * // => true
     */
    static _matchesCandidateId(targetId, c, candNode) {
        if (!targetId || !c) return false;
        return targetId === c.id || Boolean(candNode && targetId === candNode.id);
    }

    /**
     * Checks whether a parent linked to a subject matches the candidate by ID or by name + sheet row.
     *
     * @param {string|null} parentId - Parent ID on the subject person
     * @param {Object} c - Candidate object
     * @param {Person|null} candNode - Resolved candidate person node
     * @param {FamilyTree} tree - Tree instance
     * @returns {boolean} True if parent matches candidate
     *
     * @example
     * FamilyTree._matchesParentCandidate('mom_1', { id: 'mom_1' }, null, tree)
     * // => true
     *
     * @example
     * FamilyTree._matchesParentCandidate(null, { id: 'mom_1' }, null, tree)
     * // => false
     */
    static _matchesParentCandidate(parentId, c, candNode, tree) {
        if (!parentId) return false;
        if (FamilyTree._matchesCandidateId(parentId, c, candNode)) return true;
        const parent = tree ? tree.get(parentId) : null;
        if (parent && parent.name?.toLowerCase() === (c.name || '').toLowerCase()) {
            if (c.sheetRow && parent.sheetRow && c.sheetRow === parent.sheetRow) return true;
        }
        return false;
    }

    /**
     * Checks whether the candidate node has a reciprocal parent, spouse, or child link pointing to the subject.
     *
     * @param {Person|null} candNode - Candidate node in the tree
     * @param {string} personId - Subject person ID
     * @returns {boolean} True if candidate links back to person
     *
     * @example
     * FamilyTree._hasReverseLinkToPerson({ momId: 'p1' }, 'p1')
     * // => true
     *
     * @example
     * FamilyTree._hasReverseLinkToPerson(null, 'p1')
     * // => false
     */
    static _hasReverseLinkToPerson(candNode, personId) {
        if (!candNode || !personId) return false;
        return candNode.momId === personId ||
               candNode.fatherId === personId ||
               Boolean(candNode.partners?.includes(personId)) ||
               Boolean(candNode.children?.includes(personId));
    }

    /**
     * Determines whether an ambiguity candidate is the one currently linked/used in the family tree.
     *
     * @param {Object} c - Candidate object
     * @param {Object} amb - Ambiguity descriptor
     * @param {Person} p - Subject person
     * @param {FamilyTree} tree - Family tree instance
     * @returns {boolean} True if candidate is currently used in the tree
     *
     * @example
     * FamilyTree._isCandidateUsed({ id: 'c1', isCurrentlyUsed: true }, amb, p, tree)
     * // => true
     *
     * @example
     * FamilyTree._isCandidateUsed(null, amb, p, tree)
     * // => false
     */
    static _isCandidateUsed(c, amb, p, tree) {
        if (!c) return false;
        const candNode = tree ? tree.get(c.id) : null;
        const livePerson = tree ? (tree.get(p.id) || p) : p;
        const rel = (amb?.relation || '').toLowerCase();

        if (rel.includes('mother') || rel.includes('mom')) {
            if (FamilyTree._matchesParentCandidate(livePerson.momId, c, candNode, tree)) return true;
        }
        if (rel.includes('father') || rel.includes('dad')) {
            if (FamilyTree._matchesParentCandidate(livePerson.fatherId, c, candNode, tree)) return true;
        }
        if (rel.includes('spouse') || rel.includes('husband') || rel.includes('wife')) {
            if (livePerson.partners?.some(pid => FamilyTree._matchesCandidateId(pid, c, candNode))) return true;
        }
        if (rel.includes('son') || rel.includes('daughter') || rel.includes('child')) {
            if (livePerson.children?.some(cid => FamilyTree._matchesCandidateId(cid, c, candNode))) return true;
        }

        if (FamilyTree._hasReverseLinkToPerson(candNode, livePerson.id)) return true;

        if (c.isCurrentlyUsed || c.isSelected) return true;
        if (FamilyTree._matchesCandidateId(amb?.selectedId, c, candNode)) return true;

        return false;
    }

    /**
     * Audits age gap between parent and child for biological constraints and generational warnings.
     *
     * @example
     * FamilyTree._checkParentChildAgeGap(child, parent, 'Mother', 45, issues);
     * // Appends error if gap <= 0, warning if gap < 12 or gap > 45
     *
     * @example
     * FamilyTree._checkParentChildAgeGap(child, parentWithoutYob, 'Father', 60, issues);
     * // returns early without appending issues
     *
     * @param {Person} child - Child profile with yob
     * @param {Person} parent - Parent profile with yob
     * @param {string} role - 'Mother' or 'Father'
     * @param {number} maxAge - Maximum expected age at childbirth
     * @param {Array<Object>} issues - Array to append issues to
     */
    static _checkParentChildAgeGap(child, parent, role, maxAge, issues) {
        if (!parent.yob) return;
        const gap = child.yob - parent.yob;
        if (gap <= 0) {
            issues.push({
                p: child,
                type: 'error',
                category: 'parent_child_inconsistency',
                text: `Born in ${child.yob}, but ${role.toLowerCase()} (${parent.name}) was born in ${parent.yob} (child cannot be born before or in the same year as parent).`
            });
        } else if (gap < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE) {
            issues.push({
                p: child,
                type: 'warning',
                category: 'parent_child_inconsistency',
                text: `${role} (${parent.name}) was only ${gap} years old at childbirth (under biological minimum age of ${FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE}).`
            });
        }
        if (gap > maxAge) {
            issues.push({
                p: child,
                type: 'warning',
                category: 'parent_child_inconsistency',
                text: `${role} (${parent.name}) is unusually old (${gap} yrs) at birth.`
            });
        }
    }

    /**
     * Audits whether child was born after parent's death year.
     *
     * @example
     * FamilyTree._checkParentDeathConsistency(child, parent, 'Mother', false, issues);
     * // Appends error if child.yob > parent.death
     *
     * @example
     * FamilyTree._checkParentDeathConsistency(child, parentWithoutDeath, 'Father', true, issues);
     * // returns early without appending issues
     *
     * @param {Person} child - Child profile with yob
     * @param {Person} parent - Parent profile with death year
     * @param {string} role - 'Mother' or 'Father'
     * @param {boolean} allowPosthumous - Allow childbirth up to 1 year after death (for father)
     * @param {Array<Object>} issues - Array to append issues to
     */
    static _checkParentDeathConsistency(child, parent, role, allowPosthumous, issues) {
        if (!parent.death) return;
        const pDeath = parseInt(parent.death, 10);
        const limit = allowPosthumous ? pDeath + 1 : pDeath;
        if (!isNaN(pDeath) && child.yob > limit) {
            issues.push({
                p: child,
                type: 'error',
                category: 'parent_child_inconsistency',
                text: `Born in ${child.yob}, but ${role.toLowerCase()} (${parent.name}) died in ${pDeath}.`
            });
        }
    }

    /**
     * Audits a single parent-child relationship for biological childbirth age bounds and post-mortem errors.
     *
     * @param {Person} child - Child profile
     * @param {string|null} parentId - Parent profile ID
     * @param {Object} roleBounds - Parental role constraints ({ role, maxAge, allowPosthumous })
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditSingleParentChildLink(child, '1', { role: 'Mother', maxAge: 45, allowPosthumous: false }, tree, issues);
     *
     * @example
     * FamilyTree._auditSingleParentChildLink(child, null, { role: 'Father', maxAge: 60, allowPosthumous: true }, tree, issues);
     * // returns early when parentId is null
     */
    static _auditSingleParentChildLink(child, parentId, roleBounds, tree, issues) {
        if (!parentId) return;
        const parent = tree.get(parentId);
        if (!parent) return;

        const { role, maxAge, allowPosthumous } = roleBounds;
        FamilyTree._checkParentChildAgeGap(child, parent, role, maxAge, issues);
        FamilyTree._checkParentDeathConsistency(child, parent, role, allowPosthumous, issues);
    }

    /**
     * Audits parental age at childbirth and post-mortem childbirth errors.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree containing parent nodes
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditParentChildConsistency(childWithYob, tree, issues);
     *
     * @example
     * FamilyTree._auditParentChildConsistency(childWithoutYob, tree, issues);
     * // returns early when p.yob is falsy
     */
    static _auditParentChildConsistency(p, tree, issues) {
        if (!p.yob) return;
        FamilyTree._auditSingleParentChildLink(
            p, p.momId, { role: 'Mother', maxAge: FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE, allowPosthumous: false }, tree, issues
        );
        FamilyTree._auditSingleParentChildLink(
            p, p.fatherId, { role: 'Father', maxAge: FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE, allowPosthumous: true }, tree, issues
        );
    }

    /**
     * Determines whether a spousal ambiguity has been implicitly resolved by a single close sheet neighbor candidate.
     *
     * @param {Object} amb - Ambiguity descriptor
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @returns {boolean} True if ambiguity is resolved by proximity
     *
     * @example
     * FamilyTree._isSpouseAmbiguityResolvedByProximity({ relation: 'spouse', candidates: [nearCand, farCand] }, p, tree)
     * // => true
     *
     * @example
     * FamilyTree._isSpouseAmbiguityResolvedByProximity({ relation: 'mother', candidates: [] }, p, tree)
     * // => false
     */
    static _isSpouseAmbiguityResolvedByProximity(amb, p, tree) {
        const isSpouseRelation = ['spouse', 'husband', 'wife', 'partner'].includes(amb.relation);
        if (!isSpouseRelation) return false;

        const maxClose = FamilyTreeBuilder.GENERATIONAL_GAPS?.MAX_ROW_NEIGHBOR_DISTANCE || 5;
        const closebyCands = (amb.candidates || []).filter(c => {
            const cNode = tree.get(c.id) || c;
            return FamilyTreeBuilder.sharesSheet(cNode, p) && 
                FamilyTreeBuilder._getMinRowDistance(cNode, p) <= maxClose;
        });
        return closebyCands.length === 1;
    }

    /**
     * Orders ambiguity candidates with the currently used/linked candidate placed first.
     * Marks the active candidate with `isCurrentlyUsed = true`.
     *
     * @param {Object} amb - Ambiguity descriptor
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @returns {Array<Object>} Ordered candidate list
     *
     * @example
     * FamilyTree._orderAmbiguityCandidates({ candidates: [c1, c2] }, p, tree)
     * // => [c2, c1] (with c2.isCurrentlyUsed = true)
     *
     * @example
     * FamilyTree._orderAmbiguityCandidates({}, p, tree)
     * // => []
     */
    static _orderAmbiguityCandidates(amb, p, tree) {
        const candidates = amb.candidates || [];
        const usedCand = candidates.find(c => FamilyTree._isCandidateUsed(c, amb, p, tree)) || candidates[candidates.length - 1];
        const orderedCandidates = usedCand ? [usedCand, ...candidates.filter(c => c !== usedCand)] : candidates;
        if (usedCand) usedCand.isCurrentlyUsed = true;
        amb.candidates = orderedCandidates;
        return orderedCandidates;
    }

    /**
     * Formats ambiguity records for the audit log, ordering the active graph candidate first.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditAmbiguities(personWithAmbiguities, tree, issues);
     *
     * @example
     * FamilyTree._auditAmbiguities(personWithoutAmbiguities, tree, issues);
     * // returns early when ambiguities array is empty
     */
    static _auditAmbiguities(p, tree, issues) {
        if (!p.ambiguities || p.ambiguities.length === 0) return;
        const seenAmb = new Set();
        p.ambiguities.forEach(amb => {
            if (typeof amb === 'string') {
                if (!seenAmb.has(amb)) {
                    seenAmb.add(amb);
                    issues.push({ p, type: 'warning', category: 'ambiguity', amb: { message: amb }, text: `Ambiguity: ${amb}` });
                }
                return;
            }
            const key = `${amb.relation || ''}_${amb.query || ''}_${(amb.candidates || []).map(c => c.id || c.name).join('_')}`;
            if (seenAmb.has(key)) return;
            seenAmb.add(key);

            if (FamilyTree._isSpouseAmbiguityResolvedByProximity(amb, p, tree)) return;

            const orderedCandidates = FamilyTree._orderAmbiguityCandidates(amb, p, tree);
            const cList = FamilyTree._formatAmbiguityCandidatesSummary(orderedCandidates);
            const candStr = cList ? `: ${cList}` : '';
            const message = amb.message || `Found multiple candidates for ${amb.relation || 'relationship'} '${amb.query || ''}'`;
            issues.push({ p, type: 'warning', category: 'ambiguity', amb, text: `Ambiguity: ${message}${candStr}` });
        });
    }

    /**
     * Formats a list of candidate profiles into a concise comma-separated summary string.
     *
     * @param {Array<Object>} candidates - Candidate profiles
     * @returns {string} Comma-separated candidate details string
     *
     * @example
     * FamilyTree._formatAmbiguityCandidatesSummary([
     *   { name: 'Joseph', yob: 1920, death: 1995, sheetRow: 7 },
     *   { name: 'Joseph', yob: 1930 }
     * ])
     * // => 'Joseph (b. 1920, d. 1995, Row 7), Joseph (b. 1930)'
     *
     * @example
     * FamilyTree._formatAmbiguityCandidatesSummary([])
     * // => ''
     */
    static _formatAmbiguityCandidatesSummary(candidates) {
        return (candidates || [])
            .map(c => {
                const details = [
                    c.yob ? `b. ${c.yob}` : '',
                    c.death ? `d. ${c.death}` : '',
                    c.sheetRow ? `Row ${c.sheetRow}` : ''
                ].filter(Boolean).join(', ');
                return `${c.name}${details ? ` (${details})` : ''}`;
            })
            .filter(Boolean)
            .join(', ');
    }

    /**
     * Audits birth year, death year, and lifespan bounds for an individual.
     *
     * Rules checked:
     * - Death year recorded before birth year (error).
     * - Birth or death year in the future (error).
     * - Unusually early birth year < 1700 (warning).
     * - Lifespan > 115 years or living individual > 115 years old (warning).
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditDateConsistency({ yob: 1950, death: 1940 }, tree, issues);
     * // => issues.push({ type: 'error', category: 'date_anomaly', text: 'Death year (1940) is recorded before birth year (1950).' })
     *
     * @example
     * FamilyTree._auditDateConsistency({ yob: 1850, isGhost: false }, tree, issues);
     * // => issues.push({ type: 'warning', category: 'lifespan_anomaly', text: 'Profile born in 1850 is over 115 years old...' })
     */
    static _auditDateConsistency(p, tree, issues) {
        const currentYear = new Date().getFullYear();
        const yob = p.yob;
        const death = p.death ? parseInt(p.death, 10) : null;

        const dateRules = [
            { when: yob && death && death < yob, type: 'error', cat: 'date_anomaly', text: `Death year (${death}) is recorded before birth year (${yob}).` },
            { when: yob && yob > currentYear, type: 'error', cat: 'date_anomaly', text: `Birth year (${yob}) is in the future.` },
            { when: death && death > currentYear, type: 'error', cat: 'date_anomaly', text: `Death year (${death}) is in the future.` },
            { when: yob && yob < 1700, type: 'warning', cat: 'date_anomaly', text: `Unusually early birth year (${yob}) — check for typographical error.` },
            { when: yob && death && (death - yob > 115), type: 'warning', cat: 'lifespan_anomaly', text: `Recorded lifespan of ${death - yob} years (${yob}–${death}) exceeds normal human longevity (>115 yrs).` },
            { when: !p.isGhost && yob && !death && (currentYear - yob > 115), type: 'warning', cat: 'lifespan_anomaly', text: `Profile born in ${yob} is over 115 years old (${currentYear - yob} yrs) without a recorded death year.` }
        ];

        for (const { when, type, cat, text } of dateRules) {
            if (when) issues.push({ p, type, category: cat, text });
        }
    }

    /**
     * Audits the age difference between husband and wife, flagging wives recorded as older
     * or unusually large age gaps exceeding 30 years. Evaluated once per partnership pair (p.id < partner.id).
     *
     * @param {Person} p - First partner
     * @param {Person} partner - Second partner
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditSpousalAgeGap(Husband_1930, Wife_1925, issues);
     * // => issues.push({ category: 'spouse_inconsistency', text: 'Wife ... older than husband ... by 5 years.' })
     *
     * @example
     * FamilyTree._auditSpousalAgeGap(Husband_1930, Wife_1935, issues);
     * // normal age gap, no issue appended
     */
    static _auditSpousalAgeGap(p, partner, issues) {
        if (!p.yob || !partner.yob || p.id >= partner.id) return;

        const isHusband = p.gender === 'M' || partner.gender === 'F';
        const husband = isHusband ? p : partner;
        const wife = isHusband ? partner : p;
        const gap = wife.yob - husband.yob;

        if (gap < 0 && Math.abs(gap) > 0) {
            issues.push({
                p: husband,
                type: 'warning',
                category: 'spouse_inconsistency',
                text: `Wife ${wife.name} (b. ${wife.yob}) is recorded as older than husband ${husband.name} (b. ${husband.yob}) by ${Math.abs(gap)} years.`
            });
        } else if (gap > 30) {
            issues.push({
                p: husband,
                type: 'warning',
                category: 'spouse_inconsistency',
                text: `Unusually large spousal age gap: husband ${husband.name} (b. ${husband.yob}) is ${gap} years older than wife ${wife.name} (b. ${wife.yob}).`
            });
        }
    }

    /**
     * Audits an individual partner link for post-mortem marriage, age gap bounds, or celibacy violations.
     *
     * @param {Person} p - Target person
     * @param {Person} partner - Linked partner profile
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditSinglePartnerLink({ name: 'Mary', death: 1950 }, { name: 'John', yob: 1955 }, issues);
     * // => issues.push({ type: 'error', category: 'spouse_inconsistency', text: 'Spouse John was born in 1955, after Mary died in 1950.' })
     *
     * @example
     * FamilyTree._auditSinglePartnerLink({ name: 'Sr. Mary', isNun: true }, { name: 'John' }, issues);
     * // => issues.push({ type: 'warning', category: 'religious_vow', text: 'Religious profile with vows of celibacy (Sr. Mary) has a linked partner (John).' })
     */
    static _auditSinglePartnerLink(p, partner, issues) {
        if (p.death && partner.yob && parseInt(p.death, 10) < partner.yob) {
            issues.push({
                p,
                type: 'error',
                category: 'spouse_inconsistency',
                text: `Spouse ${partner.name} was born in ${partner.yob}, after ${p.name} died in ${p.death}.`
            });
        }

        FamilyTree._auditSpousalAgeGap(p, partner, issues);

        if (FamilyTreeBuilder._isCelibateReligious(p)) {
            issues.push({
                p,
                type: 'warning',
                category: 'religious_vow',
                text: `Religious profile with vows of celibacy (${p.name}) has a linked partner (${partner.name}).`
            });
        }
    }

    /**
     * Audits whether a profile is partnered with two or more biological siblings.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditSiblingSpouseConflicts(personWithSiblingPartners, tree, issues);
     * // => appends sibling_spouse_conflict error to issues
     *
     * @example
     * FamilyTree._auditSiblingSpouseConflicts(personWithOnePartner, tree, issues);
     * // returns without issues
     */
    static _auditSiblingSpouseConflicts(p, tree, issues) {
        for (let i = 0; i < p.partners.length; i++) {
            for (let j = i + 1; j < p.partners.length; j++) {
                const p1 = tree.get(p.partners[i]);
                const p2 = tree.get(p.partners[j]);
                if (p1 && p2 && FamilyTreeBuilder._areBiologicalSiblings(p1, p2)) {
                    issues.push({
                        p,
                        type: 'error',
                        category: 'sibling_spouse_conflict',
                        text: `Profile ${p.name} is partnered with biological siblings ${p1.name} and ${p2.name}.`
                    });
                }
            }
        }
    }

    /**
     * Extracts an explicit ordinal suffix (e.g. 1 from 'Wife 1') from a partner profile name.
     *
     * @param {Person} node - Partner profile
     * @returns {number|null} 1-based ordinal index or null if none
     *
     * @example
     * FamilyTree._extractPartnerOrdinal({ name: 'Kochappappan Wife 1' })
     * // => 1
     *
     * @example
     * FamilyTree._extractPartnerOrdinal({ name: 'Mary' })
     * // => null
     */
    static _extractPartnerOrdinal(node) {
        const match = (node?.name || '').match(/\b(?:Wife|Husband|Spouse|Partner)\s*(\d+)\b/i);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Determines the first and last childbearing birth years for a parent-spouse partnership.
     *
     * @param {Person} parent - Parent profile
     * @param {Person} spouse - Partner profile
     * @param {FamilyTree} tree - Tree instance for child lookups
     * @returns {{first: number|null, last: number|null}} First and last child YOB
     *
     * @example
     * FamilyTree._getSpouseChildbearingYears(parentWithChildren, spouse, tree)
     * // => { first: 1921, last: 1927 }
     *
     * @example
     * FamilyTree._getSpouseChildbearingYears(childlessParent, spouse, tree)
     * // => { first: null, last: null }
     */
    static _getSpouseChildbearingYears(parent, spouse, tree) {
        const spouseNormName = spouse._normName || spouse.name?.toLowerCase().trim();
        const children = (parent.children || [])
            .map(cid => tree.get(cid))
            .filter(c => c && (
                c.momId === spouse.id ||
                c.fatherId === spouse.id ||
                (c.mom && c.mom.toLowerCase().trim() === spouseNormName) ||
                (c.father && c.father.toLowerCase().trim() === spouseNormName)
            ));
        const yobs = children.map(c => c.yob || c._inferredYob).filter(Boolean);
        return {
            first: yobs.length ? Math.min(...yobs) : null,
            last: yobs.length ? Math.max(...yobs) : null
        };
    }

    /**
     * Determines whether partner p2 precedes partner p1 in chronological marriage sequence.
     *
     * @param {number|null} ord1 - Ordinal indicator of first partner
     * @param {number|null} ord2 - Ordinal indicator of second partner
     * @param {Object} ch1 - Childbearing years for first partner
     * @param {Object} ch2 - Childbearing years for second partner
     * @param {?number} y1 - Birth year of first partner
     * @param {?number} y2 - Birth year of second partner
     * @returns {boolean} True if p2 is chronologically earlier than p1
     *
     * @example
     * FamilyTree._isSecondPartnerEarlier(null, 1, {}, {}, 1950, 1945);
     * // => true
     *
     * @example
     * FamilyTree._isSecondPartnerEarlier(1, null, {}, {}, 1945, 1950);
     * // => false
     */
    static _isSecondPartnerEarlier(ord1, ord2, ch1, ch2, y1, y2) {
        if (ord1 === 1) return false;
        if (ord2 === 1) return true;
        if (ch1 && ch2 && ch1.first && ch2.first) {
            return ch1.first > ch2.first;
        }
        return Boolean(y1 && y2 && y1 > y2);
    }

    /**
     * Determines the chronological ordering of two spouses sharing a central partner.
     *
     * @param {Person} p1 - First spouse profile
     * @param {Person} p2 - Second spouse profile
     * @param {Person} p - Shared spouse profile
     * @param {FamilyTree} tree - Tree instance
     * @returns {{ earlySpouse: Person, lateSpouse: Person, earlyCh: Object, lateCh: Object, ord1: number|null, ord2: number|null }}
     *
     * @example
     * FamilyTree._determinePartnerOrder(Wife2, Wife1, p, tree)
     * // => { earlySpouse: Wife1, lateSpouse: Wife2, ... }
     *
     * @example
     * FamilyTree._determinePartnerOrder(WifeA, WifeB, p, tree)
     * // => { earlySpouse: WifeA, lateSpouse: WifeB, ... }
     */
    static _determinePartnerOrder(p1, p2, p, tree) {
        const ord1 = FamilyTree._extractPartnerOrdinal(p1);
        const ord2 = FamilyTree._extractPartnerOrdinal(p2);
        const ch1 = FamilyTree._getSpouseChildbearingYears(p, p1, tree);
        const ch2 = FamilyTree._getSpouseChildbearingYears(p, p2, tree);

        const y1 = p1.yob || p1._inferredYob;
        const y2 = p2.yob || p2._inferredYob;

        const p2Earlier = FamilyTree._isSecondPartnerEarlier(ord1, ord2, ch1, ch2, y1, y2);
        const earlySpouse = p2Earlier ? p2 : p1;
        const lateSpouse = p2Earlier ? p1 : p2;
        const earlyCh = p2Earlier ? ch2 : ch1;
        const lateCh = p2Earlier ? ch1 : ch2;
        return { earlySpouse, lateSpouse, earlyCh, lateCh, ord1, ord2 };
    }

    /**
     * Checks if two ordinal partner indicators denote sequential partnerships (e.g. Wife 1 vs Wife 2).
     *
     * @param {number|null} ord1 - Ordinal of first partner
     * @param {number|null} ord2 - Ordinal of second partner
     * @returns {boolean} True if ordinals denote sequential spouses
     *
     * @example
     * FamilyTree._areExplicitSequentialOrdinals(1, 2)
     * // => true
     *
     * @example
     * FamilyTree._areExplicitSequentialOrdinals(null, null)
     * // => false
     */
    static _areExplicitSequentialOrdinals(ord1, ord2) {
        if (ord1 === null && ord2 === null) return false;
        if (ord1 !== null && ord2 !== null) return ord1 !== ord2;
        return (ord1 === 1 && ord2 !== 1) || (ord2 === 1 && ord1 !== 1);
    }

    /**
     * Checks whether two partner profiles have overlapping lifespans.
     * When death year is not specified, lifespan is estimated up to 80 years from birth.
     *
     * @param {Person} p1 - First partner profile
     * @param {Person} p2 - Second partner profile
     * @returns {boolean} True if partner lifespans overlap
     *
     * @example
     * FamilyTree._haveOverlappingLifespans({ yob: 1920, death: 1980 }, { yob: 1930, death: 1990 })
     * // => true
     *
     * @example
     * FamilyTree._haveOverlappingLifespans({ yob: 1900, death: 1925 }, { yob: 1930, death: 1970 })
     * // => false
     */
    static _haveOverlappingLifespans(p1, p2) {
        const y1 = p1.yob || p1._inferredYob;
        const y2 = p2.yob || p2._inferredYob;
        const d1 = p1.death ? parseInt(p1.death, 10) : (y1 ? y1 + 80 : null);
        const d2 = p2.death ? parseInt(p2.death, 10) : (y2 ? y2 + 80 : null);
        return Boolean(y1 && y2 && d1 && d2 && Math.max(y1, y2) < Math.min(d1, d2));
    }

    /**
     * Evaluates whether two partners represent an allowable sequential remarriage rather than concurrent partners.
     *
     * Chronological order is determined by explicit ordinals (e.g. Wife 1 vs Wife 2), childbearing years,
     * or known birth years. If the earlier spouse died before or around the later spouse's childbearing/marriage
     * window, or if non-overlapping childbearing windows are established, returns true.
     *
     * @param {Person} p1 - First partner profile
     * @param {Person} p2 - Second partner profile
     * @param {Person} p - Parent profile
     * @param {FamilyTree} tree - Tree instance
     * @returns {boolean} True if relationship is a valid sequential remarriage
     *
     * @example
     * FamilyTree._isSequentialRemarriage(wife1, wife2, parent, tree)
     * // => true (when wife1 died before wife2 marriage)
     *
     * @example
     * FamilyTree._isSequentialRemarriage(wifeA, wifeB, parent, tree)
     * // => false (when lifespans and childbearing overlap)
     */
    static _isSequentialRemarriage(p1, p2, p, tree) {
        const { earlySpouse, lateSpouse, earlyCh, lateCh, ord1, ord2 } = FamilyTree._determinePartnerOrder(p1, p2, p, tree);

        const earlyDeath = earlySpouse.death ? parseInt(earlySpouse.death, 10) : null;
        const lateYob = lateSpouse.yob || lateSpouse._inferredYob;
        const lateMarriageStart = lateCh.first ? (lateCh.first - 1) : ((lateYob) ? lateYob + 20 : null);

        // If earlier spouse died before or around the later spouse marriage / childbearing, sequential remarriage!
        const remarriageCutoff = lateCh.first ? (lateCh.first + 2) : (lateMarriageStart ? lateMarriageStart + 2 : null);
        if (earlyDeath && remarriageCutoff && earlyDeath <= remarriageCutoff) {
            return true;
        }

        // If explicitly named sequential partners and earlier spouse had all children before later spouse started
        const isExplicitSequential = FamilyTree._areExplicitSequentialOrdinals(ord1, ord2);
        if (isExplicitSequential && (!earlyCh.last || !lateCh.first || earlyCh.last <= lateCh.first + 2)) {
            if (!earlyDeath || !lateMarriageStart || earlyDeath <= lateMarriageStart + 2) {
                return true;
            }
        }

        return false;
    }

    /**
     * Audits multi-partner profiles for concurrent overlapping living partners without recorded remarriage.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditConcurrentPartners(personWithConcurrentPartners, tree, issues);
     * // appends concurrent_partners error
     *
     * @example
     * FamilyTree._auditConcurrentPartners(personWithSinglePartner, tree, issues);
     * // returns early without appending issues
     */
    static _auditConcurrentPartners(p, tree, issues) {
        // Remarriages/multiple partners explicitly recorded with comma or slash are intentional polygamy/polyandry records
        if (p.spouse?.includes(',') || p.spouse?.includes('/')) return;

        const partnerNodes = p.partners.map(id => tree.get(id)).filter(Boolean);
        for (let i = 0; i < partnerNodes.length; i++) {
            for (let j = i + 1; j < partnerNodes.length; j++) {
                const p1 = partnerNodes[i], p2 = partnerNodes[j];
                if (FamilyTree._isSequentialRemarriage(p1, p2, p, tree)) {
                    continue;
                }

                if (FamilyTree._haveOverlappingLifespans(p1, p2)) {
                    issues.push({
                        p,
                        type: 'error',
                        category: 'concurrent_partners',
                        text: `Multiple concurrent living partners: ${p1.name} and ${p2.name} overlap in lifespan without recorded divorce or sequential remarriage.`
                    });
                }
            }
        }
    }

    /**
     * Audits spouse relationships for a person, checking single-partner anomalies,
     * sibling-spouse incest prohibitions, and concurrent living partners.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance for partner lookups
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditSpouseConsistency(personWithPartners, tree, issues);
     *
     * @example
     * FamilyTree._auditSpouseConsistency(unpartneredPerson, tree, issues);
     * // returns early when p.partners is empty
     */
    static _auditSpouseConsistency(p, tree, issues) {
        if (!p.partners || p.partners.length === 0) return;

        // 1. Audit individual partner pairings (age bounds, post-mortem marriages, celibacy vows)
        p.partners.forEach(partId => {
            const partner = tree.get(partId);
            if (partner) {
                FamilyTree._auditSinglePartnerLink(p, partner, issues);
            }
        });

        // 2. Multi-partner audits (biological sibling-spouses, concurrent living partners)
        if (p.partners.length > 1) {
            FamilyTree._auditSiblingSpouseConflicts(p, tree, issues);
            FamilyTree._auditConcurrentPartners(p, tree, issues);
        }
    }

    /**
     * Audits whether declared spouses, mothers, or fathers in spreadsheet data rows
     * were successfully linked to concrete or ghost profiles in the tree.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance
     * @param {Array<Object>} issues - Accumulated issue list
     *
     * @example
     * FamilyTree._auditUnresolvedClaims(personWithUnlinkedSpouse, tree, issues);
     * // appends unresolved_claim warning
     *
     * @example
     * FamilyTree._auditUnresolvedClaims(ghostPerson, tree, issues);
     * // returns early for ghost profiles
     */
    static _auditUnresolvedClaims(p, tree, issues) {
        if (p.isGhost) return;
        const claims = [
            { role: 'spouse', declared: p.spouse, isLinked: p.partners && p.partners.length > 0 },
            { role: 'mother', declared: p.mom, isLinked: !!p.momId },
            { role: 'father', declared: p.father, isLinked: !!p.fatherId }
        ];
        claims.forEach(({ role, declared, isLinked }) => {
            if (declared && !isLinked) {
                issues.push({
                    p,
                    type: 'warning',
                    category: 'unresolved_claim',
                    text: `Declared ${role} '${declared}' in spreadsheet, but no matching ${role} profile was linked in tree.`
                });
            }
        });
    }

    /**
     * Checks a person model for chronological, biological, or relational inconsistencies.
     *
     * Rules checked:
     * - Death year recorded before birth year.
     * - Parent age at childbirth below minimum marriage age or above biological ceiling.
     * - Child born after parent recorded death year.
     * - Unresolved ambiguous linkages or multiple partners.
     *
     * @param {Person} p - Target person
     * @param {FamilyTree} tree - Tree instance for parent lookups
     * @returns {Array<{p: Person, type: 'error'|'warning', text: string}>} Inconsistencies found
     *
     * @example
     * const issues = FamilyTree.auditPerson(person, tree);
     * // => [{ p: person, type: 'error', text: 'Death year (1950) is recorded before birth year (1960).' }]
     *
     * @example
     * const emptyIssues = FamilyTree.auditPerson(consistentPerson, tree);
     * // => []
     */
    static auditPerson(p, tree) {
        const issues = [];
        FamilyTree._auditDateConsistency(p, tree, issues);
        FamilyTree._auditParentChildConsistency(p, tree, issues);
        FamilyTree._auditSpouseConsistency(p, tree, issues);
        FamilyTree._auditUnresolvedClaims(p, tree, issues);
        FamilyTree._auditAmbiguities(p, tree, issues);

        if (p.partners && p.partners.length > 1) {
            issues.push({ p, type: 'warning', category: 'multiple_partners', partners: p.partners, text: `Has multiple partners (${p.partners.length}).` });
        }
        return issues;
    }

    /**
     * Strips common religious titles/honorifics ('Sr.', 'Fr.', 'Rev.', 'Br.') from a person name.
     *
     * @param {string} name - Raw person name
     * @returns {string} Cleaned name without title prefixes
     *
     * @example
     * FamilyTree.cleanPersonName('Sr. Philomena')
     * // => 'Philomena'
     *
     * @example
     * FamilyTree.cleanPersonName('Fr. Joseph')
     * // => 'Joseph'
     */
    static cleanPersonName(name) {
        if (!name || typeof name !== 'string') return '';
        let cleaned = name.trim();
        cleaned = cleaned.replace(/^(?:Rev\.|Fr\.|Sr\.|Br\.|Brother|Father|Sister)\s+/i, '');
        return cleaned.trim();
    }

    /**
     * Normalizes a string by phonetic spelling folding, reducing consecutive duplicates,
     * common digraphs (ph->p, th->t, ck->k, ch->c, sh->s, bh->b, dh->d, gh->g, kh->k),
     * and vowel digraphs (ee->i, oo->u).
     *
     * @param {string} str - Input word or name
     * @returns {string} Phonetically folded spelling string
     *
     * @example
     * FamilyTree.foldSpelling('Ouseph')
     * // => 'ousep'
     *
     * @example
     * FamilyTree.foldSpelling('Matthew')
     * // => 'matew'
     */
    static foldSpelling(str) {
        if (!str) return '';
        return str.toLowerCase().trim()
            .replace(/[\r\n\t]+/g, ' ')
            .replace(/([a-z])\1+/g, '$1')
            .replace(/ck/g, 'k')
            .replace(/bh/g, 'b')
            .replace(/dh/g, 'd')
            .replace(/gh/g, 'g')
            .replace(/kh/g, 'k')
            .replace(/ph/g, 'p')
            .replace(/th/g, 't')
            .replace(/ch/g, 'c')
            .replace(/sh/g, 's')
            .replace(/ee/g, 'i')
            .replace(/oo/g, 'u');
    }

    /**
     * Calculates the Levenshtein edit distance between two strings.
     *
     * @param {string} a - First string
     * @param {string} b - Second string
     * @returns {number} Minimum number of single-character edits (insertions, deletions, substitutions)
     *
     * @example
     * FamilyTree.levenshtein('kitten', 'sitting')
     * // => 3
     *
     * @example
     * FamilyTree.levenshtein('flaw', 'lawn')
     * // => 2
     */
    static levenshtein(a, b) {
        if (!a) return (b || '').length;
        if (!b) return a.length;
        const s1 = a.toLowerCase();
        const s2 = b.toLowerCase();
        const m = s1.length, n = s2.length;
        const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
        for (let i = 0; i <= m; i++) dp[i][0] = i;
        for (let j = 0; j <= n; j++) dp[0][j] = j;
        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= n; j++) {
                dp[i][j] = s1[i - 1] === s2[j - 1]
                    ? dp[i - 1][j - 1]
                    : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
            }
        }
        return dp[m][n];
    }

    /**
     * Computes the Jaro-Winkler similarity metric between two strings, returning
     * a normalized value in [0.0, 1.0]. Delegates to FamilyTreeBuilder.computeJaroWinkler.
     *
     * @param {string} s1 - First string
     * @param {string} s2 - Second string
     * @returns {number} Jaro-Winkler distance score between 0.0 and 1.0
     *
     * @example
     * FamilyTree.computeJaroWinkler('mothr', 'mother')
     * // => ~0.967
     *
     * @example
     * FamilyTree.computeJaroWinkler('dixon', 'dicksonx')
     * // => ~0.813
     */
    static computeJaroWinkler(s1, s2) {
        if (typeof FamilyTreeBuilder !== 'undefined' && typeof FamilyTreeBuilder.computeJaroWinkler === 'function') {
            return FamilyTreeBuilder.computeJaroWinkler(s1, s2);
        }
        if (s1 === s2) return 1.0;
        if (!s1 || !s2) return 0.0;
        return s1.toLowerCase() === s2.toLowerCase() ? 1.0 : 0.0;
    }

    /**
     * Checks if two strings differ ONLY by consonant gemination (letter doubling),
     * such as 'Mathew' vs 'Matthew', 'Chacko' vs 'Chako', 'Eliamma' vs 'Elliamma',
     * or 'Annamma' vs 'Anamma'.
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if words differ only by gemination
     *
     * @example
     * FamilyTree.isGeminationDifference('Mathew', 'Matthew')
     * // => true
     *
     * @example
     * FamilyTree.isGeminationDifference('Chinnu', 'Chinnan')
     * // => false
     */
    static isGeminationDifference(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;

        const degeminate = (s) => s.replace(/([a-z])\1+/g, '$1').replace(/ck/g, 'k');
        return degeminate(s1) === degeminate(s2);
    }

    /**
     * Checks whether a character is an English vowel (a, e, i, o, u) or semi-vowel (y, w).
     *
     * @param {string} ch - Character to check
     * @returns {boolean} True if character is a vowel or semi-vowel
     *
     * @example
     * FamilyTree.isVowelOrSemiVowel('a')
     * // => true
     *
     * @example
     * FamilyTree.isVowelOrSemiVowel('k')
     * // => false
     */
    static isVowelOrSemiVowel(ch) {
        return /^[aeiouyw]$/i.test(ch || '');
    }

    /**
     * Checks whether a candidate word extends another word by adding a single trailing vowel or semi-vowel.
     *
     * @param {string} s1 - First word
     * @param {string} s2 - Second word
     * @returns {boolean} True if one word is a strict prefix of the other with a trailing vowel/semi-vowel
     *
     * @example
     * FamilyTree._isTrailingVowelExtension('john', 'johny')
     * // => true
     *
     * @example
     * FamilyTree._isTrailingVowelExtension('ouseph', 'ousep')
     * // => false
     */
    static _isTrailingVowelExtension(s1, s2) {
        if (Math.abs(s1.length - s2.length) !== 1) return false;
        const shorter = s1.length < s2.length ? s1 : s2;
        const longer = s1.length < s2.length ? s2 : s1;
        if (!longer.startsWith(shorter)) return false;
        const extraChar = longer[longer.length - 1];
        return FamilyTree.isVowelOrSemiVowel(extraChar);
    }

    /**
     * Checks whether two words of identical length differ only by a single final character that is a vowel or semi-vowel.
     *
     * @param {string} s1 - First word
     * @param {string} s2 - Second word
     * @returns {boolean} True if words differ solely at the final character involving a vowel/semi-vowel
     *
     * @example
     * FamilyTree._isFinalVowelSubstitution('deepa', 'deepu')
     * // => true
     *
     * @example
     * FamilyTree._isFinalVowelSubstitution('deepa', 'deept')
     * // => false
     */
    static _isFinalVowelSubstitution(s1, s2) {
        if (s1.length !== s2.length || s1.length === 0) return false;
        if (s1.slice(0, -1) !== s2.slice(0, -1)) return false;
        const c1 = s1[s1.length - 1];
        const c2 = s2[s2.length - 1];
        return FamilyTree.isVowelOrSemiVowel(c1) || FamilyTree.isVowelOrSemiVowel(c2);
    }

    /**
     * Determines whether two words differ only by a word-ending vowel or semi-vowel.
     * Word-ending vowel or semi-vowel differences are meaningful distinctions (e.g. 'Deepa' vs 'Deepu',
     * 'John' vs 'Johny', 'Paul' vs 'Pauly', 'Anto' vs 'Antu', 'Rose' vs 'Rosa') and should be avoided
     * from spelling warnings.
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if the difference between w1 and w2 is at the word ending involving a vowel or semi-vowel
     *
     * @example
     *   FamilyTree.hasWordEndingVowelDifference('deepa', 'deepu')
     *   // => true ('a' vs 'u')
     *
     * @example
     *   FamilyTree.hasWordEndingVowelDifference('john', 'johny')
     *   // => true (appended 'y')
     */
    static hasWordEndingVowelDifference(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;

        return FamilyTree._isTrailingVowelExtension(s1, s2) ||
               FamilyTree._isFinalVowelSubstitution(s1, s2);
    }

    /**
     * Determines whether two words differ only by the dropping or addition of 'h'
     * (e.g. 'Ajes' vs 'Ajesh', 'Ouseph' vs 'Ousep', 'Joseph' vs 'Josep', 'Thomas' vs 'Tomas').
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if one word is formed by dropping a single 'h' from the other
     *
     * @example
     * FamilyTree.isDroppingHDifference('Ajes', 'Ajesh')
     * // => true
     *
     * @example
     * FamilyTree.isDroppingHDifference('Ouseph', 'Ousep')
     * // => true
     */
    static isDroppingHDifference(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;
        if (Math.abs(s1.length - s2.length) !== 1) return false;

        const shorter = s1.length < s2.length ? s1 : s2;
        const longer = s1.length < s2.length ? s2 : s1;

        for (let i = 0; i < longer.length; i++) {
            if (longer[i] === 'h') {
                const candidate = longer.slice(0, i) + longer.slice(i + 1);
                if (candidate === shorter) return true;
            }
        }
        return false;
    }

    /**
     * Determines whether two words differ only by a semi-vowel difference (i/y)
     * (e.g. 'Kochuthresia' vs 'Kochuthresya', 'Mariam' vs 'Mariyam').
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if difference is strictly an i/y semi-vowel substitution or glide
     *
     * @example
     * FamilyTree.isSemiVowelDifference('Kochuthresia', 'Kochuthresya')
     * // => true
     *
     * @example
     * FamilyTree.isSemiVowelDifference('Mariam', 'Mariyam')
     * // => true
     */
    static isSemiVowelDifference(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;

        // Substitution between 'i' and 'y' (e.g. Kochuthresia vs Kochuthresya)
        if (s1.length === s2.length && s1.replace(/y/g, 'i') === s2.replace(/y/g, 'i')) {
            return true;
        }

        // Glide 'y' adjacent to 'i' in transliterations (e.g. Mariam vs Mariyam: ia vs iya)
        if (s1.replace(/iya/g, 'ia') === s2.replace(/iya/g, 'ia')) {
            return true;
        }

        return false;
    }

    /**
     * Determines whether two words differ only by a diphthong difference (ie/e)
     * (e.g. 'Annie' vs 'Anne').
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if difference is strictly a diphthong variation (ie/e)
     *
     * @example
     * FamilyTree.isDiphthongDifference('Annie', 'Anne')
     * // => true
     *
     * @example
     * FamilyTree.isDiphthongDifference('Paul', 'Pauly')
     * // => false
     */
    static isDiphthongDifference(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;

        // Diphthong difference: 'ie' vs 'e' (e.g. Annie vs Anne)
        if (s1.replace(/ie/g, 'e') === s2.replace(/ie/g, 'e')) {
            return true;
        }

        return false;
    }

    /**
     * Determines whether two single-word tokens represent near-duplicate spelling variants.
     * Per domain rules, spelling warnings are triggered strictly by:
     *   1. Gemination differences (e.g. 'Annu' vs 'Anu', 'Mathew' vs 'Matthew', 'Chacko' vs 'Chako')
     *   2. Dropping or addition of 'h' (e.g. 'Ajes' vs 'Ajesh', 'Ouseph' vs 'Ousep', 'Thomas' vs 'Tomas')
     *   3. Semi-vowel differences (i/y) (e.g. 'Kochuthresia' vs 'Kochuthresya', 'Mariam' vs 'Mariyam')
     *   4. Diphthong differences (ie/e) (e.g. 'Annie' vs 'Anne')
     *
     * Consonant changes (e.g. 'Shibu' vs 'Shiju' [b/j], 'Franci' vs 'Francis' [s], 'Rehya' vs 'Rehva' [y/v])
     * and word-ending vowel changes (e.g. 'Deepa' vs 'Deepu') do NOT cause a warning.
     *
     * @param {string} w1 - First word
     * @param {string} w2 - Second word
     * @returns {boolean} True if words represent near-duplicate spellings warranting an audit warning
     *
     * @example
     * FamilyTree.isAlmostSameWord('Annu', 'Anu')
     * // => true
     *
     * @example
     * FamilyTree.isAlmostSameWord('Deepa', 'Deepu')
     * // => false
     */
    static isAlmostSameWord(w1, w2) {
        if (!w1 || !w2) return false;
        const s1 = w1.toLowerCase().trim();
        const s2 = w2.toLowerCase().trim();
        if (s1 === s2) return false;

        return FamilyTree.isGeminationDifference(s1, s2) ||
               FamilyTree.isDroppingHDifference(s1, s2) ||
               FamilyTree.isSemiVowelDifference(s1, s2) ||
               FamilyTree.isDiphthongDifference(s1, s2);
    }

    /**
     * Counts the number of near-match word differences between two equal-length word lists.
     * Returns -1 if any corresponding word pair fails both exact and near-match similarity.
     *
     * @param {string[]} wordsA - First word array
     * @param {string[]} wordsB - Second word array
     * @returns {number} Count of near-match differences, or -1 if incompatible
     *
     * @example
     * FamilyTree._countNearWordDifferences(['Ouseph', 'Varghese'], ['Ousep', 'Varghese']);
     * // => 1
     *
     * @example
     * FamilyTree._countNearWordDifferences(['John', 'Paul'], ['George', 'Ringo']);
     * // => -1
     */
    static _countNearWordDifferences(wordsA, wordsB) {
        let diffCount = 0;
        for (let i = 0; i < wordsA.length; i++) {
            const wA = wordsA[i], wB = wordsB[i];
            if (wA.toLowerCase() === wB.toLowerCase()) continue;
            if (FamilyTree.isAlmostSameWord(wA, wB)) {
                diffCount++;
            } else {
                return -1;
            }
        }
        return diffCount;
    }

    /**
     * Determines whether two person names are almost the same spelling (e.g. 'Ouseph' vs 'Ousep',
     * 'Kochu Thresia' vs 'Kochuthresia', 'Ouseph Varghese' vs 'Ousep Varghese').
     *
     * @param {string} nameA - First name
     * @param {string} nameB - Second name
     * @returns {boolean} True if names are near-duplicate spelling variants
     *
     * @example
     * FamilyTree.areAlmostSameNames('Ouseph', 'Ousep')
     * // => true
     *
     * @example
     * FamilyTree.areAlmostSameNames('Kochu Thresia', 'Kochuthresia')
     * // => true
     */
    static areAlmostSameNames(nameA, nameB) {
        const a = FamilyTree.cleanPersonName(nameA);
        const b = FamilyTree.cleanPersonName(nameB);
        if (!a || !b || a.toLowerCase() === b.toLowerCase()) return false;

        // Spacing variant: e.g. "Kochu Thresia" vs "Kochuthresia"
        if (a.replace(/\s+/g, '').toLowerCase() === b.replace(/\s+/g, '').toLowerCase()) {
            return true;
        }

        const wordsA = a.split(/\s+/), wordsB = b.split(/\s+/);
        if (wordsA.length !== wordsB.length) return false;

        return FamilyTree._countNearWordDifferences(wordsA, wordsB) === 1;
    }

    /**
     * Formats an audit warning message comparing a less-used spelling to a more common variant.
     *
     * @param {{canonicalDisplay: string, total: number}} rareGroup - Less-used (or peer) group
     * @param {{canonicalDisplay: string, total: number}} commonGroup - More common (or peer) group
     * @returns {string} Formatted audit warning text
     *
     * @example
     * FamilyTree._formatSpellingWarningText({ canonicalDisplay: 'Ousep', total: 1 }, { canonicalDisplay: 'Ouseph', total: 5 })
     * // => "Spelling 'Ousep' (used 1 time) is almost the same as 'Ouseph' (used 5 times)."
     *
     * @example
     * FamilyTree._formatSpellingWarningText({ canonicalDisplay: 'Annu', total: 2 }, { canonicalDisplay: 'Anu', total: 8 })
     * // => "Spelling 'Annu' (used 2 times) is almost the same as 'Anu' (used 8 times)."
     */
    static _formatSpellingWarningText(rareGroup, commonGroup) {
        const rareCount = `${rareGroup.total} ${rareGroup.total === 1 ? 'time' : 'times'}`;
        const commonCount = `${commonGroup.total} ${commonGroup.total === 1 ? 'time' : 'times'}`;
        return `Spelling '${rareGroup.canonicalDisplay}' (used ${rareCount}) is almost the same as '${commonGroup.canonicalDisplay}' (used ${commonCount}).`;
    }

    /**
     * Determines whether a person profile should be included in name spelling audits,
     * filtering out unknown placeholders, synthetic relative ghosts, and unnamed entries.
     *
     * @param {Object} p - Person profile
     * @returns {boolean} True if profile is eligible for spelling audit
     *
     * @example
     * FamilyTree._isEligibleForNameSpellingAudit({ name: 'Ouseph' })
     * // => true
     *
     * @example
     * FamilyTree._isEligibleForNameSpellingAudit({ name: 'George Son 1' })
     * // => false
     */
    static _isEligibleForNameSpellingAudit(p) {
        if (!p || !p.name) return false;
        if (p._isUnknown || p.name.startsWith('(')) return false;
        if (typeof FamilyTreeBuilder !== 'undefined' && typeof FamilyTreeBuilder._isRelativeName === 'function') {
            if (FamilyTreeBuilder._isRelativeName(p.name)) return false;
        } else if (/^(?:.+?\s+)?(?:Husband|Wife|Spouse|Partner|Son|Daughter|Boy|Girl|Brother|Sister|Father|Mother)(?:\s*\d+)?$/i.test(p.name.trim())) {
            return false;
        }
        return true;
    }

    /**
     * Resolves the most frequently occurring display capitalization/spelling in a name group.
     *
     * @param {Map<string, number>} displayCounts - Frequency map of display variants
     * @param {string} fallback - Default name if map is empty
     * @returns {string} Most common display name
     *
     * @example
     * FamilyTree._resolveCanonicalDisplayName(new Map([['Ouseph', 5], ['Ousep', 1]]), 'ouseph')
     * // => 'Ouseph'
     *
     * @example
     * FamilyTree._resolveCanonicalDisplayName(new Map(), 'mathew')
     * // => 'mathew'
     */
    static _resolveCanonicalDisplayName(displayCounts, fallback) {
        let maxCount = -1;
        let canonicalDisplay = fallback;
        for (const [disp, cnt] of displayCounts.entries()) {
            if (cnt > maxCount) {
                maxCount = cnt;
                canonicalDisplay = disp;
            }
        }
        return canonicalDisplay;
    }

    /**
     * Indexes an eligible person profile into normalized spelling name groups.
     *
     * @param {Person} p - Person profile to index
     * @param {Map<string, {displayCounts: Map<string, number>, total: number, people: Array<Person>}>} nameGroups - Target map
     *
     * @example
     * const groups = new Map();
     * FamilyTree._indexPersonInSpellingGroup({ name: 'Ouseph' }, groups);
     * // groups.has('ouseph') => true
     *
     * @example
     * const groups = new Map();
     * FamilyTree._indexPersonInSpellingGroup({ name: '(Unknown)' }, groups);
     * // groups.size => 0
     */
    static _indexPersonInSpellingGroup(p, nameGroups) {
        if (!FamilyTree._isEligibleForNameSpellingAudit(p)) return;
        const cleaned = FamilyTree.cleanPersonName(p.name);
        if (!cleaned) return;
        const normKey = cleaned.toLowerCase();
        if (!nameGroups.has(normKey)) {
            nameGroups.set(normKey, { displayCounts: new Map(), total: 0, people: [] });
        }
        const group = nameGroups.get(normKey);
        group.total++;
        group.people.push(p);
        group.displayCounts.set(cleaned, (group.displayCounts.get(cleaned) || 0) + 1);
    }

    /**
     * Groups eligible concrete profiles by normalized cleaned name, computing group frequency and canonical display name.
     *
     * Excludes unknowns, placeholder names in parentheses, and relative relation names (e.g. 'Mary Son 1').
     *
     * @param {Array<Person>} people - Profiles to group
     * @returns {Array<{normKey: string, canonicalDisplay: string, total: number, people: Array<Person>}>} Name groups
     *
     * @example
     * FamilyTree._groupProfilesByNormalizedName([{ name: 'Ouseph' }, { name: 'ouseph' }])
     * // => [{ normKey: 'ouseph', canonicalDisplay: 'Ouseph', total: 2, people: [...] }]
     *
     * @example
     * FamilyTree._groupProfilesByNormalizedName([{ name: '(Unknown)' }, { name: 'John Son 1' }])
     * // => []
     */
    static _groupProfilesByNormalizedName(people) {
        const nameGroups = new Map();
        for (const p of people) {
            FamilyTree._indexPersonInSpellingGroup(p, nameGroups);
        }
        return Array.from(nameGroups.entries(), ([normKey, data]) => ({
            normKey,
            canonicalDisplay: FamilyTree._resolveCanonicalDisplayName(data.displayCounts, normKey),
            total: data.total,
            people: data.people
        }));
    }

    /**
     * Records or updates spelling warning notices for all members of a target name group.
     *
     * @param {Map<string, Object>} warningsByPersonId - Map of person ID to warning descriptor
     * @param {Object} targetGroup - Group whose members receive the warning
     * @param {Object} referenceGroup - Comparison group whose spelling is contrasted
     * @param {boolean} [onlyIfMissing=false] - If true, only records warning if person doesn't already have one
     *
     * @example
     * const warnings = new Map();
     * FamilyTree._recordSpellingWarning(warnings, { canonicalDisplay: 'Ousep', total: 1, people: [{ id: 'p1' }] }, { canonicalDisplay: 'Ouseph', total: 5 }, false);
     * // warnings.get('p1').text => "Spelling 'Ousep' (used 1 time) is almost the same as 'Ouseph' (used 5 times)."
     *
     * @example
     * const warnings = new Map([['p1', { priority: 10 }]]);
     * FamilyTree._recordSpellingWarning(warnings, { people: [{ id: 'p1' }] }, { total: 3 }, false);
     * // warnings.get('p1').priority remains 10 (higher priority preserved)
     */
    static _recordSpellingWarning(warningsByPersonId, targetGroup, referenceGroup, onlyIfMissing = false) {
        const text = FamilyTree._formatSpellingWarningText(targetGroup, referenceGroup);
        const priority = referenceGroup.total;
        for (const p of targetGroup.people) {
            const existing = warningsByPersonId.get(p.id);
            if (onlyIfMissing) {
                if (!existing) {
                    warningsByPersonId.set(p.id, { p, text, priority });
                }
            } else if (!existing || priority > existing.priority) {
                warningsByPersonId.set(p.id, { p, text, priority });
            }
        }
    }

    /**
     * Compares pairs of distinct name groups for near-duplicate spellings, returning prioritized warnings per person.
     *
     * @param {Array<Object>} groups - Name groups
     * @returns {Map<string, {p: Person, text: string, priority: number}>} Map of person ID to warning descriptor
     *
     * @example
     * const g1 = { canonicalDisplay: 'Ouseph', total: 5, people: [{ id: 'p1' }] };
     * const g2 = { canonicalDisplay: 'Ousep', total: 1, people: [{ id: 'p2' }] };
     * FamilyTree._compareSpellingGroups([g1, g2]);
     * // => Map containing warning for 'p2' referencing 'Ouseph'
     *
     * @example
     * const g1 = { canonicalDisplay: 'George', total: 3, people: [{ id: 'p1' }] };
     * const g2 = { canonicalDisplay: 'Mathew', total: 4, people: [{ id: 'p2' }] };
     * FamilyTree._compareSpellingGroups([g1, g2]);
     * // => empty Map (distinct names)
     */
    /**
     * Compares a pair of spelling groups and records near-duplicate name warnings for the less frequent variant.
     *
     * @private
     * @param {Object} gA - First spelling group
     * @param {Object} gB - Second spelling group
     * @param {Map<string, Array<Object>>} warningsByPersonId - Accumulated warning map
     *
     * @example
     * const map = new Map();
     * FamilyTree._evaluateSpellingPair({ canonicalDisplay: 'Ousep', total: 1, people: [] }, { canonicalDisplay: 'Ouseph', total: 5, people: [] }, map);
     * // => map populated with warning
     *
     * @example
     * const map = new Map();
     * FamilyTree._evaluateSpellingPair({ canonicalDisplay: 'John', total: 2, people: [] }, { canonicalDisplay: 'Mary', total: 2, people: [] }, map);
     * // => map unmodified (distinct names)
     */
    static _evaluateSpellingPair(gA, gB, warningsByPersonId) {
        if (!FamilyTree.areAlmostSameNames(gA.canonicalDisplay, gB.canonicalDisplay)) return;
        if (gA.total < gB.total) {
            FamilyTree._recordSpellingWarning(warningsByPersonId, gA, gB, false);
        } else if (gB.total < gA.total) {
            FamilyTree._recordSpellingWarning(warningsByPersonId, gB, gA, false);
        } else {
            FamilyTree._recordSpellingWarning(warningsByPersonId, gA, gB, true);
            FamilyTree._recordSpellingWarning(warningsByPersonId, gB, gA, true);
        }
    }

    /**
     * Compares all pairs of phonetic spelling groups to detect name spelling anomalies and discrepancies.
     *
     * @param {Array<Object>} groups - Array of spelling groups with persons and name variants
     * @returns {Map<string, Object>} Map from person ID to detected spelling warning details
     *
     * @example
     * const warnings = FamilyTree._compareSpellingGroups([]);
     * // => warnings.size === 0
     *
     * @example
     * const groupA = { norm: 'joseph', count: 5, persons: [{ id: 'p1', name: 'Joseph' }] };
     * const groupB = { norm: 'josef', count: 1, persons: [{ id: 'p2', name: 'Josef' }] };
     * const warnings = FamilyTree._compareSpellingGroups([groupA, groupB]);
     * // => warnings.has('p2') === true
     */
    static _compareSpellingGroups(groups) {
        const warningsByPersonId = new Map();
        for (let i = 0; i < groups.length; i++) {
            for (let j = i + 1; j < groups.length; j++) {
                FamilyTree._evaluateSpellingPair(groups[i], groups[j], warningsByPersonId);
            }
        }
        return warningsByPersonId;
    }

    /**
     * Audits near-duplicate name spellings across the entire tree, flagging the less-common variant.
     * Flags less-used spellings as the cause of warning (e.g. 'Ousep' used 1 time vs 'Ouseph' used 5 times).
     *
     * @param {FamilyTree} tree - Tree to audit
     * @param {Array<Object>} issues - Inconsistency issue sink
     *
     * @example
     * const issues = [];
     * FamilyTree._auditNameSpellings({ all: [{ id: 'p1', name: 'Ouseph' }, { id: 'p2', name: 'Ousep' }] }, issues);
     * // issues has 1 entry with category 'spelling'
     *
     * @example
     * const issues = [];
     * FamilyTree._auditNameSpellings({ all: [{ id: 'p1', name: 'George' }] }, issues);
     * // issues remains empty
     */
    static _auditNameSpellings(tree, issues) {
        if (!tree || !tree.all) return;

        const groups = FamilyTree._groupProfilesByNormalizedName(tree.all);
        if (groups.length < 2) return;

        const warningsByPersonId = FamilyTree._compareSpellingGroups(groups);
        for (const { p, text } of warningsByPersonId.values()) {
            issues.push({
                p,
                type: 'warning',
                category: 'spelling',
                text
            });
        }
    }

    /**
     * Traverses graph neighbors from a starting node to collect all reachable connected node IDs.
     *
     * @param {string} startId - Initial person node ID
     * @param {Set<string>} [visited] - Optional global visited set to avoid re-visiting
     * @returns {Set<string>} Set of connected person node IDs
     *
     * @example
     * tree._collectConnectedComponent('p1')
     * // => Set {'p1', 'p2', 'p3'}
     *
     * @example
     * const visited = new Set(['p1']);
     * tree._collectConnectedComponent('p1', visited)
     * // => Set {'p1'}
     */
    _collectConnectedComponent(startId, visited = new Set()) {
        const component = new Set([startId]);
        const queue = [startId];
        let qIdx = 0;
        visited.add(startId);

        while (qIdx < queue.length) {
            const id = queue[qIdx++];
            const p = this.get(id);
            if (!p) continue;
            const neighbors = [p.momId, p.fatherId, ...p.partners, ...p.children].filter(Boolean);
            for (const n of neighbors) {
                if (!visited.has(n)) {
                    visited.add(n);
                    component.add(n);
                    queue.push(n);
                }
            }
        }
        return component;
    }

    /**
     * Identifies the oldest non-ghost person profile within a set of node IDs.
     * Prioritizes nodes with an explicit birth year (minimum YOB); if no member has a birth year,
     * falls back to the first non-ghost member in the component.
     *
     * @param {Set<string>} componentIds - Set of node IDs in a connected component
     * @returns {Person|null} Oldest Person entity, or null if only ghosts
     *
     * @example
     * // Component with members: P1 (yob 1950), P2 (yob 1920), P3 (no yob)
     * tree._findOldestInComponent(new Set(['P1', 'P2', 'P3']))
     * // => P2
     *
     * @example
     * // Component with members without birth years: P1, P2
     * tree._findOldestInComponent(new Set(['P1', 'P2']))
     * // => P1
     */
    _findOldestInComponent(componentIds) {
        let oldest = null;
        let minYear = Infinity;

        for (const id of componentIds) {
            const p = this.get(id);
            if (!p || p.isGhost) continue;

            if (p.yob && p.yob < minYear) {
                minYear = p.yob;
                oldest = p;
            } else if (!oldest) {
                oldest = p;
            }
        }
        return oldest;
    }

    /**
     * Identifies all disconnected / disjoint subtrees in the graph outside
     * the primary tree connected to `rootId`.
     *
     * Performs breadth-first traversal from rootId to determine reachable nodes,
     * then clusters remaining unvisited nodes into disjoint subtrees, determining
     * each component's oldest member and size.
     *
     * @returns {Array<{root: Person, size: number}>} Disjoint roots sorted descending by component size
     *
     * @example
     * const subtrees = tree.findDisjointSubtrees();
     * // => [{ root: Person[John, 1850], size: 14 }, ...]
     *
     * @example
     * const singleTree = new FamilyTree();
     * singleTree.findDisjointSubtrees();
     * // => []
     */
    findDisjointSubtrees() {
        if (!this.root) return [];
        const roots = [];
        const visited = new Set();
        this._collectConnectedComponent(this.rootId, visited);

        for (const id of Object.keys(this.nodes)) {
            if (visited.has(id)) continue;
            const component = this._collectConnectedComponent(id, visited);
            const oldest = this._findOldestInComponent(component);
            if (oldest) {
                roots.push({ root: oldest, size: component.size });
            }
        }
        roots.sort((a, b) => b.size - a.size);
        return roots;
    }

    /**
     * Extracts duplicate spreadsheet source row references for a single person profile,
     * grouping by spreadsheet source ID and identifying sheets with multiple references.
     *
     * @param {Person} p - Profile to inspect
     * @returns {Array<Object>} List of duplicate source references
     *
     * @example
     * FamilyTree._findDuplicatePersonSourceRefs({ _allSourceRefs: [{ sheetId: 's1' }, { sheetId: 's1' }] })
     * // => [{ sheetId: 's1' }, { sheetId: 's1' }]
     *
     * @example
     * FamilyTree._findDuplicatePersonSourceRefs({ _allSourceRefs: [{ sheetId: 's1' }, { sheetId: 's2' }] })
     * // => []
     */
    static _findDuplicatePersonSourceRefs(p) {
        if (!p || p.isGhost || !p._allSourceRefs) return [];
        const sheetGroups = {};
        for (const ref of p._allSourceRefs) {
            if (!sheetGroups[ref.sheetId]) sheetGroups[ref.sheetId] = [];
            sheetGroups[ref.sheetId].push(ref);
        }
        const duplicatedRefs = [];
        for (const refs of Object.values(sheetGroups)) {
            if (refs.length > 1) duplicatedRefs.push(...refs);
        }
        return duplicatedRefs;
    }

    /**
     * Audits whether individual profiles appear in multiple duplicate rows on the same spreadsheet.
     *
     * @param {FamilyTree} tree - Target tree
     * @returns {Array<{p: Person, duplicatedRefs: Array<Object>}>} Duplicated source reference groups
     *
     * @example
     * const dupes = FamilyTree._auditDuplicateSourceRefs(treeWithDuplicates);
     * // => [{ p: Person[John], duplicatedRefs: [...] }]
     *
     * @example
     * const dupes = FamilyTree._auditDuplicateSourceRefs(cleanTree);
     * // => []
     */
    static _auditDuplicateSourceRefs(tree) {
        const dupes = [];
        for (const p of tree.all || []) {
            const duplicatedRefs = FamilyTree._findDuplicatePersonSourceRefs(p);
            if (duplicatedRefs.length > 0) {
                dupes.push({ p, duplicatedRefs });
            }
        }
        return dupes;
    }

    /**
     * Generates a temporary flattened visual layout of the tree from its root for audit verification.
     * 
     * @param {FamilyTree} tree - Target tree instance
     * @returns {Object|null} Flattened layout with nodes array, or null if layout cannot be generated
     *
     * @example
     * const layout = FamilyTree._generateAuditLayout(tree);
     * // => { nodes: [...], bounds: {...} }
     *
     * @example
     * const emptyLayout = FamilyTree._generateAuditLayout({ rootId: null });
     * // => null
     */
    static _generateAuditLayout(tree) {
        if (!tree.rootId || typeof layoutSubtree !== 'function' || typeof flattenTreeLayout !== 'function') {
            return null;
        }
        try {
            const rootNode = tree.get(tree.rootId);
            if (!rootNode) return null;

            const layout = layoutSubtree(rootNode, tree, {
                collapsedNodes: new Set(),
                visibleNodes: tree.getVisibleNodes(new Set()),
                rootNodeYob: rootNode.bestYob || 1900,
                ppy: 10,
                siblingGap: 24
            }, new Set());

            return layout ? flattenTreeLayout(layout) : null;
        } catch (e) {
            return null;
        }
    }

    /**
     * Inspects flattened visual layout nodes to identify and record any profiles rendered more than once.
     * 
     * @param {Array<Object>} flatNodes - Flattened layout node records
     * @param {Array<Object>} inconsistencies - Accumulated audit issues list
     *
     * @example
     * const issues = [];
     * FamilyTree._collectDuplicateRenderedNodes([{ person: { id: 'p1', name: 'John' } }, { person: { id: 'p1', name: 'John' } }], issues);
     * // issues has 1 entry with category 'duplicate_rendered_node'
     *
     * @example
     * const issues = [];
     * FamilyTree._collectDuplicateRenderedNodes([{ person: { id: 'p1', name: 'John' } }], issues);
     * // issues remains empty
     */
    static _collectDuplicateRenderedNodes(flatNodes, inconsistencies) {
        const seenNodeIds = new Map();
        (flatNodes || []).forEach(n => {
            const p = n.person;
            if (!p || p.isGhost) return;
            if (seenNodeIds.has(p.id)) {
                inconsistencies.push({
                    p,
                    type: 'error',
                    category: 'duplicate_rendered_node',
                    text: `Node '${p.name}' (${p.id}) is rendered multiple times in the family tree layout.`
                });
            } else {
                seenNodeIds.set(p.id, true);
            }
        });
    }

    /**
     * Audits visual tree layout for structural invariants (e.g. guaranteeing no node card is duplicated in rendering).
     *
     * @param {FamilyTree} tree - Target tree
     * @param {Array<Object>} inconsistencies - Accumulated inconsistency issues
     *
     * @example
     * const issues = [];
     * FamilyTree._auditLayoutInvariants(validTree, issues);
     * // issues remains empty
     *
     * @example
     * const issues = [];
     * FamilyTree._auditLayoutInvariants(treeWithDupes, issues);
     * // issues contains duplicate_rendered_node warning/error
     */
    static _auditLayoutInvariants(tree, inconsistencies) {
        const flat = FamilyTree._generateAuditLayout(tree);
        if (flat) {
            FamilyTree._collectDuplicateRenderedNodes(flat.nodes, inconsistencies);
        }
    }

    /**
     * Encapsulated business logic to perform full graph integrity audit.
     *
     * Checks:
     * - Person chronological and biological inconsistencies.
     * - Duplicate source spreadsheet row references.
     * - Near-duplicate name spellings across distinct branches.
     * - Disjoint subtrees unreachable from root.
     * - Visual layout rendering invariants (no duplicated node cards).
     *
     * @returns {{inconsistencies: Array<Object>, dupes: Array<Object>, subtrees: Array<Object>}} Audit results
     *
     * @example
     * const { inconsistencies, dupes, subtrees } = tree.audit();
     * // returns structured report of all detected issues
     *
     * @example
     * const report = emptyTree.audit();
     * // => { inconsistencies: [], dupes: [], subtrees: [] }
     */
    audit() {
        const inconsistencies = [];
        const dupes = FamilyTree._auditDuplicateSourceRefs(this);
        this.all.forEach(p => inconsistencies.push(...FamilyTree.auditPerson(p, this)));
        FamilyTree._auditNameSpellings(this, inconsistencies);
        const subtrees = this.findDisjointSubtrees();
        FamilyTree._auditLayoutInvariants(this, inconsistencies);
        return { inconsistencies, dupes, subtrees };
    }
}


// ============================================================================
// MODULE 4: BUILDER LOGIC (Tree Construction)

/**
 * Validates genealogical graph invariants and detects anomalies, cycles, and chronological violations.
 *
 * @example
 * const auditor = new InvariantAuditor();
 * const report = auditor.audit(tree);
 * // report.inconsistencies => Array of { p, type: 'error'|'warning', text }
 *
 * @example
 * const auditor = new InvariantAuditor();
 * const report = auditor.audit(emptyTree);
 * // report.subtrees => []
 */
class InvariantAuditor {
    /**
     * Constructs a new InvariantAuditor instance.
     *
     * @example
     * const auditor = new InvariantAuditor();
     *
     * @example
     * const isInstance = new InvariantAuditor() instanceof InvariantAuditor;
     * // => true
     */
    constructor() {}

    /**
     * Performs comprehensive graph integrity analysis.
     *
     * @param {FamilyTree} tree - Tree to analyze
     * @returns {{ inconsistencies: Array<Object>, dupes: Array<Object>, subtrees: Array<Object> }}
     *
     * @example
     * const auditor = new InvariantAuditor();
     * const report = auditor.audit(tree);
     * // => { inconsistencies: [...], dupes: [...], subtrees: [...] }
     *
     * @example
     * const auditor = new InvariantAuditor();
     * const report = auditor.audit(emptyTree);
     * // => { inconsistencies: [], dupes: [], subtrees: [] }
     */
    audit(tree) {
        return tree.audit();
    }
}

/**
 * Declarative orchestrator executing the 5-phase genealogical construction pipeline.
 *
 * @example
 * const pipeline = new FamilyTreePipeline(rawRows, sheetNames);
 * const tree = pipeline.execute();
 *
 * @example
 * const pipeline = new FamilyTreePipeline([]);
 * const tree = pipeline.execute();
 * // => empty FamilyTree
 */
class FamilyTreePipeline {
    /**
     * Constructs a FamilyTreePipeline with raw row datasets and sheet mappings.
     *
     * @param {Array<Object>} rawRows - Array of raw row objects from input sheets
     * @param {Object} [sheetNames={}] - Dictionary mapping sheet ID to sheet display name
     *
     * @example
     * const pipeline = new FamilyTreePipeline([{ Name: 'John', Sex: 'M' }]);
     *
     * @example
     * const pipeline = new FamilyTreePipeline([], { '1': 'Sheet1' });
     */
    constructor(rawRows, sheetNames = {}) {
        this.builder = new FamilyTreeBuilder(rawRows, sheetNames);
    }

    /**
     * Executes the tree construction pipeline and returns the assembled FamilyTree.
     *
     * @returns {FamilyTree} Built and validated family tree
     *
     * @example
     * const pipeline = new FamilyTreePipeline(rawRows);
     * const tree = pipeline.execute();
     *
     * @example
     * const tree = new FamilyTreePipeline([]).execute();
     * // => FamilyTree with 0 nodes
     */
    execute() {
        return this.builder.build();
    }
}

// ============================================================================

/**
 * ============================================================================
 * GENEALOGICAL INFERENCE RULES & ARTIFICIAL AGE RESTRICTIONS
 * ============================================================================
 * All artificial age restrictions, chronological assumptions, biological bounds,
 * and fallback heuristics implemented across the application are documented here
 * in a single centralized place:
 * 
 * 1. MOTHER & FIRST CHILD AGE GAP (Maternal Generation Step):
 *    - A mother is assumed to be exactly 24 years older than her first child
 *      (first-born child by earliest known/inferred birth year):
 *        * mother.yob = firstChild.yob - 24 (when mother's birth year is unknown)
 *        * firstChild.yob = mother.yob + 24 (when child's birth year is unknown)
 *    - This applies equally to real profiles and autogenerated ghost mothers.
 * 
 * 2. HUSBAND & WIFE AGE GAP (Spousal Generation Step):
 *    - When partner genders are known or deduced (husband is assumed to be 2 years older than wife):
 *        * husband.yob = wife.yob - 2
 *        * wife.yob = husband.yob + 2
 *    - When gender cannot be deduced and one partner is a ghost:
 *        * Both partners are deduced to be of the SAME age:
 *            ghostPartner.yob = partner.yob
 * 
 * 3. FATHER & FIRST CHILD AGE GAP (Paternal Fallback Step):
 *    - When a father's birth year is inferred directly from a child without a
 *      known mother profile:
 *        * father.yob = firstChild.yob - 26 (24 yrs maternal gap + 2 yrs spousal gap)
 *        * firstChild.yob = father.yob + 26 (when father is known, child unknown)
 * 
 * 4. SIBLING AGE GAP (Consecutive Siblings):
 *    - Consecutive siblings in a family unit are assumed to have a 2-year age gap:
 *        * Forward pass (older to younger): child[i + 1].yob = child[i].yob + 2
 *        * Backward pass (younger to older): child[i - 1].yob = child[i].yob - 2
 * 
 * 5. BIOLOGICAL FEASIBILITY CONSTRAINTS (Candidate Validation & Filtering):
 *    - Parent-Child Age Gaps (_isValidParentCandidate):
 *        * Minimum parent age at childbirth: 15 years (child.yob - parent.yob >= 15)
 *        * Maximum maternal age at childbirth: 50 years (child.yob - mother.yob <= 50)
 *        * Maximum paternal age at childbirth: 60 years (child.yob - father.yob <= 60)
 *    - Spousal Age Difference Bounds (_isValidSpouseCandidate):
 *        * Husband vs Wife: Husband can be between 0 yrs younger and 20 yrs older
 *          (-20 <= husband.yob - wife.yob <= 0)
 *        * Wife vs Husband: Wife can be between 0 yrs older and 20 yrs younger
 *          (0 <= wife.yob - husband.yob <= 20)
 *        * Undetermined genders: Age difference must not exceed 8 years (|diff| <= 8)
 *    - Incestuous & Biological Prohibitions:
 *        * Direct parent-child marriages are strictly prohibited.
 *        * First cousin marriages (sharing common grandparents) are strictly prohibited.
 * 
 * 6. FREE-FORM & RAW AGE DEDUCTIONS (_deduceYearsFromAge, processFreeForm):
 *    - "Died young", "infant", "baby" without explicit year: Assumed age = 1 year.
 *    - Explicit age: yob = currentYear - age.
 *    - Years after death: death = currentYear - yearsAfterDeath, yob = death - age.
 * ============================================================================
 */
/**
 * Builder class for ingesting genealogical datasets, resolving ambiguous relationships,
 * inferring chronological milestones (YOB/YOD), and producing fully interconnected FamilyTree instances.
 *
 * @example
 * const builder = new FamilyTreeBuilder(rawRows, sheetNames);
 * const tree = builder.build();
 *
 * @example
 * const defaultProfile = FamilyTreeBuilder.DemographicProfile.DEFAULT;
 * const builder = new FamilyTreeBuilder([]);
 */
class FamilyTreeBuilder {
    /**
     * Declarative ontology of religious and vocational honorifics.
     * Encapsulates honorific prefix matching, canonical gender, celibacy vows, and career labels.
     */
    static TITLE_ONTOLOGY = Object.freeze([
        { prefix: /^(?:sr\.?|sister)\b/i, gender: 'F', isCelibate: true, career: 'Nun', isNun: true },
        { prefix: /^(?:fr\.?|father|rev\.?)\b/i, gender: 'M', isCelibate: true, career: 'Priest', isPriest: true },
        { prefix: /^(?:br\.?|brother)\b/i, gender: 'M', isCelibate: true, career: 'Brother', isBrother: true },
    ]);

    /**
     * Encapsulates generational and biological demographic assumptions for a genealogical corpus.
     * Supports configurable demographic profiles (e.g. historical vs modern).
     */
    static DemographicProfile = class DemographicProfile {
        /**
         * Constructs a new DemographicProfile configuration instance.
         *
         * @param {Object} [config={}] - Custom configuration overrides
         *
         * @example
         * const profile = new FamilyTreeBuilder.DemographicProfile({ generationalGaps: { MATERNAL_FIRST_CHILD: 22 } });
         *
         * @example
         * const defaultProfile = new FamilyTreeBuilder.DemographicProfile();
         */
        constructor(config = {}) {
            this.generationalGaps = Object.freeze({
                ...(FamilyTreeBuilder.GENERATIONAL_GAPS || {}),
                ...(config.generationalGaps || config.GENERATIONAL_GAPS || {})
            });
            this.biologicalBounds = Object.freeze({
                ...(FamilyTreeBuilder.BIOLOGICAL_BOUNDS || {}),
                ...(config.biologicalBounds || config.BIOLOGICAL_BOUNDS || {})
            });
        }

        static DEFAULT = null;
    };

    /**
     * Matches a name or nickname against the declarative title ontology.
     * 
     * @param {string} name - Primary name
     * @param {string} [nick=''] - Nickname
     * @returns {Object|null} Matching ontology record or null
     *
     * @example
     * FamilyTreeBuilder.matchTitleOntology('Sr. Philomena')
     * // => { prefix: ..., gender: 'F', isCelibate: true, career: 'Nun', isNun: true }
     *
     * @example
     * FamilyTreeBuilder.matchTitleOntology('John', 'Father')
     * // => { prefix: ..., gender: 'M', isCelibate: true, career: 'Priest', isPriest: true }
     */
    static matchTitleOntology(name, nick = '') {
        const lowerName = (name || '').trim();
        const lowerNick = (nick || '').trim();
        for (const entry of FamilyTreeBuilder.TITLE_ONTOLOGY) {
            if (entry.prefix.test(lowerName) || (lowerNick && entry.prefix.test(lowerNick))) {
                return entry;
            }
        }
        return null;
    }

    static GENERATIONAL_GAPS = (() => {
        const MATERNAL_FIRST_CHILD = 24;   // Mother age at first-born child birth
        const SPOUSAL_GENDER_OFFSET = 2;   // Husband is assumed this many years older than his wife
        return Object.freeze({
            MATERNAL_FIRST_CHILD,
            SPOUSAL_GENDER_OFFSET,
            // Derived, NOT an independent knob. A father is one spousal offset older than the
            // mother, so his age at the first birth is the maternal gap plus that offset.
            // Spelling the identity out keeps the two ends of the deduction consistent: the
            // builder reaches a father either directly (child - PATERNAL_FIRST_CHILD) or via
            // his wife (child - MATERNAL_FIRST_CHILD - SPOUSAL_GENDER_OFFSET), and those two
            // paths must agree or the same person gets two different birth years.
            PATERNAL_FIRST_CHILD: MATERNAL_FIRST_CHILD + SPOUSAL_GENDER_OFFSET,
            CONSECUTIVE_SIBLING: 2,         // Assumed gap between adjacent birth-order siblings
            DEFAULT_FIRST_MARRIAGE_AGE_FEMALE: 18, // Default age of a woman at her first marriage
            SECOND_WIFE_MARRIAGE_AGE: 18,   // Subsequent spouse married after previous wife's last child (alias for DEFAULT_FIRST_MARRIAGE_AGE_FEMALE)
            MIN_PARENTAL_AGE: 14,           // Absolute physical minimum parent-child age difference
            MAX_ROW_NEIGHBOR_DISTANCE: 5,   // Maximum spreadsheet row distance for namesake fallback
            ADJACENT_ROW_MAX_DISTANCE: 3,   // Maximum spreadsheet row distance for adjacent co-spouses / immediate family grouping
            PARENT_RESOLUTION_MARGIN_YEARS: 5, // Minimum generational-gap fitness advantage (in years) to lock in a parent candidate
        });
    })();

    static BIOLOGICAL_BOUNDS = Object.freeze({
        MAX_MOTHER_CHILDBIRTH_AGE: 55,  // Upper bound for maternal conception
        MAX_FATHER_CHILDBIRTH_AGE: 80,  // Upper bound for paternal conception
        MOTHER_OLDER_CHILD_THRESHOLD: 50, // Threshold above which maternal age requires valid first-child corroboration
        MAX_SPOUSE_AGE_DIFF: 30,        // Max acceptable age difference between partners (subsequent wives/remarriage)
        MAX_UNKNOWN_GENDER_DIFF: 8,     // Max acceptable age gap when partner genders are unknown
        MAX_HUMAN_LIFESPAN: 110,        // Upper bound for plausible lifespan
        DEFAULT_INFANT_DEATH_AGE: 1,    // Assumed age for "died young", "infant", "baby"
    });

    /**
     * Social conventions, NOT laws of nature. Unlike BIOLOGICAL_BOUNDS, every value here is a
     * tunable prior fitted to the observed corpus: widening one admits more speculative links,
     * narrowing one discards real ones. Each entry records the observations that bound it, so a
     * future retune can tell "this breaks a documented family" apart from "this breaks a guess".
     */
    static HEURISTIC_PRIORS = Object.freeze({
        // Max age difference between a husband and his FIRST wife (subsequent wives fall back to
        // BIOLOGICAL_BOUNDS.MAX_SPOUSE_AGE_DIFF, since remarriage lifts the convention).
        //
        // Sweeping this knob against the corpus puts the feasible window at [12, 14]:
        //   <= 11  rejects a documented couple: George b.1928 / Sicily b.1940 (Ollur sheet, 12yr gap)
        //   >= 15  accepts a declared 15yr pairing the corpus expects to stay unlinked (test 90B)
        // 13 is the midpoint, deliberately off both bounding observations, so the constant
        // describes the convention rather than restating one family's arithmetic.
        MAX_FIRST_WIFE_AGE_DIFF: 13,
    });

    static RELATIONSHIP_TOKENS = Object.freeze({
        MALE_INDICATORS: Object.freeze(['son', 'boy', 'father', 'dad', 'papa', 'grandpa', 'husband', 'brother', 'uncle', 'nephew', 'grandson']),
        FEMALE_INDICATORS: Object.freeze(['daughter', 'girl', 'mother', 'mom', 'mama', 'grandma', 'wife', 'sister', 'aunt', 'niece', 'granddaughter']),
        SIBLING_KEYWORDS: Object.freeze(['brother', 'sister', 'sibling', 'sib']),
        PARENT_KEYWORDS: Object.freeze(['mother', 'mom', 'father', 'dad']),
        SPOUSE_KEYWORDS: Object.freeze(['spouse', 'partner', 'husband', 'wife']),
        CHILD_TOKENS: Object.freeze(['son', 'boy', 'daughter', 'girl']),
    });

    /**
     * Resolves the primary sheet row index for a person node, inspecting _sheetRow, sheetRow,
     * or finding the minimum row index in _sheetRows if multi-sheet.
     * 
     * @param {Object} n - Domain node
     * @param {number|null} [defaultValue=null] - Value returned when row cannot be resolved
     * @returns {number|null} Minimum row index or defaultValue
     * 
     * @example
     * FamilyTreeBuilder.getNodeSheetRow({ _sheetRow: 14 })
     * // => 14
     *
     * @example
     * FamilyTreeBuilder.getNodeSheetRow({ _sheetRows: { s1: 20, s2: 15 } })
     * // => 15
     */
    static getNodeSheetRow(n, defaultValue = null) {
        if (!n) return defaultValue;
        if (n._sheetRows && Object.keys(n._sheetRows).length > 0) {
            return Math.min(...Object.values(n._sheetRows));
        }
        if (n._sheetRow !== undefined && n._sheetRow !== null) return n._sheetRow;
        if (n.sheetRow !== undefined && n.sheetRow !== null) return n.sheetRow;
        return defaultValue;
    }

    static CROSS_SHEET_DISTANCE = 9999;
    static MAX_ROW_SENTINEL = 99999;

    /**
     * Computes a normalized continuous spatial proximity kernel between two sheet rows or a distance.
     * Evaluates to 1.0 for distance 0, decaying exponentially as distance grows.
     * Returns 0 for cross-sheet comparisons (dist >= CROSS_SHEET_DISTANCE).
     *
     * @param {number} dist - Row distance
     * @param {number} [scale=5] - Characteristic decay scale in rows
     * @returns {number} Proximity score in [0, 1]
     *
     * @example
     * FamilyTreeBuilder.computeRowProximity(0)
     * // => 1.0
     *
     * @example
     * FamilyTreeBuilder.computeRowProximity(9999)
     * // => 0
     */
    static computeRowProximity(dist, scale = 5) {
        if (dist === null || dist === undefined || dist >= FamilyTreeBuilder.CROSS_SHEET_DISTANCE || dist < 0) {
            return 0;
        }
        return Math.exp(-dist / scale);
    }

    /**
     * Evaluates generational gap fitness between a child and a parent.
     * Computes a continuous score reflecting demographic plausibility around an ideal gap (default: 30 yrs),
     * penalizing values outside biological bounds [minAge, maxAge].
     *
     * @param {number} childYob - Child birth year
     * @param {number} parentYob - Parent birth year
     * @param {number} [idealGap=30] - Historically expected mean parental gap
     * @param {number} [minAge=14] - Minimum biological parental age
     * @param {number} [maxAge=60] - Maximum biological parental age
     * @returns {number} Plausibility score (higher is better, 0 if invalid or out of bounds)
     *
     * @example
     * FamilyTreeBuilder.computeGenerationalFitness(1950, 1920)
     * // => 200 (exact ideal 30yr gap)
     *
     * @example
     * FamilyTreeBuilder.computeGenerationalFitness(1950, 1945)
     * // => 0 (5yr gap < 14)
     */
    static computeGenerationalFitness(childYob, parentYob, idealGap = 30, minAge = 14, maxAge = 60) {
        if (!childYob || !parentYob) return 0;
        const gap = childYob - parentYob;
        if (gap < minAge || gap > maxAge) return 0;
        return 200 - Math.abs(gap - idealGap);
    }

    /**
     * Calculates the minimum row distance between two nodes across shared spreadsheet sources,
     * falling back to single-sheet row accounting if multi-sheet metadata is absent.
     *
     * @param {Object} a - First person node
     * @param {Object} b - Second person node
     * @returns {number} Minimum absolute row difference, or CROSS_SHEET_DISTANCE if not on the same sheet
     *
     * @example
     * FamilyTreeBuilder._getMinRowDistance({ _sheetRow: 10 }, { _sheetRow: 14 })
     * // => 4
     *
     * @example
     * FamilyTreeBuilder._getMinRowDistance(null, { _sheetRow: 14 })
     * // => 9999
     */
    static _getMinRowDistance(a, b) {
        if (!a || !b) return FamilyTreeBuilder.CROSS_SHEET_DISTANCE;
        let min = FamilyTreeBuilder.CROSS_SHEET_DISTANCE;
        if (a._sourceIds && b._sourceIds && a._sheetRows && b._sheetRows) {
            for (const sid of a._sourceIds) {
                if (b._sourceIds.has(sid)) {
                    const sidKey = sid || 'default';
                    const rA = a._sheetRows[sidKey] ?? a._sheetRows[sid];
                    const rB = b._sheetRows[sidKey] ?? b._sheetRows[sid];
                    if (rA !== undefined && rB !== undefined) min = Math.min(min, Math.abs(rA - rB));
                }
            }
        }
        if (min < FamilyTreeBuilder.CROSS_SHEET_DISTANCE) return min;
        if (FamilyTreeBuilder.sharesSheet(a, b)) {
            const rA = FamilyTreeBuilder.getNodeSheetRow(a, null);
            const rB = FamilyTreeBuilder.getNodeSheetRow(b, null);
            if (rA !== null && rA !== undefined && rA < FamilyTreeBuilder.MAX_ROW_SENTINEL &&
                rB !== null && rB !== undefined && rB < FamilyTreeBuilder.MAX_ROW_SENTINEL) {
                return Math.abs(rA - rB);
            }
        }
        return FamilyTreeBuilder.CROSS_SHEET_DISTANCE;
    }

    /**
     * Normalizes names by folding consecutive repeated vowels to a single instance.
     * This aids in matching phonetic/transliteration spelling variations (e.g. Kunjaagasthi vs Kunjagasthi).
     * 
     * @param {string} s - Input name or string
     * @returns {string} Lowercased, trimmed string with duplicate consecutive vowels collapsed
     * 
     * @example
     * FamilyTreeBuilder.foldVowels("Kunjaagasthi")
     * // => "kunjagasthi"
     * 
     * @example
     * FamilyTreeBuilder.foldVowels("Ouseph")
     * // => "ouseph"
     */
    static foldVowels(s) {
        if (!s) return '';
        return s.toLowerCase().trim().replace(/([aeiou])\1+/g, '$1');
    }

    /**
     * Normalizes names by folding consecutive repeated vowels and aspirated consonant variations
     * (e.g. 'bh' -> 'b', 'th' -> 't', 'dh' -> 'd', 'ph' -> 'p', 'gh' -> 'g', 'kh' -> 'k').
     *
     * @param {string} s - Input name or string
     * @returns {string} Phonetically folded string
     *
     * @example
     * FamilyTreeBuilder.foldPhonetic("Abhi")
     * // => "abi"
     *
     * @example
     * FamilyTreeBuilder.foldPhonetic("Bindhu")
     * // => "bindu"
     */
    static foldPhonetic(s) {
        if (!s) return '';
        return FamilyTreeBuilder.foldVowels(s)
            .replace(/bh/g, 'b')
            .replace(/dh/g, 'd')
            .replace(/gh/g, 'g')
            .replace(/kh/g, 'k')
            .replace(/ph/g, 'p')
            .replace(/th/g, 't');
    }

    /**
     * Checks whether two names conflict due to distinct diminutive suffixes (e.g. '-amma' vs '-kutty').
     *
     * @param {string} norm1 - First normalized name string
     * @param {string} norm2 - Second normalized name string
     * @returns {boolean} True if suffixes conflict
     *
     * @example
     * FamilyTreeBuilder._hasConflictingDiminutiveSuffixes('annamma', 'annakutty');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasConflictingDiminutiveSuffixes('annamma', 'maryamma');
     * // => false
     */
    static _hasConflictingDiminutiveSuffixes(norm1, norm2) {
        const hasAmma1 = norm1.endsWith('amma') || norm1.endsWith('ama');
        const hasKutty1 = norm1.endsWith('kutty') || norm1.endsWith('kuty');
        const hasAmma2 = norm2.endsWith('amma') || norm2.endsWith('ama');
        const hasKutty2 = norm2.endsWith('kutty') || norm2.endsWith('kuty');
        return (hasAmma1 && hasKutty2) || (hasKutty1 && hasAmma2);
    }

    /**
     * Determines whether two word token arrays share at least one matching or phonetically folded token.
     *
     * @param {Array<string>} w1 - Word tokens from first name
     * @param {Array<string>} w2 - Word tokens from second name
     * @returns {boolean} True if phonetic word overlap exists
     *
     * @example
     * FamilyTreeBuilder._hasPhoneticWordOverlap(['george'], ['george']);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasPhoneticWordOverlap(['sobha'], ['soba']);
     * // => true
     */
    static _hasPhoneticWordOverlap(w1, w2) {
        const collapseDupes = w => w.replace(/(.)\1+/g, '$1');
        return w1.some(word1 => w2.some(word2 => {
            const c1 = collapseDupes(word1), c2 = collapseDupes(word2);
            if (c1 === c2 || c1.startsWith(c2) || c2.startsWith(c1)) return true;
            const f1 = FamilyTreeBuilder.foldPhonetic(c1), f2 = FamilyTreeBuilder.foldPhonetic(c2);
            return f1 === f2 || f1.startsWith(f2) || f2.startsWith(f1);
        }));
    }

    /**
     * Determines if two name strings refer to conflicting (distinct) people using adaptive word-prefix matching.
     * Short words (<=6 chars) match on 3-char prefixes; longer words match on half-length prefixes.
     * Empty/null values represent missing information and never conflict.
     *
     * @param {string|null} s1 - First name string
     * @param {string|null} s2 - Second name string
     * @returns {boolean} True if names conflict (different people), false if compatible/unifiable
     *
     * @example
     * FamilyTreeBuilder._hasNameConflict("Annapurna", "Annamma")
     * // => true (distinct names)
     *
     * @example
     * FamilyTreeBuilder._hasNameConflict("Sobha", "Soba")
     * // => false (phonetic match)
     */
    static _hasNameConflict(s1, s2) {
        if (!s1 || !s2) return false;
        const norm1 = s1.toLowerCase().trim(), norm2 = s2.toLowerCase().trim();
        if (norm1 === norm2) return false;

        const relRegex = /\b(sister|brother|mother|father|son|daughter|wife|husband)(?:\s*\d+)?\b/i;
        if (relRegex.test(norm1) !== relRegex.test(norm2)) return true;

        if (FamilyTreeBuilder._hasConflictingDiminutiveSuffixes(norm1, norm2)) return true;
        if (norm1.includes(norm2) || norm2.includes(norm1)) return false;

        const w1 = norm1.split(/[\s,&/]+/).filter(w => w.length > 2);
        const w2 = norm2.split(/[\s,&/]+/).filter(w => w.length > 2);
        if (w1.length === 0 || w2.length === 0) return false;

        return !FamilyTreeBuilder._hasPhoneticWordOverlap(w1, w2);
    }

    /**
     * Checks if two lowercase name strings overlap via substring containment.
     * Simpler than _hasNameConflict — used for partner name matching where
     * names have already been lowercased/trimmed from the node map.
     *
     * @param {string} a - First lowercase name
     * @param {string} b - Second lowercase name
     * @returns {boolean} True if names match or one contains the other
     *
     * @example
     * FamilyTreeBuilder._namesOverlap('ammini', 'ammini')
     * // => true (exact match)
     *
     * @example
     * FamilyTreeBuilder._namesOverlap('ammini', 'mary')
     * // => false (distinct)
     */
    static _namesOverlap(a, b) {
        return a === b || a.includes(b) || b.includes(a);
    }

    /**
     * Normalizes an arbitrary cell value into a comparable lowercase key.
     *
     * Non-string inputs (undefined/null/numbers from sparse spreadsheet cells)
     * collapse to the empty string so callers can compare without null guards.
     *
     * @param {*} s - Raw value from a spreadsheet cell or node field
     * @returns {string} Lowercased, trimmed string ('' for non-strings)
     *
     * @example
     * FamilyTreeBuilder._normText('  Kochuthresia ')
     * // => 'kochuthresia'
     *
     * @example
     * FamilyTreeBuilder._normText(undefined)
     * // => '' (sparse cell collapses to empty, never throws)
     */
    static _normText(s) {
        return typeof s === 'string' ? s.toLowerCase().trim() : '';
    }

    /**
     * Checks whether a parent-name cell names a real, identifiable person.
     *
     * Spreadsheets use placeholders rather than blanks for unrecorded parents,
     * so single letters, parenthesized notes, and 'unknown' markers are all
     * rejected as non-identifying.
     *
     * @param {*} s - Raw or normalized parent name
     * @returns {boolean} True if the value names an identifiable parent
     *
     * @example
     * FamilyTreeBuilder._isNamedParent('Annamma')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isNamedParent('(unknown)')
     * // => false (parenthesized placeholder)
     */
    static _isNamedParent(s) {
        return typeof s === 'string' && s.length > 1 && !s.startsWith('(') && !s.includes('unknown');
    }

    /**
     * Checks whether two node references denote the same person.
     *
     * Deduplication and ghost substitution can leave two distinct object
     * references describing one person, so reference equality alone is not
     * sufficient; matching ids are authoritative when both sides carry one.
     *
     * @param {Object} a - First node
     * @param {Object} b - Second node
     * @returns {boolean} True if both references denote the same person
     *
     * @example
     * FamilyTreeBuilder._isSameNode({ id: 'p1' }, { id: 'p1' })
     * // => true (distinct objects, same id)
     *
     * @example
     * FamilyTreeBuilder._isSameNode({ id: 'p1' }, { id: 'p2' })
     * // => false
     */
    static _isSameNode(a, b) {
        return a === b || Boolean(a && b && a.id && b.id && a.id === b.id);
    }

    /**
     * Resolves the birth year to reason with, preferring recorded over inferred.
     *
     * The builder mixes two node shapes: plain objects parsed straight from the
     * sheet (no `bestYob`) and `Person` instances (whose `bestYob` getter is
     * `yob || _inferredYob || 9999`). Consulting `yob` and `_inferredYob` first
     * makes both shapes agree, and lets the `bestYob` term supply Person's 9999
     * "unknown" sentinel only when nothing real is recorded.
     *
     * @param {Object} node - Sheet-derived node or Person instance
     * @returns {number|string|undefined} Best available birth year, or undefined
     *     when a plain node records none
     *
     * @example
     * FamilyTreeBuilder._effectiveYob({ yob: 1950, _inferredYob: 1948 })
     * // => 1950 (recorded year wins over inferred)
     *
     * @example
     * FamilyTreeBuilder._effectiveYob({ _inferredYob: 1948 })
     * // => 1948
     *
     * @example
     * FamilyTreeBuilder._effectiveYob({})
     * // => undefined (plain node; a Person would yield 9999)
     */
    static _effectiveYob(node) {
        return node.yob || node._inferredYob || node.bestYob;
    }

    /**
     * Returns a birth year only when one is actually recorded or inferred.
     *
     * Unlike {@link FamilyTreeBuilder._effectiveYob}, this never surfaces the
     * `Person.bestYob` sentinel (9999) and tolerates a missing node, so it is
     * the right choice for comparisons and sorts where "unknown" must stay
     * falsy rather than sort as a far-future year.
     *
     * @param {Object|null|undefined} node - Node to read, possibly absent
     * @returns {number|string|null} Recorded or inferred year, else null
     *
     * @example
     * FamilyTreeBuilder._knownYob({ _inferredYob: 1948 })
     * // => 1948
     *
     * @example
     * FamilyTreeBuilder._knownYob(undefined)
     * // => null (an unresolved partner reference sorts as unknown)
     */
    static _knownYob(node) {
        return node ? (node.yob || node._inferredYob || null) : null;
    }

    /**
     * Checks whether a parsed relation label denotes a mother.
     *
     * Sheets write maternal references both ways ("Mother: Annamma" and
     * "Mom: Annamma"), so both spellings are accepted.
     *
     * @param {string} relationType - Relation label parsed from a cell
     * @returns {boolean} True for 'mother' or 'mom'
     *
     * @example
     * FamilyTreeBuilder._isMotherRelation('mom')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isMotherRelation('parent')
     * // => false (unspecified role; see _isParentRelation)
     */
    static _isMotherRelation(relationType) {
        return relationType === 'mother' || relationType === 'mom';
    }

    /**
     * Checks whether a parsed relation label denotes a father.
     *
     * @param {string} relationType - Relation label parsed from a cell
     * @returns {boolean} True for 'father' or 'dad'
     *
     * @example
     * FamilyTreeBuilder._isFatherRelation('dad')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isFatherRelation('husband')
     * // => false
     */
    static _isFatherRelation(relationType) {
        return relationType === 'father' || relationType === 'dad';
    }

    /**
     * Checks whether a relation label targets a parent of either sex.
     *
     * Deliberately narrower than `_isMotherRelation || _isFatherRelation`: the
     * generic parent branches only ever see the long-form labels plus the
     * sexless 'parent', so the 'mom'/'dad' shorthands are not accepted here.
     *
     * @param {string} relationType - Relation label parsed from a cell
     * @returns {boolean} True for 'mother', 'father', or 'parent'
     *
     * @example
     * FamilyTreeBuilder._isParentRelation('parent')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isParentRelation('mom')
     * // => false (shorthand is handled by _isMotherRelation)
     */
    static _isParentRelation(relationType) {
        return relationType === 'mother' || relationType === 'father' || relationType === 'parent';
    }

    /**
     * Checks whether a relation label targets a spouse of either sex.
     *
     * @param {string} relationType - Relation label parsed from a cell
     * @returns {boolean} True for 'spouse', 'husband', or 'wife'
     *
     * @example
     * FamilyTreeBuilder._isSpouseRelation('wife')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isSpouseRelation('sister')
     * // => false
     */
    static _isSpouseRelation(relationType) {
        return relationType === 'spouse' || relationType === 'husband' || relationType === 'wife';
    }

    /**
     * Checks whether two nodes are already joined as partners.
     *
     * Partner lists are only eventually symmetric — one side is written first
     * during linking — so both directions must be consulted.
     *
     * @param {Object} a - First node
     * @param {Object} b - Second node
     * @returns {boolean} True if either node lists the other as a partner
     *
     * @example
     * FamilyTreeBuilder._arePartnersLinked({ id: 'p1', partners: ['p2'] }, { id: 'p2' })
     * // => true (link recorded on one side only)
     *
     * @example
     * FamilyTreeBuilder._arePartnersLinked({ id: 'p1' }, { id: 'p2' })
     * // => false (missing partner lists are treated as empty)
     */
    static _arePartnersLinked(a, b) {
        return (a.partners || []).includes(b.id) || (b.partners || []).includes(a.id);
    }

    /**
     * Validates if a father-child age difference satisfies biological bounds.
     *
     * @param {number|null} childYob - Child's birth year
     * @param {number|null} dadYob - Father's birth year
     * @returns {boolean} True if biologically valid or if years are unknown
     *
     * @example
     * FamilyTreeBuilder._isValidPaternalAge(1975, 1950)
     * // => true (diff = 25 years)
     *
     * @example
     * FamilyTreeBuilder._isValidPaternalAge(1960, 1950)
     * // => false (diff = 10 < MIN_PARENTAL_AGE)
     */
    static _isValidPaternalAge(childYob, dadYob) {
        if (!childYob || !dadYob) return true;
        const ageDiff = childYob - dadYob;
        return ageDiff >= FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE &&
               ageDiff <= FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE;
    }

    /**
     * Identifies spreadsheet instruction text, relational column subtitles,
     * or non-geographic entries (such as "husband/FATHER" or "if husband/father has it")
     * that should be avoided and never treated as real locations.
     * 
     * @param {string|null} p - Raw location string
     * @returns {boolean} True if the string is invalid / not a real location
     *
     * @example
     * FamilyTreeBuilder.isInvalidLocation('husband/FATHER')
     * // => true
     *
     * @example
     * FamilyTreeBuilder.isInvalidLocation('Kochi, Kerala')
     * // => false
     */
    static isInvalidLocation(p) {
        return Person.isInvalidLocation(p);
    }

    static FAVICON_DATA_URI = 'data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2064%2064%22%20width%3D%2264%22%20height%3D%2264%22%3E%20%3Cdefs%3E%20%3ClinearGradient%20id%3D%22bgGrad%22%20x1%3D%220%25%22%20y1%3D%220%25%22%20x2%3D%22100%25%22%20y2%3D%22100%25%22%3E%20%3Cstop%20offset%3D%220%25%22%20stop-color%3D%22%23312e81%22%20%2F%3E%20%3Cstop%20offset%3D%2250%25%22%20stop-color%3D%22%234f46e5%22%20%2F%3E%20%3Cstop%20offset%3D%22100%25%22%20stop-color%3D%22%237c3aed%22%20%2F%3E%20%3C%2FlinearGradient%3E%20%3CradialGradient%20id%3D%22canopyGlow%22%20cx%3D%2250%25%22%20cy%3D%2238%25%22%20r%3D%2242%25%22%3E%20%3Cstop%20offset%3D%220%25%22%20stop-color%3D%22%23a5b4fc%22%20stop-opacity%3D%220.45%22%20%2F%3E%20%3Cstop%20offset%3D%22100%25%22%20stop-color%3D%22%23a5b4fc%22%20stop-opacity%3D%220%22%20%2F%3E%20%3C%2FradialGradient%3E%20%3ClinearGradient%20id%3D%22trunkGrad%22%20x1%3D%220%25%22%20y1%3D%220%25%22%20x2%3D%220%25%22%20y2%3D%22100%25%22%3E%20%3Cstop%20offset%3D%220%25%22%20stop-color%3D%22%23ffffff%22%20%2F%3E%20%3Cstop%20offset%3D%22100%25%22%20stop-color%3D%22%23c7d2fe%22%20%2F%3E%20%3C%2FlinearGradient%3E%20%3C%2Fdefs%3E%20%3Crect%20x%3D%222%22%20y%3D%222%22%20width%3D%2260%22%20height%3D%2260%22%20rx%3D%2214%22%20fill%3D%22url(%23bgGrad)%22%20stroke%3D%22%23a5b4fc%22%20stroke-opacity%3D%220.35%22%20stroke-width%3D%221.5%22%20%2F%3E%20%3Ccircle%20cx%3D%2232%22%20cy%3D%2225%22%20r%3D%2220%22%20fill%3D%22url(%23canopyGlow)%22%20%2F%3E%20%3Cg%20fill%3D%22none%22%20stroke%3D%22url(%23trunkGrad)%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%20%3Cpath%20d%3D%22M32%2049%20V33%22%20stroke-width%3D%224.5%22%20%2F%3E%20%3Cpath%20d%3D%22M23%2051%20C28%2051%2032%2048%2032%2043%22%20stroke-width%3D%223.2%22%20%2F%3E%20%3Cpath%20d%3D%22M41%2051%20C36%2051%2032%2048%2032%2043%22%20stroke-width%3D%223.2%22%20%2F%3E%20%3Cpath%20d%3D%22M32%2036%20C22%2036%2016%2030%2016%2021%22%20stroke-width%3D%223.4%22%20%2F%3E%20%3Cpath%20d%3D%22M32%2034%20V15%22%20stroke-width%3D%223.4%22%20%2F%3E%20%3Cpath%20d%3D%22M32%2036%20C42%2036%2048%2030%2048%2021%22%20stroke-width%3D%223.4%22%20%2F%3E%20%3C%2Fg%3E%20%3Ccircle%20cx%3D%2232%22%20cy%3D%2214%22%20r%3D%226.2%22%20fill%3D%22%23fde68a%22%20stroke%3D%22%23ffffff%22%20stroke-width%3D%222%22%20%2F%3E%20%3Ccircle%20cx%3D%2216%22%20cy%3D%2221%22%20r%3D%225.2%22%20fill%3D%22%23ffffff%22%20stroke%3D%22%23c7d2fe%22%20stroke-width%3D%221.5%22%20%2F%3E%20%3Ccircle%20cx%3D%2248%22%20cy%3D%2221%22%20r%3D%225.2%22%20fill%3D%22%23ffffff%22%20stroke%3D%22%23c7d2fe%22%20stroke-width%3D%221.5%22%20%2F%3E%20%3Ccircle%20cx%3D%2232%22%20cy%3D%2235%22%20r%3D%223.6%22%20fill%3D%22%23ffffff%22%20%2F%3E%20%3C%2Fsvg%3E';

    /**
     * Normalizes tree layout options, providing defaults for visibleNodes, collapsedNodes, ppy, and siblingGap.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layout={}] - Raw layout configuration
     * @returns {Object} Fully populated layout configuration
     *
     * @example
     * FamilyTreeBuilder.normalizeLayoutConfig(tree, { ppy: 2.0 })
     * // => { ppy: 2.0, siblingGap: 24, visibleNodes: Set(...), ... }
     *
     * @example
     * FamilyTreeBuilder.normalizeLayoutConfig(null, {})
     * // => { ppy: 1.5, siblingGap: 24, rootNodeYob: 1900, ... }
     */
    static normalizeLayoutConfig(tree, layout = {}) {
        const collapsed = layout.collapsedNodes || new Set();
        const visible = layout.visibleNodes || (tree && typeof tree.getVisibleNodes === 'function' ? tree.getVisibleNodes(collapsed) : new Set(tree?.all ? tree.all.map(n => n.id) : []));
        return {
            focusId: layout.focusId || null,
            aiHighlightedIds: layout.aiHighlightedIds || null,
            rootNodeYob: layout.rootNodeYob || (tree?.getStats ? tree.getStats().rootNodeYob : (tree?.root?.yob || 1900)),
            visibleNodes: visible,
            collapsedNodes: collapsed,
            ppy: typeof layout.ppy === 'number' ? layout.ppy : 1.5,
            siblingGap: typeof layout.siblingGap === 'number' ? layout.siblingGap : 24,
            ...layout
        };
    }

    /**
     * Computes the layout of the family tree using layoutSubtree and flattenTreeLayout.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layout={}] - Layout configuration options
     * @returns {Object|null} Layout data containing nodes, paths, and bounding box dimensions
     *
     * @example
     * const layout = FamilyTreeBuilder.computeLayout(tree);
     * // => { nodes: [...], paths: [...], bounds: {...} }
     *
     * @example
     * const emptyLayout = FamilyTreeBuilder.computeLayout(null);
     * // => null
     */
    static computeLayout(tree, layout = {}) {
        if (typeof FamilyTreeBuilder._computeLayoutFn === 'function') {
            return FamilyTreeBuilder._computeLayoutFn(tree, layout);
        }
        if (typeof layoutSubtree === 'function' && typeof flattenTreeLayout === 'function') {
            const normalized = FamilyTreeBuilder.normalizeLayoutConfig(tree, layout);
            const startPerson = layout.rootNode || (layout.rootId ? tree.get(layout.rootId) : tree.root);
            const sub = layoutSubtree(startPerson, tree, normalized, new Set());
            return flattenTreeLayout(sub);
        }
        return null;
    }

    /**
     * Marks all partner profiles of a person as visited to prevent redundant traversal.
     * 
     * @param {Person} person - Person node
     * @param {FamilyTree} tree - Tree instance
     * @param {Set<string>} visited - Set of visited node IDs
     *
     * @example
     * const visited = new Set();
     * FamilyTreeBuilder._markPartnersVisited({ partners: ['p2'] }, tree, visited);
     * // visited.has('p2') => true
     *
     * @example
     * const visited = new Set(['p1']);
     * FamilyTreeBuilder._markPartnersVisited({ partners: [] }, tree, visited);
     * // visited size remains 1
     */
    static _markPartnersVisited(person, tree, visited) {
        (person.partners || []).forEach(pId => {
            const partner = tree.get(pId);
            if (partner && !visited.has(partner.id)) {
                visited.add(partner.id);
            }
        });
    }

    /**
     * Enqueues valid display children of a person into the BFS depth-calculation queue.
     * 
     * @param {Person} person - Person node
     * @param {FamilyTree} tree - Tree instance
     * @param {number} depth - Current depth
     * @param {Set<string>} visited - Set of visited node IDs
     * @param {Array<{ person: Person, depth: number }>} queue - BFS queue
     *
     * @example
     * const queue = [];
     * FamilyTreeBuilder._enqueueDisplayChildren({ children: ['c1'] }, tree, 0, new Set(), queue);
     * // queue.length => 1
     *
     * @example
     * const queue = [];
     * FamilyTreeBuilder._enqueueDisplayChildren({ children: [] }, tree, 0, new Set(), queue);
     * // queue.length => 0
     */
    static _enqueueDisplayChildren(person, tree, depth, visited, queue) {
        const kids = typeof person.getValidDisplayChildren === 'function'
            ? person.getValidDisplayChildren(tree)
            : (person.children || []).map(id => tree.get(id)).filter(Boolean);

        for (const child of kids) {
            if (child && !visited.has(child.id)) {
                visited.add(child.id);
                queue.push({ person: child, depth: depth + 1 });
            }
        }
    }

    /**
     * Calculates the maximum generational depth of visible display nodes in the tree
     * starting from the root (depth 0).
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Person} [startPerson=null] - Optional start person (defaults to tree.root)
     * @returns {number} Maximum generation depth (e.g. 0 for root only, 3 for 4 generations)
     *
     * @example
     * FamilyTreeBuilder.getMaxGenerationDepth(tree)
     * // => 3
     *
     * @example
     * FamilyTreeBuilder.getMaxGenerationDepth(null)
     * // => 0
     */
    static getMaxGenerationDepth(tree, startPerson = null) {
        if (!tree) return 0;
        const root = startPerson || tree.root;
        if (!root) return 0;

        let maxDepth = 0;
        const visited = new Set();
        const queue = [{ person: root, depth: 0 }];
        visited.add(root.id);

        while (queue.length > 0) {
            const { person, depth } = queue.shift();
            if (depth > maxDepth) {
                maxDepth = depth;
            }

            FamilyTreeBuilder._markPartnersVisited(person, tree, visited);
            FamilyTreeBuilder._enqueueDisplayChildren(person, tree, depth, visited, queue);
        }

        return maxDepth;
    }

    /**
     * Recursively computes the total number of individuals (branch head, spouses,
     * children, and all subsequent descendants) belonging to a family branch.
     *
     * @param {Object} node - Branch head or descendant node
     * @param {FamilyTree} tree - Tree domain model
     * @param {Set<string>} [visited=new Set()] - Visited person ID tracker to prevent cyclic counting
     * @returns {number} Total member count in the branch
     *
     * @example
     * FamilyTreeBuilder._countFamilyBranchDescendants(thomasNode, tree);
     * // => 4
     *
     * @example
     * FamilyTreeBuilder._countFamilyBranchDescendants(singlePersonWithoutSpouseOrKids, tree);
     * // => 1
     */
    static _countFamilyBranchDescendants(node, tree, visited = new Set()) {
        if (!node || visited.has(node.id)) return 0;
        visited.add(node.id);
        let count = 1;

        (node.partners || []).forEach(pId => {
            const p = tree.get(pId);
            if (p && !visited.has(p.id)) {
                visited.add(p.id);
                count++;
            }
        });

        const kids = typeof node.getValidDisplayChildren === 'function'
            ? node.getValidDisplayChildren(tree)
            : (node.children || []).map(id => tree.get(id)).filter(Boolean);

        kids.forEach(k => {
            count += FamilyTreeBuilder._countFamilyBranchDescendants(k, tree, visited);
        });

        return count;
    }

    /**
     * Encodes JSX source code to base64, supporting both browser (btoa) and Node.js (Buffer) environments.
     *
     * @param {string} source - Raw application source code string.
     * @returns {string} Base64-encoded string representation.
     *
     * @example
     * FamilyTreeBuilder._encodeSourceBase64('console.log("hello");');
     * // => 'Y29uc29sZS5sb2coImhlbGxvIik7'
     *
     * @example
     * FamilyTreeBuilder._encodeSourceBase64('');
     * // => ''
     */
    static _encodeSourceBase64(source) {
        return (typeof btoa !== 'undefined')
            ? btoa(unescape(encodeURIComponent(source)))
            : Buffer.from(source).toString('base64');
    }

    /**
     * Generates the inline Tailwind CSS configuration script for standalone application styling.
     *
     * @returns {string} Script tag configuring custom Tailwind animations and keyframes.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneTailwindConfig().includes('tailwind.config =')
     * // => true
     *
     * @example
     * const cfg = FamilyTreeBuilder._getStandaloneTailwindConfig();
     * console.log(cfg.includes('text-gradient'));
     */
    static _getStandaloneTailwindConfig() {
        return `  <script>
    tailwind.config = {
      theme: {
        extend: {
          keyframes: {
            'text-gradient': {
              '0%': { backgroundPosition: '0% 50%' },
              '50%': { backgroundPosition: '100% 50%' },
              '100%': { backgroundPosition: '0% 50%' },
            }
          },
          animation: {
            'text-gradient': 'text-gradient 3s linear infinite',
          }
        }
      }
    }
  </script>`;
    }

    /**
     * Generates the CDN script tags and external font links required by the standalone application.
     *
     * @returns {string} Script tags and stylesheet link elements.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneHeadScripts().includes('cdn.tailwindcss.com')
     * // => true
     *
     * @example
     * const headScripts = FamilyTreeBuilder._getStandaloneHeadScripts();
     * console.log(headScripts.includes('react.production.min.js'));
     */
    static _getStandaloneHeadScripts() {
        return `  <!-- Tailwind CSS CDN -->
  <script src="https://cdn.tailwindcss.com"></script>
${this._getStandaloneTailwindConfig()}

  <!-- Google Fonts -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Uncial+Antiqua&display=swap" rel="stylesheet" crossOrigin="anonymous">

  <!-- React 18 & ReactDOM 18 UMD -->
  <script crossorigin src="https://unpkg.com/react@18.3.1/umd/react.production.min.js"></script>
  <script crossorigin src="https://unpkg.com/react-dom@18.3.1/umd/react-dom.production.min.js"></script>

  <!-- Babel Standalone -->
  <script src="https://unpkg.com/@babel/standalone@7.24.7/babel.min.js"></script>

  <!-- html-to-image for diagram export -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/html-to-image/1.11.11/html-to-image.min.js"></script>`;
    }

    /**
     * Generates the <head> section containing CDN scripts, fonts, and Tailwind setup for the standalone app.
     *
     * @param {string} title - The HTML document title.
     * @returns {string} The complete <head> HTML markup block.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneHeadMarkup('My Family Tree');
     * // => '<head>\n  <meta charset="UTF-8" />\n  ...<title>My Family Tree</title>...\n</head>'
     *
     * @example
     * const head = FamilyTreeBuilder._getStandaloneHeadMarkup('Generations');
     * console.log(head.includes('Generations'));
     */
    static _getStandaloneHeadMarkup(title) {
        return `<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${title}</title>
  <link rel="icon" type="image/svg+xml" href="${FamilyTreeBuilder.FAVICON_DATA_URI}" />
${this._getStandaloneHeadScripts()}
</head>`;
    }

    /**
     * Generates the module environment shim script for standalone browser execution.
     *
     * @returns {string} Global module shim script fragment.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneModuleShim().includes('window.require')
     * // => true
     *
     * @example
     * const shim = FamilyTreeBuilder._getStandaloneModuleShim();
     * console.log(shim.includes('window.exports'));
     */
    static _getStandaloneModuleShim() {
        return `    window.exports = window.exports || {};
    window.module = window.module || { exports: window.exports };
    window.require = function(moduleName) {
      if (moduleName === 'react') return window.React;
      if (moduleName === 'react-dom' || moduleName === 'react-dom/client') return window.ReactDOM;
      throw new Error('Cannot find module "' + moduleName + '"');
    };`;
    }

    /**
     * Generates error markup rendered into the root element if standalone application loading fails.
     *
     * @returns {string} Error display template literal string.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneErrorTemplate().includes('Error Loading Standalone Application')
     * // => true
     *
     * @example
     * const tpl = FamilyTreeBuilder._getStandaloneErrorTemplate();
     * console.log(tpl.includes('max-w-xl'));
     */
    static _getStandaloneErrorTemplate() {
        return `\`<div class="flex items-center justify-center h-full p-8 font-sans">
            <div class="max-w-xl bg-red-50 border border-red-200 text-red-700 p-6 rounded-2xl shadow-lg">
              <h2 class="text-lg font-bold mb-2">Error Loading Standalone Application</h2>
              <pre class="text-xs font-mono whitespace-pre-wrap overflow-auto max-h-96">\${err.message}</pre>
            </div>
          </div>\``;
    }

    /**
     * Generates the inner loadApp async function implementation for compiling and mounting the standalone React app.
     *
     * @returns {string} JavaScript source code of the loadApp function definition.
     *
     * @example
     * FamilyTreeBuilder._getStandaloneAppLoaderScript().includes('Babel.transform')
     * // => true
     *
     * @example
     * const loader = FamilyTreeBuilder._getStandaloneAppLoaderScript();
     * console.log(loader.includes('ReactDOM.createRoot'));
     */
    static _getStandaloneAppLoaderScript() {
        return `    async function loadApp() {
      try {
        const rawB64 = document.getElementById('embedded-app-b64').textContent.trim();
        const code = decodeURIComponent(escape(atob(rawB64)));
        window.appCode = code;

        const transformed = Babel.transform(code, {
          presets: ['react', 'env'],
          filename: 'App.jsx'
        }).code;

        const moduleFunc = new Function('React', 'ReactDOM', 'exports', 'module', 'require', transformed);
        const localExports = {};
        const localModule = { exports: localExports };
        moduleFunc(window.React, window.ReactDOM, localExports, localModule, window.require);

        const AppComponent = localModule.exports.default || localExports.default || window.App;
        if (!AppComponent) {
          throw new Error('App component was not exported from App.jsx');
        }

        const root = ReactDOM.createRoot(document.getElementById("root"));
        root.render(React.createElement(AppComponent));
      } catch (err) {
        console.error('Error initializing Standalone Family Tree app:', err);
        document.getElementById('root').innerHTML = ${this._getStandaloneErrorTemplate()};
      }
    }`;
    }

    /**
     * Generates the client-side JavaScript bootstrap loader for decrypting and executing the standalone bundle.
     *
     * @returns {string} Embedded script markup block
     *
     * @example
     * FamilyTreeBuilder._getStandaloneBootstrapScript().includes('function loadApp');
     * // => true
     *
     * @example
     * const script = FamilyTreeBuilder._getStandaloneBootstrapScript();
     * console.log(script.includes('Babel.transform'));
     */
    static _getStandaloneBootstrapScript() {
        return `<script type="text/javascript">
${this._getStandaloneModuleShim()}

${this._getStandaloneAppLoaderScript()}

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', loadApp);
    } else {
      loadApp();
    }
  </script>`;
    }

    /**
     * Builds a self-contained, single-file HTML document packaging the entire React app
     * and the pre-embedded family tree dataset for offline and double-click (file://) execution.
     * 
     * @param {string} appJsx - Complete App.jsx source code
     * @param {Object} [treeData=null] - { url, rows, sheetTags }
     * @param {string} [title='Family Tree'] - Document title
     * @returns {string} Standalone HTML document string
     *
     * @example
     * const html = FamilyTreeBuilder.buildStandaloneAppHtml('export default function App() {}', { rows: [] });
     * // => '<!DOCTYPE html>...'
     *
     * @example
     * const html = FamilyTreeBuilder.buildStandaloneAppHtml('const x = 1;', null, 'My Tree');
     * // => '<!DOCTYPE html>...<title>My Tree</title>...'
     */
    static buildStandaloneAppHtml(appJsx, treeData = null, title = 'Family Tree') {
        const b64Jsx = FamilyTreeBuilder._encodeSourceBase64(appJsx);
        const treeDataJson = treeData ? JSON.stringify(treeData) : '{}';

        return `<!DOCTYPE html>
<html lang="en">
${FamilyTreeBuilder._getStandaloneHeadMarkup(title)}
<body class="h-screen w-screen overflow-hidden bg-white">
  <div id="root" class="h-full w-full"></div>

  <!-- Embedded Tree Dataset for 0ms Instant First Paint -->
  <script id="embedded-tree-data" type="application/json">
${treeDataJson}
  </script>

  <!-- Embedded Base64 Application Source (Eliminates local HTTP fetch / CORS restrictions) -->
  <script id="embedded-app-b64" type="text/plain">
${b64Jsx}
  </script>

  <!-- Standalone React & Babel In-Memory Loader -->
  ${FamilyTreeBuilder._getStandaloneBootstrapScript()}
</body>
</html>
`;
    }

    /**
     * Initializes a new FamilyTreeBuilder instance for processing raw tabular rows into a genealogical graph.
     *
     * @param {Array<Object>} rawRows - Array of raw row objects parsed from spreadsheet or CSV
     * @param {Object} [sheetNames={}] - Optional mapping of sheet names or tags
     *
     * @example
     * const builder = new FamilyTreeBuilder([{ Name: 'Thomas', YOB: '1905' }]);
     * // => FamilyTreeBuilder instance with initialized rawRows and empty nodeMap
     *
     * @example
     * const builder = new FamilyTreeBuilder([], { main: 'Family Data' });
     * // => FamilyTreeBuilder instance with sheetNames configured
     */
    constructor(rawRows, sheetNames = {}) {
        this.rawRows = rawRows;
        this.sheetNames = sheetNames;
        this.nodeMap = {};
        this.name2nodes = {};
        this.rootId = null;
    }

    /**
     * Finds matching character positions between two strings within a given distance window.
     *
     * @param {string} str1 - Normalized first string
     * @param {string} str2 - Normalized second string
     * @param {number} matchDist - Maximum allowable index distance for match
     * @returns {{ s1Matches: Array<boolean>, s2Matches: Array<boolean>, matches: number }}
     *
     * @example
     * FamilyTreeBuilder._findMatchingCharacters('mothr', 'mother', 2);
     * // => { s1Matches: [true, true, true, true, true], s2Matches: [true, true, true, true, false, true], matches: 5 }
     *
     * @example
     * FamilyTreeBuilder._findMatchingCharacters('abc', 'xyz', 1);
     * // => { s1Matches: [false, false, false], s2Matches: [false, false, false], matches: 0 }
     */
    static _findMatchingCharacters(str1, str2, matchDist) {
        const len1 = str1.length;
        const len2 = str2.length;
        const s1Matches = new Array(len1).fill(false);
        const s2Matches = new Array(len2).fill(false);

        let matches = 0;
        for (let i = 0; i < len1; i++) {
            const start = Math.max(0, i - matchDist);
            const end = Math.min(i + matchDist + 1, len2);
            for (let j = start; j < end; j++) {
                if (s2Matches[j] || str1[i] !== str2[j]) continue;
                s1Matches[i] = true;
                s2Matches[j] = true;
                matches++;
                break;
            }
        }
        return { s1Matches, s2Matches, matches };
    }

    /**
     * Counts transpositions between matched characters in two strings.
     *
     * @param {string} str1 - First string
     * @param {string} str2 - Second string
     * @param {Array<boolean>} s1Matches - Matched positions in str1
     * @param {Array<boolean>} s2Matches - Matched positions in str2
     * @returns {number} Half-transposition count
     *
     * @example
     * FamilyTreeBuilder._countTranspositions('martha', 'marhta', [true, true, true, true, true, true], [true, true, true, true, true, true]);
     * // => 1
     *
     * @example
     * FamilyTreeBuilder._countTranspositions('abc', 'abc', [true, true, true], [true, true, true]);
     * // => 0
     */
    static _countTranspositions(str1, str2, s1Matches, s2Matches) {
        let t = 0, k = 0;
        for (let i = 0; i < str1.length; i++) {
            if (!s1Matches[i]) continue;
            while (!s2Matches[k]) k++;
            if (str1[i] !== str2[k]) t++;
            k++;
        }
        return t / 2;
    }

    /**
     * Calculates the length of the common prefix between two strings (up to maxPrefix characters).
     *
     * @param {string} str1 - First string
     * @param {string} str2 - Second string
     * @param {number} [maxPrefix=4] - Maximum prefix length to inspect
     * @returns {number} Number of matching leading characters
     *
     * @example
     * FamilyTreeBuilder._calculateCommonPrefixLength('mother', 'mothr', 4)
     * // => 4
     *
     * @example
     * FamilyTreeBuilder._calculateCommonPrefixLength('father', 'mother', 4)
     * // => 0
     */
    static _calculateCommonPrefixLength(str1, str2, maxPrefix = 4) {
        const bound = Math.min(maxPrefix, Math.min(str1.length, str2.length));
        let prefix = 0;
        for (let i = 0; i < bound; i++) {
            if (str1[i] === str2[i]) prefix++;
            else break;
        }
        return prefix;
    }

    /**
     * Computes the Jaro-Winkler similarity metric between two strings, returning
     * a normalized value in [0.0, 1.0]. Used for fuzzy schema alignment of CSV
     * column headers against canonical genealogical fields.
     *
     * @param {string} s1 - First string
     * @param {string} s2 - Second string
     * @returns {number} Jaro-Winkler distance score between 0.0 and 1.0
     *
     * @example
     * FamilyTreeBuilder.computeJaroWinkler('mothr', 'mother');
     * // => ~0.967
     *
     * @example
     * FamilyTreeBuilder.computeJaroWinkler('mother', 'father');
     * // => ~0.778
     */
    static computeJaroWinkler(s1, s2) {
        if (s1 === s2) return 1.0;
        if (!s1 || !s2) return 0.0;

        const str1 = s1.toLowerCase();
        const str2 = s2.toLowerCase();
        if (str1 === str2) return 1.0;

        const len1 = str1.length;
        const len2 = str2.length;
        const matchDist = Math.floor(Math.max(len1, len2) / 2) - 1;

        const { s1Matches, s2Matches, matches } = FamilyTreeBuilder._findMatchingCharacters(str1, str2, matchDist);
        if (matches === 0) return 0.0;

        const transpositions = FamilyTreeBuilder._countTranspositions(str1, str2, s1Matches, s2Matches);
        const jaro = ((matches / len1) + (matches / len2) + ((matches - transpositions) / matches)) / 3.0;
        const prefix = FamilyTreeBuilder._calculateCommonPrefixLength(str1, str2, 4);

        const p = 0.1;
        return jaro + prefix * p * (1.0 - jaro);
    }

    /**
     * Checks whether a candidate column key collides with parent or spousal keywords.
     *
     * @param {string} target - Target attribute name (e.g. 'mother', 'father', 'spouse')
     * @param {string} normKey - Normalized candidate column header
     * @param {boolean} isSubstring - Whether substring matching is active
     * @returns {boolean} True if collision detected
     *
     * @example
     * FamilyTreeBuilder._isParentOrSpouseCollision('mother', 'father name', false);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isParentOrSpouseCollision('spouse', 'spouse age', false);
     * // => true
     */
    static _isParentOrSpouseCollision(target, normKey, isSubstring) {
        if (normKey.includes('years') || normKey.includes('death') || normKey.includes('birth') || normKey.includes('age')) {
            return true;
        }
        if (target === 'mother' || target === 'mom') {
            return normKey.includes('location') || normKey.includes('family name') || normKey.includes('place') ||
                normKey.startsWith('father');
        }
        if (target === 'father' || target === 'dad') {
            return normKey.includes('location') || normKey.includes('family name') || normKey.includes('place') ||
                normKey.startsWith('mother');
        }
        return normKey.includes('location') || normKey.includes('place') || (isSubstring && normKey.includes('family name'));
    }

    /**
     * Determines whether a candidate column header is a disallowed collision for a target field.
     * Prevents false positive column assignments during spreadsheet header normalization.
     *
     * @param {string} target - Target semantic field (e.g. 'mother', 'father', 'name', 'birth')
     * @param {string} normKey - Candidate normalized column header
     * @param {boolean} [isSubstring=false] - Whether matching in substring fallback mode
     * @returns {boolean} True if assignment should be disallowed
     *
     * @example
     * FamilyTreeBuilder._isDisallowedColumnCollision('father', 'location if father has it', false);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isDisallowedColumnCollision('father', 'father name', false);
     * // => false
     */
    static _isDisallowedColumnCollision(target, normKey, isSubstring = false) {
        const t = target.toLowerCase();
        if (t === 'name' && normKey.includes('nick')) return true;
        if (t === 'mother' || t === 'mom' || t === 'father' || t === 'dad' ||
            t === 'spouse' || t === 'husband' || t === 'wife' || t === 'partner') {
            return FamilyTreeBuilder._isParentOrSpouseCollision(t, normKey, isSubstring);
        }
        if (t.includes('birth') || t === 'yob' || t === 'dob') {
            return normKey.includes('death') || normKey.includes('died') || normKey.includes('after') || normKey.includes('since');
        }
        if (t.includes('death') || t === 'yod') {
            if (normKey.includes('birth') || normKey.includes('born')) return true;
            if (t === 'death' || t === 'year of death' || t === 'death year' || t === 'yod') {
                return normKey.includes('years') || normKey.includes('after') || normKey.includes('since') || normKey.includes('ago');
            }
        }
        if (isSubstring && t === 'age') {
            return normKey !== 'age' && !normKey.startsWith('age ') && !normKey.endsWith(' age') && !normKey.includes(' age ');
        }
        return false;
    }

    /**
     * Finds a column key that matches one of the target names exactly or as a leading word prefix.
     *
     * @param {Array<string>} rKeys - Available column headers in the row
     * @param {Array<string>} possibleNames - Candidate target header names (lowercase)
     * @returns {string|null} Matching key or null
     *
     * @example
     * FamilyTreeBuilder._findExactOrPrefixColumnKey(['Name', 'Age'], ['name']);
     * // => 'Name'
     *
     * @example
     * FamilyTreeBuilder._findExactOrPrefixColumnKey(['Father Name', 'Age'], ['father']);
     * // => 'Father Name'
     */
    static _findExactOrPrefixColumnKey(rKeys, possibleNames) {
        for (const k of rKeys) {
            if (k.startsWith('_')) continue;
            const norm = k.toLowerCase().trim().replace(/[\r\n]+/g, ' ');
            for (const p of possibleNames) {
                if ((norm === p || norm.startsWith(p + ' ')) && !FamilyTreeBuilder._isDisallowedColumnCollision(p, norm, false)) {
                    return k;
                }
            }
        }
        return null;
    }

    /**
     * Finds a column key that contains one of the target names as a substring, guarded by collision rules.
     *
     * @param {Array<string>} rKeys - Available column headers in the row
     * @param {Array<string>} possibleNames - Candidate target header names (lowercase)
     * @returns {string|null} Matching key or null
     *
     * @example
     * FamilyTreeBuilder._findSubstringColumnKey(['Location of Residence'], ['location']);
     * // => 'Location of Residence'
     *
     * @example
     * FamilyTreeBuilder._findSubstringColumnKey(['Father Location'], ['father']);
     * // => null
     */
    static _findSubstringColumnKey(rKeys, possibleNames) {
        for (const k of rKeys) {
            if (k.startsWith('_')) continue;
            const norm = k.toLowerCase().trim().replace(/[\r\n]+/g, ' ');
            for (const p of possibleNames) {
                if (norm.includes(p) && !FamilyTreeBuilder._isDisallowedColumnCollision(p, norm, true)) {
                    return k;
                }
            }
        }
        return null;
    }

    /**
     * Computes the highest Jaro-Winkler similarity score between a column header and schema synonym.
     *
     * Evaluates both full header string similarity and individual header token similarity.
     *
     * @param {string} norm - Normalized column header string
     * @param {Array<string>} normTokens - Filtered tokens from normalized header
     * @param {string} p - Candidate schema synonym
     * @returns {number} Maximum similarity score (0.0 to 1.0)
     *
     * @example
     * FamilyTreeBuilder._scoreFuzzyHeaderCandidate('mothr', ['mothr'], 'mother');
     * // => 0.9666666666666667
     *
     * @example
     * FamilyTreeBuilder._scoreFuzzyHeaderCandidate('city location', ['city', 'location'], 'location');
     * // => 1.0
     */
    static _scoreFuzzyHeaderCandidate(norm, normTokens, p) {
        if (FamilyTreeBuilder._isDisallowedColumnCollision(p, norm, true)) return 0;
        let maxScore = 0;
        if (Math.abs(norm.length - p.length) <= 4) {
            maxScore = Math.max(maxScore, FamilyTreeBuilder.computeJaroWinkler(norm, p));
        }
        if (!p.includes(' ')) {
            for (const tok of normTokens) {
                if (Math.abs(tok.length - p.length) <= 2) {
                    maxScore = Math.max(maxScore, FamilyTreeBuilder.computeJaroWinkler(tok, p));
                }
            }
        }
        return maxScore;
    }

    /**
     * Finds a column key using fuzzy Jaro-Winkler similarity alignment (score >= 0.85).
     *
     * @param {Array<string>} rKeys - Available column headers in the row
     * @param {Array<string>} possibleNames - Candidate target header names (lowercase)
     * @returns {string|null} Best matching key or null
     *
     * @example
     * FamilyTreeBuilder._findFuzzyColumnKey(['Mothr Name'], ['mother']);
     * // => 'Mothr Name'
     *
     * @example
     * FamilyTreeBuilder._findFuzzyColumnKey(['City'], ['father']);
     * // => null
     */
    static _findFuzzyColumnKey(rKeys, possibleNames) {
        let bestKey = null;
        let bestScore = 0.85;
        for (const k of rKeys) {
            if (k.startsWith('_')) continue;
            const norm = k.toLowerCase().trim().replace(/[\r\n]+/g, ' ');
            const normTokens = norm.split(/[\s,/_]+/).filter(t => t.length >= 3);
            for (const p of possibleNames) {
                const score = FamilyTreeBuilder._scoreFuzzyHeaderCandidate(norm, normTokens, p);
                if (score >= bestScore) {
                    bestScore = score;
                    bestKey = k;
                }
            }
        }
        return bestKey;
    }

    /**
     * Extracts a cell value from a raw row by searching across schema header synonyms.
     *
     * Performs a 3-tier cascade:
     * 1. Exact or prefix match.
     * 2. Substring match with collision guards.
     * 3. Fuzzy Jaro-Winkler schema alignment (>= 0.85).
     *
     * @param {Array<string>} rKeys - Row header keys
     * @param {Object} r - Raw row data object
     * @param {Array<string>} possibleNames - Acceptable header candidate names
     * @returns {string} Cleaned cell value or empty string
     *
     * @example
     * FamilyTreeBuilder._extractColumnValue(['Mother Name', 'Age'], { 'Mother Name': 'Mary' }, ['mother', 'mom']);
     * // => 'Mary'
     *
     * @example
     * FamilyTreeBuilder._extractColumnValue(['Location (if father has it)'], { 'Location (if father has it)': 'Palai' }, ['father', 'dad']);
     * // => ''
     */
    static _extractColumnValue(rKeys, r, possibleNames) {
        const exactKey = FamilyTreeBuilder._findExactOrPrefixColumnKey(rKeys, possibleNames);
        if (exactKey) return r[exactKey] ? r[exactKey].toString().trim() : '';

        const substrKey = FamilyTreeBuilder._findSubstringColumnKey(rKeys, possibleNames);
        if (substrKey) return r[substrKey] ? r[substrKey].toString().trim() : '';

        const fuzzyKey = FamilyTreeBuilder._findFuzzyColumnKey(rKeys, possibleNames);
        if (fuzzyKey && r[fuzzyKey] !== undefined && r[fuzzyKey] !== null) {
            return r[fuzzyKey].toString().trim();
        }
        return '';
    }

    /**
     * Resolves death year from explicit string or elapsed years since death.
     *
     * @private
     * @param {string} rawDeath - Raw death column input
     * @param {number|null} validYearsAfterDeath - Sanitized years since death
     * @param {number} currentYear - Current reference year
     * @returns {string|number} Resolved death year or empty string
     *
     * @example
     * FamilyTreeBuilder._resolveDeathYear('', 10, 2026);
     * // => 2016
     *
     * @example
     * FamilyTreeBuilder._resolveDeathYear('circa 2000', null, 2026);
     * // => 'circa 2000'
     */
    static _resolveDeathYear(rawDeath, validYearsAfterDeath, currentYear) {
        if (rawDeath) {
            const pDeath = parseInt(rawDeath, 10);
            return (!isNaN(pDeath) && pDeath > 0) ? pDeath : rawDeath.toString().trim();
        }
        return validYearsAfterDeath !== null ? (currentYear - validYearsAfterDeath) : '';
    }

    /**
     * Deduces year of birth and death year from explicit values, relative ages, or years since death.
     * 
     * @param {string} rawAge - Raw age string (e.g. '45')
     * @param {string} rawYearsAfterDeath - Raw years since death string (e.g. '10')
     * @param {string} rawYob - Explicit year of birth string (e.g. '1975')
     * @param {string} rawDeath - Explicit death year string (e.g. '2015')
     * @param {number} currentYear - Current calendar year
     * @returns {{ yob: number, death: string|number }}
     * 
     * @example
     * FamilyTreeBuilder._deduceYearsFromAge('50', '', '', '', 2026);
     * // => { yob: 1976, death: '' }
     * 
     * @example
     * FamilyTreeBuilder._deduceYearsFromAge('75', '10', '', '', 2026);
     * // => { yob: 1941, death: 2016 }
     */
    static _deduceYearsFromAge(rawAge, rawYearsAfterDeath, rawYob, rawDeath, currentYear) {
        const parsedAge = parseInt(rawAge, 10);
        const validAge = (!isNaN(parsedAge) && parsedAge > 0 && parsedAge < FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_HUMAN_LIFESPAN) ? parsedAge : null;
        const parsedYearsAfterDeath = parseInt(rawYearsAfterDeath, 10);
        const validYearsAfterDeath = (!isNaN(parsedYearsAfterDeath) && parsedYearsAfterDeath >= 0) ? parsedYearsAfterDeath : null;

        const death = FamilyTreeBuilder._resolveDeathYear(rawDeath, validYearsAfterDeath, currentYear);
        const pYob = parseInt(rawYob, 10);
        let yob = (!isNaN(pYob) && pYob > 0) ? pYob : 0;

        if (!yob && validAge !== null) {
            const deathYear = parseInt(death, 10);
            yob = (!isNaN(deathYear) && deathYear > 0) ? (deathYear - validAge) : (currentYear - validAge);
        }
        return { yob, death };
    }

    /** Set of statically recognized female forenames and naming components. */
    static _STATIC_FEMALE_NAMES = Object.freeze(new Set());

    /** Set of statically recognized male forenames and naming components. */
    static _STATIC_MALE_NAMES = Object.freeze(new Set());

    /**
     * Determines whether a given person name represents a female individual based on
     * explicit female word lists, title ontology, and linguistic suffix heuristics.
     *
     * @param {string} name - Person name string
     * @returns {boolean} True if classified as female
     *
     * @example
     * FamilyTreeBuilder._isFemaleName('Mary Thankamma');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isFemaleName('Joseph');
     * // => false
     */
    static _isFemaleName(name) {
        if (!name) return false;
        const lower = name.toLowerCase().trim();
        if (FamilyTreeBuilder._dynamicFemaleNames && FamilyTreeBuilder._dynamicFemaleNames.has(lower)) return true;
        const titleMatch = FamilyTreeBuilder.matchTitleOntology(lower);
        if (titleMatch) {
            if (titleMatch.gender === 'F') return true;
            if (titleMatch.gender === 'M') return false;
        }
        const femaleNames = FamilyTreeBuilder._STATIC_FEMALE_NAMES;
        if (femaleNames.has(lower)) return true;
        const tokens = lower.split(/\s+/);
        if (tokens.some(t => femaleNames.has(t))) return true;
        if (tokens.some(t => FamilyTreeBuilder._dynamicFemaleNames && FamilyTreeBuilder._dynamicFemaleNames.has(t))) return true;
        if (!FamilyTreeBuilder._isMaleName(lower) && tokens.some(t => /(?:amma|mol|mary)$/i.test(t))) return true;
        return false;
    }

    /**
     * Determines whether a given person name represents a male individual based on
     * explicit male word lists, title ontology, and linguistic suffix heuristics.
     *
     * @param {string} name - Person name string
     * @returns {boolean} True if classified as male
     *
     * @example
     * FamilyTreeBuilder._isMaleName('Jacob Varkey');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isMaleName('Annamma');
     * // => false
     */
    static _isMaleName(name) {
        if (!name) return false;
        const lower = name.toLowerCase().trim();
        if (FamilyTreeBuilder._dynamicMaleNames && FamilyTreeBuilder._dynamicMaleNames.has(lower)) return true;
        const titleMatch = FamilyTreeBuilder.matchTitleOntology(lower);
        if (titleMatch) {
            if (titleMatch.gender === 'M') return true;
            if (titleMatch.gender === 'F') return false;
        }
        const maleNames = FamilyTreeBuilder._STATIC_MALE_NAMES;
        if (maleNames.has(lower)) return true;
        const tokens = lower.split(/\s+/);
        if (tokens.some(t => maleNames.has(t))) return true;
        if (tokens.some(t => FamilyTreeBuilder._dynamicMaleNames && FamilyTreeBuilder._dynamicMaleNames.has(t))) return true;
        if (lower.endsWith('appan') || lower.endsWith('son') || /\bson(?:\s+\d+)?$/i.test(lower) ||
            lower.endsWith('achan') || lower.endsWith('mon') ||
            lower.endsWith('ose') || lower.endsWith('ouse') || lower.endsWith('eph')) return true;
        return false;
    }

    /**
     * Checks if a name string represents a generic placeholder or kinship title
     * (e.g. "Wife", "Husband", "Ghost", "Unknown", "Son", "Daughter", "Brother", "Sister").
     * 
     * @param {string} name - Name string
     * @returns {boolean} True if the name is a generic placeholder or relative title
     *
     * @example
     * FamilyTreeBuilder._isGenericKinshipName('unni wife');
     * // => true
     * 
     * @example
     * FamilyTreeBuilder._isGenericKinshipName('mini');
     * // => false
     */
    static _isGenericKinshipName(name) {
        if (!name) return false;
        const norm = name.toLowerCase().trim();
        const keywords = ['wife', 'husband', 'ghost', 'unknown', 'father', 'mother', 'brother', 'sister', 'son', 'daughter'];
        return keywords.some(kw => norm.includes(kw));
    }

    /**
     * Checks whether a claimant person explicitly declared a target person as their spouse,
     * considering primary names, nicknames, and multi-spouse lists.
     * 
     * @param {Object} claimant - Person declaring a spouse
     * @param {Object} target - Person being evaluated as spouse
     * @returns {boolean} True if claimant's spouse declaration matches target
     *
     * @example
     * FamilyTreeBuilder._claimsAsSpouse({ spouse: 'Mini' }, { _normName: 'mini', nick: '' });
     * // => true
     * 
     * @example
     * FamilyTreeBuilder._claimsAsSpouse({ spouse: 'Hus: Lab tech Fee Col' }, { _normName: 'unni', nick: '' });
     * // => false
     */
    static _claimsAsSpouse(claimant, target) {
        if (!claimant || !claimant.spouse || !target) return false;
        const declared = claimant.spouse.toLowerCase().trim();
        if (!declared) return false;

        const matchesTarget = (name) => {
            if (!name) return false;
            return !FamilyTreeBuilder._hasNameConflict(declared, name);
        };

        if (matchesTarget(target._normName)) return true;
        if (target.nick && matchesTarget(target.nick.toLowerCase().trim())) return true;
        return false;
    }

    /**
     * Checks if a name string matches a generic relative or placeholder pattern (e.g. "Son 1", "Wife").
     *
     * @param {string} name - Person name string
     * @returns {boolean} True if matching relative pattern
     *
     * @example
     * FamilyTreeBuilder._isRelativeName('Thomas Son 1');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isRelativeName('Thomas');
     * // => false
     */
    static _isRelativeName(name) {
        if (!name) return false;
        return /^(?:.+?\s+)?(?:Husband|Wife|Spouse|Partner|Son|Daughter|Boy|Girl|Brother|Sister|Father|Mother)(?:\s*\d+)?$/i.test(name.trim());
    }

    /**
     * Checks if a name string matches a generic child placeholder pattern (e.g. "Son 1", "Daughter 2", "Boy").
     *
     * @param {string} name - Person name string
     * @returns {boolean} True if matching relative child pattern
     *
     * @example
     * FamilyTreeBuilder._isRelativeChildName('Daughter 2');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isRelativeChildName('Wife');
     * // => false
     */
    static _isRelativeChildName(name) {
        if (!name) return false;
        return /^(?:.+?\s+)?(Son|Daughter|Boy|Girl)(?:\s*\d+)?$/i.test(name.trim());
    }

    /**
     * Determines whether a node is likely female based on gender, spouse metadata, occupation, or name patterns.
     *
     * @param {Object} node - Person node object
     * @returns {boolean} True if node is deduced as female
     *
     * @example
     * FamilyTreeBuilder._isNodeLikelyFemale({ gender: 'F' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isNodeLikelyFemale({ name: 'George', gender: 'M' });
     * // => false
     */
    static _isNodeLikelyFemale(node) {
        if (!node) return false;
        return node.gender === 'F' || node.spouseType === 'wife' ||
            Boolean(node.spouse && FamilyTreeBuilder._isMaleName(node.spouse)) ||
            (!FamilyTreeBuilder._isMaleName(node.name) && (node.name || '').toLowerCase().split(/\s+/).some(t => /(?:amma|mol|mary)$/i.test(t)));
    }

    /**
     * Deduces parent names and IDs for a newly synthesized child ghost relative node
     * based on the anchor parent's gender and spousal metadata.
     *
     * @param {Object} baseNode - The anchor parent Person node
     * @returns {{ mom: string, father: string, momId: string, fatherId: string, _namedParentId?: string, _namedParentName?: string }}
     *
     * @example
     * FamilyTreeBuilder._deduceGhostChildParents({ id: 'm1', name: 'Mary', gender: 'F', spouse: 'Joseph', spouseId: 'f1' });
     * // => { mom: 'Mary', father: 'Joseph', momId: 'm1', fatherId: 'f1' }
     *
     * @example
     * FamilyTreeBuilder._deduceGhostChildParents({ id: 'p1', name: 'Noble' });
     * // => { father: 'Noble', mom: '', fatherId: 'p1', momId: '', _namedParentId: 'p1', _namedParentName: 'Noble' }
     */
    static _deduceGhostChildParents(baseNode) {
        if (FamilyTreeBuilder._isNodeLikelyFemale(baseNode)) {
            return {
                mom: baseNode.name,
                father: baseNode.spouse || '',
                momId: baseNode.id,
                fatherId: baseNode.spouseId || ''
            };
        }
        if (baseNode.gender === 'M') {
            return {
                father: baseNode.name,
                mom: baseNode.spouse || '',
                fatherId: baseNode.id,
                momId: baseNode.spouseId || ''
            };
        }

        const fatherName = !baseNode.mom ? baseNode.name : (baseNode.spouse || '');
        return {
            father: fatherName,
            mom: baseNode.spouse || '',
            fatherId: (fatherName && fatherName === baseNode.name) ? baseNode.id : (baseNode.spouseId || ''),
            momId: baseNode.spouseId || '',
            _namedParentId: baseNode.id,
            _namedParentName: baseNode.name
        };
    }

    /**
     * Deduces parent names and IDs for a newly synthesized ghost relative node.
     *
     * @param {Object} baseNode - The anchor Person node
     * @param {boolean} isSibling - Whether the ghost is a sibling vs child
     * @param {string} [targetMom=''] - Target mother name for siblings
     * @param {string} [targetDad=''] - Target father name for siblings
     * @returns {{ mom: string, father: string, momId: string, fatherId: string }}
     *
     * @example
     * FamilyTreeBuilder._deduceGhostRelativeParents({ id: 'm1', name: 'Mary', gender: 'F' }, false);
     * // => { mom: 'Mary', father: '', momId: 'm1', fatherId: '' }
     *
     * @example
     * FamilyTreeBuilder._deduceGhostRelativeParents({ momId: 'm1', fatherId: 'f1' }, true, 'Mary', 'Joseph');
     * // => { mom: 'Mary', father: 'Joseph', momId: 'm1', fatherId: 'f1' }
     */
    static _deduceGhostRelativeParents(baseNode, isSibling, targetMom, targetDad) {
        if (isSibling) {
            return {
                mom: targetMom || '',
                father: targetDad || '',
                momId: baseNode.momId || '',
                fatherId: baseNode.fatherId || ''
            };
        }
        return FamilyTreeBuilder._deduceGhostChildParents(baseNode);
    }
    /**
     * Inherits spreadsheet row mappings and provenance references from a base node.
     *
     * @param {Object} baseNode - Originating person node
     * @returns {{ _sheetRows: Object<string, number>, _allSourceRefs: Object[] }} Inherited tracking metadata
     *
     * @example
     * const tracking1 = FamilyTreeBuilder._inheritSourceTracking({ _sheetRows: { s1: 10 }, _allSourceRefs: [{ sheetId: 's1', row: 10 }] });
     *
     * @example
     * const tracking2 = FamilyTreeBuilder._inheritSourceTracking({ _sourceId: 's2', _sheetRow: 5 });
     */
    static _inheritSourceTracking(baseNode) {
        const _sheetRows = baseNode._sheetRows
            ? { ...baseNode._sheetRows }
            : (baseNode._sourceId && baseNode._sheetRow ? { [baseNode._sourceId]: baseNode._sheetRow } : {});
        const _allSourceRefs = baseNode._allSourceRefs
            ? [...baseNode._allSourceRefs]
            : (baseNode._sourceId && baseNode._sheetRow ? [{ sheetId: baseNode._sourceId, row: baseNode._sheetRow }] : []);
        return { _sheetRows, _allSourceRefs };
    }

    /**
     * Synthesizes display name, role-based raw ID, and unique identifier for a deduced ghost entity.
     *
     * @private
     * @param {Object} params
     * @param {Object} params.baseNode - Base profile node
     * @param {string} params.role - Relative role name (e.g. 'son', 'sister')
     * @param {number} params.index - Ordinal index among siblings
     * @param {number} params.totalCount - Total count of relatives in group
     * @param {number} params.nodeCount - Current tree node count
     * @param {number} params.newNodeCount - Newly added node counter
     * @returns {{ name: string, rawId: string, id: string }} Synthesized identity properties
     *
     * @example
     * FamilyTreeBuilder._buildGhostIdentity({ baseNode: { name: 'John', _sourceId: 's1' }, role: 'son', index: 1, totalCount: 1, nodeCount: 10, newNodeCount: 1 });
     * // => { name: 'John Son', rawId: 'ghost_son_10_1', id: 'ghost_John_Son_s1_11' }
     *
     * @example
     * FamilyTreeBuilder._buildGhostIdentity({ baseNode: { name: 'Mary', _sourceId: 's1' }, role: 'daughter', index: 2, totalCount: 2, nodeCount: 5, newNodeCount: 1 });
     * // => { name: 'Mary Daughter 2', rawId: 'ghost_daughter_5_1', id: 'ghost_Mary_Daughter_2_s1_6' }
     */
    static _buildGhostIdentity({ baseNode, role, index, totalCount, nodeCount, newNodeCount }) {
        const titleCaseRole = role.charAt(0).toUpperCase() + role.slice(1);
        const nameSuffix = totalCount > 1 ? ` ${index}` : '';
        const name = `${baseNode.name} ${titleCaseRole}${nameSuffix}`.trim();
        const rawId = `ghost_${role}_${nodeCount}_${newNodeCount}`;
        const id = `ghost_${name.replace(/\s+/g, '_')}_${baseNode._sourceId}_${nodeCount + newNodeCount}`;
        return { name, rawId, id };
    }

    /**
     * Assembles the person record object for a synthesized ghost relative entity.
     *
     * @param {Object} params
     * @param {string} params.rawId - Internal role-based identifier
     * @param {Object} params.baseNode - Base profile node
     * @param {Object<string, number>} params._sheetRows - Inherited sheet row mapping
     * @param {Object[]} params._allSourceRefs - Inherited source references
     * @param {string} params.id - Unique ghost entity ID
     * @param {string} params.name - Synthesized display name
     * @param {string} params.gender - Assigned gender ('M' | 'F')
     * @param {string} params.mom - Mother's name
     * @param {string} params.father - Father's name
     * @param {string} params.momId - Mother's entity ID
     * @param {string} params.fatherId - Father's entity ID
     * @param {boolean} params.isSibling - Whether ghost is a sibling of baseNode
     * @returns {Object} Complete ghost person record
     *
     * @example
     * FamilyTreeBuilder._assembleGhostRelativeRecord({ rawId: 'g1', baseNode: { id: 'p1', _sourceId: 's1' }, _sheetRows: {}, _allSourceRefs: [], id: 'ghost_1', name: 'Ghost', gender: 'M', mom: '', father: '', momId: '', fatherId: '', isSibling: false });
     * // => { id: 'ghost_1', name: 'Ghost', isGhost: true, ... }
     *
     * @example
     * FamilyTreeBuilder._assembleGhostRelativeRecord({ rawId: 'g2', baseNode: { id: 'p2', name: 'Base', _sourceId: 's1' }, _sheetRows: {}, _allSourceRefs: [], id: 'ghost_2', name: 'Base Brother', gender: 'M', mom: 'Mom', father: 'Dad', momId: 'm1', fatherId: 'd1', isSibling: true });
     * // => { id: 'ghost_2', explicitSiblings: ['p2'], ... }
     */
    static _assembleGhostRelativeRecord({ rawId, baseNode, _sheetRows, _allSourceRefs, id, name, gender, mom, father, momId, fatherId, isSibling }) {
        return {
            _rawId: rawId,
            _sourceId: baseNode._sourceId,
            _sourceIds: new Set([baseNode._sourceId]),
            _sheetRows,
            _allSourceRefs,
            id,
            name,
            _normName: name.toLowerCase().trim(),
            gender,
            isGhost: true,
            mom,
            father,
            momId,
            fatherId,
            _namedParentId: isSibling ? '' : baseNode.id,
            _namedParentName: isSibling ? '' : baseNode.name,
            explicitSiblings: isSibling ? [baseNode.id] : [],
            partners: [],
            children: [],
            ambiguities: []
        };
    }

    /**
     * Factory function to create a ghost Person entity for unlisted relatives deduced from text.
     * 
     * @param {Object} params - Relative instantiation parameters
     * @returns {Object} Initialized ghost node
     *
     * @example
     * const ghost = FamilyTreeBuilder._createGhostRelative({ baseNode: { name: 'John', _sourceId: 's1' }, role: 'son', index: 1, totalCount: 1, gender: 'M', isSibling: false, nodeCount: 10, newNodeCount: 1 });
     * // => { name: 'John Son', isGhost: true, gender: 'M', ... }
     *
     * @example
     * const ghost = FamilyTreeBuilder._createGhostRelative({ baseNode: { name: 'Mary', _sourceId: 's1' }, role: 'sister', index: 1, totalCount: 2, gender: 'F', isSibling: true, nodeCount: 5, newNodeCount: 1 });
     * // => { name: 'Mary Sister 1', isGhost: true, gender: 'F', ... }
     */
    static _createGhostRelative({ baseNode, role, index, totalCount, gender, isSibling, nodeCount, newNodeCount, targetMom, targetDad }) {
        const { name, rawId, id } = FamilyTreeBuilder._buildGhostIdentity({ baseNode, role, index, totalCount, nodeCount, newNodeCount });
        const { mom, father, momId, fatherId } = FamilyTreeBuilder._deduceGhostRelativeParents(baseNode, isSibling, targetMom, targetDad);
        const { _sheetRows, _allSourceRefs } = FamilyTreeBuilder._inheritSourceTracking(baseNode);

        return FamilyTreeBuilder._assembleGhostRelativeRecord({
            rawId, baseNode, _sheetRows, _allSourceRefs, id, name, gender,
            mom, father, momId, fatherId, isSibling
        });
    }

    /**
     * Collects and sorts children of a parent with a specific partner chronologically.
     *
     * @param {Object} parent - Parent profile
     * @param {Object} partner - Partner profile
     * @param {Object} nodeMap - Map of node IDs to Person nodes
     * @param {Function} getYob - Accessor for effective birth year
     * @returns {Array<Object>} Children sorted by YOB, then by sheet row
     *
     * @example
     * FamilyTreeBuilder._collectPartnerChildren({ children: ['c1'] }, { id: 'p1', _normName: 'mary' }, { c1: { momId: 'p1' } }, p => p.yob);
     * // => [{ momId: 'p1' }]
     *
     * @example
     * FamilyTreeBuilder._collectPartnerChildren({ children: [] }, null, {}, p => p.yob);
     * // => []
     */
    static _collectPartnerChildren(parent, partner, nodeMap, getYob) {
        if (!parent.children || !nodeMap) return [];
        const partnerNorm = partner ? partner._normName : '';
        const partnerId = partner ? partner.id : '';
        const children = parent.children
            .map(cid => nodeMap[cid])
            .filter(c => c && (c.momId === partnerId || (partnerNorm && (c.mother || '').toLowerCase().trim() === partnerNorm)));

        return children.sort((a, b) => {
            const aYob = getYob(a), bYob = getYob(b);
            if (aYob && bYob) return aYob - bYob;
            return FamilyTreeBuilder.getNodeSheetRow(a, 0) - FamilyTreeBuilder.getNodeSheetRow(b, 0);
        });
    }

    /**
     * Compares two partner descriptors to establish chronological sequence in remarriage scenarios.
     * Evaluates explicit ordinal numbers, birth years, sheet row order, and children birth years.
     *
     * @param {Object} a - First partner descriptor with ptr, ord, firstChildYob, and firstChildRow
     * @param {Object} b - Second partner descriptor with ptr, ord, firstChildYob, and firstChildRow
     * @param {Function} getYob - Accessor returning effective birth year
     * @returns {number} Negative if a preceded b, positive if b preceded a, 0 if tied
     *
     * @example
     * FamilyTreeBuilder._compareRemarriagePartners({ ord: 1 }, { ord: 2 }, () => null);
     * // => -1
     *
     * @example
     * FamilyTreeBuilder._compareRemarriagePartners({ ord: null, ptr: { yob: 1910 } }, { ord: null, ptr: { yob: 1920 } }, p => p.yob);
     * // => -10
     */
    static _compareRemarriagePartners(a, b, getYob) {
        if (a.ord !== null && b.ord !== null) return a.ord - b.ord;
        if (a.ord === 1 && b.ord !== 1) return -1;
        if (b.ord === 1 && a.ord !== 1) return 1;
        if (a.ptr && b.ptr) {
            const yA = getYob(a.ptr), yB = getYob(b.ptr);
            if (yA && yB && yA !== yB) return yA - yB;
            const rA = FamilyTreeBuilder.getNodeSheetRow(a.ptr, null);
            const rB = FamilyTreeBuilder.getNodeSheetRow(b.ptr, null);
            if (rA !== null && rB !== null && FamilyTreeBuilder.sharesSheet(a.ptr, b.ptr)) {
                return rA - rB;
            }
        }
        if (a.firstChildYob && b.firstChildYob) return a.firstChildYob - b.firstChildYob;
        return a.firstChildRow - b.firstChildRow;
    }

    /**
     * Chronologically sorts a person's partners to determine order of marriage
     * based on partner birth years, child birth years, and spreadsheet row sequence.
     *
     * @param {Object} known - Person node whose partners are being ordered
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} nodeMap - Map of node IDs to Person instances
     * @returns {Array<{ptr: Object, ord: number|null, firstChildYob: number|null, firstChildRow: number, children: Array<Object>}>} Sorted partner records
     *
     * @example
     * FamilyTreeBuilder._sortPartnersForRemarriage({ partners: ['p1', 'p2'] }, p => p.yob, { p1: { yob: 1910 }, p2: { yob: 1915 } });
     * // => [{ ptr: { yob: 1910 }, ... }, { ptr: { yob: 1915 }, ... }]
     *
     * @example
     * FamilyTreeBuilder._sortPartnersForRemarriage({ partners: [] }, p => p.yob, {});
     * // => []
     */
    static _sortPartnersForRemarriage(known, getYob, nodeMap) {
        return (known.partners || []).map(pid => {
            const ptr = nodeMap[pid];
            const ptrChildren = FamilyTreeBuilder._collectPartnerChildren(known, ptr, nodeMap, getYob);
            const firstChild = ptrChildren[0];
            return {
                ptr,
                ord: FamilyTree._extractPartnerOrdinal(ptr),
                firstChildYob: firstChild ? getYob(firstChild) : null,
                firstChildRow: ptrChildren.length ? FamilyTreeBuilder.getNodeSheetRow(ptrChildren[0], 99999) : 99999,
                children: ptrChildren
            };
        }).sort((a, b) => FamilyTreeBuilder._compareRemarriagePartners(a, b, getYob));
    }

    /**
     * Applies inferred birth year calculation to a subsequent wife based on previous wife's last child.
     *
     * @param {Object} unknown - Subsequent wife person node
     * @param {number} lastPrevChildYob - Birth year of the previous wife's last child
     * @returns {boolean} True if inferred YOB was updated, false if unchanged
     *
     * @example
     * FamilyTreeBuilder._applySubsequentWifeYob(wifeNode, 1920);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._applySubsequentWifeYob({ yob: 0, _inferredYob: 1902 }, 1920);
     * // => false
     */
    static _applySubsequentWifeYob(unknown, lastPrevChildYob) {
        const firstMarriageAge = FamilyTreeBuilder.GENERATIONAL_GAPS.DEFAULT_FIRST_MARRIAGE_AGE_FEMALE ||
                                 FamilyTreeBuilder.GENERATIONAL_GAPS.SECOND_WIFE_MARRIAGE_AGE;
        const inferred = lastPrevChildYob - firstMarriageAge;
        if (unknown._inferredYob !== inferred || unknown.yob !== 0) {
            unknown.yob = 0;
            unknown._inferredYob = inferred;
            unknown._isSecondWifeInferred = true;
            return true;
        }
        return false;
    }

    /**
     * Estimates the birth year of a subsequent/second wife based on the last child
     * of the previous wife, assuming marriage at ~18 years of age.
     *
     * @param {Object} known - Husband node with multiple partners
     * @param {Object} unknown - Subsequent wife whose birth year is being estimated
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} [nodeMap] - Map of node IDs to Person instances
     * @returns {boolean|null} True if inferred YOB set, false if waiting/unchanged, null if not a subsequent wife
     *
     * @example
     * FamilyTreeBuilder._inferSubsequentWifeYob(husbandNode, secondWifeNode, getYob, nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferSubsequentWifeYob({ partners: ['p1'] }, secondWifeNode, getYob, nodeMap);
     * // => null
     */
    static _inferSubsequentWifeYob(known, unknown, getYob, nodeMap) {
        if (!known.partners || known.partners.length <= 1 || !known.children || known.children.length === 0 || !nodeMap) {
            return null;
        }

        const partnersWithFirstChildRow = FamilyTreeBuilder._sortPartnersForRemarriage(known, getYob, nodeMap);
        const uIndex = partnersWithFirstChildRow.findIndex(pt => pt.ptr && pt.ptr.id === unknown.id);
        if (uIndex <= 0) return null;

        const prevPartnerInfo = partnersWithFirstChildRow[uIndex - 1];
        if (prevPartnerInfo.children.length === 0) return null;

        const lastPrevChild = prevPartnerInfo.children[prevPartnerInfo.children.length - 1];
        const lastPrevChildYob = getYob(lastPrevChild);
        return lastPrevChildYob ? FamilyTreeBuilder._applySubsequentWifeYob(unknown, lastPrevChildYob) : false;
    }

    /**
     * Identifies spousal gender roles between two married partners.
     * 
     * @param {Object} known - Spouse node with known birth year
     * @param {Object} unknown - Spouse node whose birth year is being evaluated
     * @returns {{ isKHusband: boolean, isKWife: boolean }}
     *
     * @example
     * FamilyTreeBuilder._determineSpousalRoles({ gender: 'M' }, { gender: 'F' });
     * // => { isKHusband: true, isKWife: false }
     *
     * @example
     * FamilyTreeBuilder._determineSpousalRoles({ gender: 'F' }, { gender: 'M' });
     * // => { isKHusband: false, isKWife: true }
     */
    static _determineSpousalRoles(known, unknown) {
        let isKHusband = false, isKWife = false;
        if (known.gender === 'M' || unknown.gender === 'F') isKHusband = true;
        else if (known.gender === 'F' || unknown.gender === 'M') isKWife = true;
        else if (known.spouseType === 'wife' || unknown.spouseType === 'husband') isKHusband = true;
        else if (known.spouseType === 'husband' || unknown.spouseType === 'wife') isKWife = true;
        return { isKHusband, isKWife };
    }

    /**
     * Deduces a wife's birth year given a known husband's birth year and subsequent wife offsets.
     * 
     * @param {Object} knownHusband - Husband node with known birth year
     * @param {Object} unknownWife - Wife node to infer birth year for
     * @param {number} kYob - Husband's birth year
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} [nodeMap] - Mapping of node IDs to Person nodes
     * @returns {boolean}
     *
     * @example
     * FamilyTreeBuilder._inferWifeYobFromHusband({ id: 'h1' }, { id: 'w1' }, 1950, p => p.yob, {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferWifeYobFromHusband({ id: 'h1' }, { id: 'w1', yob: 1952 }, 1950, p => p.yob, {});
     * // => false
     */
    static _inferWifeYobFromHusband(knownHusband, unknownWife, kYob, getYob, nodeMap) {
        const subsequentResult = FamilyTreeBuilder._inferSubsequentWifeYob(knownHusband, unknownWife, getYob, nodeMap);
        if (subsequentResult !== null) return subsequentResult;

        if (unknownWife.yob) return false;
        const expectedYob = kYob + FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET;
        if (unknownWife.death && expectedYob > unknownWife.death) return false;
        if (!unknownWife._inferredYob || unknownWife._inferredYob < expectedYob) {
            unknownWife._inferredYob = expectedYob;
            return true;
        }
        return false;
    }

    /**
     * Deduces a husband's birth year given a known wife's birth year.
     * 
     * @param {Object} knownWife - Wife node with known birth year
     * @param {Object} unknownHusband - Husband node to infer birth year for
     * @param {number} kYob - Wife's birth year
     * @returns {boolean}
     *
     * @example
     * FamilyTreeBuilder._inferHusbandYobFromWife({ id: 'w1' }, { id: 'h1' }, 1952);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferHusbandYobFromWife({ id: 'w1' }, { id: 'h1', yob: 1950 }, 1952);
     * // => false
     */
    static _inferHusbandYobFromWife(knownWife, unknownHusband, kYob) {
        if (unknownHusband.yob) return false;
        const expectedYob = kYob - FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET;
        if (unknownHusband.death && expectedYob > unknownHusband.death) return false;
        if (!unknownHusband._inferredYob || unknownHusband._inferredYob > expectedYob) {
            unknownHusband._inferredYob = expectedYob;
            return true;
        }
        return false;
    }

    /**
     * Infers the birth year of one spouse from a known partner.
     * Accounts for standard spousal offsets (husband 2 years older than wife)
     * and sequential remarriages where later wives have their birth year constrained
     * based on the last child of the preceding wife.
     * 
     * @param {Object} known - Spouse with determined YOB
     * @param {Object} unknown - Spouse whose YOB is to be inferred
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} [nodeMap] - Mapping of node IDs to Person nodes
     * @returns {boolean} True if an inferred YOB was set on unknown spouse
     * 
     * @example
     * FamilyTreeBuilder._inferSingleSpouseYob({ gender: 'M', yob: 1950 }, { gender: 'F' }, p => p.yob, {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferSingleSpouseYob({ yob: 1950 }, { yob: 1952, _hasExplicitYob: true }, p => p.yob, {});
     * // => false
     */
    static _inferSingleSpouseYob(known, unknown, getYob, nodeMap) {
        const kYob = getYob(known);
        if (!kYob) return false;
        if (unknown._hasExplicitYob) return false;

        const { isKHusband, isKWife } = FamilyTreeBuilder._determineSpousalRoles(known, unknown);

        if (isKHusband) {
            return FamilyTreeBuilder._inferWifeYobFromHusband(known, unknown, kYob, getYob, nodeMap);
        }

        if (isKWife) {
            return FamilyTreeBuilder._inferHusbandYobFromWife(known, unknown, kYob);
        }

        // Unknown gender fallback: assume same age
        if (!unknown._inferredYob) {
            unknown._inferredYob = kYob;
            return true;
        }
        return false;
    }

    /**
     * Symmetrically propagates inferred birth years between married partners.
     * 
     * @param {Object} n - First spouse node
     * @param {Object} p - Second spouse node
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} [nodeMap] - Mapping of node IDs to Person nodes
     * @returns {boolean} True if an inferred YOB was set on either spouse
     *
     * @example
     * FamilyTreeBuilder._propagateSpouseYobs({ gender: 'M', yob: 1950 }, { gender: 'F' }, p => p.yob, {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._propagateSpouseYobs({ yob: 1950 }, { yob: 1952, _hasExplicitYob: true }, p => p.yob, {});
     * // => false
     */
    static _propagateSpouseYobs(n, p, getYob, nodeMap) {
        return FamilyTreeBuilder._inferSingleSpouseYob(n, p, getYob, nodeMap) ||
               FamilyTreeBuilder._inferSingleSpouseYob(p, n, getYob, nodeMap);
    }

    /**
     * Infers child birth year from parent birth year and generational gap if unknown.
     *
     * @param {number|null} parentYob - Known birth year of parent
     * @param {Object} firstChild - Child node whose birth year may be inferred
     * @param {number} gap - Generational gap in years
     * @returns {boolean} True if child._inferredYob was assigned
     *
     * @example
     * FamilyTreeBuilder._inferDownwardChildYob(1950, { yob: 0 }, 24);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferDownwardChildYob(1950, { yob: 1974 }, 24);
     * // => false
     */
    static _inferDownwardChildYob(parentYob, firstChild, gap) {
        if (parentYob && !firstChild.yob && !firstChild._inferredYob) {
            firstChild._inferredYob = parentYob + gap;
            return true;
        }
        return false;
    }

    /**
     * Infers parent birth year from child birth year and generational gap if unknown.
     * When parent is a wife with a known husband, her inferred birth year is bounded
     * so that she cannot be older than her husband plus the spousal offset.
     *
     * @param {number|null} childYob - Known birth year of child
     * @param {Object} parent - Parent node whose birth year may be inferred
     * @param {number} gap - Generational gap in years
     * @param {Object} [nodeMap=null] - Mapping of node IDs to Person nodes
     * @returns {boolean} True if parent._inferredYob was assigned or updated to an earlier year
     *
     * @example
     * FamilyTreeBuilder._inferUpwardParentYob(1974, { yob: 0 }, 24);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._inferUpwardParentYob(1974, { yob: 1950 }, 24);
     * // => false
     */
    static _inferUpwardParentYob(childYob, parent, gap, nodeMap = null) {
        if (!childYob || parent.yob || parent._isSecondWifeInferred || parent._isAutoPartner) {
            return false;
        }

        let newParentYob = childYob - gap;

        // Walking up from a child can push a mother's birth year implausibly early. Clamp it so she
        // is never inferred to be older than her husband allows under the spousal age convention.
        const wifeYobFloor = FamilyTreeBuilder._resolveWifeYobFloor(parent, nodeMap);
        if (wifeYobFloor !== null && newParentYob < wifeYobFloor) {
            newParentYob = wifeYobFloor;
        }

        // Keep the earliest estimate seen so far: a parent must predate every child claiming them.
        if (!parent._inferredYob || newParentYob < parent._inferredYob) {
            parent._inferredYob = newParentYob;
            return true;
        }
        return false;
    }

    /**
     * Computes the earliest birth year a wife may plausibly have, given her recorded husbands.
     *
     * Husbands are assumed to be `SPOUSAL_GENDER_OFFSET` years older than their wives, so each
     * husband implies a lower bound of `husbandYob + offset`. The most restrictive (latest) of
     * those bounds wins. Partners of unknown gender are only trusted as husbands when they carry
     * a birth year, since an undated unknown partner tells us nothing.
     *
     * @param {Object} parent - Candidate wife node
     * @param {Object|null} nodeMap - Mapping of node IDs to Person nodes
     * @returns {number|null} Earliest plausible birth year, or null when no bound applies
     *
     * @example
     * FamilyTreeBuilder._resolveWifeYobFloor({ gender: 'F', partners: ['h1'] }, { h1: { gender: 'M', yob: 1920 } });
     * // => 1922
     *
     * @example
     * FamilyTreeBuilder._resolveWifeYobFloor({ gender: 'M', partners: ['w1'] }, { w1: { yob: 1930 } });
     * // => null (only wives are clamped)
     */
    static _resolveWifeYobFloor(parent, nodeMap) {
        if (parent.gender !== 'F' || !parent.partners || parent.partners.length === 0 || !nodeMap) {
            return null;
        }

        let floor = null;
        for (const pid of parent.partners) {
            const partner = nodeMap[pid];
            if (!partner) continue;

            const isHusbandLike = partner.gender === 'M' || (!partner.gender && (partner.yob || partner._inferredYob));
            if (!isHusbandLike) continue;

            const husbandYob = partner.yob || partner._inferredYob;
            if (!husbandYob) continue;

            const minWifeYob = husbandYob + FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET;
            if (floor === null || minWifeYob > floor) floor = minWifeYob;
        }
        return floor;
    }

    /**
     * Propagates inferred birth years between parent and first-born child using generational gaps.
     * Incurs maternal (24 years) or paternal (26 years) gap depending on parent gender.
     *
     * @param {Object} parent - Parent node with known or unknown birth year
     * @param {Object} firstChild - Eldest child node with known or unknown birth year
     * @param {Function} getYob - Accessor for effective birth year
     * @param {Object} [nodeMap=null] - Mapping of node IDs to Person nodes
     * @returns {boolean} True if birth year was newly inferred
     *
     * @example
     * const mom = { gender: 'F', yob: 1950 };
     * const child = { momId: mom.id };
     * FamilyTreeBuilder._propagateParentChildYobs(mom, child, p => p.yob);
     * // => true (child._inferredYob set to 1974)
     *
     * @example
     * const dad = { gender: 'M' };
     * const child = { fatherId: dad.id, yob: 1976 };
     * FamilyTreeBuilder._propagateParentChildYobs(dad, child, p => p.yob);
     * // => true (dad._inferredYob set to 1950)
     */
    static _propagateParentChildYobs(parent, firstChild, getYob, nodeMap = null) {
        const isMother = parent.gender === 'F' || firstChild.momId === parent.id;
        const isFather = parent.gender === 'M' || firstChild.fatherId === parent.id;
        const isNamedParent = firstChild._namedParentId === parent.id;
        const gap = isMother ? FamilyTreeBuilder.GENERATIONAL_GAPS.MATERNAL_FIRST_CHILD :
                    isFather ? FamilyTreeBuilder.GENERATIONAL_GAPS.PATERNAL_FIRST_CHILD :
                    isNamedParent ? 25 : 0;
        if (!gap) return false;

        const parentYob = getYob(parent);
        if (FamilyTreeBuilder._inferDownwardChildYob(parentYob, firstChild, gap)) {
            return true;
        }

        const childYob = getYob(firstChild);
        return FamilyTreeBuilder._inferUpwardParentYob(childYob, parent, gap, nodeMap);
    }

    /**
     * Resolves the primary/minimum effective spreadsheet row number for a node.
     * Returns 99999 if no row number is known.
     *
     * @param {Object} node - Person or raw row node
     * @returns {number} Minimum effective row number
     *
     * @example
     * FamilyTreeBuilder._getNodeEffectiveRow({ _sheetRows: { 's1': 42 } });
     * // => 42
     *
     * @example
     * FamilyTreeBuilder._getNodeEffectiveRow(null);
     * // => 99999
     */
    static _getNodeEffectiveRow(node) {
        return FamilyTreeBuilder.getNodeSheetRow(node, 99999);
    }

    /**
     * Sorts siblings chronologically: explicit YOB first, then same-sheet row order, then inferred YOB.
     *
     * @param {Object[]} siblings - List of sibling nodes
     * @param {Function} getYob - Function returning effective birth year
     * @returns {Object[]} Sorted array of siblings
     *
     * @example
     * FamilyTreeBuilder._sortSiblingsChronologically([{ name: 'B', yob: 1980 }, { name: 'A', yob: 1975 }], p => p.yob);
     * // => [{ name: 'A', yob: 1975 }, { name: 'B', yob: 1980 }]
     *
     * @example
     * FamilyTreeBuilder._sortSiblingsChronologically([{ name: 'Bob', _sheetRow: 5 }, { name: 'Alice', _sheetRow: 2 }], p => p.yob);
     * // => [{ name: 'Alice', _sheetRow: 2 }, { name: 'Bob', _sheetRow: 5 }]
     */
    static _sortSiblingsChronologically(siblings, getYob) {
        return [...siblings].sort((a, b) => {
            if (a.yob && b.yob && a.yob !== b.yob) return a.yob - b.yob;
            const numA = FamilyTreeBuilder._parseNumberedSiblingRole(a);
            const numB = FamilyTreeBuilder._parseNumberedSiblingRole(b);
            if (numA && numB && numA.role === numB.role && numA.num !== numB.num) {
                return numA.num - numB.num;
            }
            const rA = FamilyTreeBuilder._getNodeEffectiveRow(a);
            const rB = FamilyTreeBuilder._getNodeEffectiveRow(b);
            if (rA < 99999 && rB < 99999 && rA !== rB && FamilyTreeBuilder.sharesSheet(a, b)) {
                return rA - rB;
            }
            const yA = getYob(a), yB = getYob(b);
            if (yA && yB && yA !== yB) return yA - yB;
            const nameA = a.name || '';
            const nameB = b.name || '';
            return nameA.localeCompare(nameB);
        });
    }

    /**
     * Determines whether the spreadsheet asserts a definite birth order between
     * two siblings, i.e. whether `elder` is genuinely known to precede `younger`.
     *
     * Seniority is only claimed when the sheet actually states it: by row order
     * on a shared sheet, or by matching numbered roles ("Son 1" before "Son 2").
     * Siblings the sheet leaves unordered report no seniority, so a guessed birth
     * year is never allowed to override a stated one.
     *
     * @param {Object} elder - Sibling claimed to be older
     * @param {Object} younger - Sibling claimed to be younger
     * @returns {boolean} True if the sheet establishes elder before younger
     *
     * @example
     * FamilyTreeBuilder._hasSiblingSeniority({ _sheetRow: 10 }, { _sheetRow: 12 });
     * // => true (row order on the same sheet)
     *
     * @example
     * FamilyTreeBuilder._hasSiblingSeniority({ name: 'Son 2' }, { name: 'Son 1' });
     * // => false (numbered roles contradict the claim)
     */
    static _hasSiblingSeniority(elder, younger) {
        const rElder = FamilyTreeBuilder._getNodeEffectiveRow(elder);
        const rYounger = FamilyTreeBuilder._getNodeEffectiveRow(younger);

        const hasRowOrder = rElder < 99999 && rYounger < 99999 && rElder < rYounger
            && FamilyTreeBuilder.sharesSheet(elder, younger);

        const numElder = FamilyTreeBuilder._parseNumberedSiblingRole(elder);
        const numYounger = FamilyTreeBuilder._parseNumberedSiblingRole(younger);
        const hasNumberedRoleOrder =
            numElder && numYounger && numElder.role === numYounger.role && numElder.num < numYounger.num;

        return Boolean(hasRowOrder || hasNumberedRoleOrder);
    }

    /**
     * Pushes an adjacent sibling's inferred birth year to respect a minimum gap
     * from an anchor sibling whose birth year is already known.
     *
     * A target with no birth year at all is always seeded. A target that already
     * has an inferred (but not explicit) birth year is only corrected when the
     * sheet actually establishes the birth order, so a guess never overrides a
     * stated fact.
     *
     * @param {Object} anchor - Sibling with a known birth year
     * @param {Object} target - Adjacent sibling being constrained
     * @param {Function} getYob - YOB accessor
     * @param {number} gap - Minimum generational gap (typically 2 years)
     * @param {number} direction - +1 when target is younger, -1 when target is older
     * @returns {boolean} True if the target's inferred birth year was updated
     *
     * @example
     * const anchor = { yob: 1980 }, target = {};
     * FamilyTreeBuilder._propagateAdjacentSibling(anchor, target, p => p.yob, 2, 1);
     * // => true (target._inferredYob is 1982)
     *
     * @example
     * const anchorYounger = { yob: 1984 }, targetOlder = {};
     * FamilyTreeBuilder._propagateAdjacentSibling(anchorYounger, targetOlder, p => p.yob, 2, -1);
     * // => true (targetOlder._inferredYob is 1982)
     */
    static _propagateAdjacentSibling(anchor, target, getYob, gap, direction) {
        const anchorYob = getYob(anchor);
        if (!anchorYob) return false;

        const bound = anchorYob + (direction * gap);

        if (!getYob(target)) {
            target._inferredYob = bound;
            return true;
        }

        const [elder, younger] = direction > 0 ? [anchor, target] : [target, anchor];
        const violatesBound = direction > 0 ? target._inferredYob < bound : target._inferredYob > bound;

        if (FamilyTreeBuilder._hasSiblingSeniority(elder, younger)
            && !target.yob && target._inferredYob && violatesBound) {
            target._inferredYob = bound;
            return true;
        }
        return false;
    }

    /**
     * Forward propagation between consecutive siblings: older node constrains younger node.
     *
     * @param {Object} currNode - Preceding (older) sibling
     * @param {Object} nextNode - Subsequent (younger) sibling
     * @param {Function} getYob - YOB accessor
     * @param {number} gap - Minimum generational gap (typically 2 years)
     * @returns {boolean} True if nextNode's inferred YOB was updated
     *
     * @example
     * const elder = { yob: 1980 };
     * const younger = {};
     * FamilyTreeBuilder._propagateAdjacentSiblingForward(elder, younger, p => p.yob, 2);
     * // => true (younger._inferredYob is 1982)
     *
     * @example
     * const elder = { yob: 1980 };
     * const younger = { yob: 1982 };
     * FamilyTreeBuilder._propagateAdjacentSiblingForward(elder, younger, p => p.yob, 2);
     * // => false
     */
    static _propagateAdjacentSiblingForward(currNode, nextNode, getYob, gap) {
        return FamilyTreeBuilder._propagateAdjacentSibling(currNode, nextNode, getYob, gap, 1);
    }

    /**
     * Backward propagation between consecutive siblings: younger node constrains older node.
     *
     * @param {Object} currNode - Subsequent (younger) sibling
     * @param {Object} prevNode - Preceding (older) sibling
     * @param {Function} getYob - YOB accessor
     * @param {number} gap - Minimum generational gap (typically 2 years)
     * @returns {boolean} True if prevNode's inferred YOB was updated
     *
     * @example
     * const younger = { yob: 1982 };
     * const elder = {};
     * FamilyTreeBuilder._propagateAdjacentSiblingBackward(younger, elder, p => p.yob, 2);
     * // => true (elder._inferredYob is 1980)
     *
     * @example
     * const younger = { yob: 1982 };
     * const elder = { yob: 1980 };
     * FamilyTreeBuilder._propagateAdjacentSiblingBackward(younger, elder, p => p.yob, 2);
     * // => false
     */
    static _propagateAdjacentSiblingBackward(currNode, prevNode, getYob, gap) {
        return FamilyTreeBuilder._propagateAdjacentSibling(currNode, prevNode, getYob, gap, -1);
    }

    /**
     * Propagates inferred birth years across a chronological list of siblings
     * with 2-year generational gaps, enforcing spreadsheet row order seniority.
     *
     * @param {Object[]} childNodes - Sibling nodes under a shared parent/couple
     * @param {Function} getYob - Accessor for effective birth year (explicit or inferred)
     * @returns {boolean} True if any sibling's inferred birth year was updated
     *
     * @example
     * const c1 = {}, c2 = {}, c3 = { yob: 1990 };
     * FamilyTreeBuilder._propagateSiblingYobs([c1, c2, c3], p => p.yob);
     * // => true (c2._inferredYob = 1988, c1._inferredYob = 1986)
     *
     * @example
     * const c1 = { yob: 1986 }, c2 = { yob: 1988 };
     * FamilyTreeBuilder._propagateSiblingYobs([c1, c2], p => p.yob);
     * // => false
     */
    static _propagateSiblingYobs(childNodes, getYob) {
        let changed = false;
        const gap = FamilyTreeBuilder.GENERATIONAL_GAPS.CONSECUTIVE_SIBLING || 2;
        const sorted = FamilyTreeBuilder._sortSiblingsChronologically(childNodes, getYob);

        // Forward pass: child[i] is older than child[i+1] (lower row number = older person)
        for (let i = 0; i < sorted.length - 1; i++) {
            if (FamilyTreeBuilder._propagateAdjacentSiblingForward(sorted[i], sorted[i + 1], getYob, gap)) {
                changed = true;
            }
        }

        // Backward pass: child[i] is younger than child[i-1]
        for (let i = sorted.length - 1; i > 0; i--) {
            if (FamilyTreeBuilder._propagateAdjacentSiblingBackward(sorted[i], sorted[i - 1], getYob, gap)) {
                changed = true;
            }
        }

        return changed;
    }

    /**
     * Collects the family names a candidate mother's husbands would pass down to her children.
     *
     * In patrilineal naming a child takes the father's family, so these are exactly
     * the family names her children are expected to carry. Already-linked partners
     * are authoritative; only when none of them records a family do we fall back to
     * looking up her declared spouse by name on her own sheet.
     *
     * @param {Object} candidate - Candidate mother node
     * @param {Object} [nodeMap={}] - Map of all nodes
     * @returns {Set<string>} Lower-cased family names, empty when nothing is recorded
     *
     * @example
     * FamilyTreeBuilder._collectSpouseFamilies({ partners: ['p1'] }, { p1: { family: 'Kizhakkumthala' } });
     * // => Set { 'kizhakkumthala' }
     *
     * @example
     * // Mariyakkutty has no linked partner yet, but her row declares Spouse: Thomas,
     * // and Thomas's row on the same sheet carries Family: Parathottiyil.
     * FamilyTreeBuilder._collectSpouseFamilies({ spouse: 'Thomas' }, nodeMapWithThomas);
     * // => Set { 'parathottiyil' }
     */
    static _collectSpouseFamilies(candidate, nodeMap = {}) {
        const families = new Set();
        const add = (f) => { const v = (f || '').toLowerCase().trim(); if (v) families.add(v); };

        for (const pid of (candidate.partners || [])) add(nodeMap[pid]?.family);
        if (families.size > 0) return families;

        const spouseNames = new Set([candidate.spouse, ...(candidate._localImplicitSpouses || [])]
            .filter(Boolean).map(s => s.toLowerCase().trim()));
        if (spouseNames.size === 0) return families;

        for (const n of Object.values(nodeMap)) {
            if (!n || !n.family || !FamilyTreeBuilder.sharesSheet(candidate, n)) continue;
            if (spouseNames.has((n.name || '').toLowerCase().trim())) add(n.family);
        }
        return families;
    }

    /**
     * Checks if a candidate mother's husband/partner family is compatible with the child's family name.
     * In patrilineal naming, a child belongs to the father's family, so the mother's husband should match childFamily.
     *
     * Silence is not a conflict: a candidate whose husband records no family at all
     * stays eligible. This is a veto, not evidence — for the positive form, see
     * `_resolveBySiblingBlockFamily`.
     *
     * @param {Object} candidate - Candidate mother node
     * @param {string} childFamily - Normalized family name of the child
     * @param {Object} [nodeMap={}] - Map of all nodes
     * @returns {boolean} False if candidate mother's partner has a conflicting family name
     *
     * @example
     * FamilyTreeBuilder._isMotherSpouseFamilyCompatible({ partners: ['p1'] }, 'Kizhakkumthala', { p1: { family: 'Kizhakkumthala' } });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isMotherSpouseFamilyCompatible({ partners: ['p1'] }, 'Kizhakkumthala', { p1: { family: 'OtherFamily' } });
     * // => false
     */
    static _isMotherSpouseFamilyCompatible(candidate, childFamily, nodeMap = {}) {
        if (!childFamily) return true;
        const families = FamilyTreeBuilder._collectSpouseFamilies(candidate, nodeMap);
        return families.size === 0 || families.has(childFamily.toLowerCase().trim());
    }

    /**
     * Checks whether a person matches a target parent name by name overlap, nickname overlap,
     * or lack of lexical name conflict.
     *
     * @param {Object} person - Candidate person node.
     * @param {string} parentName - Target parent name to compare.
     * @returns {boolean} True if person matches parentName.
     *
     * @example
     * FamilyTreeBuilder._isCandidateMatchingParentName({ name: 'Rosy Anthikkad' }, 'Rosy');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateMatchingParentName({ name: 'John Doe' }, 'Mary');
     * // => false
     */
    static _isCandidateMatchingParentName(person, parentName) {
        if (!person || !parentName) return false;
        return FamilyTreeBuilder._namesOverlap(person.name, parentName) ||
            (person.nick && FamilyTreeBuilder._namesOverlap(person.nick, parentName)) ||
            !FamilyTreeBuilder._hasNameConflict(person.name, parentName);
    }

    /**
     * Checks whether any of the candidate's existing partners are biological siblings
     * of individuals matching the target parent name.
     *
     * @param {Object} candidate - Candidate parent node.
     * @param {string} otherParentName - Name of the child's other parent.
     * @param {Object} [nodeMap={}] - Map of all nodes by ID.
     * @returns {boolean} True if a partner of candidate is a sibling of an otherParent candidate.
     *
     * @example
     * FamilyTreeBuilder._hasPartnerSiblingConflict(candWithJohny, 'Ousephunni', nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasPartnerSiblingConflict({ partners: [] }, 'Mary', {});
     * // => false
     */
    static _hasPartnerSiblingConflict(candidate, otherParentName, nodeMap = {}) {
        const otherParents = Object.values(nodeMap).filter(n =>
            FamilyTreeBuilder._isCandidateMatchingParentName(n, otherParentName)
        );
        return (candidate.partners || []).some(pid => {
            const p = nodeMap[pid];
            return p && otherParents.some(op => FamilyTreeBuilder._areBiologicalSiblings(p, op));
        });
    }

    /**
     * Checks if candidate parent's existing spouse conflicts with the other known parent name of the child.
     * 
     * @param {Object} candidate - Candidate parent node
     * @param {string} otherParentName - Name of the child's other parent (e.g. child.mom or child.father)
     * @param {Object} [nodeMap={}] - Map of all nodes
     * @returns {boolean} True if candidate's spouse conflicts with otherParentName
     * 
     * @example
     * FamilyTreeBuilder._hasSpouseConflictWithOtherParent(candWithJohny, 'Ousephunni', nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasSpouseConflictWithOtherParent(cand, '', nodeMap);
     * // => false
     */
    static _hasSpouseConflictWithOtherParent(candidate, otherParentName, nodeMap = {}) {
        if (!otherParentName) return false;
        if (FamilyTreeBuilder._namesOverlap(otherParentName, candidate.name)) return false;

        const isAlreadyPartner = (candidate.partners || []).some(pid =>
            FamilyTreeBuilder._isCandidateMatchingParentName(nodeMap[pid], otherParentName)
        );
        if (isAlreadyPartner) return false;

        if (FamilyTreeBuilder._hasPartnerSiblingConflict(candidate, otherParentName, nodeMap)) {
            return true;
        }

        if (candidate.gender === 'F' && candidate.partners && candidate.partners.length > 0) {
            const hasExplicitMulti = candidate.spouse && (candidate.spouse.includes(',') || candidate.spouse.includes('/'));
            if (!hasExplicitMulti) {
                return true;
            }
        }

        if (!candidate.spouse) return false;
        const candSpouses = candidate.spouse.split(/[,/]+/).map(s => s.trim()).filter(Boolean);
        return candSpouses.length === 1 && FamilyTreeBuilder._hasNameConflict(candSpouses[0], otherParentName);
    }

    /**
     * Finds nodes in nodeMap whose normalized name matches target and share the same sheet as refNode.
     *
     * @param {string} name - Name string to match against.
     * @param {Object} refNode - Reference node for sheet locality.
     * @param {Object} [nodeMap={}] - Map of ID to node objects.
     * @returns {Array<Object>} Array of matching same-sheet nodes.
     *
     * @example
     * FamilyTreeBuilder._findSameSheetCandidates('Joseph', { sheet: 'Parathottiyil' }, nodeMap);
     * // => [nodeJoseph]
     *
     * @example
     * FamilyTreeBuilder._findSameSheetCandidates('', { sheet: 'Parathottiyil' }, nodeMap);
     * // => []
     */
    static _findSameSheetCandidates(name, refNode, nodeMap = {}) {
        if (!name || !refNode) return [];
        const norm = name.toLowerCase().trim();
        return Object.values(nodeMap).filter(c =>
            c && c._normName === norm && FamilyTreeBuilder.sharesSheet(c, refNode)
        );
    }

    /**
     * Attempts to resolve family name patrilineally from father node or father string candidates.
     *
     * @param {Object} node - Subject person node.
     * @param {Object} nodeMap - Map of ID to node objects.
     * @param {Set<string>} visited - Cycle prevention visited set.
     * @returns {string} Resolved family name or empty string.
     *
     * @example
     * FamilyTreeBuilder._resolvePaternalFamilyName({ fatherId: 'dad_1' }, { dad_1: { family: 'Mecheri' } }, new Set());
     * // => 'mecheri'
     *
     * @example
     * FamilyTreeBuilder._resolvePaternalFamilyName({}, {}, new Set());
     * // => ''
     */
    static _resolvePaternalFamilyName(node, nodeMap, visited) {
        if (node.fatherId && nodeMap[node.fatherId]) {
            const fam = FamilyTreeBuilder._resolveFamilyName(nodeMap[node.fatherId], nodeMap, visited);
            if (fam) return fam;
        }
        if (node.father) {
            const dadCands = FamilyTreeBuilder._findSameSheetCandidates(node.father, node, nodeMap);
            for (const dad of dadCands) {
                const fam = FamilyTreeBuilder._resolveFamilyName(dad, nodeMap, visited);
                if (fam) return fam;
            }
        }
        return '';
    }

    /**
     * Attempts to resolve family name from a mother's partners or declared spouse candidates.
     *
     * @param {Object|null} mom - Mother node
     * @param {Object} nodeMap - Map of ID to node objects
     * @param {Set<string>} visited - Cycle prevention visited set
     * @returns {string} Resolved family name or empty string
     *
     * @example
     * FamilyTreeBuilder._resolveFamilyNameFromMother(momNode, nodeMap, new Set());
     *
     * @example
     * FamilyTreeBuilder._resolveFamilyNameFromMother(null, nodeMap, new Set());
     */
    static _resolveFamilyNameFromMother(mom, nodeMap, visited) {
        if (!mom) return '';
        for (const pid of (mom.partners || [])) {
            if (nodeMap[pid]) {
                const fam = FamilyTreeBuilder._resolveFamilyName(nodeMap[pid], nodeMap, visited);
                if (fam) return fam;
            }
        }
        if (mom.spouse) {
            const spCands = FamilyTreeBuilder._findSameSheetCandidates(mom.spouse, mom, nodeMap);
            for (const sp of spCands) {
                const fam = FamilyTreeBuilder._resolveFamilyName(sp, nodeMap, visited);
                if (fam) return fam;
            }
        }
        return '';
    }

    /**
     * Resolves family name matrilineally by tracing mother's partners or spouses.
     *
     * @param {Object} node - Subject node.
     * @param {Object} nodeMap - Map of ID to node objects.
     * @param {Set<string>} visited - Cycle prevention visited set.
     * @returns {string} Resolved family name or empty string.
     *
     * @example
     * FamilyTreeBuilder._resolveMaternalFamilyName({ momId: 'mom_1' }, { mom_1: { partners: ['dad_1'] }, dad_1: { family: 'Kizhakkumthala' } }, new Set());
     * // => 'kizhakkumthala'
     *
     * @example
     * FamilyTreeBuilder._resolveMaternalFamilyName({}, {}, new Set());
     * // => ''
     */
    static _resolveMaternalFamilyName(node, nodeMap, visited) {
        if (node.momId && nodeMap[node.momId]) {
            const fam = FamilyTreeBuilder._resolveFamilyNameFromMother(nodeMap[node.momId], nodeMap, visited);
            if (fam) return fam;
        }
        if (node.mom) {
            const momCands = FamilyTreeBuilder._findSameSheetCandidates(node.mom, node, nodeMap);
            for (const mom of momCands) {
                const fam = FamilyTreeBuilder._resolveFamilyNameFromMother(mom, nodeMap, visited);
                if (fam) return fam;
            }
        }
        return '';
    }

    /**
     * Resolves the family name for a node, checking explicit family, then patrilineally, then matrilineally.
     *
     * @param {Object} node - Subject person node.
     * @param {Object} [nodeMap={}] - Map of ID to node objects.
     * @param {Set<string>} [visited=new Set()] - Cycle prevention visited set.
     * @returns {string} Resolved lowercase family name or empty string.
     *
     * @example
     * FamilyTreeBuilder._resolveFamilyName({ family: 'Mecheri' });
     * // => 'mecheri'
     *
     * @example
     * FamilyTreeBuilder._resolveFamilyName(null);
     * // => ''
     */
    static _resolveFamilyName(node, nodeMap = {}, visited = new Set()) {
        if (!node) return '';
        const key = node.id || node._normName || '';
        if (key && visited.has(key)) return '';
        if (key) visited.add(key);

        if (node.family) return node.family.toLowerCase().trim();

        const patFam = FamilyTreeBuilder._resolvePaternalFamilyName(node, nodeMap, visited);
        if (patFam) return patFam;

        return FamilyTreeBuilder._resolveMaternalFamilyName(node, nodeMap, visited);
    }

    /**
     * Verifies that the age difference between parent and child is biologically possible.
     * 
     * @param {number} parentYob - Year of birth of parent
     * @param {number} childYob - Year of birth of child
     * @param {string} relationType - 'father' or 'mother'
     * @returns {boolean} True if age difference is biologically valid
     * 
     * @example
     * FamilyTreeBuilder._isBiologicalAgeGapValid(1950, 1975, 'mother');
     * // => true (25 yr gap)
     *
     * @example
     * FamilyTreeBuilder._isBiologicalAgeGapValid(1970, 1975, 'mother');
     * // => false (5 yr gap < 10)
     */
    static _isBiologicalAgeGapValid(parentYob, childYob, relationType) {
        const ageDiff = childYob - parentYob;
        if (ageDiff < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE) return false;
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        const isDad = FamilyTreeBuilder._isFatherRelation(relationType);
        if (isMom && ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE) return false;
        if (isDad && ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE) return false;
        return true;
    }

    /**
     * Checks if a candidate mother in the late childbirth grey zone (50-55 years) has an earlier child
     * born within the normal range (14-50 years).
     * 
     * @param {Object} candidate - Mother candidate node
     * @param {number} parentYob - Mother's birth year
     * @param {string} identifier - Mother's name identifier
     * @param {Object} nodeMap - Map of all person nodes
     * @param {boolean} [useBestYob=true] - Whether to use best/inferred birth year fallback
     * @returns {boolean} True if a valid earlier child exists on the same sheet
     * 
     * @example
     * FamilyTreeBuilder._hasValidEarlierChild(mother, 1920, 'mom', { c1: { yob: 1955, momId: 'm1' } });
     * // => true (35 yr gap)
     *
     * @example
     * FamilyTreeBuilder._hasValidEarlierChild(mother, 1920, 'mom', {});
     * // => false (no other child)
     */
    static _hasValidEarlierChild(candidate, parentYob, identifier, nodeMap, useBestYob = true) {
        const ident = identifier ? identifier.toLowerCase().trim() : '';
        return Object.values(nodeMap).some(n => {
            const childYob = useBestYob ? FamilyTreeBuilder._effectiveYob(n) : n.yob;
            if (!childYob || !FamilyTreeBuilder.sharesSheet(n, candidate)) return false;
            const diff = childYob - parentYob;
            const inNormalRange = diff >= FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE && diff <= FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD;
            if (!inNormalRange) return false;
            if (n.momId === candidate.id) return true;
            const nMom = n.mom ? n.mom.toLowerCase().trim() : '';
            return ident && nMom === ident;
        });
    }

    /**
     * Validates that parent-child age gaps and maternal childbirth boundaries are satisfied.
     * 
     * @param {number} parentYob - Candidate parent birth year
     * @param {number} childYob - Source child birth year
     * @param {string} relationType - 'father' or 'mother'
     * @param {Object} context - Parent resolution context ({ identifier, candidate, nodeMap, useBestYob })
     * @returns {boolean} True if parent-child age gaps are valid
     * 
     * @example
     * FamilyTreeBuilder._validateParentChildAgeBounds(1950, 1975, 'mother', { identifier: 'mary', candidate: {}, nodeMap: {} });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._validateParentChildAgeBounds(1970, 1975, 'mother', { identifier: 'mary', candidate: {}, nodeMap: {} });
     * // => false (<14 yrs)
     */
    static _validateParentChildAgeBounds(parentYob, childYob, relationType, context = {}) {
        const { identifier, candidate, nodeMap, useBestYob = true } = context;
        if (!FamilyTreeBuilder._isBiologicalAgeGapValid(parentYob, childYob, relationType)) return false;
        const ageDiff = childYob - parentYob;
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        if (isMom && ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD) {
            if (!FamilyTreeBuilder._hasValidEarlierChild(candidate, parentYob, identifier, nodeMap, useBestYob)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Gathers all explicit, originating, or reverse-referenced child IDs of a candidate parent.
     *
     * @param {Object} candidate - Parent node
     * @param {Object} [nodeMap={}] - Node map by ID
     * @returns {Set<string>} Set of child IDs
     *
     * @example
     * FamilyTreeBuilder._collectCandidateChildIds({ children: ['c1'], _originatingChildIds: ['c2'] }, { c3: { momId: 'p1' } });
     * // => Set(['c1', 'c2'])
     *
     * @example
     * FamilyTreeBuilder._collectCandidateChildIds(null, {});
     * // => Set([])
     */
    static _collectCandidateChildIds(candidate, nodeMap = {}) {
        const candChildIds = new Set([
            ...(candidate?.children || []),
            ...(candidate?._originatingChildIds || [])
        ]);
        const candId = candidate?.id;
        if (candId) {
            for (const n of Object.values(nodeMap)) {
                if (n && (n.momId === candId || n.fatherId === candId)) {
                    candChildIds.add(n.id);
                }
            }
        }
        return candChildIds;
    }

    /**
     * Determines whether a candidate's child is a co-sibling of sourceNode on the same sheet
     * without conflicting family declarations.
     *
     * @param {Object} candidate - Candidate parent node
     * @param {Object} ch - Child node of candidate
     * @param {Object} sourceNode - Child node seeking parent
     * @returns {boolean} True if ch is a compatible co-sibling
     *
     * @example
     * FamilyTreeBuilder._isCoSiblingWithoutConflict({ id: 'p1' }, { mom: 'Mary', family: 'K', _sheet: 's1' }, { mom: 'Mary', family: 'K', _sheet: 's1' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCoSiblingWithoutConflict({ id: 'p1' }, { mom: 'Mary', family: 'A', _sheet: 's1' }, { mom: 'Mary', family: 'B', _sheet: 's1' });
     * // => false (family conflict)
     */
    static _isCoSiblingWithoutConflict(candidate, ch, sourceNode) {
        if (!candidate || candidate.isGhost || !ch || !sourceNode) return false;
        if (!FamilyTreeBuilder.sharesSheet(ch, sourceNode)) return false;

        const sameMom = ch.mom && sourceNode.mom && FamilyTreeBuilder._normText(ch.mom) === FamilyTreeBuilder._normText(sourceNode.mom);
        const sameDad = ch.father && sourceNode.father && FamilyTreeBuilder._normText(ch.father) === FamilyTreeBuilder._normText(sourceNode.father);
        if (!sameMom && !sameDad) return false;

        const sDeclaredFam = FamilyTreeBuilder._normText(sourceNode._declaredFamily || sourceNode.family);
        const chDeclaredFam = FamilyTreeBuilder._normText(ch._declaredFamily || ch.family);
        const explicitFamConflict = sDeclaredFam && chDeclaredFam && sDeclaredFam !== chDeclaredFam;
        return !explicitFamConflict;
    }

    /**
     * Collects all established partner IDs and resolved spouse-column partner IDs for a child.
     *
     * @param {Object} ch - Child node
     * @param {Object} [nodeMap={}] - Node map by ID
     * @returns {Set<string>} Set of spouse/partner node IDs
     *
     * @example
     * FamilyTreeBuilder._collectEffectiveSpouseIds({ partners: ['sp1'] }, {});
     * // => Set(['sp1'])
     *
     * @example
     * FamilyTreeBuilder._collectEffectiveSpouseIds(null, {});
     * // => Set([])
     */
    static _collectEffectiveSpouseIds(ch, nodeMap = {}) {
        const chSpouseIds = new Set(ch?.partners || []);
        if (!ch?.spouse) return chSpouseIds;

        const spNorm = (ch.spouse || '').toLowerCase().trim();
        const chNorm = (ch._normName || ch.name || '').toLowerCase().trim();

        for (const potentialSp of Object.values(nodeMap)) {
            if (!potentialSp || potentialSp === ch || !FamilyTreeBuilder.sharesSheet(potentialSp, ch)) continue;
            const pNorm = (potentialSp._normName || potentialSp.name || '').toLowerCase().trim();
            if (pNorm !== spNorm) continue;

            const dist = FamilyTreeBuilder._getMinRowDistance(potentialSp, ch);
            const reciprocal = potentialSp.spouse && (potentialSp.spouse || '').toLowerCase().trim() === chNorm;
            if (reciprocal || dist <= 3) {
                chSpouseIds.add(potentialSp.id);
            }
        }
        return chSpouseIds;
    }

    /**
     * Checks if a spouse node is a first cousin, biological sibling, or parent/child of sourceNode.
     *
     * @param {Object} spouseNode - Spouse of candidate's child
     * @param {Object} sourceNode - Child node seeking parent
     * @param {Object} [nodeMap={}] - Node map by ID
     * @returns {boolean} True if consanguinity conflict exists
     *
     * @example
     * FamilyTreeBuilder._hasConsanguinityConflictWithSource({ id: 'a', mom: 'Mary' }, { id: 'b', mom: 'Mary' }, {});
     * // => true (biological siblings)
     *
     * @example
     * FamilyTreeBuilder._hasConsanguinityConflictWithSource({ id: 'a' }, { id: 'b' }, {});
     * // => false
     */
    static _hasConsanguinityConflictWithSource(spouseNode, sourceNode, nodeMap = {}) {
        if (!spouseNode || !sourceNode) return false;
        return (FamilyTreeBuilder._areFirstCousins(spouseNode, sourceNode, nodeMap) ||
                FamilyTreeBuilder._areBiologicalSiblings(spouseNode, sourceNode) ||
                FamilyTreeBuilder._isBiologicalParentChild(spouseNode, sourceNode));
    }

    /**
     * Checks whether any spouse of a child has a consanguinity conflict with the source node.
     *
     * @param {Object} ch - Child node
     * @param {Object} sourceNode - Source reference person
     * @param {Object} nodeMap - Graph nodes mapped by ID
     * @returns {boolean} True if any spouse has a consanguinity conflict
     *
     * @example
     * FamilyTreeBuilder._hasChildSpouseConsanguinityConflict(ch, source, nodeMap);
     *
     * @example
     * FamilyTreeBuilder._hasChildSpouseConsanguinityConflict({ partners: [] }, source, nodeMap);
     */
    static _hasChildSpouseConsanguinityConflict(ch, sourceNode, nodeMap) {
        const chSpouseIds = FamilyTreeBuilder._collectEffectiveSpouseIds(ch, nodeMap);
        for (const spId of chSpouseIds) {
            const sp = nodeMap[spId];
            if (FamilyTreeBuilder._hasConsanguinityConflictWithSource(sp, sourceNode, nodeMap)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines whether treating candidate as a parent of sourceNode would cause
     * an incestuous in-law conflict (such as a child of candidate marrying a biological
     * first cousin, sibling, or parent/child of sourceNode).
     *
     * In Syrian Christian tradition, biological sibling and first-cousin marriages are strictly
     * prohibited. If candidate is parent of child X, and X is married to Y who is a first cousin
     * (or sibling) of sourceNode, candidate cannot be sourceNode's parent (as that would make
     * sourceNode and X siblings, implying Y married their own biological first cousin).
     * "A person's cousin's in-law (mother-in-law / father-in-law) cannot be their parent."
     *
     * @param {Object} candidate - Candidate parent node
     * @param {Object} sourceNode - Child node seeking parent
     * @param {Object} [nodeMap={}] - Graph nodes mapped by ID
     * @param {Set<string>} [visited=new Set()] - Cycle prevention visited set
     * @returns {boolean} True if an in-law marriage conflict is detected
     *
     * @example
     * FamilyTreeBuilder._hasInLawMarriageConflict({ id: 'cand' }, { id: 'src' }, {});
     * // => false
     *
     * @example
     * FamilyTreeBuilder._hasInLawMarriageConflict(null, null, {});
     * // => false
     */
    static _hasInLawMarriageConflict(candidate, sourceNode, nodeMap = {}, visited = new Set()) {
        if (!candidate || !sourceNode || !nodeMap) return false;
        const pairKey = `${candidate.id || candidate.name || ''}->${sourceNode.id || sourceNode.name || ''}`;
        if (visited.has(pairKey)) return false;
        visited.add(pairKey);

        const candChildIds = FamilyTreeBuilder._collectCandidateChildIds(candidate, nodeMap);

        for (const chId of candChildIds) {
            if (chId === sourceNode.id) continue;
            const ch = nodeMap[chId];
            if (!ch || FamilyTreeBuilder._isCoSiblingWithoutConflict(candidate, ch, sourceNode)) {
                continue;
            }
            if (FamilyTreeBuilder._hasChildSpouseConsanguinityConflict(ch, sourceNode, nodeMap)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if a candidate parent's family name matches or is compatible with the child node.
     * 
     * @param {Object} candidate - Candidate parent node
     * @param {Object} sourceNode - Child node
     * @param {boolean} isDad - Whether candidate is father
     * @param {boolean} isMom - Whether candidate is mother
     * @param {Object} [nodeMap={}] - Dictionary of all person nodes
     * @returns {boolean} True if family name is compatible
     *
     * @example
     * FamilyTreeBuilder._isParentFamilyCompatible({ family: 'Mecheri' }, { family: 'Mecheri' }, true, false, {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isParentFamilyCompatible({ family: 'Mecheri' }, { family: 'Other' }, true, false, {});
     * // => false
     */
    static _isParentFamilyCompatible(candidate, sourceNode, isDad, isMom, nodeMap) {
        if (!sourceNode.family) return true;
        const nFam = sourceNode.family.toLowerCase().trim();
        const candFam = FamilyTreeBuilder._resolveFamilyName(candidate, nodeMap);
        if (isDad && candFam && candFam !== nFam) return false;
        if (isMom && !FamilyTreeBuilder._isMotherSpouseFamilyCompatible(candidate, nFam, nodeMap)) return false;
        return true;
    }

    /**
     * Verifies biological generation age boundaries between parent candidate and child node.
     * 
     * @param {Object} candidate - Candidate parent node
     * @param {Object} sourceNode - Child node
     * @param {string} relationType - 'mother' or 'father'
     * @param {string} identifier - Query identifier
     * @param {Object} [nodeMap={}] - Dictionary of all person nodes
     * @returns {boolean} True if age difference is biologically plausible
     *
     * @example
     * FamilyTreeBuilder._isParentChildAgeCompatible({ yob: 1950 }, { yob: 1975 }, 'mother', 'mary', {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isParentChildAgeCompatible({ yob: 1970 }, { yob: 1975 }, 'mother', 'mary', {});
     * // => false
     */
    static _isParentChildAgeCompatible(candidate, sourceNode, relationType, identifier, nodeMap) {
        const cYob = FamilyTreeBuilder._effectiveYob(candidate);
        const sYob = FamilyTreeBuilder._effectiveYob(sourceNode);
        if (cYob && sYob) {
            if (!FamilyTreeBuilder._validateParentChildAgeBounds(cYob, sYob, relationType, { identifier, candidate, nodeMap, useBestYob: true })) {
                return false;
            }
        }

        if (!cYob && sYob) {
            const allNodesList = Object.values(nodeMap);
            const { minBound } = FamilyTreeBuilder._getSiblingAgeBounds(candidate, allNodesList);
            if (minBound > -Infinity && sYob - (minBound - 15) < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE) {
                return false;
            }
        }

        if (candidate.yob && sourceNode.yob) {
            if (!FamilyTreeBuilder._validateParentChildAgeBounds(candidate.yob, sourceNode.yob, relationType, { identifier, candidate, nodeMap, useBestYob: false })) {
                return false;
            }
        }

        return true;
    }

    /**
     * Validates whether a person candidate is a viable parent for sourceNode based on biological age constraints.
     * 
     * @param {Object} candidate - Potential parent node
     * @param {Object} sourceNode - Child node
     * @param {string} relationType - 'mother', 'father', or 'parent'
     * @param {string} identifier - Raw searched name
     * @param {Object} [nodeMap={}] - Mapping of node ID -> Node
     * @param {boolean} [skipInLawConflict=false] - Whether to skip in-law marriage conflict check
     * @returns {boolean} True if candidate is biologically viable
     * 
     * @example
     * FamilyTreeBuilder._isValidParentCandidate({ yob: 1950 }, { yob: 1975 }, 'mother', 'mary', {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isValidParentCandidate({ yob: 1970 }, { yob: 1975 }, 'mother', 'mary', {});
     * // => false
     */
    static _isValidParentCandidate(candidate, sourceNode, relationType, identifier, nodeMap = {}, skipInLawConflict = false) {
        if (FamilyTreeBuilder._isCelibateReligious(candidate)) return false;
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        const isDad = FamilyTreeBuilder._isFatherRelation(relationType);

        if (!FamilyTreeBuilder._isParentFamilyCompatible(candidate, sourceNode, isDad, isMom, nodeMap)) {
            return false;
        }

        const otherParentName = isDad ? sourceNode.mom : sourceNode.father;
        if (FamilyTreeBuilder._hasSpouseConflictWithOtherParent(candidate, otherParentName, nodeMap)) return false;
        if (!skipInLawConflict && FamilyTreeBuilder._hasInLawMarriageConflict(candidate, sourceNode, nodeMap)) return false;

        return FamilyTreeBuilder._isParentChildAgeCompatible(candidate, sourceNode, relationType, identifier, nodeMap);
    }

    /**
     * Finds co-sheet siblings of a node that share a mother or father without name conflict.
     *
     * @param {Object} node - Target person node.
     * @param {Array<Object>} [allNodes=[]] - Array of candidate nodes.
     * @returns {Array<Object>} Array of matching sibling nodes on the same sheet.
     *
     * @example
     * FamilyTreeBuilder._findCoSheetSiblings({ id: '1', mom: 'Mary', _sheet: 's1' }, [{ id: '1', mom: 'Mary', _sheet: 's1' }, { id: '2', mom: 'Mary', _sheet: 's1' }]);
     * // => [{ id: '2', mom: 'Mary', _sheet: 's1' }]
     *
     * @example
     * FamilyTreeBuilder._findCoSheetSiblings(null, []);
     * // => []
     */
    static _findCoSheetSiblings(node, allNodes = []) {
        if (!node || !allNodes || !allNodes.length) return [];
        return allNodes.filter(s => s !== node && FamilyTreeBuilder.sharesSheet(s, node) && (
            (node.mom && s.mom && !FamilyTreeBuilder._hasNameConflict(node.mom, s.mom)) ||
            (node.father && s.father && !FamilyTreeBuilder._hasNameConflict(node.father, s.father))
        ));
    }

    /**
     * Adjusts elder/younger sibling birth bounds based on spreadsheet row ordering.
     *
     * @param {number} rNode - Spreadsheet row index of target node.
     * @param {Object} sibling - Sibling node with possible yob and sheet row.
     * @param {Object} bounds - Object with minBound and maxBound numbers.
     *
     * @example
     * const bounds = { minBound: -Infinity, maxBound: Infinity };
     * FamilyTreeBuilder._narrowSiblingBoundsByRow(10, { yob: 1980, _sheetRow: 20 }, bounds);
     * // bounds.maxBound becomes 1980
     *
     * @example
     * const bounds = { minBound: -Infinity, maxBound: Infinity };
     * FamilyTreeBuilder._narrowSiblingBoundsByRow(25, { yob: 1980, _sheetRow: 20 }, bounds);
     * // bounds.minBound becomes 1980
     */
    static _narrowSiblingBoundsByRow(rNode, sibling, bounds) {
        if (!sibling || !sibling.yob) return;
        const rS = FamilyTreeBuilder.getNodeSheetRow(sibling, FamilyTreeBuilder.MAX_ROW_SENTINEL);
        if (rNode < FamilyTreeBuilder.MAX_ROW_SENTINEL && rS < FamilyTreeBuilder.MAX_ROW_SENTINEL) {
            if (rNode < rS) {
                bounds.maxBound = Math.min(bounds.maxBound, sibling.yob);
            } else if (rNode > rS) {
                bounds.minBound = Math.max(bounds.minBound, sibling.yob);
            }
        }
    }

    /**
     * Computes sibling age bounds for a person based on their relative spreadsheet row order.
     * 
     * @param {Object} node - Target person node.
     * @param {Array<Object>} [allNodes=[]] - List of all nodes in tree.
     * @returns {{minBound: number, maxBound: number}} Minimum and maximum birth year bounds.
     * 
     * @example
     * FamilyTreeBuilder._getSiblingAgeBounds({ id: '1', _sheetRow: 10 }, []);
     * // => { minBound: -Infinity, maxBound: Infinity }
     *
     * @example
     * FamilyTreeBuilder._getSiblingAgeBounds(null, []);
     * // => { minBound: -Infinity, maxBound: Infinity }
     */
    static _getSiblingAgeBounds(node, allNodes = []) {
        let minBound = -Infinity;
        let maxBound = Infinity;
        if (!node || !allNodes || !allNodes.length) return { minBound, maxBound };

        const rNode = FamilyTreeBuilder.getNodeSheetRow(node, FamilyTreeBuilder.MAX_ROW_SENTINEL);
        const siblings = FamilyTreeBuilder._findCoSheetSiblings(node, allNodes);
        const bounds = { minBound, maxBound };

        siblings.forEach(s => FamilyTreeBuilder._narrowSiblingBoundsByRow(rNode, s, bounds));

        return bounds;
    }

    /**
     * Checks if two people are biological siblings (share the same mother or father).
     * 
     * @param {Object} a - First person node
     * @param {Object} b - Second person node
     * @returns {boolean} True if a and b are biological siblings on the same sheet
     * 
     * @example
     * FamilyTreeBuilder._areBiologicalSiblings({ id: '1', mom: 'Mariyam', _sheet: 's1' }, { id: '2', mom: 'Mariyam', _sheet: 's1' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._areBiologicalSiblings({ id: '1', mom: 'Mariyam', _sheet: 's1' }, { id: '2', mom: 'Annamma', _sheet: 's1' });
     * // => false
     */
    static _areBiologicalSiblings(a, b) {
        if (!a || !b || FamilyTreeBuilder._isSameNode(a, b)) return false;
        if (!FamilyTreeBuilder.sharesSheet(a, b)) return false;
        const aMom = FamilyTreeBuilder._normText(a.mom), bMom = FamilyTreeBuilder._normText(b.mom);
        const aDad = FamilyTreeBuilder._normText(a.father), bDad = FamilyTreeBuilder._normText(b.father);

        if (FamilyTreeBuilder._isNamedParent(aMom) && FamilyTreeBuilder._isNamedParent(bMom) && aMom === bMom) return true;
        if (FamilyTreeBuilder._isNamedParent(aDad) && FamilyTreeBuilder._isNamedParent(bDad) && aDad === bDad) return true;
        if (a.momId && b.momId && a.momId === b.momId) return true;
        if (a.fatherId && b.fatherId && a.fatherId === b.fatherId) return true;
        if (a.explicitSiblings && a.explicitSiblings.includes(b.id)) return true;
        if (b.explicitSiblings && b.explicitSiblings.includes(a.id)) return true;
        return false;
    }

    /**
     * Determines whether a person possesses a religious title indicating vows of celibacy (e.g. Sr, Fr, nun).
     * Celibate religious individuals do not marry and must never be matched or assigned as spouses.
     * Note: "achan" is a kinship term / title not indicating celibacy vows, so it does not trigger celibacy.
     *
     * @param {Object} node - Person node to inspect
     * @returns {boolean} True if person is a celibate religious individual
     *
     * @example
     * FamilyTreeBuilder._isCelibateReligious({ name: 'Mary', nick: 'Sr Nicoletta' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCelibateReligious({ name: 'Jose achan' });
     * // => false
     */
    static _isCelibateReligious(node) {
        if (!node) return false;
        if (node.isCelibate) return true;
        if (node.isNun || node.isPriest) return true;
        if (node.job === 'Nun' || node.job === 'Priest') return true;
        const name = (node.name || '').trim();
        const nick = (node.nick || '').trim();
        const norm = (node._normName || '').trim();
        const text = [name, nick, norm, node.freeForm].filter(Boolean).join(' ');
        if (!text) return false;

        // Relative roles, spouses, and parents are NEVER celibate religious
        if (/(?:wife|husband|daughter|son)/i.test(text)) return false;
        if (/(?:brother|sister)\b/i.test(name) && !/^(?:brother|sister|br\.|sr\.)\s+/i.test(name)) return false;
        if (node.children && node.children.length > 0) return false;

        const titleMatch = FamilyTreeBuilder.matchTitleOntology(name, nick);
        if (titleMatch && titleMatch.isCelibate) return true;

        return /\b(?:sr|sr\.|fr|fr\.|rev|rev\.|br\.|nun|monk|priest)\b/i.test(text) ||
               /^(?:brother|sister)\s+[a-z]+/i.test(name) ||
               /^(?:brother|sister)\s+[a-z]+/i.test(nick);
    }

    /**
     * Checks if candidate is married to, partnered with, or claimed by a child of sourceNode on the same sheet.
     *
     * @param {Object} candidate - Potential spouse node.
     * @param {Object} sourceNode - Reference parent node.
     * @param {Array<Object>} allNodes - Complete pool of tree nodes.
     * @param {string} srcNorm - Normalized name of sourceNode.
     * @param {string} candNorm - Normalized name of candidate.
     * @returns {boolean} True if candidate is married to a child of sourceNode.
     *
     * @example
     * FamilyTreeBuilder._isCandidateChildInLaw(candSonInLaw, fatherNode, allNodes, 'father', 'son in law');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateChildInLaw({}, {}, [], 'father', 'other');
     * // => false
     */
    static _isCandidateChildInLaw(candidate, sourceNode, allNodes, srcNorm, candNorm) {
        if (FamilyTreeBuilder._claimsAsSpouse(candidate, sourceNode)) return false;
        return allNodes.some(other => {
            if (!other || other === candidate || other === sourceNode) return false;
            if (!FamilyTreeBuilder.sharesSheet(other, sourceNode)) return false;
            const oMom = (other.mom || '').toLowerCase().trim();
            const oDad = (other.father || '').toLowerCase().trim();
            const isChild = (oMom === srcNorm || oDad === srcNorm || other.momId === sourceNode.id || other.fatherId === sourceNode.id);
            if (!isChild) return false;

            const candClaimsOther = candidate.spouse && !FamilyTreeBuilder._hasNameConflict(candidate.spouse, other._normName || other.name);
            const otherClaimsCand = other.spouse && !FamilyTreeBuilder._hasNameConflict(other.spouse, candNorm);
            const isPartnered = FamilyTreeBuilder._arePartnersLinked(candidate, other);
            const maxRowDist = FamilyTreeBuilder.GENERATIONAL_GAPS.ADJACENT_ROW_MAX_DISTANCE;
            return candClaimsOther || (otherClaimsCand && FamilyTreeBuilder._getMinRowDistance(candidate, other) <= maxRowDist) || isPartnered;
        });
    }

    /**
     * Checks if candidate appears strictly below sourceNode in row index on a shared sheet.
     *
     * @param {Object} candidate - Potential descendant namesake candidate.
     * @param {Object} sourceNode - Ancestor reference node.
     * @returns {boolean} True if candidate is placed at a subsequent row number.
     *
     * @example
     * FamilyTreeBuilder._isCandidateRowSubsequent(candOnRow50, ancestorOnRow2);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateRowSubsequent(candOnRow2, ancestorOnRow50);
     * // => false
     */
    static _isCandidateRowSubsequent(candidate, sourceNode) {
        const dist = FamilyTreeBuilder._getMinRowDistance(candidate, sourceNode);
        // Immediate family rows (<= 3 rows apart) are co-listed siblings/spouses rather than subsequent-generation descendants.
        if (dist <= FamilyTreeBuilder.GENERATIONAL_GAPS.ADJACENT_ROW_MAX_DISTANCE || dist === 9999) return false;

        for (const sid of candidate._sourceIds || []) {
            if (sourceNode._sourceIds && sourceNode._sourceIds.has(sid) &&
                candidate._sheetRows?.[sid] && sourceNode._sheetRows?.[sid]) {
                if (candidate._sheetRows[sid] > sourceNode._sheetRows[sid]) return true;
            }
        }
        return false;
    }

    /**
     * Determines whether a candidate spouse is a contemporary with compatible age or from an explicitly distinct family.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Reference node
     * @returns {boolean} True if candidate is a contemporary or from a different family
     *
     * @example
     * FamilyTreeBuilder._isCandidateCrossFamilyOrContemporary({ yob: 1952 }, { yob: 1950 });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateCrossFamilyOrContemporary({ family: 'Smith' }, { family: 'Jones' });
     * // => true
     */
    static _isCandidateCrossFamilyOrContemporary(candidate, sourceNode) {
        if (sourceNode.yob && candidate.yob && FamilyTreeBuilder._arePartnersAgeCompatible(sourceNode, candidate)) {
            return true;
        }
        if (sourceNode.family && candidate.family) {
            const normSrcFam = sourceNode.family.toLowerCase().trim();
            const normCandFam = candidate.family.toLowerCase().trim();
            if (normSrcFam && normCandFam && normSrcFam !== normCandFam) return true;
        }
        return false;
    }

    /**
     * Determines whether a candidate with the same or similar name is actually a descendant namesake
     * (e.g., grandchild named after grandparent) rather than an eligible spouse contemporary.
     *
     * @param {Object} candidate - Potential spouse candidate
     * @param {Object} sourceNode - Source node seeking spouse
     * @param {Object[]} [allNodes=[]] - Full list of nodes in current tree build
     * @returns {boolean} True if candidate is a younger descendant namesake
     *
     * @example
     * FamilyTreeBuilder._isDescendantNamesake(candAmmachi, anthonyNode, allNodes);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isDescendantNamesake(candGeorge, emilyNode, allNodes);
     * // => false
     */
    static _isDescendantNamesake(candidate, sourceNode, allNodes = []) {
        if (!candidate || !sourceNode || candidate.isGhost) return false;

        const srcNorm = (sourceNode._normName || sourceNode.name || '').toLowerCase().trim();
        const candNorm = (candidate._normName || candidate.name || '').toLowerCase().trim();

        if (FamilyTreeBuilder._isCandidateChildInLaw(candidate, sourceNode, allNodes, srcNorm, candNorm)) {
            return true;
        }

        if (candidate.spouse || (!candidate.father && !candidate.mom)) return false;
        if (FamilyTreeBuilder._isCandidateCrossFamilyOrContemporary(candidate, sourceNode)) return false;

        return FamilyTreeBuilder._isCandidateRowSubsequent(candidate, sourceNode);
    }

    /**
     * Determines maximum permissible age difference between spouses, accommodating subsequent remarriages.
     *
     * @param {Object} partnerA - First partner node
     * @param {Object} partnerB - Second partner node
     * @param {boolean} [hasExistingPartners=false] - Whether either partner has existing marriages
     * @returns {number} Maximum permissible age difference in years
     *
     * @example
     * FamilyTreeBuilder._getMaxSpouseAgeDiff({ gender: 'M' }, { gender: 'F' }, false);
     * // => 25
     *
     * @example
     * FamilyTreeBuilder._getMaxSpouseAgeDiff({ gender: 'M' }, { gender: 'F' }, true);
     * // => 35
     */
    static _getMaxSpouseAgeDiff(partnerA, partnerB, hasExistingPartners = false) {
        const isSubsequent = hasExistingPartners || FamilyTreeBuilder._isSubsequentSpouse(partnerA, partnerB);
        return isSubsequent ? FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_SPOUSE_AGE_DIFF : FamilyTreeBuilder.HEURISTIC_PRIORS.MAX_FIRST_WIFE_AGE_DIFF;
    }

    /**
     * Validates chronological age ordering between husband and wife candidates,
     * ensuring wife is not older than husband unless an exception (inferred offset or <=5yr tolerance with strong claim) applies.
     *
     * @param {Object} husband - Husband person node
     * @param {Object} wife - Wife person node
     * @param {number} diff - Absolute difference between birth years
     * @param {boolean} hasSpouseClaim - Whether either party explicitly declared the other as spouse
     * @param {boolean} sharesChildren - Whether the pair shares child links
     * @returns {boolean} True if age relationship is compatible
     *
     * @example
     * FamilyTreeBuilder._validateHusbandWifeAgeOrder({ yob: 1950 }, { yob: 1952 }, 2, true, true);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._validateHusbandWifeAgeOrder({ yob: 1955 }, { yob: 1945 }, 10, false, false);
     * // => false
     */
    static _validateHusbandWifeAgeOrder(husband, wife, diff, hasSpouseClaim, sharesChildren) {
        const hYob = husband.yob || husband._inferredYob;
        const wYob = wife.yob || wife._inferredYob;
        if (wYob < hYob) {
            if (!wife.yob && hasSpouseClaim) {
                wife._inferredYob = hYob + FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET;
                return true;
            }
            if ((sharesChildren || hasSpouseClaim) && diff <= 5) return true;
            return false;
        }
        return true;
    }

    /**
     * Checks if age difference and gender roles between two prospective partners are biologically compatible.
     *
     * @param {Object} partnerA - First partner node
     * @param {Object} partnerB - Second partner node
     * @param {boolean} [hasExistingPartners=false] - Whether either partner has existing marriages
     * @returns {boolean} True if partners are age-compatible
     *
     * @example
     * FamilyTreeBuilder._arePartnersAgeCompatible({ gender: 'M', yob: 1950 }, { gender: 'F', yob: 1952 });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._arePartnersAgeCompatible({ gender: 'M', yob: 1950 }, { gender: 'F', yob: 1995 });
     * // => false
     */
    static _arePartnersAgeCompatible(partnerA, partnerB, hasExistingPartners = false) {
        if (!partnerA || !partnerB) return true;
        const aYob = partnerA.yob || partnerA._inferredYob;
        const bYob = partnerB.yob || partnerB._inferredYob;
        if (!aYob || !bYob) return true;

        const maxDiff = FamilyTreeBuilder._getMaxSpouseAgeDiff(partnerA, partnerB, hasExistingPartners);
        const diff = Math.abs(aYob - bYob);
        if (diff > maxDiff) return false;

        const husband = partnerA.gender === 'M' ? partnerA : partnerB.gender === 'M' ? partnerB : null;
        const wife = partnerA.gender === 'F' ? partnerA : partnerB.gender === 'F' ? partnerB : null;
        if (husband && wife) {
            const hasSpouseClaim = FamilyTreeBuilder._claimsAsSpouse(partnerA, partnerB) || FamilyTreeBuilder._claimsAsSpouse(partnerB, partnerA);
            const sharesChildren = (partnerA.children || []).some(cid => (partnerB.children || []).includes(cid));
            return FamilyTreeBuilder._validateHusbandWifeAgeOrder(husband, wife, diff, hasSpouseClaim, sharesChildren);
        }

        return true;
    }

    /**
     * Determines whether a candidate or source node represents a subsequent spouse (second/third wife, remarriage).
     *
     * @param {Object} candidate - Prospective spouse node
     * @param {Object} sourceNode - Source person node
     * @returns {boolean} True if either party indicates remarriage or subsequent spouse status
     *
     * @example
     * FamilyTreeBuilder._isSubsequentSpouse({ name: 'Mary (2nd wife)' }, { name: 'John' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isSubsequentSpouse({ name: 'Mary' }, { name: 'John' });
     * // => false
     */
    static _isSubsequentSpouse(candidate, sourceNode) {
        const subRegex = /\b(?:wife\s+([2-9]|\d{2,})|2nd\s+wife|3rd\s+wife|second\s+wife|third\s+wife|remarriage)\b/i;
        if (candidate && subRegex.test(candidate.name || candidate._normName || '')) return true;
        if (sourceNode && subRegex.test(sourceNode.name || sourceNode._normName || '')) return true;
        if (candidate && candidate.partners && candidate.partners.length > 0) return true;
        if (sourceNode && sourceNode.partners && sourceNode.partners.length > 0) return true;
        return false;
    }

    /**
     * Checks if candidate is an adjacent co-spouse on the same sheet sharing spouse links.
     *
     * @param {Object} candidate - Potential co-spouse candidate
     * @param {Object} sourceNode - Source person node
     * @param {Array<Object>} [allNodes=[]] - All tree nodes
     * @returns {boolean} True if candidate is an adjacent co-spouse
     *
     * @example
     * FamilyTreeBuilder._isAdjacentCoSpouse({ id: 'c1' }, { id: 's1', spouse: 'John' }, []);
     * // => false
     *
     * @example
     * FamilyTreeBuilder._isAdjacentCoSpouse(null, null, []);
     * // => false
     */
    static _isAdjacentCoSpouse(candidate, sourceNode, allNodes = []) {
        if (!sourceNode || !sourceNode.spouse || !candidate || candidate.isGhost) return false;
        const normSpouse = sourceNode.spouse.toLowerCase().trim();
        const maxRowDist = FamilyTreeBuilder.GENERATIONAL_GAPS.ADJACENT_ROW_MAX_DISTANCE;
        return allNodes.some(other => {
            if (!other || other === sourceNode || other.isGhost) return false;
            if (!FamilyTreeBuilder.sharesSheet(other, sourceNode)) return false;
            if (FamilyTreeBuilder._getMinRowDistance(other, sourceNode) > maxRowDist) return false;
            if (!other.spouse || other.spouse.toLowerCase().trim() !== normSpouse) return false;
            const isPartnered = FamilyTreeBuilder._arePartnersLinked(candidate, other);
            const otherClaimsCand = FamilyTreeBuilder._claimsAsSpouse(other, candidate);
            return isPartnered || otherClaimsCand;
        });
    }

    /**
     * Verifies whether person explicitly declared a single spouse that matches another person on the sheet,
     * indicating person is exclusively married to that other person and cannot marry targetNode.
     * 
     * @param {Object} person - Subject person node
     * @param {Object} targetNode - Prospective spouse node
     * @param {string} targetNorm - Normalized name of targetNode
     * @param {Object} [nodeMap={}] - Map of all tree nodes by ID
     * @returns {boolean} True if person is exclusively married to someone else
     * 
     * @example
     * FamilyTreeBuilder._isExclusivelyMarriedToOther({ spouse: 'Thankamma' }, { name: 'Eliamma' }, 'eliamma', {});
     * // => false
     *
     * @example
     * FamilyTreeBuilder._isExclusivelyMarriedToOther({ spouse: 'Thankamma' }, { name: 'Thankamma' }, 'thankamma', {});
     * // => false
     */
    static _isExclusivelyMarriedToOther(person, targetNode, targetNorm, nodeMap = {}) {
        if (!person) return false;
        if (person.isGhost && person._originatingSpouseIds && person._originatingSpouseIds.length > 0) {
            if (!person._originatingSpouseIds.includes(targetNode.id)) {
                const originatingSpouses = person._originatingSpouseIds.map(id => nodeMap[id]).filter(Boolean);
                const isCoSpouse = originatingSpouses.some(orig =>
                    FamilyTreeBuilder._getMinRowDistance(targetNode, orig) <= 3 ||
                    FamilyTreeBuilder._isAdjacentCoSpouse(targetNode, orig, Object.values(nodeMap))
                );
                if (!isCoSpouse) return true;
            }
        }
        if (!person.spouse) return false;
        const spouses = person.spouse.split(/[,/]+/).map(s => s.trim().toLowerCase()).filter(Boolean);
        if (spouses.length !== 1) return false;
        const singleSpouse = spouses[0];
        const matchesTarget = !FamilyTreeBuilder._hasNameConflict(singleSpouse, targetNorm) ||
            (targetNode.nick && !FamilyTreeBuilder._hasNameConflict(singleSpouse, targetNode.nick.toLowerCase().trim()));
        if (!matchesTarget) {
            return (person.partners || []).some(pid => pid !== targetNode.id) ||
                Object.values(nodeMap).some(n =>
                    n !== targetNode && !n.isGhost &&
                    FamilyTreeBuilder.sharesSheet(n, person) &&
                    (!FamilyTreeBuilder._hasNameConflict(n.name, singleSpouse) || (n.nick && !FamilyTreeBuilder._hasNameConflict(n.nick, singleSpouse)))
                );
        }
        return false;
    }

    /**
     * Checks if two nodes form a biological parent-child pair (by direct ID or declared parent name).
     *
     * @param {Object} nodeA - First node
     * @param {Object} nodeB - Second node
     * @returns {boolean} True if either node is the parent of the other
     *
     * @example
     * FamilyTreeBuilder._isBiologicalParentChild({ id: 'dad' }, { fatherId: 'dad' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isBiologicalParentChild({ id: '1' }, { id: '2' });
     * // => false
     */
    static _isBiologicalParentChild(nodeA, nodeB) {
        if (nodeA.momId && nodeA.momId === nodeB.id) return true;
        if (nodeA.fatherId && nodeA.fatherId === nodeB.id) return true;
        if (nodeB.momId && nodeB.momId === nodeA.id) return true;
        if (nodeB.fatherId && nodeB.fatherId === nodeA.id) return true;

        const aNorm = FamilyTreeBuilder._normText(nodeA._normName || nodeA.name);
        const bNorm = FamilyTreeBuilder._normText(nodeB._normName || nodeB.name);

        const aMom = FamilyTreeBuilder._normText(nodeA.mom), aDad = FamilyTreeBuilder._normText(nodeA.father);
        const bMom = FamilyTreeBuilder._normText(nodeB.mom), bDad = FamilyTreeBuilder._normText(nodeB.father);

        if (FamilyTreeBuilder._isNamedParent(aMom) && aMom === bNorm) return true;
        if (FamilyTreeBuilder._isNamedParent(aDad) && aDad === bNorm) return true;
        if (FamilyTreeBuilder._isNamedParent(bMom) && bMom === aNorm) return true;
        if (FamilyTreeBuilder._isNamedParent(bDad) && bDad === aNorm) return true;

        return false;
    }

    /**
     * Deduces spousal roles based on spreadsheet row proximity heuristic when candidate and source share a sheet.
     * Husbands conventionally appear in lower row numbers than wives on the same sheet.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Source person node
     * @returns {{ isHusband: boolean, isWife: boolean }|null} Deduced roles or null if row heuristic inapplicable
     *
     * @example
     * FamilyTreeBuilder._deduceSpousalRolesByRowProximity({ sheet: 'S1', sheetRow: 10 }, { sheet: 'S1', sheetRow: 15 });
     * // => { isHusband: true, isWife: false }
     *
     * @example
     * FamilyTreeBuilder._deduceSpousalRolesByRowProximity({ sheet: 'S1', sheetRow: 20 }, { sheet: 'S1', sheetRow: 15 });
     * // => { isHusband: false, isWife: true }
     */
    static _deduceSpousalRolesByRowProximity(candidate, sourceNode) {
        // Row proximity heuristic: husbands appear in lower rows than their wives
        const rCand = candidate._sheetRow ?? candidate.sheetRow ?? 99999;
        const rSrc = sourceNode._sheetRow ?? sourceNode.sheetRow ?? 99999;
        if (FamilyTreeBuilder.sharesSheet(candidate, sourceNode) && rCand < 99999 && rSrc < 99999 && rCand !== rSrc) {
            let isHusband = false, isWife = false;
            if (rCand > rSrc) isWife = true;
            else isHusband = true;
            return { isHusband, isWife };
        }
        return null;
    }

    /**
     * Deduces whether the candidate is expected to be the husband or the wife
     * based on explicit genders, name morphology, spreadsheet row seniority, or relation type.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Source person node
     * @param {string} relationType - Relation type ('husband' | 'wife' | 'spouse')
     * @returns {{ isHusband: boolean, isWife: boolean }} Inferred spousal roles
     *
     * @example
     * FamilyTreeBuilder._deduceSpousalRoles({ gender: 'M' }, { gender: 'F' }, 'husband');
     * // => { isHusband: true, isWife: false }
     *
     * @example
     * FamilyTreeBuilder._deduceSpousalRoles({ gender: 'F' }, { gender: 'M' }, 'wife');
     * // => { isHusband: false, isWife: true }
     */
    static _deduceSpousalRoles(candidate, sourceNode, relationType) {
        const candM = candidate.gender === 'M' || (!candidate.gender && FamilyTreeBuilder._isMaleName(candidate.name));
        const candF = candidate.gender === 'F' || (!candidate.gender && FamilyTreeBuilder._isFemaleName(candidate.name));
        const srcM = sourceNode.gender === 'M' || (!sourceNode.gender && FamilyTreeBuilder._isMaleName(sourceNode.name));
        const srcF = sourceNode.gender === 'F' || (!sourceNode.gender && FamilyTreeBuilder._isFemaleName(sourceNode.name));

        if (candM && !srcM) return { isHusband: true, isWife: false };
        if (srcM && !candM) return { isHusband: false, isWife: true };
        if (candF && !srcF) return { isHusband: false, isWife: true };
        if (srcF && !candF) return { isHusband: true, isWife: false };

        const rowRoles = FamilyTreeBuilder._deduceSpousalRolesByRowProximity(candidate, sourceNode);
        if (rowRoles) return rowRoles;

        if (relationType === 'husband' || sourceNode.spouseType === 'husband') return { isHusband: true, isWife: false };
        if (relationType === 'wife' || sourceNode.spouseType === 'wife') return { isHusband: false, isWife: true };

        return { isHusband: false, isWife: false };
    }

    /**
     * Evaluates biological age difference constraints between candidate and source node.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Source node
     * @param {string} relationType - Relation role string
     * @param {boolean} sourceExplicitlyClaimsCand - Whether source node explicitly claims candidate
     * @returns {boolean} True if age difference is biologically acceptable
     *
     * @example
     * FamilyTreeBuilder._areSpousalAgesCompatible({ yob: 1950, gender: 'M' }, { yob: 1952, gender: 'F' }, 'husband', true);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._areSpousalAgesCompatible({ yob: 1990, gender: 'M' }, { yob: 1950, gender: 'F' }, 'husband', false);
     * // => false
     */
    static _areSpousalAgesCompatible(candidate, sourceNode, relationType, sourceExplicitlyClaimsCand) {
        if (!candidate.yob || !sourceNode.yob) return true;

        const ageDiff = candidate.yob - sourceNode.yob; 
        const { isHusband, isWife } = FamilyTreeBuilder._deduceSpousalRoles(candidate, sourceNode, relationType);
        const maxDiff = FamilyTreeBuilder._getMaxSpouseAgeDiff(candidate, sourceNode);

        if (isHusband && !isWife) {
            if (ageDiff < -maxDiff || ageDiff > 0) return false; 
        } else if (isWife && !isHusband) {
            if (ageDiff < 0 || ageDiff > maxDiff) return false; 
        } else {
            // Gender-Unknown partner handling: allow partners when genders are indeterminate
            const isExplicitClaim = sourceExplicitlyClaimsCand || FamilyTreeBuilder._claimsAsSpouse(candidate, sourceNode);
            const unknownLimit = isExplicitClaim ? maxDiff : FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_UNKNOWN_GENDER_DIFF;
            if (Math.abs(ageDiff) > unknownLimit) return false;
        }
        return true;
    }

    /**
     * Computes the spousal alignment bonus for a first-cousin parent candidate.
     *
     * @param {Object} candidate - Candidate parent node
     * @param {string} otherParentStr - Normalized name of the other declared parent
     * @param {Object} nodeMap - Complete node map
     * @returns {number} Score bonus (1000 if spouses match, else 0)
     *
     * @example
     * FamilyTreeBuilder._computeParentCandidateSpouseBonus({ spouse: 'mary' }, 'mary', {});
     * // => 1000
     *
     * @example
     * FamilyTreeBuilder._computeParentCandidateSpouseBonus({ spouse: 'anna' }, 'mary', {});
     * // => 0
     */
    static _computeParentCandidateSpouseBonus(candidate, otherParentStr, nodeMap) {
        if (!FamilyTreeBuilder._isNamedParent(otherParentStr)) return 0;
        const cSp = FamilyTreeBuilder._normText(candidate.spouse);
        if (cSp === otherParentStr || (candidate.partners || []).some(pid => FamilyTreeBuilder._normText(nodeMap[pid]?._normName || nodeMap[pid]?.name) === otherParentStr)) {
            return 1000;
        }
        return 0;
    }

    /**
     * Computes the generational fitness score between a parent candidate and a child node.
     *
     * @param {Object} candidate - Candidate parent node
     * @param {Object} node - Child node
     * @returns {number} Generational fitness bonus or 0 if birth years are unavailable
     *
     * @example
     * FamilyTreeBuilder._computeGenerationalFitnessBonus({ yob: 1950 }, { yob: 1980 });
     * // => 100
     *
     * @example
     * FamilyTreeBuilder._computeGenerationalFitnessBonus({}, { yob: 1980 });
     * // => 0
     */
    static _computeGenerationalFitnessBonus(candidate, node) {
        const cYob = FamilyTreeBuilder._effectiveYob(candidate);
        const nYob = FamilyTreeBuilder._effectiveYob(node);
        if (!cYob || !nYob) return 0;
        return FamilyTreeBuilder.computeGenerationalFitness(
            nYob, cYob, 30,
            FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE, 60
        );
    }

    /**
     * Scores a candidate parent for a node during first-cousin ancestry resolution.
     * Prioritizes co-parent alignment, ancestor row seniority, generational fitness,
     * and penalizes excessive spreadsheet row distance.
     *
     * @param {Object} candidate - Candidate parent node
     * @param {Object} node - Child node
     * @param {boolean} isMom - True if evaluating mother, false for father
     * @param {Object} nodeMap - Complete node map
     * @returns {number} Relative fitness score
     *
     * @example
     * FamilyTreeBuilder._scoreFirstCousinParentCandidate({ id: 'p1' }, { id: 'c1' }, true, {});
     * // => 0
     *
     * @example
     * FamilyTreeBuilder._scoreFirstCousinParentCandidate({ id: 'p1', _sheetRow: 1 }, { id: 'c1', _sheetRow: 10 }, true, {});
     * // => 491
     */
    static _scoreFirstCousinParentCandidate(candidate, node, isMom, nodeMap) {
        const otherParentStr = isMom ? FamilyTreeBuilder._normText(node.father) : FamilyTreeBuilder._normText(node.mom);
        let score = FamilyTreeBuilder._computeParentCandidateSpouseBonus(candidate, otherParentStr, nodeMap);

        const cRow = FamilyTreeBuilder._getNodeEffectiveRow(candidate);
        const nRow = FamilyTreeBuilder._getNodeEffectiveRow(node);
        if (cRow < nRow) score += 500;

        score += FamilyTreeBuilder._computeGenerationalFitnessBonus(candidate, node);
        score -= Math.abs(cRow - nRow);
        return score;
    }

    /**
     * Adds a person node and all their partners/spouses into the parental cluster.
     *
     * @param {Object} p - Parent person node
     * @param {Object[]} parents - Cluster accumulator array
     * @param {Set<string>} seenIds - Set of node IDs already in cluster
     * @param {Object} [nodeMap={}] - Node map by ID
     * @param {Object[]} [allNodes=[]] - Array of all nodes
     *
     * @example
     * const parents = [], seen = new Set();
     * FamilyTreeBuilder._addParentAndPartnersToCluster({ id: 'p1', partners: ['p2'] }, parents, seen, { p2: { id: 'p2' } });
     * // parents contains [{ id: 'p1', ... }, { id: 'p2' }]
     *
     * @example
     * const parents = [], seen = new Set(['p1']);
     * FamilyTreeBuilder._addParentAndPartnersToCluster({ id: 'p1' }, parents, seen, {});
     * // parents remains empty (already seen)
     */
    static _addParentAndPartnersToCluster(p, parents, seenIds, nodeMap = {}, allNodes = []) {
        if (!p || seenIds.has(p.id || p)) return;
        seenIds.add(p.id || p);
        parents.push(p);

        for (const pid of (p.partners || [])) {
            if (nodeMap[pid] && !seenIds.has(pid)) {
                seenIds.add(pid);
                parents.push(nodeMap[pid]);
            }
        }

        if (p.spouse) {
            const spNorm = FamilyTreeBuilder._normText(p.spouse);
            const spMatches = allNodes.filter(sp => sp && sp !== p && FamilyTreeBuilder.sharesSheet(sp, p) && FamilyTreeBuilder._normText(sp._normName || sp.name) === spNorm);
            for (const sp of spMatches) {
                if (!seenIds.has(sp.id || sp)) {
                    seenIds.add(sp.id || sp);
                    parents.push(sp);
                }
            }
        }
    }

    /**
     * Resolves the best-matching candidate parent node by name and gender compatibility on the same sheet.
     *
     * @param {Object} node - Seeking child node
     * @param {string} parentStr - Declared parent name string
     * @param {boolean} isMom - True if mother, false if father
     * @param {Object} [nodeMap={}] - Node map by ID
     * @param {Object[]} [allNodes=[]] - Array of all nodes
     * @returns {Object|null} Best-scoring matching parent node or null
     *
     * @example
     * FamilyTreeBuilder._findBestMatchingParentNode({ id: 'c1', _sheet: 's1' }, 'Emily', true, {}, [{ id: 'p1', name: 'Emily', gender: 'F', _sheet: 's1' }]);
     * // => { id: 'p1', name: 'Emily', ... }
     *
     * @example
     * FamilyTreeBuilder._findBestMatchingParentNode({ id: 'c1' }, '', true, {}, []);
     * // => null
     */
    static _findBestMatchingParentNode(node, parentStr, isMom, nodeMap = {}, allNodes = []) {
        const pStr = FamilyTreeBuilder._normText(parentStr);
        if (!FamilyTreeBuilder._isNamedParent(pStr)) return null;

        const expectedGender = isMom ? 'F' : 'M';
        const relation = isMom ? 'mother' : 'father';
        const matches = allNodes.filter(n =>
            n && n !== node &&
            FamilyTreeBuilder.sharesSheet(n, node) &&
            FamilyTreeBuilder._normText(n._normName || n.name) === pStr &&
            (n.gender === expectedGender || !n.gender) &&
            FamilyTreeBuilder._isValidParentCandidate(n, node, relation, pStr, nodeMap, true)
        );
        matches.sort((m1, m2) =>
            FamilyTreeBuilder._scoreFirstCousinParentCandidate(m2, node, isMom, nodeMap) -
            FamilyTreeBuilder._scoreFirstCousinParentCandidate(m1, node, isMom, nodeMap)
        );
        return matches.length > 0 ? matches[0] : null;
    }

    /**
     * Resolves the parental cluster (parents, co-parents, partners, and spouses) for a node.
     *
     * @param {Object} node - Target node
     * @param {Object} [nodeMap={}] - Map of all nodes keyed by id
     * @returns {Array<Object>} List of resolved parent and parental-spouse nodes
     *
     * @example
     * FamilyTreeBuilder._resolveNodeParentCluster({ id: 'c1', momId: 'm1' }, { m1: { id: 'm1', partners: [] } });
     * // => [{ id: 'm1', ... }]
     *
     * @example
     * FamilyTreeBuilder._resolveNodeParentCluster({ id: 'c1' }, {});
     * // => []
     */
    static _resolveNodeParentCluster(node, nodeMap = {}) {
        const parents = [];
        const seenIds = new Set();
        const allNodes = Object.values(nodeMap || {});

        const resolveParent = (parentId, parentStr, isMom) => {
            if (parentId && nodeMap[parentId]) {
                FamilyTreeBuilder._addParentAndPartnersToCluster(nodeMap[parentId], parents, seenIds, nodeMap, allNodes);
                return;
            }
            const match = FamilyTreeBuilder._findBestMatchingParentNode(node, parentStr, isMom, nodeMap, allNodes);
            if (match) {
                FamilyTreeBuilder._addParentAndPartnersToCluster(match, parents, seenIds, nodeMap, allNodes);
            }
        };

        resolveParent(node.momId, node.mom, true);
        resolveParent(node.fatherId, node.father, false);
        return parents;
    }

    /**
     * Determines whether two individuals are biological first cousins by inspecting shared grandparents.
     * Evaluates parental clusters for both nodes and checks for common grandparents or biological
     * sibling relationships between parents.
     * 
     * @param {Object} nodeA - First node
     * @param {Object} nodeB - Second node
     * @param {Object} [nodeMap={}] - Map of all nodes keyed by id
     * @returns {boolean} True if individuals are biological first cousins
     *
     * @example
     * FamilyTreeBuilder._areFirstCousins({ id: '1', _sheet: 's1' }, { id: '2', _sheet: 's1' }, {});
     * // => false
     *
     * @example
     * FamilyTreeBuilder._areFirstCousins(null, null, {});
     * // => false
     */
    static _areFirstCousins(nodeA, nodeB, nodeMap = {}) {
        if (!nodeA || !nodeB || FamilyTreeBuilder._isSameNode(nodeA, nodeB)) return false;
        if (!FamilyTreeBuilder.sharesSheet(nodeA, nodeB)) return false;

        const parentsA = FamilyTreeBuilder._resolveNodeParentCluster(nodeA, nodeMap);
        const parentsB = FamilyTreeBuilder._resolveNodeParentCluster(nodeB, nodeMap);

        for (const pA of parentsA) {
            for (const pB of parentsB) {
                if (FamilyTreeBuilder._isSameNode(pA, pB)) continue;
                if (FamilyTreeBuilder._areBiologicalSiblings(pA, pB)) return true;

                const pAMom = FamilyTreeBuilder._normText(pA.mom), pADad = FamilyTreeBuilder._normText(pA.father);
                const pBMom = FamilyTreeBuilder._normText(pB.mom), pBDad = FamilyTreeBuilder._normText(pB.father);
                if (FamilyTreeBuilder._isNamedParent(pAMom) && (pAMom === pBMom || pAMom === pBDad)) return true;
                if (FamilyTreeBuilder._isNamedParent(pADad) && (pADad === pBMom || pADad === pBDad)) return true;
            }
        }
        return false;
    }

    /**
     * Determines whether a candidate spouse is already exclusively claimed by another person.
     *
     * @param {Object} candidate - Potential spouse candidate
     * @param {string} srcNorm - Normalized source person name
     * @param {boolean} isImplicitNamedSpouse - Whether source is an implicit named spouse
     * @param {boolean} sourceExplicitlyClaimsCand - Whether source explicitly claims candidate
     * @returns {boolean} True if candidate is claimed by another partner
     *
     * @example
     * FamilyTreeBuilder._isCandidateTakenByOtherSpouse({ spouse: 'Other' }, 'john', false, false);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateTakenByOtherSpouse({ spouse: 'John' }, 'john', false, false);
     * // => false
     */
    static _isCandidateTakenByOtherSpouse(candidate, srcNorm, isImplicitNamedSpouse, sourceExplicitlyClaimsCand) {
        if (isImplicitNamedSpouse || sourceExplicitlyClaimsCand) return false;
        const candSpouseStrs = [
            candidate.spouse, 
            ...(candidate._localImplicitSpouses || [])
        ].filter(Boolean).map(s => s.toLowerCase().trim());

        return candSpouseStrs.length > 0 && 
            !candSpouseStrs.some(s => s === srcNorm || s.includes(srcNorm) || srcNorm.includes(s));
    }

    /**
     * Checks if a candidate-source pairing violates biological kinship (siblings, parent-child, first cousins)
     * or celibacy vows unless both have explicitly claimed each other as spouses.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Seeking person node
     * @param {boolean} bothExplicitlyClaim - True if reciprocal spouse claims exist
     * @param {Object} [nodeMap={}] - Complete domain node map
     * @returns {boolean} True if kinship or religious vows prohibit pairing
     *
     * @example
     * FamilyTreeBuilder._hasIncestOrCelibacyConflict({ id: '1', mom: 'Mary', _sheet: 's1' }, { id: '2', mom: 'Mary', _sheet: 's1' }, false, {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasIncestOrCelibacyConflict({ id: '1' }, { id: '2' }, false, {});
     * // => false
     */
    static _hasIncestOrCelibacyConflict(candidate, sourceNode, bothExplicitlyClaim, nodeMap = {}) {
        if (FamilyTreeBuilder._isSameNode(candidate, sourceNode)) return true;
        if (FamilyTreeBuilder._areBiologicalSiblings(candidate, sourceNode)) return true;
        if (!bothExplicitlyClaim && (FamilyTreeBuilder._isCelibateReligious(candidate) || FamilyTreeBuilder._isCelibateReligious(sourceNode))) return true;
        if (FamilyTreeBuilder._isBiologicalParentChild(candidate, sourceNode)) return true;
        if (!bothExplicitlyClaim && FamilyTreeBuilder._areFirstCousins(candidate, sourceNode, nodeMap)) return true;
        return false;
    }

    /**
     * Validates spreadsheet row distance bounds for spouse candidates lacking known birth years.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Seeking person node
     * @param {boolean} isCoSpouse - Whether candidate is an adjacent co-spouse
     * @param {boolean} isImplicitNamedSpouse - Whether source name embeds candidate's name with wife/husband
     * @param {boolean} sourceExplicitlyClaimsCand - Whether source explicitly claims candidate
     * @returns {boolean} True if within allowable row distance
     *
     * @example
     * FamilyTreeBuilder._isRowProximityValidForSpouse({ yob: 1950 }, { yob: 1952 }, false, false, false);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isRowProximityValidForSpouse({ _sheetRow: 10 }, { _sheetRow: 80 }, false, false, false);
     * // => false
     */
    static _isRowProximityValidForSpouse(candidate, sourceNode, isCoSpouse, isImplicitNamedSpouse, sourceExplicitlyClaimsCand) {
        if (candidate.yob && sourceNode.yob) return true;
        const dist = FamilyTreeBuilder._getMinRowDistance(candidate, sourceNode);
        const isExplicitClaim = sourceExplicitlyClaimsCand || FamilyTreeBuilder._claimsAsSpouse(candidate, sourceNode);
        const maxDist = (isImplicitNamedSpouse || isExplicitClaim) ? 50 : 3;
        return isCoSpouse || dist <= maxDist || dist === 9999;
    }

    /**
     * Determines whether source profile name represents an implicit named spouse (e.g. 'John Wife').
     *
     * @param {Object} sourceNode - Source subject node
     * @param {string} candNorm - Normalized candidate name
     * @returns {boolean} True if source name includes candidate name with wife/husband role
     *
     * @example
     * FamilyTreeBuilder._isImplicitNamedSpouse({ _normName: 'john wife' }, 'john');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isImplicitNamedSpouse({ _normName: 'mary' }, 'john');
     * // => false
     */
    static _isImplicitNamedSpouse(sourceNode, candNorm) {
        const normName = sourceNode._normName || '';
        return Boolean(candNorm && normName.includes(candNorm) && (normName.includes('wife') || normName.includes('husband')));
    }

    /**
     * Checks if candidate violates cross-sheet sharing or descendant namesake constraints.
     *
     * @param {Object} candidate - Spouse candidate
     * @param {Object} sourceNode - Source subject node
     * @param {boolean} isImplicitNamedSpouse - Whether source contains candidate's name as wife/husband
     * @param {boolean} sourceExplicitlyClaimsCand - Whether source explicitly claims candidate
     * @param {Object} [nodeMap={}] - Complete node directory
     * @returns {boolean} True if candidate has a cross-sheet or descendant conflict
     *
     * @example
     * FamilyTreeBuilder._hasCrossSheetOrDescendantConflict({ _sheet: 's1' }, { _sheet: 's1' }, false, false, {});
     * // => false
     *
     * @example
     * FamilyTreeBuilder._hasCrossSheetOrDescendantConflict({ _sheet: 's1' }, { _sheet: 's2' }, false, false, {});
     * // => true
     */
    static _hasCrossSheetOrDescendantConflict(candidate, sourceNode, isImplicitNamedSpouse, sourceExplicitlyClaimsCand, nodeMap = {}) {
        if (!FamilyTreeBuilder.sharesSheet(candidate, sourceNode)) {
            const isExplicitClaim = sourceExplicitlyClaimsCand || FamilyTreeBuilder._claimsAsSpouse(candidate, sourceNode);
            if (!isImplicitNamedSpouse && !isExplicitClaim) return true;
        }
        if (!isImplicitNamedSpouse && FamilyTreeBuilder._isDescendantNamesake(candidate, sourceNode, Object.values(nodeMap || {}))) {
            return true;
        }
        return false;
    }

    /**
     * Evaluates whether two candidate spouse nodes have cross-sheet, descendant, or candidate-taken conflicts.
     *
     * @param {Object} candidate - Candidate spouse node
     * @param {Object} sourceNode - Reference node seeking spouse
     * @param {string} candNorm - Normalized candidate name
     * @param {string} srcNorm - Normalized source node name
     * @param {Object} nodeMap - Mapping of person IDs to nodes
     * @returns {boolean} True if a conflict exists preventing marriage
     *
     * @example
     * FamilyTreeBuilder._hasSpousalContextConflicts({ id: 'c1', name: 'Mary' }, { id: 's1', name: 'John' }, 'mary', 'john', {});
     * // => false
     *
     * @example
     * FamilyTreeBuilder._hasSpousalContextConflicts({ id: 'c2', name: 'Mary' }, { id: 's1', name: 'John' }, 'mary', 'john', {});
     * // => true
     */
    static _hasSpousalContextConflicts(candidate, sourceNode, candNorm, srcNorm, nodeMap) {
        const isImplicitNamedSpouse = FamilyTreeBuilder._isImplicitNamedSpouse(sourceNode, candNorm);
        const sourceExplicitlyClaimsCand = FamilyTreeBuilder._claimsAsSpouse(sourceNode, candidate);

        if (FamilyTreeBuilder._isCandidateTakenByOtherSpouse(candidate, srcNorm, isImplicitNamedSpouse, sourceExplicitlyClaimsCand)) {
            return true;
        }

        if (FamilyTreeBuilder._hasCrossSheetOrDescendantConflict(candidate, sourceNode, isImplicitNamedSpouse, sourceExplicitlyClaimsCand, nodeMap)) {
            return true;
        }

        const isCoSpouse = FamilyTreeBuilder._isAdjacentCoSpouse(candidate, sourceNode, Object.values(nodeMap || {}));
        return !FamilyTreeBuilder._isRowProximityValidForSpouse(candidate, sourceNode, isCoSpouse, isImplicitNamedSpouse, sourceExplicitlyClaimsCand);
    }

    /**
     * Validates whether a candidate person node can be legally paired as a spouse with a source node.
     *
     * @param {Object} candidate - Potential spouse node being evaluated
     * @param {Object} sourceNode - Reference node seeking a spouse
     * @param {string} relationType - Desired relationship role ('husband' or 'wife')
     * @param {Object} [nodeMap={}] - Mapping of node IDs to person nodes
     * @returns {boolean} True if the candidate satisfies all eligibility rules
     *
     * @example
     * FamilyTreeBuilder._isValidSpouseCandidate({ id: 'w1', gender: 'F' }, { id: 'h1', gender: 'M' }, 'wife', {});
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isValidSpouseCandidate({ id: 'w1', gender: 'M' }, { id: 'h1', gender: 'M' }, 'wife', {});
     * // => false
     */
    static _isValidSpouseCandidate(candidate, sourceNode, relationType, nodeMap = {}) {
        const bothExplicitlyClaim = FamilyTreeBuilder._claimsAsSpouse(sourceNode, candidate) && FamilyTreeBuilder._claimsAsSpouse(candidate, sourceNode);
        if (FamilyTreeBuilder._hasIncestOrCelibacyConflict(candidate, sourceNode, bothExplicitlyClaim, nodeMap)) {
            return false;
        }

        const candNorm = FamilyTreeBuilder._normText(candidate._normName || candidate.name);
        const srcNorm = FamilyTreeBuilder._normText(sourceNode._normName || sourceNode.name);

        if (FamilyTreeBuilder._hasSpousalContextConflicts(candidate, sourceNode, candNorm, srcNorm, nodeMap)) {
            return false;
        }

        if (FamilyTreeBuilder._isExclusivelyMarriedToOther(candidate, sourceNode, srcNorm, nodeMap)) return false;
        if (FamilyTreeBuilder._isExclusivelyMarriedToOther(sourceNode, candidate, candNorm, nodeMap)) return false;

        const sourceExplicitlyClaimsCand = FamilyTreeBuilder._claimsAsSpouse(sourceNode, candidate);
        return FamilyTreeBuilder._areSpousalAgesCompatible(candidate, sourceNode, relationType, sourceExplicitlyClaimsCand);
    }

    /**
     * Determines whether two nodes share at least one spreadsheet source sheet ID.
     *
     * @param {Object} nodeA - First node
     * @param {Object} nodeB - Second node
     * @returns {boolean} True if both nodes originate from or appear on the same sheet
     *
     * @example
     * FamilyTreeBuilder.sharesSheet({ _sourceId: 'sheet1' }, { _sourceId: 'sheet1' });
     * // => true
     *
     * @example
     * FamilyTreeBuilder.sharesSheet({ _sourceId: 'sheet1' }, { _sourceId: 'sheet2' });
     * // => false
     */
    static sharesSheet(nodeA, nodeB) {
        if (nodeA._sourceIds && nodeB._sourceIds) {
            if (nodeA._sourceIds.size < nodeB._sourceIds.size) {
                for (const id of nodeA._sourceIds) {
                    if (nodeB._sourceIds.has(id)) return true;
                }
            } else {
                for (const id of nodeB._sourceIds) {
                    if (nodeA._sourceIds.has(id)) return true;
                }
            }
            return false;
        }
        return nodeA._sourceId === nodeB._sourceId;
    }

    /**
     * Executes a convergent multi-pass transformation loop until no further mutations occur or maxIterations is reached.
     * 
     * @param {Object[]} nodes - List of domain nodes
     * @param {Function} passFn - Callback (node, index) => boolean (returns true if mutation occurred)
     * @param {number} [maxIterations=20] - Maximum passes allowed before terminating
     * @returns {number} Actual iterations run
     *
     * @example
     * const items = [1, 2];
     * FamilyTreeBuilder._runConvergentPass(items, () => false);
     * // => 1
     *
     * @example
     * let count = 0;
     * FamilyTreeBuilder._runConvergentPass([1], () => { count++; return count < 3; }, 5);
     * // => 3
     */
    static _runConvergentPass(nodes, passFn, maxIterations = 20) {
        let changed = true;
        let iterations = 0;
        while (changed && iterations < maxIterations) {
            changed = false;
            iterations++;
            for (let i = 0; i < nodes.length; i++) {
                if (passFn(nodes[i], i)) {
                    changed = true;
                }
            }
        }
        return iterations;
    }

    /**
     * Captures a lightweight serializable signature of node attributes and edges to detect stabilization.
     *
     * @param {Object[]} nodes - Master node list
     * @returns {string} Graph state signature
     *
     * @example
     * const sig = this._snapshotDeductionState([{ id: 'p1', yob: 1950 }]);
     * // => "p1::...|..."
     *
     * @example
     * const sig = this._snapshotDeductionState([]);
     * // => ""
     */
    _snapshotDeductionState(nodes) {
        return nodes.map(n => `${n.id}:${n.bestYob || n._inferredYob || ''}:${n.gender || ''}:${n.momId || ''}:${n.fatherId || ''}:${(n.partners || []).join(',')}:${(n.ambiguities || []).map(a => (a.candidates || []).map(c => c.id).join(',')).join(';')}`).join('|');
    }

    /**
     * Executes a single pass of genealogical deductions across deduplicated nodes.
     *
     * @param {Object[]} deduplicated - Deduplicated domain nodes
     *
     * @example
     * builder._runSingleDeductionCycle(nodes);
     * // executes attribute inferences, ghost parent replacement, and spouse promotions
     *
     * @example
     * builder._runSingleDeductionCycle([]);
     * // no-op on empty list
     */
    _runSingleDeductionCycle(deduplicated) {
        this.inferYobs(deduplicated);
        this.inferGenders(deduplicated);
        this.inferLocations(deduplicated);
        this.inferFamilyNames(deduplicated);

        this.replaceGhostParentsWithConcrete(deduplicated);
        this.inferMissingParents(deduplicated);
        this.cleanupAmbiguities(deduplicated);
        this.promoteDeclaredSpouses(deduplicated);
    }

    /**
     * Executes the iterated age, gender, and relationship deduction loop until attributes
     * and relationships stabilize or the iteration limit is reached.
     * 
     * @param {Object[]} deduplicated - Deduplicated node list
     * 
     * @example
     * builder._runDeductionConvergenceLoop(nodes);
     * // runs inference cycles until snapshot state matches previous cycle
     *
     * @example
     * builder._runDeductionConvergenceLoop([]);
     * // terminates immediately on empty list
     */
    _runDeductionConvergenceLoop(deduplicated) {
        let deductionIteration = 0;
        const MAX_DEDUCTION_ITERATIONS = 10;
        let deductionChanged = true;

        while (deductionChanged && deductionIteration < MAX_DEDUCTION_ITERATIONS) {
            deductionIteration++;
            const stateBefore = this._snapshotDeductionState(deduplicated);
            this._runSingleDeductionCycle(deduplicated);
            const stateAfter = this._snapshotDeductionState(deduplicated);
            deductionChanged = (stateBefore !== stateAfter);
        }
    }

    /**
     * Executes entity expansion, free-form text parsing, relative synthesis, and relationship naming.
     *
     * @param {Object[]} deduplicated - Deduplicated domain nodes
     *
     * @example
     * builder._expandEntitiesAndRelationships(nodes);
     *
     * @example
     * builder._expandEntitiesAndRelationships([]);
     */
    _expandEntitiesAndRelationships(deduplicated) {
        this.preInferGenders(deduplicated);
        this.processFreeForm(deduplicated);
        this.expandRelativeReferences(deduplicated);
        this.linkExplicitSiblings(deduplicated);
        this.parseNameRelationships(deduplicated);
        this.generateMissingProfiles(deduplicated);
        this.parseNameRelationships(deduplicated);
    }

    /**
     * Finalizes tree structure by inferring deaths, cleaning redundant ghosts, coupling parents, merging roots, and locating root.
     *
     * @param {Object[]} deduplicated - Ingested domain nodes
     *
     * @example
     * builder._finalizeTreeStructure(nodes);
     *
     * @example
     * builder._finalizeTreeStructure([]);
     */
    _finalizeTreeStructure(deduplicated) {
        this.inferDeaths(deduplicated);
        this.cleanupRedundantGhosts(deduplicated);
        this._sortParentChildrenChronologically();
        this.inferYobs(Object.values(this.nodeMap));
        this._sortParentChildrenChronologically();
        this.ensureEveryParentHasPartner(deduplicated);
        this.mergeDisconnectedRoots(deduplicated);
        this.inferDeaths(Object.values(this.nodeMap));
        Object.values(this.nodeMap).forEach(n => {
            if (n && n.partners && n.partners.length > 1) {
                const partnerNodes = FamilyTreeBuilder._sortPartnersChronologically(
                    n.partners.map(pid => this.nodeMap[pid]).filter(Boolean)
                );
                n.partners = partnerNodes.map(p => p.id);
            }
        });
        this.findRoot(deduplicated);
    }

    /**
     * Constructs and links a complete hierarchical family tree graph from ingested spreadsheet rows.
     * 
     * Orchestrates normalization, entity expansion, biological linking, deduction convergence, and root resolution.
     * 
     * @returns {FamilyTree} Fully constructed FamilyTree domain model
     * 
     * @example
     * const tree = new FamilyTreeBuilder(rawRows).build();
     * // => returns initialized FamilyTree instance
     *
     * @example
     * const tree = new FamilyTreeBuilder([]).build();
     * // => returns empty FamilyTree instance
     */
    build() {
        FamilyTreeBuilder._dynamicFemaleNames = new Set();
        FamilyTreeBuilder._dynamicMaleNames = new Set();
        // Phase 1: Ingestion & Normalization
        const normalized = this.normalize(this.rawRows);
        const deduplicated = this.deduplicate(normalized);
        this.indexNodes(deduplicated);

        // Phase 2: Entity Expansion & Free-Form Parsing
        this._expandEntitiesAndRelationships(deduplicated);

        // Phase 3: Graph Linking & Biological Validation
        this.linkRelationships(deduplicated);
        this.inferMissingParents(deduplicated);
        this.validateParentChildLinks(deduplicated);

        // Phase 4 & 5: Iterated Age, Gender, and Relationship Deduction Loop
        // Continues until attribute and relationship deductions stabilize
        this._runDeductionConvergenceLoop(deduplicated);

        // Phase 6: Finalization & Root Selection
        this._finalizeTreeStructure(deduplicated);

        // Return structured Domain Model
        const tree = new FamilyTree(this.nodeMap, this.rootId, this.sheetNames);
        tree.rawRows = this.rawRows;
        return tree;
    }

    /**
     * Splits a name into relationship tokens (baseName, spouse, child, parent, number) by scanning right-to-left.
     *
     * @param {string[]} tokens - Name string tokens
     * @returns {Object|null} Map of token indices and base name if valid
     *
     * @example
     * builder._parseRelationshipTokens(["Ferrocy", "Son", "1", "Wife"]);
     * // => { baseName: "Ferrocy", cIdx: 1, sIdx: 3, nIdx: 2, ... }
     *
     * @example
     * builder._parseRelationshipTokens(["John"]);
     * // => null
     */
    _parseRelationshipTokens(tokens) {
        if (tokens.length < 2) return null;
        const cToks = new Set(['son', 'boy', 'daughter', 'girl']);
        const sToks = new Set(['wife', 'husband']);
        const pToks = new Set(['mother', 'mom', 'father', 'dad']);
        const bToks = new Set(['brother', 'sister', 'bro', 'sis']);

        let scan = tokens.length - 1, sIdx = -1, cIdx = -1, nIdx = -1, pIdx = -1, bIdx = -1;
        if (scan >= 1 && /^\d+$/.test(tokens[scan])) { nIdx = scan; scan--; }
        if (scan >= 1 && sToks.has(tokens[scan].toLowerCase())) {
            sIdx = scan; scan--;
            if (nIdx < 0 && scan >= 1 && /^\d+$/.test(tokens[scan])) { nIdx = scan; scan--; }
        }
        if (scan >= 1 && cToks.has(tokens[scan].toLowerCase())) { cIdx = scan; scan--; }
        if (cIdx < 0 && sIdx < 0 && scan >= 1 && pToks.has(tokens[scan].toLowerCase())) { pIdx = scan; scan--; }
        if (cIdx < 0 && sIdx < 0 && pIdx < 0 && scan >= 1 && bToks.has(tokens[scan].toLowerCase())) { bIdx = scan; scan--; }
        
        if (sIdx < 0 && cIdx < 0 && pIdx < 0 && bIdx < 0) return null;
        if (scan < 0) return null;

        return { baseName: tokens.slice(0, scan + 1).join(' '), scan, cIdx, sIdx, pIdx, bIdx, nIdx };
    }

    /**
     * Produces a normalized phonetic key by folding vowels and phonetic equivalents,
     * then collapsing consecutive duplicate characters.
     *
     * @param {string} name - Input name
     * @returns {{ folded: string, phonetic: string }} Canonical folded and phonetic representations
     *
     * @example
     * FamilyTreeBuilder._canonicalPhoneticKey('Kunjaagasthi');
     * // => { folded: 'kunjagasthi', phonetic: 'kunjagasti' }
     *
     * @example
     * FamilyTreeBuilder._canonicalPhoneticKey('Mary');
     * // => { folded: 'mary', phonetic: 'mary' }
     */
    static _canonicalPhoneticKey(name) {
        const collapse = w => w.replace(/(.)\1+/g, '$1');
        return {
            folded: collapse(FamilyTreeBuilder.foldVowels(name)),
            phonetic: collapse(FamilyTreeBuilder.foldPhonetic(name))
        };
    }

    /**
     * Retrieves candidate nodes from the name-to-nodes map matching either the exact
     * lowercased name or matching the vowel-folded / phonetic spelling variation.
     * 
     * @param {string} name - Identifier or name to search
     * @returns {Object[]} Matching candidate Person objects
     *
     * @example
     * builder._getCandidatesByName("Kunjagasthi");
     * // => [Person[Kunjaagasthi]]
     *
     * @example
     * builder._getCandidatesByName("");
     * // => []
     */
    _getCandidatesByName(name) {
        if (!name) return [];
        const lower = name.toLowerCase().trim();
        let cands = this.name2nodes[lower] || [];
        if (cands.length === 0) {
            const target = FamilyTreeBuilder._canonicalPhoneticKey(lower);
            Object.keys(this.name2nodes).forEach(k => {
                const cand = FamilyTreeBuilder._canonicalPhoneticKey(k);
                if (cand.folded === target.folded || cand.phonetic === target.phonetic) {
                    cands.push(...this.name2nodes[k]);
                }
            });
        }
        return Array.from(new Set(cands));
    }

    /**
     * Resolves an anchor relative through preceding numbered siblings on the same sheet
     * (e.g. searching backwards from "Son 3" through "Son 2" and "Son 1" to find shared anchor).
     *
     * @param {string} norm - Lowercase normalized base name
     * @param {Object} n - Source node
     * @returns {Object|null} Matching anchor relative if found
     *
     * @example
     * builder._findPrecedingNumberedRelativeAnchor('ferrocy', { name: 'Ferrocy Son 2' });
     * // => returns anchor person if found on previous numbered sibling
     *
     * @example
     * builder._findPrecedingNumberedRelativeAnchor('john', { name: 'John' });
     * // => null
     */
    _findPrecedingNumberedRelativeAnchor(norm, n) {
        const numMatch = (n.name || '').match(/^(.*?)\s+(?:Brother|Sister|Son|Daughter|Boy|Girl)\s+(\d+)$/i);
        if (!numMatch || numMatch[1].toLowerCase().trim() !== norm) return null;

        const role = n.name.match(/(?:Brother|Sister|Son|Daughter|Boy|Girl)/i)[0];
        const num = parseInt(numMatch[2], 10);
        for (let i = num - 1; i >= 1; i--) {
            const prevName = `${numMatch[1]} ${role} ${i}`.toLowerCase();
            const prevNode = Object.values(this.nodeMap).find(x => x && x._normName === prevName && FamilyTreeBuilder.sharesSheet(x, n));
            if (prevNode && prevNode.explicitSiblings && prevNode.explicitSiblings.length > 0) {
                const matchedAnchor = prevNode.explicitSiblings.map(id => this.nodeMap[id]).find(s => s && s._normName === norm);
                if (matchedAnchor) return matchedAnchor;
            }
        }
        return null;
    }

    /**
     * Attempts to find a relative on the same sheet by exact or spelling-folded name match.
     *
     * @param {string} baseName - Base name string to match
     * @param {Object} n - Source relative node
     * @returns {Object|null} Matching relative node or null
     *
     * @example
     * builder._findRelativeNode("Ferrocy", { _sourceId: 's1' });
     * // => returns matching node on same sheet
     *
     * @example
     * builder._findRelativeNode("NonExistent", { _sourceId: 's1' });
     * // => null
     */
    _findRelativeNode(baseName, n) {
        const norm = baseName.toLowerCase().trim();
        const precedingAnchor = this._findPrecedingNumberedRelativeAnchor(norm, n);
        if (precedingAnchor) return precedingAnchor;

        let cands = this._getCandidatesByName(baseName).filter(c => c !== n && FamilyTreeBuilder.sharesSheet(c, n));
        if (cands.length <= 1) return cands[0] || null;
        const bioValid = cands.filter(c => !(c.yob && n.yob && c.yob > n.yob - FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE));
        if (bioValid.length > 0) cands = bioValid;

        const matchingCands = cands.filter(c => FamilyTreeBuilder._computeCoParentMatchScore(c, n) > 0);
        if (matchingCands.length > 0) {
            cands = matchingCands;
        } else {
            const nonConflicting = cands.filter(c => FamilyTreeBuilder._computeCoParentMatchScore(c, n) >= 0);
            if (nonConflicting.length > 0) cands = nonConflicting;
        }

        cands.sort((a, b) => FamilyTreeBuilder._getMinRowDistance(a, n) - FamilyTreeBuilder._getMinRowDistance(b, n));
        return cands[0];
    }

    /**
     * Applies parent relationship from a node named "BaseName Mother/Father".
     *
     * @param {Object} n - Source node
     * @param {number} pIdx - Index of parent token in tokens array
     * @param {string[]} tokens - Token array of node name
     * @param {string} baseName - Base child name string
     *
     * @example
     * builder._applyParentNameRelationship({ name: 'Robin Mother' }, 1, ['Robin', 'Mother'], 'Robin');
     * // child Robin gets mom set to 'Robin Mother'
     *
     * @example
     * builder._applyParentNameRelationship({ name: 'Robin Father' }, 1, ['Robin', 'Father'], 'Robin');
     * // child Robin gets father set to 'Robin Father'
     */
    _applyParentNameRelationship(n, pIdx, tokens, baseName) {
        const tStr = tokens[pIdx].toLowerCase();
        const isMom = (tStr === 'mother' || tStr === 'mom');
        const childNode = this._findRelativeNode(baseName, n);
        if (childNode) {
            if (isMom && !childNode.mom) childNode.mom = n.name;
            else if (!isMom && !childNode.father) childNode.father = n.name;
        }
    }

    /**
     * Applies sibling relationship and links reciprocal references and shared parents
     * from a node named "BaseName Brother/Sister".
     * 
     * @param {Object} n - Source sibling node
     * @param {string} baseName - Anchor sibling name
     *
     * @example
     * builder._applySiblingNameRelationship({ name: 'Annamma Brother' }, 'Annamma');
     * // links reciprocal siblings and propagates shared parents
     *
     * @example
     * builder._applySiblingNameRelationship({ name: 'Standalone' }, 'Unknown');
     * // sets n.sibling = 'Unknown'
     */
    _applySiblingNameRelationship(n, baseName) {
        if (!n.sibling) n.sibling = baseName;
        const norm = baseName.toLowerCase().trim();
        let anchorNode = (n.explicitSiblings || [])
            .map(id => this.nodeMap[id])
            .find(s => s && s._normName === norm);
        if (!anchorNode) {
            anchorNode = this._findRelativeNode(baseName, n);
        }
        if (anchorNode) {
            this._linkSiblingReciprocal(n, anchorNode);
            this._propagateSiblingParent(n, anchorNode, 'mom');
            this._propagateSiblingParent(n, anchorNode, 'father');
        }
    }

    /**
     * Checks whether a parent node's declared spouse can be safely assigned as the mother of a child,
     * verifying that no earlier spreadsheet row on the same sheet already claimed that spouse as a partner.
     *
     * @param {Object} pNode - Parent node being evaluated
     * @param {string} spouseName - Declared spouse name on pNode
     * @returns {boolean} True if no earlier row on the same sheet partnered with spouseName
     *
     * @example
     * builder._isSpouseEligibleAsMother(fatherNode, 'Mary');
     * // => true
     *
     * @example
     * builder._isSpouseEligibleAsMother(fatherNode, '');
     * // => false
     */
    _isSpouseEligibleAsMother(pNode, spouseName) {
        if (!spouseName) return false;
        const spNode = this._findRelativeNode(spouseName, pNode);
        const pRow = FamilyTreeBuilder.getNodeSheetRow(pNode, null);
        if (pRow === null) return true;
        const spNorm = (spNode && spNode.name ? spNode.name : spouseName).toLowerCase().trim();
        const spId = spNode ? spNode.id : null;
        const allNodes = this.nodeMap ? Object.values(this.nodeMap) : [];
        // Guard against misattributing a remarried or namesake co-spouse already claimed by an earlier union row.
        const hasEarlierPartner = allNodes.some(other => {
            if (!other || other.id === pNode.id) return false;
            if (!FamilyTreeBuilder.sharesSheet(pNode, other)) return false;
            const oRow = FamilyTreeBuilder.getNodeSheetRow(other, null);
            if (oRow === null || oRow >= pRow) return false;
            const otherSpNorm = (other.spouse || '').toLowerCase().trim();
            return otherSpNorm === spNorm || (spId && other.partners && other.partners.includes(spId));
        });
        return !hasEarlierPartner;
    }

    /**
     * Resolves parent/spouse roles by spreadsheet row-order convention when both parent and spouse names
     * are gender-neutral (traditional genealogical sheets list husband on an earlier row than wife).
     *
     * @param {Object} n - Child node being linked
     * @param {Object} pNode - Named parent node with gender-neutral name and spouse
     * @returns {void}
     *
     * @example
     * builder._assignParentRoleByRowOrder(childNode, wifeOnLaterRow);
     * // => assigns wifeOnLaterRow as mother ('F') and earlier-row spouse as father
     *
     * @example
     * builder._assignParentRoleByRowOrder(childNode, husbandOnEarlierRow);
     * // => assigns husbandOnEarlierRow as father ('M') and later-row spouse as mother
     */
    _assignParentRoleByRowOrder(n, pNode) {
        const pRow = FamilyTreeBuilder.getNodeSheetRow(pNode);
        const spCandidate = this._findRelativeNode(pNode.spouse, pNode);
        const spRow = spCandidate ? FamilyTreeBuilder.getNodeSheetRow(spCandidate) : null;
        if (!pRow || !spRow || pRow === spRow) return;
        if (pRow > spRow) {
            pNode.gender = 'F';
            n.mom = pNode.name;
            n.momId = pNode.id;
            n.father = pNode.spouse;
            if (spCandidate) n.fatherId = spCandidate.id;
        } else {
            pNode.gender = 'M';
            n.father = pNode.name;
            n.fatherId = pNode.id;
            if (this._isSpouseEligibleAsMother(pNode, pNode.spouse)) {
                n.mom = pNode.spouse;
                if (spCandidate) n.momId = spCandidate.id;
            }
        }
    }

    /**
     * Deduces and assigns parent/spouse roles when the named parent node has ambiguous gender,
     * using spouse name gender hints or spreadsheet row-order conventions (husband precedes wife).
     *
     * @param {Object} n - Child node being linked
     * @param {Object} pNode - Named parent node with ambiguous gender
     * @returns {void}
     *
     * @example
     * builder._assignParentRoleBySpouseAndRow(childNode, parentWithMaleSpouse);
     * // => assigns parentWithMaleSpouse as mother ('F') and spouse as father
     *
     * @example
     * builder._assignParentRoleBySpouseAndRow(realChildNode, singleParentWithoutSpouse);
     * // => defaults singleParentWithoutSpouse to father ('M')
     */
    _assignParentRoleBySpouseAndRow(n, pNode) {
        if (!pNode.spouse) {
            if (!n.isGhost) {
                pNode.gender = 'M';
                n.father = pNode.name;
                n.fatherId = pNode.id;
            }
            return;
        }
        if (FamilyTreeBuilder._isMaleName(pNode.spouse)) {
            pNode.gender = 'F';
            n.mom = pNode.name;
            n.momId = pNode.id;
            n.father = pNode.spouse;
            return;
        }
        if (FamilyTreeBuilder._isFemaleName(pNode.spouse)) {
            pNode.gender = 'M';
            n.father = pNode.name;
            n.fatherId = pNode.id;
            if (this._isSpouseEligibleAsMother(pNode, pNode.spouse)) n.mom = pNode.spouse;
            return;
        }
        this._assignParentRoleByRowOrder(n, pNode);
    }

    /**
     * Links a child node to a named parent node deduced from child name tokens (e.g. "Tensy3 Son 1").
     *
     * @param {Object} n - Seeking child node
     * @param {string} baseName - Extracted base parent name string
     * @returns {boolean} True if a parent node was matched and linked
     *
     * @example
     * builder._applyNamedParentInChildName(childNode, 'Tensy');
     * // => true
     *
     * @example
     * builder._applyNamedParentInChildName(childNode, 'NonExistent');
     * // => false
     */
    _applyNamedParentInChildName(n, baseName) {
        const pNode = (n._namedParentId && this.nodeMap[n._namedParentId]) ? this.nodeMap[n._namedParentId] : this._findRelativeNode(baseName, n);
        if (!pNode) return false;

        const isMale = pNode.gender === 'M' || FamilyTreeBuilder._isMaleName(pNode.name);
        const isFemale = pNode.gender === 'F' || FamilyTreeBuilder._isFemaleName(pNode.name);

        if (isMale) {
            n.father = pNode.name;
            n.fatherId = pNode.id;
            if (!n.mom && pNode.spouse && this._isSpouseEligibleAsMother(pNode, pNode.spouse)) n.mom = pNode.spouse;
        } else if (isFemale) {
            n.mom = pNode.name;
            n.momId = pNode.id;
            if (!n.father && pNode.spouse) n.father = pNode.spouse;
        } else {
            this._assignParentRoleBySpouseAndRow(n, pNode);
        }
        n._namedParentId = pNode.id;
        n._namedParentName = pNode.name;
        if (!pNode.children) pNode.children = [];
        if (!pNode.children.includes(n.id)) pNode.children.push(n.id);
        return true;
    }

    /**
     * Applies parent and spouse relationship inferences for child-type name patterns.
     *
     * @param {Object} n - Target person node
     * @param {string} baseName - Extracted base parent name
     * @param {string[]} toks - Split name tokens
     * @param {number} sIdx - Index of spouse token (-1 if none)
     * @param {number} nIdx - Index of numeric child sequence token (-1 if none)
     *
     * @example
     * builder._applyChildNameRelationship(node, 'John', ['John', 'Son', '1'], -1, 2);
     * // => sets _nameChildNumber: 1
     *
     * @example
     * builder._applyChildNameRelationship(node, 'Mary', ['Mary', 'Daughter', 'Wife'], 2, -1);
     * // => sets spouse: 'Mary Daughter'
     */
    _applyChildNameRelationship(n, baseName, toks, sIdx, nIdx) {
        if (nIdx >= 0) n._nameChildNumber = parseInt(toks[nIdx], 10);
        if (sIdx >= 0) {
            if (!n.spouse) n.spouse = toks.slice(0, sIdx).join(' ');
            return;
        }
        if (this._applyNamedParentInChildName(n, baseName)) return;
        if (n.mom || n.father) return;
        n.mom = baseName;
    }

    /**
     * Parses relationship tokens in a single node's name and applies parent, sibling, spouse, or birth order links.
     *
     * @private
     * @param {Object} n - Person node with potentially structured name tokens
     *
     * @example
     * builder._parseNodeNameRelationship({ name: 'Ferrocy Son 1' });
     * // => sets _nameChildNumber: 1
     *
     * @example
     * builder._parseNodeNameRelationship({ name: 'John Wife' });
     * // => sets spouse: 'John'
     */
    _parseNodeNameRelationship(n) {
        if (!n.name) return;
        const toks = n.name.split(/\s+/);
        const parsed = this._parseRelationshipTokens(toks);
        if (!parsed) return;
        const { baseName, cIdx, sIdx, pIdx, bIdx, nIdx } = parsed;

        if (pIdx >= 0) {
            if (!n.isGhost) this._applyParentNameRelationship(n, pIdx, toks, baseName);
            return;
        }
        if (bIdx >= 0) {
            if (!n.isGhost) this._applySiblingNameRelationship(n, baseName);
            return;
        }
        if (cIdx < 0 && sIdx >= 0) {
            if (!n.spouse) n.spouse = baseName;
            return;
        }
        this._applyChildNameRelationship(n, baseName, toks, sIdx, nIdx);
    }

    /**
     * Parses structured name patterns to extract implicit family relationships.
     * Runs AFTER preInferGenders (so parent genders from name tokens are available)
     * and BEFORE/AFTER generateMissingProfiles (to handle both concrete and ghost nodes).
     *
     * Naming Convention:
     *   <ParentName> <ChildToken> [<Number>] [<SpouseToken>]
     *
     * Numbers indicate birth order: "Son 1" is older than "Son 2".
     *
     * @param {Array<Object>} nodes - Array of person nodes to process
     *
     * @example
     * builder.parseNameRelationships([{ name: 'Ferrocy Son 1' }]);
     * // parses child order and links parent Ferrocy
     *
     * @example
     * builder.parseNameRelationships([{ name: 'John Wife' }]);
     * // parses spouse relationship to John
     */
    parseNameRelationships(nodes) {
        nodes.forEach(n => this._parseNodeNameRelationship(n));
    }

    /**
     * Infers gender and vocation from religious titles ('Sr.', 'Fr.') or gendered suffixes ('appan', 'son').
     *
     * @param {Object} n - Profile node to inspect and populate
     *
     * @example
     * const n = { name: 'Sr. Alphonsa' };
     * builder._inferVocationAndSuffixGender(n);
     * // => n.gender === 'F', n.isNun === true
     *
     * @example
     * const n = { name: 'Fr. Kuriakose' };
     * builder._inferVocationAndSuffixGender(n);
     * // => n.gender === 'M', n.isPriest === true
     */
    _inferVocationAndSuffixGender(n) {
        if (!n.name) return;
        const lowerName = n.name.toLowerCase().trim();
        const lowerNick = (n.nick || '').toLowerCase().trim();

        // 1. Nun check: "Sr." or "Sr " prefix -> nun, female
        if (/^sr(?:\.|\s)\s*/i.test(lowerName) || (n.nick && /^sr(?:\.|\s)\s*/i.test(lowerNick))) {
            n.isNun = true;
            if (!n.job) n.job = 'Nun';
            if (!n.gender) n.gender = 'F';
        }
        // 2. Priest check: "Fr." or "Fr " prefix -> priest, male
        else if (/^fr(?:\.|\s)\s*/i.test(lowerName) || (n.nick && /^fr(?:\.|\s)\s*/i.test(lowerNick))) {
            n.isPriest = true;
            if (!n.job) n.job = 'Priest';
            if (!n.gender) n.gender = 'M';
        }
        // 3. Suffix check: "son", "appan" -> male
        else if (!n.gender && (lowerName.endsWith('appan') || lowerName.endsWith('son') || /\bson(?:\s+\d+)?$/i.test(lowerName))) {
            n.gender = 'M';
        }
    }

    /**
     * Infers the gender of a base profile when referenced by a relative spouse row
     * (e.g. "<BaseName> Husband" implies BaseName is female, "<BaseName> Wife" implies male).
     *
     * @param {Object} n - Relative node to inspect
     * @param {Object[]} nodes - List of existing domain nodes
     *
     * @example
     * const n = { name: 'Mary Husband', _sourceId: 's1' }, base = { _normName: 'mary', _sourceId: 's1' };
     * builder._inferSpouseSuffixGender(n, [base]);
     * // => base.gender === 'F'
     *
     * @example
     * const n = { name: 'John Wife', _sourceId: 's1' }, base = { _normName: 'john', _sourceId: 's1' };
     * builder._inferSpouseSuffixGender(n, [base]);
     * // => base.gender === 'M'
     */
    _inferSpouseSuffixGender(n, nodes) {
        if (!n.name) return;
        const match = n.name.match(/^(.+?)\s+(Husband|Wife)$/i);
        if (!match) return;
        const base = match[1].toLowerCase().trim();
        const impliedGender = match[2].toLowerCase() === 'husband' ? 'F' : 'M';
        const baseNode = nodes.find(o => o !== n &&
            (o._normName === base || FamilyTreeBuilder.foldVowels(o._normName) === FamilyTreeBuilder.foldVowels(base)) &&
            FamilyTreeBuilder.sharesSheet(o, n)
        );
        if (baseNode && !baseNode.gender) baseNode.gender = impliedGender;
    }

    /**
     * Infers node gender by scanning right-to-left tokens for gender indicators ("Wife", "Son"),
     * followed by static dictionary lookup and definitive morphological suffixes ('*amma', '*appan').
     *
     * @param {Object} n - Profile node
     * @param {Set<string>} maleTokens - Recognized male relationship indicator tokens
     * @param {Set<string>} femaleTokens - Recognized female relationship indicator tokens
     *
     * @example
     * const node = { name: 'Antu Son' };
     * builder._inferNameTokenGender(node, new Set(['son']), new Set(['daughter']));
     * // node.gender === 'M'
     *
     * @example
     * const node = { name: 'Mary' };
     * builder._inferNameTokenGender(node, new Set(['son']), new Set(['daughter']));
     * // node.gender === 'F' (via static dictionary)
     */
    _inferNameTokenGender(n, maleTokens, femaleTokens) {
        if (n.gender || !n.name) return;
        const lowerName = n.name.toLowerCase().trim();
        const tokens = lowerName.split(/\s+/);
        for (let i = tokens.length - 1; i >= 0; i--) {
            if (maleTokens.has(tokens[i])) { n.gender = 'M'; break; }
            if (femaleTokens.has(tokens[i])) { n.gender = 'F'; break; }
        }
        if (n.gender) return;

        if (FamilyTreeBuilder._isFemaleName(n.name)) {
            n.gender = 'F';
        } else if (FamilyTreeBuilder._isMaleName(n.name)) {
            n.gender = 'M';
        }
    }

    /**
     * Records a gender vote for a normalized name if it is not generic, unknown, or ghost.
     *
     * @param {Map<string, {F: number, M: number}>} evidence - Vote map
     * @param {string} name - Raw person name
     * @param {'F'|'M'} gender - Voted gender
     *
     * @example
     * const evidence = new Map();
     * FamilyTreeBuilder._recordGenderVote(evidence, 'Mary', 'F');
     * // evidence.get('mary') => { F: 1, M: 0 }
     *
     * @example
     * const evidence = new Map();
     * FamilyTreeBuilder._recordGenderVote(evidence, '(Unknown)', 'M');
     * // evidence.has('(unknown)') => false (ignored)
     */
    static _recordGenderVote(evidence, name, gender) {
        if (!name) return;
        const c = (typeof name === 'string' ? name.toLowerCase().trim() : '');
        if (!c || c.startsWith('(') || c.includes('unknown') || c.includes('ghost')) return;
        if (FamilyTreeBuilder._isGenericKinshipName && FamilyTreeBuilder._isGenericKinshipName(c)) return;
        if (!evidence.has(c)) evidence.set(c, { F: 0, M: 0 });
        evidence.get(c)[gender]++;
    }

    /**
     * Resolves the senior (male candidate) and junior (female candidate) members of a married pair
     * using birth year seniority first and spreadsheet row order as tiebreaker.
     *
     * @param {Object} nodeA - First spouse node
     * @param {Object} nodeB - Second spouse node
     * @returns {{ senior: Object, junior: Object }|null} Ordered pair or null if seniority is tied/unknown
     *
     * @example
     * FamilyTreeBuilder._resolveSeniorJuniorSpousePair({ name: 'Joseph', yob: 1920 }, { name: 'Mary', yob: 1925 });
     * // => { senior: { name: 'Joseph', yob: 1920 }, junior: { name: 'Mary', yob: 1925 } }
     *
     * @example
     * FamilyTreeBuilder._resolveSeniorJuniorSpousePair({ name: 'Anna', sheetRow: 15 }, { name: 'Thomas', sheetRow: 12 });
     * // => { senior: { name: 'Thomas', sheetRow: 12 }, junior: { name: 'Anna', sheetRow: 15 } }
     */
    static _resolveSeniorJuniorSpousePair(nodeA, nodeB) {
        const aYob = FamilyTreeBuilder._effectiveYob(nodeA);
        const bYob = FamilyTreeBuilder._effectiveYob(nodeB);
        if (aYob && bYob && aYob !== bYob) {
            return aYob < bYob ? { senior: nodeA, junior: nodeB } : { senior: nodeB, junior: nodeA };
        }
        const aRow = nodeA.sheetRow || nodeA._sheetRow;
        const bRow = nodeB.sheetRow || nodeB._sheetRow;
        if (aRow && bRow && aRow !== bRow) {
            return aRow < bRow ? { senior: nodeA, junior: nodeB } : { senior: nodeB, junior: nodeA };
        }
        return null;
    }

    /**
     * Votes for male/female names based on birth year or spreadsheet row seniority within married pairs.
     *
     * @param {Object[]} nodes - Array of domain Person nodes
     * @param {Map<string, {F: number, M: number}>} evidence - Vote map
     *
     * @example
     * const nodes = [
     *   { name: 'Joseph', spouse: 'Kochuthresia', yob: 1920, _sourceId: 's1' },
     *   { name: 'Kochuthresia', spouse: 'Joseph', yob: 1922, _sourceId: 's1' }
     * ];
     * const evidence = new Map();
     * FamilyTreeBuilder._collectSpousalSeniorityGenderEvidence(nodes, evidence);
     * // evidence.get('joseph').M === 1, evidence.get('kochuthresia').F === 1
     *
     * @example
     * const nodes = [
     *   { name: 'Anna', spouse: 'Thomas', yob: 1930, _sourceId: 's1' },
     *   { name: 'Thomas', spouse: 'Anna', yob: 1924, _sourceId: 's1' }
     * ];
     * const evidence = new Map();
     * FamilyTreeBuilder._collectSpousalSeniorityGenderEvidence(nodes, evidence);
     * // evidence.get('thomas').M === 1, evidence.get('anna').F === 1
     */
    static _collectSpousalSeniorityGenderEvidence(nodes, evidence) {
        nodes.forEach(n => {
            if (!n.spouse) return;
            const spName = (n.spouse || '').toLowerCase().trim();
            const spouseCand = nodes.find(o => o !== n && (o.name || '').toLowerCase().trim() === spName && FamilyTreeBuilder.sharesSheet(o, n));
            const pair = spouseCand && FamilyTreeBuilder._resolveSeniorJuniorSpousePair(n, spouseCand);
            if (!pair) return;
            FamilyTreeBuilder._recordGenderVote(evidence, pair.senior.name, 'M');
            FamilyTreeBuilder._recordGenderVote(evidence, pair.junior.name, 'F');
        });
    }

    /**
     * Votes for anchor genders based on relative role qualifiers (e.g. "<Name> Wife", "<Name> Husband").
     *
     * @param {Object[]} nodes - Array of domain Person nodes
     * @param {Map<string, {F: number, M: number}>} evidence - Vote map
     *
     * @example
     * const evidence = new Map();
     * FamilyTreeBuilder._collectRelativeNameGenderEvidence([{ name: 'George Wife' }], evidence);
     * // evidence.get('george').M === 1
     *
     * @example
     * const evidence = new Map();
     * FamilyTreeBuilder._collectRelativeNameGenderEvidence([{ name: 'Mary Husband 2' }], evidence);
     * // evidence.get('mary').F === 1
     */
    static _collectRelativeNameGenderEvidence(nodes, evidence) {
        nodes.forEach(n => {
            if (!n.name) return;
            const wifeMatch = n.name.match(/^(.+?)\s+Wife(?:\s+\d+)?$/i);
            if (wifeMatch) FamilyTreeBuilder._recordGenderVote(evidence, wifeMatch[1], 'M');
            const husMatch = n.name.match(/^(.+?)\s+Husband(?:\s+\d+)?$/i);
            if (husMatch) FamilyTreeBuilder._recordGenderVote(evidence, husMatch[1], 'F');
        });
    }

    /**
     * Populates dynamic female and male sets with names having strictly non-conflicting votes.
     * Names with contradictory evidence (e.g. votes for both F and M) are excluded.
     *
     * @param {Map<string, {F: number, M: number}>} evidence - Vote map
     * @param {Set<string>} dynF - Dynamic female name set
     * @param {Set<string>} dynM - Dynamic male name set
     *
     * @example
     * const evidence = new Map([['mary', { F: 3, M: 0 }], ['sunny', { F: 1, M: 1 }]]);
     * const dynF = new Set(), dynM = new Set();
     * FamilyTreeBuilder._populateUnanimousDynamicGenders(evidence, dynF, dynM);
     * // dynF.has('mary') === true, dynM.has('sunny') === false, dynF.has('sunny') === false
     *
     * @example
     * const evidence = new Map([['john', { F: 0, M: 2 }]]);
     * const dynF = new Set(), dynM = new Set();
     * FamilyTreeBuilder._populateUnanimousDynamicGenders(evidence, dynF, dynM);
     * // dynM.has('john') === true
     */
    static _populateUnanimousDynamicGenders(evidence, dynF, dynM) {
        for (const [name, counts] of evidence.entries()) {
            if (counts.F > 0 && counts.M === 0) {
                dynF.add(name);
            } else if (counts.M > 0 && counts.F === 0) {
                dynM.add(name);
            }
        }
    }

    /**
     * Dynamically populates gender name sets using non-conflicting relational evidence:
     * 1. Mother/Father columns (mothers are female, fathers are male).
     * 2. Marriage age seniority: in a married pair, the younger partner is female, older is male.
     * 3. Relative name patterns: '<Name> Wife' implies <Name> is male; '<Name> Husband' implies <Name> is female.
     *
     * Only names with strictly non-conflicting evidence (votes for one gender and 0 for the other)
     * are added to dynamic sets. Ambiguous/conflicting names (like 'Sunny') remain unassigned.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Set<string>} dynF - Dynamic female names set
     * @param {Set<string>} dynM - Dynamic male names set
     *
     * @example
     * const nodes = [
     *   { name: 'Joseph', gender: 'M' },
     *   { name: 'Mary', mom: 'Ann', father: 'Joachim' }
     * ];
     * const dynF = new Set(), dynM = new Set();
     * builder._seedDynamicGendersFromNonConflictingEvidence(nodes, dynF, dynM);
     * // dynF has 'ann', dynM has 'joachim' and 'joseph'
     *
     * @example
     * const nodes = [
     *   { name: 'Paul', spouse: 'Sara', yob: 1930, _sourceId: 's1' },
     *   { name: 'Sara', spouse: 'Paul', yob: 1935, _sourceId: 's1' }
     * ];
     * const dynF = new Set(), dynM = new Set();
     * builder._seedDynamicGendersFromNonConflictingEvidence(nodes, dynF, dynM);
     * // dynM has 'paul', dynF has 'sara'
     */
    _seedDynamicGendersFromNonConflictingEvidence(nodes, dynF, dynM) {
        const evidence = new Map();

        // 1. Evidence from explicit parental columns and explicit genders
        nodes.forEach(n => {
            if (n.mom) FamilyTreeBuilder._recordGenderVote(evidence, n.mom, 'F');
            if (n.father) FamilyTreeBuilder._recordGenderVote(evidence, n.father, 'M');
            if (n.gender === 'F') FamilyTreeBuilder._recordGenderVote(evidence, n.name, 'F');
            if (n.gender === 'M') FamilyTreeBuilder._recordGenderVote(evidence, n.name, 'M');
        });

        // 2. Evidence from married pairs: age seniority
        FamilyTreeBuilder._collectSpousalSeniorityGenderEvidence(nodes, evidence);

        // 3. Evidence from relative name patterns (<Name> Wife, <Name> Husband)
        FamilyTreeBuilder._collectRelativeNameGenderEvidence(nodes, evidence);

        // 4. Populate dynamic sets for non-conflicting names
        FamilyTreeBuilder._populateUnanimousDynamicGenders(evidence, dynF, dynM);
    }

    /**
     * Seeds dynamic gender name sets from parental relationships (mothers are female, fathers are male).
     *
     * @param {Object[]} nodes - Array of domain nodes
     * @param {Set<string>} dynF - Dynamic female name set
     * @param {Set<string>} dynM - Dynamic male name set
     *
     * @example
     * const nodes = [{ mom: 'Elizabeth', father: 'Zachariah' }];
     * const dynF = new Set(), dynM = new Set();
     * builder._seedDynamicGendersFromParents(nodes, dynF, dynM);
     * // dynF.has('elizabeth') === true, dynM.has('zachariah') === true
     *
     * @example
     * const nodes = [{ mom: 'John' }]; // 'John' is in static male dictionary
     * const dynF = new Set(), dynM = new Set();
     * builder._seedDynamicGendersFromParents(nodes, dynF, dynM);
     * // dynF.has('john') === false (skipped because static male)
     */
    _seedDynamicGendersFromParents(nodes, dynF, dynM) {
        const clean = (s) => (s || '').toLowerCase().trim();
        nodes.forEach(n => {
            if (n.mom) {
                const mClean = clean(n.mom);
                if (mClean && !FamilyTreeBuilder._isMaleName(mClean)) dynF.add(mClean);
            }
            if (n.father) {
                const fClean = clean(n.father);
                if (fClean && !FamilyTreeBuilder._isFemaleName(fClean)) dynM.add(fClean);
            }
        });
    }

    /**
     * Resolves unique candidate for a relative's name on the same sheet excluding the source node.
     *
     * @param {string} name - Relative name
     * @param {Object} sourceNode - Context node
     * @returns {Object|null} Unique relative node or null if 0 or >1 matches
     *
     * @example
     * const child = { id: 'c1', _sourceId: 's1' };
     * const relative = builder._getUniqueSheetRelative('Anthony', child);
     * // returns unique matching Anthony node on sheet 's1' or null
     *
     * @example
     * const child = { id: 'c1', _sourceId: 's1' };
     * const nonExistent = builder._getUniqueSheetRelative('', child);
     * // returns null
     */
    _getUniqueSheetRelative(name, sourceNode) {
        if (!name) return null;
        const cands = this.name2nodes[name.toLowerCase().trim()] || [];
        const valid = cands.filter(c => c === sourceNode ? false : FamilyTreeBuilder.sharesSheet(c, sourceNode));
        return valid.length === 1 ? valid[0] : null;
    }

    /**
     * Applies learned or dictionary gender to a node if gender is currently unassigned.
     *
     * @param {Object} n - Domain node
     * @param {Set<string>} dynF - Dynamic female names
     * @param {Set<string>} dynM - Dynamic male names
     * @returns {boolean} Whether node gender was assigned
     *
     * @example
     * const node = { name: 'Shanthi', gender: null };
     * FamilyTreeBuilder._applyLearnedGenderToNode(node, new Set(['shanthi']), new Set());
     * // returns true; node.gender === 'F'
     *
     * @example
     * const node = { name: 'George', gender: 'M' };
     * FamilyTreeBuilder._applyLearnedGenderToNode(node, new Set(), new Set(['george']));
     * // returns false (already assigned)
     */
    static _applyLearnedGenderToNode(n, dynF, dynM) {
        if (n.gender) return false;
        const nName = (n.name || '').toLowerCase().trim();
        if (FamilyTreeBuilder._isFemaleName(n.name) || dynF.has(nName)) {
            n.gender = 'F';
            return true;
        }
        if (FamilyTreeBuilder._isMaleName(n.name) || dynM.has(nName)) {
            n.gender = 'M';
            return true;
        }
        return false;
    }

    /**
     * Infers partner's name gender from known node gender and updates dynamic gender sets.
     *
     * @param {Object} n - Domain node
     * @param {string} spName - Lowercase normalized spouse name
     * @param {Set<string>} dynF - Dynamic female names
     * @param {Set<string>} dynM - Dynamic male names
     * @returns {boolean} Whether dynamic gender sets were updated
     *
     * @example
     * const maleNode = { name: 'Thomas', gender: 'M' };
     * const dynF = new Set(), dynM = new Set();
     * FamilyTreeBuilder._inferPartnerDynamicGender(maleNode, 'annu', dynF, dynM);
     * // returns true; dynF.has('annu') === true
     *
     * @example
     * const femaleNode = { name: 'Mary', gender: 'F' };
     * const dynF = new Set(), dynM = new Set();
     * FamilyTreeBuilder._inferPartnerDynamicGender(femaleNode, 'joseph', dynF, dynM);
     * // returns true; dynM.has('joseph') === true
     */
    static _inferPartnerDynamicGender(n, spName, dynF, dynM) {
        if (!spName) return false;
        const nName = (n.name || '').toLowerCase().trim();
        const isM = n.gender === 'M' || dynM.has(nName) || FamilyTreeBuilder._isMaleName(n.name);
        const isF = n.gender === 'F' || dynF.has(nName) || FamilyTreeBuilder._isFemaleName(n.name);
        if (isM && !isF) {
            if (!FamilyTreeBuilder._isMaleName(spName) && !dynM.has(spName) && !dynF.has(spName)) {
                dynF.add(spName);
                return true;
            }
        } else if (isF && !isM) {
            if (!FamilyTreeBuilder._isFemaleName(spName) && !dynF.has(spName) && !dynM.has(spName)) {
                dynM.add(spName);
                return true;
            }
        }
        return false;
    }

    /**
     * Applies dynamic or static name gender to a node and infers partner's name gender into dynamic sets.
     *
     * @param {Object} n - Domain node
     * @param {Set<string>} dynF - Dynamic female names
     * @param {Set<string>} dynM - Dynamic male names
     * @returns {boolean} Whether any node gender or dynamic name set was updated
     *
     * @example
     * const node = { name: 'Shanthi', gender: '', spouse: 'Varghese' };
     * const dynF = new Set(['shanthi']), dynM = new Set();
     * builder._propagateNodeAndPartnerDynamicGender(node, dynF, dynM);
     * // returns true; node.gender === 'F', dynM has 'varghese'
     *
     * @example
     * const node = { name: 'John', gender: 'M', spouse: '' };
     * const dynF = new Set(), dynM = new Set(['john']);
     * builder._propagateNodeAndPartnerDynamicGender(node, dynF, dynM);
     * // returns false (no unassigned attributes changed)
     */
    _propagateNodeAndPartnerDynamicGender(n, dynF, dynM) {
        let changed = false;
        if (FamilyTreeBuilder._applyLearnedGenderToNode(n, dynF, dynM)) changed = true;
        const spName = (n.spouse || '').toLowerCase().trim();
        if (FamilyTreeBuilder._inferPartnerDynamicGender(n, spName, dynF, dynM)) changed = true;
        return changed;
    }

    /**
     * Deduces missing gender for a spouse node based on partner gender or spouseType relationship.
     *
     * @param {Object} n - Declaring partner node
     * @param {Object} sp - Target spouse node lacking gender
     * @returns {'M'|'F'|null} Inferred gender or null if ambiguous
     *
     * @example
     * const n = { name: 'Mary', gender: 'F' };
     * const sp = { name: 'Joseph' };
     * FamilyTreeBuilder._deduceSpouseRelationalGender(n, sp);
     * // => 'M'
     *
     * @example
     * const n = { name: 'Anthony', gender: 'M' };
     * const sp = { name: 'Ann' };
     * FamilyTreeBuilder._deduceSpouseRelationalGender(n, sp);
     * // => 'F'
     */
    static _deduceSpouseRelationalGender(n, sp) {
        if (n.gender === 'F' && !FamilyTreeBuilder._isFemaleName(sp.name)) return 'M';
        if (n.gender === 'M' && !FamilyTreeBuilder._isMaleName(sp.name)) return 'F';
        if (n.spouseType === 'husband' && !n.gender && sp.spouseType !== 'husband' && sp.gender !== 'F') {
            if (!FamilyTreeBuilder._isFemaleName(sp.name) && !FamilyTreeBuilder._isMaleName(n.name)) return 'M';
        }
        if (n.spouseType === 'wife' && !n.gender && sp.spouseType !== 'wife' && sp.gender !== 'M') {
            if (!FamilyTreeBuilder._isMaleName(sp.name) && !FamilyTreeBuilder._isFemaleName(n.name)) return 'F';
        }
        return null;
    }

    /**
     * Propagates gender to uniquely identifiable parents and spouse of a node on the same sheet.
     *
     * @param {Object} n - Domain node
     * @returns {boolean} Whether any node's gender was updated
     *
     * @example
     * const child = { id: 'c1', father: 'Joseph', _sourceId: 's1' };
     * builder._propagateRelationalGenders(child);
     * // Joseph on same sheet gets gender='M', returns true
     *
     * @example
     * const person = { id: 'p1', spouse: 'Mary', gender: 'M', _sourceId: 's1' };
     * builder._propagateRelationalGenders(person);
     * // Mary on same sheet gets gender='F', returns true
     */
    _propagateRelationalGenders(n) {
        let changed = false;
        if (n.father) {
            const dad = this._getUniqueSheetRelative(n.father, n);
            if (dad && dad.gender !== 'M') { dad.gender = 'M'; changed = true; }
        }
        if (n.mom) {
            const mom = this._getUniqueSheetRelative(n.mom, n);
            if (mom && mom.gender !== 'F') { mom.gender = 'F'; changed = true; }
        }
        if (n.spouse) {
            const sp = this._getUniqueSheetRelative(n.spouse, n);
            if (sp && !sp.gender) {
                const inferredGender = FamilyTreeBuilder._deduceSpouseRelationalGender(n, sp);
                if (inferredGender) { sp.gender = inferredGender; changed = true; }
            }
        }
        return changed;
    }

    /**
     * Propagates learned name genders and resolves reciprocal spouse/parent node genders iteratively.
     *
     * @param {Object[]} nodes - Array of domain nodes
     * @param {Set<string>} dynF - Dynamic female name set
     * @param {Set<string>} dynM - Dynamic male name set
     *
     * @example
     * const nodes = [{ id: '1', name: 'Mary', gender: null }];
     * builder._propagateDynamicGenders(nodes, new Set(['mary']), new Set());
     * // nodes[0].gender becomes 'F'
     *
     * @example
     * const nodes = [
     *   { id: '1', name: 'Father1', gender: null, children: ['2'], _sourceId: 's1' },
     *   { id: '2', name: 'Child1', father: 'Father1', _sourceId: 's1' }
     * ];
     * builder._propagateDynamicGenders(nodes, new Set(), new Set());
     * // nodes[0].gender becomes 'M' via relational inference
     */
    _propagateDynamicGenders(nodes, dynF, dynM) {
        let changed = true;
        let iterations = 0;

        while (changed && iterations < 10) {
            changed = false;
            iterations++;

            nodes.forEach(n => {
                if (this._propagateNodeAndPartnerDynamicGender(n, dynF, dynM)) changed = true;
                if (this._propagateRelationalGenders(n)) changed = true;
            });
        }
    }

    /**
     * Pre-infers genders for profiles based on vocations (nun, priest), name suffixes,
     * relationship tokens, dynamic parental roles, and spouse propagation.
     *
     * @param {Object[]} nodes - List of domain Person/node objects
     *
     * @example
     * const nodes = [{ name: 'Sr. Mary', notes: '' }, { name: 'Fr. Joseph', notes: '' }];
     * builder.preInferGenders(nodes);
     * // nodes[0].gender === 'F', nodes[1].gender === 'M'
     *
     * @example
     * const nodes = [{ name: 'Antu Son' }, { name: 'George Wife' }];
     * builder.preInferGenders(nodes);
     * // nodes[0].gender === 'M'
     */
    preInferGenders(nodes) {
        const maleTokens = new Set(FamilyTreeBuilder.RELATIONSHIP_TOKENS.MALE_INDICATORS);
        const femaleTokens = new Set(FamilyTreeBuilder.RELATIONSHIP_TOKENS.FEMALE_INDICATORS);

        nodes.forEach(n => {
            this._inferVocationAndSuffixGender(n);
            this._inferSpouseSuffixGender(n, nodes);
            this._inferNameTokenGender(n, maleTokens, femaleTokens);
        });

        if (!FamilyTreeBuilder._dynamicFemaleNames) FamilyTreeBuilder._dynamicFemaleNames = new Set();
        if (!FamilyTreeBuilder._dynamicMaleNames) FamilyTreeBuilder._dynamicMaleNames = new Set();
        const dynF = FamilyTreeBuilder._dynamicFemaleNames;
        const dynM = FamilyTreeBuilder._dynamicMaleNames;

        this._seedDynamicGendersFromNonConflictingEvidence(nodes, dynF, dynM);
        this._seedDynamicGendersFromParents(nodes, dynF, dynM);
        this._propagateDynamicGenders(nodes, dynF, dynM);
    }

    /**
     * Checks if any child of a ghost parent is already linked to an existing non-ghost parent of the same gender.
     *
     * @param {Object} ghost - Ghost parent node
     * @returns {Object|null} Concrete replacement parent if found, null otherwise
     *
     * @example
     * const ghostMom = { id: 'g1', gender: 'F', children: ['c1'] };
     * builder.nodeMap = { c1: { momId: 'realMom' }, realMom: { id: 'realMom', isGhost: false } };
     * builder._findChildNonGhostParent(ghostMom);
     * // returns builder.nodeMap.realMom
     *
     * @example
     * const ghostDad = { id: 'g2', gender: 'M', children: ['c2'] };
     * builder.nodeMap = { c2: { fatherId: 'g2' } };
     * builder._findChildNonGhostParent(ghostDad);
     * // returns null (no distinct concrete parent found)
     */
    _findChildNonGhostParent(ghost) {
        for (const childId of ghost.children) {
            const child = this.nodeMap[childId];
            if (!child) continue;
            if (ghost.gender === 'F' && child.momId && child.momId !== ghost.id) {
                const m = this.nodeMap[child.momId];
                if (m && !m.isGhost) return m;
            } else if (ghost.gender === 'M' && child.fatherId && child.fatherId !== ghost.id) {
                const d = this.nodeMap[child.fatherId];
                if (d && !d.isGhost) return d;
            }
        }
        return null;
    }

    /**
     * Checks whether candidate replacement parent is compatible with all existing partners of the ghost parent.
     *
     * @private
     * @param {Object} c - Candidate concrete parent node
     * @param {Array<string>} ghostPartners - Partner IDs of the ghost parent
     * @param {Object<string, Object>} nodeMap - Global node lookup dictionary
     * @returns {boolean} True if candidate is compatible with all partners
     *
     * @example
     * FamilyTreeBuilder._isCandidateCompatibleWithGhostPartners(candNode, [], nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCandidateCompatibleWithGhostPartners(candNode, ['p1'], nodeMap);
     * // => true
     */
    static _isCandidateCompatibleWithGhostPartners(c, ghostPartners, nodeMap) {
        if (!ghostPartners || ghostPartners.length === 0) return true;
        return ghostPartners.every(pid => {
            const p = nodeMap[pid];
            return !p || (
                FamilyTreeBuilder._isValidSpouseCandidate(c, p, c.gender === 'M' ? 'husband' : 'wife', nodeMap) &&
                !FamilyTreeBuilder._isExclusivelyMarriedToOther(c, p, p._normName, nodeMap) &&
                (!c.mom || FamilyTreeBuilder._claimsAsSpouse(c, p) || FamilyTreeBuilder._claimsAsSpouse(p, c))
            );
        });
    }

    /**
     * Searches for a concrete parent replacement matching declared parent names on the ghost's children,
     * restricted to close row proximity (<= 15 rows) on the same sheet.
     *
     * @param {Object} ghost - Ghost parent node
     * @returns {Object|null} Nearest valid concrete parent candidate, or null
     *
     * @example
     * const ghostDad = { gender: 'M', children: ['c1'], partners: [] };
     * builder.nodeMap = { c1: { father: 'Joseph', _sourceId: 's1', _row: 10 } };
     * builder._findConcreteReplacementByChildDeclaredParent(ghostDad);
     * // returns matching concrete Joseph node within 15 rows on sheet 's1', or null
     *
     * @example
     * const ghostMom = { gender: 'F', children: ['c2'], partners: [] };
     * builder.nodeMap = { c2: { mom: 'Unknown' } };
     * builder._findConcreteReplacementByChildDeclaredParent(ghostMom);
     * // returns null
     */
    _findConcreteReplacementByChildDeclaredParent(ghost) {
        for (const childId of ghost.children) {
            const child = this.nodeMap[childId];
            if (!child) continue;
            const parentName = ghost.gender === 'F' ? child.mom : child.father;
            if (parentName && !parentName.endsWith(' Mother') && !parentName.endsWith(' Father')) {
                const relationType = ghost.gender === 'F' ? 'mother' : 'father';
                const cands = (this.name2nodes[parentName.toLowerCase().trim()] || []).filter(c => 
                    !c.isGhost && 
                    FamilyTreeBuilder.sharesSheet(c, child) &&
                    FamilyTreeBuilder._getMinRowDistance(c, child) <= 15 &&
                    FamilyTreeBuilder._isValidParentCandidate(c, child, relationType, parentName, this.nodeMap) &&
                    FamilyTreeBuilder._isCandidateCompatibleWithGhostPartners(c, ghost.partners, this.nodeMap)
                ).sort((a, b) => FamilyTreeBuilder._getMinRowDistance(a, child) - FamilyTreeBuilder._getMinRowDistance(b, child));
                if (cands.length > 0) return cands[0];
            }
        }
        return null;
    }

    /**
     * Reassigns valid children from a ghost parent to a concrete replacement profile.
     *
     * @param {Object} ghost - Ghost parent node
     * @param {Object} concreteReplacement - Target concrete parent node
     * @param {Object} [nodeMap={}] - Node map by ID
     *
     * @example
     * const ghost = { id: 'g1', gender: 'F', children: ['c1'] };
     * const real = { id: 'r1', gender: 'F', children: [] };
     * const nodeMap = { c1: { id: 'c1', mom: 'Mary', momId: 'g1' } };
     * FamilyTreeBuilder._transferGhostChildren(ghost, real, nodeMap);
     * // nodeMap.c1.momId === 'r1', real.children has 'c1', ghost.children is empty
     *
     * @example
     * const ghost = { id: 'g2', gender: 'M', children: ['c2'] };
     * const real = { id: 'r2', gender: 'M', children: ['c2'] };
     * const nodeMap = { c2: { id: 'c2', father: 'Joseph', fatherId: 'g2' } };
     * FamilyTreeBuilder._transferGhostChildren(ghost, real, nodeMap);
     * // ghost.children is empty, c2.fatherId === 'r2'
     */
    static _transferGhostChildren(ghost, concreteReplacement, nodeMap = {}) {
        const transferredChildIds = [];
        ghost.children.forEach(childId => {
            const child = nodeMap[childId];
            if (!child) return;
            const relationType = ghost.gender === 'F' ? 'mother' : 'father';
            const parentName = ghost.gender === 'F' ? child.mom : child.father;
            if (FamilyTreeBuilder._isValidParentCandidate(concreteReplacement, child, relationType, parentName, nodeMap)) {
                if (child.momId === ghost.id) child.momId = concreteReplacement.id;
                if (child.fatherId === ghost.id) child.fatherId = concreteReplacement.id;
                if (!concreteReplacement.children.includes(childId)) {
                    concreteReplacement.children.push(childId);
                }
                transferredChildIds.push(childId);
            }
        });
        ghost.children = ghost.children.filter(cid => !transferredChildIds.includes(cid));
    }

    /**
     * Re-links compatible spouses from a ghost parent to a concrete replacement profile.
     *
     * @param {Object} ghost - Ghost parent node
     * @param {Object} concreteReplacement - Target concrete parent node
     * @param {Object} [nodeMap={}] - Node map by ID
     *
     * @example
     * const ghost = { id: 'g1', partners: ['p1'] };
     * const real = { id: 'r1', partners: [], yob: 1920 };
     * const nodeMap = { p1: { id: 'p1', partners: ['g1'], yob: 1925 } };
     * FamilyTreeBuilder._transferGhostPartners(ghost, real, nodeMap);
     * // real.partners has 'p1', nodeMap.p1.partners has 'r1'
     *
     * @example
     * const ghost = { id: 'g2', partners: [] };
     * const real = { id: 'r2', partners: [] };
     * FamilyTreeBuilder._transferGhostPartners(ghost, real, {});
     * // leaves partners unmodified
     */
    static _transferGhostPartners(ghost, concreteReplacement, nodeMap = {}) {
        ghost.partners.forEach(partnerId => {
            const partner = nodeMap[partnerId];
            if (partner && partner.id !== concreteReplacement.id) {
                partner.partners = partner.partners.filter(id => id !== ghost.id && id !== concreteReplacement.id);
                const validSpouse = FamilyTreeBuilder._arePartnersAgeCompatible(concreteReplacement, partner, true);
                if (validSpouse) {
                    if (!partner.partners.includes(concreteReplacement.id)) {
                        partner.partners.push(concreteReplacement.id);
                    }
                    if (!concreteReplacement.partners.includes(partner.id)) {
                        concreteReplacement.partners.push(partner.id);
                    }
                }
            }
        });
    }

    /**
     * Transfers source tracking IDs, spreadsheet row refs, and basic attributes (place, job, family)
     * from a ghost parent node to a concrete replacement profile.
     *
     * @param {Object} ghost - Ghost parent node
     * @param {Object} concreteReplacement - Target concrete parent node
     *
     * @example
     * const ghost = { _sourceIds: new Set(['s1']), place: 'Ernakulam' };
     * const real = { _sourceId: 's2', place: '' };
     * FamilyTreeBuilder._transferGhostSourcesAndAttributes(ghost, real);
     * // real._sourceIds has 's1' and 's2', real.place === 'Ernakulam'
     *
     * @example
     * const ghost = { job: 'Teacher' };
     * const real = { job: 'Engineer' };
     * FamilyTreeBuilder._transferGhostSourcesAndAttributes(ghost, real);
     * // real.job remains 'Engineer' (not overwritten)
     */
    static _transferGhostSourcesAndAttributes(ghost, concreteReplacement) {
        if (ghost._sourceIds) {
            if (!concreteReplacement._sourceIds) concreteReplacement._sourceIds = new Set([concreteReplacement._sourceId]);
            ghost._sourceIds.forEach(sid => concreteReplacement._sourceIds.add(sid));
        }
        if (ghost._allSourceRefs) {
            if (!concreteReplacement._allSourceRefs) concreteReplacement._allSourceRefs = [];
            ghost._allSourceRefs.forEach(ref => {
                if (!concreteReplacement._allSourceRefs.some(er => er.sheetId === ref.sheetId && er.row === ref.row)) {
                    concreteReplacement._allSourceRefs.push(ref);
                }
            });
        }
        ['place', 'job', 'family'].forEach(attr => {
            if (!concreteReplacement[attr] && ghost[attr]) concreteReplacement[attr] = ghost[attr];
        });
    }

    /**
     * Reassigns children, spouses, sources, and attributes from a redundant ghost parent
     * to a concrete replacement profile, then prunes the ghost entity.
     *
     * @param {Object} ghost - Redundant ghost parent node
     * @param {Object} concreteReplacement - Target concrete profile
     *
     * @example
     * const ghost = { id: 'g1', children: ['c1'], partners: [] };
     * const real = { id: 'r1', children: [], partners: [] };
     * builder.nodeMap = { g1: ghost, r1: real, c1: { id: 'c1', fatherId: 'g1' } };
     * builder._transferGhostParentToConcrete(ghost, real);
     * // ghost removed from builder.nodeMap if children transferred
     *
     * @example
     * const ghost = { id: 'g2', children: [], partners: [] };
     * const real = { id: 'r2', children: [], partners: [] };
     * builder.nodeMap = { g2: ghost, r2: real };
     * builder._transferGhostParentToConcrete(ghost, real);
     * // builder.nodeMap.g2 is deleted
     */
    _transferGhostParentToConcrete(ghost, concreteReplacement) {
        FamilyTreeBuilder._transferGhostChildren(ghost, concreteReplacement, this.nodeMap);
        FamilyTreeBuilder._transferGhostPartners(ghost, concreteReplacement, this.nodeMap);
        FamilyTreeBuilder._transferGhostSourcesAndAttributes(ghost, concreteReplacement);
        if (ghost.children.length === 0) {
            delete this.nodeMap[ghost.id];
        }
    }

    /**
     * Checks if a candidate profile is a compatible replacement for a ghost parent with a specific partner.
     * Enforces mutual spousal claims, non-exclusivity with other spouses, and validity for all ghost children.
     *
     * @param {Object} c - Candidate concrete profile
     * @param {Object} partner - Known partner profile
     * @param {string[]} [ghostChildren=[]] - IDs of ghost's children
     * @param {'mother'|'father'} relationType - Parent relationship type
     * @param {string} normGhostName - Normalized name of the ghost parent
     * @param {Object} nodeMap - Complete tree node map
     * @returns {boolean} True if candidate is a compatible replacement
     *
     * @example
     * FamilyTreeBuilder._isCompatibleGhostReplacementForPartner(c, partner, ['c1'], 'mother', 'mercy', nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isCompatibleGhostReplacementForPartner(c, partner, [], 'father', 'john', nodeMap);
     * // => false
     */
    static _isCompatibleGhostReplacementForPartner(c, partner, ghostChildren, relationType, normGhostName, nodeMap) {
        // Require mutual spouse claim: both candidate and partner must claim each other as spouse.
        // This ensures matching husband/wife names (e.g. Mercy names Jake and Jake names Mercy)
        // and prevents unrelated same-named candidates (e.g. Mini married to Mini Husband)
        // from being hijacked by another person (e.g. Unni claiming a different Mini).
        const claimsPartner = FamilyTreeBuilder._claimsAsSpouse(c, partner) && FamilyTreeBuilder._claimsAsSpouse(partner, c);
        if (!claimsPartner) return false;
        if (FamilyTreeBuilder._isExclusivelyMarriedToOther(c, partner, partner._normName, nodeMap)) return false;
        if (FamilyTreeBuilder._isExclusivelyMarriedToOther(partner, c, c._normName, nodeMap)) return false;
        const validSpouse = FamilyTreeBuilder._isValidSpouseCandidate(c, partner, c.gender === 'M' ? 'husband' : 'wife', nodeMap);
        if (!validSpouse) return false;
        return (ghostChildren || []).every(cid => {
            const ch = nodeMap[cid];
            return !ch || FamilyTreeBuilder._isValidParentCandidate(c, ch, relationType, normGhostName, nodeMap);
        });
    }

    /**
     * Attempts to find a concrete profile replacement for a ghost parent based on mutual partner claims and child validity.
     *
     * @param {object} ghost - The ghost parent profile.
     * @returns {object|null} Concrete replacement node if found, otherwise null.
     *
     * @example
     * const ghost = { name: 'Mercy', gender: 'F', partners: ['p1'], children: [] };
     * builder._findConcreteReplacementByPartner(ghost);
     * // returns matching concrete Mercy node partnered with p1, or null
     *
     * @example
     * const ghost = { name: 'Unknown', partners: [] };
     * builder._findConcreteReplacementByPartner(ghost);
     * // returns null
     */
    _findConcreteReplacementByPartner(ghost) {
        if (!ghost || !ghost.partners || ghost.partners.length === 0) return null;
        const normGhostName = (ghost._normName || ghost.name || '').toLowerCase().trim();
        const relationType = ghost.gender === 'F' ? 'mother' : 'father';
        const candList = this.name2nodes[normGhostName] || [];

        for (const partnerId of ghost.partners) {
            const partner = this.nodeMap[partnerId];
            if (!partner) continue;
            for (const c of candList) {
                if (FamilyTreeBuilder._isCompatibleGhostReplacementForPartner(c, partner, ghost.children, relationType, normGhostName, this.nodeMap)) {
                    return c;
                }
            }
        }
        return null;
    }

    /**
     * Iterates over all ghost nodes in the node map and replaces redundant ghost parents
     * with matching concrete profiles when existing parent links, mutual spousal claims,
     * or declared parent names identify a valid concrete candidate.
     *
     * @param {Object[]} [nodes] - List of domain Person/node objects
     *
     * @example
     * builder.replaceGhostParentsWithConcrete(nodes);
     * // Replaces eligible ghost parents with concrete profiles in nodeMap
     *
     * @example
     * builder.replaceGhostParentsWithConcrete();
     * // Inspects this.nodeMap and transfers ghost parent links to concrete nodes
     */
    replaceGhostParentsWithConcrete(nodes) {
        Object.values(this.nodeMap).filter(p => p.isGhost).forEach(ghost => {
            if (ghost.children && ghost.children.length > 0) {
                let concreteReplacement = this._findChildNonGhostParent(ghost);

                if (!concreteReplacement && ghost.partners.length > 0) {
                    concreteReplacement = this._findConcreteReplacementByPartner(ghost);
                }

                if (!concreteReplacement) {
                    concreteReplacement = this._findConcreteReplacementByChildDeclaredParent(ghost);
                }

                if (concreteReplacement) {
                    this._transferGhostParentToConcrete(ghost, concreteReplacement);
                }
            }
        });
    }

    /**
     * Collects all lowercase normalized names explicitly declared in raw rows across sheets.
     *
     * @param {Array<Object>} [rawRows=[]] - Raw parsed spreadsheet rows
     * @returns {Set<string>} Set of normalized explicit profile names
     *
     * @example
     * const names = FamilyTreeBuilder._collectDeclaredRawNames([{ Name: 'John' }, { Name: 'Mary' }]);
     * names.has('john'); // => true
     *
     * @example
     * const empty = FamilyTreeBuilder._collectDeclaredRawNames([]);
     * empty.size; // => 0
     */
    static _collectDeclaredRawNames(rawRows = []) {
        return new Set(
            (rawRows || [])
                .map(r => {
                    const rKeys = Object.keys(r);
                    return FamilyTreeBuilder._extractColumnValue(rKeys, r, ['name']).toLowerCase().trim();
                })
                .filter(Boolean)
        );
    }

    /**
     * Determines whether a ghost node represents a declared spouse eligible for promotion to concrete profile.
     *
     * @param {Object} p - Person node candidate
     * @param {Object} nodeMap - Map of node IDs to person records
     * @param {Set<string>} rawNames - Set of lowercase normalized names with dedicated rows
     * @returns {boolean} True if eligible for promotion (has concrete partner, not generic kinship, no raw row conflict)
     *
     * @example
     * const eligible = FamilyTreeBuilder._shouldPromoteGhostSpouse(
     *     { id: 'autoghost_1_spouse_1', isGhost: true, name: 'Mini', partners: ['c1'] },
     *     { c1: { isGhost: false } },
     *     new Set()
     * );
     * // => true
     *
     * @example
     * const ineligible = FamilyTreeBuilder._shouldPromoteGhostSpouse(
     *     { id: 'autoghost_1_spouse_1', isGhost: false, name: 'Mini', partners: ['c1'] },
     *     { c1: { isGhost: false } },
     *     new Set()
     * );
     * // => false
     */
    static _shouldPromoteGhostSpouse(p, nodeMap, rawNames) {
        if (!p.isGhost) return false;
        const norm = (p._normName || p.name || '').toLowerCase().trim();
        if (FamilyTreeBuilder._isGenericKinshipName(norm)) return false;
        if (rawNames.has(norm)) return false;

        const hasConcretePartner = (p.partners || []).some(pid => {
            const partner = nodeMap[pid];
            return partner && !partner.isGhost;
        });
        return hasConcretePartner && p.id.startsWith('autoghost_') && p.id.includes('_spouse_');
    }

    /**
     * Promotes declared named spouses (e.g. "Spouse: Mini") who were instantiated
     * as ghost nodes back to concrete profile entities if they are linked to a
     * concrete person in the graph and are not generic placeholder titles.
     *
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.promoteDeclaredSpouses(nodes);
     * // Promotes autoghost spouse nodes partnered with concrete nodes to concrete profiles (isGhost = false)
     *
     * @example
     * const ghostSpouse = { id: 'autoghost_1_spouse_2', isGhost: true, name: 'Mini', partners: ['concreteId'] };
     * builder.promoteDeclaredSpouses([ghostSpouse]);
     * // ghostSpouse.isGhost becomes false if no dedicated raw row exists for 'Mini'
     */
    promoteDeclaredSpouses(nodes) {
        const rawNames = FamilyTreeBuilder._collectDeclaredRawNames(this.rawRows);
        Object.values(this.nodeMap).forEach(p => {
            if (FamilyTreeBuilder._shouldPromoteGhostSpouse(p, this.nodeMap, rawNames)) {
                p.isGhost = false;
            }
        });
    }

    /**
     * Deduplicates redundant ghost children and ghost partners across all nodes.
     * When free-form counts (e.g. "4 daughters") generate ghost profiles that duplicate
     * an explicit row or another ghost, merges attributes/links into the concrete node
     * or single primary ghost, and deletes redundant ghosts from nodeMap.
     *
     * @param {Object[]} nodes - List of domain Person/node objects to clean
     *
     * @example
     * const nodes = [{ children: ['c1', 'c2'], partners: [] }];
     * builder.cleanupRedundantGhosts(nodes);
     * // Deduplicates child ghosts among nodes
     *
     * @example
     * const nodes = [{ children: [], partners: ['p1', 'p2'] }];
     * builder.cleanupRedundantGhosts(nodes);
     * // Deduplicates partner ghosts among nodes
     */
    cleanupRedundantGhosts(nodes) {
        nodes.forEach(n => {
            if (n.children && n.children.length > 1) {
                this._deduplicateNodeChildren(n);
            }
        });

        nodes.forEach(n => {
            if (n.partners && n.partners.length > 1) {
                this._deduplicateNodePartners(n);
            }
        });
    }

    /**
     * Groups children of a node by normalized name and merges redundant ghost children.
     *
     * @param {Object} parentNode - The parent node whose children are checked
     *
     * @example
     * const parent = { children: ['c1', 'c2'] };
     * builder._deduplicateNodeChildren(parent);
     * // Merges matching ghost children into concrete children or primary ghost
     *
     * @example
     * const parent = { children: [] };
     * builder._deduplicateNodeChildren(parent);
     * // No-op when no children present
     */
    _deduplicateNodeChildren(parentNode) {
        const childGroups = this._groupNodesByNormName(parentNode.children);
        Object.values(childGroups).forEach(group => {
            if (group.length > 1) {
                const reals = group.filter(c => !c.isGhost);
                const ghosts = group.filter(c => c.isGhost);

                if (reals.length > 0 && ghosts.length > 0) {
                    const realChild = reals[0];
                    ghosts.forEach(g => this._mergeGhostIntoRealChild(realChild, g, parentNode));
                } else if (ghosts.length > 1) {
                    this._mergeRedundantGhostChildren(ghosts, parentNode);
                }
            }
        });

        // Deduplicate free-form ghost children with unmatched concrete children
        const currentChildren = (parentNode.children || []).map(id => this.nodeMap[id]).filter(Boolean);
        this._deduplicateFreeFormGhosts(parentNode, currentChildren);
    }

    /**
     * Checks whether a child name is a generic numbered placeholder relative to parent names.
     *
     * @param {string} childName - Name of the child
     * @param {Array<string>} [parentNames=[]] - List of candidate parent names
     * @returns {boolean} True if childName matches a pattern like "<Parent> Daughter 1"
     *
     * @example
     * FamilyTreeBuilder._isGenericNumberedChildName('John Son 1', ['John']);
     * // returns true
     *
     * @example
     * FamilyTreeBuilder._isGenericNumberedChildName('Mary', ['John']);
     * // returns false
     */
    static _isGenericNumberedChildName(childName, parentNames = []) {
        if (!childName) return false;
        const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        return parentNames.some(pName => {
            const pat = new RegExp('^' + escapeRegex(pName) + '\\s+(?:daughter|son|child|girl|boy|kid)\\s+\\d+$', 'i');
            return pat.test(childName);
        });
    }

    /**
     * Reads the gender that a free-form ghost's own name states outright.
     *
     * Free-form text like "2 daughters" is expanded into ghosts named
     * "Saju Daughter 1" / "Saju Daughter 2", so the role word in the name is the
     * sheet's literal assertion about that child - unlike a `gender` field, which
     * may have been synthesised elsewhere in the pipeline.
     *
     * @param {Object} ghost - The ghost child being inspected
     * @returns {string} 'F', 'M', or '' when the name carries no role word
     *
     * @example
     * FamilyTreeBuilder._ghostDeclaredGender({ name: 'Saju Daughter 1' });
     * // returns 'F'
     *
     * @example
     * FamilyTreeBuilder._ghostDeclaredGender({ name: 'Saju Child 1', gender: 'F' });
     * // returns '' - "child" states no gender, and the field is not the sheet speaking
     */
    static _ghostDeclaredGender(ghost) {
        const name = (ghost && ghost.name) || '';
        if (/\b(daughter|girl)\b/i.test(name)) return 'F';
        if (/\b(son|boy)\b/i.test(name)) return 'M';
        return '';
    }

    /**
     * Buckets free-form ghosts by gender, putting gendered buckets first.
     *
     * A genderless ghost ("2 children") can absorb any real child, so it has to
     * choose last; otherwise it would consume the one real child whose recorded
     * gender is the only thing that could satisfy a "1 son" ghost.
     *
     * @param {Object[]} ghosts - Free-form ghost children of a single parent
     * @returns {Array<Array>} [gender, ghosts] pairs, gendered buckets first
     *
     * @example
     * FamilyTreeBuilder._groupGhostsByDeclaredGender([{ name: 'A Daughter 1' }, { name: 'A Daughter 2' }]);
     * // returns [['F', [Daughter 1, Daughter 2]]] - a single bucket of two
     *
     * @example
     * FamilyTreeBuilder._groupGhostsByDeclaredGender([{ name: 'A Child 1' }, { name: 'A Son 1' }]);
     * // returns [['M', [Son 1]], ['', [Child 1]]] - the son gets to pick first
     */
    static _groupGhostsByDeclaredGender(ghosts) {
        const groups = new Map();
        for (const g of ghosts) {
            const gender = FamilyTreeBuilder._ghostDeclaredGender(g) || g.gender || '';
            if (!groups.has(gender)) groups.set(gender, []);
            groups.get(gender).push(g);
        }
        return [...groups.entries()].sort(([a], [b]) => (a ? 0 : 1) - (b ? 0 : 1));
    }

    /**
     * Reserves the real children that one gender bucket of ghosts will absorb.
     *
     * Children whose recorded gender matches are reserved first, because they are
     * the only ones this bucket can claim exclusively; children of unknown gender
     * fill the rest. The claim is then returned *oldest first*, so that
     * "Daughter 1" pairs with the eldest daughter rather than with whichever
     * daughter the sheet happened to state a gender for.
     *
     * @param {string} gender - 'F', 'M', or '' for an unrestricted bucket
     * @param {number} count - Number of ghosts in the bucket
     * @param {Object[]} bySeniority - Every candidate real child, oldest first
     * @param {Set<string>} claimed - IDs already reserved by an earlier bucket
     * @returns {Object[]} Up to `count` real children, oldest first
     *
     * @example
     * const reals = [{ id: 'aneesha' }, { id: 'annu', gender: 'F' }];
     * FamilyTreeBuilder._claimRealsForGenderGroup('F', 2, reals, new Set());
     * // returns [aneesha, annu] - seniority order, not gender-match order
     *
     * @example
     * FamilyTreeBuilder._claimRealsForGenderGroup('M', 1, [{ id: 'a', gender: 'F' }], new Set());
     * // returns [] - neither a male nor an unknown-gender child is available
     */
    static _claimRealsForGenderGroup(gender, count, bySeniority, claimed) {
        const free = bySeniority.filter(r => !claimed.has(r.id) && !r._absorbedGhost);
        const preference = gender
            ? [...free.filter(r => r.gender === gender), ...free.filter(r => !r.gender)]
            : free;
        const picked = preference.slice(0, count);
        picked.forEach(r => claimed.add(r.id));
        return picked.sort((a, b) => bySeniority.indexOf(a) - bySeniority.indexOf(b));
    }

    /**
     * Deduplicates generic free-form ghost profiles against real concrete child profiles.
     *
     * @param {Object} parentNode - The parent node containing children
     * @param {Object[]} currentChildren - Resolved child instances
     *
     * @example
     * const parent = { name: 'John', partners: [] };
     * const children = [{ id: 'g1', isGhost: true, _fromFreeForm: true, gender: 'F', name: 'John Daughter 1' }, { id: 'm1', name: 'Mary', gender: 'F' }];
     * builder._deduplicateFreeFormGhosts(parent, children);
     * // Merges g1 into m1, setting m1._absorbedGhost = true
     *
     * @example
     * const parent = { name: 'John', partners: [] };
     * builder._deduplicateFreeFormGhosts(parent, []);
     * // No-op when no children present
     */
    _deduplicateFreeFormGhosts(parentNode, currentChildren) {
        const ghosts = currentChildren.filter(c => c.isGhost && c._fromFreeForm && !c._isAdditional && (!c.partners || c.partners.length === 0));
        if (ghosts.length === 0) return;

        const parentNames = [parentNode.name, ...(parentNode.partners || []).map(pId => this.nodeMap[pId]?.name)].filter(Boolean);
        const reals = currentChildren.filter(c => !c.isGhost && !c._absorbedGhost && !FamilyTreeBuilder._isGenericNumberedChildName(c.name, parentNames));
        if (reals.length === 0) return;

        // Oldest first. The ghosts carry the sheet's birth order ("Daughter 1" is
        // the elder), so the real children must be matched in birth order too -
        // matching them in parent.children order would hand "Daughter 1" (and its
        // inferred birth year) to whichever sibling merely happened to sort first.
        const bySeniority = [...reals].sort((a, b) => FamilyTreeBuilder.compareSiblingNodes(a, b, this.nodeMap));

        // "2 daughters" leaves no doubt: whichever children it names are daughters,
        // so an absorbed child may be given that gender. "2 daughters, 2 sons" does
        // not - which of the four slots a lone real child fills is a guess, and
        // guessing would make Manesh's son John a daughter.
        const buckets = FamilyTreeBuilder._groupGhostsByDeclaredGender(ghosts);
        const unanimous = buckets.length === 1 && !!buckets[0][0];

        const claimed = new Set();
        for (const [gender, group] of buckets) {
            group.sort((a, b) => (FamilyTreeBuilder._parseNumberedSiblingRole(a)?.num || 0)
                - (FamilyTreeBuilder._parseNumberedSiblingRole(b)?.num || 0));
            const targets = FamilyTreeBuilder._claimRealsForGenderGroup(gender, group.length, bySeniority, claimed);
            targets.forEach((real, idx) => this._mergeGhostIntoRealChild(real, group[idx], parentNode, unanimous));
        }
    }

    /**
     * Synchronizes name and nickname when merging a ghost child whose name
     * phonetically matches the real child and carries the parent's prefix.
     *
     * @param {Object} realChild - The concrete target child node
     * @param {Object} ghost - The ghost child being absorbed
     * @param {Object} parentNode - The parent node
     *
     * @example
     * const real = { name: 'Abi', nick: '' };
     * const ghost = { name: 'John Abi' };
     * const parent = { name: 'John' };
     * FamilyTreeBuilder._synchronizeGhostNameAndNick(real, ghost, parent);
     * // real.name updated to 'John Abi', real.nick becomes 'Abi'
     *
     * @example
     * const real = { name: 'Paul', nick: '' };
     * const ghost = { name: 'Peter' };
     * FamilyTreeBuilder._synchronizeGhostNameAndNick(real, ghost, { name: 'John' });
     * // No change because phonetic representations differ
     */
    static _synchronizeGhostNameAndNick(realChild, ghost, parentNode) {
        if (!ghost.name || !realChild.name) return;
        if (FamilyTreeBuilder.foldPhonetic(ghost.name) !== FamilyTreeBuilder.foldPhonetic(realChild.name)) return;
        if (parentNode && parentNode.name && !realChild.name.toLowerCase().startsWith(parentNode.name.toLowerCase()) && ghost.name.toLowerCase().startsWith(parentNode.name.toLowerCase())) {
            if (!realChild.nick) realChild.nick = realChild.name;
            else if (!realChild.nick.toLowerCase().includes(realChild.name.toLowerCase())) realChild.nick += `, ${realChild.name}`;
            realChild.name = ghost.name;
            realChild._normName = ghost.name.toLowerCase().trim();
        }
    }

    /**
     * Replaces references to an absorbed ghost in parent children lists with the real child id.
     *
     * @param {Object} realChild - The concrete target child node
     * @param {Object} ghost - The ghost child being absorbed
     * @param {Object} parentNode - The parent node
     * @param {Object<string, Object>} nodeMap - Active tree node map
     *
     * @example
     * const real = { id: 'r1' }, ghost = { id: 'g1' }, parent = { id: 'p1', children: ['g1'] };
     * FamilyTreeBuilder._replaceGhostInParentChildLists(real, ghost, parent, { p1: parent });
     * // parent.children is now ['r1']
     *
     * @example
     * const real = { id: 'r2' }, ghost = { id: 'g2', momId: 'm1' }, parent = { id: 'p2' };
     * const mom = { id: 'm1', children: ['g2'] };
     * FamilyTreeBuilder._replaceGhostInParentChildLists(real, ghost, parent, { m1: mom });
     * // mom.children is now ['r2']
     */
    static _replaceGhostInParentChildLists(realChild, ghost, parentNode, nodeMap) {
        const parents = [ghost.momId, ghost.fatherId, parentNode.id].filter(Boolean);
        new Set(parents).forEach(pId => {
            const parent = nodeMap[pId];
            if (parent && parent.children) {
                const ghostIdx = parent.children.indexOf(ghost.id);
                if (ghostIdx !== -1) {
                    parent.children = parent.children.filter(id => id !== ghost.id && id !== realChild.id);
                    parent.children.splice(ghostIdx, 0, realChild.id);
                } else if (!parent.children.includes(realChild.id)) {
                    parent.children.push(realChild.id);
                }
            }
        });
    }

    /**
     * Transfers partner and children relationships from a ghost child to the concrete real child node.
     *
     * @param {Object} realChild - The target child node receiving relationships
     * @param {Object} ghost - The redundant ghost child being merged
     * @param {Object} nodeMap - Map of person IDs to person nodes
     *
     * @example
     * FamilyTreeBuilder._transferGhostRelations({ id: 'r1', partners: [], children: [] }, { id: 'g1', partners: ['p1'] }, { p1: { partners: ['g1'] } });
     * // => realChild.partners includes 'p1', p1.partners includes 'r1'
     *
     * @example
     * FamilyTreeBuilder._transferGhostRelations({ id: 'r1', partners: [], children: [] }, { id: 'g1', children: ['c1'] }, { c1: { momId: 'g1' } });
     * // => realChild.children includes 'c1', c1.momId updated to 'r1'
     */
    static _transferGhostRelations(realChild, ghost, nodeMap) {
        (ghost.partners || []).forEach(pId => {
            if (!realChild.partners.includes(pId)) realChild.partners.push(pId);
            const p = nodeMap[pId];
            if (p) p.partners = p.partners.map(id => id === ghost.id ? realChild.id : id);
        });

        (ghost.children || []).forEach(gcId => {
            if (!realChild.children.includes(gcId)) realChild.children.push(gcId);
            const gc = nodeMap[gcId];
            if (gc) {
                if (gc.momId === ghost.id) gc.momId = realChild.id;
                if (gc.fatherId === ghost.id) gc.fatherId = realChild.id;
            }
        });
    }

    /**
     * Merges attributes, partners, children, and parent references from a ghost child into a real child node.
     *
     * @param {Object} realChild - The concrete target child node
     * @param {Object} ghost - The redundant ghost child being absorbed
     * @param {Object} parentNode - The parent containing both children
     * @param {boolean} [mayStateGender=false] - True when the free-form text names
     *     only one gender, so the ghost's role word applies to the match for certain
     *
     * @example
     * const real = { id: 'r1', partners: [], children: [] };
     * const ghost = { id: 'g1', place: 'Kochi', partners: [], children: [] };
     * builder._mergeGhostIntoRealChild(real, ghost, { id: 'p1' });
     * // real.place becomes 'Kochi', real._absorbedGhost becomes true, ghost deleted
     *
     * @example
     * const real = { id: 'r2', partners: [], children: [], yob: 1950 };
     * const ghost = { id: 'g2', yob: 1948, partners: [], children: [] };
     * builder._mergeGhostIntoRealChild(real, ghost, { id: 'p2' });
     * // real.yob remains 1950 (not overwritten)
     */
    _mergeGhostIntoRealChild(realChild, ghost, parentNode, mayStateGender = false) {
        realChild._absorbedGhost = true;
        // A numbered free-form ghost ("Manesh Daughter 2") carries the sheet's
        // statement of this child's birth order. Keep that ordinal on the real
        // child so sibling sorting stays stable after the ghost disappears.
        realChild._siblingOrdinal =
            FamilyTreeBuilder._parseNumberedSiblingRole(ghost.name) || realChild._siblingOrdinal;
        FamilyTreeBuilder._synchronizeGhostNameAndNick(realChild, ghost, parentNode);

        // Gender travels only when the sheet actually said it: either the caller
        // vouched that the free-form text is unambiguous (and the ghost's own name
        // carries the role word), or the target is itself a ghost being filled in
        // from a non-free-form source. A synthesised gender must never be invented
        // onto a real person.
        const genderIsStated = (mayStateGender && !!FamilyTreeBuilder._ghostDeclaredGender(ghost))
            || (realChild.isGhost && !ghost._fromFreeForm);
        ['gender', 'yob', 'place', 'momId', 'fatherId'].forEach(prop => {
            if (prop === 'gender' && !genderIsStated) return;
            if (!realChild[prop] && ghost[prop]) realChild[prop] = ghost[prop];
        });
        if ((!realChild.yob || realChild.yob === 0) && ghost._inferredYob) realChild._inferredYob = ghost._inferredYob;

        FamilyTreeBuilder._transferGhostRelations(realChild, ghost, this.nodeMap);
        FamilyTreeBuilder._replaceGhostInParentChildLists(realChild, ghost, parentNode, this.nodeMap);

        delete this.nodeMap[ghost.id];
    }

    /**
     * Merges duplicate ghost children into the first primary ghost, removing excess ghost nodes.
     *
     * @param {Object[]} ghosts - Array of duplicate ghost nodes
     * @param {Object} parentNode - The parent containing the ghost children
     *
     * @example
     * const g1 = { id: 'g1' }, g2 = { id: 'g2' };
     * const parent = { id: 'p1', children: ['g1', 'g2'] };
     * builder.nodeMap = { g1, g2, p1: parent };
     * builder._mergeRedundantGhostChildren([g1, g2], parent);
     * // parent.children is ['g1'], builder.nodeMap.g2 is deleted
     *
     * @example
     * const g1 = { id: 'g1' };
     * builder._mergeRedundantGhostChildren([g1], { id: 'p1' });
     * // Leaves g1 untouched
     */
    _mergeRedundantGhostChildren(ghosts, parentNode) {
        for (let i = 1; i < ghosts.length; i++) {
            const g = ghosts[i];
            const parents = [g.momId, g.fatherId, parentNode.id].filter(Boolean);
            new Set(parents).forEach(pId => {
                const parent = this.nodeMap[pId];
                if (parent && parent.children) {
                    parent.children = parent.children.filter(id => id !== g.id);
                }
            });
            delete this.nodeMap[g.id];
        }
    }

    /**
     * Groups partners of a node by normalized name and merges redundant ghost partners.
     *
     * @param {Object} n - The node whose partners are checked
     *
     * @example
     * const person = { partners: ['p1', 'p2'] };
     * builder._deduplicateNodePartners(person);
     * // Merges ghost partner into real partner or primary ghost
     *
     * @example
     * const person = { partners: ['p1'] };
     * builder._deduplicateNodePartners(person);
     * // No-op when person has <= 1 partner
     */
    _deduplicateNodePartners(n) {
        const partnerGroups = this._groupNodesByNormName(n.partners);
        Object.values(partnerGroups).forEach(group => {
            if (group.length > 1) {
                const reals = group.filter(p => !p.isGhost);
                const ghosts = group.filter(p => p.isGhost);

                if (reals.length > 0 && ghosts.length > 0) {
                    const targetPartner = reals[0];
                    ghosts.forEach(g => this._reassignGhostPartner(n, g, targetPartner));
                } else if (ghosts.length > 1) {
                    const primary = ghosts[0];
                    for (let i = 1; i < ghosts.length; i++) {
                        this._reassignGhostPartner(n, ghosts[i], primary);
                    }
                }
            }
        });
    }

    /**
     * Reassigns children of a ghost partner to the target partner and removes the ghost.
     *
     * @param {Object} n - The anchor node
     * @param {Object} ghost - The redundant ghost partner
     * @param {Object} targetPartner - The retained concrete or primary ghost partner
     *
     * @example
     * const n = { id: 'n1', partners: ['g1'] };
     * const ghost = { id: 'g1', partners: ['n1'], children: ['c1'] };
     * const real = { id: 'r1', partners: [], children: [] };
     * builder.nodeMap = { g1: ghost, c1: { momId: 'g1' } };
     * builder._reassignGhostPartner(n, ghost, real);
     * // c1.momId updated to 'r1', real.children has 'c1', ghost deleted
     *
     * @example
     * const n = { id: 'n1', partners: ['g2'] };
     * const ghost = { id: 'g2', partners: ['n1'], children: [] };
     * const real = { id: 'r2', partners: [], children: [] };
     * builder.nodeMap = { g2: ghost };
     * builder._reassignGhostPartner(n, ghost, real);
     * // ghost deleted from builder.nodeMap
     */
    _reassignGhostPartner(n, ghost, targetPartner) {
        n.partners = n.partners.filter(id => id !== ghost.id);
        ghost.partners = ghost.partners.filter(id => id !== n.id);

        ghost.children.forEach(cId => {
            const child = this.nodeMap[cId];
            if (child) {
                if (child.momId === ghost.id) child.momId = targetPartner.id;
                if (child.fatherId === ghost.id) child.fatherId = targetPartner.id;
                if (!targetPartner.children.includes(cId)) targetPartner.children.push(cId);
            }
        });
        ghost.children = [];
        delete this.nodeMap[ghost.id];
    }

    /**
     * Groups node IDs by their normalized lowercase name.
     *
     * @param {string[]} nodeIds - Array of node IDs to resolve from nodeMap and group
     * @returns {Object.<string, Object[]>} Map of normalized name to node list
     *
     * @example
     * builder.nodeMap = { p1: { name: 'Mary' }, p2: { name: 'Mary' } };
     * builder._groupNodesByNormName(['p1', 'p2']);
     * // returns { 'mari': [nodeMap.p1, nodeMap.p2] }
     *
     * @example
     * builder._groupNodesByNormName([]);
     * // returns {}
     */
    _groupNodesByNormName(nodeIds) {
        const groups = {};
        (nodeIds || []).forEach(id => {
            const node = this.nodeMap[id];
            if (node) {
                const norm = node._normName || (node.name || '').toLowerCase().trim();
                const key = FamilyTreeBuilder.foldPhonetic(norm);
                if (!groups[key]) groups[key] = [];
                groups[key].push(node);
            }
        });
        return groups;
    }

    /**
     * Filters out duplicate rows while preserving multiple identically named relative
     * references on different spreadsheet rows.
     * 
     * @param {Object[]} rows - Raw CSV row records
     * @returns {Object[]} Deduplicated row records
     * 
     * @example
     * const rows = [{ Name: 'John', Age: '30' }, { Name: 'John', Age: '30' }];
     * builder._filterUniqueRows(rows);
     * // returns [{ Name: 'John', Age: '30' }]
     * 
     * @example
     * const rows = [{ Name: 'Mary Son', _sourceId: 's1', _sheetRow: 2 }, { Name: 'Mary Son', _sourceId: 's1', _sheetRow: 5 }];
     * builder._filterUniqueRows(rows);
     * // returns both rows because relative child entries on distinct rows are preserved
     */
    _filterUniqueRows(rows) {
        const seen = new Set();
        return rows.filter((r, idx) => {
            const rawName = r.Name || r.name || '';
            const isRel = FamilyTreeBuilder._isRelativeName(rawName);
            const sheetRowKey = r._sheetRow !== undefined ? `${r._sheetRow}|` : '';
            const keyStr = isRel || r._sheetRow !== undefined
                ? `${r._sourceId || ''}|${sheetRowKey}${rawName}`
                : [r._sourceId || '', ...Object.keys(r).sort().filter(k => !k.startsWith('_')).map(k => r[k])].join('|');
            if (seen.has(keyStr)) return false;
            seen.add(keyStr);
            return true;
        });
    }

    /**
     * Partitions an array of nodes (pre-sorted by spreadsheet row) into contiguous clusters
     * where each adjacent pair of nodes is separated by at most maxGap rows.
     *
     * @param {Object[]} sortedNodes - Array of node objects sorted by spreadsheet row
     * @param {number} [maxGap=5] - Maximum spreadsheet row gap between consecutive nodes
     * @returns {Array<Object[]>} Array of node clusters
     *
     * @example
     * FamilyTreeBuilder._clusterNodesByRowProximity([{ _sheetRow: 2 }, { _sheetRow: 5 }, { _sheetRow: 20 }], 5);
     * // returns [[{ _sheetRow: 2 }, { _sheetRow: 5 }], [{ _sheetRow: 20 }]]
     *
     * @example
     * FamilyTreeBuilder._clusterNodesByRowProximity([]);
     * // returns []
     */
    static _clusterNodesByRowProximity(sortedNodes, maxGap = 5) {
        if (!sortedNodes || sortedNodes.length === 0) return [];
        const clusters = [];
        let curCluster = [sortedNodes[0]];
        for (let i = 1; i < sortedNodes.length; i++) {
            const prevRow = FamilyTreeBuilder.getNodeSheetRow(curCluster[curCluster.length - 1], 0);
            const thisRow = FamilyTreeBuilder.getNodeSheetRow(sortedNodes[i], 0);
            if (Math.abs(thisRow - prevRow) <= maxGap) {
                curCluster.push(sortedNodes[i]);
            } else {
                clusters.push(curCluster);
                curCluster = [sortedNodes[i]];
            }
        }
        clusters.push(curCluster);
        return clusters;
    }

    /**
     * Numbers multiple relative children in a cluster sequentially (e.g. "Mary Son 1", "Mary Son 2")
     * if the cluster contains more than one person.
     *
     * @param {Object[]} clust - Cluster of relative child nodes
     *
     * @example
     * const clust = [{ name: 'Mary Son' }, { name: 'Mary Son' }];
     * FamilyTreeBuilder._numberRelativeChildCluster(clust);
     * // clust[0].name becomes 'Mary Son 1', clust[1].name becomes 'Mary Son 2'
     *
     * @example
     * const clust = [{ name: 'Mary Son' }];
     * FamilyTreeBuilder._numberRelativeChildCluster(clust);
     * // clust[0].name remains 'Mary Son' (single-item cluster is not numbered)
     */
    static _numberRelativeChildCluster(clust) {
        if (!clust || clust.length <= 1) return;
        clust.forEach((n, idx) => {
            n.name = `${n.name} ${idx + 1}`;
            n._normName = n.name.toLowerCase().trim();
        });
    }

    /**
     * Numbers multiple relative children with identical names on the same sheet (e.g. 3x "Mary Son" -> "Mary Son 1", "Mary Son 2", "Mary Son 3")
     * based on row clustering within 5 spreadsheet rows.
     * 
     * @param {Object[]} normalized - Normalized node objects
     * 
     * @example
     * const nodes = [{ name: 'Mary Son', _sourceId: 's1', _sheetRow: 2 }, { name: 'Mary Son', _sourceId: 's1', _sheetRow: 3 }];
     * builder._disambiguateRelativeChildrenNames(nodes);
     * // nodes[0].name becomes 'Mary Son 1', nodes[1].name becomes 'Mary Son 2'
     * 
     * @example
     * const nodes = [{ name: 'Mary Son 1', _sourceId: 's1', _sheetRow: 2 }];
     * builder._disambiguateRelativeChildrenNames(nodes);
     * // nodes[0].name remains 'Mary Son 1' (already numbered)
     */
    _disambiguateRelativeChildrenNames(normalized) {
        const relGroups = {};
        normalized.forEach(n => {
            if (FamilyTreeBuilder._isRelativeChildName(n.name) && !/\d+$/.test(n.name.trim())) {
                const key = `${n._sourceId || 'default'}|${n._normName}`;
                if (!relGroups[key]) relGroups[key] = [];
                relGroups[key].push(n);
            }
        });
        Object.values(relGroups).forEach(group => {
            if (group.length <= 1) return;
            group.sort((a, b) => FamilyTreeBuilder.getNodeSheetRow(a, 0) - FamilyTreeBuilder.getNodeSheetRow(b, 0));
            const clusters = FamilyTreeBuilder._clusterNodesByRowProximity(group, 5);
            clusters.forEach(clust => FamilyTreeBuilder._numberRelativeChildCluster(clust));
        });
    }

    /**
     * Ingests and normalizes raw spreadsheet row objects into domain person specifications.
     * 
     * @param {Object[]} rows - Raw CSV / Google Sheet row objects
     * @returns {Object[]} Cleaned, normalized node objects sorted by YOB
     * 
     * @example
     * const rows = [{ Name: 'John', Age: '50' }];
     * builder.normalize(rows);
     * // returns normalized array of domain person specifications sorted by YOB
     * 
     * @example
     * const rows = [];
     * builder.normalize(rows);
     * // returns []
     */
    normalize(rows) {
        const uniqueRows = this._filterUniqueRows(rows);
        const currentYear = new Date().getFullYear();
        const normalized = uniqueRows.map((r, i) => this._normalizeSingleRow(r, i, currentYear))
            .filter(r => !r._isUnknown || r.spouse || r.yob || r.death || r.job || r.place || r.mom || r.father || r.sibling);

        this._disambiguateRelativeChildrenNames(normalized);
        this._computeLocalImplicitSpouses(normalized);
        return normalized.sort((a, b) => (a.yob || 9999) - (b.yob || 9999));
    }

    /**
     * Parses primary name and optional nickname, splitting compound 'Name/Nick' entries.
     *
     * @param {string} rawName - Raw name cell value
     * @param {string} rawNick - Explicit nickname cell value
     * @returns {{ name: string, nick: string }}
     *
     * @example
     * builder._parseNameAndNick('Joseph / Kunjappu', '');
     * // returns { name: 'Joseph', nick: 'Kunjappu' }
     *
     * @example
     * builder._parseNameAndNick('Mary', 'Molu');
     * // returns { name: 'Mary', nick: 'Molu' }
     */
    _parseNameAndNick(rawName, rawNick) {
        let name = rawName || '(No Name)', nick = rawNick;
        if (rawName && rawName.includes('/')) {
            const parts = rawName.split('/');
            name = parts[0].trim();
            if (!nick) nick = parts.slice(1).join('/').trim();
        }
        return { name, nick };
    }

    /**
     * Normalizes a raw gender string to 'M', 'F', or an empty string.
     *
     * @param {?string} raw - Raw gender input string
     * @returns {string} Normalized gender 'M', 'F', or ''
     *
     * @example
     * FamilyTreeBuilder._normalizeRawGender('Male');
     * // => 'M'
     *
     * @example
     * FamilyTreeBuilder._normalizeRawGender('female');
     * // => 'F'
     */
    static _normalizeRawGender(raw) {
        if (!raw) return '';
        const lower = raw.toLowerCase();
        if (lower.startsWith('m')) return 'M';
        if (lower.startsWith('f')) return 'F';
        return '';
    }

    /**
     * Resolves religious prefix and returns parsed vocation attributes, or null if no match.
     *
     * @param {string} normName - Normalized lowercase name
     * @param {string} normNick - Normalized lowercase nickname
     * @param {string} gender - Initial resolved gender
     * @returns {Object|null} Vocation attributes or null
     *
     * @example
     * FamilyTreeBuilder._resolveReligiousPrefixVocation('fr. john', '', 'M');
     * // returns { gender: 'M', isNun: false, isPriest: true, isCelibate: true, job: '' }
     *
     * @example
     * FamilyTreeBuilder._resolveReligiousPrefixVocation('alice', '', '');
     * // returns null
     */
    static _resolveReligiousPrefixVocation(normName, normNick, gender) {
        const prefix = (typeof Person !== 'undefined' && Person._matchReligiousPrefix)
            ? Person._matchReligiousPrefix(normName, normNick)
            : null;
        if (!prefix) return null;
        return {
            gender: gender || prefix.gender || '',
            isNun: prefix.vocation === 'Nun',
            isPriest: prefix.vocation === 'Priest',
            isCelibate: true,
            job: ''
        };
    }

    /**
     * Resolves religious vocation and gender from name, nickname, and explicit gender.
     *
     * @param {string} name - Primary name
     * @param {string} nick - Nickname
     * @param {string} rawGender - Explicit gender value from sheet
     * @returns {{ gender: string, isNun: boolean, isPriest: boolean, isCelibate: boolean, job: string }}
     *
     * @example
     * builder._resolveReligiousVocationAndGender('Sr. Mary', '', '');
     * // returns { gender: 'F', isNun: true, isPriest: false, isCelibate: true, job: 'Nun' }
     *
     * @example
     * builder._resolveReligiousVocationAndGender('Fr. Joseph', '', '');
     * // returns { gender: 'M', isNun: false, isPriest: true, isCelibate: true, job: 'Priest' }
     */
    _resolveReligiousVocationAndGender(name, nick, rawGender) {
        let gender = FamilyTreeBuilder._normalizeRawGender(rawGender);
        const normNameCheck = name.toLowerCase().trim();
        const normNickCheck = (nick || '').toLowerCase().trim();
        const titleMatch = FamilyTreeBuilder.matchTitleOntology(normNameCheck, normNickCheck);

        if (titleMatch) {
            return {
                gender: gender || titleMatch.gender || '',
                isNun: Boolean(titleMatch.isNun),
                isPriest: Boolean(titleMatch.isPriest),
                isCelibate: Boolean(titleMatch.isCelibate),
                job: titleMatch.career || ''
            };
        }

        const prefixResult = FamilyTreeBuilder._resolveReligiousPrefixVocation(normNameCheck, normNickCheck, gender);
        if (prefixResult) return prefixResult;

        if (!gender && typeof Person !== 'undefined' && Person._hasMaleNameSuffix(normNameCheck)) {
            gender = 'M';
        }
        return { gender: gender || '', isNun: false, isPriest: false, isCelibate: false, job: '' };
    }

    /**
     * Resolves birth and death years from row columns.
     * 
     * @param {Function} getCol - Column extractor
     * @param {number} currentYear - Reference current year
     * @returns {{ yob: number|null, death: number|null, hasExplicitYob: boolean }}
     * 
     * @example
     * const getCol = (keys) => keys.includes('yob') ? '1980' : '';
     * builder._resolveRowDates(getCol, 2026);
     * // returns { yob: 1980, death: null, hasExplicitYob: true }
     * 
     * @example
     * const getCol = (keys) => keys.includes('age') ? '46' : '';
     * builder._resolveRowDates(getCol, 2026);
     * // returns { yob: 1980, death: null, hasExplicitYob: false }
     */
    _resolveRowDates(getCol, currentYear) {
        const rawYobVal = getCol(['year of birth', 'yob', 'birth year']);
        const { yob, death } = FamilyTreeBuilder._deduceYearsFromAge(
            getCol(['age', 'current age', 'approximate age', 'present age']),
            getCol(['years after death', 'years since death', 'years deceased', 'years dead', 'died years ago', 'death years ago']),
            rawYobVal,
            getCol(['year of death', 'death year', 'death']),
            currentYear
        );
        const hasExplicitYob = !isNaN(parseInt(rawYobVal, 10)) && parseInt(rawYobVal, 10) > 0;
        return { yob, death, hasExplicitYob };
    }

    /**
     * Resolves sheet ID, row number, and sheetRows tracking map for a normalized row.
     * 
     * @param {Object} r - Raw row record
     * @param {number} i - 0-based row index
     * @returns {{ sheetId: string, rowNum: number, sheetRows: Object }}
     * 
     * @example
     * builder._resolveSheetRowTracking({ _sourceId: 's1', _sheetRow: 5 }, 0);
     * // returns { sheetId: 's1', rowNum: 5, sheetRows: { s1: 5 } }
     * 
     * @example
     * builder._resolveSheetRowTracking({}, 3);
     * // returns { sheetId: 'default', rowNum: 5, sheetRows: { default: 5 } }
     */
    _resolveSheetRowTracking(r, i) {
        const sheetId = r._sourceId || 'default';
        const rowNum = r._sheetRow || i + 2;
        const sheetRows = r._sheetRows
            ? (typeof r._sheetRows === 'string' ? JSON.parse(r._sheetRows) : { ...r._sheetRows })
            : { [sheetId]: rowNum };
        return { sheetId, rowNum, sheetRows };
    }

    /**
     * Constructs a normalized person record with initial graph tracking fields.
     *
     * @param {Object} p - Extracted person attributes and tracking metadata
     * @returns {Object} Complete normalized record
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedRowRecord({
     *     rawId: 0, sheetId: 's1', rowNum: 2, sheetRows: { s1: 2 },
     *     id: 'p1', name: 'John', nick: '', gender: 'M', hasExplicitName: true,
     *     sibling: '', yob: 1980, hasExplicitYob: true,
     *     mom: 'Mary', father: 'Joseph', family: 'Smith',
     *     spouse: '', spouseType: '', death: null,
     *     job: '', isNun: false, isPriest: false, isCelibate: false,
     *     place: 'Kochi', freeForm: ''
     * });
     * // returns normalized person object with initialized tracking fields
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedRowRecord({
     *     rawId: 1, sheetId: 's1', rowNum: 3, sheetRows: { s1: 3 },
     *     id: 'p2', name: '', nick: '', gender: '', hasExplicitName: false,
     *     sibling: '', yob: null, hasExplicitYob: false,
     *     mom: '', father: '', family: '',
     *     spouse: '', spouseType: '', death: null,
     *     job: '', isNun: false, isPriest: false, isCelibate: false,
     *     place: '', freeForm: ''
     * });
     * // returns normalized person object with _isUnknown set to true
     */
    /**
     * Builds provenance tracking and parent sheet source metadata for a normalized row.
     *
     * @param {Object} p - Input parsed row data
     * @returns {Object} Provenance and source metadata fields
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedSourceMetadata({ sheetId: 's1', rawId: 1, sheetRows: {}, rowNum: 2, mom: 'Mary', father: 'John' });
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedSourceMetadata({ sheetId: 's2', rawId: 2, sheetRows: {}, rowNum: 5, mom: '', father: '' });
     */
    static _buildNormalizedSourceMetadata(p) {
        return {
            _rawId: p.rawId,
            _sourceId: p.sheetId,
            _sourceIds: new Set([p.sheetId]),
            _sheetRows: p.sheetRows,
            _allSourceRefs: [{ sheetId: p.sheetId, row: p.rowNum }],
            _momSourceSheet: p.mom ? p.sheetId : null,
            _momSourceSheets: new Set(p.mom ? [p.sheetId] : []),
            _fatherSourceSheet: p.father ? p.sheetId : null,
            _fatherSourceSheets: new Set(p.father ? [p.sheetId] : [])
        };
    }

    /**
     * Builds vocation and religious celibacy flags for a normalized row record.
     *
     * @param {Object} p - Parsed row fields
     * @returns {{ job: string, isNun: boolean|undefined, isPriest: boolean|undefined, isCelibate: boolean|undefined, place: string, freeForm: string }} Vocation attributes
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedVocationMetadata({ job: 'Teacher', isNun: false, isPriest: false, isCelibate: false, place: 'Kochi', freeForm: '' });
     * // => { job: 'Teacher', isNun: undefined, isPriest: undefined, isCelibate: undefined, place: 'Kochi', freeForm: '' }
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedVocationMetadata({ job: 'Priest', isNun: false, isPriest: true, isCelibate: true, place: 'Rome', freeForm: 'Father' });
     * // => { job: 'Priest', isNun: undefined, isPriest: true, isCelibate: true, place: 'Rome', freeForm: 'Father' }
     */
    static _buildNormalizedVocationMetadata(p) {
        return {
            job: p.job,
            isNun: p.isNun || undefined,
            isPriest: p.isPriest || undefined,
            isCelibate: p.isCelibate || undefined,
            place: p.place,
            freeForm: p.freeForm
        };
    }

    /**
     * Instantiates a fully populated normalized row record object from normalized person attributes.
     *
     * @param {Object} p - Parsed person attributes
     * @returns {Object} Normalized person record with initialized tracking and relationship fields
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedRowRecord({
     *     rawId: 0, sheetId: 's1', rowNum: 2, sheetRows: { s1: 2 },
     *     id: 'p1', name: 'John', nick: 'Johnny', gender: 'M', hasExplicitName: true,
     *     sibling: '', yob: 1950, hasExplicitYob: true,
     *     mom: 'Mary', father: 'Joseph', family: 'Smith',
     *     spouse: 'Anna', spouseType: 'wife', death: 2020,
     *     job: 'Doctor', isNun: false, isPriest: false, isCelibate: false,
     *     place: 'Kochi', freeForm: ''
     * });
     * // returns normalized person object with initialized tracking fields
     *
     * @example
     * FamilyTreeBuilder._buildNormalizedRowRecord({
     *     rawId: 1, sheetId: 's1', rowNum: 3, sheetRows: { s1: 3 },
     *     id: 'p2', name: '', nick: '', gender: '', hasExplicitName: false,
     *     sibling: '', yob: null, hasExplicitYob: false,
     *     mom: '', father: '', family: '',
     *     spouse: '', spouseType: '', death: null,
     *     job: '', isNun: false, isPriest: false, isCelibate: false,
     *     place: '', freeForm: ''
     * });
     * // returns normalized person object with _isUnknown set to true
     */
    static _buildNormalizedRowRecord(p) {
        return {
            ...this._buildNormalizedSourceMetadata(p),
            ...this._buildNormalizedVocationMetadata(p),
            id: p.id,
            name: p.name,
            _normName: p.name.toLowerCase().trim(),
            _isUnknown: !p.hasExplicitName,
            gender: p.gender,
            nick: p.nick,
            sibling: p.sibling,
            yob: p.yob,
            _hasExplicitYob: p.hasExplicitYob,
            mom: p.mom,
            father: p.father,
            family: p.family,
            _declaredFamily: p.family || undefined,
            spouse: p.spouse,
            spouseType: p.spouseType,
            death: p.death,
            partners: [], children: [], ambiguities: []
        };
    }

    /**
     * Assembles vocation, status, location, and descriptive attributes for a raw row payload.
     *
     * @param {Object} p - Person row attributes and column resolver
     * @returns {{ job: string, isNun: boolean, isPriest: boolean, isCelibate: boolean, place: string, freeForm: string }} Vocation and descriptive attributes
     *
     * @example
     * const getCol = () => '';
     * FamilyTreeBuilder._assembleRowVocationPayload({ getCol, isNun: true, isPriest: false, isCelibate: true, place: 'Kochi' });
     * // => { job: 'Nun', isNun: true, isPriest: false, isCelibate: true, place: 'Kochi', freeForm: '' }
     *
     * @example
     * const getCol = (k) => k.includes('job') ? 'Engineer' : '';
     * FamilyTreeBuilder._assembleRowVocationPayload({ getCol, isNun: false, isPriest: false, isCelibate: false, place: 'Bangalore' });
     * // => { job: 'Engineer', isNun: false, isPriest: false, isCelibate: false, place: 'Bangalore', freeForm: '' }
     */
    static _assembleRowVocationPayload(p) {
        const getCol = p.getCol;
        return {
            job: getCol(['job', 'career']) || p.titleJob || (p.isNun ? 'Nun' : p.isPriest ? 'Priest' : ''),
            isNun: p.isNun,
            isPriest: p.isPriest,
            isCelibate: p.isCelibate,
            place: p.place,
            freeForm: getCol(['free form', 'freeform', 'free_form', 'notes', 'comments', 'description', 'details', 'extra'])
        };
    }

    /**
     * Assembles the full field attributes for a normalized person row record.
     *
     * @param {Object} p - Parsed identity, tracking, and date attributes
     * @returns {Object} Complete attributes ready for record construction
     *
     * @example
     * const getCol = () => '';
     * FamilyTreeBuilder._assembleRowRecordPayload({ getCol, rawId: 0, sheetId: 's1', rowNum: 2, sheetRows: {}, name: 'John' });
     * // returns assembled payload record with default empty strings for missing fields
     *
     * @example
     * const getCol = (k) => k.includes('mother') ? 'Mary' : '';
     * FamilyTreeBuilder._assembleRowRecordPayload({ getCol, rawId: 1, sheetId: 's1', rowNum: 3, sheetRows: {}, name: 'Baby' });
     * // returns assembled payload record with mom: 'Mary'
     */
    static _assembleRowRecordPayload(p) {
        const getCol = p.getCol;
        return {
            rawId: p.rawId,
            sheetId: p.sheetId,
            rowNum: p.rowNum,
            sheetRows: p.sheetRows,
            id: getCol(['id', 'uuid', 'key']),
            name: p.name,
            hasExplicitName: Boolean(p.rawName),
            gender: p.gender,
            nick: p.nick,
            sibling: getCol(['sibling', 'brother', 'sister', 'sib']),
            yob: p.yob,
            hasExplicitYob: p.hasExplicitYob,
            mom: getCol(['mother', 'mom']),
            father: getCol(['father', 'dad']),
            family: getCol(['family name', 'family']),
            spouse: p.spouse,
            spouseType: p.spouseType,
            death: p.death,
            ...this._assembleRowVocationPayload(p)
        };
    }

    /**
     * Normalizes a single spreadsheet raw row object into a structured person specification.
     *
     * @param {Object} r - Raw row object
     * @param {number} i - Row index
     * @param {number} currentYear - Reference current year
     * @returns {Object} Normalized person record
     *
     * @example
     * builder._normalizeSingleRow({ Name: 'Thomas', Age: '30' }, 0, 2026);
     * // returns normalized Person specification for Thomas
     *
     * @example
     * builder._normalizeSingleRow({ Name: 'Sr. Mary', Place: 'Kochi' }, 1, 2026);
     * // returns normalized Person specification for Sr. Mary with isNun=true, gender='F'
     */
    _normalizeSingleRow(r, i, currentYear) {
        const rKeys = Object.keys(r);
        const getCol = (possible) => FamilyTreeBuilder._extractColumnValue(rKeys, r, possible);

        const { spouse, spouseType } = this._extractSpouseField(r, rKeys);
        const rawName = getCol(['name']);
        const { name, nick } = this._parseNameAndNick(rawName, getCol(['nick']));
        const { gender, isNun, isPriest, isCelibate, job: titleJob } = this._resolveReligiousVocationAndGender(name, nick, getCol(['gender', 'sex']));
        const { yob, death, hasExplicitYob } = this._resolveRowDates(getCol, currentYear);
        const { sheetId, rowNum, sheetRows } = this._resolveSheetRowTracking(r, i);
        const rawPlace = getCol(['location', 'place']);
        const place = FamilyTreeBuilder.isInvalidLocation(rawPlace) ? '' : rawPlace;

        const payload = FamilyTreeBuilder._assembleRowRecordPayload({
            getCol, rawId: i, sheetId, rowNum, sheetRows,
            rawName, name, nick, gender, isNun, isPriest, isCelibate, titleJob,
            yob, death, hasExplicitYob, spouse, spouseType, place
        });
        return FamilyTreeBuilder._buildNormalizedRowRecord(payload);
    }

    /**
     * Finds the column key representing a spouse or partner in a row record.
     *
     * @param {string[]} rKeys - Object keys of a row record
     * @returns {?string} Found spouse column key or undefined
     *
     * @example
     * FamilyTreeBuilder._findSpouseColumnKey(['Name', 'Spouse', 'YOB']);
     * // => 'Spouse'
     *
     * @example
     * FamilyTreeBuilder._findSpouseColumnKey(['Name', 'Husband Name', 'YOB']);
     * // => 'Husband Name'
     */
    static _findSpouseColumnKey(rKeys) {
        const spouseTokens = ['spouse', 'partner', 'husband', 'wife', 'hus'];
        const isEligible = k => {
            if (k.startsWith('_')) return false;
            const norm = k.toLowerCase().trim();
            return !norm.includes('location') && !norm.includes('place');
        };
        const primaryMatch = rKeys.find(k => {
            if (!isEligible(k)) return false;
            const primary = k.toLowerCase().trim().split(/[\r\n]+/)[0].trim();
            return spouseTokens.some(p => primary === p || primary.startsWith(p + ' ') || primary.endsWith(' ' + p));
        });
        if (primaryMatch) return primaryMatch;
        return rKeys.find(k => isEligible(k) && spouseTokens.some(p => k.toLowerCase().includes(p)));
    }

    /**
     * Deduces spouse type ('husband', 'wife', or 'spouse') from the spouse column header key.
     *
     * @param {?string} key - Column key name
     * @returns {string} 'husband', 'wife', or 'spouse'
     *
     * @example
     * FamilyTreeBuilder._deduceSpouseTypeFromKey('Husband');
     * // => 'husband'
     *
     * @example
     * FamilyTreeBuilder._deduceSpouseTypeFromKey('Wife Name');
     * // => 'wife'
     */
    static _deduceSpouseTypeFromKey(key) {
        if (!key) return 'spouse';
        const norm = key.toLowerCase();
        const primary = norm.split(/[\r\n]+/)[0].trim();
        if (primary.includes('husband') || primary.includes('hus') || norm.includes('husband')) {
            return 'husband';
        }
        if (primary.includes('wife') || norm.includes('wife')) {
            return 'wife';
        }
        return 'spouse';
    }

    /**
     * Extracts spouse value and spouse type ('spouse', 'husband', 'wife') from row columns.
     *
     * @param {Object} r - Raw row record
     * @param {string[]} rKeys - Object keys of row record
     * @returns {{ spouse: string, spouseType: string }}
     *
     * @example
     * builder._extractSpouseField({ Spouse: 'Mary' }, ['Spouse']);
     * // returns { spouse: 'Mary', spouseType: 'spouse' }
     *
     * @example
     * builder._extractSpouseField({ Husband: 'Joseph' }, ['Husband']);
     * // returns { spouse: 'Joseph', spouseType: 'husband' }
     */
    _extractSpouseField(r, rKeys) {
        const spouseKey = FamilyTreeBuilder._findSpouseColumnKey(rKeys);
        const hasSpouseValue = spouseKey && r[spouseKey] ? r[spouseKey].toString().trim() : '';
        const spouseType = hasSpouseValue ? FamilyTreeBuilder._deduceSpouseTypeFromKey(spouseKey) : 'spouse';
        return { spouse: hasSpouseValue || '', spouseType };
    }

    /**
     * Finds the closest candidate on the same sheet matching a claimant's declared spouse name,
     * enforcing biological spousal age difference constraints.
     *
     * @param {Object} claimant - Person declaring a spouse
     * @param {Object[]} sheetRows - All rows on the claimant's spreadsheet
     * @returns {{ bestTarget: Object|null, bestDist: number }}
     *
     * @example
     * const claimant = { spouse: 'Mary', yob: 1940, _rawId: 10, _sheetRows: { s1: 10 } };
     * const candidates = [{ _normName: 'mary', yob: 1942, _rawId: 12, _sheetRows: { s1: 12 } }];
     * builder._findBestSpouseTarget(claimant, candidates);
     * // returns { bestTarget: candidates[0], bestDist: 2 }
     *
     * @example
     * const claimant = { spouse: 'Alice', yob: 1940, _rawId: 10 };
     * builder._findBestSpouseTarget(claimant, []);
     * // returns { bestTarget: null, bestDist: Infinity }
     */
    _findBestSpouseTarget(claimant, sheetRows) {
        const targetName = claimant.spouse.toLowerCase().trim();
        const claimantRow = claimant._sheetRows ? Object.values(claimant._sheetRows)[0] : claimant._rawId;
        let bestTarget = null, bestDist = Infinity;

        sheetRows.forEach(target => {
            if (target === claimant) return;
            const matches = target._normName === targetName || target._normName.startsWith(targetName + ' ') || targetName.includes(target._normName);
            if (matches && claimant.yob && target.yob) {
                const gap = Math.abs(claimant.yob - target.yob);
                if (gap > FamilyTreeBuilder.HEURISTIC_PRIORS.MAX_FIRST_WIFE_AGE_DIFF) return;
                if (claimant.gender === 'F' && target.gender === 'M' && claimant.yob < target.yob - 5) return;
            }
            if (matches) {
                const targetRow = target._sheetRows ? Object.values(target._sheetRows)[0] : target._rawId;
                const dist = Math.abs(claimantRow - targetRow);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestTarget = target;
                }
            }
        });

        return { bestTarget, bestDist };
    }

    /**
     * Checks whether the target candidate is already claimed as the spouse of one of the claimant's children.
     * Prevents parent-child cross-generation spousal hijacking.
     *
     * @param {Object} target - Matched spouse candidate
     * @param {Object} claimant - Potential spouse claimant
     * @param {Object[]} sheetRows - All rows on the sheet
     * @returns {boolean} True if target is the spouse of a child of claimant
     *
     * @example
     * const claimant = { name: 'Joseph', _normName: 'joseph' };
     * const target = { name: 'Anna', _normName: 'anna', spouse: 'Antony' };
     * const sheetRows = [{ name: 'Antony', father: 'Joseph', spouse: 'Anna' }];
     * builder._isTargetSpouseOfClaimantChild(target, claimant, sheetRows);
     * // returns true
     *
     * @example
     * const claimant = { name: 'Joseph', _normName: 'joseph' };
     * const target = { name: 'Mary', _normName: 'mary', spouse: '' };
     * builder._isTargetSpouseOfClaimantChild(target, claimant, []);
     * // returns false
     */
    _isTargetSpouseOfClaimantChild(target, claimant, sheetRows) {
        return sheetRows.some(other => {
            const oMom = (other.mom || '').toLowerCase().trim();
            const oDad = (other.father || '').toLowerCase().trim();
            const cNorm = (claimant._normName || claimant.name || '').toLowerCase().trim();
            if (oMom !== cNorm && oDad !== cNorm) return false;
            const otherClaimsTarget = other.spouse && !FamilyTreeBuilder._hasNameConflict(other.spouse, target._normName || target.name);
            const targetClaimsOther = target.spouse && !FamilyTreeBuilder._hasNameConflict(target.spouse, other._normName || other.name);
            return otherClaimsTarget || targetClaimsOther;
        });
    }

    /**
     * Registers mutual implicit spouse references between co-parents declared on a child's row.
     *
     * @param {Object} child - Child node declaring mother and father
     * @param {Object[]} sheetRows - Sibling and parent rows on the same sheet
     *
     * @example
     * const child = { mom: 'Mary', father: 'Joseph', spouse: '' };
     * const sheetRows = [{ _normName: 'mary', _localImplicitSpouses: [] }, { _normName: 'joseph', _localImplicitSpouses: [] }];
     * builder._recordCoParentImplicitSpouses(child, sheetRows);
     * // sheetRows[0]._localImplicitSpouses has 'Joseph', sheetRows[1]._localImplicitSpouses has 'Mary'
     *
     * @example
     * const child = { mom: 'Mary', father: 'Joseph', spouse: 'Joseph' };
     * const sheetRows = [{ _normName: 'joseph', _localImplicitSpouses: [] }];
     * builder._recordCoParentImplicitSpouses(child, sheetRows);
     * // No implicit spouse added because child claims Joseph as spouse
     */
    _recordCoParentImplicitSpouses(child, sheetRows) {
        const normMom = child.mom.toLowerCase().trim();
        const normDad = child.father.toLowerCase().trim();
        sheetRows.forEach(target => {
            const childSpouse = (child.spouse || '').toLowerCase().trim();
            // If child explicitly claims target as spouse, target is child's spouse, NOT child's father/parent
            const isChildSpouseOfTarget = (childSpouse === target._normName || childSpouse.startsWith(target._normName + ' '));
            if (target._normName === normDad && !isChildSpouseOfTarget && (!target.spouse || !FamilyTreeBuilder._hasNameConflict(target.spouse, child.mom)) && !target._localImplicitSpouses.includes(child.mom)) {
                target._localImplicitSpouses.push(child.mom);
            }
            if (target._normName === normMom && (!target.spouse || !FamilyTreeBuilder._hasNameConflict(target.spouse, child.father)) && !target._localImplicitSpouses.includes(child.father)) {
                target._localImplicitSpouses.push(child.father);
            }
        });
    }

    /**
     * Finds and registers the best neighbor target for a claimant's declared spouse on the sheet.
     *
     * @param {Object} claimant - Row declaring a spouse
     * @param {Array<Object>} sheetRows - Rows belonging to the same spreadsheet
     *
     * @example
     * builder._recordClaimantImplicitSpouse(wifeRow, sheetRows);
     *
     * @example
     * builder._recordClaimantImplicitSpouse({ spouse: null }, sheetRows);
     */
    _recordClaimantImplicitSpouse(claimant, sheetRows) {
        if (!claimant.spouse) return;
        const { bestTarget, bestDist } = this._findBestSpouseTarget(claimant, sheetRows);

        if (bestTarget && bestDist <= FamilyTreeBuilder.GENERATIONAL_GAPS.MAX_ROW_NEIGHBOR_DISTANCE) {
            if (!this._isTargetSpouseOfClaimantChild(bestTarget, claimant, sheetRows) && 
                !bestTarget._localImplicitSpouses.includes(claimant.name)) {
                bestTarget._localImplicitSpouses.push(claimant.name);
            }
        }
    }

    /**
     * Computes implicit spouse relationships across rows belonging to a single spreadsheet.
     *
     * @param {Array<Object>} sheetRows - Rows belonging to the same spreadsheet
     *
     * @example
     * builder._computeSheetImplicitSpouses(sheetRows);
     *
     * @example
     * builder._computeSheetImplicitSpouses([]);
     */
    _computeSheetImplicitSpouses(sheetRows) {
        sheetRows.forEach(claimant => {
            this._recordClaimantImplicitSpouse(claimant, sheetRows);
        });
        sheetRows.forEach(child => {
            if (child.mom && child.father) {
                this._recordCoParentImplicitSpouses(child, sheetRows);
            }
        });
    }

    /**
     * Computes local implicit spousal relationships within each sheet by matching
     * declared spouses within neighbor distance and pairing co-parents from child rows.
     *
     * @param {Object[]} normalized - Normalized specification rows
     *
     * @example
     * const rows = [
     *   { name: 'Joseph', spouse: 'Mary', _sourceId: 's1', _sheetRows: { s1: 1 } },
     *   { name: 'Mary', spouse: '', _sourceId: 's1', _normName: 'mary', _sheetRows: { s1: 2 } }
     * ];
     * builder._computeLocalImplicitSpouses(rows);
     * // rows[1]._localImplicitSpouses includes 'Joseph'
     *
     * @example
     * const rows = [];
     * builder._computeLocalImplicitSpouses(rows);
     * // No-op for empty array
     */
    _computeLocalImplicitSpouses(normalized) {
        normalized.forEach(r => { r._localImplicitSpouses = []; });

        const bySheet = {};
        normalized.forEach(r => {
            const sid = r._sourceId || 'default';
            if (!bySheet[sid]) bySheet[sid] = [];
            bySheet[sid].push(r);
        });

        Object.values(bySheet).forEach(sheetRows => {
            this._computeSheetImplicitSpouses(sheetRows);
        });
    }

    /**
     * Clusters and deduplicates namesake profiles across spreadsheet rows based on corroborative relational evidence.
     * 
     * @param {Object[]} normalized - Normalized specification nodes
     * @returns {Object[]} Deduplicated domain entities
     * 
     * @example
     * const nodes = [
     *   { name: 'John', _normName: 'john', yob: 1950, mom: 'Mary' },
     *   { name: 'John', _normName: 'john', yob: 1950, mom: 'Mary', spouse: 'Ann' }
     * ];
     * builder.deduplicate(nodes);
     * // returns single merged John node with spouse: 'Ann' and _mergeCount: 2
     * 
     * @example
     * const nodes = [];
     * builder.deduplicate(nodes);
     * // returns []
     */
    deduplicate(normalized) {
        const deduplicated = [];
        const byName = {};
        normalized.forEach(n => {
            const name = n._isUnknown ? `unknown_${n._rawId}` : n._normName;
            if (!byName[name]) byName[name] = [];
            byName[name].push(n);
        });

        Object.values(byName).forEach(group => {
            const mergedGroup = [];
            group.forEach(n => {
                const match = mergedGroup.find(m => this._canMergeProfiles(m, n, normalized));
                if (match) {
                    this._mergeProfileFields(match, n);
                } else {
                    n._mergeCount = 1;
                    mergedGroup.push(n);
                }
            });
            deduplicated.push(...mergedGroup);
        });

        return deduplicated;
    }

    /**
     * Evaluates whether two profiles have conflicting birth years or violate sibling age bounds.
     *
     * @param {Object} m - First profile
     * @param {Object} n - Second profile
     * @param {Object[]} allNodes - All candidate profiles for sibling context
     * @returns {boolean} True if birth years or sibling bounds conflict
     *
     * @example
     * builder._hasBirthYearOrSiblingConflict({ yob: 1940 }, { yob: 1945 }, []);
     * // returns true (diff of 5 exceeds consecutive sibling gap limit of 2)
     *
     * @example
     * builder._hasBirthYearOrSiblingConflict({ yob: 1940 }, { yob: 1941 }, []);
     * // returns false (age difference within consecutive sibling limit)
     */
    _hasBirthYearOrSiblingConflict(m, n, allNodes) {
        if (m.yob && n.yob && Math.abs(m.yob - n.yob) > FamilyTreeBuilder.GENERATIONAL_GAPS.CONSECUTIVE_SIBLING) {
            return true;
        }
        const boundsM = FamilyTreeBuilder._getSiblingAgeBounds(m, allNodes);
        const boundsN = FamilyTreeBuilder._getSiblingAgeBounds(n, allNodes);
        if (n.yob && (n.yob > boundsM.maxBound || n.yob < boundsM.minBound)) return true;
        if (m.yob && (m.yob > boundsN.maxBound || m.yob < boundsN.minBound)) return true;
        if (boundsM.maxBound < boundsN.minBound || boundsN.maxBound < boundsM.minBound) return true;
        return false;
    }

    /**
     * Checks whether two profiles have conflicting explicit or implicit spouses.
     * Also guards against cross-sheet namesake hijacking where local implicit spouses
     * on one sheet conflict with the explicit spouse on the other sheet.
     *
     * @param {Object} m - First profile
     * @param {Object} n - Second profile
     * @returns {boolean} True if spousal names conflict
     *
     * @example
     * builder._hasSpousalConflict({ spouse: 'Mary' }, { spouse: 'Ammini' });
     * // returns true
     *
     * @example
     * builder._hasSpousalConflict({ spouse: 'Mary' }, { spouse: 'Mary' });
     * // returns false
     */
    _hasSpousalConflict(m, n) {
        if (m.spouse && n.spouse && FamilyTreeBuilder._hasNameConflict(m.spouse, n.spouse)) {
            return true;
        }
        const mSpouses = [m.spouse || '', (m._localImplicitSpouses || []).join(', ')].filter(Boolean).join(', ');
        const nSpouses = [n.spouse || '', (n._localImplicitSpouses || []).join(', ')].filter(Boolean).join(', ');
        if (FamilyTreeBuilder._hasNameConflict(mSpouses, nSpouses)) {
            return true;
        }

        // Cross-sheet guard: if either profile has local implicit spouses that conflict
        // with the other's explicit spouse, these are different people who happen to share
        // one spouse name (e.g. two "Vareeth"s both married to "Ammini" but one also
        // married to "Mary" — the Marys are implicit spouses from the second sheet).
        if (!FamilyTreeBuilder.sharesSheet(m, n)) {
            for (const imp of (n._localImplicitSpouses || [])) {
                if (m.spouse && FamilyTreeBuilder._hasNameConflict(imp, m.spouse)) return true;
            }
            for (const imp of (m._localImplicitSpouses || [])) {
                if (n.spouse && FamilyTreeBuilder._hasNameConflict(imp, n.spouse)) return true;
            }
        }
        return false;
    }

    /**
     * Determines whether two same-named profiles share corroborative relational
     * evidence, i.e. a third person who vouches for them being one and the same.
     *
     * Corroboration is deliberately relational only. A shared name and a similar
     * age are the two cheapest coincidences in a genealogy sheet — half a village
     * is called Joby and born in the early seventies — so they buy no confidence
     * here. Only a shared parent or a shared spouse does.
     *
     * @param {Object} m - First candidate profile
     * @param {Object} n - Second candidate profile
     * @returns {boolean} True if corroborative evidence exists
     *
     * @example
     * builder._evaluateCorroborativeEvidence({ mom: 'Rosy' }, { mom: 'Rosy' });
     * // returns true
     *
     * @example
     * builder._evaluateCorroborativeEvidence({ mom: 'Rosy' }, { mom: 'Mary' });
     * // returns false
     *
     * @example
     * builder._evaluateCorroborativeEvidence({ yob: 1971 }, { yob: 1973 });
     * // returns false (two namesakes of about the same age vouch for nothing)
     */
    _evaluateCorroborativeEvidence(m, n) {
        if (m.spouse && n.spouse && !FamilyTreeBuilder._hasNameConflict(m.spouse, n.spouse)) return true;
        if (m.mom && n.mom && !FamilyTreeBuilder._hasNameConflict(m.mom, n.mom)) return true;
        if (m.father && n.father && !FamilyTreeBuilder._hasNameConflict(m.father, n.father)) return true;
        return false;
    }

    /**
     * Checks whether two profiles on different sheets record the very same
     * explicit birth year.
     *
     * This is weak evidence — enough to excuse the row-proximity check, which is
     * meaningless once two rows live on different sheets, but never enough to
     * excuse a conflicting town or trade. Note the strict equality: an
     * approximate match is no match at all, because two brothers are expected to
     * be born `CONSECUTIVE_SIBLING` years apart.
     *
     * @param {Object} m - First candidate profile
     * @param {Object} n - Second candidate profile
     * @returns {boolean} True if both sheets record an identical birth year
     *
     * @example
     * FamilyTreeBuilder._sharesExactCrossSheetBirthYear(
     *     { yob: 1952, _sourceIds: new Set(['a']) }, { yob: 1952, _sourceIds: new Set(['b']) });
     * // returns true
     *
     * @example
     * FamilyTreeBuilder._sharesExactCrossSheetBirthYear(
     *     { yob: 1971, _sourceIds: new Set(['a']) }, { yob: 1973, _sourceIds: new Set(['b']) });
     * // returns false (a two-year gap is a sibling gap, not an identity)
     */
    static _sharesExactCrossSheetBirthYear(m, n) {
        if (FamilyTreeBuilder.sharesSheet(m, n)) return false;
        return !!m.yob && m.yob === n.yob;
    }


    /**
     * Checks if a profile lacking explicit parents matches an anchor parent nearby on the other sheet's raw rows.
     *
     * @param {Object} m - First candidate profile
     * @param {Object} n - Second candidate profile
     * @returns {boolean} True if nearby parent on other sheet corroborates the merge
     *
     * @example
     * const m = { mom: '', father: '', _sheetRows: { s1: 5 } };
     * const n = { mom: 'Mary', father: '', _sheetRows: { s2: 10 } };
     * builder.rawRows = [{ _sourceId: 's1', _sheetRow: 3, Name: 'Mary' }];
     * builder._matchesCrossSheetNearbyParent(m, n);
     * // returns true (parent 'Mary' exists within 5 rows on sheet s1)
     *
     * @example
     * const m = { mom: 'Ann', father: '' };
     * const n = { mom: 'Ann', father: '' };
     * builder._matchesCrossSheetNearbyParent(m, n);
     * // returns false (both profiles already have parents)
     */
    _matchesCrossSheetNearbyParent(m, n) {
        if (FamilyTreeBuilder.sharesSheet(m, n)) return false;
        const hasNoParentsM = !m.mom && !m.father;
        const hasNoParentsN = !n.mom && !n.father;
        if (hasNoParentsM === hasNoParentsN) return false;

        const withParents = hasNoParentsM ? n : m;
        const withoutParents = hasNoParentsM ? m : n;
        const parentName = (withParents.mom || withParents.father || '').toLowerCase().trim();
        if (!parentName) return false;

        const withoutRows = withoutParents._sheetRows || {};
        for (const [sid, rowNum] of Object.entries(withoutRows)) {
            const rawSheetRows = this.rawRows ? this.rawRows.filter(r => (r._sourceId || 'default') === sid) : [];
            const parentExistsNearby = rawSheetRows.some(r => {
                const rName = (r.Name || r.NAME || '').toLowerCase().trim();
                const rRow = r._sheetRow || 0;
                return rName === parentName && rRow > 0 && rRow <= rowNum && rowNum - rRow <= 5;
            });
            if (parentExistsNearby) return true;
        }
        return false;
    }

    /**
     * Checks if two candidate nodes sharing the same sheet have conflicting parentage or relative names.
     *
     * @param {Object} m - First candidate person node
     * @param {Object} n - Second candidate person node
     * @param {boolean} corroborative - Whether corroborating evidence is present
     * @returns {boolean} True if a same-sheet merge conflict exists
     *
     * @example
     * const conflict1 = FamilyTreeBuilder._hasSameSheetMergeConflict({ name: 'Mary' }, { name: 'Mary' }, false);
     *
     * @example
     * const conflict2 = FamilyTreeBuilder._hasSameSheetMergeConflict({ mom: 'Ann' }, { mom: '' }, true);
     */
    static _hasSameSheetMergeConflict(m, n, corroborative) {
        if (!FamilyTreeBuilder.sharesSheet(m, n)) return false;
        if (!corroborative) return true;
        if (FamilyTreeBuilder._isRelativeName(m.name) && FamilyTreeBuilder._isRelativeName(n.name)) return true;
        const mHasParents = !!(m.mom || m.father);
        const nHasParents = !!(n.mom || n.father);
        return mHasParents !== nHasParents;
    }

    /**
     * Checks whether two candidate nodes have immediate property, kinship, or demographic conflicts.
     *
     * @param {Object} m - First candidate node
     * @param {Object} n - Second candidate node
     * @param {Object[]} [allNodes=[]] - Context nodes for sibling boundary calculation
     * @returns {boolean} True if a direct profile conflict is detected
     *
     * @example
     * const n1 = { yob: 1950, mom: 'Mary' };
     * const n2 = { yob: 1950, mom: 'Sarah' };
     * builder._hasDirectProfileConflict(n1, n2, []);
     * // returns true (conflicting mothers)
     *
     * @example
     * const n1 = { yob: 1950, mom: 'Mary', father: 'John' };
     * const n2 = { yob: 1950, mom: 'Mary', father: 'John' };
     * builder._hasDirectProfileConflict(n1, n2, []);
     * // returns false
     */
    _hasDirectProfileConflict(m, n, allNodes = []) {
        if (this._hasBirthYearOrSiblingConflict(m, n, allNodes)) return true;
        if (m.death && n.death && String(m.death).trim().toLowerCase() !== String(n.death).trim().toLowerCase()) return true;
        if (this._hasSpousalConflict(m, n)) return true;
        if (FamilyTreeBuilder._hasNameConflict(m.mom, n.mom)) return true;
        if (FamilyTreeBuilder._hasNameConflict(m.father, n.father)) return true;
        if (FamilyTreeBuilder._hasNameConflict(m.family, n.family)) return true;
        return false;
    }

    /**
     * Determines whether two candidate person records can be safely merged into a single profile.
     *
     * @param {Object} m - First candidate node
     * @param {Object} n - Second candidate node
     * @param {Object[]} [allNodes=[]] - Context nodes for sibling boundary calculation
     * @returns {boolean} True if m and n can be merged into a single profile
     *
     * @example
     * const n1 = { name: 'Gopal', _normName: 'gopal', father: 'Raman', mom: 'Lakshmi' };
     * const n2 = { name: 'Gopal', _normName: 'gopal', father: 'Raman', mom: 'Lakshmi' };
     * builder._canMergeProfiles(n1, n2, []);
     * // returns true
     *
     * @example
     * const n1 = { name: 'Gopal', _normName: 'gopal', father: 'Raman' };
     * const n2 = { name: 'Gopal', _normName: 'gopal', father: 'Suresh' };
     * builder._canMergeProfiles(n1, n2, []);
     * // returns false (conflicting fathers)
     */
    _canMergeProfiles(m, n, allNodes = []) {
        if (this._hasDirectProfileConflict(m, n, allNodes)) return false;

        let corroborative = this._evaluateCorroborativeEvidence(m, n);

        if (FamilyTreeBuilder._hasSameSheetMergeConflict(m, n, corroborative)) return false;

        if (!corroborative) {
            if (m.place && n.place && !m.place.toLowerCase().includes(n.place.toLowerCase()) && !n.place.toLowerCase().includes(m.place.toLowerCase())) return false;
            if (m.job && n.job && !m.job.toLowerCase().includes(n.job.toLowerCase()) && !n.job.toLowerCase().includes(m.job.toLowerCase())) return false;
        }

        if (!corroborative && this._matchesCrossSheetNearbyParent(m, n)) {
            corroborative = true;
        }

        // Deliberately placed *below* the place/job guards: an identical birth year
        // recorded on two sheets excuses the row-distance check (rows on different
        // sheets are always maximally far apart) but must never excuse a profile
        // that lives in a different town or works a different trade.
        if (!corroborative && FamilyTreeBuilder._sharesExactCrossSheetBirthYear(m, n)) {
            corroborative = true;
        }

        const dist = FamilyTreeBuilder._getMinRowDistance(m, n);
        if (!corroborative && dist > FamilyTreeBuilder.GENERATIONAL_GAPS.MAX_ROW_NEIGHBOR_DISTANCE) return false;

        return true;
    }

    /**
     * Merges source sheet tracking IDs, row mappings, and provenance references from source into target.
     * 
     * @param {Object} target - Receiving node
     * @param {Object} source - Incoming node
     * 
     * @example
     * const target = { _sourceIds: new Set(['s1']) };
     * const source = { _sourceIds: new Set(['s2']) };
     * builder._mergeNodeSourceTracking(target, source);
     * // target._sourceIds now contains 's1' and 's2'
     * 
     * @example
     * const target = { _sheetRows: { s1: 10 } };
     * const source = { _sheetRows: { s1: 5 } };
     * builder._mergeNodeSourceTracking(target, source);
     * // target._sheetRows.s1 updated to lower row 5
     */
    _mergeNodeSourceTracking(target, source) {
        if (source._sourceIds) {
            if (!target._sourceIds) target._sourceIds = new Set();
            source._sourceIds.forEach(id => target._sourceIds.add(id));
        }
        if (source._sheetRows) {
            if (!target._sheetRows) target._sheetRows = {};
            Object.keys(source._sheetRows).forEach(k => {
                if (!target._sheetRows[k] || source._sheetRows[k] < target._sheetRows[k]) {
                    target._sheetRows[k] = source._sheetRows[k];
                }
            });
        }
        if (source._allSourceRefs) {
            if (!target._allSourceRefs) target._allSourceRefs = [];
            target._allSourceRefs.push(...source._allSourceRefs);
        }
    }

    /**
     * Merges two comma-separated strings into a deduplicated comma-separated string.
     *
     * @param {string} s1 - First comma-separated string
     * @param {string} s2 - Second comma-separated string
     * @returns {string} Merged comma-separated string
     *
     * @example
     * FamilyTreeBuilder._mergeCommaSeparatedValues('Palakkad', 'Palakkad, Kerala');
     * // returns 'Palakkad, Kerala'
     *
     * @example
     * FamilyTreeBuilder._mergeCommaSeparatedValues('', 'Teacher');
     * // returns 'Teacher'
     */
    static _mergeCommaSeparatedValues(s1, s2) {
        if (!s1) return s2 || '';
        if (!s2) return s1 || '';
        const set = new Set([...s1.split(',').map(s => s.trim()), ...s2.split(',').map(s => s.trim())]);
        return Array.from(set).filter(Boolean).join(', ');
    }

    /**
     * Selects the more detailed (longer) non-empty string between two alternatives.
     *
     * @param {string} s1 - First string
     * @param {string} s2 - Second string
     * @returns {string} Preferred string
     *
     * @example
     * FamilyTreeBuilder._pickMoreDetailedString('Mary', 'Marykutty');
     * // returns 'Marykutty'
     *
     * @example
     * FamilyTreeBuilder._pickMoreDetailedString('Joseph', '');
     * // returns 'Joseph'
     */
    static _pickMoreDetailedString(s1, s2) {
        if (!s1) return s2 || '';
        if (!s2) return s1 || '';
        return s2.length > s1.length ? s2 : s1;
    }

    /**
     * Merges declared parent metadata (name, source sheet, and multi-sheet tracking set)
     * into the target profile, preferring longer/more detailed names and accumulating sheets.
     *
     * @param {Object} target - Target person profile
     * @param {Object} incoming - Incoming person profile
     * @param {string} nameKey - Property key for parent name (e.g. 'mom', 'father')
     * @param {string} sheetKey - Property key for parent source sheet (e.g. '_momSourceSheet')
     * @param {string} sheetsKey - Property key for parent source sheets set (e.g. '_momSourceSheets')
     *
     * @example
     * const target = { mom: 'Mary', _momSourceSheet: 's1' };
     * const incoming = { mom: 'Mary Ann', _momSourceSheet: 's2' };
     * FamilyTreeBuilder._mergeParentMetadata(target, incoming, 'mom', '_momSourceSheet', '_momSourceSheets');
     * // target.mom becomes 'Mary Ann', target._momSourceSheets contains 's1' and 's2'
     *
     * @example
     * const target = { mom: 'Mary Ann', _momSourceSheet: 's1' };
     * const incoming = { mom: 'Mary', _momSourceSheet: 's2' };
     * FamilyTreeBuilder._mergeParentMetadata(target, incoming, 'mom', '_momSourceSheet', '_momSourceSheets');
     * // target.mom remains 'Mary Ann' (longer name preferred)
     */
    static _mergeParentMetadata(target, incoming, nameKey, sheetKey, sheetsKey) {
        if (!target[nameKey] && incoming[nameKey]) {
            target[nameKey] = incoming[nameKey];
            target[sheetKey] = incoming[sheetKey];
        } else if (target[nameKey] && incoming[nameKey] && incoming[nameKey].length > target[nameKey].length) {
            target[nameKey] = incoming[nameKey];
            target[sheetKey] = incoming[sheetKey];
        } else if (target[nameKey] && !target[sheetKey] && incoming[sheetKey]) {
            target[sheetKey] = incoming[sheetKey];
        }
        if (!target[sheetsKey]) target[sheetsKey] = new Set(target[sheetKey] ? [target[sheetKey]] : []);
        if (incoming[sheetsKey]) incoming[sheetsKey].forEach(s => target[sheetsKey].add(s));
        if (incoming[sheetKey]) target[sheetsKey].add(incoming[sheetKey]);
    }

    /**
     * Merges domain fields from an incoming profile node into a matched target profile node.
     *
     * @param {Object} match - Target person node
     * @param {Object} n - Incoming duplicate person node
     *
     * @example
     * const match = { name: 'John', gender: '', place: 'Kochi' };
     * const incoming = { name: 'John', gender: 'M', place: 'Ernakulam' };
     * builder._mergeProfileFields(match, incoming);
     * // match.gender becomes 'M', match.place becomes 'Kochi, Ernakulam'
     *
     * @example
     * const match = { name: 'Mary', spouse: 'Joseph' };
     * const incoming = { name: 'Mary', spouse: 'Joseph Varghese' };
     * builder._mergeProfileFields(match, incoming);
     * // match.spouse becomes 'Joseph Varghese' (longer string selected)
     */
    _mergeProfileFields(match, n) {
        this._mergeNodeSourceTracking(match, n);

        match._mergeCount = (match._mergeCount || 1) + 1;
        match.gender = match.gender || n.gender;
        match.nick = match.nick || n.nick;
        match.sibling = FamilyTreeBuilder._mergeCommaSeparatedValues(match.sibling, n.sibling);

        FamilyTreeBuilder._mergeParentMetadata(match, n, 'mom', '_momSourceSheet', '_momSourceSheets');
        FamilyTreeBuilder._mergeParentMetadata(match, n, 'father', '_fatherSourceSheet', '_fatherSourceSheets');

        match.family = FamilyTreeBuilder._pickMoreDetailedString(match.family, n.family);
        match.spouse = FamilyTreeBuilder._pickMoreDetailedString(match.spouse, n.spouse);

        const mergedImplicit = new Set([...(match._localImplicitSpouses || []), ...(n._localImplicitSpouses || [])]);
        match._localImplicitSpouses = Array.from(mergedImplicit);
        if ((!match.spouseType || match.spouseType === 'spouse') && n.spouseType) match.spouseType = n.spouseType;
        match.death = match.death || n.death;
        match.job = FamilyTreeBuilder._mergeCommaSeparatedValues(match.job, n.job);
        match.place = FamilyTreeBuilder._mergeCommaSeparatedValues(match.place, n.place);
        match.freeForm = FamilyTreeBuilder._mergeCommaSeparatedValues(match.freeForm, n.freeForm);
        match.yob = match.yob || n.yob;
        match._hasExplicitYob = match._hasExplicitYob || n._hasExplicitYob;
    }

    /**
     * Parses natural language relational statements (spouse, mother, father) from freeForm descriptions.
     *
     * @param {Object} n - Person node
     *
     * @example
     * const node = { freeForm: 'married to Jane', spouse: '' };
     * builder._parseFreeFormRelations(node);
     * // node.spouse becomes 'Jane'
     *
     * @example
     * const node = { freeForm: 'mother is Rosy, father is Thomas', mom: '', father: '' };
     * builder._parseFreeFormRelations(node);
     * // node.mom becomes 'Rosy', node.father becomes 'Thomas'
     */
    _parseFreeFormRelations(n) {
        const t = n.freeForm.trim();
        if (/\b(?:no|without|zero|0)\s+(?:children|kids|issue|sons?|daughters?|boys?|girls?|siblings?|sisters?|brothers?)\b/i.test(t) || /\bchildless\b/i.test(t)) {
            return;
        }
        const spouseM = t.match(/\b(?:married to|wife is|husband is|spouse is|spouse:|wife:|husband:|partner is|partner:)\s*([A-Z][a-zA-Z\s]+?)(?:[,.;\n]|$|\band\b)/i);
        if (spouseM && !n.spouse) {
            n.spouse = spouseM[1].trim();
            const lower = spouseM[0].toLowerCase();
            if (lower.includes('husband')) n.spouseType = 'husband';
            else if (lower.includes('wife')) n.spouseType = 'wife';
        }
        const momM = t.match(/\b(?:mother is|mom is|mother:|mom:)\s*([A-Z][a-zA-Z\s]+?)(?:[,.;\n]|$|\band\b)/i);
        if (momM && !n.mom) n.mom = momM[1].trim();
        const dadM = t.match(/\b(?:father is|dad is|father:|dad:)\s*([A-Z][a-zA-Z\s]+?)(?:[,.;\n]|$|\band\b)/i);
        if (dadM && !n.father) n.father = dadM[1].trim();
    }

    /**
     * Parses natural language date properties (year of birth, death year, age) from freeForm text.
     *
     * @param {Object} n - Person node
     * @param {number} currentYear - Reference current year
     *
     * @example
     * const node = { freeForm: 'born in 1950', yob: null };
     * builder._parseFreeFormDates(node, 2026);
     * // node.yob becomes 1950
     *
     * @example
     * const node = { freeForm: 'died in 2010 age 70', yob: null, death: null };
     * builder._parseFreeFormDates(node, 2026);
     * // node.death becomes 2010, node.yob becomes 1940
     */
    _parseFreeFormDates(n, currentYear) {
        const t = n.freeForm.trim();
        const yobM = t.match(/\b(?:born in|birth year|born|b\.)\s*(\d{4})\b/i);
        if (yobM && !n.yob) n.yob = parseInt(yobM[1], 10);
        const deathM = t.match(/\b(?:died in|death year|died|d\.|passed away in)\s*(\d{4})\b/i);
        if (deathM && !n.death) n.death = parseInt(deathM[1], 10);
        const ageM = t.match(/\b(?:age|aged)\s*[:=]?\s*(\d{1,3})\b/i);
        if (ageM && !n.yob) {
            const ageVal = parseInt(ageM[1], 10);
            if (ageVal > 0 && ageVal < 110) {
                if (n.death && parseInt(n.death, 10)) n.yob = parseInt(n.death, 10) - ageVal;
                else n.yob = currentYear - ageVal;
            }
        }
    }

    /**
     * Identifies abstract roles, implied genders, and sibling indicators from free-form relation strings.
     *
     * @param {string} relStr - Natural language relation token (e.g. 'daughters', 'son')
     * @returns {{ role: string, gender: string, isSibling: boolean }}
     *
     * @example
     * builder._identifyFreeFormRole('daughters');
     * // returns { role: 'daughter', gender: 'F', isSibling: false }
     *
     * @example
     * builder._identifyFreeFormRole('brother');
     * // returns { role: 'brother', gender: 'M', isSibling: true }
     */
    _identifyFreeFormRole(relStr) {
        let role = '', gender = '', isSibling = false;
        if (relStr.includes('daughter') || relStr.includes('girl')) { role = 'daughter'; gender = 'F'; }
        else if (relStr.includes('son') || relStr.includes('boy')) { role = 'son'; gender = 'M'; }
        else if (relStr.includes('child') || relStr.includes('kid')) { role = 'child'; }
        else if (relStr.includes('sister')) { role = 'sister'; gender = 'F'; isSibling = true; }
        else if (relStr.includes('brother')) { role = 'brother'; gender = 'M'; isSibling = true; }
        else if (relStr.includes('sibling')) { role = 'sibling'; isSibling = true; }
        return { role, gender, isSibling };
    }

    /**
     * Parses English numeric words or digit strings into positive integer quantities.
     *
     * @param {string} token - Number token string (e.g. 'three', '4', 'a')
     * @returns {number|null} Parsed integer count or null if invalid
     *
     * @example
     * builder._parseWordNum('three');
     * // returns 3
     *
     * @example
     * builder._parseWordNum('5');
     * // returns 5
     */
    _parseWordNum(token) {
        if (!token) return null;
        const t = token.toLowerCase().trim();
        const w = {'a':1,'an':1,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12};
        if (w[t]) return w[t];
        const v = parseInt(t, 10);
        return (!isNaN(v) && v > 0) ? v : null;
    }

    /**
     * Resolves mother and father names for a sibling generated from free-form text,
     * assigning defaults to base node and registering in syntheticSiblingParentNames.
     *
     * @param {Object} n - Base person node
     * @returns {{ tm: string, td: string }} Mother and father names
     *
     * @example
     * const node = { name: 'John', mom: 'Mary', father: 'Joseph' };
     * builder._resolveFreeFormSiblingParents(node);
     * // returns { tm: 'Mary', td: 'Joseph' }
     *
     * @example
     * const node = { name: 'John', mom: '', father: '' };
     * builder._resolveFreeFormSiblingParents(node);
     * // returns { tm: 'John Mother', td: 'John Father' }
     */
    _resolveFreeFormSiblingParents(n) {
        const tm = n.mom || `${n.name} Mother`;
        const td = n.father || `${n.name} Father`;
        this.syntheticSiblingParentNames = this.syntheticSiblingParentNames || new Set();
        if (!n.mom) {
            n.mom = tm;
            this.syntheticSiblingParentNames.add(tm.toLowerCase().trim());
        }
        if (!n.father) {
            n.father = td;
            this.syntheticSiblingParentNames.add(td.toLowerCase().trim());
        }
        return { tm, td };
    }

    /**
     * Attaches a synthesized ghost node to the base node as either an explicit sibling or a child.
     *
     * @param {Object} g - Synthesized ghost relative node
     * @param {Object} baseNode - Reference node receiving the relative
     * @param {boolean} isSibling - Whether the relative is a sibling
     * @param {boolean} [isAdditional=false] - Whether this is an additional ghost child
     *
     * @example
     * FamilyTreeBuilder._attachGhostToFamily({ id: 'g1' }, { explicitSiblings: [] }, true);
     * // => baseNode.explicitSiblings includes 'g1'
     *
     * @example
     * FamilyTreeBuilder._attachGhostToFamily({ id: 'g2' }, { children: [] }, false, true);
     * // => g2._fromFreeForm is true, g2._isAdditional is true, baseNode.children includes 'g2'
     */
    static _attachGhostToFamily(g, baseNode, isSibling, isAdditional = false) {
        if (isSibling) {
            if (!baseNode.explicitSiblings) baseNode.explicitSiblings = [];
            baseNode.explicitSiblings.push(g.id);
        } else {
            g._fromFreeForm = true;
            if (isAdditional) g._isAdditional = true;
            if (!baseNode.children) baseNode.children = [];
            if (!baseNode.children.includes(g.id)) baseNode.children.push(g.id);
        }
    }

    /**
     * Instantiates ghost relative profiles and links them to the base node as siblings or children.
     *
     * @param {Object} params - Parameter object
     * @param {Object} params.baseNode - Source node
     * @param {string} params.role - Relative role
     * @param {string} params.gender - Gender ('M' or 'F')
     * @param {boolean} params.isSibling - Whether relative is a sibling
     * @param {number} params.count - Total count of relatives in this group
     * @param {string} params.targetMom - Target mother name
     * @param {string} params.targetDad - Target father name
     * @param {boolean} params.isAdditional - Whether description specifies additional relatives
     * @param {Object[]} params.nodes - Active nodes
     * @param {Object[]} params.newNodes - Newly synthesized nodes accumulator
     *
     * @example
     * FamilyTreeBuilder._synthesizeFreeFormRelativeGhosts({
     *   baseNode: n, role: 'son', gender: 'M', isSibling: false, count: 2,
     *   targetMom: '', targetDad: '', isAdditional: false, nodes: [], newNodes: []
     * });
     * // => Appends 2 ghost sons to newNodes and registers IDs in baseNode.children
     *
     * @example
     * FamilyTreeBuilder._synthesizeFreeFormRelativeGhosts({
     *   baseNode: n, role: 'sister', gender: 'F', isSibling: true, count: 1,
     *   targetMom: 'Mary', targetDad: 'Joseph', isAdditional: true, nodes: [], newNodes: []
     * });
     * // => Appends 1 ghost sister to newNodes and adds ID to baseNode.explicitSiblings
     */
    static _synthesizeFreeFormRelativeGhosts({ baseNode, role, gender, isSibling, count, targetMom, targetDad, isAdditional, nodes, newNodes }) {
        for (let i = 1; i <= count; i++) {
            const g = FamilyTreeBuilder._createGhostRelative({
                baseNode,
                role,
                index: i,
                totalCount: count,
                gender,
                isSibling,
                nodeCount: nodes.length,
                newNodeCount: newNodes.length,
                targetMom,
                targetDad
            });
            FamilyTreeBuilder._attachGhostToFamily(g, baseNode, isSibling, isAdditional);
            newNodes.push(g);
        }
    }

    /**
     * Extracts quantitative sibling/child generations from free-form text and synthesizes ghost records.
     *
     * @param {Object} n - Source node with free-form text
     * @param {Object[]} nodes - Active nodes
     * @param {Object[]} newNodes - Newly synthesized nodes accumulator
     *
     * @example
     * builder._parseFreeFormQuantities({ freeForm: 'Has 2 sons and 1 daughter', children: [] }, [], newNodes);
     * // => Synthesizes 2 ghost sons and 1 ghost daughter into newNodes
     *
     * @example
     * builder._parseFreeFormQuantities({ freeForm: 'childless', children: [] }, [], newNodes);
     * // => Early returns without synthesizing any ghosts
     */
    _parseFreeFormQuantities(n, nodes, newNodes) {
        const t = n.freeForm.trim();
        if (/\b(?:no|without|zero|0)\s+(?:children|kids|issue|sons?|daughters?|boys?|girls?|siblings?|sisters?|brothers?)\b/i.test(t) || /\bchildless\b/i.test(t)) {
            return;
        }
        const numPattern = /(?:\b(?:additional|more)\s+)?(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|a|an)?\s*(?:additional|more)?\s*(daughters?|sons?|children|kids|boys?|girls?|sisters?|brothers?|siblings?)/gi;
        let match;
        while ((match = numPattern.exec(t)) !== null) {
            const count = this._parseWordNum(match[1]) || 1;
            const { role, gender, isSibling } = this._identifyFreeFormRole(match[2].toLowerCase());
            if (!role) continue;
            let tm = '', td = '';
            if (isSibling) {
                const parents = this._resolveFreeFormSiblingParents(n);
                tm = parents.tm;
                td = parents.td;
            }
            const isAdditional = match[0].toLowerCase().includes('additional') || match[0].toLowerCase().includes('more');
            FamilyTreeBuilder._synthesizeFreeFormRelativeGhosts({
                baseNode: n, role, gender, isSibling, count,
                targetMom: tm, targetDad: td, isAdditional, nodes, newNodes
            });
        }
    }

    /**
     * Extracts structured attributes and ghost relationships from free-form descriptions across all nodes.
     *
     * @param {Object[]} nodes - Validated Person instances
     *
     * @example
     * builder.processFreeForm([personA, personB]);
     * // => Parses free-form text on all nodes, creating ghost relatives and indexing them
     *
     * @example
     * builder.processFreeForm([{ name: 'John', freeForm: '3 daughters' }]);
     * // => Generates and indexes 3 ghost daughter nodes in builder.nodeMap and builder.name2nodes
     */
    processFreeForm(nodes) {
        const currentYear = new Date().getFullYear();
        const newNodes = [];
        nodes.forEach(n => {
            if (!n.freeForm || !n.freeForm.trim()) return;
            this._parseFreeFormRelations(n);
            this._parseFreeFormDates(n, currentYear);
            this._parseFreeFormQuantities(n, nodes, newNodes);
        });
        this._indexNewNodes(nodes, newNodes);
    }

    /**
     * Indexes newly synthesized nodes into the master node list and lookup indices.
     * 
     * @param {Object[]} nodes - Master node list
     * @param {Object[]} newNodes - Newly created ghost nodes
     *
     * @example
     * builder._indexNewNodes(nodes, [ghostNode1, ghostNode2]);
     * // => Appends ghosts to nodes, maps by id in builder.nodeMap, and records in builder.name2nodes
     *
     * @example
     * builder._indexNewNodes([], [{ id: 'g_1', _normName: 'mary' }]);
     * // => builder.nodeMap['g_1'] is set and builder.name2nodes['mary'] contains the node
     */
    _indexNewNodes(nodes, newNodes) {
        newNodes.forEach(node => {
            nodes.push(node);
            this.nodeMap[node.id] = node;
            const lower = node._normName;
            if (!this.name2nodes[lower]) this.name2nodes[lower] = [];
            if (!this.name2nodes[lower].includes(node)) {
                this.name2nodes[lower].push(node);
            }
        });
    }

    /**
     * Expands multi-level compound relative names into ghost profiles and links.
     * 
     * Supports:
     * - [Child, Spouse]: e.g. "Rosy Daughter 1 Husband", "Rachel Son 1 Wife"
     * - [Sibling, Spouse]: e.g. "Devasikkutty Sister 1 Husband", "Mary Brother Wife"
     * - [Sibling, Child]: e.g. "Kunjagaasthi Brother Daughter 3"
     * - [Child, Child]: e.g. "George Son 1 Daughter 1"
     * - [Parent, Spouse]: e.g. "Annamma Father Wife 2"
     * - [Spouse, Parent]: e.g. "Rosy Husband Father"
     */

    static _RELATIVE_CHILD_TOKENS = new Set(['son', 'boy', 'daughter', 'dau', 'girl', 'child', 'kid']);
    static _RELATIVE_SIBLING_TOKENS = new Set(['brother', 'sister', 'bro', 'sis']);
    static _RELATIVE_PARENT_TOKENS = new Set(['father', 'mother', 'dad', 'mom']);
    static _RELATIVE_SPOUSE_TOKENS = new Set(['wife', 'husband', 'hus']);

    /**
     * Dispatches multi-level compound relative expansion to the appropriate relationship handler.
     *
     * @param {Object} n - Declaring compound node
     * @param {Object} ctx - Multi-level resolution context
     * @param {string} r1 - First relationship token
     * @param {string} r2 - Second relationship token
     *
     * @example
     * builder._dispatchMultiLevelCompound(n, ctx, 'daughter', 'husband');
     * // => Invokes _expandChildSpouseCompound(n, ctx)
     *
     * @example
     * builder._dispatchMultiLevelCompound(n, ctx, 'brother', 'son');
     * // => Invokes _expandSiblingChildCompound(n, ctx)
     */
    _dispatchMultiLevelCompound(n, ctx, r1, r2) {
        const C = FamilyTreeBuilder._RELATIVE_CHILD_TOKENS;
        const S = FamilyTreeBuilder._RELATIVE_SIBLING_TOKENS;
        const P = FamilyTreeBuilder._RELATIVE_PARENT_TOKENS;
        const W = FamilyTreeBuilder._RELATIVE_SPOUSE_TOKENS;

        if (C.has(r1) && W.has(r2)) this._expandChildSpouseCompound(n, ctx);
        else if (S.has(r1) && W.has(r2)) this._expandSiblingSpouseCompound(n, ctx);
        else if (S.has(r1) && C.has(r2)) this._expandSiblingChildCompound(n, ctx);
        else if (C.has(r1) && C.has(r2)) this._expandChildChildCompound(n, ctx);
        else if (P.has(r1) && W.has(r2)) this._expandParentSpouseCompound(n, ctx);
        else if (W.has(r1) && P.has(r2)) this._expandSpouseParentCompound(n, ctx);
    }

    /**
     * Inserts a space between adjacent letters and digits so unspaced compound tokens
     * like "Sister1" or "Daughter3" normalize to "Sister 1" and "Daughter 3".
     *
     * @param {string} name - Raw relative compound string from a spreadsheet row
     * @returns {string} Trimmed name with letter-digit boundaries separated by a single space
     *
     * @example
     * FamilyTreeBuilder._normalizeRelativeCompoundName('Rosy Daughter1 Husband');
     * // => 'Rosy Daughter 1 Husband'
     *
     * @example
     * FamilyTreeBuilder._normalizeRelativeCompoundName('Mary Sister1 Daughter2');
     * // => 'Mary Sister 1 Daughter 2'
     */
    static _normalizeRelativeCompoundName(name) {
        return name.replace(/([a-zA-Z]+)(\d+)/g, '$1 $2').trim();
    }

    /**
     * Expands multi-level relative strings (e.g. "Rosy Daughter 1 Husband", "George Son 1 Daughter 1")
     * into intermediate ghost Person profiles and resolves cross-tier genealogical links.
     * 
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     *
     * @example
     * builder._expandMultiLevelRelatives(ws); // ws.nodes = [{ name: 'Rosy Daughter 1 Husband' }]
     * // => Generates ghost "Rosy Daughter 1", links to husband and parent Rosy
     *
     * @example
     * builder._expandMultiLevelRelatives(ws); // ws.nodes = [{ name: 'George Son 1 Daughter 1' }]
     * // => Generates "George Son 1" and intermediate spouse, linking child to the couple
     */
    _expandMultiLevelRelatives(ws) {
        const relWordsPattern = '(?:Daughter|Dau|Son|Girl|Boy|Brother|Sister|Bro|Sis|Father|Mother|Dad|Mom|Husband|Wife|Hus)';
        const multiLevelRegex = new RegExp(`^(.+?)\\s+(${relWordsPattern})(?:\\s*(\\d+))?\\s+(${relWordsPattern})(?:\\s*(\\d+))?$`, 'i');

        ws.nodes.forEach(n => {
            if (!n.name) return;
            const normalizedName = FamilyTreeBuilder._normalizeRelativeCompoundName(n.name);
            const m = normalizedName.match(multiLevelRegex);
            if (!m) return;

            const baseName = m[1].trim();
            const r1 = m[2].toLowerCase();
            const n1 = m[3] ? parseInt(m[3], 10) : null;
            const r2 = m[4].toLowerCase();
            const n2 = m[5] ? parseInt(m[5], 10) : null;

            const ctx = this._buildMultiLevelContext(n, { baseName, r1, n1, r2, n2 }, ws);
            this._dispatchMultiLevelCompound(n, ctx, r1, r2);
        });
    }

    /**
     * Builds resolution context for multi-level relative compounds.
     *
     * @param {Object} n - Declaring compound node
     * @param {Object} parsedCompound - Extracted relation tokens ({ baseName, r1, n1, r2, n2 })
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {Object} Resolution context object
     *
     * @example
     * builder._buildMultiLevelContext(n, { baseName: 'Rosy', r1: 'daughter', n1: 1, r2: 'husband', n2: null }, ws);
     * // => { anchorNode, anchorName: 'Rosy', r1: 'daughter', n1: 1, r2: 'husband', n2: null, ws }
     *
     * @example
     * builder._buildMultiLevelContext(n, { baseName: 'Mary', r1: 'brother', n1: null, r2: 'wife', n2: null }, ws);
     * // => { anchorNode, anchorName: 'Mary', r1: 'brother', n1: null, r2: 'wife', n2: null, ws }
     */
    _buildMultiLevelContext(n, parsedCompound, ws) {
        const { baseName, r1, n1, r2, n2 } = parsedCompound;
        const anchorNode = this._findAnchorNode(baseName, n, ws);
        const anchorName = anchorNode ? anchorNode.name : baseName;
        const srcId = anchorNode ? (anchorNode._sourceId || n._sourceId) : n._sourceId;
        const isAnchorFemale = anchorNode ? (anchorNode.gender === 'F' || anchorNode.spouseType === 'wife') : false;

        const knownSpouseNode = this._findKnownSpouseNode(anchorNode, anchorName, ws);

        return {
            anchorNode, anchorName, srcId, isAnchorFemale,
            knownSpouseNode, knownSpouseName: knownSpouseNode ? knownSpouseNode.name : null,
            baseName, r1, n1, r2, n2, ws
        };
    }

    /**
     * Inherits sheet rows and source tracking identifiers from anchor and declaring nodes
     * onto a ghost child node.
     *
     * @param {Object} cNode - Ghost child node
     * @param {Object|null} anchorNode - Anchor parent node
     * @param {Object} n - Declaring partner node
     * @param {boolean} isMarried - Whether ghost child is part of a spousal compound
     *
     * @example
     * FamilyTreeBuilder._inheritGhostSourceTracking(cNode, anchorNode, n, true);
     * // => cNode._sheetRows and cNode._sourceIds updated from anchorNode and n
     *
     * @example
     * FamilyTreeBuilder._inheritGhostSourceTracking(cNode, null, n, false);
     * // => Combines source tracking identifiers solely from n into cNode._sourceIds
     */
    static _inheritGhostSourceTracking(cNode, anchorNode, n, isMarried) {
        if (isMarried) {
            if (!cNode._sheetRows) {
                cNode._sheetRows = n._sheetRows ? { ...n._sheetRows } : (anchorNode && anchorNode._sheetRows ? { ...anchorNode._sheetRows } : undefined);
            }
            if (!cNode._sheetRow) {
                cNode._sheetRow = n._sheetRow || (anchorNode ? anchorNode._sheetRow : undefined);
            }
        }
        const combinedSources = new Set([...(cNode._sourceIds || []), ...(anchorNode?._sourceIds || []), ...(anchorNode?._sourceId ? [anchorNode._sourceId] : []), ...(n._sourceIds || []), ...(n._sourceId ? [n._sourceId] : [])]);
        cNode._sourceIds = combinedSources;
    }

    /**
     * Links a ghost child node to its anchor parent and spousal ghost parent, establishing
     * parent IDs and registering child references on parent nodes.
     *
     * @param {Object} cNode - Child node
     * @param {Object|null} anchorNode - Anchor parent node
     * @param {boolean} isAnchorFemale - Whether anchor parent is female
     * @param {Object|null} pSpouseGhost - Spousal ghost parent node
     *
     * @example
     * FamilyTreeBuilder._linkGhostChildToParents(childNode, motherNode, true, fatherGhost);
     * // => childNode.momId = motherNode.id, childNode.fatherId = fatherGhost.id
     *
     * @example
     * FamilyTreeBuilder._linkGhostChildToParents(childNode, fatherNode, false, motherGhost);
     * // => childNode.fatherId = fatherNode.id, childNode.momId = motherGhost.id
     */
    static _linkGhostChildToParents(cNode, anchorNode, isAnchorFemale, pSpouseGhost) {
        if (anchorNode) {
            cNode._namedParentId = anchorNode.id;
            if (isAnchorFemale) {
                        cNode.momId = anchorNode.id;
                        if (pSpouseGhost) cNode.fatherId = pSpouseGhost.id;
                    } else {
                        cNode.fatherId = anchorNode.id;
                        if (pSpouseGhost) cNode.momId = pSpouseGhost.id;
                    }
        }

        if (pSpouseGhost) {
            if (!pSpouseGhost.children.includes(cNode.id)) pSpouseGhost.children.push(cNode.id);
            if (anchorNode && !anchorNode.children.includes(cNode.id)) anchorNode.children.push(cNode.id);
        }
    }

    /**
     * Establishes mutual spousal partnership between a child node and declaring node,
     * resetting declaring node's parent strings.
     *
     * @param {Object} cNode - Child node
     * @param {Object} n - Declaring partner node
     *
     * @example
     * FamilyTreeBuilder._linkChildSpousePartnership(childNode, declaringNode);
     * // => cNode.spouse = declaringNode.name, declaringNode.spouse = childNode.name, partners linked
     *
     * @example
     * FamilyTreeBuilder._linkChildSpousePartnership(sonNode, inLawNode);
     * // => Resets inLawNode.mom = '' and inLawNode.father = ''
     */
    static _linkChildSpousePartnership(cNode, n) {
        cNode.spouse = n.name;
        n.spouse = cNode.name;
        FamilyTreeBuilder._linkMutualPartners(cNode, n);
        n.mom = '';
        n.father = '';
    }

    /**
     * Establishes mutual partnership edge between two person nodes if not already present.
     *
     * @param {Object|null} nodeA - First partner node
     * @param {Object|null} nodeB - Second partner node
     *
     * @example
     * FamilyTreeBuilder._linkMutualPartners(nodeA, nodeB);
     * // => nodeA.partners.includes(nodeB.id) && nodeB.partners.includes(nodeA.id)
     *
     * @example
     * FamilyTreeBuilder._linkMutualPartners(nodeA, null);
     * // => No-op when either node is null or undefined
     */
    static _linkMutualPartners(nodeA, nodeB) {
        if (!nodeA || !nodeB || nodeA.id === nodeB.id) return;
        if (!nodeA.partners.includes(nodeB.id)) nodeA.partners.push(nodeB.id);
        if (!nodeB.partners.includes(nodeA.id)) nodeB.partners.push(nodeA.id);
    }

    /**
     * Registers a child identifier on a parent node's children list without duplicates.
     *
     * @param {Object|null} parent - Parent node
     * @param {string} childId - Child identifier
     *
     * @example
     * FamilyTreeBuilder._addChildIdToParent(parent, 'child_1');
     * // => parent.children includes 'child_1'
     *
     * @example
     * FamilyTreeBuilder._addChildIdToParent(null, 'child_1');
     * // => Safe no-op when parent is null or childId is empty
     */
    static _addChildIdToParent(parent, childId) {
        if (!parent || !childId) return;
        if (!parent.children.includes(childId)) {
            parent.children.push(childId);
        }
    }

    /**
     * Deduces the display name of an anchor node's spouse and parents (mother and father)
     * based on anchor gender, optional known spouse, and fallback behavior.
     *
     * @param {string} anchorName - Name of the anchor node
     * @param {boolean} isAnchorFemale - Whether anchor is female
     * @param {string|null} [knownSpouseName=null] - Known spouse name if present
     * @param {boolean} [fallbackToSyntheticSpouse=true] - Whether to fallback to synthetic spouse when known spouse is absent
     * @returns {{ targetSpouse: string, parentMom: string, parentDad: string }}
     *
     * @example
     * FamilyTreeBuilder._deduceAnchorSpouseAndParents('George', false, null);
     * // => { targetSpouse: 'George Wife', parentMom: 'George Wife', parentDad: 'George' }
     *
     * @example
     * FamilyTreeBuilder._deduceAnchorSpouseAndParents('Rosy', true, 'Joy');
     * // => { targetSpouse: 'Joy', parentMom: 'Rosy', parentDad: 'Joy' }
     */
    static _deduceAnchorSpouseAndParents(anchorName, isAnchorFemale, knownSpouseName = null, fallbackToSyntheticSpouse = true) {
        const targetSpouse = knownSpouseName || (isAnchorFemale ? `${anchorName} Husband` : `${anchorName} Wife`);
        const parentMom = isAnchorFemale ? anchorName : (fallbackToSyntheticSpouse || knownSpouseName ? targetSpouse : '');
        const parentDad = isAnchorFemale ? (fallbackToSyntheticSpouse || knownSpouseName ? targetSpouse : '') : anchorName;
        return { targetSpouse, parentMom, parentDad };
    }

    /**
     * Executes a callback for each relative name in a numbered or single-entity series.
     * When num is null, executes once for "${baseName} ${role}".
     * When num is provided, executes for each index from 1 up to max(num, minCount),
     * indicating whether the current index matches target num.
     *
     * @param {string} baseName - Anchor base name (e.g. 'Rosy')
     * @param {string} role - Capitalized role name (e.g. 'Daughter')
     * @param {number|null} num - 1-based index or null
     * @param {Function} callback - (name: string, isTarget: boolean, index: number) => void
     * @param {number} [minCount=2] - Minimum count when numbered
     *
     * @example
     * FamilyTreeBuilder._forEachRelativeInSeries('Antu', 'Son', null, (name, isTarget) => {});
     * // => Invokes callback once with ('Antu Son', true, 1)
     *
     * @example
     * FamilyTreeBuilder._forEachRelativeInSeries('Antu', 'Son', 1, (name, isTarget) => {});
     * // => Invokes callback for ('Antu Son 1', true, 1) and ('Antu Son 2', false, 2)
     */
    static _forEachRelativeInSeries(baseName, role, num, callback, minCount = 2) {
        if (num !== null && !isNaN(num)) {
            const count = Math.max(num, minCount);
            for (let i = 1; i <= count; i++) {
                callback(`${baseName} ${role} ${i}`, i === num, i);
            }
        } else {
            callback(`${baseName} ${role}`, true, 1);
        }
    }

    /**
     * Resolves or creates a child ghost for compound relations, binding parentage,
     * source sheet tracking, and marriage to the in-law spouse.
     *
     * @param {string} cName - Child node name (e.g., "Rosy Daughter 1")
     * @param {boolean} isDaughter - Whether the child is female
     * @param {Object} parentInfo - Parent names and spouse ghost ({ parentMom, parentDad, pSpouseGhost })
     * @param {boolean} isMarried - Whether this child marries the compound node n
     * @param {Object} n - The compound in-law node
     * @param {Object} ctx - Multi-level context with anchorNode, ws, etc.
     * @returns {Object} The resolved or created child node
     *
     * @example
     * builder._resolveAndLinkChildSpouseGhost('Rosy Daughter 1', true, { parentMom: 'Rosy', parentDad: 'Rosy Husband', pSpouseGhost: pSpouse }, true, n, ctx);
     * // => Child node for 'Rosy Daughter 1' linked to Rosy & spouse, partnered with n
     *
     * @example
     * builder._resolveAndLinkChildSpouseGhost('George Son 2', false, { parentMom: 'George Wife', parentDad: 'George', pSpouseGhost: null }, false, n, ctx);
     * // => Child node for 'George Son 2' linked to George, unpartnered with n
     */
    _resolveAndLinkChildSpouseGhost(cName, isDaughter, parentInfo, isMarried, n, ctx) {
        const { parentMom, parentDad, pSpouseGhost } = parentInfo;
        const { anchorNode, srcId, isAnchorFemale, ws } = ctx;
        let cNode = ws.find(cName);
        if (!cNode) {
            cNode = ws.create(cName, isDaughter ? 'F' : 'M', { mom: parentMom, dad: parentDad, srcId });
            FamilyTreeBuilder._inheritGhostSourceTracking(cNode, anchorNode, n, isMarried);
            if (n._sourceId) cNode._sourceId = n._sourceId;
        } else {
            if (!cNode.mom) cNode.mom = parentMom;
            if (!cNode.father) cNode.father = parentDad;
            FamilyTreeBuilder._inheritGhostSourceTracking(cNode, anchorNode, n, isMarried);
        }

        FamilyTreeBuilder._linkGhostChildToParents(cNode, anchorNode, isAnchorFemale, pSpouseGhost);

        if (isMarried) {
            FamilyTreeBuilder._linkChildSpousePartnership(cNode, n);
        }

        return cNode;
    }

    /**
     * Expands [Child, Spouse] compounds (e.g. "Rosy Daughter 1 Husband", "Rachel Son 1 Wife").
     *
     * @param {Object} n - Declaring child-spouse node
     * @param {Object} ctx - Multi-level resolution context
     *
     * @example
     * builder._expandChildSpouseCompound({ name: 'Rosy Daughter 1 Husband' }, ctx);
     * // => Resolves 'Rosy Daughter 1' and 'Rosy Husband', links child to parents and partner
     *
     * @example
     * builder._expandChildSpouseCompound({ name: 'George Son 2 Wife' }, ctx);
     * // => Synthesizes 'George Son 2' and 'George Wife', establishing couple relationships
     */
    _expandChildSpouseCompound(n, ctx) {
        const { anchorNode, anchorName, srcId, isAnchorFemale, knownSpouseNode, knownSpouseName, r1, n1, ws } = ctx;
        const childRole = r1.charAt(0).toUpperCase() + r1.slice(1);
        const isDaughter = (r1 === 'daughter' || r1 === 'girl' || r1 === 'dau');
        const { targetSpouse: targetParentSpouse, parentMom, parentDad } =
            FamilyTreeBuilder._deduceAnchorSpouseAndParents(anchorName, isAnchorFemale, knownSpouseName);

        if (!n.gender) n.gender = isDaughter ? 'M' : 'F';

        let pSpouseGhost = knownSpouseNode || ws.find(targetParentSpouse, anchorNode);
        if (n1 !== null) {
            if (!pSpouseGhost) {
                pSpouseGhost = ws.create(targetParentSpouse, isAnchorFemale ? 'M' : 'F', { srcId });
                pSpouseGhost.spouse = anchorName;
            }
            FamilyTreeBuilder._linkMutualPartners(anchorNode, pSpouseGhost);
        }

        const parentInfo = { parentMom, parentDad, pSpouseGhost };
        FamilyTreeBuilder._forEachRelativeInSeries(anchorName, childRole, n1, (cName, isTarget) => {
            this._resolveAndLinkChildSpouseGhost(cName, isDaughter, parentInfo, isTarget, n, ctx);
        });
    }

    /**
     * Ensures parent ghosts exist for synthetic sibling parents and returns them.
     *
     * @param {string} targetMom - Mother ghost name
     * @param {string} targetDad - Father ghost name
     * @param {string} srcId - Sheet source ID
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {{ pMomGhost: Object, pDadGhost: Object }}
     *
     * @example
     * builder._ensureSiblingParentGhosts('Mary Mother', 'Mary Father', 's1', ws);
     * // => { pMomGhost: { name: 'Mary Mother' }, pDadGhost: { name: 'Mary Father' } }
     *
     * @example
     * builder._ensureSiblingParentGhosts('Ann Mother', 'Ann Father', 's2', ws);
     * // => Returns resolved or newly synthesized parent ghost objects
     */
    _ensureSiblingParentGhosts(targetMom, targetDad, srcId, ws) {
        const pMomGhost = ws.resolveOrCreate(targetMom, 'F', { srcId });
        const pDadGhost = ws.resolveOrCreate(targetDad, 'M', { srcId });
        return { pMomGhost, pDadGhost };
    }

    /**
     * Resolves or instantiates a sibling ghost profile under shared parents,
     * optionally linking them to an in-law spouse profile.
     *
     * @param {string} sName - Sibling profile name (e.g. 'Devasikkutty Sister 1')
     * @param {string} gender - Sibling gender ('F' or 'M')
     * @param {Object} parentInfo - Sibling parent descriptors ({ targetMom, targetDad, pMomGhost, pDadGhost })
     * @param {Object|null} inLawSpouse - In-law spouse node to bind if applicable
     * @param {Object} ctx - Context with lookup, factory, and accumulator
     * @returns {Object} Sibling domain node
     *
     * @example
     * builder._resolveAndLinkSiblingGhost('Mary Sister 1', 'F', { targetMom: 'Mary Mother', targetDad: 'Mary Father', pMomGhost: pMom, pDadGhost: pDad }, inLawHusband, ctx);
     * // => Sister node linked to pMom, pDad, and partnered with inLawHusband
     *
     * @example
     * builder._resolveAndLinkSiblingGhost('Devasikkutty Brother 2', 'M', { targetMom: 'Dev Mother', targetDad: 'Dev Father', pMomGhost: pMom, pDadGhost: pDad }, null, ctx);
     * // => Brother node registered as child of pMom and pDad without in-law partner
     */
    _resolveAndLinkSiblingGhost(sName, gender, parentInfo, inLawSpouse, ctx) {
        const { targetMom, targetDad, pMomGhost, pDadGhost } = parentInfo;
        const { srcId, ws } = ctx;
        let sNode = ws.find(sName);
        if (!sNode) {
            sNode = ws.create(sName, gender, { mom: targetMom, dad: targetDad, srcId });
        } else {
            if (!sNode.mom) sNode.mom = targetMom;
            if (!sNode.father) sNode.father = targetDad;
        }

        FamilyTreeBuilder._addChildIdToParent(pMomGhost, sNode.id);
        FamilyTreeBuilder._addChildIdToParent(pDadGhost, sNode.id);

        if (inLawSpouse) {
            sNode.spouse = inLawSpouse.name;
            inLawSpouse.spouse = sName;
            FamilyTreeBuilder._linkMutualPartners(sNode, inLawSpouse);
            inLawSpouse.mom = '';
            inLawSpouse.father = '';
        }
        return sNode;
    }

    /**
     * Sets up synthetic sibling parent names on anchor node and ensures ghost parent entities exist.
     *
     * @param {Object|null} anchorNode - Biological sibling anchor node
     * @param {string} baseName - Base name of the sibling reference
     * @param {string} srcId - Sheet source ID
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {{ targetMom: string, targetDad: string, pMomGhost: Object, pDadGhost: Object }}
     *
     * @example
     * this._setupSiblingParentGhosts(anchorNode, 'Mary', srcId, ws);
     * // => { targetMom: 'Mary Mother', targetDad: 'Mary Father', pMomGhost, pDadGhost }
     *
     * @example
     * this._setupSiblingParentGhosts(null, 'Paul', srcId, ws);
     * // => { targetMom: 'Paul Mother', targetDad: 'Paul Father', pMomGhost, pDadGhost }
     */
    _setupSiblingParentGhosts(anchorNode, baseName, srcId, ws) {
        const { targetMom, targetDad } = this._resolveTargetSiblingParents(anchorNode, baseName);
        const { pMomGhost, pDadGhost } = this._ensureSiblingParentGhosts(targetMom, targetDad, srcId, ws);
        return { targetMom, targetDad, pMomGhost, pDadGhost };
    }

    /**
     * Expands [Sibling, Spouse] compounds (e.g. "Devasikkutty Sister 1 Husband", "Mary Brother Wife").
     *
     * @param {Object} n - Compound in-law profile node
     * @param {Object} ctx - Multi-level context
     *
     * @example
     * builder._expandSiblingSpouseCompound({ name: 'Mary Brother 1 Wife' }, ctx);
     * // => Synthesizes sibling ghost 'Mary Brother 1' and links in-law wife
     *
     * @example
     * builder._expandSiblingSpouseCompound({ name: 'Paul Sister Husband' }, ctx);
     * // => Sets up synthetic parents, sibling 'Paul Sister', and mutual partnership
     */
    _expandSiblingSpouseCompound(n, ctx) {
        const { anchorNode, anchorName, srcId, baseName, r1, n1, ws } = ctx;
        const sibRole = r1.charAt(0).toUpperCase() + r1.slice(1);
        const isSister = (r1 === 'sister' || r1 === 'sis');
        const sibGender = isSister ? 'F' : 'M';

        if (!n.gender) n.gender = isSister ? 'M' : 'F';

        const parentInfo = this._setupSiblingParentGhosts(anchorNode, anchorName || baseName, srcId, ws);

        FamilyTreeBuilder._forEachRelativeInSeries(anchorName, sibRole, n1, (sName, isTarget) => {
            const inLawSpouse = isTarget ? n : null;
            this._resolveAndLinkSiblingGhost(sName, sibGender, parentInfo, inLawSpouse, ctx);
        });
    }

    /**
     * Resolves an existing spouse ghost or instantiates a new one, establishing mutual partner links.
     *
     * @param {Object|null} primaryNode - Subject person node to link as partner
     * @param {string} spouseName - Name of the spouse node
     * @param {string} spouseGender - Gender of the spouse ('M' or 'F')
     * @param {string} srcId - Source sheet identifier
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {Object} Resolved spouse node
     *
     * @example
     * this._resolveAndLinkSpouse(sibNode, 'Antu Wife', 'F', srcId, ws);
     * // => Spouse node partnered with sibNode
     *
     * @example
     * this._resolveAndLinkSpouse(null, 'Single Ghost Wife', 'F', srcId, ws);
     * // => Created standalone spouse ghost appended to ws.newNodes
     */
    _resolveAndLinkSpouse(primaryNode, spouseName, spouseGender, srcId, ws) {
        let spNode = ws.find(spouseName);
        if (!spNode) {
            spNode = ws.create(spouseName, spouseGender, { srcId });
            if (primaryNode) spNode.spouse = primaryNode.name;
        }
        FamilyTreeBuilder._linkMutualPartners(primaryNode, spNode);
        return spNode;
    }

    /**
     * Links a child node to an intermediate parent node and its auto-generated spouse,
     * assigning mom and father properties and updating children arrays.
     * 
     * @param {Object} childNode - Subject child node
     * @param {Object} parentNode - Intermediate parent node
     * @param {boolean} isParentFemale - Whether intermediate parent is female
     * @param {string} srcId - Source sheet ID
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {Object} Created or resolved spouse node of parentNode
     *
     * @example
     * builder._linkChildToParentCouple(grandchild, sonNode, false, srcId, ws);
     * // => Sets grandchild.father = sonNode.name, grandchild.mom = 'Son Wife', links children
     *
     * @example
     * builder._linkChildToParentCouple(grandchild, daughterNode, true, srcId, ws);
     * // => Sets grandchild.mom = daughterNode.name, grandchild.father = 'Daughter Husband', links children
     */
    _linkChildToParentCouple(childNode, parentNode, isParentFemale, srcId, ws) {
        const spouseName = `${parentNode.name} ${isParentFemale ? 'Husband' : 'Wife'}`;
        const spouseNode = this._resolveAndLinkSpouse(parentNode, spouseName, isParentFemale ? 'M' : 'F', srcId, ws);

        childNode.mom = isParentFemale ? parentNode.name : spouseName;
        childNode.father = isParentFemale ? spouseName : parentNode.name;

        FamilyTreeBuilder._addChildIdToParent(parentNode, childNode.id);
        FamilyTreeBuilder._addChildIdToParent(spouseNode, childNode.id);

        return spouseNode;
    }

    /**
     * Expands [Sibling, Child] compounds (e.g. "Kunjagaasthi Brother Daughter 3", "Mary Brother Daughter").
     *
     * @param {Object} n - Declaring child node
     * @param {Object} ctx - Multi-level resolution context
     *
     * @example
     * builder._expandSiblingChildCompound({ name: 'Mary Brother Daughter 1' }, ctx);
     * // => Resolves 'Mary Brother 1', creates spouse couple, and sets as parents of declaring child
     *
     * @example
     * builder._expandSiblingChildCompound({ name: 'George Sister Son' }, ctx);
     * // => Resolves 'George Sister', generates couple, and attaches child to the couple
     */
    _expandSiblingChildCompound(n, ctx) {
        const { anchorNode, anchorName, srcId, baseName, r1, n1, r2, ws } = ctx;
        const sibRole = r1.charAt(0).toUpperCase() + r1.slice(1);
        const isSister = (r1 === 'sister' || r1 === 'sis');
        const isChildDaughter = (r2 === 'daughter' || r2 === 'girl');
        const sibName = n1 !== null ? `${anchorName} ${sibRole} ${n1}` : `${anchorName} ${sibRole}`;

        if (!n.gender) n.gender = isChildDaughter ? 'F' : 'M';

        const { targetMom, targetDad } =
            this._setupSiblingParentGhosts(anchorNode, anchorName || baseName, srcId, ws);

        const sibNode = ws.resolveOrCreate(sibName, isSister ? 'F' : 'M', { mom: targetMom, dad: targetDad, srcId });

        this._linkChildToParentCouple(n, sibNode, isSister, srcId, ws);
    }

    /**
     * Expands [Child, Child] compounds (e.g. "George Son 1 Daughter 1").
     *
     * @param {Object} n - Declaring grandchild node
     * @param {Object} ctx - Multi-level context
     *
     * @example
     * builder._expandChildChildCompound({ name: 'George Son 1 Daughter 1' }, ctx);
     * // => Creates 'George Son 1', links to George, and attaches grandchild to couple
     *
     * @example
     * builder._expandChildChildCompound({ name: 'Rosy Daughter 2 Son 1' }, ctx);
     * // => Creates 'Rosy Daughter 2', links to Rosy, and establishes grandchild parentage
     */
    _expandChildChildCompound(n, ctx) {
        const { anchorName, srcId, isAnchorFemale, r1, n1, r2, ws } = ctx;
        const child1Role = r1.charAt(0).toUpperCase() + r1.slice(1);
        const isChild1Daughter = (r1 === 'daughter' || r1 === 'girl');
        const isChild2Daughter = (r2 === 'daughter' || r2 === 'girl');
        const child1Name = n1 !== null ? `${anchorName} ${child1Role} ${n1}` : `${anchorName} ${child1Role}`;

        if (!n.gender) n.gender = isChild2Daughter ? 'F' : 'M';

        const { targetSpouse: targetAnchorSpouse, parentMom, parentDad } =
            FamilyTreeBuilder._deduceAnchorSpouseAndParents(anchorName, isAnchorFemale);

        if (!ws.find(targetAnchorSpouse)) {
            ws.create(targetAnchorSpouse, isAnchorFemale ? 'M' : 'F', { srcId }).spouse = anchorName;
        }

        const child1Node =
            ws.resolveOrCreate(child1Name, isChild1Daughter ? 'F' : 'M', { mom: parentMom, dad: parentDad, srcId });

        this._linkChildToParentCouple(n, child1Node, isChild1Daughter, srcId, ws);
    }

    /**
     * Expands [Parent, Spouse] compounds (e.g. "Annamma Father Wife 2", "Mary Mother Husband").
     *
     * @param {Object} n - Declaring spouse node
     * @param {Object} ctx - Multi-level context
     *
     * @example
     * builder._expandParentSpouseCompound({ name: 'Annamma Father Wife 2' }, ctx);
     * // => Creates 'Annamma Father' and links declaring node as spouse
     *
     * @example
     * builder._expandParentSpouseCompound({ name: 'Mary Mother Husband' }, ctx);
     * // => Resolves 'Mary Mother' and links declaring husband to her
     */
    _expandParentSpouseCompound(n, ctx) {
        const { anchorNode, anchorName, srcId, r1, ws } = ctx;
        const isParentMom = (r1 === 'mother' || r1 === 'mom');
        const pRole = isParentMom ? 'Mother' : 'Father';
        const pName = `${anchorName} ${pRole}`;

        if (!n.gender) n.gender = isParentMom ? 'M' : 'F';

        const pNode = ws.resolveOrCreate(pName, isParentMom ? 'F' : 'M', { srcId });

        if (anchorNode) {
            if (isParentMom && !anchorNode.mom) anchorNode.mom = pName;
            else if (!isParentMom && !anchorNode.father) anchorNode.father = pName;
        }

        n.spouse = pName;
        FamilyTreeBuilder._linkMutualPartners(pNode, n);
    }

    /**
     * Expands [Spouse, Parent] compounds (e.g. "Rosy Husband Father", "George Wife Mother").
     *
     * @param {Object} n - Declaring in-law parent node
     * @param {Object} ctx - Multi-level resolution context
     *
     * @example
     * builder._expandSpouseParentCompound({ name: 'Rosy Husband Father' }, ctx);
     * // => Resolves 'Rosy Husband', creates co-parent 'Rosy Husband Mother', and links parentage
     *
     * @example
     * builder._expandSpouseParentCompound({ name: 'George Wife Mother' }, ctx);
     * // => Resolves 'George Wife', creates co-parent 'George Wife Father', and links declaring mother
     */
    _expandSpouseParentCompound(n, ctx) {
        const { anchorNode, anchorName, srcId, r1, r2, ws } = ctx;
        const isAnchorSpouseHusband = (r1 === 'husband' || r1 === 'hus');
        const spRole = isAnchorSpouseHusband ? 'Husband' : 'Wife';
        const spName = `${anchorName} ${spRole}`;

        const isParentMother = (r2 === 'mother' || r2 === 'mom');
        if (!n.gender) n.gender = isParentMother ? 'F' : 'M';

        const spNode = this._resolveAndLinkSpouse(anchorNode, spName, isAnchorSpouseHusband ? 'M' : 'F', srcId, ws);

        const coParentRole = isParentMother ? 'Father' : 'Mother';
        const coParentName = `${spName} ${coParentRole}`;
        const coParentNode = ws.resolveOrCreate(coParentName, isParentMother ? 'M' : 'F', { srcId });

        if (isParentMother) {
            spNode.mom = n.name;
            spNode.father = coParentName;
        } else {
            spNode.father = n.name;
            spNode.mom = coParentName;
        }

        FamilyTreeBuilder._addChildIdToParent(n, spNode.id);
        FamilyTreeBuilder._addChildIdToParent(coParentNode, spNode.id);
    }

    /**
     * Evaluates co-parent compatibility between candidate parent and reference child node.
     *
     * @param {Object} cand - Candidate parent node
     * @param {Object} childNode - Referencing child node
     * @returns {number} 1 if candidate spouse matches child's other parent, -1 if conflicting, 0 if neutral
     *
     * @example
     * FamilyTreeBuilder._computeCoParentMatchScore({ spouse: 'Annie' }, { mom: 'Annie' });
     * // => 1
     *
     * @example
     * FamilyTreeBuilder._computeCoParentMatchScore({ spouse: 'Ammini' }, { mom: 'Annie' });
     * // => -1
     */
    static _computeCoParentMatchScore(cand, childNode) {
        if (!cand || !childNode) return 0;
        if (childNode.name && /(?:Husband|Wife)/i.test(childNode.name)) return 0;
        const candPartners = [
            cand.spouse,
            ...(cand.partners || []).map(p => (typeof p === 'string' ? p : p?.name))
        ].filter(Boolean).map(s => s.toLowerCase().trim());
        if (candPartners.length === 0) return 0;

        const candNorm = (cand.name || '').toLowerCase().trim();
        let otherParent = null;
        if (childNode.father && FamilyTreeBuilder._namesOverlap(candNorm, childNode.father.toLowerCase().trim())) {
            otherParent = childNode.mom;
        } else if (childNode.mom && FamilyTreeBuilder._namesOverlap(candNorm, childNode.mom.toLowerCase().trim())) {
            otherParent = childNode.father;
        } else {
            const isCandFemale = cand.gender === 'F' || FamilyTreeBuilder._isFemaleName(cand.name);
            otherParent = isCandFemale ? childNode.father : childNode.mom;
        }
        if (!otherParent) return 0;

        const otherNorm = otherParent.toLowerCase().trim();
        const otherFolded = FamilyTreeBuilder.foldPhonetic(otherNorm);
        const hasMatch = candPartners.some(p =>
            FamilyTreeBuilder._namesOverlap(p, otherNorm) || FamilyTreeBuilder.foldPhonetic(p) === otherFolded
        );
        return hasMatch ? 1 : -1;
    }

    /**
     * Calculates ranking score for a candidate anchor node relative to referencing node.
     *
     * @param {Object} cand - Candidate anchor node
     * @param {Object} currentNode - Referencing node
     * @param {number|null} targetYob - Expected birth year (~25 years before currentNode)
     * @returns {number} Relative fit score (higher is better)
     *
     * @example
     * FamilyTreeBuilder._computeAnchorCandidateScore(adultAnchorSameSheet, childNode, 1920);
     * // => 120 (bonus for adult + same sheet - row penalty)
     *
     * @example
     * FamilyTreeBuilder._computeAnchorCandidateScore({ yob: 1910 }, { yob: 1945 }, 1920);
     * // => Score penalized by absolute difference between candidate yob and target yob
     */
    static _computeAnchorCandidateScore(cand, currentNode, targetYob) {
        let score = 0;
        const cYob = FamilyTreeBuilder._effectiveYob(cand) || null;
        if (targetYob) {
            score -= cYob ? Math.abs(cYob - targetYob) : 50;
        }
        const isAdult = Boolean(cand.spouse || (cand.partners && cand.partners.length > 0) || (cand.children && cand.children.length > 0));
        if (isAdult) score += 100;
        if (FamilyTreeBuilder.sharesSheet(cand, currentNode)) score += 20;
        const coScore = FamilyTreeBuilder._computeCoParentMatchScore(cand, currentNode);
        if (coScore > 0) score += 500;
        else if (coScore < 0) score -= 500;
        const dist = FamilyTreeBuilder._getMinRowDistance(cand, currentNode);
        if (dist < FamilyTreeBuilder.CROSS_SHEET_DISTANCE) score -= Math.min(dist, 50);
        return score;
    }

    /**
     * Filters a list of nodes to those phonetically or nominally matching the target anchor name and generation bounds.
     *
     * @param {string} name - Target anchor name to match
     * @param {Object} currentNode - Referencing node
     * @param {Object[]} pool - List of candidate nodes
     * @returns {Object[]} Matching viable candidate nodes
     *
     * @example
     * FamilyTreeBuilder._filterAnchorCandidates('Joseph', childNode, allNodes);
     * // => [nodeJoseph]
     *
     * @example
     * FamilyTreeBuilder._filterAnchorCandidates('UnknownName', childNode, allNodes);
     * // => []
     */
    static _filterAnchorCandidates(name, currentNode, pool) {
        if (!name) return [];
        const lowerName = name.toLowerCase().trim();
        const targetPhonetic = FamilyTreeBuilder.foldPhonetic(lowerName);
        const curYob = FamilyTreeBuilder._effectiveYob(currentNode);

        return pool.filter(n => {
            if (n._normName !== lowerName && FamilyTreeBuilder.foldPhonetic(n.name) !== targetPhonetic) return false;
            if (currentNode.spouse && (n.mom === currentNode.spouse || n.father === currentNode.spouse)) return false;
            if (n.mom === currentNode.name || n.father === currentNode.name) return false;
            const cYob = FamilyTreeBuilder._effectiveYob(n);
            if (cYob && curYob && cYob > curYob + 15) return false;
            return true;
        });
    }

    /**
     * Identifies the optimal anchor parent node by filtering candidates and ranking by fit score.
     *
     * @param {string} name - Anchor parent name to search
     * @param {Object} currentNode - Context node referencing the anchor
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {Object|null} Best matching anchor node or null
     *
     * @example
     * builder._findAnchorNode('Antu', childNode, ws);
     * // => Person node matching 'Antu' with highest candidate score
     *
     * @example
     * builder._findAnchorNode('NonExistent', childNode, ws);
     * // => null
     */
    _findAnchorNode(name, currentNode, ws) {
        let cands = FamilyTreeBuilder._filterAnchorCandidates(name, currentNode, ws.pool);
        if (cands.length === 0) return null;

        // When candidates exist on the same spreadsheet as the referencing node, prioritize local sheet candidates
        const sameSheetCands = cands.filter(c => FamilyTreeBuilder.sharesSheet(c, currentNode));
        if (sameSheetCands.length > 0) {
            cands = sameSheetCands;
        }

        const curYob = FamilyTreeBuilder._effectiveYob(currentNode);
        const targetYob = curYob ? curYob - 25 : null;

        cands.sort((a, b) => {
            const scoreA = FamilyTreeBuilder._computeAnchorCandidateScore(a, currentNode, targetYob);
            const scoreB = FamilyTreeBuilder._computeAnchorCandidateScore(b, currentNode, targetYob);
            return scoreB - scoreA;
        });

        return cands[0];
    }

    /**
     * Constructs a synthetic ghost person record for relative or numbered child expansion.
     * 
     * @param {string} name - Profile display name
     * @param {string} gender - Gender code ('M' or 'F')
     * @param {string} mom - Mother display name
     * @param {string} father - Father display name
     * @param {string} sourceId - Origin sheet identifier
     * @param {number} sequenceIndex - Disambiguating sequence counter
     * @returns {Object} Domain Person ghost record
     *
     * @example
     * FamilyTreeBuilder._buildGhostPersonRecord('Mary Sister', 'F', 'Mom', 'Dad', 's1', 0);
     * // => { id: 'ghost_Mary_Sister_0', isGhost: true, gender: 'F', mom: 'Mom', father: 'Dad', ... }
     *
     * @example
     * FamilyTreeBuilder._buildGhostPersonRecord('John Mother', 'F', '', '', 's1', 1);
     * // => { id: 'ghost_John_Mother_1', _isSyntheticSiblingParent: true, ... }
     */
    static _buildGhostPersonRecord(name, gender, mom, father, sourceId, sequenceIndex) {
        return {
            _rawId: `ghost_${name.replace(/\s+/g, '_')}_${sequenceIndex}`,
            _isSyntheticSiblingParent: Boolean(name.endsWith(' Mother') || name.endsWith(' Father')),
            _sourceId: sourceId,
            _sourceIds: new Set([sourceId]),
            id: `ghost_${name.replace(/\s+/g, '_')}_${sequenceIndex}`,
            name: name,
            _normName: name.toLowerCase().trim(),
            gender: gender,
            isGhost: true,
            mom: mom || '',
            father: father || '',
            partners: [], children: [], ambiguities: []
        };
    }

    /**
     * Resolves a person by name from a candidate pool with vowel-folding and phonetic matching,
     * preferring candidates on the same sheet with closest row proximity.
     * 
     * @param {string} name - Name to resolve
     * @param {Object|null} contextNode - Context node for sheet proximity
     * @param {Object[]} candidatePool - Array of person nodes to search
     * @returns {Object|null} Matching person node, or null
     *
     * @example
     * FamilyTreeBuilder._findCandidateByNameAndProximity('John', null, [p1]);
     * // => p1
     *
     * @example
     * FamilyTreeBuilder._findCandidateByNameAndProximity('Unknown', null, [p1]);
     * // => null
     */
    static _findCandidateByNameAndProximity(name, contextNode, candidatePool) {
        if (!name) return null;
        const lower = name.toLowerCase().trim();
        const targetFolded = FamilyTreeBuilder.foldVowels(lower);
        const targetPhonetic = FamilyTreeBuilder.foldPhonetic(lower);
        const matches = candidatePool.filter(n =>
            n._normName === lower ||
            FamilyTreeBuilder.foldVowels(n.name) === targetFolded ||
            FamilyTreeBuilder.foldPhonetic(n.name) === targetPhonetic
        );
        if (matches.length === 0) return null;
        if (matches.length === 1 || !contextNode) return matches[0];
        const sameSheet = matches.filter(m => FamilyTreeBuilder.sharesSheet(m, contextNode));
        if (sameSheet.length > 0) {
            sameSheet.sort((a, b) => FamilyTreeBuilder._getMinRowDistance(a, contextNode) - FamilyTreeBuilder._getMinRowDistance(b, contextNode));
            return sameSheet[0];
        }
        return matches[0];
    }

    /**
     * Expands relative references in parental fields (such as "Anthony Sister" or "Babu Brother")
     * into synthetic ghost person records and shared synthetic parent placeholders.
     * 
     * @param {Object[]} nodes - List of domain nodes
     * 
     * @example
     * builder.expandRelativeReferences([childWithSisterMother]);
     * // => Generates ghost profiles: "Anthony Sister", "Anthony Mother", "Anthony Father"
     *
     * @example
     * builder.expandRelativeReferences(nodes);
     * // => Expands sibling parent references, multi-level compounds, and missing numbered children
     */
    expandRelativeReferences(nodes) {
        // One workspace carries the node pool, the ghost accumulator, and the
        // lookup/factory strategies through all three expansion stages below.
        const ws = new GhostWorkspace(
            nodes,
            (name, contextNode, pool) =>
                FamilyTreeBuilder._findCandidateByNameAndProximity(name, contextNode, pool),
            (name, gender, mom, father, sourceId, sequenceIndex) =>
                FamilyTreeBuilder._buildGhostPersonRecord(name, gender, mom, father, sourceId, sequenceIndex)
        );

        this._expandSiblingParentReferences(ws);
        this._expandMultiLevelRelatives(ws);
        this._expandMissingNumberedChildren(ws);
        this._indexNewNodes(nodes, ws.newNodes);
    }

    /**
     * Resolves an anchor node's known spouse from explicit spouse fields, partners, or adjacent sheet rows.
     *
     * @param {Object} anchorNode - The parent anchor profile
     * @param {string} anchorName - Cleaned name of the anchor
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * @returns {Object|null} Matching spouse node if found
     *
     * @example
     * builder._findKnownSpouseNode(antuNode, 'Antu', ws);
     * // => Person node representing spouse of Antu
     *
     * @example
     * builder._findKnownSpouseNode(null, 'Unknown', ws);
     * // => null
     */
    _findKnownSpouseNode(anchorNode, anchorName, ws) {
        if (!anchorNode) return null;
        if (anchorNode.spouse) {
            const sp = ws.find(anchorNode.spouse, anchorNode);
            if (sp) return sp;
        }
        if (anchorNode.partners && anchorNode.partners.length > 0) {
            const p = this.nodeMap[anchorNode.partners[0]] || ws.find(anchorNode.partners[0], anchorNode);
            if (p) return p;
        }
        return ws.nodes.find(o => 
            o.spouse && 
            o.spouse.toLowerCase().trim() === anchorName.toLowerCase().trim() && 
            FamilyTreeBuilder.sharesSheet(o, anchorNode) && 
            FamilyTreeBuilder._getMinRowDistance(o, anchorNode) <= 3
        ) || null;
    }

    /**
     * Checks if a candidate node matches a vowel-folded anchor parent name via father, mom, or name prefix.
     *
     * @param {Object} node - Candidate node to check
     * @param {string} anchorFolded - Vowel-folded anchor parent name
     * @returns {boolean} True if candidate's parents or prefix match the anchor
     *
     * @example
     * FamilyTreeBuilder._matchesAnchorParent({ father: 'Raphael' }, 'rphl');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._matchesAnchorParent({ name: 'Raphael Son 1' }, 'rphl');
     * // => true
     */
    static _matchesAnchorParent(node, anchorFolded) {
        if (!node || !anchorFolded) return false;
        return Boolean(
            (node.father && FamilyTreeBuilder.foldVowels(node.father) === anchorFolded) ||
            (node.mom && FamilyTreeBuilder.foldVowels(node.mom) === anchorFolded) ||
            (node.name && FamilyTreeBuilder.foldVowels(node.name).startsWith(anchorFolded + ' '))
        );
    }

    /**
     * Finds preceding siblings on the same sheet belonging to the same anchor parent.
     *
     * @param {Object[]} nodes - All candidate nodes
     * @param {Object} anchorNode - Anchor parent node
     * @param {string} anchorName - Name of the anchor parent
     * @param {Object} n - Current node containing the numbered child reference
     * @param {number|null} nRow - Row number of node n
     * @returns {Object[]} Preceding siblings on the sheet sorted by row order
     *
     * @example
     * builder._findPrecedingSheetSiblings(nodes, anchorNode, 'Antu', childNode, 15);
     * // => Sibling nodes on the same sheet with row < 15 matching 'Antu'
     *
     * @example
     * builder._findPrecedingSheetSiblings(nodes, anchorNode, 'Antu', childNode, null);
     * // => []
     */
    _findPrecedingSheetSiblings(nodes, anchorNode, anchorName, n, nRow) {
        if (nRow === null) return [];
        const anchorFolded = FamilyTreeBuilder.foldVowels(anchorName);
        return nodes.filter(o => {
            if (o === n || o === anchorNode) return false;
            if (!FamilyTreeBuilder.sharesSheet(o, n)) return false;
            const r = FamilyTreeBuilder.getNodeSheetRow(o, null);
            if (r === null || r >= nRow) return false;
            if (n.mom && o.mom && FamilyTreeBuilder.foldPhonetic(n.mom) !== FamilyTreeBuilder.foldPhonetic(o.mom) && !FamilyTreeBuilder._namesOverlap(n.mom.toLowerCase().trim(), o.mom.toLowerCase().trim())) return false;
            return FamilyTreeBuilder._matchesAnchorParent(o, anchorFolded);
        }).sort((a, b) => FamilyTreeBuilder.getNodeSheetRow(a, 0) - FamilyTreeBuilder.getNodeSheetRow(b, 0));
    }

    /**
     * Checks if a sibling profile or node matches the target sibling gender role (daughter vs son).
     * Evaluates explicit gender, spouse indicators ('wife'/'husband'), cross-referenced spouse nodes,
     * and female-specific name endings with male-exception guards.
     *
     * @param {Object} s - Sibling profile or node to check
     * @param {boolean} isDaughter - True if matching female/daughter, false for male/son
     * @param {Object[]} [nodes=[]] - Context nodes for spouse cross-referencing
     * @returns {boolean} True if sibling matches the target gender role
     *
     * @example
     * FamilyTreeBuilder._matchesSiblingGenderRole({ gender: 'F' }, true);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._matchesSiblingGenderRole({ name: 'Mary', gender: null }, true);
     * // => true
     */
    static _matchesSiblingGenderRole(s, isDaughter, nodes = []) {
        if (!s) return false;
        const targetGender = isDaughter ? 'F' : 'M';
        if (s.gender === targetGender) return true;

        const targetSpouseType = isDaughter ? 'wife' : 'husband';
        const spouseProp = isDaughter ? s.husband : s.wife;
        if (s.spouseType === targetSpouseType || spouseProp) return true;

        const lowerName = (s._normName || s.name || '').toLowerCase();
        const oppositeSpouseRole = isDaughter ? ' husband' : ' wife';
        if (nodes && nodes.some(o => o.name && o.name.toLowerCase() === lowerName + oppositeSpouseRole)) return true;

        if (isDaughter) {
            if (!FamilyTreeBuilder._isMaleName(s.name) && lowerName.split(/\s+/).some(t => /(?:amma|mol|mary)$/i.test(t))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Filters a list of siblings to those matching the target gender role (daughter vs son).
     *
     * @param {Object[]} siblings - List of sibling profiles
     * @param {boolean} isDaughter - Whether looking for female/daughter siblings
     * @param {Object[]} nodes - All domain nodes for cross-reference
     * @returns {Object[]} Sibling profiles matching the gender role
     *
     * @example
     * builder._filterSiblingsByGenderRole([sisterNode, brotherNode], true, nodes);
     * // => [sisterNode]
     *
     * @example
     * builder._filterSiblingsByGenderRole([sisterNode, brotherNode], false, nodes);
     * // => [brotherNode]
     */
    _filterSiblingsByGenderRole(siblings, isDaughter, nodes) {
        return (siblings || []).filter(s => FamilyTreeBuilder._matchesSiblingGenderRole(s, isDaughter, nodes));
    }

    /**
     * Computes an effective row number for an interpolated numbered child between preceding siblings and the reference node.
     *
     * @param {number} i - Current child index (1-based)
     * @param {number} num - Total number in reference (e.g. 3 in "Antu Daughter 3")
     * @param {number} nRow - Row number of the reference node
     * @param {Object[]} sheetSiblings - Array of preceding siblings on the sheet
     * @returns {number} Interpolated effective row number
     *
     * @example
     * builder._calculateInterpolatedChildRow(1, 3, 14, [{ _sheetRow: 12 }]);
     * // => 11.5 (first child interpolated before preceding sibling)
     *
     * @example
     * builder._calculateInterpolatedChildRow(2, 3, 20, []);
     * // => 19.0 (linear step back from reference row when no preceding siblings)
     */
    _calculateInterpolatedChildRow(i, num, nRow, sheetSiblings) {
        if (i === 1 && sheetSiblings.length > 0) {
            const firstSibRow = FamilyTreeBuilder.getNodeSheetRow(sheetSiblings[0], 0);
            return firstSibRow - 0.5;
        } else if (sheetSiblings.length > 0) {
            const lastSibRow = FamilyTreeBuilder.getNodeSheetRow(sheetSiblings[sheetSiblings.length - 1], 0);
            return lastSibRow + (nRow - lastSibRow) * (i / num);
        } else {
            return nRow - (num - i) * 1.0;
        }
    }

    /**
     * Deduces mother and father display names for an intermediate numbered child ghost.
     * 
     * @param {string} anchorName - Display name of the anchor parent
     * @param {boolean} isAnchorFemale - Whether anchor parent is female
     * @param {string|null} knownSpouseName - Display name of the known spouse, if any
     * @returns {{ parentMom: string, parentDad: string }} Deduced parent names
     *
     * @example
     * FamilyTreeBuilder._deduceParentNamesForChild('Mary', true, 'John');
     * // => { parentMom: 'Mary', parentDad: 'John' }
     *
     * @example
     * FamilyTreeBuilder._deduceParentNamesForChild('Paul', false, null);
     * // => { parentMom: '', parentDad: 'Paul' }
     */
    static _deduceParentNamesForChild(anchorName, isAnchorFemale, knownSpouseName) {
        const { parentMom, parentDad } = FamilyTreeBuilder._deduceAnchorSpouseAndParents(anchorName, isAnchorFemale, knownSpouseName, false);
        return { parentMom, parentDad };
    }

    /**
     * Points a freshly synthesized ghost child at its anchor parent and, when known, that
     * parent's spouse — so the ghost is attached to the couple rather than dangling.
     *
     * The anchor's role is inferred rather than assumed: an explicitly female anchor becomes the
     * mother, an explicitly male anchor (by gender or by being recorded as a husband) becomes the
     * father, and an anchor of indeterminate gender is deliberately left unlinked so that later
     * gender-inference passes are free to decide without fighting a premature guess.
     *
     * @param {Object} cNode - Ghost child node being attached
     * @param {Object|null} anchorNode - Anchor parent node, if one was resolved
     * @param {boolean} [isAnchorFemale] - Whether the anchor parent is known to be female
     * @param {Object|null} [knownSpouseNode] - Anchor's spouse node, if already resolved
     * @returns {void}
     *
     * @example
     * FamilyTreeBuilder._linkGhostChildToAnchorCouple(ghost, motherNode, true, fatherNode);
     * // => ghost.momId === motherNode.id and ghost.fatherId === fatherNode.id
     *
     * @example
     * FamilyTreeBuilder._linkGhostChildToAnchorCouple(ghost, null, false, null);
     * // => ghost is left untouched (no anchor to attach to)
     */
    static _linkGhostChildToAnchorCouple(cNode, anchorNode, isAnchorFemale, knownSpouseNode) {
        if (!anchorNode) return;

        cNode._namedParentId = anchorNode.id;
        cNode._namedParentName = anchorNode.name;

        if (isAnchorFemale) {
            cNode.momId = anchorNode.id;
            if (knownSpouseNode) cNode.fatherId = knownSpouseNode.id;
            return;
        }

        const isAnchorMale = anchorNode.gender === 'M' || anchorNode.spouseType === 'husband';
        if (isAnchorMale) {
            cNode.fatherId = anchorNode.id;
            if (knownSpouseNode) cNode.momId = knownSpouseNode.id;
        }
    }

    /**
     * Synthesizes missing intermediate numbered ghost child profiles between existing siblings and target index.
     * 
     * @param {Object} params - Parameter configuration object
     * @param {number} params.startIdx - Starting child index (1-based)
     * @param {number} params.num - Target child index
     * @param {string} params.anchorName - Display name of the anchor parent
     * @param {string} params.childRole - Role string ('Son', 'Daughter', etc.)
     * @param {boolean} params.isDaughter - Whether child is female
     * @param {string} params.parentMom - Display name of mother
     * @param {string} params.parentDad - Display name of father
     * @param {string} params.srcId - Source sheet identifier
     * @param {number|null} params.nRow - Sheet row of the triggering child node
     * @param {Object[]} params.sheetSiblings - Preceding siblings on the same sheet
     * @param {Object|null} params.anchorNode - Anchor parent node
     * @param {boolean} [params.isAnchorFemale] - Whether anchor parent is female
     * @param {Object|null} [params.knownSpouseNode] - Anchor's known spouse node
     * @param {GhostWorkspace} params.ws - Shared ghost-synthesis workspace
     * @param {FamilyTreeBuilder} builder - Tree builder instance for row interpolation
     *
     * @example
     * FamilyTreeBuilder._synthesizeMissingIntermediateGhosts({
     *   startIdx: 2, num: 4, anchorName: 'Mary', childRole: 'Son', isDaughter: false,
     *   parentMom: 'Mary', parentDad: 'John', srcId: 's1', nRow: 10, sheetSiblings: [],
     *   anchorNode: null, ws
     * }, builder);
     * // => Synthesizes 'Mary Son 2' and 'Mary Son 3' ghost records into ws.newNodes
     *
     * @example
     * FamilyTreeBuilder._synthesizeMissingIntermediateGhosts({
     *   startIdx: 1, num: 2, anchorName: 'Rosa', childRole: 'Daughter', isDaughter: true,
     *   parentMom: 'Rosa', parentDad: '', srcId: 's2', nRow: null, sheetSiblings: [],
     *   anchorNode: null, ws
     * }, builder);
     * // => Synthesizes 'Rosa Daughter 1' ghost into ws.newNodes without sheet row assignment
     */
    static _synthesizeMissingIntermediateGhosts(params, builder) {
        const {
            startIdx, num, anchorName, childRole, isDaughter, parentMom, parentDad,
            srcId, nRow, sheetSiblings, anchorNode, isAnchorFemale, knownSpouseNode, ws
        } = params;
        for (let i = startIdx; i < num; i++) {
            const cName = `${anchorName} ${childRole} ${i}`;
            let cNode = ws.find(cName, anchorNode);
            if (!cNode) {
                cNode = ws.create(cName, isDaughter ? 'F' : 'M', { mom: parentMom, dad: parentDad, srcId });
                FamilyTreeBuilder._linkGhostChildToAnchorCouple(cNode, anchorNode, isAnchorFemale, knownSpouseNode);
            }
            // Space the synthesized siblings evenly between the anchor and the triggering child so
            // later row-proximity reasoning sees a plausible birth order.
            if (!cNode._sheetRows && nRow !== null) {
                const effRow = builder._calculateInterpolatedChildRow(i, num, nRow, sheetSiblings);
                cNode._sheetRows = { [srcId]: effRow };
                cNode._sheetRow = effRow;
            }
        }
    }

    /**
     * Expands missing intermediate numbered child references for a specific node and anchor parent.
     * 
     * @param {Object} n - Triggering numbered child node
     * @param {string} baseName - Base name of anchor parent
     * @param {string} role - Sibling role ('daughter', 'son', etc.)
     * @param {number} num - Target sibling index (e.g. 3 for 'Mary Son 3')
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     * 
     * @example
     * builder._expandIntermediateChildrenForNode({ name: 'Mary Son 3' }, 'Mary', 'son', 3, ws);
     * // => Synthesizes missing intermediate ghosts 'Mary Son 1' and 'Mary Son 2'
     *
     * @example
     * builder._expandIntermediateChildrenForNode({ name: 'Paul Daughter 2' }, 'Paul', 'daughter', 2, ws);
     * // => Synthesizes 'Paul Daughter 1' linked to Paul and partner
     */
    _expandIntermediateChildrenForNode(n, baseName, role, num, ws) {
        const anchorNode = this._findAnchorNode(baseName, n, ws);
        const anchorName = anchorNode ? anchorNode.name : baseName;
        const srcId = anchorNode ? (anchorNode._sourceId || n._sourceId) : n._sourceId;
        const isAnchorFemale = anchorNode ? (anchorNode.gender === 'F' || anchorNode.spouseType === 'wife') : false;

        const knownSpouseNode = this._findKnownSpouseNode(anchorNode, anchorName, ws);
        const knownSpouseName = knownSpouseNode ? knownSpouseNode.name : null;

        const childRole = role.charAt(0).toUpperCase() + role.slice(1);
        const isDaughter = (role === 'daughter' || role === 'girl');
        const { parentMom, parentDad } = FamilyTreeBuilder._deduceParentNamesForChild(anchorName, isAnchorFemale, knownSpouseName);

        const nRow = FamilyTreeBuilder.getNodeSheetRow(n, null);
        const sheetSiblings = this._findPrecedingSheetSiblings(ws.nodes, anchorNode, anchorName, n, nRow);
        const existingMatchingSiblings = this._filterSiblingsByGenderRole(sheetSiblings, isDaughter, ws.nodes);

        existingMatchingSiblings.forEach((s, idx) => {
            if (!s._nameChildNumber) s._nameChildNumber = idx + 1;
        });

        const startIdx = existingMatchingSiblings.length + 1;
        FamilyTreeBuilder._synthesizeMissingIntermediateGhosts({
            startIdx, num, anchorName, childRole, isDaughter, parentMom, parentDad,
            srcId, nRow, sheetSiblings, anchorNode, isAnchorFemale, knownSpouseNode, ws
        }, this);
    }

    /**
     * Expands missing intermediate numbered child references into ghost profiles.
     * For example, "Antu Daughter 3" generates "Antu Daughter 1" and "Antu Daughter 2"
     * if they do not already exist, positioned chronologically with interpolated sheet rows.
     *
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     *
     * @example
     * builder._expandMissingNumberedChildren(ws); // ws.nodes = [{ name: 'Antu Daughter 3' }]
     * // => Generates ghost "Antu Daughter 1" and "Antu Daughter 2" with interpolated sheet rows
     *
     * @example
     * builder._expandMissingNumberedChildren(ws); // ws.nodes = [{ name: 'George Son 1' }]
     * // => No additional numbered children generated for index 1
     */
    _expandMissingNumberedChildren(ws) {
        const childWordsPattern = '(?:Daughter|Dau|Son|Girl|Boy)';
        const singleChildRegex = new RegExp(`^(.+?)\\s+(${childWordsPattern})\\s*(\\d+)$`, 'i');

        ws.nodes.forEach(n => {
            if (!n.name) return;
            const normalizedName = FamilyTreeBuilder._normalizeRelativeCompoundName(n.name);
            const sm = normalizedName.match(singleChildRegex);
            if (!sm) return;

            const baseName = sm[1].trim();
            const role = sm[2].toLowerCase();
            const num = parseInt(sm[3], 10);
            if (num < 2) return;

            this._expandIntermediateChildrenForNode(n, baseName, role, num, ws);
        });
    }

    /**
     * Determines the target mother and father names for a sibling reference,
     * registering synthetic parent names when parents are not yet recorded on the anchor node.
     *
     * @param {Object|null} anchorNode - Biological sibling anchor node
     * @param {string} baseName - Base name of the sibling reference
     * @returns {{ targetMom: string, targetDad: string }} Resolved target parent names
     *
     * @example
     * this._resolveTargetSiblingParents(anchorNode, 'Rosa');
     * // => { targetMom: 'Rosa Mother', targetDad: 'Rosa Father' }
     *
     * @example
     * this._resolveTargetSiblingParents(null, 'Paul');
     * // => { targetMom: 'Paul Mother', targetDad: 'Paul Father' }
     */
    _resolveTargetSiblingParents(anchorNode, baseName) {
        const targetMom = anchorNode ? (anchorNode.mom || `${anchorNode.name} Mother`) : `${baseName} Mother`;
        const targetDad = anchorNode ? (anchorNode.father || `${anchorNode.name} Father`) : `${baseName} Father`;
        this.syntheticSiblingParentNames = this.syntheticSiblingParentNames || new Set();
        if (!anchorNode || !anchorNode.mom) this.syntheticSiblingParentNames.add(targetMom.toLowerCase().trim());
        if (!anchorNode || !anchorNode.father) this.syntheticSiblingParentNames.add(targetDad.toLowerCase().trim());
        if (anchorNode) {
            if (!anchorNode.mom) anchorNode.mom = targetMom;
            if (!anchorNode.father) anchorNode.father = targetDad;
        }
        return { targetMom, targetDad };
    }

    /**
     * Retrieves or creates a ghost sibling node, initializes target parents, and establishes reciprocal links with anchor.
     *
     * @param {Object} params - Parameter object
     * @param {string} params.val - Full sibling ghost name
     * @param {string} params.gender - Gender ('M' or 'F')
     * @param {string} params.targetMom - Target mother name
     * @param {string} params.targetDad - Target father name
     * @param {string} params.srcId - Sheet source ID
     * @param {Object|null} params.anchorNode - Biological sibling anchor node
     * @param {GhostWorkspace} params.ws - Shared ghost-synthesis workspace
     * @returns {Object} Sibling ghost node
     *
     * @example
     * this._linkOrCreateSiblingGhost({ val: 'Rosa Sister', gender: 'F', targetMom, targetDad, srcId, anchorNode, ws });
     * // => Returns Rosa Sister node with reciprocal links to anchorNode
     *
     * @example
     * this._linkOrCreateSiblingGhost({ val: 'Paul Brother', gender: 'M', targetMom, targetDad, srcId, anchorNode: null, ws });
     * // => Returns Paul Brother node initialized without reciprocal anchor linkage
     */
    _linkOrCreateSiblingGhost({ val, gender, targetMom, targetDad, srcId, anchorNode, ws }) {
        let sGhost = ws.find(val);
        if (!sGhost) {
            sGhost = ws.create(val, gender, { mom: targetMom, dad: targetDad, srcId });
        } else {
            if (!sGhost.mom) sGhost.mom = targetMom;
            if (!sGhost.father) sGhost.father = targetDad;
        }
        if (anchorNode) {
            this._linkSiblingReciprocal(sGhost, anchorNode);
            this._propagateSiblingParent(sGhost, anchorNode, 'mom');
            this._propagateSiblingParent(sGhost, anchorNode, 'father');
        }
        return sGhost;
    }

    /**
     * Resolves a parental sibling reference (e.g. "Rosa Sister" in mom field), synthesizing
     * the sibling ghost, shared synthetic parent placeholders, and reciprocal linkages.
     *
     * @param {Object} params - Resolution parameters
     * @param {string} params.val - Raw parental field value (e.g. "Anthony Sister")
     * @param {Object} params.n - Child node declaring the parental sibling
     * @param {GhostWorkspace} params.ws - Shared ghost-synthesis workspace
     *
     * @example
     * this._resolveParentSiblingGhostReference({ val: 'Anthony Sister', n, ws });
     * // => Synthesizes "Anthony Sister", "Anthony Mother", "Anthony Father" and links reciprocal siblings
     *
     * @example
     * this._resolveParentSiblingGhostReference({ val: 'InvalidName', n, ws });
     * // => Early returns when value does not match sibling role pattern
     */
    _resolveParentSiblingGhostReference({ val, n, ws }) {
        if (!val) return;
        const match = val.match(/^(.+?)\s+(Sister|Brother)(?:\s*\d+)?$/i);
        if (!match) return;

        const baseName = match[1].trim();
        const anchorNode = this._findAnchorNode(baseName, n, ws);
        const { targetMom, targetDad } = this._resolveTargetSiblingParents(anchorNode, baseName);
        const srcId = anchorNode ? (anchorNode._sourceId || n._sourceId) : n._sourceId;
        this._linkOrCreateSiblingGhost({
            val,
            gender: match[2].toLowerCase() === 'sister' ? 'F' : 'M',
            targetMom,
            targetDad,
            srcId,
            anchorNode,
            ws
        });
        this._ensureSiblingParentGhosts(targetMom, targetDad, srcId, ws);
    }

    /**
     * Synthesizes ghost sibling and parent profiles for parental sibling references.
     * 
     * @param {GhostWorkspace} ws - Shared ghost-synthesis workspace
     *
     * @example
     * builder._expandSiblingParentReferences(ws); // ws.nodes = [childWithMomSister]
     * // => Generates "Anthony Sister", "Anthony Mother", "Anthony Father"
     *
     * @example
     * builder._expandSiblingParentReferences(ws);
     * // => Scans both mom and father fields on all nodes, creating needed ghost sibling profiles
     */
    _expandSiblingParentReferences(ws) {
        ws.nodes.forEach(n => {
            ['mom', 'father'].forEach(field => {
                this._resolveParentSiblingGhostReference({ val: n[field], n, ws });
            });
        });
    }

    /**
     * Validates and cleans up relationship ambiguities, parent-child age gaps, and partner constraints.
     * 
     * Orchestrates:
     * 1. Parent age compatibility and biological gap validation
     * 2. Incompatible parent-child and family-mismatched link detachment
     * 3. Partner age compatibility and duplicate partner pruning
     * 4. Parent children array synchronization after detachments
     * 5. Resolved ambiguity filtering
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder.cleanupAmbiguities(nodes);
     * // => Detaches biologically impossible parents, unlinks incompatible partners, syncs children arrays
     *
     * @example
     * builder.cleanupAmbiguities([personWithConflictingDad]);
     * // => Validates biological bounds and prunes conflicting paternal link
     */
    cleanupAmbiguities(nodes) {
        nodes.forEach(n => {
            this._validateNodeParentAges(n);
            this._detachIncompatibleParentLinks(n);
            this._pruneNodeIncompatiblePartners(n);
        });

        this._syncParentChildrenArrays(nodes);
        this._filterNodeAmbiguities(nodes);
    }

    /**
     * Resolves cases where both momId and fatherId point to the exact same parent node by inspecting parent's gender.
     * 
     * @param {Object} n - Child person node
     * @param {Object} nodeMap - Map of person ID to person record
     *
     * @example
     * FamilyTreeBuilder._resolveIdenticalParentId({ momId: 'p1', fatherId: 'p1' }, { p1: { id: 'p1', gender: 'F' } });
     * // => node.fatherId is cleared, node.momId is preserved as 'p1'
     *
     * @example
     * FamilyTreeBuilder._resolveIdenticalParentId({ momId: 'p2', fatherId: 'p2' }, { p2: { id: 'p2', gender: 'M' } });
     * // => node.momId is cleared, node.fatherId is preserved as 'p2'
     */
    static _resolveIdenticalParentId(n, nodeMap) {
        if (n.momId && n.fatherId && n.momId === n.fatherId) {
            const p = nodeMap[n.momId];
            if (p) {
                if (p.gender === 'F') n.fatherId = undefined;
                else n.momId = undefined;
            }
        }
    }

    /**
     * Resolves which parent key ('fatherId' or 'momId') violates biological age compatibility
     * based on mother-to-father age difference gap (mYob - dYob).
     *
     * @param {number} gap - Age gap between mother and father (mYob - dYob)
     * @param {number} maxDiff - Maximum allowable age difference between spouses
     * @returns {?string} 'fatherId' if father is too old, 'momId' if mother is too old, or null if compatible
     *
     * @example
     * FamilyTreeBuilder._resolveIncompatibleCoParentKey(70, 45);
     * // => 'fatherId'
     *
     * @example
     * FamilyTreeBuilder._resolveIncompatibleCoParentKey(-60, 45);
     * // => 'momId'
     */
    static _resolveIncompatibleCoParentKey(gap, maxDiff) {
        if (gap > maxDiff) return 'fatherId';
        if (gap < -FamilyTreeBuilder.HEURISTIC_PRIORS.MAX_FIRST_WIFE_AGE_DIFF) return 'momId';
        return null;
    }

    /**
     * Verifies biological age compatibility between mother and father of a node, unlinking the implausible parent if age gap is excessive.
     * 
     * @param {Object} n - Child person node
     * @param {Object} nodeMap - Map of person ID to person record
     *
     * @example
     * FamilyTreeBuilder._validateCoParentAgeCompatibility({ momId: 'm', fatherId: 'f' }, { m: { yob: 1970 }, f: { yob: 1900 } });
     * // => Excessive age gap results in child.fatherId being cleared
     *
     * @example
     * FamilyTreeBuilder._validateCoParentAgeCompatibility({ momId: 'm', fatherId: 'f' }, { m: { yob: 1900 }, f: { yob: 1970 } });
     * // => Negative age gap beyond biological threshold clears child.momId
     */
    static _validateCoParentAgeCompatibility(n, nodeMap) {
        if (!n.momId || !n.fatherId) return;
        const mom = nodeMap[n.momId], dad = nodeMap[n.fatherId];
        const mYob = mom ? (mom.yob || mom._inferredYob) : null;
        const dYob = dad ? (dad.yob || dad._inferredYob) : null;
        if (!mYob || !dYob) return;
        const gap = mYob - dYob;
        const maxDiff = FamilyTreeBuilder._getMaxSpouseAgeDiff(mom, dad);
        const invalidParentKey = FamilyTreeBuilder._resolveIncompatibleCoParentKey(gap, maxDiff);
        if (invalidParentKey) {
            n[invalidParentKey] = undefined;
        }
    }

    /**
     * Validates child birth year against biological parental limits (minimum age 14, maximum age e.g. 52/75).
     * If child birth year is unstated, infers it using default offset; if birth year is explicit and invalid, detaches the parent.
     * 
     * @param {Object} n - Child person node
     * @param {Object} nodeMap - Map of person ID to person record
     * @param {string} parentIdKey - 'momId' or 'fatherId'
     * @param {number} maxAge - Maximum plausible age at childbirth (e.g. 52 for mother, 75 for father)
     * @param {number} defaultChildOffset - Generational offset to assign to child if unstated (e.g. 22 or 25)
     *
     * @example
     * FamilyTreeBuilder._enforceParentChildBiologicalGap({ fatherId: 'f', yob: 1950 }, { f: { yob: 1945 } }, 'fatherId', 75, 25);
     * // => Gap of 5 < 14 violates biological bound, clearing node.fatherId
     *
     * @example
     * FamilyTreeBuilder._enforceParentChildBiologicalGap({ momId: 'm', _inferredYob: 2010 }, { m: { yob: 1940 } }, 'momId', 52, 22);
     * // => Gap of 70 > 52 adjusts unstated birth year to 1962
     */
    static _enforceParentChildBiologicalGap(n, nodeMap, parentIdKey, maxAge, defaultChildOffset) {
        if (!n[parentIdKey]) return;
        const parent = nodeMap[n[parentIdKey]];
        const pYob = parent ? (parent.yob || parent._inferredYob) : null;
        const nYob = n.yob || n._inferredYob;
        if (pYob && nYob && (nYob < pYob + FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE || nYob > pYob + maxAge)) {
            if (!n.yob) n._inferredYob = pYob + defaultChildOffset;
            else {
                n[parentIdKey] = undefined;
                if (n._namedParentId === parent.id) n._namedParentId = undefined;
            }
        }
    }

    /**
     * Validates parent ages, identical parent ID resolution, and biological childbirth bounds.
     * 
     * @param {Object} n - Child node
     *
     * @example
     * builder._validateNodeParentAges(childNode);
     * // => Disambiguates identical parent IDs and enforces biological maternal/paternal bounds
     *
     * @example
     * builder._validateNodeParentAges({ momId: 'm', fatherId: 'f', yob: 2000 });
     * // => Validates co-parent compatibility against builder.nodeMap
     */
    _validateNodeParentAges(n) {
        FamilyTreeBuilder._resolveIdenticalParentId(n, this.nodeMap);
        FamilyTreeBuilder._validateCoParentAgeCompatibility(n, this.nodeMap);
        FamilyTreeBuilder._enforceParentChildBiologicalGap(
            n, this.nodeMap, 'momId',
            FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE,
            FamilyTreeBuilder.GENERATIONAL_GAPS.MATERNAL_FIRST_CHILD
        );
        FamilyTreeBuilder._enforceParentChildBiologicalGap(
            n, this.nodeMap, 'fatherId',
            FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE,
            FamilyTreeBuilder.GENERATIONAL_GAPS.PATERNAL_FIRST_CHILD
        );
    }

    /**
     * Unlinks two partner nodes by removing their reciprocal partner IDs.
     *
     * @param {Object} p1 - First partner node
     * @param {Object} p2 - Second partner node
     *
     * @example
     * FamilyTreeBuilder._unlinkPartners(momNode, dadNode);
     * // => Reciprocal IDs removed from p1.partners and p2.partners
     *
     * @example
     * FamilyTreeBuilder._unlinkPartners(momNode, null);
     * // => Safe no-op when either node is null or undefined
     */
    static _unlinkPartners(p1, p2) {
        if (!p1 || !p2) return;
        p1.partners = (p1.partners || []).filter(pid => pid !== p2.id);
        p2.partners = (p2.partners || []).filter(pid => pid !== p1.id);
    }

    /**
     * Detaches a child from a father node and unlinks the father from the mother.
     *
     * @param {Object} n - Child node
     * @param {Object} dad - Father node
     * @param {Object|null} mom - Mother node
     *
     * @example
     * FamilyTreeBuilder._detachPaternalLink(childNode, dadNode, momNode);
     * // => childNode.fatherId cleared, child removed from dad.children, parents unlinked
     *
     * @example
     * FamilyTreeBuilder._detachPaternalLink(childNode, dadNode, null);
     * // => Clears fatherId and removes child from dad.children without mother unlinking
     */
    static _detachPaternalLink(n, dad, mom) {
        n.fatherId = undefined;
        dad.children = (dad.children || []).filter(cid => cid !== n.id);
        if (mom) {
            FamilyTreeBuilder._unlinkPartners(mom, dad);
        }
    }

    /**
     * Detaches a child from a mother node and unlinks the mother from the father.
     *
     * @param {Object} n - Child node
     * @param {Object} mom - Mother node
     * @param {Object|null} dad - Father node
     *
     * @example
     * FamilyTreeBuilder._detachMaternalLink(childNode, momNode, dadNode);
     * // => childNode.momId cleared, child removed from mom.children, parents unlinked
     *
     * @example
     * FamilyTreeBuilder._detachMaternalLink(childNode, momNode, null);
     * // => Clears momId and removes child from mom.children without father unlinking
     */
    static _detachMaternalLink(n, mom, dad) {
        n.momId = undefined;
        mom.children = (mom.children || []).filter(cid => cid !== n.id);
        if (dad) {
            FamilyTreeBuilder._unlinkPartners(mom, dad);
        }
    }

    /**
     * Checks whether two family names conflict after case-folding and trimming.
     *
     * @param {string} fam1 - First family name
     * @param {string} fam2 - Second family name
     * @returns {boolean} True if both names are non-empty and differ
     *
     * @example
     * FamilyTreeBuilder._hasFamilyMismatch('Mecheri', 'Chalissery')
     * // => true
     *
     * @example
     * FamilyTreeBuilder._hasFamilyMismatch('Mecheri', ' mecheri ')
     * // => false
     */
    static _hasFamilyMismatch(fam1, fam2) {
        const f1 = fam1 ? fam1.toLowerCase().trim() : '';
        const f2 = fam2 ? fam2.toLowerCase().trim() : '';
        return Boolean(f1 && f2 && f1 !== f2);
    }

    /**
     * Detaches one parent link when co-parents are age-incompatible and family name mismatches.
     *
     * @param {Object} n - Child node
     * @param {Object} dad - Father node
     * @param {Object} mom - Mother node
     * @param {string} nFam - Child family name
     *
     * @example
     * builder._detachIncompatibleCoParent(child, dad, mom, 'mecheri')
     *
     * @example
     * builder._detachIncompatibleCoParent(child, dad, mom, '')
     */
    _detachIncompatibleCoParent(n, dad, mom, nFam) {
        const dadFam = FamilyTreeBuilder._resolveFamilyName(dad, this.nodeMap);
        if (FamilyTreeBuilder._hasFamilyMismatch(nFam, dadFam)) {
            FamilyTreeBuilder._detachPaternalLink(n, dad, mom);
        } else if (FamilyTreeBuilder._hasFamilyMismatch(n.family, mom.family)) {
            FamilyTreeBuilder._detachMaternalLink(n, mom, dad);
        }
    }

    /**
     * Detaches parent-child links where family names conflict or parents are age-incompatible.
     * 
     * @param {Object} n - Child node
     *
     * @example
     * builder._detachIncompatibleParentLinks(childWithMismatchedFamilyDad);
     * // => Detaches paternal link when child family does not match resolved father family
     *
     * @example
     * builder._detachIncompatibleParentLinks(compatibleChildNode);
     * // => Leaves links intact when families and ages are compatible
     */
    _detachIncompatibleParentLinks(n) {
        const dad = n.fatherId ? this.nodeMap[n.fatherId] : null;
        const mom = n.momId ? this.nodeMap[n.momId] : null;
        const nFam = n.family ? n.family.toLowerCase().trim() : '';

        if (dad) {
            const dadFam = FamilyTreeBuilder._resolveFamilyName(dad, this.nodeMap);
            if (FamilyTreeBuilder._hasFamilyMismatch(nFam, dadFam)) {
                FamilyTreeBuilder._detachPaternalLink(n, dad, mom);
            }
        }

        if (mom && dad && !FamilyTreeBuilder._arePartnersAgeCompatible(dad, mom, dad.partners && dad.partners.length > 0)) {
            this._detachIncompatibleCoParent(n, dad, mom, nFam);
        }
    }

    /**
     * Prunes age-incompatible and duplicate partners from a node.
     * 
     * @param {Object} n - Domain Person instance
     *
     * @example
     * builder._pruneNodeIncompatiblePartners(personWithDuplicatePartners);
     * // => Retains unique, age-compatible partner IDs in n.partners
     *
     * @example
     * builder._pruneNodeIncompatiblePartners({ partners: [] });
     * // => No-op when node has no partners
     */
    _pruneNodeIncompatiblePartners(n) {
        if (n.partners && n.partners.length > 0) {
            const uniquePartners = [];
            n.partners.forEach(pid => {
                if (pid === n.id) return;
                const p = this.nodeMap[pid];
                if (!p) return;
                if (!FamilyTreeBuilder._arePartnersAgeCompatible(n, p, uniquePartners.length > 0)) return;
                const isDup = uniquePartners.some(existingId => {
                    const ep = this.nodeMap[existingId];
                    if (!ep) return false;
                    return ep._normName === p._normName && ep.yob === p.yob && ep.yob;
                });
                if (!isDup) uniquePartners.push(pid);
            });
            n.partners = uniquePartners;
        }
    }

    /**
     * Synchronizes parent children arrays after detachments.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._syncParentChildrenArrays(nodes);
     * // => Filters each parent's children array to children who actually reference parent ID
     *
     * @example
     * builder._syncParentChildrenArrays([{ children: ['c1'] }]);
     * // => Ensures child 'c1' in builder.nodeMap has matching momId or fatherId
     */
    _syncParentChildrenArrays(nodes) {
        nodes.forEach(p => {
            if (p.children && p.children.length > 0) {
                p.children = p.children.filter(cid => {
                    const c = this.nodeMap[cid];
                    if (!c) return false;
                    if (c.momId === p.id || c.fatherId === p.id) return true;
                    const isUngendered = !p.gender || (p.gender !== 'M' && p.gender !== 'F');
                    const bioCompatible = !(p.yob && c.yob && (c.yob - p.yob < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE));
                    return Boolean(c._namedParentId === p.id && isUngendered && bioCompatible);
                });
            }
        });
    }

    /**
     * Filters ambiguous spouse candidates for a node, pruning already-taken candidates.
     *
     * @param {Object} amb - Ambiguity object { relation, query, candidates, message }
     * @param {Object} node - Proposing Person node
     * @returns {boolean} True if more than 1 viable spouse candidate remains (ambiguity persists)
     *
     * @example
     * builder._filterSpouseAmbiguity({ relation: 'spouse', candidates: [c1Free, c2Taken] }, node);
     * // => false (c1Free is single candidate, ambiguity resolved)
     *
     * @example
     * builder._filterSpouseAmbiguity({ relation: 'spouse', candidates: [c1Free, c2Free] }, node);
     * // => true (multiple viable unpartnered candidates persist)
     */
    _filterSpouseAmbiguity(amb, node) {
        const viable = amb.candidates.filter(c => {
            const candNode = this.nodeMap[c.id];
            if (!candNode) return false;
            if (candNode.partners.includes(node.id)) return true;
            return candNode.partners.length === 0;
        });

        if (viable.length <= 1) return false;
        const maxClose = FamilyTreeBuilder.GENERATIONAL_GAPS?.MAX_ROW_NEIGHBOR_DISTANCE || 5;
        const closeby = viable.filter(c => {
            const candNode = this.nodeMap[c.id];
            return candNode && FamilyTreeBuilder.sharesSheet(candNode, node) && 
                FamilyTreeBuilder._getMinRowDistance(candNode, node) <= maxClose;
        });
        if (closeby.length === 1) return false;

        amb.candidates = viable;
        amb.message = `Found ${viable.length} candidates for ${amb.relation} '${amb.query}'`;
        return true;
    }

    /**
     * Verifies biological age bounds and family name compatibility between candidate parent and seeking child.
     *
     * @param {Object} candNode - Candidate parent node
     * @param {Object} node - Seeking child node
     * @param {string} relation - 'mother' or 'father'
     * @param {Object} nodeMap - Map of all node IDs to node objects
     * @returns {boolean} True if candidate is biologically and culturally viable
     *
     * @example
     * FamilyTreeBuilder._isParentCandidateBiologicallyAndFamilyCompatible(motherNode, childNode, 'mother', nodeMap);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isParentCandidateBiologicallyAndFamilyCompatible(tooYoungNode, childNode, 'father', nodeMap);
     * // => false (age difference less than minimum parental gap)
     */
    static _isParentCandidateBiologicallyAndFamilyCompatible(candNode, node, relation, nodeMap) {
        if (!candNode) return false;
        const cYob = FamilyTreeBuilder._effectiveYob(candNode);
        const nYob = FamilyTreeBuilder._effectiveYob(node);
        if (cYob && nYob) {
            const ageDiff = nYob - cYob;
            if (ageDiff < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE) return false;
            if (relation === 'mother' && ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE) return false;
            if (relation === 'father' && ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE) return false;
        }
        const checkFam = node._declaredFamily || (node.family && !node._inferredPaternalFamily ? node.family : null);
        if (checkFam) {
            const nFam = checkFam.toLowerCase().trim();
            const candFam = FamilyTreeBuilder._resolveFamilyName(candNode, nodeMap);
            if (relation === 'father' && candFam && candFam !== nFam) return false;
            if (relation === 'mother' && !FamilyTreeBuilder._isMotherSpouseFamilyCompatible(candNode, nFam, nodeMap)) return false;
        }
        return true;
    }

    /**
     * Binds an unambiguous resolved parent to a child and updates parent's children list.
     *
     * @param {Object} remNode - Unambiguous parent node
     * @param {Object} node - Child node
     * @param {string} relation - 'mother' or 'father'
     *
     * @example
     * builder._bindResolvedParent(motherNode, childNode, 'mother');
     * // => sets childNode.momId, childNode.mom, and pushes childNode.id to motherNode.children
     *
     * @example
     * builder._bindResolvedParent(fatherNode, childNode, 'father');
     * // => sets childNode.fatherId, childNode.father, and registers child in fatherNode.children
     */
    _bindResolvedParent(remNode, node, relation) {
        if (!remNode || !node) return;
        if (relation === 'mother') {
            node.momId = remNode.id;
            node.mom = remNode.name;
        } else if (relation === 'father') {
            node.fatherId = remNode.id;
            node.father = remNode.name;
        }
        if (!remNode.children) remNode.children = [];
        if (!remNode.children.includes(node.id)) remNode.children.push(node.id);
    }

    /**
     * Filters ambiguous parent candidates for a child using biological age bounds and family names.
     * When exactly 1 viable candidate remains, binds the parent to the child and updates parent children.
     *
     * @param {Object} amb - Ambiguity object { relation, query, candidates, message }
     * @param {Object} node - Seeking child Person node
     * @returns {boolean} True if more than 1 viable parent candidate remains (ambiguity persists)
     *
     * @example
     * builder._filterParentAmbiguity({ relation: 'mother', candidates: [mary1940, mary1960] }, { yob: 1955 });
     * // => false (mary1960 is too young, mary1940 auto-bound as mother)
     *
     * @example
     * builder._filterParentAmbiguity({ relation: 'father', candidates: [dad1, dad2] }, childNode);
     * // => true (both candidates remain viable, ambiguity retained)
     */
    _filterParentAmbiguity(amb, node) {
        if (node._namedParentId && amb.candidates.some(c => c.id === node._namedParentId)) {
            return false;
        }

        const viable = amb.candidates.filter(c =>
            FamilyTreeBuilder._isParentCandidateBiologicallyAndFamilyCompatible(this.nodeMap[c.id], node, amb.relation, this.nodeMap)
        );

        if (viable.length <= 1) {
            if (viable.length === 1) {
                this._bindResolvedParent(this.nodeMap[viable[0].id], node, amb.relation);
            }
            return false;
        }

        amb.candidates = viable;
        amb.message = `Found ${viable.length} candidates for ${amb.relation} '${amb.query}'`;
        return true;
    }

    /**
     * Filters ambiguities that have already been resolved or have <= 1 candidate remaining.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._filterNodeAmbiguities(nodes);
     * // => filters and resolves parent/spouse ambiguities on all nodes
     *
     * @example
     * builder._filterNodeAmbiguities([nodeWithResolvedSpouseAmbiguity]);
     * // => drops ambiguity from node.ambiguities once candidate is resolved
     */
    _filterNodeAmbiguities(nodes) {
        nodes.forEach(n => {
            if (!n.ambiguities || n.ambiguities.length === 0) return;
            n.ambiguities = n.ambiguities.filter(amb => {
                if (amb.relation === 'spouse' || amb.relation === 'husband' || amb.relation === 'wife') {
                    return this._filterSpouseAmbiguity(amb, n);
                }
                if (amb.relation === 'mother' || amb.relation === 'father' || amb.relation === 'parent') {
                    return this._filterParentAmbiguity(amb, n);
                }
                return true;
            });
        });
    }

    /**
     * Checks if a parent or person name is a synthetically generated parent ghost name (ending in ' Mother' or ' Father').
     *
     * @param {?string} name - Name to inspect
     * @returns {boolean} True if the name matches synthetic parent naming convention
     *
     * @example
     * FamilyTreeBuilder._isSyntheticGhostParent('John Doe Father');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isSyntheticGhostParent('John Doe');
     * // => false
     */
    static _isSyntheticGhostParent(name) {
        return Boolean(name && (name.endsWith(' Mother') || name.endsWith(' Father')));
    }

    /**
     * Synchronizes a known parent field between two sibling nodes, resolving conflicts by preferring non-synthetic names.
     *
     * @param {Object} n - First sibling node
     * @param {Object} bMatch - Second sibling node
     * @param {string} f - Parent field ('mom' or 'father')
     * @returns {boolean} True if either sibling node was modified
     *
     * @example
     * FamilyTreeBuilder._syncKnownSiblingParent({ mom: 'Mary' }, {}, 'mom');
     * // => true
     *
     * @example
     * FamilyTreeBuilder._syncKnownSiblingParent({ father: 'John Father' }, { father: 'John' }, 'father');
     * // => true
     */
    static _syncKnownSiblingParent(n, bMatch, f) {
        if (n[f] && !bMatch[f]) {
            bMatch[f] = n[f];
            return true;
        }
        if (!n[f] && bMatch[f]) {
            n[f] = bMatch[f];
            return true;
        }
        if (n[f] && bMatch[f] && n[f] !== bMatch[f]) {
            const nGhost = FamilyTreeBuilder._isSyntheticGhostParent(n[f]);
            const bGhost = FamilyTreeBuilder._isSyntheticGhostParent(bMatch[f]);
            if (!nGhost && bGhost) {
                bMatch[f] = n[f];
                return true;
            }
            if (nGhost && !bGhost) {
                n[f] = bMatch[f];
                return true;
            }
        }
        return false;
    }

    /**
     * Creates and assigns a synthetic ghost parent name to two sibling nodes when neither has a known parent.
     *
     * @param {Object} n - First sibling node
     * @param {Object} bMatch - Second sibling node
     * @param {string} f - Parent field ('mom' or 'father')
     * @returns {string} The synthetic parent name that was assigned
     *
     * @example
     * builder._assignSyntheticSiblingParent({ name: 'Bob' }, { name: 'Alice' }, 'mom');
     * // => 'Alice Mother'
     *
     * @example
     * builder._assignSyntheticSiblingParent({ name: 'Bob' }, { name: 'Alice' }, 'father');
     * // => 'Alice Father'
     */
    _assignSyntheticSiblingParent(n, bMatch, f) {
        const sortedName = [n.name, bMatch.name].sort()[0];
        const defParent = `${sortedName} ${f === 'mom' ? 'Mother' : 'Father'}`;
        n[f] = defParent;
        bMatch[f] = defParent;
        this.syntheticSiblingParentNames = this.syntheticSiblingParentNames || new Set();
        this.syntheticSiblingParentNames.add(defParent.toLowerCase().trim());
        return defParent;
    }

    /**
     * Propagates parent information between two sibling nodes, resolving synthetic parent ghosts.
     *
     * @param {Object} n - First sibling node
     * @param {Object} bMatch - Second sibling node
     * @param {string} f - Parent field ('mom' or 'father')
     * @returns {boolean} True if any parent property was modified
     *
     * @example
     * builder._propagateSiblingParent(siblingA, siblingB, 'mom');
     * // => Copies or synchronizes mother between siblingA and siblingB
     *
     * @example
     * builder._propagateSiblingParent(siblingA, siblingB, 'father');
     * // => Assigns synthetic default father if neither sibling had one
     */
    _propagateSiblingParent(n, bMatch, f) {
        if (n[f] || bMatch[f]) {
            return FamilyTreeBuilder._syncKnownSiblingParent(n, bMatch, f);
        }
        this._assignSyntheticSiblingParent(n, bMatch, f);
        return true;
    }

    /**
     * Ensures bidirectional sibling ID tracking between two person nodes.
     *
     * @param {Object} n - First person node
     * @param {Object} bMatch - Second person node
     * @returns {boolean} True if explicit siblings arrays were modified
     *
     * @example
     * builder._linkSiblingReciprocal(johnNode, janeNode);
     * // => Registers reciprocal IDs in johnNode.explicitSiblings and janeNode.explicitSiblings
     *
     * @example
     * builder._linkSiblingReciprocal(nodeA, nodeB);
     * // => Returns false if both nodes already track each other as explicit siblings
     */
    _linkSiblingReciprocal(n, bMatch) {
        let changed = false;
        if (!n.explicitSiblings) n.explicitSiblings = [];
        if (!n.explicitSiblings.includes(bMatch.id)) { n.explicitSiblings.push(bMatch.id); changed = true; }
        if (!bMatch.explicitSiblings) bMatch.explicitSiblings = [];
        if (!bMatch.explicitSiblings.includes(n.id)) { bMatch.explicitSiblings.push(n.id); changed = true; }
        return changed;
    }

    /**
     * Resolves an explicit sibling reference, or creates a ghost placeholder if none found.
     *
     * @param {Object} n - Source node referencing sibling
     * @param {string} sibName - Display name of the sibling
     * @param {Object[]} nodes - Master node list
     * @returns {{ match: Object, changed: boolean }} Resolved or created sibling node and changed flag
     *
     * @example
     * builder._resolveOrCreateSiblingGhost(currentNode, 'Mark', nodes);
     * // => Returns existing node for 'Mark' if found on same sheet
     *
     * @example
     * builder._resolveOrCreateSiblingGhost(currentNode, 'UnseenSibling', nodes);
     * // => Synthesizes auto-ghost sibling profile and registers in nodes and name2nodes
     */
    _resolveOrCreateSiblingGhost(n, sibName, nodes) {
        const cands = this.name2nodes[sibName.toLowerCase()] || [];
        let match = cands.find(c => c !== n && FamilyTreeBuilder.sharesSheet(c, n));
        let changed = false;
        if (!match) {
            const clean = sibName;
            match = {
                _rawId: `autoghost_sibling_${nodes.length}`,
                _sourceId: n._sourceId, _sourceIds: new Set([n._sourceId]),
                _sheetRows: n._sheetRows ? { ...n._sheetRows } : (n._sourceId && n._sheetRow ? { [n._sourceId]: n._sheetRow } : {}),
                _allSourceRefs: n._allSourceRefs ? [...n._allSourceRefs] : (n._sourceId && n._sheetRow ? [{ sheetId: n._sourceId, row: n._sheetRow }] : []),
                id: `autoghost_${clean.replace(/\s+/g, '_')}_${n._sourceId}_sibling_${nodes.length}`,
                name: clean, _normName: clean.toLowerCase().trim(), gender: '', isGhost: true,
                partners: [], children: [], ambiguities: [], explicitSiblings: [n.id]
            };
            nodes.push(match); this.nodeMap[match.id] = match;
            const l = clean.toLowerCase().trim();
            if (!this.name2nodes[l]) this.name2nodes[l] = [];
            this.name2nodes[l].push(match);
            changed = true;
        }
        return { match, changed };
    }

    /**
     * Links explicit siblings incrementally and propagates concrete parents across the sibling group.
     *
     * @param {Object[]} nodes - Validated Person instances
     *
     * @example
     * builder.linkExplicitSiblings(nodes);
     * // => Resolves comma-separated sibling strings and synchronizes parent references across siblings
     *
     * @example
     * builder.linkExplicitSiblings([nodeWithSiblings]);
     * // => Creates ghost profiles for unlisted siblings and sets reciprocal explicit siblings
     */
    linkExplicitSiblings(nodes) {
        let changed = true, maxIter = 10;
        while (changed && maxIter-- > 0) {
            changed = false;
            nodes.forEach(n => {
                if (!n.sibling) return;
                const sibNames = n.sibling.split(/[,&/]+/).map(s => s.trim()).filter(Boolean);
                sibNames.forEach(sName => {
                    const { match, changed: mc } = this._resolveOrCreateSiblingGhost(n, sName, nodes);
                    if (mc) changed = true;
                    if (this._linkSiblingReciprocal(n, match)) changed = true;
                    if (this._propagateSiblingParent(n, match, 'mom')) changed = true;
                    if (this._propagateSiblingParent(n, match, 'father')) changed = true;
                });
            });
        }
    }

    /**
     * Determines whether a candidate ghost node could plausibly be the parent of a source node.
     *
     * @param {Object} n - The source child node
     * @param {Object} c - The candidate parent node
     * @param {string} field - 'mom' or 'father'
     * @returns {boolean} True if candidate satisfies generational gap and biological bounds
     *
     * @example
     * builder._isPlausibleParent(childNode, candidateMom, 'mom');
     * // => true (child yob - mom yob between 14 and 55)
     *
     * @example
     * builder._isPlausibleParent({ yob: 1950 }, { yob: 1945 }, 'father');
     * // => false (age difference 5 < 14)
     */
    _isPlausibleParent(n, c, field) {
        const relType = (field === 'mom' || field === 'mother') ? 'mother' : 'father';
        if (!FamilyTreeBuilder._isValidParentCandidate(c, n, relType, c._normName, this.nodeMap)) return false;
        if (!c.yob || !n.yob) return true;
        const MathDiff = n.yob - c.yob;
        const minAge = FamilyTreeBuilder.GENERATIONAL_GAPS?.MIN_PARENTAL_AGE || 14;
        const maxAge = relType === 'mother'
            ? (FamilyTreeBuilder.BIOLOGICAL_BOUNDS?.MAX_MOTHER_CHILDBIRTH_AGE || 55)
            : (FamilyTreeBuilder.BIOLOGICAL_BOUNDS?.MAX_FATHER_CHILDBIRTH_AGE || 80);
        return MathDiff >= minAge && MathDiff <= maxAge;
    }

    /**
     * Rejects spouse match if candidate belongs to a different primary family subtree.
     *
     * @param {Object} n - Source person node
     * @param {Object} c - Candidate spouse node
     * @returns {boolean} True if family names conflict and candidate must be rejected
     *
     * @example
     * builder._rejectDifferentFamily({ family: 'Alappatt' }, { family: 'Mandan' });
     * // => true (distinct primary family names indicate different families)
     *
     * @example
     * builder._rejectDifferentFamily(spouseClaimantA, spouseClaimantB);
     * // => false (explicit mutual spouse claims allow different birth families)
     */
    _rejectDifferentFamily(n, c) {
        // Explicit spouse claims between marrying families are naturally distinct birth families
        if (FamilyTreeBuilder._claimsAsSpouse(n, c) || FamilyTreeBuilder._claimsAsSpouse(c, n)) return false;
        const nFam = n.family ? n.family.toLowerCase().trim() : '';
        const cFam = c.family ? c.family.toLowerCase().trim() : '';
        if (nFam && cFam && nFam !== cFam) return true;
        if (nFam && !cFam && c.spouse) {
            const hasConflict = [c.spouse, ...(c._localImplicitSpouses || [])]
                .map(s => s.toLowerCase().trim())
                .some(s => (this.name2nodes[s] || []).some(x => x.family && x.family.toLowerCase().trim() !== nFam));
            if (hasConflict) return true;
        }
        return false;
    }

    /**
     * Determines whether a candidate node could plausibly be the spouse of the source node.
     * Evaluates family separation, celibacy vows, implicit spouse markers, explicit mutual
     * claims, multi-sheet scope, row proximity, and biological generational age gaps.
     *
     * @param {Object} n - Source node
     * @param {Object} c - Candidate node
     * @returns {boolean} True if candidate is plausible spouse for source node
     *
     * @example
     * const isSpouse1 = builder._isPlausibleSpouse(unniNode, miniGhostNode);
     *
     * @example
     * const isSpouse2 = builder._isPlausibleSpouse(husbandNode, frAbhilashPriest);
     */
    _isPlausibleSpouse(n, c) {
        if (this._rejectDifferentFamily(n, c)) return false;
        if (!FamilyTreeBuilder.sharesSheet(c, n)) {
            const isImplicit = n._normName.includes(c._normName) && (n._normName.includes('wife') || n._normName.includes('husband'));
            const cClaimsSource = FamilyTreeBuilder._claimsAsSpouse(c, n);
            if (!isImplicit && !cClaimsSource) return false;
        }
        return FamilyTreeBuilder._isValidSpouseCandidate(c, n, n.spouseType || '', this.nodeMap);
    }

    /**
     * Gets correct gender for new ghost relationship based on target field or source node gender.
     *
     * @param {Object} n - Source person node
     * @param {string} field - Relational field ('mom', 'father', or 'spouse')
     * @returns {string} Gender code ('M', 'F', or empty string)
     *
     * @example
     * const gMom = builder._getGhostGender(person, 'mom'); // 'F'
     *
     * @example
     * const gDad = builder._getGhostGender(person, 'father'); // 'M'
     */
    _getGhostGender(n, field) {
        if (field === 'mom') return 'F';
        if (field === 'father') return 'M';
        if (n.gender === 'F' || n.spouseType === 'wife') return 'M';
        if (n.gender === 'M' || n.spouseType === 'husband') return 'F';
        return '';
    }

    /**
     * Splits a raw name containing an optional slash into a clean name and nickname.
     *
     * @param {string} name - Raw name string possibly containing slash.
     * @returns {{ clean: string, nick: string }} Parsed name object containing clean name and nickname.
     *
     * @example
     * const res1 = FamilyTreeBuilder._parseNameAndNick('Mary / Molly');
     * // res1 => { clean: 'Mary', nick: 'Molly' }
     *
     * @example
     * const res2 = FamilyTreeBuilder._parseNameAndNick('John');
     * // res2 => { clean: 'John', nick: '' }
     */
    static _parseNameAndNick(name) {
        if (!name) return { clean: '', nick: '' };
        if (name.includes('/')) {
            const pts = name.split('/');
            return { clean: pts[0].trim(), nick: pts.slice(1).join('/').trim() };
        }
        return { clean: name.trim(), nick: '' };
    }

    /**
     * Resolves the primary sheet ID provenance for a ghost relative.
     *
     * @param {Object} n - Declaring person node.
     * @param {string} field - Relationship field ('mom', 'father', or other).
     * @returns {string|null} Source sheet identifier.
     *
     * @example
     * const s1 = FamilyTreeBuilder._resolveGhostSourceSheet({ _momSourceSheet: 'sheetA' }, 'mom');
     *
     * @example
     * const s2 = FamilyTreeBuilder._resolveGhostSourceSheet({ _sourceId: 'mainSheet' }, 'spouse');
     */
    static _resolveGhostSourceSheet(n, field) {
        return (field === 'mom' && n._momSourceSheet) ||
               (field === 'father' && n._fatherSourceSheet) ||
               n._sourceId || null;
    }

    /**
     * Registers a ghost node under its clean, raw, and nickname entries in the name index.
     *
     * @param {Object} g - Ghost node.
     * @param {string} clean - Clean name.
     * @param {string} rawName - Raw declared name.
     *
     * @example
     * builder._indexGhostInNameMap(ghostNode, 'Mary', 'Mary / Molly');
     *
     * @example
     * builder._indexGhostInNameMap(ghostNode, 'George', 'George');
     */
    _indexGhostInNameMap(g, clean, rawName) {
        const add = l => {
            if (l) {
                if (!this.name2nodes[l]) this.name2nodes[l] = [];
                if (!this.name2nodes[l].includes(g)) this.name2nodes[l].push(g);
            }
        };
        add(clean.toLowerCase().trim());
        add(rawName.toLowerCase().trim());
        add(g._normNick);
    }

    /**
     * Determines whether a relationship field value represents a synthetic sibling parent placeholder name.
     *
     * @private
     * @param {string} clean - Sanitized name without nickname
     * @param {string} name - Raw candidate name
     * @param {string} field - Relationship field ('mom', 'father', or 'spouse')
     * @param {Set<string>|null} syntheticNames - Set of known synthetic sibling parent names
     * @returns {boolean} True if matching synthetic parent naming rules
     *
     * @example
     * FamilyTreeBuilder._isSyntheticParentField('John Father', 'John Father', 'father', null);
     * // => true
     *
     * @example
     * FamilyTreeBuilder._isSyntheticParentField('Mary', 'Mary', 'mom', new Set(['mary']));
     * // => true
     */
    static _isSyntheticParentField(clean, name, field, syntheticNames) {
        if (syntheticNames && (syntheticNames.has(clean.toLowerCase().trim()) || syntheticNames.has(name.toLowerCase().trim()))) {
            return true;
        }
        return (field === 'mom' || field === 'father') && (clean.endsWith(' Mother') || clean.endsWith(' Father'));
    }

    /**
     * Assigns originating child or spouse tracking identifiers to a newly instantiated ghost node.
     *
     * @param {Object} g - Ghost node
     * @param {Object} n - Relative node that triggered ghost creation
     * @param {string} field - Relationship field ('mom', 'father', or 'spouse')
     *
     * @example
     * const g = {};
     * FamilyTreeBuilder._assignGhostOriginatingIds(g, { id: 'child1' }, 'father');
     * // g._originatingChildIds is ['child1']
     *
     * @example
     * const g = {};
     * FamilyTreeBuilder._assignGhostOriginatingIds(g, { id: 'partner1' }, 'spouse');
     * // g._originatingSpouseIds is ['partner1']
     */
    static _assignGhostOriginatingIds(g, n, field) {
        if (field === 'mom' || field === 'father') {
            g._originatingChildIds = [n.id];
        } else if (field === 'spouse') {
            g._originatingSpouseIds = [n.id];
        }
    }

    /**
     * Instantiates a new placeholder ghost person profile and registers it into builder node maps.
     *
     * @param {Object} n - Person node referencing the missing relative
     * @param {string} name - Raw name of the missing relative
     * @param {string} field - Relational field ('mom', 'father', or 'spouse')
     * @param {string} key - Cache deduplication key
     * @param {Object[]} newNodes - Accumulator array for newly created ghost profiles
     * @returns {Object} Instantiated ghost person node
     *
     * @example
     * const g1 = builder._instantiateGhost(childNode, 'Annamma', 'mom', 'k1', newNodesArr);
     *
     * @example
     * const g2 = builder._instantiateGhost(husbandNode, 'Mariam', 'spouse', 'k2', newNodesArr);
     */
    _instantiateGhost(n, name, field, key, newNodes) {
        const { clean, nick } = FamilyTreeBuilder._parseNameAndNick(name);
        const _isSyntheticSiblingParent = FamilyTreeBuilder._isSyntheticParentField(clean, name, field, this.syntheticSiblingParentNames);
        const sourceId = FamilyTreeBuilder._resolveGhostSourceSheet(n, field);
        const { _sheetRows, _allSourceRefs } = FamilyTreeBuilder._inheritSourceTracking(n);
        const g = {
            _rawId: `autoghost_${field}_${newNodes.length}`,
            _isSyntheticSiblingParent,
            _sourceId: sourceId,
            _sourceIds: new Set(sourceId ? [sourceId] : []),
            _sheetRows,
            _allSourceRefs,
            id: `autoghost_${clean.replace(/\s+/g, '_')}_${key}`,
            name: clean, nick, _normName: clean.toLowerCase().trim(),
            _normNick: nick ? nick.toLowerCase().trim() : '',
            gender: this._getGhostGender(n, field), isGhost: true,
            family: (field === 'father' && n.family) ? n.family : '',
            partners: [], children: [], ambiguities: []
        };
        FamilyTreeBuilder._assignGhostOriginatingIds(g, n, field);
        newNodes.push(g);
        this.nodeMap[g.id] = g;
        this._indexGhostInNameMap(g, clean, name);
        return g;
    }

    /**
     * Determines whether an existing candidate matches the relational field requirement for a node,
     * taking into account provenance source sheets and relationship plausibility.
     *
     * @param {Object} c - Candidate person node
     * @param {Object} n - Source person node
     * @param {string} field - Relational field ('mom', 'father', or 'spouse')
     * @returns {boolean} True if candidate is a valid match
     *
     * @example
     * const ok1 = builder._isValidCandidateForMissingProfile(candFather, child, 'father');
     *
     * @example
     * const ok2 = builder._isValidCandidateForMissingProfile(candSpouse, person, 'spouse');
     */
    _isValidCandidateForMissingProfile(c, n, field) {
        if (c === n) return false;
        if (field === 'mom' && (n._momSourceSheets ? n._momSourceSheets.size > 0 : n._momSourceSheet)) {
            const sheets = n._momSourceSheets || new Set([n._momSourceSheet]);
            if (!c._sourceIds || !Array.from(sheets).some(sid => c._sourceIds.has(sid))) return false;
        } else if (field === 'father' && (n._fatherSourceSheets ? n._fatherSourceSheets.size > 0 : n._fatherSourceSheet)) {
            const sheets = n._fatherSourceSheets || new Set([n._fatherSourceSheet]);
            if (!c._sourceIds || !Array.from(sheets).some(sid => c._sourceIds.has(sid))) return false;
        } else if ((field === 'mom' || field === 'father') && !FamilyTreeBuilder.sharesSheet(c, n)) {
            return false;
        }
        return field === 'spouse' ? this._isPlausibleSpouse(n, c) : this._isPlausibleParent(n, c, field);
    }

    /**
     * Constructs a unique deduplication key for a missing ghost profile based on
     * source sheet, relation field, name, and 35-year generational bucket.
     *
     * @param {Object} n - Source person node
     * @param {string} field - Relational field ('mom', 'father', or 'spouse')
     * @param {string} lowerName - Normalized lowercase name
     * @returns {string} Unique ghost map cache key
     *
     * @example
     * const key1 = FamilyTreeBuilder._buildMissingGhostKey({ yob: 1970, _sourceId: 's1' }, 'mom', 'mary');
     *
     * @example
     * const key2 = FamilyTreeBuilder._buildMissingGhostKey({ yob: 1940, _sourceId: 's2' }, 'father', 'thomas');
     */
    static _buildMissingGhostKey(n, field, lowerName) {
        const genBucket = n.yob ? Math.floor(n.yob / 35) : 'unk';
        const relSourceSheet = ((field === 'mom' && n._momSourceSheet) || (field === 'father' && n._fatherSourceSheet) || n._sourceId);
        return `${relSourceSheet}_${field}_${lowerName}_${genBucket}`;
    }

    /**
     * Merges source references, sheet rows, and originating relationship IDs from a source node
     * into an existing ghost profile.
     *
     * @param {Object} ghost - Existing ghost person node
     * @param {Object} n - Source person node
     * @param {string} field - Relational field ('mom', 'father', or 'spouse')
     *
     * @example
     * FamilyTreeBuilder._mergeSourceIntoGhost(existingGhost, sourceChild, 'mom');
     *
     * @example
     * FamilyTreeBuilder._mergeSourceIntoGhost(existingGhost, sourcePartner, 'spouse');
     */
    static _mergeSourceIntoGhost(ghost, n, field) {
        if (n._sourceId) ghost._sourceIds.add(n._sourceId);
        if (n._sheetRows) {
            Object.keys(n._sheetRows).forEach(sid => {
                if (!ghost._sheetRows[sid] || n._sheetRows[sid] < ghost._sheetRows[sid]) {
                    ghost._sheetRows[sid] = n._sheetRows[sid];
                }
            });
        }
        if (n._allSourceRefs) ghost._allSourceRefs.push(...n._allSourceRefs);
        if (field === 'mom' || field === 'father') {
            if (!ghost._originatingChildIds) ghost._originatingChildIds = [];
            if (!ghost._originatingChildIds.includes(n.id)) ghost._originatingChildIds.push(n.id);
        } else if (field === 'spouse') {
            if (!ghost._originatingSpouseIds) ghost._originatingSpouseIds = [];
            if (!ghost._originatingSpouseIds.includes(n.id)) ghost._originatingSpouseIds.push(n.id);
        }
    }

    /**
     * Generates implied ghost profiles for missing relational connections.
     *
     * @param {Object[]} nodes - Array of domain person nodes to inspect
     *
     * @example
     * builder.generateMissingProfiles(nodesList);
     *
     * @example
     * builder.generateMissingProfiles(builder.nodes);
     */
    generateMissingProfiles(nodes) {
        const newNodes = [];
        const ghostMap = new Map();
        nodes.forEach(n => {
            ['mom', 'father', 'spouse'].forEach(field => {
                const name = n[field];
                if (!name || isNaN(name) === false) return;
                const lowerName = name.toLowerCase().trim();
                const candidates = this._getCandidatesByName(name);
                
                const valid = candidates.filter(c => this._isValidCandidateForMissingProfile(c, n, field));

                if (valid.length === 0) {
                    const key = FamilyTreeBuilder._buildMissingGhostKey(n, field, lowerName);
                    if (!ghostMap.has(key)) {
                        ghostMap.set(key, this._instantiateGhost(n, name, field, key, newNodes));
                    } else {
                        FamilyTreeBuilder._mergeSourceIntoGhost(ghostMap.get(key), n, field);
                    }
                }
            });
        });
        nodes.push(...newNodes);
    }

    /**
     * Assigns unique default IDs and registers nodes in nodeMap and normalized name lookup arrays.
     *
     * @param {Object[]} nodes - Person nodes to index
     *
     * @example
     * builder.indexNodes([node1, node2]);
     *
     * @example
     * builder.indexNodes(rawImportedNodes);
     */
    indexNodes(nodes) {
        nodes.forEach(n => {
            n.id = n.id || `${n.name}_${n.yob || 'unk'}_${n._rawId}`.replace(/\s+/g, '_');
            this.nodeMap[n.id] = n;
            const lowerName = n._normName;
            if (!this.name2nodes[lowerName]) this.name2nodes[lowerName] = [];
            this.name2nodes[lowerName].push(n);
        });
    }

    /**
     * Filters name-matching candidate nodes against relationship-specific biological and parental bounds.
     *
     * @param {Object[]} candidates - Candidate person nodes matching identifier name
     * @param {Object} sourceNode - Context node searching for relation
     * @param {string} relationType - Relation role ('mother', 'father', 'spouse', etc.)
     * @returns {Object[]} Candidates that satisfy generational and marital constraints
     *
     * @example
     * const validP = builder._filterCandidatesByRelation(candidates, childNode, 'father');
     *
     * @example
     * const validS = builder._filterCandidatesByRelation(candidates, personNode, 'spouse');
     */
    _filterCandidatesByRelation(candidates, sourceNode, relationType) {
        return candidates.filter(c => {
            if (FamilyTreeBuilder._isParentRelation(relationType)) {
                if (!FamilyTreeBuilder._isValidParentCandidate(c, sourceNode, relationType, c._normName, this.nodeMap)) return false;
                return (c.yob || 0) <= (sourceNode.yob || 9999);
            }
            if (FamilyTreeBuilder._isSpouseRelation(relationType)) {
                return FamilyTreeBuilder._isValidSpouseCandidate(c, sourceNode, relationType, this.nodeMap);
            }
            return true;
        });
    }

    /**
     * Filters spouse candidates to those on the same sheet appearing on a higher row number
     * than the proposing source node (wife appearing after husband convention), selecting the closest.
     *
     * @param {Object[]} candidates - Candidate spouse Person nodes
     * @param {Object} sourceNode - Proposing person node
     * @returns {Object[]} Filtered candidate nodes, or original array if none qualify
     *
     * @example
     * const res = builder._filterClosestHigherRowSpouses([c1, c2], src);
     *
     * @example
     * const fallback = builder._filterClosestHigherRowSpouses([], src);
     */
    _filterClosestHigherRowSpouses(candidates, sourceNode) {
        const sameSheet = candidates.filter(c => FamilyTreeBuilder.sharesSheet(c, sourceNode));
        if (sameSheet.length <= 1) return candidates;

        const srcRow = FamilyTreeBuilder._getNodeEffectiveRow(sourceNode);
        if (srcRow >= 99999) return candidates;

        const higherRowCandidates = sameSheet.filter(c => {
            const cRow = FamilyTreeBuilder._getNodeEffectiveRow(c);
            return cRow > srcRow && cRow < 99999;
        });
        if (higherRowCandidates.length === 0) return candidates;

        const minHigherDist = Math.min(...higherRowCandidates.map(c => FamilyTreeBuilder._getMinRowDistance(c, sourceNode)));
        const closestHigher = higherRowCandidates.filter(c => FamilyTreeBuilder._getMinRowDistance(c, sourceNode) === minHigherDist);
        return closestHigher.length > 0 ? closestHigher : candidates;
    }

    /**
     * Filters candidate spouses by explicit or unassigned marriage declarations.
     * Prioritizes candidates with mutual spouse declarations; falls back to candidates not already taken.
     *
     * @param {Object[]} candidates - Candidate Person nodes
     * @param {string} sourceNameNorm - Normalized name of proposing source node
     * @returns {Object[]} Filtered candidate list
     *
     * @example
     * const mutual = builder._filterSpousesByDeclaration(cands, 'john');
     *
     * @example
     * const untaken = builder._filterSpousesByDeclaration(cands, 'mary');
     */
    _filterSpousesByDeclaration(candidates, sourceNameNorm) {
        // 1. Prefer mutually explicit spouses
        const mutuallyExplicit = candidates.filter(c => {
            const cSpouses = [c.spouse, ...(c._localImplicitSpouses || [])].filter(Boolean).map(s => s.toLowerCase().trim());
            return cSpouses.some(s => s === sourceNameNorm || s.includes(sourceNameNorm) || sourceNameNorm.includes(s));
        });
        if (mutuallyExplicit.length > 0) return mutuallyExplicit;

        // 2. Prefer candidates not already taken
        const notTaken = candidates.filter(c => {
            const cSpouses = [c.spouse, ...(c._localImplicitSpouses || [])].filter(Boolean).map(s => s.toLowerCase().trim());
            if (cSpouses.length === 0) return true;
            return !cSpouses.some(s => !(s === sourceNameNorm || s.includes(sourceNameNorm) || sourceNameNorm.includes(s)));
        });
        return notTaken.length > 0 ? notTaken : candidates;
    }

    /**
     * Filters candidate spouses to those with the closest birth year gap to the source node.
     *
     * @param {Object[]} candidates - Candidate Person nodes
     * @param {number} sourceYob - Birth year of proposing source node
     * @returns {Object[]} Filtered candidates within close proximity of the minimal age gap
     *
     * @example
     * const closest = builder._filterClosestAgeSpouses([cand1, cand2], 1948);
     *
     * @example
     * const noYob = builder._filterClosestAgeSpouses(cands, null);
     */
    _filterClosestAgeSpouses(candidates, sourceYob) {
        if (!sourceYob || candidates.length <= 1) return candidates;
        const sorted = [...candidates].sort((a, b) => {
            const gapA = a.yob ? Math.abs(a.yob - sourceYob) : 999;
            const gapB = b.yob ? Math.abs(b.yob - sourceYob) : 999;
            return gapB - gapA;
        });

        const bestMatch = sorted[sorted.length - 1];
        if (!bestMatch?.yob) return candidates;

        const bestGap = Math.abs(bestMatch.yob - sourceYob);
        return candidates.filter(c => !c.yob || Math.abs(c.yob - sourceYob) <= bestGap + 2);
    }

    /**
     * Disambiguates multiple candidate spouses through declarations, row proximity, and age alignment.
     *
     * @param {Object[]} matches - Candidate spouse nodes
     * @param {Object} sourceNode - Seeking person node
     * @returns {Object[]} Filtered and prioritized candidate matches
     *
     * @example
     * const best = builder._resolveSpouseAmbiguity([c1, c2], source);
     *
     * @example
     * const single = builder._resolveSpouseAmbiguity([c1], source);
     */
    _resolveSpouseAmbiguity(matches, sourceNode) {
        let bestMatches = this._filterSpousesByDeclaration(matches, sourceNode._normName);

        // 2.5 Prefer adjacent row candidates on the same sheet (dist <= 3)
        if (bestMatches.length > 1) {
            const adjacent = bestMatches.filter(c => 
                FamilyTreeBuilder.sharesSheet(c, sourceNode) && 
                FamilyTreeBuilder._getMinRowDistance(c, sourceNode) <= 3
            );
            if (adjacent.length > 0) {
                bestMatches = adjacent;
            }
        }

        // 2.6 Prefer candidate on same sheet with higher row number (wife appearing after husband) if closest
        if (bestMatches.length > 1) {
            bestMatches = this._filterClosestHigherRowSpouses(bestMatches, sourceNode);
        }

        // 3. Prefer closest age gap
        if (bestMatches.length > 1 && sourceNode.yob) {
            bestMatches = this._filterClosestAgeSpouses(bestMatches, sourceNode.yob);
        }
        return bestMatches;
    }

    /**
     * Retrieves the known co-parent node for a child when searching for a complementary parent.
     *
     * When seeking a father, looks for a known mother; when seeking a mother, looks for a known father.
     * Evaluates explicit parent IDs (momId / fatherId) as well as named parent anchor IDs.
     *
     * @param {Object} child - Child Person node
     * @param {string} relationType - Target parent relation ('father' or 'mother')
     * @returns {Object|null} Known co-parent Person node if found in nodeMap
     *
     * @example
     * const coMom = builder._getKnownCoParent(childNode, 'father');
     *
     * @example
     * const coDad = builder._getKnownCoParent(childNode, 'mother');
     */
    _getKnownCoParent(child, relationType) {
        if (!child) return null;
        let pId = null;
        if (relationType === 'father') {
            pId = child.momId || (child._namedParentId && this.nodeMap[child._namedParentId]?.gender === 'F' ? child._namedParentId : null);
        } else if (relationType === 'mother') {
            pId = child.fatherId || (child._namedParentId && this.nodeMap[child._namedParentId]?.gender === 'M' ? child._namedParentId : null);
        }
        return pId ? (this.nodeMap[pId] || null) : null;
    }

    /**
     * Resolves parental candidate ambiguity by prioritizing candidates already partnered with the known co-parent.
     *
     * @param {Array<Object>} matches - Ambiguous candidates
     * @param {Object} sourceNode - Child seeking parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Array<Object>|null} Resolved match wrapped in single-element array, or null
     *
     * @example
     * const res = builder._resolveByCoParentPartner([m1, m2], child, 'mother');
     *
     * @example
     * const none = builder._resolveByCoParentPartner([f1, f2], child, 'father');
     */
    _resolveByCoParentPartner(matches, sourceNode, relationType) {
        const coParent = this._getKnownCoParent(sourceNode, relationType);
        if (coParent?.partners?.length > 0) {
            const partnerCand = matches.find(c => coParent.partners.includes(c.id));
            if (partnerCand) {
                const res = [partnerCand];
                res._parentResolved = true;
                return res;
            }
        }
        return null;
    }

    /**
     * Finds a candidate among matches that corresponds to an already resolved parent of a preceding sibling.
     *
     * @private
     * @param {Array<Object>} precedingSiblings - Preceding sibling nodes sorted by row proximity descending
     * @param {Array<Object>} matches - Candidate parent profiles
     * @param {boolean} isMom - Whether resolving a mother relation
     * @param {boolean} isDad - Whether resolving a father relation
     * @returns {Array<Object>|null} Reordered matches with resolved parent at the end, or null
     *
     * @example
     * const sibs = [{ momId: 'm1' }];
     * const cands = [{ id: 'm1', name: 'Mary' }, { id: 'm2', name: 'Molly' }];
     * FamilyTreeBuilder._findSiblingParentCandidate(sibs, cands, true, false);
     * // => [{ id: 'm2', name: 'Molly' }, { id: 'm1', name: 'Mary' }]
     *
     * @example
     * const sibs = [{ momId: 'other' }];
     * const cands = [{ id: 'm1', name: 'Mary' }];
     * FamilyTreeBuilder._findSiblingParentCandidate(sibs, cands, true, false);
     * // => null
     */
    static _findSiblingParentCandidate(precedingSiblings, matches, isMom, isDad) {
        for (const sib of precedingSiblings) {
            const sibParentId = isMom ? sib.momId : (isDad ? sib.fatherId : null);
            if (!sibParentId) continue;
            const sibParentCand = matches.find(c => c.id === sibParentId);
            if (sibParentCand) {
                const otherMatches = matches.filter(c => c.id !== sibParentId);
                const result = [...otherMatches, sibParentCand];
                result._parentResolved = true;
                return result;
            }
        }
        return null;
    }

    /**
     * Collects a child's sibling block: the same-sheet rows that declare the very
     * same parent name for the same relation.
     *
     * The declared name is what matters, not the resolved link — the whole point is
     * to reason about the block before any of its rows have been resolved.
     *
     * @param {Object} sourceNode - Child seeking a parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Array<Object>} Sibling rows, excluding sourceNode itself
     *
     * @example
     * // Kuttiyamma, Mary, George, Kuttappan, Baby, Theyyama and Alice all list
     * // Mother: Mariyakkutty, so asking from any one of them returns the other six.
     * builder._findDeclaredParentBlock(kuttiyamma, 'mother').length;
     * // => 6
     *
     * @example
     * builder._findDeclaredParentBlock({ mom: '' }, 'mother');
     * // => []
     */
    _findDeclaredParentBlock(sourceNode, relationType) {
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        const isDad = FamilyTreeBuilder._isFatherRelation(relationType);
        const declaredParent = (n) => FamilyTreeBuilder._normText(isMom ? n.mom : (isDad ? n.father : ''));

        const target = declaredParent(sourceNode);
        if (!target) return [];

        return Object.values(this.nodeMap).filter(s =>
            s && s !== sourceNode &&
            FamilyTreeBuilder.sharesSheet(s, sourceNode) &&
            declaredParent(s) === target
        );
    }

    /**
     * Resolves a namesake mother by the family name her children are known to carry.
     *
     * Two women on one sheet can share a name, and the child asking for her may
     * record nothing that tells them apart. Her *siblings* often do: a child takes
     * his father's family patrilineally, so a family name declared anywhere in the
     * sibling block points straight at the husband, and therefore at the wife.
     *
     * This runs ahead of every age-based tie-break on purpose. Otherwise the
     * biological floor `MIN_PARENTAL_AGE` ends up silently doing entity resolution:
     * lower it by a single year and a whole family re-links itself.
     *
     * @param {Array<Object>} matches - Ambiguous candidates
     * @param {Object} sourceNode - Child seeking parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Array<Object>|null} Reordered matches with the corroborated mother last, or null
     *
     * @example
     * // Kuttiyamma names only "Mother: Mariyakkutty", but her brother George
     * // carries Family: Parathottiyil — the family of Thomas, husband of exactly
     * // one of the two Mariyakkuttys. The other is married to a Kadalikkaattil.
     * builder._resolveBySiblingBlockFamily([mariyakkuttyB, mariyakkuttyA], kuttiyamma, 'mother');
     * // => [mariyakkuttyB, mariyakkuttyA]  (A wins, _parentResolved set)
     *
     * @example
     * // No family name anywhere in the block, so nothing is corroborated.
     * builder._resolveBySiblingBlockFamily([m1, m2], childWithoutFamily, 'mother');
     * // => null
     */
    _resolveBySiblingBlockFamily(matches, sourceNode, relationType) {
        if (!FamilyTreeBuilder._isMotherRelation(relationType)) return null;

        const block = [sourceNode, ...this._findDeclaredParentBlock(sourceNode, relationType)];
        const declared = new Set(block.map(s => (s.family || '').toLowerCase().trim()).filter(Boolean));
        if (declared.size === 0) return null;

        const corroborated = matches.filter(c =>
            [...FamilyTreeBuilder._collectSpouseFamilies(c, this.nodeMap)].some(f => declared.has(f))
        );
        if (corroborated.length !== 1) return null;

        const winner = corroborated[0];
        const result = [...matches.filter(c => c !== winner), winner];
        result._parentResolved = true;
        return result;
    }

    /**
     * Resolves parental candidate ambiguity by aligning with the parent assigned to preceding siblings.
     *
     * Inspects earlier rows on the same sheet that share the same declared parent name.
     *
     * @param {Array<Object>} matches - Ambiguous candidates
     * @param {Object} sourceNode - Child seeking parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Array<Object>|null} Reordered matches with sibling's parent as winner, or null
     *
     * @example
     * const sibWin = builder._resolveByPrecedingSibling([m1, m2], child, 'mother');
     *
     * @example
     * const noSib = builder._resolveByPrecedingSibling([f1, f2], singleChild, 'father');
     */
    _resolveByPrecedingSibling(matches, sourceNode, relationType) {
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        const isDad = FamilyTreeBuilder._isFatherRelation(relationType);

        const sRow = FamilyTreeBuilder._getNodeEffectiveRow(sourceNode);
        const precedingSiblings = this._findDeclaredParentBlock(sourceNode, relationType)
            .filter(s => FamilyTreeBuilder._getNodeEffectiveRow(s) < sRow)
            .sort((a, b) => FamilyTreeBuilder._getNodeEffectiveRow(b) - FamilyTreeBuilder._getNodeEffectiveRow(a));

        return FamilyTreeBuilder._findSiblingParentCandidate(precedingSiblings, matches, isMom, isDad);
    }

    /**
     * Ranks multiple parent candidates by biological generational fitness and row proximity.
     *
     * @param {Array<Object>} matches - Multiple eligible candidates
     * @param {Object} sourceNode - Child node seeking parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Array<Object>} Sorted candidates with highest ranking candidate placed at end (winner)
     *
     * @example
     * const rankedP = builder._rankByGenerationalFitness([p1, p2], child, 'father');
     *
     * @example
     * const rankedM = builder._rankByGenerationalFitness([m1, m2], child, 'mother');
     */
    _rankByGenerationalFitness(matches, sourceNode, relationType) {
        const sYob = FamilyTreeBuilder._effectiveYob(sourceNode);
        if (!sYob) return matches;

        const idealGap = FamilyTreeBuilder._isMotherRelation(relationType) ? 26 : 30;
        const gapDistance = (candidate) => {
            const cYob = FamilyTreeBuilder._effectiveYob(candidate);
            const gap = cYob ? (sYob - cYob) : 999;
            return Math.abs(gap - idealGap);
        };

        matches.sort((a, b) => {
            const diff = gapDistance(b) - gapDistance(a);
            if (diff !== 0) return diff;
            return FamilyTreeBuilder._getMinRowDistance(a, sourceNode)
                 - FamilyTreeBuilder._getMinRowDistance(b, sourceNode);
        });

        if (matches.length >= 2) {
            const bestDist = gapDistance(matches[matches.length - 1]);
            const secondDist = gapDistance(matches[matches.length - 2]);
            // Lock in the best parent candidate when its generational gap fitness beats the runner-up by > 5 years.
            if (bestDist < secondDist && secondDist - bestDist > FamilyTreeBuilder.GENERATIONAL_GAPS.PARENT_RESOLUTION_MARGIN_YEARS) {
                matches._parentResolved = true;
            }
        }
        return matches;
    }

    /**
     * Picks a winner among several same-named parent candidates.
     *
     * Returns the candidates worst-first, so `findPerson` takes the LAST element.
     * When the decision is firm, `_parentResolved` is set on the returned array to
     * stop the later row-proximity sort from undoing it.
     *
     * @param {Object[]} matches - Candidate parent nodes
     * @param {Object} sourceNode - The child node seeking a parent
     * @param {string} relationType - 'mother' or 'father'
     * @returns {Object[]} Sorted candidates with worst-fit first, best-fit last
     *
     * @example
     * const res1 = builder._resolveParentAmbiguity([cand1, cand2], child, 'father');
     *
     * @example
     * const res2 = builder._resolveParentAmbiguity([mom1, mom2], child, 'mother');
     */
    _resolveParentAmbiguity(matches, sourceNode, relationType) {
        if (matches.length <= 1 || !sourceNode) return matches;

        // Strongest first. Evidence the sheet actually states — the child's own
        // other parent, then the family name carried by the sibling block — beats
        // the propagate-what-the-last-sibling-chose rule, which merely spreads
        // whichever guess was made first. Age fitness is the last resort: it is a
        // heuristic, and letting it decide makes biological constants double as
        // entity resolution.
        const byCoParent = this._resolveByCoParentPartner(matches, sourceNode, relationType);
        if (byCoParent) return byCoParent;

        const byFamily = this._resolveBySiblingBlockFamily(matches, sourceNode, relationType);
        if (byFamily) return byFamily;

        const bySibling = this._resolveByPrecedingSibling(matches, sourceNode, relationType);
        if (bySibling) return bySibling;

        return this._rankByGenerationalFitness(matches, sourceNode, relationType);
    }

    /**
     * Resolves an already-bound parent, named anchor, or known co-parent's partner before sweeping candidates.
     *
     * @param {string} identifier - Requested name/ID
     * @param {Object|null} sourceNode - Seeking Person node
     * @param {string} relationType - 'mother', 'father', or 'parent'
     * @returns {Object|null} Matching Person node if pre-bound, otherwise null
     *
     * @example
     * const prebound = builder._resolvePreboundParentOrPartner('Joseph', child, 'father');
     *
     * @example
     * const partner = builder._resolvePreboundParentOrPartner('Joy', child, 'father');
     */
    _resolvePreboundParentOrPartner(identifier, sourceNode, relationType) {
        if (!sourceNode || (relationType !== 'mother' && relationType !== 'father' && relationType !== 'parent')) {
            return null;
        }
        const normId = identifier.toLowerCase().trim();
        const matchesName = (pId) => {
            const p = pId ? this.nodeMap[pId] : null;
            return (p && p.name && p.name.toLowerCase().trim() === normId) ? p : null;
        };

        const prebound = matchesName(sourceNode._namedParentId) ||
            (relationType === 'father' && matchesName(sourceNode.fatherId)) ||
            (relationType === 'mother' && matchesName(sourceNode.momId));
        if (prebound) return prebound;

        const coParent = this._getKnownCoParent(sourceNode, relationType);
        if (coParent?.partners?.length > 0) {
            const partner = coParent.partners.map(id => this.nodeMap[id]).find(p => p && p.name && p.name.toLowerCase().trim() === normId);
            if (partner) return partner;
        }

        return null;
    }

    /**
     * Builds a normalized summary record for an ambiguity candidate in tree audit logs.
     *
     * @param {Object} candidate - Candidate Person node
     * @param {string|null} selectedId - Node ID of candidate chosen as winner
     * @returns {Object} Serialized candidate metadata
     *
     * @example
     * const rec1 = FamilyTreeBuilder._buildAmbiguityCandidateRecord(candNode, 'P1');
     *
     * @example
     * const rec2 = FamilyTreeBuilder._buildAmbiguityCandidateRecord(candNode, null);
     */
    static _buildAmbiguityCandidateRecord(candidate, selectedId) {
        const sRow = FamilyTreeBuilder._getNodeEffectiveRow(candidate);
        return {
            id: candidate.id,
            name: candidate.name,
            yob: candidate.yob,
            death: candidate.death,
            sheetId: candidate._sourceId || (candidate._allSourceRefs && candidate._allSourceRefs[0]?.sheetId) || 'default',
            sheetRow: sRow < 99999 ? sRow : null,
            isSelected: selectedId ? (candidate.id === selectedId) : false
        };
    }

    /**
     * Filters candidate matches preferring same-sheet candidates and concrete non-ghost profiles.
     *
     * @param {Array<Object>} validCandidates - Available candidates
     * @param {Object} sourceNode - Reference person node
     * @returns {Array<Object>} Filtered candidate list
     *
     * @example
     * FamilyTreeBuilder._filterSameSheetAndRealCandidates([ghostNode, realNode], sourceNode);
     *
     * @example
     * FamilyTreeBuilder._filterSameSheetAndRealCandidates([], sourceNode);
     */
    static _filterSameSheetAndRealCandidates(validCandidates, sourceNode) {
        let matches = validCandidates.filter(c => FamilyTreeBuilder.sharesSheet(c, sourceNode));
        if (matches.length === 0) matches = validCandidates;
        if (matches.length > 1) {
            const real = matches.filter(c => !c.isGhost);
            if (real.length > 0) matches = real;
        }
        return matches;
    }

    /**
     * Sorts candidate matches by sheet row distance so the nearest candidate is placed last.
     *
     * @param {Array<Object>} candidates - Candidate matches to sort
     * @param {Object} sourceNode - Reference person node
     *
     * @example
     * FamilyTreeBuilder._sortCandidatesByRowDistance([c1, c2], sourceNode);
     *
     * @example
     * FamilyTreeBuilder._sortCandidatesByRowDistance([], sourceNode);
     */
    static _sortCandidatesByRowDistance(candidates, sourceNode) {
        candidates.sort((a, b) => {
            const distA = FamilyTreeBuilder._getMinRowDistance(a, sourceNode);
            const distB = FamilyTreeBuilder._getMinRowDistance(b, sourceNode);
            if ((distA < 9999 || distB < 9999) && distA !== distB) {
                return distB - distA;
            }
            return 0;
        });
    }

    /**
     * Narrows valid candidates to the best matches using sheet sharing, ghost exclusion,
     * relationship-specific ambiguity resolution, and row distance ranking.
     * 
     * @param {Object[]} validCandidates - Relationship-compatible candidates
     * @param {Object} sourceNode - Person referencing the relation
     * @param {string} relationType - Role relation ('mother', 'father', 'spouse', etc.)
     * @returns {Object[]} Winnowed best matches sorted with winner at the end
     * 
     * @example
     * const matches = builder._narrowCandidateMatches([c1, c2], source, 'spouse');
     *
     * @example
     * const pMatches = builder._narrowCandidateMatches([p1, p2], child, 'father');
     */
    _narrowCandidateMatches(validCandidates, sourceNode, relationType) {
        let bestMatches = FamilyTreeBuilder._filterSameSheetAndRealCandidates(validCandidates, sourceNode);

        if (FamilyTreeBuilder._isSpouseRelation(relationType)) {
            if (bestMatches.length > 1) bestMatches = this._resolveSpouseAmbiguity(bestMatches, sourceNode);
        }

        if (FamilyTreeBuilder._isParentRelation(relationType)) {
            bestMatches = this._resolveParentAmbiguity(bestMatches, sourceNode, relationType);
        }

        if (bestMatches.length > 1 && !bestMatches._parentResolved) {
            FamilyTreeBuilder._sortCandidatesByRowDistance(bestMatches, sourceNode);
        }
        return bestMatches;
    }

    /**
     * Records an ambiguity entry on the source node when multiple valid candidates exist.
     * 
     * @param {Object} sourceNode - Reference person node
     * @param {string} identifier - Searched name/identifier
     * @param {string} relationType - Relation role
     * @param {Object[]} candidates - Candidate matches
     * @param {Object|null} [selected=null] - Preferred/winning candidate
     * 
     * @example
     * builder._recordAmbiguityEntry(source, 'Mary', 'mother', [m1, m2], m2);
     *
     * @example
     * builder._recordAmbiguityEntry(source, 'John', 'father', [f1, f2]);
     */
    _recordAmbiguityEntry(sourceNode, identifier, relationType, candidates, selected = null) {
        if (candidates.length <= 1) return;
        const targetSelected = selected || candidates[candidates.length - 1];
        sourceNode.ambiguities.push({
            query: identifier,
            relation: relationType,
            message: `Found ${candidates.length} candidates for ${relationType} '${identifier}'`,
            selectedId: targetSelected ? targetSelected.id : null,
            candidates: candidates.map(c => FamilyTreeBuilder._buildAmbiguityCandidateRecord(c, targetSelected ? targetSelected.id : null))
        });
    }

    /**
     * Scopes candidate list to matching source sheets based on parental or domain node provenance.
     * 
     * @param {Object[]} candidates - Unfiltered candidate nodes
     * @param {Object} sourceNode - Reference person node
     * @param {string} relationType - Relation type ('mother', 'father', 'parent', etc.)
     * @returns {Object[]} Sheet-scoped candidates
     *
     * @example
     * const scoped = builder._scopeCandidatesToSheet(candidates, child, 'mother');
     *
     * @example
     * const general = builder._scopeCandidatesToSheet(candidates, person, 'spouse');
     */
    _scopeCandidatesToSheet(candidates, sourceNode, relationType) {
        const isMom = FamilyTreeBuilder._isMotherRelation(relationType);
        const isDad = FamilyTreeBuilder._isFatherRelation(relationType);
        if (isMom || isDad) {
            const sheets = isMom ? sourceNode._momSourceSheets : sourceNode._fatherSourceSheets;
            const singleSheet = isMom ? sourceNode._momSourceSheet : sourceNode._fatherSourceSheet;
            if (sheets && sheets.size > 0) {
                return candidates.filter(c => c._sourceIds && Array.from(sheets).some(sid => c._sourceIds.has(sid)));
            } else if (singleSheet) {
                return candidates.filter(c => c._sourceIds && c._sourceIds.has(singleSheet));
            } else {
                return candidates.filter(c => FamilyTreeBuilder.sharesSheet(c, sourceNode));
            }
        } else if (relationType === 'parent') {
            return candidates.filter(c => FamilyTreeBuilder.sharesSheet(c, sourceNode));
        }
        return candidates;
    }

    /**
     * Filters candidate list for parental relationships to prioritize concrete (non-ghost) persons over ghosts.
     * 
     * @param {Object[]} candidates - Candidate person nodes
     * @param {string} relationType - Relationship identifier ('mother', 'father', 'parent', etc.)
     * @returns {Object[]} Filtered candidate list
     *
     * @example
     * const concrete = FamilyTreeBuilder._preferConcreteCandidates([realDad, ghostDad], 'father');
     *
     * @example
     * const childList = FamilyTreeBuilder._preferConcreteCandidates([ghostChild], 'child');
     */
    static _preferConcreteCandidates(candidates, relationType) {
        if (FamilyTreeBuilder._isParentRelation(relationType)) {
            const concrete = candidates.filter(c => !c.isGhost);
            if (concrete.length > 0) return concrete;
        }
        return candidates;
    }

    /**
     * Determines whether multiple spousal candidates are disambiguated by a unique candidate in close row proximity.
     * 
     * @param {Object[]} validCandidates - Valid candidate nodes
     * @param {Object} sourceNode - Context node searching for spouse
     * @param {string} relationType - Relationship identifier ('spouse', 'wife', 'husband', 'partner')
     * @returns {boolean} True if exactly one candidate is in close proximity
     *
     * @example
     * const isRes = FamilyTreeBuilder._isSpouseResolvedByProximity([cNear, cFar], source, 'wife');
     *
     * @example
     * const notSpouse = FamilyTreeBuilder._isSpouseResolvedByProximity([p1, p2], source, 'father');
     */
    static _isSpouseResolvedByProximity(validCandidates, sourceNode, relationType) {
        const isSpouseRelation = ['spouse', 'husband', 'wife', 'partner'].includes(relationType);
        if (!isSpouseRelation) return false;
        const maxClosebyDistance = FamilyTreeBuilder.GENERATIONAL_GAPS?.MAX_ROW_NEIGHBOR_DISTANCE || 5;
        const closebySpouseCandidates = validCandidates.filter(c => 
            FamilyTreeBuilder.sharesSheet(c, sourceNode) && 
            FamilyTreeBuilder._getMinRowDistance(c, sourceNode) <= maxClosebyDistance
        );
        return closebySpouseCandidates.length === 1;
    }

    /**
     * Resolves and filters unique matching candidate nodes for a relationship query.
     *
     * @param {string} identifier - Name or identifier of relative
     * @param {Object} sourceNode - Reference node seeking relative
     * @param {string} relationType - Relation ('mother', 'father', or 'spouse')
     * @returns {Object[]|null} Filtered list of valid candidates, or null if none remain
     *
     * @example
     * builder._resolveValidCandidates('Mary', childNode, 'mother');
     * // returns [maryNode]
     *
     * @example
     * builder._resolveValidCandidates('NonExistent', childNode, 'father');
     * // returns null
     */
    _resolveValidCandidates(identifier, sourceNode, relationType) {
        let candidates = Array.from(new Map(this._getCandidatesByName(identifier).map(c => [c.id, c])).values());
        if (candidates.length === 0) return null;

        candidates = this._scopeCandidatesToSheet(candidates, sourceNode, relationType);
        if (candidates.length === 0) return null;

        let validCandidates = this._filterCandidatesByRelation(candidates, sourceNode, relationType);
        if (validCandidates.length === 0) return null;

        return FamilyTreeBuilder._preferConcreteCandidates(validCandidates, relationType);
    }

    /**
     * Resolves a named or identified person relative to a source node and relational role.
     * Evaluates prebound relations, sheet scoping, biological constraints, ambiguity resolution, and row proximity.
     *
     * @param {string} identifier - Name or person identifier to look up
     * @param {Object} sourceNode - Context node requesting the lookup
     * @param {string} relationType - Role relation ('mother', 'father', 'spouse', etc.)
     * @returns {Object|null} Resolved Person node or null if not found
     *
     * @example
     * const mom = builder.findPerson('Mary', childNode, 'mother');
     *
     * @example
     * const spouse = builder.findPerson('John', wifeNode, 'spouse');
     */
    findPerson(identifier, sourceNode, relationType) {
        if (!identifier) return null;
        if (this.nodeMap[identifier]) return this.nodeMap[identifier]; 

        const prebound = this._resolvePreboundParentOrPartner(identifier, sourceNode, relationType);
        if (prebound) return prebound;
        
        const validCandidates = this._resolveValidCandidates(identifier, sourceNode, relationType);
        if (!validCandidates) return null;

        const bestMatches = this._narrowCandidateMatches(validCandidates, sourceNode, relationType);
        const winner = bestMatches.length > 0 ? bestMatches[bestMatches.length - 1] : null;

        const isSpouseResolvedByProximity = FamilyTreeBuilder._isSpouseResolvedByProximity(validCandidates, sourceNode, relationType);

        if (validCandidates.length > 1 && !isSpouseResolvedByProximity && !sourceNode.ambiguities.some(a => a.query === identifier && a.relation === relationType)) {
            this._recordAmbiguityEntry(sourceNode, identifier, relationType, validCandidates, winner);
        }
        
        return winner; 
    }
   /**
     * Resolves and establishes bidirectional edges for spouses and parent-child lineages.
     * 
     * @param {Object[]} nodes - List of domain nodes
     * 
     * @example
     * builder.linkRelationships(nodes);
     *
     * @example
     * builder.linkRelationships(allTreeNodes);
     */
    linkRelationships(nodes) {
        this._linkSpouses(nodes);
        this._linkParents(nodes);
    }

    /**
     * Determines if a target spouse candidate already has a significantly better partner
     * (closer in age on the same sheet) than the proposing candidate.
     *
     * @param {Object} from - Proposing person node
     * @param {Object} to - Target candidate node
     * @param {number} gap - Age gap between from and to in years
     * @returns {boolean} True if target node already has a much better partner
     *
     * @example
     * const better = builder._hasBetterPartner(husbandNode, wifeNode, 15);
     *
     * @example
     * const single = builder._hasBetterPartner(husbandNode, unmarriedWifeNode, 2);
     */
    _hasBetterPartner(from, to, gap) {
        if (to.partners.length === 0) return false;
        if (!FamilyTreeBuilder.sharesSheet(from, to)) return true;

        const isAdjacentCoSpouse = to.partners.some(pId => {
            const ep = this.nodeMap[pId];
            return ep && FamilyTreeBuilder._getMinRowDistance(from, ep) <= 3;
        });
        const isCloseInSheet = isAdjacentCoSpouse || FamilyTreeBuilder._getMinRowDistance(from, to) < FamilyTreeBuilder.GENERATIONAL_GAPS.MAX_ROW_NEIGHBOR_DISTANCE;
        if (!isCloseInSheet) {
            for (const pId of to.partners) {
                const ep = this.nodeMap[pId];
                if (ep && ep.yob && to.yob) {
                    const eg = Math.abs(ep.yob - to.yob);
                    if (eg < gap - 8 && gap > 12) return true;
                }
            }
        }
        return false;
    }

    /**
     * Collects directed candidate spouse proposals from explicit spouse strings on nodes.
     * Computes the age gap between proposing and target partner, accounting for adjacent co-spouses.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @returns {{ proposals: Array<{ from: Object, to: Object, gap: number }>, proposalMap: Map<string, Set<string>> }}
     *
     * @example
     * const { proposals, proposalMap } = builder._collectSpouseProposals(nodes);
     *
     * @example
     * const res = builder._collectSpouseProposals([person1, person2]);
     */
    _collectSpouseProposals(nodes) {
        const proposals = [];
        const proposalMap = new Map();
        const allNodes = Object.values(this.nodeMap || {});

        nodes.forEach(n => {
            if (!n.spouse) return;
            const spouseNode = this.findPerson(n.spouse, n, n.spouseType || 'spouse');
            if (!spouseNode) return;

            const gap = (n.yob && spouseNode.yob)
                ? Math.abs(n.yob - spouseNode.yob)
                : (FamilyTreeBuilder._isAdjacentCoSpouse(spouseNode, n, allNodes) ? 5 : 999);

            proposals.push({ from: n, to: spouseNode, gap });
            if (!proposalMap.has(n.id)) proposalMap.set(n.id, new Set());
            proposalMap.get(n.id).add(spouseNode.id);
        });

        return { proposals, proposalMap };
    }

    /**
     * Links mutually consenting spouse proposals (A proposes B and B proposes A) bidirectionally.
     *
     * @param {Array<{ from: Object, to: Object, gap: number }>} proposals - Directed marriage proposals
     * @param {Function} isMutual - Predicate (aId, bId) => boolean
     *
     * @example
     * builder._linkMutualSpouseProposals(props, (a, b) => map.get(a)?.has(b));
     *
     * @example
     * builder._linkMutualSpouseProposals([], () => true);
     */
    _linkMutualSpouseProposals(proposals, isMutual) {
        proposals.forEach(p => {
            if (isMutual(p.from.id, p.to.id)) {
                if (!p.from.partners.includes(p.to.id)) p.from.partners.push(p.to.id);
                if (!p.to.partners.includes(p.from.id)) p.to.partners.push(p.from.id);
            }
        });
    }

    /**
     * Filters for non-mutual proposals and orders them prioritizing same-sheet proximity,
     * lowest age gap, and smallest spreadsheet row distance.
     *
     * @param {Array<{ from: Object, to: Object, gap: number }>} proposals - Directed marriage proposals
     * @param {Function} isMutual - Predicate (aId, bId) => boolean
     * @returns {Array<{ from: Object, to: Object, gap: number }>} Sorted one-way proposals
     *
     * @example
     * const sorted = builder._sortOneWaySpouseProposals(props, (a, b) => false);
     *
     * @example
     * const empty = builder._sortOneWaySpouseProposals([], () => true);
     */
    _sortOneWaySpouseProposals(proposals, isMutual) {
        return proposals.filter(p => !isMutual(p.from.id, p.to.id)).sort((a, b) => {
            const aShares = FamilyTreeBuilder.sharesSheet(a.from, a.to) ? 0 : 1;
            const bShares = FamilyTreeBuilder.sharesSheet(b.from, b.to) ? 0 : 1;
            if (aShares !== bShares) return aShares - bShares;
            if (a.gap !== b.gap) return a.gap - b.gap;
            return FamilyTreeBuilder._getMinRowDistance(a.from, a.to) - FamilyTreeBuilder._getMinRowDistance(b.from, b.to);
        });
    }

    /**
     * Resolves bidirectional edges for married partners across mutual and one-way proposals.
     *
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._linkSpouses(nodesList);
     *
     * @example
     * builder._linkSpouses([husband, wife]);
     */
    _linkSpouses(nodes) {
        const { proposals, proposalMap } = this._collectSpouseProposals(nodes);
        const isMutual = (aId, bId) => proposalMap.get(aId)?.has(bId) && proposalMap.get(bId)?.has(aId);

        this._linkMutualSpouseProposals(proposals, isMutual);
        const oneWay = this._sortOneWaySpouseProposals(proposals, isMutual);
        this._resolveOneWaySpouseProposals(oneWay);
    }

    /**
     * Checks if a person already has an existing partner with the same normalized name.
     * Prevents duplicate namesake partner links.
     *
     * @param {Object} from - Proposing node
     * @param {Object} to - Target spouse candidate
     * @returns {boolean} True if a partner with the same name already exists
     *
     * @example
     * const exists = builder._hasPartnerWithSameName(person, candidateWife);
     *
     * @example
     * const fresh = builder._hasPartnerWithSameName(person, newPartnerNode);
     */
    _hasPartnerWithSameName(from, to) {
        const toNameNorm = (to._normName || to.name || '').toLowerCase().trim();
        return from.partners.some(pid => {
            const ep = this.nodeMap[pid];
            return ep && (ep._normName || ep.name || '').toLowerCase().trim() === toNameNorm;
        });
    }

    /**
     * Determines whether a female partner is already claimed by a closer spouse on the same sheet.
     * Enforces that on the same sheet, a woman is not claimed by multiple men unless explicitly declared.
     *
     * @param {Object} to - Target candidate spouse
     * @param {Object} from - Proposing person node
     * @returns {boolean} True if candidate already has a closer partner on the same sheet
     *
     * @example
     * const closer = builder._hasCloserSameSheetPartner(wifeNode, husbandNode);
     *
     * @example
     * const ok = builder._hasCloserSameSheetPartner(unclaimedWife, husbandNode);
     */
    _hasCloserSameSheetPartner(to, from) {
        if (!((to.gender === 'F' || to.spouseType === 'husband') && to.partners.length > 0 && !to.spouse?.includes(','))) {
            return false;
        }
        const distFrom = FamilyTreeBuilder._getMinRowDistance(from, to);
        return to.partners.some(pid => {
            const ep = this.nodeMap[pid];
            if (!ep || !FamilyTreeBuilder.sharesSheet(ep, from)) return false;
            const distEp = FamilyTreeBuilder._getMinRowDistance(ep, to);
            return distEp <= 2 && distEp < distFrom;
        });
    }

    /**
     * Resolves asymmetric (one-way) spouse proposals in order of sheet proximity,
     * age compatibility, and spreadsheet row distance, enforcing single-spouse exclusivity.
     *
     * @param {Object[]} oneWay - Sorted one-way spouse proposals
     *
     * @example
     * builder._resolveOneWaySpouseProposals([{ from: husband, to: wife, gap: 2 }]);
     *
     * @example
     * builder._resolveOneWaySpouseProposals([]);
     */
    _resolveOneWaySpouseProposals(oneWay) {
        oneWay.forEach(p => {
            const { from, to, gap } = p;
            if (this._hasPartnerWithSameName(from, to)) return;
            if (this._hasCloserSameSheetPartner(to, from)) return;

            if (!this._hasBetterPartner(from, to, gap)) {
                if (!from.partners.includes(to.id)) from.partners.push(to.id);
                if (!to.partners.includes(from.id)) to.partners.push(from.id);
            }
        });
    }

    /**
     * Checks if the generational age difference between a parent and child violates biological bounds.
     *
     * @param {?Object} pNode - Candidate parent node
     * @param {?Object} child - Child person node
     * @param {number} maxAge - Maximum plausible age at childbirth
     * @returns {boolean} True if the age gap violates parental limits
     *
     * @example
     * FamilyTreeBuilder._isParentAgeGapInvalid({ yob: 1900 }, { yob: 1980 }, 60);
     * // => true (gap 80 > 60)
     *
     * @example
     * FamilyTreeBuilder._isParentAgeGapInvalid({ yob: 1950 }, { yob: 1980 }, 60);
     * // => false (gap 30 is valid)
     */
    static _isParentAgeGapInvalid(pNode, child, maxAge) {
        if (!pNode || !pNode.yob || !child || !child.yob) return false;
        const gap = child.yob - pNode.yob;
        return gap < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE || gap > maxAge;
    }

    /**
     * Finds an alternative parent candidate if the existing resolved node is biologically invalid or a replaceable ghost.
     *
     * @param {string} parentName - Parent search name
     * @param {Object} child - Child node
     * @param {string} relType - 'mother' or 'father'
     * @param {?Object} pNode - Currently assigned candidate parent node
     * @param {number} maxAge - Maximum allowed childbirth age
     * @returns {?string} Alternative parent ID or current parent ID
     *
     * @example
     * builder._findBetterParentCandidate('Mary', child, 'mother', ghostMom, 55);
     * // => 'concrete_mary_123'
     *
     * @example
     * builder._findBetterParentCandidate('Joseph', child, 'father', validDad, 70);
     * // => validDad.id
     */
    _findBetterParentCandidate(parentName, child, relType, pNode, maxAge) {
        if (FamilyTreeBuilder._isParentAgeGapInvalid(pNode, child, maxAge)) {
            const ind = this.findPerson(parentName, child, relType);
            return ind ? ind.id : (pNode ? pNode.id : null);
        }
        if (pNode && pNode.isGhost) {
            const ind = this.findPerson(parentName, child, relType);
            if (ind && !ind.isGhost) return ind.id;
        }
        return pNode ? pNode.id : null;
    }

    /**
     * Resolves and validates a single parent (mother or father) ID for a child node.
     * 
     * Applies biological age bounds and family name constraints, falling back to
     * individual person search when group-resolved parent is invalid for this child.
     * 
     * @param {Object} child - Child node seeking parent link
     * @param {string} parentName - Raw parent name query (e.g. 'Mariyakkutty')
     * @param {string} relType - 'mother' or 'father'
     * @param {string|null} resolvedId - Group-level candidate parent ID
     * @param {boolean} foundExistingCouple - True if parents were pre-matched as a known married couple
     * @param {number} maxAge - Maximum allowed childbirth age
     * @returns {string|null} Validated parent node ID or null
     * 
     * @example
     * const momId = builder._resolveSingleParentLink(childNode, 'Mary', 'mother', 'Mary_1920', true, 55);
     *
     * @example
     * const dadId = builder._resolveSingleParentLink(childNode, 'Joseph', 'father', null, false, 70);
     */
    _resolveSingleParentLink(child, parentName, relType, resolvedId, foundExistingCouple, maxAge) {
        if (!parentName) return null;
        let useId = resolvedId;

        if (useId && child.yob && !foundExistingCouple) {
            useId = this._findBetterParentCandidate(parentName, child, relType, this.nodeMap[useId], maxAge);
        } else if (!useId) {
            const ind = this.findPerson(parentName, child, relType);
            if (ind) useId = ind.id;
        }

        if (useId) {
            const pNode = this.nodeMap[useId];
            if (pNode && !FamilyTreeBuilder._isValidParentCandidate(pNode, child, relType, parentName, this.nodeMap)) {
                const ind = this.findPerson(parentName, child, relType);
                useId = ind ? ind.id : null;
            }
        }

        return useId;
    }

    /**
     * Resolves the father node for a child/group representative, prioritizing the mother's
     * candidate spouse when available for ghost children.
     * 
     * @param {Object} rep - Child representative
     * @param {string|null} resolvedMomId - Resolved mother ID
     * @returns {Object|null} Father Person node if found
     *
     * @example
     * const dadNode = builder._resolveFatherNode(childRep, 'mom_123');
     *
     * @example
     * const dadFallback = builder._resolveFatherNode(childRep, null);
     */
    _resolveFatherNode(rep, resolvedMomId) {
        if (!rep.father) return null;
        let fatherNode = null;
        if (resolvedMomId) {
            const mom = this.nodeMap[resolvedMomId];
            if (mom) {
                if (mom.partners && mom.partners.length > 0) {
                    const pNorm = rep.father.toLowerCase().trim();
                    const partnerDad = mom.partners.map(id => this.nodeMap[id]).find(p => p && p.name.toLowerCase().trim() === pNorm);
                    if (partnerDad) return partnerDad;
                }
                if (rep.isGhost) {
                    fatherNode = this.findPerson(rep.father, mom, 'spouse');
                }
            }
        }
        if (!fatherNode) fatherNode = this.findPerson(rep.father, rep, 'father');
        return fatherNode;
    }

    /**
     * Groups sibling nodes by spreadsheet source ID and declared parent references.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @returns {Object.<string, Object[]>} Groups keyed by `${sourceId}_::_${momKey}_::_${dadKey}`
     *
     * @example
     * const groups = builder._groupSiblingsByParents(nodesList);
     *
     * @example
     * const empty = builder._groupSiblingsByParents([]);
     */
    _groupSiblingsByParents(nodes) {
        const familyGroups = {};
        nodes.forEach(n => {
            if (n.mom || n.father) {
                const momStr = n.mom ? n.mom.toLowerCase().trim() : '';
                const dadStr = n.father ? n.father.toLowerCase().trim() : '';
                const momKey = n.momId || momStr;
                const dadKey = n.fatherId || dadStr;
                const key = `${n._sourceId}_::_${momKey}_::_${dadKey}`;
                if (!familyGroups[key]) familyGroups[key] = [];
                familyGroups[key].push(n);
            }
        });
        return familyGroups;
    }

    /**
     * Resolves the mother node for a representative child, prioritizing any partner
     * of the already resolved father matching the mother's name.
     *
     * @param {Object} rep - Representative child node
     * @param {string|null} resolvedFatherId - Resolved father ID if available
     * @returns {Object|null} Mother Person node if found
     *
     * @example
     * const mom = builder._resolveMomNode(childRep, 'dad_123');
     *
     * @example
     * const momFallback = builder._resolveMomNode(childRep, null);
     */
    _resolveMomNode(rep, resolvedFatherId) {
        if (!rep.mom) return null;
        let momNode = null;
        if (resolvedFatherId) {
            const dad = this.nodeMap[resolvedFatherId];
            if (dad) {
                if (dad.partners && dad.partners.length > 0) {
                    const mNorm = rep.mom.toLowerCase().trim();
                    momNode = dad.partners.map(id => this.nodeMap[id]).find(p => p && p.name.toLowerCase().trim() === mNorm);
                }
                if (!momNode && rep.isGhost) {
                    momNode = this.findPerson(rep.mom, dad, 'spouse');
                }
            }
        }
        if (!momNode) momNode = this.findPerson(rep.mom, rep, 'mother');
        return momNode;
    }

    /**
     * Finds an already-married couple matching mother and father names on the same sheet.
     *
     * @param {string} momName - Mother name
     * @param {string} dadName - Father name
     * @param {Object} sourceNode - Reference child node for sheet scoping
     * @returns {{ momId: string, fatherId: string } | null} Found couple IDs or null
     *
     * @example
     * const couple = builder._findExistingCoupleOnSheet('Mary', 'Joseph', childNode);
     *
     * @example
     * const none = builder._findExistingCoupleOnSheet('', 'Joseph', childNode);
     */
    _findExistingCoupleOnSheet(momName, dadName, sourceNode) {
        if (!momName || !dadName) return null;
        const momCands = this.name2nodes[momName.toLowerCase().trim()] || [];
        const dadCands = this.name2nodes[dadName.toLowerCase().trim()] || [];
        for (const mc of momCands) {
            for (const dc of dadCands) {
                if (FamilyTreeBuilder.sharesSheet(mc, sourceNode) && FamilyTreeBuilder.sharesSheet(dc, sourceNode) && mc.partners.includes(dc.id)) {
                    return { momId: mc.id, fatherId: dc.id };
                }
            }
        }
        return null;
    }

    /**
     * Resolves pre-assigned or named parent IDs attached directly to a representative child node.
     * 
     * @param {Object} rep - Representative child node
     * @param {Object} nodeMap - Person node dictionary
     * @returns {{ resolvedMomId: string|null, resolvedFatherId: string|null }} Resolved parent IDs
     *
     * @example
     * const p1 = FamilyTreeBuilder._resolvePreassignedParentIds({ _namedParentId: 'p1' }, nodeMap);
     *
     * @example
     * const p2 = FamilyTreeBuilder._resolvePreassignedParentIds({ fatherId: 'f1', momId: 'm1' }, nodeMap);
     */
    static _resolvePreassignedParentIds(rep, nodeMap) {
        let resolvedMomId = null, resolvedFatherId = null;
        if (rep._namedParentId && nodeMap[rep._namedParentId]) {
            const namedP = nodeMap[rep._namedParentId];
            if (namedP.gender === 'F') {
                resolvedMomId = namedP.id;
            } else {
                resolvedFatherId = namedP.id;
            }
        }
        if (!resolvedFatherId && rep.fatherId && nodeMap[rep.fatherId]) {
            resolvedFatherId = rep.fatherId;
        }
        if (!resolvedMomId && rep.momId && nodeMap[rep.momId]) {
            resolvedMomId = rep.momId;
        }
        return { resolvedMomId, resolvedFatherId };
    }

    /**
     * Determines whether two parent IDs represent a recognized spousal partnership in the node map.
     * 
     * @param {string|null} momId - Mother ID
     * @param {string|null} fatherId - Father ID
     * @param {Object} nodeMap - Person node dictionary
     * @returns {boolean} True if the two nodes are recorded partners
     *
     * @example
     * const couple = FamilyTreeBuilder._isExistingCouple('m1', 'f1', nodeMap);
     *
     * @example
     * const notCouple = FamilyTreeBuilder._isExistingCouple('m1', 'f2', nodeMap);
     */
    static _isExistingCouple(momId, fatherId, nodeMap) {
        if (!momId || !fatherId) return false;
        const m = nodeMap[momId];
        return !!(m && m.partners && m.partners.includes(fatherId));
    }

    /**
     * Resolves individual mother and father nodes for a representative child when couple resolution did not find both.
     *
     * @param {Object} rep - Representative child node
     * @param {string|null} resolvedMomId - Current resolved mother ID or null
     * @param {string|null} resolvedFatherId - Current resolved father ID or null
     * @returns {{ resolvedMomId: string|null, resolvedFatherId: string|null }} Updated resolved parent IDs
     *
     * @example
     * builder._resolveIndividualParents({ mom: 'Alice', father: 'Bob' }, null, null);
     * // => { resolvedMomId: 'm1', resolvedFatherId: 'f1' }
     *
     * @example
     * builder._resolveIndividualParents({ mom: 'Alice' }, null, 'f1');
     * // => { resolvedMomId: 'm1', resolvedFatherId: 'f1' }
     */
    _resolveIndividualParents(rep, resolvedMomId, resolvedFatherId) {
        let momId = resolvedMomId;
        let fatherId = resolvedFatherId;
        if (!momId && rep.mom) {
            const momNode = this._resolveMomNode(rep, fatherId);
            if (momNode) momId = momNode.id;
        }
        if (!fatherId && rep.father) {
            const fatherNode = this._resolveFatherNode(rep, momId);
            if (fatherNode) fatherId = fatherNode.id;
        }
        return { resolvedMomId: momId, resolvedFatherId: fatherId };
    }

    /**
     * Resolves mother and father IDs for the representative child of a sibling group.
     *
     * @param {Object} rep - Oldest or representative child in the sibling group
     * @returns {{ resolvedMomId: string|null, resolvedFatherId: string|null, foundExistingCouple: boolean }}
     *
     * @example
     * const parents = builder._resolveRepresentativeParents(childRep);
     *
     * @example
     * const parentsGhost = builder._resolveRepresentativeParents(ghostChild);
     */
    _resolveRepresentativeParents(rep) {
        let { resolvedMomId, resolvedFatherId } = FamilyTreeBuilder._resolvePreassignedParentIds(rep, this.nodeMap);
        let foundExistingCouple = false;

        if (!resolvedMomId && !resolvedFatherId && rep.mom && rep.father) {
            const couple = this._findExistingCoupleOnSheet(rep.mom, rep.father, rep);
            if (couple) {
                resolvedMomId = couple.momId;
                resolvedFatherId = couple.fatherId;
                foundExistingCouple = true;
            }
        }

        ({ resolvedMomId, resolvedFatherId } = this._resolveIndividualParents(rep, resolvedMomId, resolvedFatherId));

        if (FamilyTreeBuilder._isExistingCouple(resolvedMomId, resolvedFatherId, this.nodeMap)) {
            foundExistingCouple = true;
        }

        return { resolvedMomId, resolvedFatherId, foundExistingCouple };
    }

    /**
     * Binds resolved parental IDs to each child in a sibling group, ensuring
     * pre-assigned named parent IDs are preserved and biologically impossible
     * father ages (older wife) are guarded.
     *
     * @param {Object[]} group - Sibling nodes
     * @param {string|null} resolvedMomId - Resolved mother ID
     * @param {string|null} resolvedFatherId - Resolved father ID
     * @param {boolean} foundExistingCouple - Whether parents form a known married couple
     *
     * @example
     * builder._bindGroupParentLinks(sibs, 'mom_1', 'dad_1', true);
     *
     * @example
     * builder._bindGroupParentLinks([childNode], null, 'dad_1', false);
     */
    _bindGroupParentLinks(group, resolvedMomId, resolvedFatherId, foundExistingCouple) {
        group.forEach(n => {
            const useMomId = (n._namedParentId && n.momId === n._namedParentId)
                ? n.momId
                : (n.momId || this._resolveSingleParentLink(
                    n, n.mom, 'mother', resolvedMomId, foundExistingCouple,
                    FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE
                ));
            let useFatherId = (n._namedParentId && n.fatherId === n._namedParentId)
                ? n.fatherId
                : (n.fatherId || this._resolveSingleParentLink(
                    n, n.father, 'father', resolvedFatherId, foundExistingCouple,
                    FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_FATHER_CHILDBIRTH_AGE
                ));

            if (useMomId && useFatherId) {
                const mom = this.nodeMap[useMomId];
                const dad = this.nodeMap[useFatherId];
                if (mom && dad && mom.yob && dad.yob && mom.yob < dad.yob) {
                    useFatherId = null;
                }
            }

            if (useMomId) n.momId = useMomId;
            if (useFatherId) n.fatherId = useFatherId;
        });
    }

    /**
     * Resolves and establishes parent-child links across nuclear families.
     * 
     * Groups siblings by shared parental declarations and binds valid maternal
     * and paternal node references.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._linkParents(nodesList);
     *
     * @example
     * builder._linkParents([child1, child2]);
     */
    _linkParents(nodes) {
        const familyGroups = this._groupSiblingsByParents(nodes);

        Object.values(familyGroups).forEach(group => {
            const validChildren = group.filter(c => c.yob).sort((a, b) => a.yob - b.yob);
            const rep = validChildren.length > 0 ? validChildren[0] : group[0];

            const { resolvedMomId, resolvedFatherId, foundExistingCouple } = this._resolveRepresentativeParents(rep);
            this._bindGroupParentLinks(group, resolvedMomId, resolvedFatherId, foundExistingCouple);
        });
    }

    /**
     * Validates if a mother-child age difference satisfies biological bounds.
     * When age difference exceeds MOTHER_OLDER_CHILD_THRESHOLD (45), verifies that
     * the mother has at least one earlier valid child within normal bounds.
     *
     * @param {number|null} childYob - Child's birth year
     * @param {number|null} momYob - Mother's birth year
     * @param {string|null} momId - Mother's node ID for earlier-child lookup
     * @returns {boolean} True if biologically valid or if years are unknown
     *
     * @example
     * const ok = builder._isValidMaternalAge(1975, 1950, 'mom1');
     *
     * @example
     * const tooYoung = builder._isValidMaternalAge(1960, 1950, 'mom1');
     */
    _isValidMaternalAge(childYob, momYob, momId = null) {
        if (!childYob || !momYob) return true;
        const ageDiff = childYob - momYob;
        if (ageDiff < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE ||
            ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_MOTHER_CHILDBIRTH_AGE) {
            return false;
        }
        if (ageDiff > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD) {
            if (!momId) return false;
            const hasValidFirstChild = Object.values(this.nodeMap).some(c =>
                c.yob && c.momId === momId &&
                (c.yob - momYob >= FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE &&
                 c.yob - momYob <= FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MOTHER_OLDER_CHILD_THRESHOLD)
            );
            if (!hasValidFirstChild) return false;
        }
        return true;
    }

    /**
     * Synchronizes and sorts children under parents, and couples co-parents who share children.
     * 
     * Orchestrates:
     * 1. Parent children array reconstruction from child parent IDs
     * 2. Chronological child sorting (by YOB, numbered roles like "Daughter 1", and sheet row order)
     * 3. Co-parent coupling with biological, celibacy, and family checks
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder._syncChildrenAndParentCoupling(allNodes);
     *
     * @example
     * builder._syncChildrenAndParentCoupling([mom, dad, child]);
     */
    _syncChildrenAndParentCoupling(nodes) {
        this._populateParentChildrenArrays(nodes);
        this._sortParentChildrenChronologically();
        this._coupleCoParentsFromChildren(nodes);
    }

    /**
     * Populates children array on parents based on child momId and fatherId references.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._populateParentChildrenArrays(nodesList);
     *
     * @example
     * builder._populateParentChildrenArrays([childA, childB]);
     */
    _populateParentChildrenArrays(nodes) {
        Object.values(this.nodeMap).forEach(p => p.children = []);
        const allNodes = Object.values(this.nodeMap);
        allNodes.forEach(n => {
            if (n.momId && this.nodeMap[n.momId] && !this.nodeMap[n.momId].children.includes(n.id)) {
                this.nodeMap[n.momId].children.push(n.id);
            }
            if (n.fatherId && this.nodeMap[n.fatherId] && !this.nodeMap[n.fatherId].children.includes(n.id)) {
                this.nodeMap[n.fatherId].children.push(n.id);
            }
            if (n._namedParentId && this.nodeMap[n._namedParentId] && !this.nodeMap[n._namedParentId].children.includes(n.id)) {
                const np = this.nodeMap[n._namedParentId];
                const isUngendered = !np.gender || (np.gender !== 'M' && np.gender !== 'F');
                const bioCompatible = !(np.yob && n.yob && (n.yob - np.yob < FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE));
                if (isUngendered && bioCompatible) {
                    np.children.push(n.id);
                }
            }
        });
    }

    /**
     * Parses numbered child or sibling roles from a person's name (e.g. "Son 1", "Daughter 2", "Boy 3").
     *
     * @param {string|null} name - Person name string
     * @returns {{ role: string, num: number }|null} Parsed role and index, or null
     *
     * @example
     * const r1 = FamilyTreeBuilder._parseNumberedSiblingRole('Son 2');
     *
     * @example
     * const r2 = FamilyTreeBuilder._parseNumberedSiblingRole('Joseph');
     */
    static _parseNumberedSiblingRole(nameOrNode) {
        if (!nameOrNode) return null;
        let name = nameOrNode;
        if (typeof nameOrNode === 'object') {
            if (nameOrNode._siblingOrdinal) return nameOrNode._siblingOrdinal;
            name = nameOrNode.name;
        }
        if (typeof name !== 'string') return null;
        const m = name.match(/\b(daughter|son|girl|boy)\s*(\d+)\b/i);
        if (!m) return null;
        const rawRole = m[1].toLowerCase();
        const role = (rawRole === 'girl' || rawRole === 'daughter') ? 'daughter' : 'son';
        return { role, num: parseInt(m[2], 10) };
    }

    /**
     * Resolves the effective spreadsheet row index for a sibling node or its partners.
     *
     * @param {Object} child - The sibling node to inspect.
     * @param {Object} [nodeMap={}] - Mapping of node IDs to node objects.
     * @returns {number} The spreadsheet row index or 99999 if not found.
     *
     * @example
     * const row1 = FamilyTreeBuilder._getEffectiveChildRow(childNode, nodeMap);
     *
     * @example
     * const rowFallback = FamilyTreeBuilder._getEffectiveChildRow(null);
     */
    static _getEffectiveChildRow(child, nodeMap = {}) {
        if (!child) return 99999;
        const directRow = FamilyTreeBuilder.getNodeSheetRow(child, null);
        if (directRow !== null) return directRow;
        if (child.partners && child.partners.length > 0) {
            for (const pid of child.partners) {
                const partnerRow = FamilyTreeBuilder.getNodeSheetRow(nodeMap[pid], null);
                if (partnerRow !== null) return partnerRow;
            }
        }
        return 99999;
    }

    /**
     * Compares two sibling Person nodes chronologically by birth year, numbered sibling role,
     * spreadsheet row order, best available YOB, and name tie-breaker.
     *
     * @param {Object} childA - First sibling node
     * @param {Object} childB - Second sibling node
     * @param {Object} [nodeMap={}] - Node map for resolving partner rows
     * @returns {number} Negative if childA precedes childB, positive if childB precedes childA, 0 if equal
     *
     * @example
     * const cmp1 = FamilyTreeBuilder.compareSiblingNodes(child1, child2, nodeMap);
     *
     * @example
     * const cmp2 = FamilyTreeBuilder.compareSiblingNodes(son1, son2, nodeMap);
     */
    static compareSiblingNodes(childA, childB, nodeMap = {}) {
        if (!childA || !childB) return 0;
        if (childA.yob && childB.yob && childA.yob !== childB.yob) return childA.yob - childB.yob;

        const numA = FamilyTreeBuilder._parseNumberedSiblingRole(childA);
        const numB = FamilyTreeBuilder._parseNumberedSiblingRole(childB);
        if (numA && numB && numA.role === numB.role && numA.num !== numB.num) {
            return numA.num - numB.num;
        }

        const rA = FamilyTreeBuilder._getEffectiveChildRow(childA, nodeMap);
        const rB = FamilyTreeBuilder._getEffectiveChildRow(childB, nodeMap);
        if (rA < 99999 && rB < 99999 && rA !== rB && FamilyTreeBuilder.sharesSheet(childA, childB)) {
            return rA - rB;
        }

        const yA = childA.bestYob, yB = childB.bestYob;
        if (yA && yB && yA !== yB) return yA - yB;

        const nameA = childA.name || '';
        const nameB = childB.name || '';
        return nameA.localeCompare(nameB);
    }

    /**
     * Sorts children under each parent chronologically by YOB, numbered sibling order, and sheet row.
     *
     * @example
     * builder._sortParentChildrenChronologically();
     *
     * @example
     * treeBuilder._sortParentChildrenChronologically();
     */
    _sortParentChildrenChronologically() {
        Object.values(this.nodeMap).forEach(p => {
            p.children.sort((idA, idB) => {
                return FamilyTreeBuilder.compareSiblingNodes(this.nodeMap[idA], this.nodeMap[idB], this.nodeMap);
            });
        });
    }

    /**
     * Checks whether two co-parents are prohibited from being partnered due to biological incest
     * (being biological siblings, or having an existing partner who is the sibling of the other)
     * or celibate religious vows.
     *
     * @param {Object} mom - Mother node
     * @param {Object} dad - Father node
     * @param {Object} nodeMap - Map of node ID to Person node
     * @returns {boolean} True if coupling is prohibited
     *
     * @example
     * const prohibited1 = FamilyTreeBuilder._isCoParentCouplingProhibited(priestDad, mom, nodeMap);
     *
     * @example
     * const prohibited2 = FamilyTreeBuilder._isCoParentCouplingProhibited(regularMom, regularDad, nodeMap);
     */
    static _isCoParentCouplingProhibited(mom, dad, nodeMap) {
        if (FamilyTreeBuilder._areBiologicalSiblings(mom, dad)) return true;
        if (FamilyTreeBuilder._isCelibateReligious(mom) || FamilyTreeBuilder._isCelibateReligious(dad)) return true;
        if (mom.partners && mom.partners.some(pid => FamilyTreeBuilder._areBiologicalSiblings(nodeMap[pid], dad))) return true;
        if (dad.partners && dad.partners.some(pid => FamilyTreeBuilder._areBiologicalSiblings(nodeMap[pid], mom))) return true;
        return false;
    }

    /**
     * Checks if p1 explicitly names a single spouse that conflicts with p2's name,
     * unless p2 also explicitly references p1 as spouse.
     *
     * @param {Object} p1 - First partner
     * @param {Object} p2 - Second partner
     * @returns {boolean} True if p1 has an unreciprocated conflicting spouse declaration
     *
     * @example
     * const excl1 = FamilyTreeBuilder._hasSpouseNameExclusion(dadWithWifeMary, momJane);
     *
     * @example
     * const excl2 = FamilyTreeBuilder._hasSpouseNameExclusion(dadWithoutSpouse, momJane);
     */
    static _hasSpouseNameExclusion(p1, p2) {
        if (!p1.spouse) return false;
        const p1Spouses = p1.spouse.split(/[,/]+/).map(s => s.trim()).filter(Boolean);
        if (p1Spouses.length === 1 && FamilyTreeBuilder._hasNameConflict(p1Spouses[0], p2.name)) {
            if (!p2.spouse || !FamilyTreeBuilder._namesOverlap(p2.spouse, p1.name)) return true;
        }
        return false;
    }

    /**
     * Couples co-parents who share children, verifying sibling safety, celibacy, family, and age rules.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._coupleCoParentsFromChildren(nodesList);
     *
     * @example
     * builder._coupleCoParentsFromChildren([childWithMomAndDad]);
     */
    _coupleCoParentsFromChildren(nodes) {
        nodes.forEach(n => {
            if (n.momId && n.fatherId) {
                const mom = this.nodeMap[n.momId], dad = this.nodeMap[n.fatherId];
                if (mom && dad && mom.id !== dad.id) {
                    if (FamilyTreeBuilder._isCoParentCouplingProhibited(mom, dad, this.nodeMap)) return;
                    if (n.family && dad.family && n.family.toLowerCase().trim() !== dad.family.toLowerCase().trim()) {
                        n.fatherId = null;
                        dad.children = (dad.children || []).filter(cid => cid !== n.id);
                        return;
                    }
                    if (!FamilyTreeBuilder._arePartnersAgeCompatible(dad, mom, dad.partners && dad.partners.length > 0)) return;
                    if (FamilyTreeBuilder._hasSpouseNameExclusion(dad, mom) || FamilyTreeBuilder._hasSpouseNameExclusion(mom, dad)) return;

                    if (!mom.partners.includes(dad.id)) mom.partners.push(dad.id);
                    if (!dad.partners.includes(mom.id)) dad.partners.push(mom.id);
                }
            }
        });
    }

    /**
     * Infers a missing parent (father from mother's partner, or mother from father's partner)
     * for a child with only a single known parent, verifying biological age bounds and sheet locality.
     *
     * @param {Object} n - Child domain node
     *
     * @example
     * builder._inferMissingParentForNode(childWithMom);
     *
     * @example
     * builder._inferMissingParentForNode(childWithDad);
     */
    _inferMissingParentForNode(n) {
        if (n.momId && !n.fatherId) {
            const mom = this.nodeMap[n.momId];
            if (mom && mom.partners.length > 0) {
                const dad = this.nodeMap[mom.partners[0]];
                if (dad && FamilyTreeBuilder.sharesSheet(n, dad) && FamilyTreeBuilder._isValidPaternalAge(n.yob, dad.yob)) {
                    n.fatherId = dad.id;
                }
            }
        }
        if (n.fatherId && !n.momId) {
            const dad = this.nodeMap[n.fatherId];
            if (dad && dad.partners.length > 0) {
                const mom = this.nodeMap[dad.partners[0]];
                if (mom && FamilyTreeBuilder.sharesSheet(n, mom) && this._isValidMaternalAge(n.yob, mom.yob, mom.id)) {
                    const dRow = FamilyTreeBuilder.getNodeSheetRow(dad, null);
                    const hasEarlierHusband = (mom.partners || []).some(pid => {
                        const hp = this.nodeMap[pid];
                        if (!hp || hp.id === dad.id) return false;
                        const hpRow = FamilyTreeBuilder.getNodeSheetRow(hp, null);
                        return dRow !== null && hpRow !== null && hpRow < dRow;
                    });
                    if (!hasEarlierHusband) {
                        n.momId = mom.id;
                    }
                }
            }
        }
    }

    /**
     * Infers missing co-parents when a node has only one parent known, but that parent has a partner.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.inferMissingParents(nodesList);
     *
     * @example
     * builder.inferMissingParents([personNode]);
     */
    inferMissingParents(nodes) {
        nodes.forEach(n => this._inferMissingParentForNode(n));
        this._syncChildrenAndParentCoupling(nodes);
    }

    /**
     * Validates maternal link on a node against sheet isolation and biological age bounds.
     * Nulls out invalid mother reference.
     *
     * @param {Object} n - Child node
     *
     * @example
     * builder._validateMaternalLink(childNode);
     *
     * @example
     * builder._validateMaternalLink(orphanNode);
     */
    _validateMaternalLink(n) {
        if (!n.momId || !this.nodeMap[n.momId]) return;
        const mom = this.nodeMap[n.momId];
        const valid = FamilyTreeBuilder.sharesSheet(n, mom) && this._isValidMaternalAge(n.yob, mom.yob, mom.id);
        if (!valid) n.momId = null;
    }

    /**
     * Validates paternal link on a node against sheet isolation and biological age bounds.
     * If the candidate father is age-incompatible as a parent (< 14-16 yrs older) but within spousal
     * bounds (e.g. 12yr gap), converts the relation to husband/partner before nulling fatherId.
     *
     * @param {Object} n - Child node
     *
     * @example
     * builder._validatePaternalLink(childNode);
     *
     * @example
     * builder._validatePaternalLink(childWithHusbandInFatherCol);
     */
    _validatePaternalLink(n) {
        if (!n.fatherId || !this.nodeMap[n.fatherId]) return;
        const dad = this.nodeMap[n.fatherId];
        const valid = FamilyTreeBuilder.sharesSheet(n, dad) && FamilyTreeBuilder._isValidPaternalAge(n.yob, dad.yob);
        if (!valid) {
            // Fallback: If a candidate was listed in the Father column but is biologically impossible as a father (< 16 yrs older),
            // yet falls within spousal age bounds (e.g. George 1928 and Sicily 1940, 12yr gap), recognize him as husband/partner.
            if (n.yob && dad.yob && Math.abs(dad.yob - n.yob) <= FamilyTreeBuilder.HEURISTIC_PRIORS.MAX_FIRST_WIFE_AGE_DIFF) {
                if (!n.partners.includes(dad.id)) n.partners.push(dad.id);
                if (!dad.partners.includes(n.id)) dad.partners.push(n.id);
            }
            n.fatherId = null;
        }
    }

    /**
     * Audits and prunes parent-child links that violate sheet isolation or biological age bounds.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.validateParentChildLinks(nodesList);
     *
     * @example
     * builder.validateParentChildLinks(allTreeNodes);
     */
    validateParentChildLinks(nodes) {
        nodes.forEach(n => {
            this._validateMaternalLink(n);
            this._validatePaternalLink(n);
        });

        this._syncChildrenAndParentCoupling(nodes);
    }

    /**
     * Re-assigns a single misgendered parent to their correct parental role (mom -> father or father -> mom)
     * and adopts their oppositely-gendered partner if available.
     *
     * @param {Object} n - Child domain node
     * @param {'mom'|'father'} fromField - Field currently holding the parent
     * @param {'mom'|'father'} toField - Field that should hold the parent
     * @param {'M'|'F'} wrongGender - Gender triggering the correction
     *
     * @example
     * builder._swapMisgenderedParent(child, 'mom', 'father', 'M');
     *
     * @example
     * builder._swapMisgenderedParent(child, 'father', 'mom', 'F');
     */
    _swapMisgenderedParent(n, fromField, toField, wrongGender) {
        const fromIdProp = `${fromField}Id`;
        const toIdProp = `${toField}Id`;
        const parent = this.nodeMap[n[fromIdProp]];
        if (parent && parent.gender === wrongGender) {
            n[toIdProp] = n[fromIdProp];
            n[toField] = parent.name;
            n[fromIdProp] = '';
            n[fromField] = '';
            const correctOppositeGender = wrongGender === 'M' ? 'F' : 'M';
            const oppositePartner = (parent.partners || []).map(id => this.nodeMap[id]).find(p => p && p.gender === correctOppositeGender);
            if (oppositePartner) {
                n[fromIdProp] = oppositePartner.id;
                n[fromField] = oppositePartner.name;
            }
        }
    }

    /**
     * Corrects inverted parental assignments where a male was assigned to momId
     * or a female to fatherId, re-slotting partners if discovered.
     *
     * @param {Object} n - Domain node
     *
     * @example
     * builder._correctInvertedParentAssignment(childWithInvertedMom);
     *
     * @example
     * builder._correctInvertedParentAssignment(childWithValidParents);
     */
    _correctInvertedParentAssignment(n) {
        if (n.momId && n.fatherId) {
            const mom = this.nodeMap[n.momId];
            const dad = this.nodeMap[n.fatherId];
            if (mom && dad && mom.partners.includes(dad.id)) {
                if (mom.gender === 'M' && dad.gender === 'F') {
                    const tmp = n.momId;
                    n.momId = n.fatherId;
                    n.fatherId = tmp;
                }
            }
        } else if (n.momId && !n.fatherId) {
            this._swapMisgenderedParent(n, 'mom', 'father', 'M');
        } else if (n.fatherId && !n.momId) {
            this._swapMisgenderedParent(n, 'father', 'mom', 'F');
        }
    }

    /**
     * Deduces gender for a node and its immediate relatives based on parental roles and spouse types.
     *
     * @param {Object} n - Domain Person instance
     *
     * @example
     * builder._inferNodeGendersFromRoles(nodeWithMomId);
     *
     * @example
     * builder._inferNodeGendersFromRoles(nodeWithSpouseType);
     */
    _inferNodeGendersFromRoles(n) {
        if (n.momId && this.nodeMap[n.momId] && !this.nodeMap[n.momId].gender) {
            this.nodeMap[n.momId].gender = 'F';
        }
        if (n.fatherId && this.nodeMap[n.fatherId] && !this.nodeMap[n.fatherId].gender) {
            this.nodeMap[n.fatherId].gender = 'M';
        }
        if (n.spouse) {
            const hasConflictingHusbandHeader = (n.spouseType === 'husband') && n.partners.some(pId => this.nodeMap[pId] && (this.nodeMap[pId].spouseType === 'husband' || this.nodeMap[pId].gender === 'F' || FamilyTreeBuilder._isFemaleName(this.nodeMap[pId].name)));
            const hasConflictingWifeHeader = (n.spouseType === 'wife') && n.partners.some(pId => this.nodeMap[pId] && (this.nodeMap[pId].spouseType === 'wife' || this.nodeMap[pId].gender === 'M' || FamilyTreeBuilder._isMaleName(this.nodeMap[pId].name)));

            if (n.spouseType === 'husband' && !hasConflictingHusbandHeader && !FamilyTreeBuilder._isMaleName(n.name)) {
                n.gender = n.gender || 'F';
                n.partners.forEach(pId => {
                    if (this.nodeMap[pId] && !FamilyTreeBuilder._isFemaleName(this.nodeMap[pId].name)) {
                        this.nodeMap[pId].gender = this.nodeMap[pId].gender || 'M';
                    }
                });
            } else if (n.spouseType === 'wife' && !hasConflictingWifeHeader && !FamilyTreeBuilder._isFemaleName(n.name)) {
                n.gender = n.gender || 'M';
                n.partners.forEach(pId => {
                    if (this.nodeMap[pId] && !FamilyTreeBuilder._isMaleName(this.nodeMap[pId].name)) {
                        this.nodeMap[pId].gender = this.nodeMap[pId].gender || 'F';
                    }
                });
            }
        }
    }

    /**
     * Infers genders based on structural roles (parent/spouse assignments).
     *
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._inferRoleGenders(nodesList);
     *
     * @example
     * builder._inferRoleGenders([child1, child2]);
     */
    _inferRoleGenders(nodes) {
        nodes.forEach(n => this._correctInvertedParentAssignment(n));
        nodes.forEach(n => this._inferNodeGendersFromRoles(n));
    }

    /**
     * Builds a statistical frequency table mapping clean given names to gender counts.
     * 
     * @param {Object[]} nodes - Domain Person instances
     * @returns {Object<string, {F: number, M: number}>} Name to gender count mapping
     * 
     * @example
     * const table = builder._buildNameGenderFrequencyTable(nodesList);
     *
     * @example
     * const counts = builder._buildNameGenderFrequencyTable([personMary, personGeorge]);
     */
    _buildNameGenderFrequencyTable(nodes) {
        const table = {};
        nodes.forEach(n => {
            if (n.gender && n.name && !n.name.startsWith('(') && !n.isGhost) {
                const cleanName = n.name.trim().toLowerCase();
                if (!table[cleanName]) table[cleanName] = { 'F': 0, 'M': 0 };
                table[cleanName][n.gender]++;
            }
        });
        return table;
    }

    /**
     * Disambiguates partner genders when both are unset or identical, using age seniority or sheet row ordering.
     *
     * @param {Object} n - First partner node
     * @param {Object} p - Second partner node
     * @returns {boolean} True if partner genders were assigned
     *
     * @example
     * const changed1 = FamilyTreeBuilder._disambiguatePartnerGendersBySeniority(olderNode, youngerNode);
     *
     * @example
     * const changed2 = FamilyTreeBuilder._disambiguatePartnerGendersBySeniority(row1Node, row2Node);
     */
    static _disambiguatePartnerGendersBySeniority(n, p) {
        const nYob = FamilyTreeBuilder._effectiveYob(n);
        const pYob = FamilyTreeBuilder._effectiveYob(p);
        if (nYob && pYob && nYob !== pYob) {
            // Older person in partnership is safely assumed to be male
            n.gender = nYob < pYob ? 'M' : 'F';
            p.gender = nYob < pYob ? 'F' : 'M';
            return true;
        }
        // Lower row number in sheet is safely assumed to be male
        const nRow = n._sheetRow || (n._sheetRows && Object.values(n._sheetRows)[0]) || 9999;
        const pRow = p._sheetRow || (p._sheetRows && Object.values(p._sheetRows)[0]) || 9999;
        if (nRow !== pRow && nRow !== 9999 && pRow !== 9999) {
            n.gender = nRow < pRow ? 'M' : 'F';
            p.gender = nRow < pRow ? 'F' : 'M';
            return true;
        }
        return false;
    }

    /**
     * Deduces and assigns complementary genders to a partnership based on age, row ordering, or existing gender.
     *
     * @param {Object} n - First partner node
     * @param {Object} p - Second partner node
     * @returns {boolean} Whether either partner's gender was updated
     *
     * @example
     * const updated1 = builder._inferPartnerPairGenders(husbandNode, wifeNode);
     *
     * @example
     * const updated2 = builder._inferPartnerPairGenders(p1, p2);
     */
    _inferPartnerPairGenders(n, p) {
        let changed = false;
        const needsDisambiguation = (!n.gender && !p.gender) || (n.gender && p.gender && n.gender === p.gender);

        if (needsDisambiguation) {
            changed = FamilyTreeBuilder._disambiguatePartnerGendersBySeniority(n, p);
        } else if (n.gender && !p.gender) {
            p.gender = n.gender === 'M' ? 'F' : 'M';
            changed = true;
        } else if (!n.gender && p.gender) {
            n.gender = p.gender === 'M' ? 'F' : 'M';
            changed = true;
        }

        return changed;
    }

    /**
     * Propagates inferred genders across married partner pairs.
     * 
     * Applies opposite-gender deduction and falls back to age seniority (older=M, younger=F).
     * 
     * @param {Object[]} nodes - Domain Person instances
     * @returns {boolean} True if any node gender was updated
     * 
     * @example
     * const changed = builder._propagatePartnerGenders(nodesList);
     *
     * @example
     * const noChange = builder._propagatePartnerGenders([]);
     */
    _propagatePartnerGenders(nodes) {
        let changed = false;
        nodes.forEach(n => {
            if (n.partners?.length > 0) {
                n.partners.forEach(pId => {
                    const p = this.nodeMap[pId];
                    if (p && this._inferPartnerPairGenders(n, p)) {
                        changed = true;
                    }
                });
            }
        });
        return changed;
    }

    /**
     * Repeatedly propagates partner genders across nodes until no further updates occur.
     *
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder._convergePartnerGenders(nodesList);
     *
     * @example
     * builder._convergePartnerGenders([]);
     */
    _convergePartnerGenders(nodes) {
        let changed = true;
        while (changed) {
            changed = this._propagatePartnerGenders(nodes);
        }
    }

    /**
     * Infers unambiguous person genders from unique gender occurrences in the name frequency table.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Object<string, {F: number, M: number}>} nameGenderCounts - Name frequency map
     *
     * @example
     * FamilyTreeBuilder._inferGendersFromNameFrequency(nodes, { john: { F: 0, M: 5 } });
     *
     * @example
     * FamilyTreeBuilder._inferGendersFromNameFrequency(nodes, { mary: { F: 3, M: 0 } });
     */
    static _inferGendersFromNameFrequency(nodes, nameGenderCounts) {
        nodes.forEach(n => {
            if (!n.gender && n.name && !n.name.startsWith('(') && !n.isGhost) {
                const counts = nameGenderCounts[n.name.trim().toLowerCase()];
                if (counts) {
                    if (counts['F'] > 0 && counts['M'] === 0) n.gender = 'F';
                    else if (counts['M'] > 0 && counts['F'] === 0) n.gender = 'M';
                }
            }
        });
    }

    /**
     * Deduces unknown genders iteratively using roles, namesakes, and spousal dynamics.
     * 
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder.inferGenders(nodesList);
     *
     * @example
     * builder.inferGenders(allTreeNodes);
     */
    inferGenders(nodes) {
        // Run partner gender propagation first: after partnerships, age, and sheet rows are determined,
        // the older person in a partnership or with the lower row number is safely assumed to be male.
        this._convergePartnerGenders(nodes);
        const nameGenderCounts = this._buildNameGenderFrequencyTable(nodes);
        FamilyTreeBuilder._inferGendersFromNameFrequency(nodes, nameGenderCounts);
        this._inferRoleGenders(nodes);
        this._convergePartnerGenders(nodes);
    }

    /**
     * Resolves an inferred location for a person from valid partner or parent locations.
     *
     * @param {Object} n - Domain Person node
     * @param {Object<string, Object>} nodeMap - Mapping of person IDs to Person instances
     * @returns {string|null} Resolved place string or null
     *
     * @example
     * const loc1 = FamilyTreeBuilder._resolveInferredLocation(personWithoutPlace, nodeMap);
     *
     * @example
     * const loc2 = FamilyTreeBuilder._resolveInferredLocation(orphanNode, nodeMap);
     */
    static _resolveInferredLocation(n, nodeMap) {
        for (const pId of n.partners || []) {
            const p = nodeMap[pId];
            if (p && p.place && !FamilyTreeBuilder.isInvalidLocation(p.place)) {
                return p.place;
            }
        }
        const dad = nodeMap[n.fatherId];
        if (dad && dad.place && !FamilyTreeBuilder.isInvalidLocation(dad.place)) {
            return dad.place;
        }
        const mom = nodeMap[n.momId];
        if (mom && mom.place && !FamilyTreeBuilder.isInvalidLocation(mom.place)) {
            return mom.place;
        }
        return null;
    }

    /**
     * Deduces geographical location from spouses or parents across multiple convergent passes.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.inferLocations(nodesList);
     *
     * @example
     * builder.inferLocations(allTreeNodes);
     */
    inferLocations(nodes) {
        FamilyTreeBuilder._runConvergentPass(nodes, (n) => {
            if (n.place && !FamilyTreeBuilder.isInvalidLocation(n.place)) return false;
            const newPlace = FamilyTreeBuilder._resolveInferredLocation(n, this.nodeMap);
            if (newPlace) {
                n.place = newPlace;
                return true;
            }
            return false;
        }, 20);
    }

    /**
     * Deduces ancestral family name from father's family across multiple convergent passes.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.inferFamilyNames(nodesList);
     *
     * @example
     * builder.inferFamilyNames(allTreeNodes);
     */
    inferFamilyNames(nodes) {
        FamilyTreeBuilder._runConvergentPass(nodes, (n) => {
            if (!n.family && n.fatherId) {
                const dad = this.nodeMap[n.fatherId];
                if (dad && dad.family) {
                    n.family = dad.family;
                    n._inferredPaternalFamily = true;
                    return true;
                }
            }
            return false;
        }, 20);
    }

    /**
     * Sorts a person's partners chronologically by ordinal index, birth year, or spreadsheet row.
     *
     * @param {Object[]} partners - Array of partner Person nodes
     * @returns {Object[]} Chronologically sorted partner nodes
     *
     * @example
     * const sorted1 = FamilyTreeBuilder._sortPartnersChronologically([wife2, wife1]);
     *
     * @example
     * const sorted2 = FamilyTreeBuilder._sortPartnersChronologically([pA, pB]);
     */
    static _sortPartnersChronologically(partners) {
        const getYob = FamilyTreeBuilder._knownYob;
        return partners.slice().sort((a, b) => {
            const ordA = FamilyTree._extractPartnerOrdinal(a), ordB = FamilyTree._extractPartnerOrdinal(b);
            if (ordA !== null && ordB !== null) return ordA - ordB;
            if (ordA === 1 && ordB !== 1) return -1;
            if (ordB === 1 && ordA !== 1) return 1;
            const yA = getYob(a), yB = getYob(b);
            if (yA && yB && yA !== yB) return yA - yB;
            const rA = FamilyTreeBuilder.getNodeSheetRow(a, null);
            const rB = FamilyTreeBuilder.getNodeSheetRow(b, null);
            if (rA !== null && rB !== null && FamilyTreeBuilder.sharesSheet(a, b)) {
                return rA - rB;
            }
            return 0;
        });
    }

    /**
     * Retrieves all children of a parent node born with a specific spouse partner.
     *
     * @param {Object} parent - Parent node
     * @param {Object} spouse - Spouse node
     * @param {Object} [nodeMap={}] - Map of nodes by ID
     * @returns {Object[]} Array of shared child nodes
     *
     * @example
     * const kids1 = FamilyTreeBuilder._getPartnerChildren(parentDad, spouseMom, nodeMap);
     *
     * @example
     * const kidsEmpty = FamilyTreeBuilder._getPartnerChildren(null, null);
     */
    static _getPartnerChildren(parent, spouse, nodeMap = {}) {
        if (!parent || !spouse) return [];
        const spNorm = (spouse._normName || (spouse.name || '').toLowerCase().trim());
        return (parent.children || [])
            .map(cid => nodeMap[cid])
            .filter(c => {
                if (!c) return false;
                if (c.momId === spouse.id || c.fatherId === spouse.id) return true;
                const cMomNorm = (c.mom || '').toLowerCase().trim();
                const cDadNorm = (c.father || '').toLowerCase().trim();
                return (cMomNorm && cMomNorm === spNorm) || (cDadNorm && cDadNorm === spNorm);
            });
    }

    /**
     * Computes the minimum and maximum birth year across a collection of child nodes.
     *
     * @param {Object[]} children - Array of child nodes
     * @returns {{ min: number|null, max: number|null }} Minimum and maximum birth years
     *
     * @example
     * const ext1 = FamilyTreeBuilder._getChildYobExtremes([{ yob: 1950 }, { yob: 1955 }]);
     *
     * @example
     * const extEmpty = FamilyTreeBuilder._getChildYobExtremes([]);
     */
    static _getChildYobExtremes(children) {
        let min = null, max = null;
        for (const c of children) {
            const y = c ? (c.yob || c._inferredYob || null) : null;
            if (y) {
                if (min === null || y < min) min = y;
                if (max === null || y > max) max = y;
            }
        }
        return { min, max };
    }

    /**
     * Calculates estimated remarriage year between consecutive spouses based on childbearing intervals.
     *
     * @param {Object} parent - Shared parent node
     * @param {Object} earlierSpouse - Prior spouse node
     * @param {Object} laterSpouse - Subsequent spouse node
     * @param {Object} nodeMap - Node lookup map by ID
     * @returns {number|null} Estimated remarriage year or null
     *
     * @example
     * const y1 = FamilyTreeBuilder._computeSequentialRemarriageYear(husband, wife1, wife2, nodeMap);
     *
     * @example
     * const y2 = FamilyTreeBuilder._computeSequentialRemarriageYear(husband, wife1, null, nodeMap);
     */
    static _computeSequentialRemarriageYear(parent, earlierSpouse, laterSpouse, nodeMap) {
        const laterChildren = FamilyTreeBuilder._getPartnerChildren(parent, laterSpouse, nodeMap);
        const earlierChildren = FamilyTreeBuilder._getPartnerChildren(parent, earlierSpouse, nodeMap);

        const laterFirstChildYob = FamilyTreeBuilder._getChildYobExtremes(laterChildren).min;
        const earlierLastChildYob = FamilyTreeBuilder._getChildYobExtremes(earlierChildren).max;

        const laterYob = laterSpouse ? (laterSpouse.yob || laterSpouse._inferredYob || null) : null;
        return laterFirstChildYob
            ? Math.max(earlierLastChildYob || 0, laterFirstChildYob - 1)
            : (laterYob ? Math.max(earlierLastChildYob || 0, laterYob + 20) : null);
    }

    /**
     * Infers death years for earlier spouses under sequential remarriage before subsequent partners.
     *
     * @param {Object[]} nodes - Array of domain Person nodes
     * @param {Object} [nodeMap={}] - Node map by ID
     *
     * @example
     * FamilyTreeBuilder._inferSequentialRemarriageDeaths(nodesList, nodeMap);
     *
     * @example
     * FamilyTreeBuilder._inferSequentialRemarriageDeaths([husbandNode], nodeMap);
     */
    static _inferSequentialRemarriageDeaths(nodes, nodeMap = {}) {
        nodes.forEach(n => {
            if (!n.partners || n.partners.length < 2) return;

            const partnerNodes = FamilyTreeBuilder._sortPartnersChronologically(
                n.partners.map(pid => nodeMap[pid]).filter(Boolean)
            );
            if (partnerNodes.length < 2) return;
            n.partners = partnerNodes.map(p => p.id);

            for (let i = 0; i < partnerNodes.length - 1; i++) {
                const earlierSpouse = partnerNodes[i];
                const laterSpouse = partnerNodes[i + 1];
                if (earlierSpouse.death) continue;

                const remarriageYear = FamilyTreeBuilder._computeSequentialRemarriageYear(n, earlierSpouse, laterSpouse, nodeMap);

                if (remarriageYear && (!earlierSpouse.death || earlierSpouse.death > remarriageYear)) {
                    earlierSpouse.death = remarriageYear;
                    earlierSpouse._isDeduceDeath = true;
                }
            }
        });
    }

    /**
     * Infers death year (at age 90) for centenarians without an explicit death year.
     *
     * @param {Object[]} nodes - Array of domain Person nodes
    /**
     * Infers death years for centenarians (age > 100) lacking an explicit death year by assuming death at 90.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {number} currentYear - Reference calendar year
     *
     * @example
     * FamilyTreeBuilder._inferCentenarianDeaths(nodesList, 2026);
     *
     * @example
     * FamilyTreeBuilder._inferCentenarianDeaths([personNode], 2024);
     */
    static _inferCentenarianDeaths(nodes, currentYear) {
        nodes.forEach(n => {
            if (n.death) return;
            const yob = n.yob || n._inferredYob || null;
            if (!yob) return;
            if (currentYear - yob > 100) {
                n.death = yob + 90;
            }
        });
    }

    /**
     * Infers death years for persons who are clearly deceased but have no explicit death year.
     *
     * @param {Object[]} nodes - Domain Person instances
     *
     * @example
     * builder.inferDeaths(nodesList);
     *
     * @example
     * builder.inferDeaths(allTreeNodes);
     */
    inferDeaths(nodes) {
        // Rule 2 (Sequential Remarriage Death Deduction): Run BEFORE Rule 1 (generic 90-year living cap)
        FamilyTreeBuilder._inferSequentialRemarriageDeaths(nodes, this.nodeMap);

        // Rule 1: Age > 100 without death → assume died at 90
        FamilyTreeBuilder._inferCentenarianDeaths(nodes, new Date().getFullYear());
    }

    /**
     * Executes a multi-pass fixed-point relaxation algorithm to infer birth years across the graph.
     *
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.inferYobs(nodesList);
     *
     * @example
     * builder.inferYobs(allTreeNodes);
     */
    inferYobs(nodes) {
        const getYob = FamilyTreeBuilder._knownYob;
        this._rowFallbackUsed = false;

        let changed = true;
        let iterations = 0;
        
        while (changed && iterations < 30) {
            changed = false;
            iterations++;

            if (this._inferYobsSpouses(nodes, getYob)) changed = true;
            if (this._inferYobsParentChild(nodes, getYob)) changed = true;
            if (this._inferYobsSiblings(nodes, getYob)) changed = true;
            if (this._inferYobsDirectParentLinks(nodes, getYob)) changed = true;

            if (!changed && !this._rowFallbackUsed) {
                if (this._applyRowProximityFallback(nodes, getYob)) changed = true;
                this._rowFallbackUsed = true;
            }
        }
    }

    /**
     * Infers birth years across married spouses based on expected spousal age offsets.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if any node's inferred birth year changed
     *
     * @example
     * const changed = builder._inferYobsSpouses(nodes, getYob);
     *
     * @example
     * const noChange = builder._inferYobsSpouses([], () => null);
     */
    _inferYobsSpouses(nodes, getYob) {
        let changed = false;
        nodes.forEach(n => {
            n.partners.forEach(pId => {
                const p = this.nodeMap[pId];
                if (p && FamilyTreeBuilder._propagateSpouseYobs(n, p, getYob, this.nodeMap)) {
                    changed = true;
                }
            });
        });
        return changed;
    }

    /**
     * Infers birth years between parents and their children based on generational gaps.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if any node's inferred birth year changed
     *
     * @example
     * const changed = builder._inferYobsParentChild(nodes, getYob);
     *
     * @example
     * const noChange = builder._inferYobsParentChild([], () => null);
     */
    _inferYobsParentChild(nodes, getYob) {
        let changed = false;
        nodes.forEach(n => {
            if (n.children && n.children.length > 0) {
                const childNodes = n.children.map(id => this.nodeMap[id]).filter(Boolean);
                if (childNodes.length > 0) {
                    let refChild = childNodes[0];
                    const knownKids = childNodes.filter(c => getYob(c) !== null).sort((a, b) => getYob(a) - getYob(b));
                    if (knownKids.length > 0) refChild = knownKids[0];
                    if (FamilyTreeBuilder._propagateParentChildYobs(n, refChild, getYob, this.nodeMap)) {
                        changed = true;
                    }
                }
            }
        });
        return changed;
    }

    /**
     * Infers birth years between sibling children of a shared parent using consecutive child gaps.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if any node's inferred birth year changed
     *
     * @example
     * const changed = builder._inferYobsSiblings(nodes, getYob);
     *
     * @example
     * const noChange = builder._inferYobsSiblings([], () => null);
     */
    _inferYobsSiblings(nodes, getYob) {
        let changed = false;
        nodes.forEach(n => {
            if (n.children && n.children.length > 1) {
                const childNodes = n.children.map(id => this.nodeMap[id]).filter(Boolean);
                if (FamilyTreeBuilder._propagateSiblingYobs(childNodes, getYob)) {
                    changed = true;
                }
            }
        });
        return changed;
    }

    /**
     * Attempts to infer a child node's birth year from its mother or father.
     *
     * @param {Object} n - Child node
     * @param {Object} nodeMap - Map of person IDs to nodes
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if child node's inferred birth year was set
     *
     * @example
     * FamilyTreeBuilder._inferNodeYobFromParent(child, nodeMap, getYob)
     *
     * @example
     * FamilyTreeBuilder._inferNodeYobFromParent(orphanNode, nodeMap, getYob)
     */
    static _inferNodeYobFromParent(n, nodeMap, getYob) {
        if (n.momId) {
            const mom = nodeMap[n.momId];
            const momYob = getYob(mom);
            if (momYob) {
                n._inferredYob = momYob + FamilyTreeBuilder.GENERATIONAL_GAPS.MATERNAL_FIRST_CHILD;
                return true;
            }
        } else if (n.fatherId) {
            const dad = nodeMap[n.fatherId];
            const dadYob = getYob(dad);
            if (dadYob) {
                n._inferredYob = dadYob + FamilyTreeBuilder.GENERATIONAL_GAPS.PATERNAL_FIRST_CHILD;
                return true;
            }
        }
        return false;
    }

    /**
     * Propagates parent birth years directly to children without an explicit sibling anchor.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if any node's inferred birth year changed
     *
     * @example
     * const changed = builder._inferYobsDirectParentLinks(nodes, getYob);
     *
     * @example
     * const noChange = builder._inferYobsDirectParentLinks([], () => null);
     */
    _inferYobsDirectParentLinks(nodes, getYob) {
        let changed = false;
        nodes.forEach(n => {
            if (!getYob(n) && FamilyTreeBuilder._inferNodeYobFromParent(n, this.nodeMap, getYob)) {
                changed = true;
            }
        });
        return changed;
    }

    /**
     * Collects row and birth year anchors grouped by spreadsheet source ID.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {Object<string, Array<{ row: number, yob: number }>>} Anchors keyed by sheet ID
     *
     * @example
     * const anchors = FamilyTreeBuilder._collectSheetAnchors(nodes, getYob);
     *
     * @example
     * const empty = FamilyTreeBuilder._collectSheetAnchors([], () => null);
     */
    static _collectSheetAnchors(nodes, getYob) {
        const sheetAnchors = {};
        nodes.forEach(n => {
            const y = getYob(n);
            if (!y || !n._sheetRows) return;
            for (const [sid, row] of Object.entries(n._sheetRows)) {
                if (!sheetAnchors[sid]) sheetAnchors[sid] = [];
                sheetAnchors[sid].push({ row, yob: y });
            }
        });
        return sheetAnchors;
    }

    /**
     * Finds the nearest anchor on a spreadsheet by row distance.
     *
     * @param {number} row - Target spreadsheet row
     * @param {Array<{ row: number, yob: number }>} anchors - Available anchors on that sheet
     * @returns {{ row: number, yob: number }|null} Nearest anchor or null
     *
     * @example
     * const near1 = FamilyTreeBuilder._findNearestSheetAnchor(15, [{ row: 10, yob: 1940 }]);
     *
     * @example
     * const nearNone = FamilyTreeBuilder._findNearestSheetAnchor(15, []);
     */
    static _findNearestSheetAnchor(row, anchors) {
        if (!anchors || anchors.length === 0) return null;
        let nearest = anchors[0];
        let minDist = Math.abs(row - anchors[0].row);
        for (let i = 1; i < anchors.length; i++) {
            const d = Math.abs(row - anchors[i].row);
            if (d < minDist) {
                minDist = d;
                nearest = anchors[i];
            }
        }
        return nearest;
    }

    /**
     * Deduces the birth year of an unresolved root node using nearest sheet anchors and propagates to partners.
     *
     * @param {Object} n - Root person node
     * @param {Object<string, Array<{ row: number, yob: number }>>} sheetAnchors - Sheet anchors keyed by sheet ID
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if birth year was inferred
     *
     * @example
     * const inferred = builder._inferRootYobFromSheetAnchors(rootNode, anchors, getYob);
     *
     * @example
     * const skipped = builder._inferRootYobFromSheetAnchors(nodeWithoutAnchors, {}, getYob);
     */
    _inferRootYobFromSheetAnchors(n, sheetAnchors, getYob) {
        if (!n._sheetRows) return false;
        for (const [sid, row] of Object.entries(n._sheetRows)) {
            const nearest = FamilyTreeBuilder._findNearestSheetAnchor(row, sheetAnchors[sid]);
            if (!nearest) continue;

            n._inferredYob = nearest.yob + (row - nearest.row) * FamilyTreeBuilder.GENERATIONAL_GAPS.CONSECUTIVE_SIBLING;
            n.partners.forEach(pId => {
                const p = this.nodeMap[pId];
                if (p && !getYob(p)) {
                    FamilyTreeBuilder._propagateSpouseYobs(n, p, getYob, this.nodeMap);
                }
            });
            return true;
        }
        return false;
    }

    /**
     * Infers birth years for unresolved root nodes based on row proximity to sheet anchors.
     *
     * @param {Object[]} nodes - Domain Person instances
     * @param {Function} getYob - Accessor returning birth year or null
     * @returns {boolean} True if any root node birth year was inferred
     *
     * @example
     * const applied = builder._applyRowProximityFallback(nodes, getYob);
     *
     * @example
     * const skipped = builder._applyRowProximityFallback([], () => null);
     */
    _applyRowProximityFallback(nodes, getYob) {
        let changed = false;
        const unresolvedRoots = nodes.filter(n =>
            !getYob(n) && n._sheetRows && !n.momId && !n.fatherId && !n._namedParentId);

        if (unresolvedRoots.length === 0) return false;

        const sheetAnchors = FamilyTreeBuilder._collectSheetAnchors(nodes, getYob);

        unresolvedRoots.forEach(n => {
            if (getYob(n)) return;
            if (this._inferRootYobFromSheetAnchors(n, sheetAnchors, getYob)) {
                changed = true;
            }
        });
        return changed;
    }

    /**
     * Returns lowercase partner names for a node, looked up from the node map.
     *
     * @param {Object} node - Context person node
     * @returns {string[]} Lowercase partner names
     *
     * @example
     * const names = builder._getPartnerNames(personNode);
     *
     * @example
     * const empty = builder._getPartnerNames({ partners: [] });
     */
    _getPartnerNames(node) {
        return node.partners.map(pid => this.nodeMap[pid]?.name?.toLowerCase().trim()).filter(Boolean);
    }

    /**
     * Checks if any of a node's partners have parents (i.e., are descendants, not root-level).
     *
     * @param {Object} node - Context person node
     * @returns {boolean} True if any partner has recorded parents
     *
     * @example
     * const isDescendant = builder._hasDescendantPartner(personNode);
     *
     * @example
     * const isRootPartner = builder._hasDescendantPartner(rootNode);
     */
    _hasDescendantPartner(node) {
        return (node.partners || []).some(pid => {
            const p = this.nodeMap[pid];
            return p && (p.momId || p.fatherId);
        });
    }

    /**
     * Checks if two partner name lists have exclusive (non-overlapping) names on either side.
     *
     * @param {string[]} listA - First list of partner names
     * @param {string[]} listB - Second list of partner names
     * @returns {boolean} True if non-overlapping partners exist
     *
     * @example
     * const excl = builder._hasExclusivePartners(['ammini'], ['ammini', 'mary']);
     *
     * @example
     * const same = builder._hasExclusivePartners(['ammini'], ['ammini']);
     */
    _hasExclusivePartners(listA, listB) {
        const hasUnshared = (own, other) =>
            own.some(p1 => !other.some(p2 => FamilyTreeBuilder._namesOverlap(p1, p2)));
        return hasUnshared(listA, listB) || hasUnshared(listB, listA);
    }

    /**
     * Evaluates partner compatibility between disconnected root candidates.
     *
     * @param {Object} primary - Primary root candidate
     * @param {Object} secondary - Secondary root candidate
     * @returns {boolean} True if partner definitions conflict
     *
     * @example
     * const conflict = builder._hasRootPartnerConflict(root1, root2);
     *
     * @example
     * const compatible = builder._hasRootPartnerConflict(rootA, rootB);
     */
    _hasRootPartnerConflict(primary, secondary) {
        const pPartners = this._getPartnerNames(primary);
        const sPartners = this._getPartnerNames(secondary);
        if (pPartners.length === 0 || sPartners.length === 0) return false;

        const sharesPartner = pPartners.some(p1 => sPartners.some(p2 => FamilyTreeBuilder._namesOverlap(p1, p2)));
        if (!sharesPartner) {
            if (primary.yob && secondary.yob && primary.yob !== secondary.yob) return true;
            // In-law spouses married to descendants must not merge with other in-laws
            if (this._hasDescendantPartner(primary) || this._hasDescendantPartner(secondary)) return true;
            return false;
        }

        // Shared partner name but one root has additional unshared partners
        // (e.g. two "Vareeth"s both married to "Ammini" but one also married to "Mary")
        return this._hasExclusivePartners(pPartners, sPartners);
    }

    /**
     * Checks if a candidate birth year violates biological age bounds with a root's partners or children.
     *
     * @param {Object} rootNode - Root node whose partners/children are validated
     * @param {number|null} yob - Candidate birth year to test
     * @returns {boolean} True if biological age constraints are violated
     *
     * @example
     * const invalidAge = builder._violatesBiologicalAgeCompatibility(parentRoot, 1970);
     *
     * @example
     * const validAge = builder._violatesBiologicalAgeCompatibility(parentRoot, 1920);
     */
    _violatesBiologicalAgeCompatibility(rootNode, yob) {
        if (!yob) return false;

        const violatesPartnerAge = rootNode.partners.some(pid => {
            const p = this.nodeMap[pid];
            if (!p) return false;
            const partnerYob = p.yob || p._inferredYob;
            return partnerYob && Math.abs(yob - partnerYob) > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_SPOUSE_AGE_DIFF;
        });
        if (violatesPartnerAge) return true;

        const violatesChildAge = rootNode.children.some(cid => {
            const c = this.nodeMap[cid];
            if (!c) return false;
            const childYob = c.yob || c._inferredYob;
            return childYob && yob > childYob - FamilyTreeBuilder.GENERATIONAL_GAPS.MIN_PARENTAL_AGE;
        });
        return violatesChildAge;
    }

    /**
     * Checks whether two disconnected root candidates violate age bounds or biological compatibility.
     *
     * @param {Object} primary - Primary root candidate
     * @param {Object} secondary - Secondary root candidate
     * @param {number|undefined} pYob - Primary node birth year
     * @param {number|undefined} sYob - Secondary node birth year
     * @returns {boolean} True if age compatibility is violated
     *
     * @example
     * builder._hasRootAgeCompatibilityViolation({ yob: 1900 }, { yob: 1980 }, 1900, 1980);
     * // => true
     *
     * @example
     * builder._hasRootAgeCompatibilityViolation({ yob: 1900 }, { yob: 1905 }, 1900, 1905);
     * // => false
     */
    _hasRootAgeCompatibilityViolation(primary, secondary, pYob, sYob) {
        if (pYob && sYob && Math.abs(pYob - sYob) > FamilyTreeBuilder.BIOLOGICAL_BOUNDS.MAX_SPOUSE_AGE_DIFF) {
            return true;
        }
        if (this._violatesBiologicalAgeCompatibility(secondary, pYob || sYob)) return true;
        if (this._violatesBiologicalAgeCompatibility(primary, sYob || pYob)) return true;
        return false;
    }

    /**
     * Determines whether two disconnected root nodes from different sheets represent the same person.
     * Prevents false polygamist merges between in-law spouses who married different descendants.
     *
     * @param {Object} primary - Earlier root node
     * @param {Object} secondary - Later root node candidate
     * @returns {boolean} True if safe to merge
     *
     * @example
     * const canMerge = builder._canMergeDisconnectedRoots(rootAnthony1, rootAnthony2);
     *
     * @example
     * const cannotMerge = builder._canMergeDisconnectedRoots(inlawJose1, inlawJose2);
     */
    _canMergeDisconnectedRoots(primary, secondary) {
        // Must come from different sheets
        for (const sid of primary._sourceIds) {
            if (secondary._sourceIds.has(sid)) return false;
        }

        // Family names must not conflict
        const pFam = primary.family ? primary.family.toLowerCase().trim() : null;
        const sFam = secondary.family ? secondary.family.toLowerCase().trim() : null;
        if (pFam && sFam && pFam !== sFam) return false;

        // Partner conflict check
        if (this._hasRootPartnerConflict(primary, secondary)) return false;

        const pYob = primary.yob || primary._inferredYob;
        const sYob = secondary.yob || secondary._inferredYob;
        return !this._hasRootAgeCompatibilityViolation(primary, secondary, pYob, sYob);
    }

    /**
     * Transfers partner associations from a secondary root node to a primary root node,
     * unlinking the secondary root and ensuring age compatibility and deduplication of namesakes.
     *
     * @param {Object} primary - Primary root node absorbing partners
     * @param {Object} secondary - Secondary root node losing partners
     * @param {Object.<string, Object>} nodeMap - Map of all domain nodes keyed by id
     *
     * @example
     * // Primary (P1) absorbs partners from Secondary (P2):
     * FamilyTreeBuilder._transferSecondaryPartners(primary, secondary, nodeMap);
     *
     * @example
     * // Unlinks partner from secondary and attaches to primary when age compatible:
     * FamilyTreeBuilder._transferSecondaryPartners(targetNode, sourceNode, treeNodeMap);
     */
    static _transferSecondaryPartners(primary, secondary, nodeMap) {
        secondary.partners.forEach(partnerId => {
            const partner = nodeMap[partnerId];
            if (!partner || partner.id === primary.id) return;
            partner.partners = partner.partners.filter(id => id !== secondary.id && id !== primary.id);
            const validSpouse = FamilyTreeBuilder._arePartnersAgeCompatible(primary, partner, true);
            if (validSpouse) {
                // Check if primary already has an identical namesake partner (e.g. Ammini b. 1934)
                const existingSamePartner = primary.partners.map(pid => nodeMap[pid]).find(ep => ep && ep._normName === partner._normName && ep.yob === partner.yob && ep.yob);
                if (!existingSamePartner) {
                    if (!partner.partners.includes(primary.id)) partner.partners.push(primary.id);
                    if (!primary.partners.includes(partner.id)) primary.partners.push(partner.id);
                }
            }
        });
    }

    /**
     * Re-parents children of a secondary root node to a primary root node.
     *
     * @param {Object} primary - Target parent receiving children
     * @param {Object} secondary - Source parent losing children
     * @param {Object.<string, Object>} nodeMap - Map of all domain nodes keyed by id
     *
     * @example
     * // Secondary (P2) has child C1 (fatherId: 'P2'). Primary is P1:
     * FamilyTreeBuilder._transferSecondaryChildren(primary, secondary, nodeMap);
     *
     * @example
     * // Reparents children of source mother to target mother:
     * FamilyTreeBuilder._transferSecondaryChildren(targetMom, sourceMom, treeNodeMap);
     */
    static _transferSecondaryChildren(primary, secondary, nodeMap) {
        secondary.children.forEach(childId => {
            const child = nodeMap[childId];
            if (!child) return;
            if (child.fatherId === secondary.id) child.fatherId = primary.id;
            if (child.momId === secondary.id) child.momId = primary.id;
            if (!primary.children.includes(childId)) primary.children.push(childId);
        });
    }

    /**
     * Merges source tracking IDs and known or inferred birth years from a secondary node into primary.
     *
     * @param {Object} primary - Target node absorbing metadata
     * @param {Object} secondary - Source node providing metadata
     *
     * @example
     * // Primary has no YOB; secondary has YOB 1920 and sources ['S1']:
     * FamilyTreeBuilder._absorbSecondaryMetadata(primary, secondary);
     *
     * @example
     * // Merges inferred birth year and source IDs across duplicate roots:
     * FamilyTreeBuilder._absorbSecondaryMetadata(targetNode, sourceNode);
     */
    static _absorbSecondaryMetadata(primary, secondary) {
        secondary._sourceIds.forEach(sid => primary._sourceIds.add(sid));
        if (!primary.yob && secondary.yob) primary.yob = secondary.yob;
        if (!primary._inferredYob && secondary._inferredYob) primary._inferredYob = secondary._inferredYob;
    }

    /**
     * Absorbs a secondary root node's partners, children, and sources into the primary root node.
     *
     * @param {Object} primary - Target root node
     * @param {Object} secondary - Source root node to absorb and remove
     *
     * @example
     * builder._absorbSecondaryRoot(patriarch1, patriarch2);
     *
     * @example
     * builder._absorbSecondaryRoot(primaryRoot, duplicateRoot);
     */
    _absorbSecondaryRoot(primary, secondary) {
        FamilyTreeBuilder._transferSecondaryPartners(primary, secondary, this.nodeMap);
        FamilyTreeBuilder._transferSecondaryChildren(primary, secondary, this.nodeMap);
        FamilyTreeBuilder._absorbSecondaryMetadata(primary, secondary);

        // Clean up secondary
        secondary.children = [];
        secondary.partners = [];
        delete this.nodeMap[secondary.id];
    }

    /**
     * Links parent to an existing co-parent if any shared child already has another non-celibate parent.
     *
     * @param {Object} p - Parent node
     * @returns {boolean} True if a co-parent was linked, false otherwise
     *
     * @example
     * const linked = builder._linkCoParentPartner(singleParentNode);
     *
     * @example
     * const notLinked = builder._linkCoParentPartner(celibateReligiousParent);
     */
    _linkCoParentPartner(p) {
        for (const cid of p.children) {
            const child = this.nodeMap[cid];
            if (!child) continue;
            const otherId = (p.gender === 'F' || child.momId === p.id) ? child.fatherId : child.momId;
            if (otherId && this.nodeMap[otherId] && otherId !== p.id) {
                const other = this.nodeMap[otherId];
                if (!FamilyTreeBuilder._isCelibateReligious(other)) {
                    if (FamilyTreeBuilder._areBiologicalSiblings(p, other)) continue;
                    if (p.partners && p.partners.some(pid => FamilyTreeBuilder._areBiologicalSiblings(this.nodeMap[pid], other))) continue;
                    if (other.partners && other.partners.some(pid => FamilyTreeBuilder._areBiologicalSiblings(this.nodeMap[pid], p))) continue;
                    if (!p.partners.includes(other.id)) p.partners.push(other.id);
                    if (!other.partners.includes(p.id)) other.partners.push(p.id);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Assigns a parent's children to a newly linked partner and synchronizes parental IDs.
     *
     * @param {Object} p - Existing parent node
     * @param {Object} partner - Newly associated partner node
     * @param {boolean} isMale - Whether parent p is male (true) or female (false)
     *
     * @example
     * builder._assignChildrenToNewPartner(fatherNode, motherPartner, true);
     *
     * @example
     * builder._assignChildrenToNewPartner(motherNode, fatherPartner, false);
     */
    _assignChildrenToNewPartner(p, partner, isMale) {
        p.children.forEach(cid => {
            const child = this.nodeMap[cid];
            if (child) {
                if (isMale && !child.momId) child.momId = partner.id;
                else if (!isMale && !child.fatherId) child.fatherId = partner.id;
                if (!partner.children.includes(cid)) partner.children.push(cid);
            }
        });
    }

    /**
     * Finds and links an unattached relative candidate (e.g. '<Name> Wife' or '<Name> Husband')
     * on the same spreadsheet within close row proximity (<= 5 rows).
     *
     * @param {Object} p - Parent node
     * @param {boolean} isMale - Whether p is male
     * @param {string} targetRole - Expected partner role ('wife' or 'husband')
     * @returns {boolean} True if partner matched and linked, false otherwise
     *
     * @example
     * const linked = builder._linkMatchingSameSheetRelativeSpouse(personAntu, true, 'wife');
     *
     * @example
     * const notLinked = builder._linkMatchingSameSheetRelativeSpouse(personMary, false, 'husband');
     */
    _linkMatchingSameSheetRelativeSpouse(p, isMale, targetRole) {
        const targetSuffix = isMale ? ' Wife' : ' Husband';
        const expectedName = (p.name + targetSuffix).toLowerCase().trim();
        const sameSheetCandidates = Object.values(this.nodeMap).filter(c => 
            c && c !== p && FamilyTreeBuilder.sharesSheet(c, p) &&
            (!c.partners || c.partners.length === 0) &&
            (c._normName === expectedName || (c.spouse && c.spouse.toLowerCase().trim() === p._normName && FamilyTreeBuilder._getMinRowDistance(c, p) <= 5))
        );
        if (sameSheetCandidates.length === 0) return false;

        const partner = sameSheetCandidates[0];
        if (!p.partners.includes(partner.id)) p.partners.push(partner.id);
        if (!partner.partners.includes(p.id)) partner.partners.push(partner.id);
        this._assignChildrenToNewPartner(p, partner, isMale);
        return true;
    }

    /**
     * Creates and attaches a synthetic autoghost partner for a concrete parent lacking a spouse.
     *
     * @param {Object} p - Parent node
     * @param {boolean} isMale - Whether p is male
     * @param {string} targetRole - 'wife' or 'husband'
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder._createAutoGhostPartner(singleFather, true, 'wife', domainNodes);
     *
     * @example
     * builder._createAutoGhostPartner(singleMother, false, 'husband', domainNodes);
     */
    _createAutoGhostPartner(p, isMale, targetRole, nodes) {
        const partnerTitle = isMale ? 'Wife' : 'Husband';
        const partnerGender = isMale ? 'F' : 'M';
        const rawSpouseName = p.spouse ? p.spouse.split(/[,/]+/)[0].trim() : '';
        const partnerName = (rawSpouseName && !rawSpouseName.toLowerCase().includes('unknown'))
            ? rawSpouseName
            : `${p.name} ${partnerTitle}`;
        const ghostKey = `${p.id}_auto_${targetRole}`;
        const g = this._instantiateGhost(p, partnerName, targetRole, ghostKey, nodes);
        g.gender = partnerGender;
        g._isAutoPartner = true;
        if (!p.partners.includes(g.id)) p.partners.push(g.id);
        if (!g.partners.includes(p.id)) g.partners.push(p.id);
        this._assignChildrenToNewPartner(p, g, isMale);
        if (p.yob || p._inferredYob) {
            g._inferredYob = (p.yob || p._inferredYob) + (isMale ? FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET : -FamilyTreeBuilder.GENERATIONAL_GAPS.SPOUSAL_GENDER_OFFSET);
            const currentYear = new Date().getFullYear();
            if (!g.death && (currentYear - g._inferredYob > 100)) {
                g.death = g._inferredYob + 90;
            }
        }
    }

    /**
     * Ensures that every parent profile who has children also has a linked partner,
     * either by linking to an existing co-parent, matching a nearby '<Name> Wife/Husband',
     * or creating an autoghost partner for concrete parents without a spouse.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.ensureEveryParentHasPartner(domainNodes);
     *
     * @example
     * builder.ensureEveryParentHasPartner(allTreeNodes);
     */
    ensureEveryParentHasPartner(nodes) {
        nodes.forEach(p => {
            if (!p.children || p.children.length === 0) return;
            if (p.partners && p.partners.length > 0) return;

            // 1. Check if any child already has another parent set
            if (this._linkCoParentPartner(p)) return;

            // 2. Check if an unattached candidate matching <Name> Wife / Husband exists on same sheet
            const isMale = p.gender === 'M' || p.children.some(cid => this.nodeMap[cid]?.fatherId === p.id);
            const targetRole = isMale ? 'wife' : 'husband';
            if (this._linkMatchingSameSheetRelativeSpouse(p, isMale, targetRole)) return;

            // 3. Create autoghost partner only if partner info exists (e.g. named spouse)
            const rawSpouseName = p.spouse ? p.spouse.split(/[,/]+/)[0].trim() : '';
            const hasSpouseInfo = Boolean(rawSpouseName && !rawSpouseName.toLowerCase().includes('unknown'));
            if (!p.isGhost && hasSpouseInfo) {
                this._createAutoGhostPartner(p, isMale, targetRole, nodes);
            }
        });
    }

    /**
     * Merges disconnected root-level namesakes from different sheets.
     * When the same ancestor appears on multiple sheets (e.g. Anthony on
     * Vadakkethala with spouse Rosa, and Anthony on Ollur with spouse
     * Thandammama), they form separate disconnected subtrees. This method
     * merges them by absorbing the secondary node into the primary node.
     *
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.mergeDisconnectedRoots(domainNodes);
     *
     * @example
     * builder.mergeDisconnectedRoots(allTreeNodes);
     */
    mergeDisconnectedRoots(nodes) {
        const rootsByName = {};
        Object.values(this.nodeMap).forEach(n => {
            if (n.isGhost || n._isUnknown || n.fatherId || n.momId) return;
            if (!n.children || n.children.length === 0) return;
            const name = n._normName || n.name.toLowerCase().trim();
            if (!rootsByName[name]) rootsByName[name] = [];
            rootsByName[name].push(n);
        });

        Object.values(rootsByName).forEach(group => {
            if (group.length < 2) return;
            group.sort((a, b) => (a.yob || a._inferredYob || 9999) - (b.yob || b._inferredYob || 9999));

            const primary = group[0];
            for (let i = 1; i < group.length; i++) {
                const secondary = group[i];
                if (this._canMergeDisconnectedRoots(primary, secondary)) {
                    this._absorbSecondaryRoot(primary, secondary);
                }
            }
        });
    }

    /**
     * Calculates the number of unique reachable connected nodes in the genealogical graph
     * starting from a given person ID using breadth-first search.
     *
     * @param {string} startId - Initial person node ID
     * @param {Object<string, Object>} nodeMap - Mapping of person IDs to Person instances
     * @returns {number} Count of reachable nodes
     *
     * @example
     * const reach = FamilyTreeBuilder._computeGraphReach('p1', nodeMap);
     *
     * @example
     * const isolatedReach = FamilyTreeBuilder._computeGraphReach('single_node_id', nodeMap);
     */
    static _computeGraphReach(startId, nodeMap) {
        const visited = new Set();
        const queue = [startId];
        while (queue.length > 0) {
            const currId = queue.shift();
            if (visited.has(currId)) continue;
            visited.add(currId);
            const p = nodeMap[currId];
            if (!p) continue;
            const neighbors = [p.momId, p.fatherId, ...(p.partners || []), ...(p.children || [])].filter(Boolean);
            neighbors.forEach(nid => { if (!visited.has(nid)) queue.push(nid); });
        }
        return visited.size;
    }

    /**
     * Finds the optimal root node for the family tree, prioritizing the root candidate
     * that anchors the largest connected component (reach) in the genealogical graph,
     * breaking ties by earliest birth year.
     * 
     * @param {Object[]} nodes - List of domain nodes
     *
     * @example
     * builder.findRoot(domainNodes);
     *
     * @example
     * builder.findRoot(allTreeNodes);
     */
    findRoot(nodes) {
        let bestRoot = null;
        let maxReach = -1;
        let minYear = 9999;

        // Only consider active nodes currently in this.nodeMap (excluding deleted/absorbed ghosts)
        const activeNodes = (nodes || []).filter(n => n && this.nodeMap && this.nodeMap[n.id]);
        const rootCandidates = activeNodes.filter(n => !n.momId && !n.fatherId && !n._namedParentId);

        rootCandidates.forEach(n => {
            const reach = FamilyTreeBuilder._computeGraphReach(n.id, this.nodeMap);
            const yob = n.yob || n._inferredYob || 9999;

            if (reach > maxReach || (reach === maxReach && yob < minYear)) {
                maxReach = reach;
                minYear = yob;
                bestRoot = n;
            }
        });

        if (bestRoot) this.rootId = bestRoot.id;
        else if (activeNodes.length > 0) this.rootId = activeNodes[0].id;
        else if (this.nodeMap && Object.keys(this.nodeMap).length > 0) this.rootId = Object.keys(this.nodeMap)[0];
    }

    /**
     * Compact Trie / Radix Tree index for fast O(L) spatial location queries
     * supporting phonetic normalization (consonant folding, vowel normalization)
     * and longest prefix matching for transliterated town names.
     *
     * @example
     * const trie = new FamilyTreeBuilder.LocationTrie();
     *
     * @example
     * const geoTrie = FamilyTreeBuilder.getGeoTrie(LOCATION_GEO_HIERARCHY);
     */
    static LocationTrie = class LocationTrie {
        /**
         * Creates an empty LocationTrie instance.
         *
         * @example
         * const trie = new FamilyTreeBuilder.LocationTrie();
         *
         * @example
         * const locationIndex = new FamilyTreeBuilder.LocationTrie();
         */
        constructor() {
            this.root = { children: {}, value: null };
            this._size = 0;
        }

        /**
         * Normalizes a location query or key string by folding repeated vowels,
         * consonants, and aspirated digraphs for robust phonetic matching.
         *
         * @param {string} str - Raw location name
         * @returns {string} Normalized phonetic key
         *
         * @example
         * LocationTrie.normalizeKey("Chalakudy"); // => "calakudi"
         *
         * @example
         * LocationTrie.normalizeKey("Thrissur"); // => "trisur"
         */
        static normalizeKey(str) {
            if (!str) return '';
            return str.toLowerCase().trim()
                .replace(/[\r\n\t]+/g, ' ')
                .replace(/aa/g, 'a')
                .replace(/ee/g, 'i')
                .replace(/oo/g, 'u')
                .replace(/kk/g, 'k')
                .replace(/tt/g, 't')
                .replace(/pp/g, 'p')
                .replace(/ll/g, 'l')
                .replace(/dd/g, 'd')
                .replace(/rr/g, 'r')
                .replace(/ch/g, 'c');
        }

        /**
         * Inserts a geographic key-value mapping into the Trie, indexing both
         * raw lowercase and phonetically normalized keys.
         *
         * @param {string} key - Place name
         * @param {Object} value - Geographic metadata object
         * @returns {void}
         *
         * @example
         * trie.insert('chalakudy', { district: 'Thrissur' });
         *
         * @example
         * trie.insert('ollur', { district: 'Thrissur', state: 'Kerala' });
         */
        insert(key, value) {
            if (!key) return;
            const insertKey = (k) => {
                let curr = this.root;
                for (let i = 0; i < k.length; i++) {
                    const ch = k[i];
                    if (!curr.children[ch]) {
                        curr.children[ch] = { children: {}, value: null };
                    }
                    curr = curr.children[ch];
                }
                curr.value = value;
            };

            const lower = key.toLowerCase().trim();
            insertKey(lower);
            const norm = FamilyTreeBuilder.LocationTrie.normalizeKey(key);
            if (norm && norm !== lower) {
                insertKey(norm);
            }
            this._size++;
        }

        /**
         * Searches the Trie for an exact or phonetically equivalent key match.
         *
         * @param {string} query - Search term
         * @returns {Object|null} Associated geographic metadata or null
         *
         * @example
         * trie.search('chalakkudy'); // => { district: 'Thrissur' }
         *
         * @example
         * trie.search('unknown_place'); // => null
         */
        search(query) {
            if (!query) return null;
            const lookup = (q) => {
                let curr = this.root;
                for (let i = 0; i < q.length; i++) {
                    const ch = q[i];
                    if (!curr.children[ch]) return null;
                    curr = curr.children[ch];
                }
                return curr.value;
            };

            const direct = lookup(query.toLowerCase().trim());
            if (direct) return direct;
            const norm = FamilyTreeBuilder.LocationTrie.normalizeKey(query);
            return lookup(norm);
        }

        /**
         * Performs longest prefix matching for compound location queries (e.g. "Seattle, WA").
         *
         * @param {string} query - Query string
         * @returns {Object|null} Matching geographic metadata or null
         *
         * @example
         * trie.longestPrefixMatch('seattle, wa'); // => { state: 'Washington' }
         *
         * @example
         * trie.longestPrefixMatch('chalakudy town'); // => { district: 'Thrissur' }
         */
        longestPrefixMatch(query) {
            if (!query) return null;
            const match = (q) => {
                let curr = this.root;
                let lastVal = null;
                for (let i = 0; i < q.length; i++) {
                    const ch = q[i];
                    if (!curr.children[ch]) break;
                    curr = curr.children[ch];
                    if (curr.value) lastVal = curr.value;
                }
                return lastVal;
            };

            const direct = match(query.toLowerCase().trim());
            if (direct) return direct;
            const norm = FamilyTreeBuilder.LocationTrie.normalizeKey(query);
            return match(norm);
        }
    };

    /**
     * Expands a compressed dot-separated geographic hierarchy into a flat map of town names to metadata.
     *
     * @param {Object<string, string[]>} compressed - Map of "Country.State.District" to array of town names
     * @returns {Object<string, { country: ?string, state: ?string, district: ?string }>} Expanded mapping
     *
     * @example
     * FamilyTreeBuilder._expandGeoHierarchy({ "India.Kerala.Thrissur": ["Ollur", "Chalakudy"] });
     *
     * @example
     * FamilyTreeBuilder._expandGeoHierarchy({ "USA.WA.King": ["Seattle", "Bellevue"] });
     */
    static _expandGeoHierarchy(compressed) {
        const res = {};
        for (const [path, towns] of Object.entries(compressed)) {
            const [country, state, district] = path.split('.');
            const meta = Object.freeze({
                country: country || null,
                state: state || null,
                district: district || null
            });
            for (const t of towns) {
                res[t] = meta;
            }
        }
        return res;
    }

    /**
     * Cached singleton LocationTrie instance.
     * @type {FamilyTreeBuilder.LocationTrie|null}
     */
    static _geoTrieInstance = null;

    /**
     * Returns a singleton LocationTrie instance populated with geographic hierarchy data.
     *
     * @param {Object<string, Object>} hierarchy - Map of place names to geographic metadata
     * @returns {FamilyTreeBuilder.LocationTrie|null} Populated LocationTrie instance
     *
     * @example
     * const trie = FamilyTreeBuilder.getGeoTrie(LOCATION_GEO_HIERARCHY);
     *
     * @example
     * const cachedTrie = FamilyTreeBuilder.getGeoTrie();
     */
    static getGeoTrie(hierarchy) {
        if (!FamilyTreeBuilder._geoTrieInstance && hierarchy) {
            const trie = new FamilyTreeBuilder.LocationTrie();
            for (const [k, v] of Object.entries(hierarchy)) {
                trie.insert(k, v);
            }
            FamilyTreeBuilder._geoTrieInstance = trie;
        }
        return FamilyTreeBuilder._geoTrieInstance;
    }
}

// Alias Module 1 constants directly to FamilyTreeBuilder constants
GENERATIONAL_GAPS = FamilyTreeBuilder.GENERATIONAL_GAPS;
BIOLOGICAL_BOUNDS = FamilyTreeBuilder.BIOLOGICAL_BOUNDS;
HEURISTIC_PRIORS = FamilyTreeBuilder.HEURISTIC_PRIORS;
RELATIONSHIP_TOKENS = FamilyTreeBuilder.RELATIONSHIP_TOKENS;
TITLE_ONTOLOGY = FamilyTreeBuilder.TITLE_ONTOLOGY;
DemographicProfile = FamilyTreeBuilder.DemographicProfile;
DemographicProfile.DEFAULT = Object.freeze(new DemographicProfile());

/**
 * @fileoverview Renders a laid-out FamilyTree into standalone SVG markup.
 *
 * This is the lowest layer of the render stack: it owns XML escaping, person-card
 * geometry and typography, connector and timeline groups, and the assembly of a
 * complete <svg> document. It knows nothing about paper sizes or pagination —
 * {@link A4PrintComposer} sits on top of it for that.
 */

/**
 * Renders family tree layouts as pure SVG markup.
 *
 * Consumes the same layout data the on-screen canvas uses (via
 * `FamilyTreeBuilder.computeLayout`) so the exported vector output stays visually
 * faithful to the interactive view.
 *
 * @example
 * const { svg, width, height } = SvgTreeRenderer.generatePureSvgTree(tree, layoutConfig, {});
 * // => svg: '<svg xmlns="http://www.w3.org/2000/svg" ...>...</svg>'
 *
 * @example
 * SvgTreeRenderer._escapeSvgXml('Tom & Jerry');
 * // => 'Tom &amp; Jerry'
 */
class SvgTreeRenderer {

    /**
     * Escapes XML/SVG special characters in text strings.
     *
     * @param {string|*} str - Input string to escape
     * @returns {string} Escaped XML string
     *
     * @example
     * SvgTreeRenderer._escapeSvgXml('Tom & Jerry <cartoon> "2024"');
     * // => 'Tom &amp; Jerry &lt;cartoon&gt; &quot;2024&quot;'
     *
     * @example
     * SvgTreeRenderer._escapeSvgXml(null);
     * // => ''
     */
    static _escapeSvgXml(str) {
        if (!str) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');
    }

    /**
     * Wraps card text into up to 3 lines formatted for compact SVG display.
     *
     * @param {string} text - Input name or title
     * @param {number} [maxChars=13] - Maximum characters per line before line break
     * @returns {string[]} Array of up to 3 lines
     *
     * @example
     * SvgTreeRenderer._wrapSvgCardText('Grandfather Alexander The Great');
     * // => ['Grandfather', 'Alexander', 'The Great']
     *
     * @example
     * SvgTreeRenderer._wrapSvgCardText('Short Name');
     * // => ['Short Name']
     */
    static _wrapSvgCardText(text, maxChars = 13) {
        if (!text) return [];
        const words = String(text).trim().split(/\s+/);
        const lines = [];
        let cur = '';
        for (const w of words) {
            if (!cur) cur = w;
            else if ((cur + ' ' + w).length <= maxChars) cur += ' ' + w;
            else { lines.push(cur); cur = w; }
        }
        if (cur) lines.push(cur);
        const out = [];
        for (const l of lines) {
            if (l.length > 15) {
                out.push(l.slice(0, 13) + '-');
                out.push(l.slice(13));
            } else {
                out.push(l);
            }
        }
        return out.slice(0, 3);
    }

    /**
     * Renders background timeline grid lines and year labels for SVG trees.
     *
     * @param {FamilyTree} tree - Populated tree instance
     * @param {Object} layoutConfig - Layout configuration
     * @param {number} padY - Vertical padding offset
     * @param {number} totalW - Canvas total width
     * @param {number} totalH - Canvas total height
     * @returns {string} SVG snippet of timeline grid lines and year markers
     *
     * @example
     * SvgTreeRenderer._renderSvgTimelineGrid(tree, { ppy: 1.5 }, 20, 1000, 800);
     * // => '<line x1="0" y1="24.0" .../><text x="6" ...>1900</text>...'
     *
     * @example
     * SvgTreeRenderer._renderSvgTimelineGrid(null, {}, 0, 100, 100);
     * // => ''
     */
    static _renderSvgTimelineGrid(tree, layoutConfig, padY, totalW, totalH) {
        if (!tree || typeof tree.getStats !== 'function') return '';
        const stats = tree.getStats();
        const rootYob = stats.rootNodeYob || 1900;
        const maxYear = stats.maxYear || new Date().getFullYear();
        const ppy = layoutConfig?.ppy || 1.5;
        const step = (maxYear - rootYob > 80) ? 20 : 10;
        const startYear = Math.floor(rootYob / step) * step;

        let timelineSvg = '';
        for (let y = startYear; y <= maxYear; y += step) {
            const lineY = ((y - rootYob) * ppy + 24) + padY;
            if (lineY >= 0 && lineY <= totalH) {
                timelineSvg += `<line x1="0" y1="${lineY.toFixed(1)}" x2="${totalW.toFixed(1)}" y2="${lineY.toFixed(1)}" stroke="#f1f5f9" stroke-width="1" stroke-dasharray="4,4"/>`;
                timelineSvg += `<text x="6" y="${(lineY - 4).toFixed(1)}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="9" font-weight="bold" fill="#cbd5e1" opacity="0.8">${y}</text>`;
            }
        }
        return timelineSvg;
    }

    /**
     * Resolves SVG color theme palette according to person gender.
     *
     * @param {'M'|'F'|string} [gender] - Gender character
     * @returns {{ bg: string, border: string, text: string, dateBg: string, dateText: string, jobText: string }}
     *
     * @example
     * SvgTreeRenderer._getSvgCardTheme('M');
     * // => { bg: '#e0f2fe', border: '#7dd3fc', text: '#082f49', dateBg: '#bae6fd', dateText: '#0c4a6e', jobText: '#0369a1' }
     *
     * @example
     * SvgTreeRenderer._getSvgCardTheme('F');
     * // => { bg: '#ffe4e6', border: '#fda4af', text: '#4c0519', dateBg: '#fecdd3', dateText: '#881337', jobText: '#be123c' }
     */
    static _getSvgCardTheme(gender) {
        if (gender === 'M') {
            return { bg: '#e0f2fe', border: '#7dd3fc', text: '#082f49', dateBg: '#bae6fd', dateText: '#0c4a6e', jobText: '#0369a1' };
        }
        if (gender === 'F') {
            return { bg: '#ffe4e6', border: '#fda4af', text: '#4c0519', dateBg: '#fecdd3', dateText: '#881337', jobText: '#be123c' };
        }
        return { bg: '#f1f5f9', border: '#cbd5e1', text: '#0f172a', dateBg: '#e2e8f0', dateText: '#334155', jobText: '#475569' };
    }

    /**
     * Renders the date badge element for an SVG person card.
     *
     * @param {Object} cardInfo - Date info object with cardText and isDeduced
     * @param {string} dateBg - Badge background color
     * @param {string} dateText - Badge text color
     * @param {number} currentY - Current vertical cursor position
     * @returns {{ svg: string, nextY: number }} Rendered SVG string and updated Y position
     *
     * @example
     * SvgTreeRenderer._renderSvgCardDateBadge({ cardText: 'b. 1950', isDeduced: false }, '#e2e8f0', '#334155', 38);
     * // => { svg: '<rect .../><text ...>b. 1950</text>', nextY: 53 }
     *
     * @example
     * SvgTreeRenderer._renderSvgCardDateBadge(null, '#e2e8f0', '#334155', 38);
     * // => { svg: '', nextY: 38 }
     */
    static _renderSvgCardDateBadge(cardInfo, dateBg, dateText, currentY) {
        const cardText = cardInfo?.cardText;
        if (!cardText || currentY >= 58) return { svg: '', nextY: currentY };
        const badgeW = Math.min(82, Math.max(36, cardText.length * 5.8 + 8));
        const badgeX = 45 - badgeW / 2;
        let svg = `<rect x="${badgeX.toFixed(1)}" y="${currentY.toFixed(1)}" width="${badgeW.toFixed(1)}" height="13" rx="3" ry="3" fill="${dateBg}" stroke="rgba(0,0,0,0.06)" stroke-width="0.5"/>`;
        svg += `<text x="45" y="${(currentY + 9.5).toFixed(1)}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="9" font-weight="600" fill="${dateText}" text-anchor="middle"${cardInfo.isDeduced ? ' font-style="italic"' : ''}>${SvgTreeRenderer._escapeSvgXml(cardText)}</text>`;
        return { svg, nextY: currentY + 15 };
    }

    /**
     * Renders job or nickname subtitle text for an SVG person card.
     *
     * @param {Person} p - Person instance
     * @param {number} currentY - Current vertical cursor position
     * @param {string} jobText - Text fill color for jobs
     * @param {string} defaultText - Text fill color for nicknames
     * @returns {string} Rendered subtitle SVG string
     *
     * @example
     * SvgTreeRenderer._renderSvgCardSubtitle({ job: 'Doctor' }, 53, '#475569', '#0f172a');
     * // => '<text ...>Doctor</text>'
     *
     * @example
     * SvgTreeRenderer._renderSvgCardSubtitle({ nick: 'Bobby' }, 53, '#475569', '#0f172a');
     * // => '<text ...>"Bobby"</text>'
     */
    static _renderSvgCardSubtitle(p, currentY, jobText, defaultText) {
        if (currentY >= 70) return '';
        if (p.job) {
            const jobStr = p.job.length > 14 ? p.job.slice(0, 13) + '…' : p.job;
            return `<text x="45" y="${(currentY + 4).toFixed(1)}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="8.5" font-weight="500" fill="${jobText}" text-anchor="middle">${SvgTreeRenderer._escapeSvgXml(jobStr)}</text>`;
        }
        if (p.nick) {
            const nickStr = p.nick.length > 14 ? p.nick.slice(0, 13) + '…' : p.nick;
            return `<text x="45" y="${(currentY + 4).toFixed(1)}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="8.5" font-style="italic" fill="${defaultText}" opacity="0.75" text-anchor="middle">&quot;${SvgTreeRenderer._escapeSvgXml(nickStr)}&quot;</text>`;
        }
        return '';
    }

    /**
     * Formats an SVG text element with tspans for multi-line person names on cards.
     *
     * @private
     * @param {string[]} nameLines - Wrapped lines of person name
     * @param {number} startNameY - Starting baseline Y coordinate
     * @param {string} text - Fill text color hex code
     * @returns {string} SVG text element markup
     *
     * @example
     * SvgTreeRenderer._renderSvgCardNameText(['Alice', 'Smith'], 18, '#1e293b');
     * // => '<text x="45" y="18" ...><tspan x="45" dy="0">Alice</tspan><tspan x="45" dy="13">Smith</tspan></text>'
     *
     * @example
     * SvgTreeRenderer._renderSvgCardNameText(['Bob'], 24, '#0f172a');
     * // => '<text x="45" y="24" ...><tspan x="45" dy="0">Bob</tspan></text>'
     */
    static _renderSvgCardNameText(nameLines, startNameY, text) {
        const tspans = nameLines.map((line, idx) =>
            `<tspan x="45" dy="${idx === 0 ? 0 : 13}">${SvgTreeRenderer._escapeSvgXml(line)}</tspan>`
        ).join('');
        return `<text x="45" y="${startNameY}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="11" font-weight="bold" fill="${text}" text-anchor="middle">${tspans}</text>`;
    }

    /**
     * Renders an individual person node card as SVG elements.
     *
     * @param {Person} p - Person instance
     * @param {number} nx - Absolute X coordinate
     * @param {number} ny - Absolute Y coordinate
     * @returns {string} SVG snippet representing the person card
     *
     * @example
     * SvgTreeRenderer._renderSvgPersonCard(person, 100, 200);
     * // => '<g class="person-node" transform="translate(100.0, 200.0)"><rect width="90" .../>...</g>'
     *
     * @example
     * SvgTreeRenderer._renderSvgPersonCard(null, 0, 0);
     * // => ''
     */
    static _renderSvgPersonCard(p, nx, ny) {
        if (!p) return '';
        const isGhost = !!p.isGhost;
        const { bg, border, text, dateBg, dateText, jobText } = SvgTreeRenderer._getSvgCardTheme(p.gender);

        const strokeDash = isGhost ? 'stroke-dasharray="4,4" opacity="0.85"' : '';
        const nameLines = SvgTreeRenderer._wrapSvgCardText(p.name || 'Unknown');
        const startNameY = nameLines.length === 1 ? 24 : (nameLines.length === 2 ? 18 : 14);

        let cardSvg = `<g class="person-node" transform="translate(${nx.toFixed(1)}, ${ny.toFixed(1)})">`;
        cardSvg += `<rect width="90" height="76" rx="12" ry="12" fill="${bg}" stroke="${border}" stroke-width="2" ${strokeDash}/>`;
        cardSvg += SvgTreeRenderer._renderSvgCardNameText(nameLines, startNameY, text);

        const cardInfo = typeof p.getCardDateString === 'function' ? p.getCardDateString() : null;
        let currentY = startNameY + (nameLines.length - 1) * 13 + 12;

        const dateBadge = SvgTreeRenderer._renderSvgCardDateBadge(cardInfo, dateBg, dateText, currentY);
        cardSvg += dateBadge.svg;
        currentY = dateBadge.nextY;

        cardSvg += SvgTreeRenderer._renderSvgCardSubtitle(p, currentY, jobText, text);
        cardSvg += '</g>';
        return cardSvg;
    }

    /**
     * Renders an SVG <g class="tree-connectors"> element containing all connector paths.
     *
     * @param {Array<Object>} paths - Array of path objects with 'd' attribute string.
     * @param {number} padX - Horizontal padding offset.
     * @param {number} padY - Vertical padding offset.
     * @returns {string} SVG group markup string.
     *
     * @example
     * SvgTreeRenderer._renderSvgConnectorsGroup([{ d: 'M 0 0 L 10 10' }], 10, 20);
     * // => '<g class="tree-connectors" ...><path d="M 0 0 L 10 10" /></g>'
     *
     * @example
     * SvgTreeRenderer._renderSvgConnectorsGroup([], 0, 0);
     * // => '<g class="tree-connectors" ...></g>'
     */
    static _renderSvgConnectorsGroup(paths, padX, padY) {
        let pathsSvg = `<g class="tree-connectors" stroke="#cbd5e1" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" transform="translate(${padX.toFixed(1)}, ${padY.toFixed(1)})">`;
        for (const p of paths) {
            pathsSvg += `<path d="${p.d}" />`;
        }
        pathsSvg += '</g>';
        return pathsSvg;
    }

    /**
     * Renders an SVG <g class="tree-nodes"> element containing cards for all layout nodes.
     *
     * @param {Array<Object>} nodes - Array of layout node objects with person, x, and y.
     * @param {number} padX - Horizontal padding offset.
     * @param {number} padY - Vertical padding offset.
     * @returns {string} SVG group markup string.
     *
     * @example
     * SvgTreeRenderer._renderSvgNodesGroup([{ person: p1, x: 50, y: 100 }], 10, 20);
     * // => '<g class="tree-nodes"><g class="person-node" ...>...</g></g>'
     *
     * @example
     * SvgTreeRenderer._renderSvgNodesGroup([], 0, 0);
     * // => '<g class="tree-nodes"></g>'
     */
    static _renderSvgNodesGroup(nodes, padX, padY) {
        let nodesSvg = '<g class="tree-nodes">';
        for (const n of nodes) {
            nodesSvg += SvgTreeRenderer._renderSvgPersonCard(n.person, n.x + padX, n.y + padY);
        }
        nodesSvg += '</g>';
        return nodesSvg;
    }

    /**
     * Composes SVG markup containing timeline grid, connector paths, and person cards.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} layoutConfig - Layout configuration
     * @param {Object} layoutData - Computed layout geometry
     * @param {Object} options - Formatting and feature flags
     * @param {Object} svgBounds - Canvas padding and dimensions ({ padX, padY, totalW, totalH })
     * @returns {{ fullSvg: string, innerSvg: string }}
     *
     * @example
     * SvgTreeRenderer._composeSvgTreeContent(tree, {}, layoutData, {}, { padX: 10, padY: 10, totalW: 500, totalH: 400 });
     * // => { fullSvg: '<svg ...>...</svg>', innerSvg: '...' }
     *
     * @example
     * SvgTreeRenderer._composeSvgTreeContent(tree, {}, { paths: [], nodes: [] }, { showTimeline: false }, { padX: 0, padY: 0, totalW: 100, totalH: 100 });
     * // => { fullSvg: '<svg ...></svg>', innerSvg: '<g ...></g><g ...></g>' }
     */
    static _composeSvgTreeContent(tree, layoutConfig, layoutData, options, svgBounds) {
        const { padX, padY, totalW, totalH } = svgBounds;
        const timelineSvg = options.showTimeline !== false
            ? SvgTreeRenderer._renderSvgTimelineGrid(tree, layoutConfig, padY, totalW, totalH)
            : '';
        const pathsSvg = SvgTreeRenderer._renderSvgConnectorsGroup(layoutData.paths, padX, padY);
        const nodesSvg = SvgTreeRenderer._renderSvgNodesGroup(layoutData.nodes, padX, padY);

        const innerSvg = `${timelineSvg}${pathsSvg}${nodesSvg}`;
        const fullSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${totalW.toFixed(1)}" height="${totalH.toFixed(1)}" viewBox="0 0 ${totalW.toFixed(1)} ${totalH.toFixed(1)}">${innerSvg}</svg>`;
        return { fullSvg, innerSvg };
    }

    /**
     * Returns a fallback empty SVG tree result when layout data contains no renderable nodes.
     *
     * @returns {{ svg: string, innerSvg: string, width: number, height: number, padX: number, padY: number, layoutData: null }}
     *
     * @example
     * SvgTreeRenderer._createEmptySvgTreeResult().width;
     * // => 100
     *
     * @example
     * SvgTreeRenderer._createEmptySvgTreeResult().layoutData;
     * // => null
     */
    static _createEmptySvgTreeResult() {
        return {
            svg: '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"></svg>',
            innerSvg: '',
            width: 100,
            height: 100,
            padX: 0,
            padY: 0,
            layoutData: null
        };
    }

    /**
     * Generates a self-contained SVG representation of the entire family tree canvas.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layoutConfig={}] - Tree layout options
     * @param {Object} [options={}] - Formatting options
     * @returns {{ svg: string, innerSvg: string, width: number, height: number, padX: number, padY: number, layoutData: Object }}
     *
     * @example
     * const svgResult = SvgTreeRenderer.generatePureSvgTree(tree);
     * // => { svg: '<svg ...>...</svg>', innerSvg: '...', width: 1200, height: 800, ... }
     *
     * @example
     * const svgResult = SvgTreeRenderer.generatePureSvgTree(null);
     * // => { svg: '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"></svg>', innerSvg: '', ... }
     */
    static generatePureSvgTree(tree, layoutConfig = {}, options = {}) {
        const layoutData = FamilyTreeBuilder.computeLayout(tree, layoutConfig);
        if (!layoutData || layoutData.nodes.length === 0) {
            return SvgTreeRenderer._createEmptySvgTreeResult();
        }

        const cardPadPx = typeof options.cardPadPx === 'number' ? options.cardPadPx : 15;
        const padX = cardPadPx - layoutData.minX;
        const padY = cardPadPx - layoutData.minY;
        const totalW = layoutData.width + cardPadPx * 2;
        const totalH = layoutData.height + cardPadPx * 2;

        const { fullSvg, innerSvg } = SvgTreeRenderer._composeSvgTreeContent(
            tree, layoutConfig, layoutData, options, { padX, padY, totalW, totalH }
        );

        return {
            svg: fullSvg,
            innerSvg,
            width: totalW,
            height: totalH,
            padX,
            padY,
            layoutData
        };
    }

    /**
     * Parses the bounding box / dimensions from an SVG string via viewBox or width/height attributes.
     *
     * @param {string} rawSvg - Raw SVG string.
     * @returns {{ vbX: number, vbY: number, vbW: number, vbH: number }} Parsed SVG bounds.
     *
     * @example
     * SvgTreeRenderer._parseSvgDimensions('<svg viewBox="0 0 1000 800">');
     * // => { vbX: 0, vbY: 0, vbW: 1000, vbH: 800 }
     *
     * @example
     * SvgTreeRenderer._parseSvgDimensions('<svg width="600" height="400">');
     * // => { vbX: 0, vbY: 0, vbW: 600, vbH: 400 }
     */
    static _parseSvgDimensions(rawSvg) {
        let vbX = 0, vbY = 0, vbW = 1000, vbH = 1000;
        const vbMatch = rawSvg.match(/viewBox\s*=\s*["']([^"']+)["']/i);
        if (vbMatch) {
            const parts = vbMatch[1].trim().split(/[\s,]+/).map(Number);
            if (parts.length >= 4 && !isNaN(parts[2]) && !isNaN(parts[3])) {
                vbX = parts[0]; vbY = parts[1]; vbW = parts[2]; vbH = parts[3];
            }
        } else {
            const wMatch = rawSvg.match(/width\s*=\s*["']?(\d+(?:\.\d+)?)/i);
            const hMatch = rawSvg.match(/height\s*=\s*["']?(\d+(?:\.\d+)?)/i);
            if (wMatch) vbW = parseFloat(wMatch[1]);
            if (hMatch) vbH = parseFloat(hMatch[1]);
        }
        return { vbX, vbY, vbW, vbH };
    }
}

/**
 * @fileoverview Wraps raw SVG markup in a self-contained, interactive HTML page.
 *
 * The exported file has no network dependencies: pan/zoom handlers, gesture
 * support, keyboard shortcuts, and toolbar styling are all inlined, so a shared
 * export keeps working offline. Independent of the rest of the render stack — it
 * takes SVG markup as input and never builds it.
 */

/**
 * Builds a standalone HTML viewer document around a raw SVG image.
 *
 * Also normalizes the `data:` URLs produced by canvas export so callers can hand
 * over whatever the browser gave them.
 *
 * @example
 * const html = SvgViewerDocument.buildInlineSvgHtml('<svg>...</svg>', 'Family Tree');
 * // => '<!DOCTYPE html>...' with inlined pan/zoom script
 *
 * @example
 * SvgViewerDocument.extractRawSvgFromDataUrl('data:image/svg+xml;utf8,<svg></svg>');
 * // => '<svg></svg>'
 */
class SvgViewerDocument {

    /**
     * Extracts raw SVG XML content from a data URL (URL-encoded or base64).
     *
     * @param {string} dataUrl - Data URL containing SVG content
     * @returns {string} Raw <svg>...</svg> string
     *
     * @example
     * SvgViewerDocument.extractRawSvgFromDataUrl('data:image/svg+xml;utf8,<svg></svg>')
     * // => '<svg></svg>'
     *
     * @example
     * SvgViewerDocument.extractRawSvgFromDataUrl('')
     * // => ''
     */
    static extractRawSvgFromDataUrl(dataUrl) {
        if (!dataUrl) return '';
        const commaIdx = dataUrl.indexOf(',');
        if (commaIdx === -1) return dataUrl;
        const header = dataUrl.substring(0, commaIdx);
        const content = dataUrl.substring(commaIdx + 1);
        if (header.includes('base64')) {
            try {
                return decodeURIComponent(escape(atob(content)));
            } catch (e) {
                return atob(content);
            }
        }
        try {
            return decodeURIComponent(content);
        } catch (e) {
            return unescape(content);
        }
    }

    /**
     * Generates CSS styles for the SVG canvas and viewport container.
     *
     * @returns {string} Viewport and canvas CSS rules.
     *
     * @example
     * SvgViewerDocument._getInlineSvgViewportStyles().includes('#tree-viewport')
     * // => true
     *
     * @example
     * const styles = SvgViewerDocument._getInlineSvgViewportStyles();
     * console.log(styles.includes('#tree-canvas'));
     */
    static _getInlineSvgViewportStyles() {
        return `body { margin: 0; display: flex; justify-content: center; align-items: center; min-height: 100vh; background: #f0f0f0; }
        svg { max-width: 100%; height: auto; box-shadow: 0 4px 10px rgba(0,0,0,0.1); background: white; }
        html, body {
            width: 100%; height: 100%; overflow: hidden; background: #f8fafc;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        }
        #tree-viewport {
            width: 100vw; height: 100vh; overflow: auto; display: block;
            cursor: grab; position: relative; scrollbar-width: thin;
        }
        #tree-viewport:active { cursor: grabbing; }
        #tree-canvas { display: inline-block; transform-origin: 0 0; padding: 40px; box-sizing: border-box; }
        #tree-canvas svg {
            max-width: none !important; height: auto !important;
            box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
            border-radius: 8px; background: #ffffff; display: block;
        }`;
    }

    /**
     * Generates CSS styles for the floating pan/zoom control toolbar.
     *
     * @returns {string} Toolbar CSS rules.
     *
     * @example
     * SvgViewerDocument._getInlineSvgToolbarStyles().includes('.zoom-toolbar')
     * // => true
     *
     * @example
     * const styles = SvgViewerDocument._getInlineSvgToolbarStyles();
     * console.log(styles.includes('.zoom-btn'));
     */
    static _getInlineSvgToolbarStyles() {
        return `.zoom-toolbar {
            position: fixed; bottom: 24px; right: 24px; display: flex; align-items: center; gap: 6px;
            background: rgba(255, 255, 255, 0.94); backdrop-filter: blur(8px);
            border: 1px solid rgba(226, 232, 240, 0.9); box-shadow: 0 4px 16px rgba(15, 23, 42, 0.08);
            border-radius: 9999px; padding: 4px 8px; z-index: 9999; user-select: none;
        }
        .zoom-btn {
            background: transparent; border: none; cursor: pointer; padding: 6px 10px; font-size: 14px;
            font-weight: 600; color: #334155; border-radius: 9999px; display: flex; align-items: center;
            justify-content: center; transition: all 0.15s ease;
        }
        .zoom-btn:hover { background: #f1f5f9; color: #0f172a; }
        .zoom-level { font-size: 12px; font-weight: 600; color: #64748b; min-width: 44px; text-align: center; }`;
    }

    /**
     * Generates combined CSS styles for the inline SVG viewer wrapper.
     *
     * @returns {string} CSS styles for SVG viewport, canvas, and zoom controls.
     *
     * @example
     * SvgViewerDocument._getInlineSvgStyles().includes('#tree-viewport')
     * // => true
     *
     * @example
     * SvgViewerDocument._getInlineSvgStyles().includes('.zoom-toolbar')
     * // => true
     */
    static _getInlineSvgStyles() {
        return `${SvgViewerDocument._getInlineSvgViewportStyles()}\n${SvgViewerDocument._getInlineSvgToolbarStyles()}`;
    }

    /**
     * Generates HTML markup for the floating zoom toolbar in the inline SVG viewer.
     *
     * @returns {string} Toolbar HTML markup string.
     *
     * @example
     * SvgViewerDocument._getInlineSvgToolbarHtml().includes('zoom-toolbar')
     * // => true
     *
     * @example
     * SvgViewerDocument._getInlineSvgToolbarHtml().includes('btn-fit')
     * // => true
     */
    static _getInlineSvgToolbarHtml() {
        return `<div class="zoom-toolbar">
        <button class="zoom-btn" id="btn-out" title="Zoom Out ( - )">−</button>
        <span class="zoom-level" id="zoom-text">100%</span>
        <button class="zoom-btn" id="btn-in" title="Zoom In ( + )">+</button>
        <div style="width: 1px; height: 16px; background: #cbd5e1; margin: 0 2px;"></div>
        <button class="zoom-btn" id="btn-fit" title="Fit to Window ( 0 )">Fit</button>
        <button class="zoom-btn" id="btn-actual" title="Actual Size ( 1 )">100%</button>
    </div>`;
    }

    /**
     * Generates JavaScript zoom and window fitting helper functions for inline SVG viewer.
     *
     * @returns {string} JS script fragment for zoom and fit logic.
     *
     * @example
     * SvgViewerDocument._getInlineSvgZoomFunctions().includes('function updateZoom')
     * // => true
     *
     * @example
     * const fns = SvgViewerDocument._getInlineSvgZoomFunctions();
     * console.log(fns.includes('fitToWindow'));
     */
    static _getInlineSvgZoomFunctions() {
        return `            function updateZoom(newScale, focalX, focalY) {
                newScale = Math.min(maxScale, Math.max(minScale, newScale));
                if (Math.abs(newScale - scale) < 0.001) return;
                const prevScale = scale;
                scale = newScale;
                if (canvas) canvas.style.transform = "scale(" + scale + ")";
                if (zoomText) zoomText.textContent = Math.round(scale * 100) + "%";
                if (focalX !== undefined && focalY !== undefined && viewport) {
                    const ratio = scale / prevScale;
                    viewport.scrollLeft = (viewport.scrollLeft + focalX) * ratio - focalX;
                    viewport.scrollTop = (viewport.scrollTop + focalY) * ratio - focalY;
                }
            }
            function fitToWindow() {
                if (!svg || !viewport) return;
                const naturalW = svg.getAttribute("width") ? parseFloat(svg.getAttribute("width")) : (svg.viewBox?.baseVal?.width || 1200);
                const naturalH = svg.getAttribute("height") ? parseFloat(svg.getAttribute("height")) : (svg.viewBox?.baseVal?.height || 800);
                const availW = viewport.clientWidth - 80;
                const availH = viewport.clientHeight - 80;
                if (naturalW <= 0 || naturalH <= 0 || availW <= 0 || availH <= 0) return;
                const scaleW = availW / naturalW;
                const scaleH = availH / naturalH;
                const targetScale = Math.min(1.0, Math.max(minScale, Math.min(scaleW, scaleH)));
                updateZoom(targetScale);
                viewport.scrollLeft = Math.max(0, (canvas.scrollWidth * targetScale - viewport.clientWidth) / 2);
                viewport.scrollTop = 0;
            }`;
    }

    /**
     * Generates JavaScript event listeners for zoom toolbar buttons and keyboard shortcuts.
     *
     * @returns {string} Script fragment binding zoom buttons and keys.
     *
     * @example
     * const script = SvgViewerDocument._getInlineSvgZoomShortcuts();
     * console.log(script.includes('btnIn'));
     *
     * @example
     * SvgViewerDocument._getInlineSvgZoomShortcuts().includes('keydown');
     * // => true
     */
    static _getInlineSvgZoomShortcuts() {
        return `            if (btnIn) btnIn.addEventListener("click", () => updateZoom(scale * 1.25));
            if (btnOut) btnOut.addEventListener("click", () => updateZoom(scale * 0.8));
            if (btnActual) btnActual.addEventListener("click", () => updateZoom(1.0));
            if (btnFit) btnFit.addEventListener("click", fitToWindow);
            window.addEventListener("keydown", (e) => {
                if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
                if ((e.key === "+" || e.key === "=") && !e.ctrlKey && !e.metaKey) { e.preventDefault(); updateZoom(scale * 1.2); }
                else if ((e.key === "-" || e.key === "_") && !e.ctrlKey && !e.metaKey) { e.preventDefault(); updateZoom(scale * 0.8); }
                else if (e.key === "0" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); fitToWindow(); }
                else if (e.key === "1" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); updateZoom(1.0); }
            });`;
    }

    /**
     * Generates event listener bindings for dragging, wheel zoom, and keyboard shortcuts.
     *
     * @returns {string} JS script fragment for gesture and event handlers.
     *
     * @example
     * SvgViewerDocument._getInlineSvgGestureHandlers().includes('viewport.addEventListener')
     * // => true
     *
     * @example
     * const handlers = SvgViewerDocument._getInlineSvgGestureHandlers();
     * console.log(handlers.includes('keydown'));
     */
    static _getInlineSvgGestureHandlers() {
        return `            let isDragging = false;
            let startX = 0, startY = 0;
            let initialScrollLeft = 0, initialScrollTop = 0;
            if (viewport) {
                viewport.addEventListener("mousedown", (e) => {
                    if (e.target.closest(".zoom-toolbar")) return;
                    isDragging = true; startX = e.clientX; startY = e.clientY;
                    initialScrollLeft = viewport.scrollLeft; initialScrollTop = viewport.scrollTop;
                });
                window.addEventListener("mousemove", (e) => {
                    if (!isDragging) return;
                    e.preventDefault();
                    viewport.scrollLeft = initialScrollLeft - (e.clientX - startX);
                    viewport.scrollTop = initialScrollTop - (e.clientY - startY);
                });
                window.addEventListener("mouseup", () => { isDragging = false; });
                viewport.addEventListener("wheel", (e) => {
                    if (e.ctrlKey || e.metaKey) {
                        e.preventDefault();
                        const rect = viewport.getBoundingClientRect();
                        const factor = e.deltaY < 0 ? 1.1 : 0.9;
                        updateZoom(scale * factor, e.clientX - rect.left, e.clientY - rect.top);
                    }
                }, { passive: false });
            }
${SvgViewerDocument._getInlineSvgZoomShortcuts()}`;
    }

    /**
     * Generates the client-side JavaScript that enables smooth pan, zoom, wheel pinch, and keyboard navigation.
     *
     * @returns {string} Self-invoking JavaScript code wrapped in a <script> tag.
     *
     * @example
     * SvgViewerDocument._getInlineSvgPanZoomScript().includes('<script>')
     * // => true
     *
     * @example
     * SvgViewerDocument._getInlineSvgPanZoomScript().includes('updateZoom')
     * // => true
     */
    static _getInlineSvgPanZoomScript() {
        return `<script>
        (function() {
            const viewport = document.getElementById("tree-viewport");
            const canvas = document.getElementById("tree-canvas");
            const zoomText = document.getElementById("zoom-text");
            const btnIn = document.getElementById("btn-in");
            const btnOut = document.getElementById("btn-out");
            const btnFit = document.getElementById("btn-fit");
            const btnActual = document.getElementById("btn-actual");
            const svg = canvas ? canvas.querySelector("svg") : null;
            let scale = 1.0;
            const minScale = 0.1;
            const maxScale = 5.0;
${SvgViewerDocument._getInlineSvgZoomFunctions()}
${SvgViewerDocument._getInlineSvgGestureHandlers()}
            if (document.readyState === "loading") {
                window.addEventListener("DOMContentLoaded", fitToWindow);
            } else {
                setTimeout(fitToWindow, 50);
            }
        })();
    </script>`;
    }

    /**
     * Generates a self-contained HTML document with inline SVG wrapper.
     *
     * @param {string} rawSvg - Raw SVG code
     * @param {string} [title='Family Tree'] - Page title
     * @returns {string} HTML document content
     *
     * @example
     * SvgViewerDocument.buildInlineSvgHtml('<svg></svg>', 'My Tree')
     * // => '<!DOCTYPE html><html>...'
     *
     * @example
     * SvgViewerDocument.buildInlineSvgHtml('<svg viewBox="0 0 100 100"></svg>')
     * // => HTML document with default title 'Family Tree'
     */
    static buildInlineSvgHtml(rawSvg, title = 'Family Tree') {
        return `<!DOCTYPE html>
<html>
<head>
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${title}</title>
    <link rel="icon" type="image/svg+xml" href="${FamilyTreeBuilder.FAVICON_DATA_URI}">
    <style>
        ${SvgViewerDocument._getInlineSvgStyles()}
    </style>
</head>
<body>

    <div id="tree-viewport">
        <div id="tree-canvas">
            <!-- YOUR WEB APP INJECTS THE RAW <svg>...</svg> CODE HERE -->
            ${rawSvg}
        </div>
    </div>

    ${SvgViewerDocument._getInlineSvgToolbarHtml()}

    ${SvgViewerDocument._getInlineSvgPanZoomScript()}
</body>
</html>
`;
    }
}

/**
 * @fileoverview Paginates a family tree across A4 sheets and composes printable HTML.
 *
 * The top layer of the render stack. It decides how many pages the tree needs and
 * at what scale, slices the rendered vector output into per-page tiles, builds the
 * assembly guide and chapter atlas, and emits a print-ready document. Delegates
 * all SVG generation to {@link SvgTreeRenderer}.
 */

/**
 * Composes multi-page A4 print documents from a family tree.
 *
 * Two entry points exist because printing can start from either end: build the
 * vector art here (`buildPrintableA4Html`), or paginate SVG that was already
 * captured from the live canvas (`buildPrintableA4HtmlFromSvg`).
 *
 * @example
 * const grid = A4PrintComposer.computeA4PrintGrid(tree, layoutConfig, { mode: 'compact', targetPages: 8 });
 * // => { cols: 4, rows: 2, tiles: [...], scale: 0.42 }
 *
 * @example
 * const html = A4PrintComposer.buildPrintableA4Html(tree, layoutConfig, { title: 'Chalissery' });
 * // => '<!DOCTYPE html>...' with one .a4-sheet per tile
 */
class A4PrintComposer {

    /**
     * Calculates the optimal relaxed generation row height for compact A4 print mode
     * to eliminate unused bottom whitespace on printed pages.
     *
     * @param {FamilyTree} tree - Tree domain model
     * @param {Object} layoutConfig - Layout configuration
     * @param {Object} metrics - Page pixel metrics ({ tileHeightPx, standardScale, printableHeightPx })
     * @param {number} cardPadPx - Padding around canvas nodes
     * @param {boolean} isCompact - Whether compact mode is active
     * @returns {number} Effective generation row height in pixels (defaults to 160)
     *
     * @example
     * A4PrintComposer._computeEffectiveGenerationHeight(tree, {}, { tileHeightPx: 600, standardScale: 1.2, printableHeightPx: 718 }, 15, true)
     * // => 200 (max bound for roomy 2-gen tree)
     *
     * @example
     * A4PrintComposer._computeEffectiveGenerationHeight(tree, { generationRowHeight: 110 }, { tileHeightPx: 600, standardScale: 1.2, printableHeightPx: 718 }, 15, true)
     * // => 110
     */
    static _computeEffectiveGenerationHeight(tree, layoutConfig, metrics, cardPadPx, isCompact) {
        if (layoutConfig.generationRowHeight) return layoutConfig.generationRowHeight;
        if (!isCompact) return 160;

        const maxDepth = FamilyTreeBuilder.getMaxGenerationDepth(tree, layoutConfig.rootNode);
        if (maxDepth <= 0) return 160;

        const { tileHeightPx, standardScale, printableHeightPx } = metrics;
        const availH1Row = tileHeightPx - (cardPadPx * 2) - 76;
        const genH1Row = Math.floor(availH1Row / maxDepth);
        if (genH1Row >= 110) {
            return Math.min(200, Math.max(120, genH1Row));
        }

        const tileH2Rows = (printableHeightPx * 2) / standardScale;
        const availH2Rows = tileH2Rows - (cardPadPx * 2) - 76;
        return Math.min(200, Math.max(120, Math.floor(availH2Rows / maxDepth)));
    }

    /**
     * Constructs a print tile descriptor for a single grid coordinate (r, c).
     *
     * Tile geometry and occupancy testing are delegated to {@link PrintTileBounds}, which owns
     * the canvas-padding offset and edge arithmetic.
     *
     * @param {number} r - Grid row index
     * @param {number} c - Grid column index
     * @param {Object} dims - Grid dimensions ({ tileWidthPx, tileHeightPx, padX, padY })
     * @param {Object} layoutData - Positioned nodes and connection paths
     * @param {number} pageIndex - Sequential 1-based page index
     * @returns {Object} Tile descriptor
     *
     * @example
     * A4PrintComposer._buildPrintTile(0, 0, { tileWidthPx: 800, tileHeightPx: 600, padX: 10, padY: 10 }, { nodes: [], paths: [] }, 1)
     * // => { pageIndex: 1, row: 0, col: 0, x: 0, y: 0, width: 800, height: 600, nodeCount: 0, isEmpty: true, ... }
     *
     * @example
     * A4PrintComposer._buildPrintTile(0, 1, { tileWidthPx: 800, tileHeightPx: 600, padX: 10, padY: 10 }, { nodes: [{ x: 810, y: 10 }], paths: [] }, 2)
     * // => { pageIndex: 2, row: 0, col: 1, x: 800, y: 0, ... }
     */
    static _buildPrintTile(r, c, dims, layoutData, pageIndex) {
        const bounds = PrintTileBounds.forGridCell(r, c, dims.tileWidthPx, dims.tileHeightPx, dims.padX, dims.padY);
        const { nodeCount, isEmpty } = bounds.inspectOccupancy(layoutData);

        return {
            pageIndex,
            row: r,
            col: c,
            x: bounds.x,
            y: bounds.y,
            width: bounds.width,
            height: bounds.height,
            viewBox: bounds.viewBox,
            nodeCount,
            isEmpty
        };
    }

    /**
     * Slices the laid-out tree canvas into grid-aligned A4 printable page tiles.
     *
     * Page numbers are assigned only to tiles that are actually emitted, so skipping blank
     * tiles yields a gap-free 1..N page sequence rather than one with holes.
     *
     * @param {Object} dims - Grid dimensions ({ rows, cols, tileWidthPx, tileHeightPx, padX, padY })
     * @param {Object} layoutData - Positioned nodes and connection paths
     * @param {boolean} skipEmptyPages - Whether to exclude tiles with no nodes or paths
     * @returns {Array<Object>} List of tile specifications
     *
     * @example
     * A4PrintComposer._slicePrintGridTiles({ rows: 1, cols: 1, tileWidthPx: 800, tileHeightPx: 600, padX: 15, padY: 15 }, layoutData, true)
     * // => [{ pageIndex: 1, row: 0, col: 0, x: 0, y: 0, width: 800, height: 600, ... }]
     *
     * @example
     * A4PrintComposer._slicePrintGridTiles({ rows: 2, cols: 2, tileWidthPx: 800, tileHeightPx: 600, padX: 0, padY: 0 }, { nodes: [], paths: [] }, true)
     * // => [] (empty pages skipped)
     */
    static _slicePrintGridTiles(dims, layoutData, skipEmptyPages) {
        const tiles = [];
        let pageNumber = 1;

        for (let r = 0; r < dims.rows; r++) {
            for (let c = 0; c < dims.cols; c++) {
                const tile = A4PrintComposer._buildPrintTile(r, c, dims, layoutData, pageNumber);
                if (tile.isEmpty && skipEmptyPages) {
                    continue;
                }
                pageNumber++;
                tiles.push(tile);
            }
        }

        return tiles;
    }

    /**
     * Fixed physical geometry of a printed sheet, in millimeters.
     *
     * Every printed page is A4 landscape with a uniform margin. This is the one
     * source of truth: the tile math below and the emitted `.a4-sheet` CSS both
     * derive from it, so the two can never disagree about how much of the tree
     * fits on a page. Page size is deliberately not configurable — the generated
     * stylesheet hardcodes `@page { size: A4 landscape }`, so a caller-supplied
     * page size would silently mis-scale every sheet.
     *
     * @example
     * A4PrintComposer.SHEET_MM.widthMm;
     * // => 297
     *
     * @example
     * A4PrintComposer.SHEET_MM.marginMm;
     * // => 10 (leaving a 277 x 190 mm printable area)
     */
    static SHEET_MM = Object.freeze({ widthMm: 297, heightMm: 210, marginMm: 10 });

    /**
     * How much of the final row of sheets must be covered by the tree for that row to earn
     * its paper.
     *
     * When the chosen grid is limited by width rather than height, the rows together span
     * more canvas than the tree occupies, and the leftover can be a sliver: a 10x2 grid was
     * observed spending six extra sheets on a band only 8.4% of a page tall. Below this
     * threshold the tree is re-spaced to fit one row fewer instead.
     *
     * @example
     * A4PrintComposer.TRAILING_ROW_REFLOW_RATIO;
     * // => 0.4
     *
     * @example
     * // A final row covered 8.4% by the tree is reflowed away; one covered 62.6% is kept.
     * 0.084 < A4PrintComposer.TRAILING_ROW_REFLOW_RATIO;
     * // => true
     */
    static TRAILING_ROW_REFLOW_RATIO = 0.4;

    /**
     * Tightest generation spacing, in canvas pixels, that reflowing may fall back to.
     *
     * Matches the legibility floor {@link A4PrintComposer._computeEffectiveGenerationHeight}
     * already applies: below this, rows crowd badly enough that saving a sheet is not worth it.
     *
     * @example
     * A4PrintComposer.MIN_COMPACT_GENERATION_HEIGHT;
     * // => 110
     *
     * @example
     * // A tree needing 90px rows to save a sheet is left alone.
     * 90 >= A4PrintComposer.MIN_COMPACT_GENERATION_HEIGHT;
     * // => false
     */
    static MIN_COMPACT_GENERATION_HEIGHT = 110;

    /**
     * Computes raw millimeter dimensions and printable boundary areas for paper printing.
     *
     * @returns {Object} Millimeter dimensions derived from {@link A4PrintComposer.SHEET_MM}
     *
     * @example
     * A4PrintComposer._computePageMillimeterDimensions()
     * // => { pageWidthMm: 297, pageHeightMm: 210, marginMm: 10, printableWidthMm: 277, printableHeightMm: 190 }
     *
     * @example
     * A4PrintComposer._computePageMillimeterDimensions().printableWidthMm
     * // => 277 (297 less a 10mm margin on each side)
     */
    static _computePageMillimeterDimensions() {
        const { widthMm: pageWidthMm, heightMm: pageHeightMm, marginMm } = A4PrintComposer.SHEET_MM;
        const printableWidthMm = pageWidthMm - 2 * marginMm;
        const printableHeightMm = pageHeightMm - 2 * marginMm;
        return { pageWidthMm, pageHeightMm, marginMm, printableWidthMm, printableHeightMm };
    }

    /**
     * Converts physical millimeter dimensions and font sizes into pixel measurements, scale, and tile bounds.
     *
     * @param {Object} mmDims - Millimeter dimensions including printable width and height
     * @param {number} targetFontSizePt - Target font size in points
     * @param {number} baseFontSizePx - Base font size in pixels
     * @returns {Object} Calculated pixel metrics, scale, and tile dimensions
     *
     * @example
     * A4PrintComposer._computePagePixelMetrics({ printableWidthMm: 277, printableHeightMm: 190 }, 10, 11);
     * // => { MM_TO_PX: 3.7795275590551185, printableWidthPx: 1046.9291338582676, standardScale: 1.2121212121212122, ... }
     *
     * @example
     * A4PrintComposer._computePagePixelMetrics({ printableWidthMm: 200, printableHeightMm: 100 }, 12, 12);
     * // => { standardScale: 1.3333333333333333, tileWidthPx: 566.9291338582678, ... }
     */
    static _computePagePixelMetrics(mmDims, targetFontSizePt, baseFontSizePx) {
        const MM_TO_PX = 96 / 25.4;
        const PT_TO_PX = 96 / 72;
        const printableWidthPx = mmDims.printableWidthMm * MM_TO_PX;
        const printableHeightPx = mmDims.printableHeightMm * MM_TO_PX;
        const standardScale = (targetFontSizePt * PT_TO_PX) / baseFontSizePx;
        const tileWidthPx = printableWidthPx / standardScale;
        const tileHeightPx = printableHeightPx / standardScale;
        return { MM_TO_PX, PT_TO_PX, printableWidthPx, printableHeightPx, standardScale, tileWidthPx, tileHeightPx };
    }

    /**
     * Computes physical page metrics, printable pixel areas, scale factors,
     * and tile dimensions for partitioning an SVG diagram across A4 landscape sheets.
     *
     * @param {Object} [options={}] - Print sizing configuration
     * @returns {Object} Calculated page metric properties
     *
     * @example
     * A4PrintComposer._computePageMetrics({ targetFontSizePt: 10, baseFontSizePx: 11 })
     * // => { printableWidthMm: 277, printableHeightMm: 190, standardScale: 1.212, tileWidthPx: 863.3, ... }
     *
     * @example
     * A4PrintComposer._computePageMetrics({})
     * // => { targetFontSizePt: 10, baseFontSizePx: 11, ... }
     */
    static _computePageMetrics(options = {}) {
        const targetFontSizePt = options.targetFontSizePt || 10;
        const baseFontSizePx = options.baseFontSizePx || 11;
        const mmDims = A4PrintComposer._computePageMillimeterDimensions();
        const pixelMetrics = A4PrintComposer._computePagePixelMetrics(mmDims, targetFontSizePt, baseFontSizePx);
        return {
            targetFontSizePt,
            baseFontSizePx,
            ...mmDims,
            ...pixelMetrics
        };
    }

    /**
     * Constructs a fallback empty print grid structure when no layout nodes are available.
     *
     * @param {Object} params - Sizing and configuration parameters
     * @returns {Object} Empty grid descriptor
     *
     * @example
     * A4PrintComposer._createEmptyPrintGridResult({ scale: 1, targetFontSizePt: 10, isCompact: false, options: {} })
     * // => { cols: 0, rows: 0, tiles: [], totalCanvasWidth: 0, totalCanvasHeight: 0, ... }
     *
     * @example
     * A4PrintComposer._createEmptyPrintGridResult({ scale: 1.2, targetFontSizePt: 12, isCompact: true, options: { mode: 'compact' } })
     * // => { cols: 0, rows: 0, tiles: [], mode: 'compact', ... }
     */
    static _createEmptyPrintGridResult({ scale, targetFontSizePt, printableWidthMm, printableHeightMm, tileWidthPx, tileHeightPx, effectiveGenHeight, isCompact, options }) {
        return {
            scale,
            targetFontSizePt,
            effectiveFontSizePt: targetFontSizePt,
            printableWidthMm,
            printableHeightMm,
            tileWidthPx,
            tileHeightPx,
            cols: 0,
            rows: 0,
            tiles: [],
            totalCanvasWidth: 0,
            totalCanvasHeight: 0,
            generationRowHeight: effectiveGenHeight || 160,
            mode: isCompact ? 'compact' : (options.mode || 'full')
        };
    }

    /**
     * Resolves final grid column, row, scale, and tile dimensions, applying budget optimization if requested.
     *
     * @param {{ cols: number, rows: number, scale: number, tileWidthPx: number, tileHeightPx: number }} baseGrid
     * @param {boolean} isCompact - Whether compact/auto-fit mode is enabled
     * @param {Object} options - User options
     * @param {number} printableWidthPx - Printable page width in px
     * @param {number} printableHeightPx - Printable page height in px
     * @param {number} totalCanvasWidth - Total canvas width in px
     * @param {number} totalCanvasHeight - Total canvas height in px
     * @param {number} targetPages - Max page count
     * @returns {{ cols: number, rows: number, scale: number, tileWidthPx: number, tileHeightPx: number }}
     *
     * @example
     * A4PrintComposer._resolvePrintGridDimensions(
     *     { cols: 2, rows: 2, scale: 1, tileWidthPx: 800, tileHeightPx: 600 },
     *     { isCompact: true, options: { targetPages: 2 }, printableWidthPx: 800, printableHeightPx: 600, totalCanvasWidth: 1600, totalCanvasHeight: 1200, targetPages: 2 }
     * );
     * // => { cols: 2, rows: 1, scale: ~0.8, tileWidthPx: 1000, tileHeightPx: 750 }
     *
     * @example
     * A4PrintComposer._resolvePrintGridDimensions(
     *     { cols: 1, rows: 1, scale: 1, tileWidthPx: 800, tileHeightPx: 600 },
     *     { isCompact: false, options: {}, printableWidthPx: 800, printableHeightPx: 600, totalCanvasWidth: 800, totalCanvasHeight: 600, targetPages: 10 }
     * );
     * // => { cols: 1, rows: 1, scale: 1, tileWidthPx: 800, tileHeightPx: 600 }
     */
    static _resolvePrintGridDimensions(baseGrid, { isCompact, options, printableWidthPx, printableHeightPx, totalCanvasWidth, totalCanvasHeight, targetPages }) {
        // Page-budget optimization only applies to compact/auto-fit exports; a plain export
        // prints the natural grid at its natural scale.
        if (!isCompact || (!options.targetPages && !options.autoFitPages)) {
            return baseGrid;
        }
        const spec = new PrintGridSpec(printableWidthPx, printableHeightPx, totalCanvasWidth, totalCanvasHeight, targetPages);
        return spec.fitWithinPageBudget(baseGrid);
    }

    /**
     * Calculates canvas bounding dimensions and optimizes page budget (rows, cols, scale, tile sizes).
     *
     * @param {Object} params
     * @param {Object} params.layoutData - Computed layout tree geometry
     * @param {number} params.cardPadPx - Canvas edge padding in pixels
     * @param {number} params.initialTileWidthPx - Base unscaled tile width in pixels
     * @param {number} params.initialTileHeightPx - Base unscaled tile height in pixels
     * @param {number} params.initialScale - Standard scale ratio
     * @param {boolean} params.isCompact - Whether auto-fit or compact mode is enabled
     * @param {Object} params.options - User print options
     * @param {number} params.printableWidthPx - Available printable width on paper
     * @param {number} params.printableHeightPx - Available printable height on paper
     * @param {number} params.targetPages - Target page count ceiling
     * @returns {{ padX: number, padY: number, totalCanvasWidth: number, totalCanvasHeight: number, cols: number, rows: number, scale: number, tileWidthPx: number, tileHeightPx: number }}
     *
     * @example
     * A4PrintComposer._calculatePrintGridDimensions({
     *     layoutData: { minX: 0, minY: 0, width: 1000, height: 800 },
     *     cardPadPx: 15, initialTileWidthPx: 800, initialTileHeightPx: 600,
     *     initialScale: 1, isCompact: false, options: {},
     *     printableWidthPx: 800, printableHeightPx: 600, targetPages: 10
     * });
     * // => { padX: 15, padY: 15, cols: 2, rows: 2, ... }
     *
     * @example
     * A4PrintComposer._calculatePrintGridDimensions({
     *     layoutData: { minX: 0, minY: 0, width: 400, height: 300 },
     *     cardPadPx: 15, initialTileWidthPx: 800, initialTileHeightPx: 600,
     *     initialScale: 1, isCompact: false, options: {},
     *     printableWidthPx: 800, printableHeightPx: 600, targetPages: 10
     * });
     * // => { padX: 15, padY: 15, cols: 1, rows: 1, ... }
     */
    static _calculatePrintGridDimensions({
        layoutData, cardPadPx, initialTileWidthPx, initialTileHeightPx,
        initialScale, isCompact, options, printableWidthPx, printableHeightPx, targetPages
    }) {
        const padX = cardPadPx - layoutData.minX;
        const padY = cardPadPx - layoutData.minY;
        const totalCanvasWidth = Math.max(initialTileWidthPx, layoutData.width + cardPadPx * 2);
        const totalCanvasHeight = Math.max(initialTileHeightPx, layoutData.height + cardPadPx * 2);

        const baseGrid = {
            cols: Math.max(1, Math.ceil(totalCanvasWidth / initialTileWidthPx)),
            rows: Math.max(1, Math.ceil(totalCanvasHeight / initialTileHeightPx)),
            scale: initialScale,
            tileWidthPx: initialTileWidthPx,
            tileHeightPx: initialTileHeightPx
        };

        const grid = A4PrintComposer._resolvePrintGridDimensions(baseGrid, {
            isCompact, options, printableWidthPx, printableHeightPx,
            totalCanvasWidth, totalCanvasHeight, targetPages
        });

        return { padX, padY, totalCanvasWidth, totalCanvasHeight, ...grid };
    }

    /**
     * Resolves generation row height and computes tree layout for print grid generation.
     *
     * @param {Object} tree - Tree instance.
     * @param {Object} layoutConfig - User layout configuration.
     * @param {Object} metrics - Computed page metrics.
     * @param {number} cardPadPx - Padding around cards.
     * @param {boolean} isCompact - Whether compact compression mode is active.
     * @returns {{ effectiveGenHeight: number, layoutData: Object }} Layout data and row height.
     *
     * @example
     * A4PrintComposer._resolvePrintGridLayout(tree, {}, metrics, 15, false)
     * // => { effectiveGenHeight: 220, layoutData: { nodes: [...], paths: [...] } }
     *
     * @example
     * A4PrintComposer._resolvePrintGridLayout(tree, { verticalCompression: true }, metrics, 15, true)
     * // => { effectiveGenHeight: 160, layoutData: { nodes: [...], paths: [...] } }
     */
    static _resolvePrintGridLayout(tree, layoutConfig, metrics, cardPadPx, isCompact) {
        const effectiveGenHeight = A4PrintComposer._computeEffectiveGenerationHeight(
            tree, layoutConfig, metrics, cardPadPx, isCompact
        );
        const effectiveLayoutConfig = isCompact
            ? { ...layoutConfig, verticalCompression: true, generationRowHeight: effectiveGenHeight || 160 }
            : { ...layoutConfig };
        const layoutData = FamilyTreeBuilder.computeLayout(tree, effectiveLayoutConfig);
        return { effectiveGenHeight, layoutData };
    }

    /**
     * Assembles the final printable grid result object bundle.
     *
     * @param {Object} p - Output parameters and dimensions.
     * @returns {Object} Complete print grid descriptor.
     *
     * @example
     * A4PrintComposer._assemblePrintGridResult({ scale: 1, cols: 2, rows: 2, tiles: [], layoutData: null, options: {} });
     * // => { scale: 1, cols: 2, rows: 2, tiles: [], ... }
     *
     * @example
     * A4PrintComposer._assemblePrintGridResult({ scale: 1.2, cols: 1, rows: 1, tiles: [{}], isCompact: true, options: { mode: 'compact' } });
     * // => { scale: 1.2, cols: 1, rows: 1, mode: 'compact', ... }
     */
    static _assemblePrintGridResult(p) {
        return {
            scale: p.scale,
            targetFontSizePt: p.targetFontSizePt,
            effectiveFontSizePt: p.effectiveFontSizePt,
            baseFontSizePx: p.baseFontSizePx,
            pageWidthMm: p.pageWidthMm,
            pageHeightMm: p.pageHeightMm,
            marginMm: p.marginMm,
            printableWidthMm: p.printableWidthMm,
            printableHeightMm: p.printableHeightMm,
            tileWidthPx: p.tileWidthPx,
            tileHeightPx: p.tileHeightPx,
            totalCanvasWidth: p.totalCanvasWidth,
            totalCanvasHeight: p.totalCanvasHeight,
            padX: p.padX,
            padY: p.padY,
            cols: p.cols,
            rows: p.rows,
            tiles: p.tiles,
            layoutData: p.layoutData,
            generationRowHeight: p.effectiveGenHeight || 160,
            mode: p.isCompact ? 'compact' : (p.options.mode || 'full')
        };
    }

    /**
     * Slices printable grid tiles and computes the effective target font size in points.
     *
     * @param {Object} dims - Calculated grid dimensions and scale
     * @param {number} baseFontSizePx - Base unscaled font size in pixels
     * @param {number} PT_TO_PX - Conversion ratio from points to CSS pixels
     * @param {Object} layoutData - Computed tree layout data
     * @param {boolean} skipEmptyPages - Whether to omit blank tiles
     * @returns {{ effectiveFontSizePt: number, tiles: Array<Object> }}
     *
     * @example
     * A4PrintComposer._generatePrintGridTiles(
     *     { scale: 1.2, rows: 2, cols: 2, tileWidthPx: 800, tileHeightPx: 600, padX: 15, padY: 15 },
     *     11, 1.3333333333333333, layoutData, true
     * );
     * // => { effectiveFontSizePt: 10, tiles: [...] }
     *
     * @example
     * A4PrintComposer._generatePrintGridTiles(
     *     { scale: 1.0, rows: 1, cols: 1, tileWidthPx: 500, tileHeightPx: 400, padX: 10, padY: 10 },
     *     12, 1.3333333333333333, { nodes: [], paths: [] }, true
     * );
     * // => { effectiveFontSizePt: 9, tiles: [] }
     */
    static _generatePrintGridTiles(dims, baseFontSizePx, PT_TO_PX, layoutData, skipEmptyPages) {
        const effectiveFontSizePt = Number(((dims.scale * baseFontSizePx) / PT_TO_PX).toFixed(1));
        const tiles = A4PrintComposer._slicePrintGridTiles(dims, layoutData, skipEmptyPages);
        return { effectiveFontSizePt, tiles };
    }

    /**
     * Calculates grid dimensions, generates page tiles, and assembles the print grid result for populated layouts.
     *
     * @private
     * @param {Object} params - Computation parameters
     * @param {Object} params.metrics - Page metrics and standard scale settings
     * @param {Object} params.layoutData - Computed tree layout containing positioned nodes and paths
     * @param {number} params.effectiveGenHeight - Generation tier height in pixels
     * @param {number} params.cardPadPx - Padding around canvas cards
     * @param {boolean} params.isCompact - Whether compact compression is active
     * @param {Object} params.options - User-specified print options
     * @param {boolean} params.skipEmptyPages - Whether to omit empty tiles
     * @returns {Object} Complete grid specification, page tiles, and layout metadata
     *
     * @example
     * A4PrintComposer._buildActivePrintGridResult({
     *     metrics, layoutData, effectiveGenHeight: 80, cardPadPx: 15, isCompact: false, options: {}, skipEmptyPages: true
     * });
     * // => { cols: 2, rows: 1, tiles: [...], scale: 1.0, ... }
     *
     * @example
     * A4PrintComposer._buildActivePrintGridResult({
     *     metrics, layoutData: { nodes: [{ x: 0, y: 0 }], paths: [] }, effectiveGenHeight: 60,
     *     cardPadPx: 10, isCompact: true, options: { mode: 'compact' }, skipEmptyPages: false
     * });
     * // => { cols: 1, rows: 1, tiles: [...], scale: 0.85, ... }
     */
    static _buildActivePrintGridResult({
        metrics, layoutData, effectiveGenHeight, cardPadPx, isCompact, options, skipEmptyPages
    }) {
        const dims = A4PrintComposer._calculatePrintGridDimensions({
            layoutData, cardPadPx, isCompact, options,
            initialTileWidthPx: metrics.tileWidthPx, initialTileHeightPx: metrics.tileHeightPx,
            initialScale: metrics.standardScale, printableWidthPx: metrics.printableWidthPx,
            printableHeightPx: metrics.printableHeightPx, targetPages: options.targetPages || 10
        });

        const { effectiveFontSizePt, tiles } = A4PrintComposer._generatePrintGridTiles(
            dims, metrics.baseFontSizePx, metrics.PT_TO_PX, layoutData, skipEmptyPages
        );

        return A4PrintComposer._assemblePrintGridResult({
            ...metrics, ...dims, effectiveFontSizePt, tiles, layoutData, effectiveGenHeight, isCompact, options
        });
    }

    /**
     * Computes grid slicing parameters for printing the family tree on A4 landscape paper
     * such that person names are rendered at a specified physical font size (default 10pt),
     * with optional vertical compression and target page budget auto-fitting.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layoutConfig={}] - Tree layout configuration
     * @param {Object} [options={}] - Print formatting options
     * @param {number} [options.targetFontSizePt=10] - Desired font size of person names on paper (points)
     * @param {number} [options.baseFontSizePx=11] - Canvas font size of person names (pixels)
     * Sheet geometry is fixed (see {@link A4PrintComposer.SHEET_MM}); only how
     * much tree fits on each sheet is tunable, via the font size options.
     *
     * @param {number} [options.cardPadPx=15] - Margin padding around canvas nodes (px)
     * @param {boolean} [options.skipEmptyPages=true] - Whether to exclude grid tiles with no nodes or paths
     * @param {string} [options.mode='full'] - Print mode: 'full' | 'compact' | 'atlas'
     * @param {number} [options.targetPages=10] - Target page budget for compact mode
     * @param {boolean} [options.verticalCompression=false] - Whether to apply vertical compression
     * @param {boolean} [options.autoFitPages=false] - Whether to auto-fit to target page budget
     * @returns {Object} Grid specifications and tile list
     *
     * @example
     * const grid = A4PrintComposer.computeA4PrintGrid(tree, {}, { mode: 'compact', targetPages: 8 });
     * // => { cols: 4, rows: 2, tiles: [...], scale: ~0.95, ... }
     *
     * @example
     * const grid = A4PrintComposer.computeA4PrintGrid(tree);
     * // => { cols: ..., rows: ..., tiles: [...], mode: 'full', ... }
     */
    static computeA4PrintGrid(tree, layoutConfig = {}, options = {}) {
        const metrics = A4PrintComposer._computePageMetrics(options);
        const cardPadPx = typeof options.cardPadPx === 'number' ? options.cardPadPx : 15;
        const skipEmptyPages = options.skipEmptyPages !== false;
        const isCompact = options.mode === 'compact' || options.autoFitPages || options.verticalCompression || layoutConfig.verticalCompression;

        const { effectiveGenHeight, layoutData } = A4PrintComposer._resolvePrintGridLayout(
            tree, layoutConfig, metrics, cardPadPx, isCompact
        );

        if (!layoutData || layoutData.nodes.length === 0) {
            return A4PrintComposer._createEmptyPrintGridResult({
                scale: metrics.standardScale, targetFontSizePt: metrics.targetFontSizePt,
                effectiveGenHeight, isCompact, options,
                printableWidthMm: metrics.printableWidthMm, printableHeightMm: metrics.printableHeightMm,
                tileWidthPx: metrics.tileWidthPx, tileHeightPx: metrics.tileHeightPx
            });
        }

        const grid = A4PrintComposer._buildActivePrintGridResult({
            metrics, layoutData, effectiveGenHeight, cardPadPx, isCompact, options, skipEmptyPages
        });
        return A4PrintComposer._reflowTrailingSheetRow(grid, {
            tree, layoutConfig, metrics, cardPadPx, isCompact, options, skipEmptyPages
        });
    }

    /**
     * Drops a final row of sheets that the tree barely reaches into, by squeezing the
     * generations a little tighter.
     *
     * The page-budget search maximises legibility, so it happily spends a whole extra row of
     * sheets on the last few pixels of the tree: a grid limited by canvas *width* spans more
     * vertical canvas than the tree needs, and the overspill lands on paper that is otherwise
     * blank. Compact mode is already free to re-space generations, so the cheaper trade is to
     * pull the tree in until it fits the rows above.
     *
     * Shrinking the canvas can only ever raise the achievable scale, so the retry never costs
     * legibility; it is accepted purely on printing fewer sheets.
     *
     * @param {Object} grid - Grid descriptor from {@link A4PrintComposer._buildActivePrintGridResult}
     * @param {Object} ctx - Everything needed to lay the tree out again
     * @returns {Object} The tightened grid, or the original when it cannot be improved
     *
     * @example
     * // 10x2 grid whose last row is only 8.4% covered -> re-spaced to 10x1, 10 sheets instead of 16.
     * A4PrintComposer._reflowTrailingSheetRow(grid, { tree, layoutConfig: {}, metrics, cardPadPx: 15, isCompact: true, options: {}, skipEmptyPages: true }).rows;
     * // => 1
     *
     * @example
     * // A last row 62.6% covered is genuine content and is left untouched.
     * A4PrintComposer._reflowTrailingSheetRow(wellPackedGrid, ctx) === wellPackedGrid;
     * // => true
     */
    static _reflowTrailingSheetRow(grid, ctx) {
        const { tree, layoutConfig, metrics, cardPadPx, isCompact, options, skipEmptyPages } = ctx;
        if (!isCompact || grid.rows < 2) return grid;

        const trailingCanvas = grid.totalCanvasHeight - (grid.rows - 1) * grid.tileHeightPx;
        if (trailingCanvas > grid.tileHeightPx * A4PrintComposer.TRAILING_ROW_REFLOW_RATIO) return grid;

        const depth = FamilyTreeBuilder.getMaxGenerationDepth(tree, layoutConfig.rootNode);
        if (depth < 2 || !grid.generationRowHeight) return grid;

        // Calibrate against the layout we just produced rather than assuming a formula:
        // everything that is not generation spacing (the bottom card, connector overhang)
        // stays fixed as the spacing changes.
        const gaps = depth - 1;
        const fixedHeight = grid.layoutData.height - gaps * grid.generationRowHeight;
        const heightBudget = (grid.rows - 1) * grid.tileHeightPx - cardPadPx * 2;
        const generationRowHeight = Math.floor((heightBudget - fixedHeight) / gaps);
        if (generationRowHeight < A4PrintComposer.MIN_COMPACT_GENERATION_HEIGHT) return grid;

        const tightened = A4PrintComposer._buildActivePrintGridResult({
            metrics, cardPadPx, isCompact, options, skipEmptyPages,
            ...A4PrintComposer._resolvePrintGridLayout(
                tree, { ...layoutConfig, generationRowHeight }, metrics, cardPadPx, isCompact
            )
        });
        return tightened.tiles.length < grid.tiles.length ? tightened : grid;
    }

    /**
     * Identifies and chronologically sorts primary branch heads under a tree root
     * for generating Atlas chapter pages.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} root - Root node of the family tree
     * @returns {Array<Object>} Sorted list of primary branch head nodes
     *
     * @example
     * A4PrintComposer._collectAtlasBranchHeads(tree, rootNode);
     * // => [Person(Thomas, b. 1905), Person(Paul, b. 1908)]
     *
     * @example
     * A4PrintComposer._collectAtlasBranchHeads(emptyTree, singleRoot);
     * // => []
     */
    static _collectAtlasBranchHeads(tree, root) {
        let branchNodes = [];
        if (typeof root.getValidDisplayChildren === 'function') {
            branchNodes = root.getValidDisplayChildren(tree);
        } else if (root.children && Array.isArray(root.children)) {
            branchNodes = root.children.map(id => tree.get(id)).filter(Boolean);
        }

        // If root is a synthetic sibling parent, the siblings themselves can be the branches
        if (branchNodes.length === 0 && FamilyTree.isSyntheticSiblingParent(root)) {
            branchNodes = (tree.all || []).filter(n => !n.isGhost && (!n.parents || n.parents.length === 0));
        }

        return branchNodes.sort((a, b) => (a.bestYob - b.bestYob) || (a.sheetRow - b.sheetRow));
    }

    /**
     * Overlays clickable SVG chapter badges ("📖 Ch. 1 (p. 2)") on branch head nodes
     * within the master overview SVG layout.
     *
     * @param {Object} overviewResult - Generated SVG result { innerSvg, layoutData, padX, padY }
     * @param {Array<Object>} branchInfoList - Metadata list of branches { index, pageIndex, node, ... }
     * @returns {string} Enriched SVG inner content with chapter badges appended
     *
     * @example
     * A4PrintComposer._injectAtlasChapterBadges(
     *     { innerSvg: '<g>...</g>', layoutData: { nodes: [{ person: { id: 'p1' }, x: 10, y: 20 }] }, padX: 15, padY: 15 },
     *     [{ index: 1, pageIndex: 2, node: { id: 'p1' } }]
     * );
     * // => '<g>...</g><g class="atlas-badges"><g class="branch-badge">...</g></g>'
     *
     * @example
     * A4PrintComposer._injectAtlasChapterBadges({ innerSvg: '<g></g>', layoutData: { nodes: [] }, padX: 0, padY: 0 }, []);
     * // => '<g></g><g class="atlas-badges"></g>'
     */
    static _injectAtlasChapterBadges(overviewResult, branchInfoList) {
        let overviewInnerSvg = overviewResult.innerSvg;
        if (!overviewResult.layoutData || !overviewResult.layoutData.nodes) {
            return overviewInnerSvg;
        }

        let badgesSvg = '<g class="atlas-badges">';
        overviewResult.layoutData.nodes.forEach(n => {
            const bInfo = branchInfoList.find(b => b.node.id === n.person.id);
            if (bInfo) {
                const nx = n.x + overviewResult.padX;
                const ny = n.y + overviewResult.padY;
                const badgeText = `📖 Ch. ${bInfo.index} (p. ${bInfo.pageIndex})`;
                const badgeW = 86;
                const badgeH = 15;
                const bx = nx + 45 - badgeW / 2;
                const by = ny + 76 - 4;
                badgesSvg += `<g class="branch-badge" cursor="pointer">`;
                badgesSvg += `<rect x="${bx.toFixed(1)}" y="${by.toFixed(1)}" width="${badgeW}" height="${badgeH}" rx="4" ry="4" fill="#2563eb" stroke="#ffffff" stroke-width="1"/>`;
                badgesSvg += `<text x="${(bx + badgeW / 2).toFixed(1)}" y="${(by + 11).toFixed(1)}" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="8.5" font-weight="700" fill="#ffffff" text-anchor="middle">${badgeText}</text>`;
                badgesSvg += `</g>`;
            }
        });
        badgesSvg += '</g>';
        return overviewInnerSvg + badgesSvg;
    }

    /**
     * Constructs the master overview sheet (Sheet 1) for the Family Atlas.
     *
     * Collapses all branch heads to display only the root and top-level branch nodes,
     * and overlays chapter badges referencing each branch's dedicated sheet.
     *
     * @param {FamilyTree} tree - Populated tree instance
     * @param {Person} root - Root person node
     * @param {Object} atlasMeta - Atlas branch metadata ({ branchNodes, branchInfoList, totalAtlasSheets })
     * @param {Object} layoutConfig - Layout configuration
     * @param {Object} options - Export and rendering options
     * @returns {Object} Overview sheet descriptor
     *
     * @example
     * A4PrintComposer._buildAtlasOverviewSheet(tree, root, { branchNodes: [branchA], branchInfoList: [bInfoA], totalAtlasSheets: 2 }, {}, {});
     * // => { type: 'overview', pageIndex: 1, totalSheets: 2, title: 'Master Overview & Table of Contents', ... }
     *
     * @example
     * A4PrintComposer._buildAtlasOverviewSheet(tree, root, { branchNodes: [], branchInfoList: [], totalAtlasSheets: 1 }, { verticalCompression: true }, {});
     * // => { type: 'overview', pageIndex: 1, totalSheets: 1, branches: [], ... }
     */
    static _buildAtlasOverviewSheet(tree, root, atlasMeta, layoutConfig, options) {
        const { branchNodes, branchInfoList, totalAtlasSheets } = atlasMeta;
        const collapsedForOverview = new Set(branchNodes.map(b => b.id));
        const overviewLayoutConfig = {
            ...layoutConfig,
            collapsedNodes: collapsedForOverview,
            verticalCompression: true
        };
        const overviewResult = SvgTreeRenderer.generatePureSvgTree(tree, overviewLayoutConfig, options);

        // Inject chapter badges on the branch head nodes in the overview SVG
        const overviewInnerSvg = A4PrintComposer._injectAtlasChapterBadges(overviewResult, branchInfoList);
        const overviewSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ${overviewResult.width.toFixed(1)} ${overviewResult.height.toFixed(1)}" preserveAspectRatio="xMidYMid meet">${overviewInnerSvg}</svg>`;

        return {
            type: 'overview',
            pageIndex: 1,
            totalSheets: totalAtlasSheets,
            title: 'Master Overview & Table of Contents',
            subtitle: `${root.name} Lineage • ${branchInfoList.length} Major Branches`,
            svg: overviewSvg,
            innerSvg: overviewInnerSvg,
            width: overviewResult.width,
            height: overviewResult.height,
            viewBox: `0 0 ${overviewResult.width.toFixed(1)} ${overviewResult.height.toFixed(1)}`,
            branches: branchInfoList
        };
    }

    /**
     * Constructs a dedicated branch chapter sheet (Sheets 2..N+1) for the Family Atlas.
     *
     * Renders the isolated descendant subtree rooted at the branch head node.
     *
     * @param {FamilyTree} tree - Populated tree instance
     * @param {Object} bInfo - Branch metadata and chapter descriptor
     * @param {number} totalAtlasSheets - Total count of atlas sheets
     * @param {Object} layoutConfig - Layout configuration
     * @param {Object} options - Export and rendering options
     * @returns {Object} Branch chapter sheet descriptor
     *
     * @example
     * A4PrintComposer._buildAtlasBranchSheet(tree, { node: bNode, index: 1, pageIndex: 2, name: 'John', branchTitle: 'John', memberCount: 5 }, 3, {}, {});
     * // => { type: 'branch', pageIndex: 2, chapterIndex: 1, totalSheets: 3, title: 'Chapter 1: The John Branch', ... }
     *
     * @example
     * A4PrintComposer._buildAtlasBranchSheet(tree, { node: bNode2, index: 2, pageIndex: 3, name: 'Mary', branchTitle: 'Mary & Joseph', memberCount: 8 }, 3, {}, {});
     * // => { type: 'branch', pageIndex: 3, chapterIndex: 2, title: 'Chapter 2: The Mary & Joseph Branch', ... }
     */
    static _buildAtlasBranchSheet(tree, bInfo, totalAtlasSheets, layoutConfig, options) {
        const branchLayoutConfig = {
            ...layoutConfig,
            rootNode: bInfo.node,
            rootId: bInfo.node.id,
            verticalCompression: true,
            collapsedNodes: new Set()
        };
        const branchSvgResult = SvgTreeRenderer.generatePureSvgTree(tree, branchLayoutConfig, options);
        const branchSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ${branchSvgResult.width.toFixed(1)} ${branchSvgResult.height.toFixed(1)}" preserveAspectRatio="xMidYMid meet">${branchSvgResult.innerSvg}</svg>`;

        return {
            type: 'branch',
            pageIndex: bInfo.pageIndex,
            chapterIndex: bInfo.index,
            totalSheets: totalAtlasSheets,
            title: `Chapter ${bInfo.index}: The ${bInfo.branchTitle} Branch`,
            subtitle: `${bInfo.memberCount} Members • Descendants of ${bInfo.name}`,
            svg: branchSvg,
            innerSvg: branchSvgResult.innerSvg,
            width: branchSvgResult.width,
            height: branchSvgResult.height,
            viewBox: `0 0 ${branchSvgResult.width.toFixed(1)} ${branchSvgResult.height.toFixed(1)}`,
            node: bInfo.node,
            branchInfo: bInfo
        };
    }

    /**
     * Builds chapter metadata and title descriptor for a family tree branch head.
     *
     * @param {Object} bNode - Branch head person node.
     * @param {number} idx - 0-based index of the branch.
     * @param {FamilyTree} tree - Tree instance for partner lookups.
     * @returns {{ index: number, pageIndex: number, node: Object, name: string, branchTitle: string, memberCount: number }}
     *
     * @example
     * A4PrintComposer._buildBranchInfoDescriptor(johnNode, 0, tree);
     * // => { index: 1, pageIndex: 2, node: johnNode, name: 'John', branchTitle: 'John & Mary', memberCount: 5 }
     *
     * @example
     * A4PrintComposer._buildBranchInfoDescriptor(singleNode, 2, tree);
     * // => { index: 3, pageIndex: 4, node: singleNode, name: 'Paul', branchTitle: 'Paul', memberCount: 1 }
     */
    static _buildBranchInfoDescriptor(bNode, idx, tree) {
        const count = FamilyTreeBuilder._countFamilyBranchDescendants(bNode, tree);
        const spouseNames = (bNode.partners || []).map(pId => tree.get(pId)?.name).filter(Boolean);
        const branchTitle = spouseNames.length > 0 ? `${bNode.name} & ${spouseNames.join(' / ')}` : bNode.name;
        return {
            index: idx + 1,
            pageIndex: idx + 2, // Sheet 1 is overview, Sheet 2+ are chapters
            node: bNode,
            name: bNode.name,
            branchTitle,
            memberCount: count
        };
    }

    /**
     * Builds multi-sheet Family Atlas export data consisting of a master overview sheet
     * and dedicated chapter sheets for each primary descendant branch.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layoutConfig={}] - Layout configuration options
     * @param {Object} [options={}] - Atlas rendering and export options
     * @returns {Array<Object>} List of atlas sheet descriptors (overview and chapter sheets)
     *
     * @example
     * const sheets = A4PrintComposer.buildFamilyAtlasSheets(tree);
     * // => [{ type: 'overview', pageIndex: 1, ... }, { type: 'branch', pageIndex: 2, ... }]
     *
     * @example
     * const sheets = A4PrintComposer.buildFamilyAtlasSheets(null);
     * // => []
     */
    static buildFamilyAtlasSheets(tree, layoutConfig = {}, options = {}) {
        if (!tree || !tree.root) return [];
        const root = tree.root;

        // Identify primary branch heads (children of the root)
        const branchNodes = A4PrintComposer._collectAtlasBranchHeads(tree, root);
        const branchInfoList = branchNodes.map((bNode, idx) =>
            A4PrintComposer._buildBranchInfoDescriptor(bNode, idx, tree)
        );

        const totalAtlasSheets = 1 + branchInfoList.length;
        const sheets = [];

        // 1. MASTER OVERVIEW SHEET (Sheet 1)
        sheets.push(A4PrintComposer._buildAtlasOverviewSheet(
            tree, root, { branchNodes, branchInfoList, totalAtlasSheets }, layoutConfig, options
        ));

        // 2. DEDICATED BRANCH CHAPTER SHEETS (Sheets 2..N+1)
        branchInfoList.forEach(bInfo => {
            sheets.push(A4PrintComposer._buildAtlasBranchSheet(tree, bInfo, totalAtlasSheets, layoutConfig, options));
        });

        return sheets;
    }

    /**
     * Generates base CSS layout rules for screen display of A4 pages in the preview wrapper.
     *
     * @returns {string} Screen layout CSS rules.
     *
     * @example
     * A4PrintComposer._getBaseA4SheetStyles().includes('.a4-sheet')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getBaseA4SheetStyles();
     * console.log(styles.includes('.sheet-header'));
     */
    static _getBaseA4SheetStyles() {
        const mm = A4PrintComposer._computePageMillimeterDimensions();
        return `        * { box-sizing: border-box; }
        body {
            margin: 0; padding: 0; background-color: #0f172a; color: #334155;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important;
        }
        .sheets-wrapper { padding: 24px 20px; display: flex; flex-direction: column; align-items: center; gap: 28px; }
        .a4-sheet {
            width: ${mm.pageWidthMm}mm; height: ${mm.pageHeightMm}mm; background: white; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
            border-radius: 4px; padding: ${mm.marginMm}mm; display: flex; flex-direction: column; justify-content: space-between;
            position: relative; overflow: hidden; page-break-after: always; break-after: page;
            page-break-inside: avoid; break-inside: avoid;
        }
        .sheet-header, .sheet-footer { display: flex; justify-content: space-between; align-items: center; font-size: 8pt; color: #94a3b8; user-select: none; }
        .sheet-header { border-bottom: 1px dashed #e2e8f0; padding-bottom: 3mm; margin-bottom: 2mm; }
        .sheet-footer { border-top: 1px dashed #e2e8f0; padding-top: 3mm; margin-top: 2mm; }
        .sheet-body { flex: 1; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; overflow: hidden; }
        .sheet-body svg { width: ${mm.printableWidthMm}mm; height: ${mm.printableHeightMm}mm; max-width: 100%; max-height: 100%; display: block; background: #ffffff; }`;
    }

    /**
     * Generates @page and @media print CSS rules for clean physical A4 page printing.
     *
     * @returns {string} Print media CSS rules.
     *
     * @example
     * A4PrintComposer._getBaseA4MediaPrintStyles().includes('@media print')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getBaseA4MediaPrintStyles();
     * console.log(styles.includes('size: A4 landscape'));
     */
    static _getBaseA4MediaPrintStyles() {
        const mm = A4PrintComposer._computePageMillimeterDimensions();
        return `        @page { size: A4 landscape; margin: 0; }
        @media print {
            html, body { background: white !important; color: black !important; }
            .no-print { display: none !important; }
            .sheets-wrapper { padding: 0 !important; gap: 0 !important; display: block !important; }
            .a4-sheet {
                width: ${mm.pageWidthMm}mm !important; height: ${mm.pageHeightMm}mm !important; box-shadow: none !important; border-radius: 0 !important;
                padding: ${mm.marginMm}mm !important; margin: 0 !important; page-break-after: always !important; break-after: page !important;
                -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important;
            }
            .sheet-body svg { width: ${mm.printableWidthMm}mm !important; height: ${mm.printableHeightMm}mm !important; }
        }`;
    }

    /**
     * Generates base CSS styles for A4 landscape paper sheets, headers, footers, and print media rules.
     *
     * @returns {string} Base print stylesheet
     *
     * @example
     * A4PrintComposer._getBaseA4PrintStyles().includes('size: A4 landscape');
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getBaseA4PrintStyles();
     * console.log(styles.includes('.a4-sheet'));
     */
    static _getBaseA4PrintStyles() {
        return `${A4PrintComposer._getBaseA4SheetStyles()}\n${A4PrintComposer._getBaseA4MediaPrintStyles()}`;
    }

    /**
     * Generates CSS layout rules for the sticky print preview toolbar and left metadata.
     *
     * @returns {string} Toolbar container CSS rules.
     *
     * @example
     * A4PrintComposer._getToolbarA4ContainerStyles().includes('.print-toolbar')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getToolbarA4ContainerStyles();
     * console.log(styles.includes('.toolbar-title'));
     */
    static _getToolbarA4ContainerStyles() {
        return `        .print-toolbar {
            position: sticky; top: 0; z-index: 1000; background: rgba(15, 23, 42, 0.96);
            backdrop-filter: blur(12px); border-bottom: 1px solid rgba(255, 255, 255, 0.12);
            padding: 12px 24px; display: flex; align-items: center; justify-content: space-between;
            color: #f8fafc; box-shadow: 0 4px 20px rgba(0,0,0,0.35);
        }
        .toolbar-left { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
        .toolbar-title { margin: 0; font-size: 16px; font-weight: 700; color: #f8fafc; }
        .toolbar-badge {
            background: rgba(255, 255, 255, 0.12); color: #cbd5e1; font-size: 11px;
            font-weight: 600; padding: 3px 8px; border-radius: 9999px; border: 1px solid rgba(255, 255, 255, 0.08);
        }`;
    }

    /**
     * Generates CSS styles for the primary print action button.
     *
     * @returns {string} Button CSS rules.
     *
     * @example
     * A4PrintComposer._getToolbarA4ButtonStyles().includes('.print-btn')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getToolbarA4ButtonStyles();
     * console.log(styles.includes('linear-gradient'));
     */
    static _getToolbarA4ButtonStyles() {
        return `        .print-btn {
            background: linear-gradient(135deg, #2563eb, #1d4ed8); color: white; border: none;
            padding: 9px 18px; font-size: 13px; font-weight: 600; border-radius: 8px; cursor: pointer;
            display: inline-flex; align-items: center; gap: 8px; box-shadow: 0 2px 8px rgba(37, 99, 235, 0.4);
            transition: all 0.2s ease;
        }
        .print-btn:hover {
            background: linear-gradient(135deg, #1d4ed8, #1e40af); transform: translateY(-1px);
            box-shadow: 0 4px 12px rgba(37, 99, 235, 0.5);
        }`;
    }

    /**
     * Combines container, layout, and button styling for the A4 print preview toolbar.
     *
     * @returns {string} Toolbar CSS stylesheet
     *
     * @example
     * A4PrintComposer._getToolbarA4PrintStyles().includes('.print-toolbar');
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getToolbarA4PrintStyles();
     * console.log(styles.includes('.print-btn'));
     */
    static _getToolbarA4PrintStyles() {
        return `${A4PrintComposer._getToolbarA4ContainerStyles()}\n${A4PrintComposer._getToolbarA4ButtonStyles()}`;
    }

    /**
     * Generates CSS styles for the multi-page poster assembly guide container and header instructions.
     *
     * @returns {string} Guide container CSS rules.
     *
     * @example
     * A4PrintComposer._getAssemblyGuideHeaderStyles().includes('.assembly-guide')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getAssemblyGuideHeaderStyles();
     * console.log(styles.includes('.guide-header'));
     */
    static _getAssemblyGuideHeaderStyles() {
        return `        .assembly-guide {
            max-width: 297mm; margin: 20px auto 0 auto; background: rgba(30, 41, 59, 0.7);
            border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 16px 20px; color: #cbd5e1;
        }
        .guide-header { font-size: 12px; line-height: 1.5; margin-bottom: 12px; }
        .guide-header strong { color: #38bdf8; margin-right: 6px; }
        .grid-overview { display: flex; justify-content: center; }`;
    }

    /**
     * Generates CSS styles for the assembly matrix grid table and page indicator cells.
     *
     * @returns {string} Matrix grid cell CSS rules.
     *
     * @example
     * A4PrintComposer._getAssemblyGuideGridStyles().includes('.grid-table')
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getAssemblyGuideGridStyles();
     * console.log(styles.includes('.grid-cell'));
     */
    static _getAssemblyGuideGridStyles() {
        return `        .grid-table {
            display: grid; gap: 6px; background: rgba(15, 23, 42, 0.6); padding: 8px;
            border-radius: 8px; border: 1px solid rgba(255, 255, 255, 0.06);
        }
        .grid-cell {
            padding: 8px 12px; font-size: 11px; text-align: center; border-radius: 6px;
            text-decoration: none; line-height: 1.3;
        }
        .grid-cell.active { background: #1e3a8a; color: #93c5fd; border: 1px solid #3b82f6; font-weight: 600; }
        .grid-cell.active:hover { background: #2563eb; color: white; }
        .grid-cell.empty { background: rgba(51, 65, 85, 0.3); color: #64748b; border: 1px dashed rgba(255, 255, 255, 0.1); }`;
    }

    /**
     * Combines instructions header and matrix table styling for the poster assembly guide.
     *
     * @returns {string} Assembly guide CSS stylesheet
     *
     * @example
     * A4PrintComposer._getAssemblyGuideA4PrintStyles().includes('.assembly-guide');
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getAssemblyGuideA4PrintStyles();
     * console.log(styles.includes('.grid-table'));
     */
    static _getAssemblyGuideA4PrintStyles() {
        return `${A4PrintComposer._getAssemblyGuideHeaderStyles()}\n${A4PrintComposer._getAssemblyGuideGridStyles()}`;
    }

    /**
     * Generates CSS styles for printable A4 landscape pages and toolbar controls.
     *
     * @returns {string} CSS stylesheet
     *
     * @example
     * A4PrintComposer._getA4PrintStyles().includes('size: A4 landscape');
     * // => true
     *
     * @example
     * const styles = A4PrintComposer._getA4PrintStyles();
     * console.log(styles.includes('.print-toolbar'));
     */
    static _getA4PrintStyles() {
        return `
        ${A4PrintComposer._getBaseA4PrintStyles()}
        ${A4PrintComposer._getToolbarA4PrintStyles()}
        ${A4PrintComposer._getAssemblyGuideA4PrintStyles()}`;
    }

    /**
     * Renders HTML sections for each A4 landscape sheet in Compact Poster mode.
     *
     * @param {Object} compactGrid - Grid specification with tiles, printable dimensions, etc.
     * @param {string} innerSvg - Inner SVG content string
     * @param {string} title - Lineage or document title
     * @returns {string} Concatenated HTML sheets
     *
     * @example
     * A4PrintComposer._renderCompactA4Sheets(grid, '<g></g>', 'Smith');
     * // => '<section class="a4-sheet" ...>...</section>'
     *
     * @example
     * A4PrintComposer._renderCompactA4Sheets({ tiles: [], printableWidthMm: 277, printableHeightMm: 190, rows: 0, cols: 0 }, '', '');
     * // => ''
     */
    static _renderCompactA4Sheets(compactGrid, innerSvg, title) {
        const compactTotalPages = compactGrid.tiles.length;
        const escapedTitle = SvgTreeRenderer._escapeSvgXml(title);
        return compactGrid.tiles.map(tile => `
        <section class="a4-sheet" data-sheet-type="compact" id="page-${tile.pageIndex}" data-page="${tile.pageIndex}" data-row="${tile.row + 1}" data-col="${tile.col + 1}">
            <header class="sheet-header no-print">
                <span class="sheet-title"><strong>${escapedTitle}</strong> — Sheet ${tile.pageIndex} of ${compactTotalPages}</span>
                <span class="sheet-coords">Grid: Row ${tile.row + 1} of ${compactGrid.rows}, Column ${tile.col + 1} of ${compactGrid.cols}</span>
            </header>
            <div class="sheet-body">
                <svg 
                    xmlns="http://www.w3.org/2000/svg" 
                    width="${compactGrid.printableWidthMm}mm" 
                    height="${compactGrid.printableHeightMm}mm" 
                    viewBox="${tile.viewBox}"
                    preserveAspectRatio="xMidYMid meet"
                >
                    ${innerSvg}
                </svg>
            </div>
            <footer class="sheet-footer">
                <span class="sheet-meta">${escapedTitle} • Sheet ${tile.pageIndex} of ${compactTotalPages} • Row ${tile.row + 1}, Col ${tile.col + 1}</span>
                <span class="sheet-scale">Compact Poster (${compactGrid.cols}×${compactGrid.rows} Grid) • 10pt names on A4 Landscape</span>
            </footer>
        </section>`).join('\n');
    }

    /**
     * Renders a single cell inside the print grid overview table.
     *
     * @param {Object|null} matchTile - Matching grid tile or undefined
     * @param {number} r - Zero-indexed row number
     * @param {number} c - Zero-indexed column number
     * @returns {string} Cell HTML markup
     *
     * @example
     * A4PrintComposer._renderGridOverviewCell({ pageIndex: 1 }, 0, 0);
     * // => '<a href="#page-1" ...'
     *
     * @example
     * A4PrintComposer._renderGridOverviewCell(null, 0, 1);
     * // => '<div class="grid-cell empty" ...'
     */
    static _renderGridOverviewCell(matchTile, r, c) {
        if (matchTile) {
            return `<a href="#page-${matchTile.pageIndex}" class="grid-cell active" title="Page ${matchTile.pageIndex} (Row ${r+1}, Col ${c+1})">Page ${matchTile.pageIndex}<br><small>R${r+1} C${c+1}</small></a>`;
        }
        return `<div class="grid-cell empty" title="Empty (Row ${r+1}, Col ${c+1})"><em>Empty</em><br><small>R${r+1} C${c+1}</small></div>`;
    }

    /**
     * Renders the complete HTML grid overview table for compact poster assembly.
     *
     * @param {Object} compactGrid - Grid layout configuration and tiles
     * @returns {string} Grid table HTML string
     *
     * @example
     * A4PrintComposer._renderGridOverviewTable({ rows: 1, cols: 1, tiles: [{ pageIndex: 1, row: 0, col: 0 }] });
     *
     * @example
     * A4PrintComposer._renderGridOverviewTable({ rows: 0, cols: 0, tiles: [] });
     */
    static _renderGridOverviewTable(compactGrid) {
        if (!compactGrid || compactGrid.rows <= 0 || compactGrid.cols <= 0) return '';
        let cells = '';
        for (let r = 0; r < compactGrid.rows; r++) {
            for (let c = 0; c < compactGrid.cols; c++) {
                const matchTile = compactGrid.tiles.find(t => t.row === r && t.col === c);
                cells += A4PrintComposer._renderGridOverviewCell(matchTile, r, c);
            }
        }
        return `<div class="grid-overview"><div class="grid-table" style="grid-template-columns: repeat(${compactGrid.cols}, 1fr);">${cells}</div></div>`;
    }

    /**
     * Renders an HTML overview map showing the layout grid of A4 sheets for print assembly.
     *
     * @param {Object} compactGrid - Grid layout configuration and tiles
     * @returns {string} Assembly guide HTML string
     *
     * @example
     * A4PrintComposer._renderCompactAssemblyGuide({ rows: 1, cols: 1, tiles: [{ pageIndex: 1, row: 0, col: 0 }] });
     * // => '<div class="guide-compact">...<a href="#page-1" ...>Page 1...</a>...</div>'
     *
     * @example
     * A4PrintComposer._renderCompactAssemblyGuide({ rows: 0, cols: 0, tiles: [] });
     * // => '<div class="guide-compact">...</div>'
     */
    static _renderCompactAssemblyGuide(compactGrid) {
        const compactGridMapHtml = A4PrintComposer._renderGridOverviewTable(compactGrid);
        return `
        <div class="guide-compact">
            <div class="guide-header">
                <strong>📐 Compact Poster (${compactGrid.cols}×${compactGrid.rows} Grid, ${compactGrid.tiles.length} Pages):</strong>
                <span>Tree vertically compressed by generation depth with relaxed spacing to fill page height without bottom whitespace. Fits in <strong>${compactGrid.cols}×${compactGrid.rows} Grid (${compactGrid.tiles.length} Pages)</strong>. Names calibrated at ~${compactGrid.effectiveFontSizePt}pt.</span>
            </div>
            ${compactGridMapHtml}
        </div>`;
    }

    /**
     * Renders the top toolbar markup for the printable A4 HTML view.
     *
     * @param {string} escTitle - XML/HTML escaped document title
     * @param {string} badgesHtml - Formatted badge HTML elements
     * @returns {string} Toolbar HTML markup
     *
     * @example
     * A4PrintComposer._renderA4PrintToolbar('Smith Lineage', '<span class="toolbar-badge">Page 1</span>');
     * // => '    <div class="print-toolbar no-print">...'
     *
     * @example
     * A4PrintComposer._renderA4PrintToolbar('Tree', '');
     * // => '    <div class="print-toolbar no-print">...'
     */
    static _renderA4PrintToolbar(escTitle, badgesHtml) {
        return `    <div class="print-toolbar no-print">
        <div class="toolbar-left">
            <h1 class="toolbar-title">${escTitle}</h1>
            ${badgesHtml}
        </div>
        <div class="toolbar-right">
            <button class="print-btn" onclick="window.print()">
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect width="12" height="8" x="6" y="14"></rect></svg>
                <span>Print / Save to PDF</span>
            </button>
        </div>
    </div>`;
    }

    /**
     * Builds the standard HTML5 shell and toolbar for printable A4 documents.
     *
     * @param {Object} p - Document configuration parameters.
     * @param {string} [p.title] - Document title.
     * @param {string} [p.escapedTitle] - Pre-escaped document title.
     * @param {Array<string>} [p.badges=[]] - Toolbar badge labels.
     * @param {string} [p.bodyHtml=''] - HTML content to inject in document body.
     * @returns {string} Full HTML document string.
     *
     * @example
     * A4PrintComposer._buildA4DocumentHtml({ title: 'Tree', badges: ['Page 1'], bodyHtml: '<main></main>' });
     * // => '<!DOCTYPE html>...'
     *
     * @example
     * A4PrintComposer._buildA4DocumentHtml({ escapedTitle: 'Custom &amp; Title' });
     * // => '<!DOCTYPE html>...<title>Custom &amp; Title — A4 Landscape Print View</title>...'
     */
    static _buildA4DocumentHtml({ title, escapedTitle, badges = [], bodyHtml = '' }) {
        const escTitle = escapedTitle || SvgTreeRenderer._escapeSvgXml(title || 'Family Tree');
        const badgesHtml = badges.map(b => `<span class="toolbar-badge">${b}</span>`).join('\n            ');
        return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${escTitle} — A4 Landscape Print View</title>
    <link rel="icon" type="image/svg+xml" href="${FamilyTreeBuilder.FAVICON_DATA_URI}">
    <style>
        ${A4PrintComposer._getA4PrintStyles()}
    </style>
</head>
<body>
${A4PrintComposer._renderA4PrintToolbar(escTitle, badgesHtml)}
${bodyHtml}
</body>
</html>`;
    }

    /**
     * Renders printable A4 assembly guide and sheet wrapper body HTML markup.
     *
     * @param {Object} compactGrid - Grid layout specification
     * @param {string} innerSvg - Inner SVG markup for family tree
     * @param {string} title - Lineage or document title
     * @returns {string} Body HTML container string
     *
     * @example
     * const body = A4PrintComposer._renderPrintableA4Body({ tiles: [], cols: 1, rows: 1 }, '<g></g>', 'Title');
     * // body.includes('<main class="sheets-wrapper">') => true
     *
     * @example
     * const body = A4PrintComposer._renderPrintableA4Body({ tiles: [], cols: 1, rows: 1 }, '', 'Tree');
     * // body.includes('assembly-guide') => true
     */
    static _renderPrintableA4Body(compactGrid, innerSvg, title) {
        const compactPagesHtml = A4PrintComposer._renderCompactA4Sheets(compactGrid, innerSvg, title);
        const compactGuideHtml = A4PrintComposer._renderCompactAssemblyGuide(compactGrid);
        return `    <div class="assembly-guide no-print">\n        ${compactGuideHtml}\n    </div>\n\n    <main class="sheets-wrapper">\n        ${compactPagesHtml}\n    </main>`;
    }

    /**
     * Builds a standalone, print-ready HTML document splitting the tree canvas into a series
     * of SVG images formatted for A4 landscape paper in Compact Poster mode (<= 10 pages).
     * Applies relaxed vertical compression to eliminate bottom whitespace.
     *
     * @param {FamilyTree} tree - Populated family tree instance
     * @param {Object} [layoutConfig={}] - Tree layout options
     * @param {Object} [options={}] - Formatting options
     * @returns {string} Complete HTML document content
     *
     * @example
     * const html = A4PrintComposer.buildPrintableA4Html(tree);
     * // => '<!DOCTYPE html>...'
     *
     * @example
     * const html = A4PrintComposer.buildPrintableA4Html(tree, {}, { title: 'Smith Lineage', targetPages: 6 });
     * // => '<!DOCTYPE html>...Smith Lineage...'
     */
    static buildPrintableA4Html(tree, layoutConfig = {}, options = {}) {
        const title = options.title || (tree?.root?.name ? `${tree.root.name} Family Tree` : 'Family Tree');
        const escapedTitle = SvgTreeRenderer._escapeSvgXml(title);

        const compactGrid = A4PrintComposer.computeA4PrintGrid(tree, layoutConfig, {
            ...options,
            mode: 'compact',
            targetPages: options.targetPages || 10,
            autoFitPages: true
        });
        const effectiveLayoutConfig = {
            ...layoutConfig,
            verticalCompression: true,
            generationRowHeight: compactGrid.generationRowHeight || layoutConfig.generationRowHeight || 160
        };
        const compactSvgResult = SvgTreeRenderer.generatePureSvgTree(tree, effectiveLayoutConfig, options);

        return A4PrintComposer._buildA4DocumentHtml({
            escapedTitle,
            badges: [`${compactGrid.tiles.length} Pages (${compactGrid.cols}×${compactGrid.rows} Grid)`],
            bodyHtml: A4PrintComposer._renderPrintableA4Body(compactGrid, compactSvgResult.innerSvg, title)
        });
    }

    /**
     * Generates an array of page tiles spanning a 2D SVG canvas.
     *
     * @param {number} vbX - Origin X.
     * @param {number} vbY - Origin Y.
     * @param {number} cols - Number of columns.
     * @param {number} rows - Number of rows.
     * @param {number} tileWidthPx - Tile width in user units.
     * @param {number} tileHeightPx - Tile height in user units.
     * @returns {Array<{ pageIndex: number, row: number, col: number, viewBox: string }>}
     *
     * @example
     * A4PrintComposer._generateSvgGridTiles(0, 0, 1, 1, 500, 400);
     * // => [{ pageIndex: 1, row: 0, col: 0, viewBox: "0.0 0.0 500.0 400.0" }]
     *
     * @example
     * A4PrintComposer._generateSvgGridTiles(10, 20, 2, 1, 300, 200);
     * // => [{ pageIndex: 1, row: 0, col: 0, ... }, { pageIndex: 2, row: 0, col: 1, ... }]
     */
    static _generateSvgGridTiles(vbX, vbY, cols, rows, tileWidthPx, tileHeightPx) {
        const tiles = [];
        let pageNumber = 1;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                const tx = vbX + c * tileWidthPx;
                const ty = vbY + r * tileHeightPx;
                tiles.push({
                    pageIndex: pageNumber++,
                    row: r,
                    col: c,
                    viewBox: `${tx.toFixed(1)} ${ty.toFixed(1)} ${tileWidthPx.toFixed(1)} ${tileHeightPx.toFixed(1)}`
                });
            }
        }
        return tiles;
    }

    /**
     * Parses viewBox/dimensions from a raw SVG string and slices it into a grid of page tiles.
     *
     * @param {string} rawSvg - Raw SVG string
     * @param {number} tileWidthPx - Tile width in SVG user units
     * @param {number} tileHeightPx - Tile height in SVG user units
     * @returns {{ cols: number, rows: number, tiles: Array<{ pageIndex: number, row: number, col: number, viewBox: string }> }}
     *
     * @example
     * A4PrintComposer._sliceRawSvgTiles('<svg viewBox="0 0 1000 800">...</svg>', 500, 400);
     * // => { cols: 2, rows: 2, tiles: [...] }
     *
     * @example
     * A4PrintComposer._sliceRawSvgTiles('<svg width="300" height="200">...</svg>', 500, 400);
     * // => { cols: 1, rows: 1, tiles: [...] }
     */
    static _sliceRawSvgTiles(rawSvg, tileWidthPx, tileHeightPx) {
        const { vbX, vbY, vbW, vbH } = SvgTreeRenderer._parseSvgDimensions(rawSvg);
        const cols = Math.max(1, Math.ceil(vbW / tileWidthPx));
        const rows = Math.max(1, Math.ceil(vbH / tileHeightPx));
        const tiles = A4PrintComposer._generateSvgGridTiles(vbX, vbY, cols, rows, tileWidthPx, tileHeightPx);
        return { cols, rows, tiles };
    }

    /**
     * Renders A4 printable sheet sections for raw SVG tiles.
     *
     * @param {Array<Object>} tiles - Sliced tile objects
     * @param {string} innerContent - Inner SVG XML contents without root <svg> tags
     * @param {string} title - Document title
     * @param {Object} sheetSpec - Sheet dimensions and grid counts ({ printableWidthMm, printableHeightMm, rows, cols })
     * @returns {string} Concatenated HTML sections
     *
     * @example
     * A4PrintComposer._renderRawSvgA4Sheets([{ pageIndex: 1, row: 0, col: 0, viewBox: '0 0 100 100' }], '<rect/>', 'Atlas', { printableWidthMm: 277, printableHeightMm: 190, rows: 1, cols: 1 });
     * // => '<section class="a4-sheet" id="page-1" ...>...</section>'
     *
     * @example
     * A4PrintComposer._renderRawSvgA4Sheets([], '', 'Empty', { printableWidthMm: 277, printableHeightMm: 190, rows: 0, cols: 0 });
     * // => ''
     */
    static _renderRawSvgA4Sheets(tiles, innerContent, title, sheetSpec) {
        const { printableWidthMm, printableHeightMm, rows, cols } = sheetSpec;
        const totalPages = tiles.length;
        return tiles.map(tile => `
        <section class="a4-sheet" id="page-${tile.pageIndex}" data-page="${tile.pageIndex}">
            <header class="sheet-header no-print">
                <span class="sheet-title"><strong>${title}</strong> — Sheet ${tile.pageIndex} of ${totalPages}</span>
                <span class="sheet-coords">Grid: Row ${tile.row + 1} of ${rows}, Column ${tile.col + 1} of ${cols}</span>
            </header>
            <div class="sheet-body">
                <svg xmlns="http://www.w3.org/2000/svg" width="${printableWidthMm}mm" height="${printableHeightMm}mm" viewBox="${tile.viewBox}" preserveAspectRatio="xMidYMid meet">
                    ${innerContent}
                </svg>
            </div>
            <footer class="sheet-footer">
                <span class="sheet-meta">${title} • Sheet [${tile.row + 1}, ${tile.col + 1}] • Page ${tile.pageIndex} of ${totalPages}</span>
                <span class="sheet-scale">Calibrated for 10pt names on A4 Landscape (297×210mm)</span>
            </footer>
        </section>`).join('\n');
    }

    /**
     * Builds printable A4 landscape pages from a pre-captured raw SVG string.
     *
     * @param {string} rawSvg - Master SVG content
     * @param {Object} [options={}] - Formatting options
     * @returns {string} Complete HTML document content
     *
     * @example
     * const html = A4PrintComposer.buildPrintableA4HtmlFromSvg('<svg viewBox="0 0 800 600"><circle/></svg>');
     * // => '<!DOCTYPE html>...'
     *
     * @example
     * const html = A4PrintComposer.buildPrintableA4HtmlFromSvg('', {});
     * // => ''
     */
    static buildPrintableA4HtmlFromSvg(rawSvg, options = {}) {
        if (!rawSvg) return '';
        const metrics = A4PrintComposer._computePageMetrics(options);
        const { printableWidthMm, printableHeightMm, tileWidthPx, tileHeightPx } = metrics;
        const title = options.title || 'Family Tree';

        const { cols, rows, tiles } = A4PrintComposer._sliceRawSvgTiles(rawSvg, tileWidthPx, tileHeightPx);
        const innerContent = rawSvg.replace(/<svg[^>]*>/i, '').replace(/<\/svg\s*>$/i, '');
        const pagesHtml = A4PrintComposer._renderRawSvgA4Sheets(
            tiles, innerContent, title, { printableWidthMm, printableHeightMm, rows, cols }
        );
        const totalPages = tiles.length;

        return A4PrintComposer._buildA4DocumentHtml({
            title,
            badges: [
                'A4 Landscape',
                '10pt Names',
                `${totalPages} ${totalPages === 1 ? 'Page' : 'Pages'}`
            ],
            bodyHtml: `    <main class="sheets-wrapper">
        ${pagesHtml}
    </main>`
        });
    }
}


// ============================================================================
// MODULE 5: CUSTOM HOOKS & DATA ENGINE (Parallel Fetching & Caching)
// ============================================================================

/**
 * Client-side persistence cache for spreadsheet data to enable instant (<50ms) initial render.
 *
 * @example
 * TreeDataCache.set('https://docs.google.com/...', rows, sheetTags);
 * const cached = TreeDataCache.get('https://docs.google.com/...');
 *
 * @example
 * TreeDataCache.clear('https://docs.google.com/...');
 */
const TreeDataCache = {
    CACHE_PREFIX: 'ft_cache_v61_',

    /**
     * Generates a namespaced cache key for the provided spreadsheet URL.
     *
     * @param {string} [url] - Spreadsheet URL
     * @returns {string} Prefixed cache storage key
     *
     * @example
     * const key = TreeDataCache.getKey('https://docs.google.com/spreadsheets/d/123');
     *
     * @example
     * const emptyKey = TreeDataCache.getKey();
     */
    getKey(url) {
        return `${this.CACHE_PREFIX}${(url || '').trim()}`;
    },

    /**
     * Attempts to read embedded tree dataset from the document script tag.
     *
     * @param {string} [url] - Target sheet URL to match against embedded payload
     * @returns {Object|null} Embedded tree data object or null if not available
     *
     * @example
     * TreeDataCache._getEmbeddedTreeData('https://example.com')
     * // => { url: 'https://example.com', rows: [...] }
     *
     * @example
     * TreeDataCache._getEmbeddedTreeData('mismatched-url')
     * // => null
     */
    _getEmbeddedTreeData(url) {
        if (typeof document === 'undefined') return null;
        try {
            const embeddedElem = document.getElementById('embedded-tree-data');
            if (embeddedElem && embeddedElem.textContent.trim()) {
                const embeddedData = JSON.parse(embeddedElem.textContent);
                if (embeddedData && Array.isArray(embeddedData.rows) && embeddedData.rows.length > 0) {
                    if (!url || embeddedData.url === url || !embeddedData.url) {
                        return embeddedData;
                    }
                }
            }
        } catch (e) {}
        return null;
    },

    /**
     * Reads and parses cached tree data from browser localStorage.
     *
     * @param {string} key - Cache lookup key
     * @returns {Object|null} Cached tree dataset or null if missing or invalid
     *
     * @example
     * TreeDataCache._getLocalStorageTreeData('ft_cache_v61_sheet1')
     * // => { rows: [...], sheetTags: {...}, timestamp: 1672531199000 }
     *
     * @example
     * TreeDataCache._getLocalStorageTreeData('invalid_key')
     * // => null
     */
    _getLocalStorageTreeData(key) {
        if (typeof localStorage === 'undefined') return null;
        try {
            const raw = localStorage.getItem(key);
            if (!raw) return null;
            const data = JSON.parse(raw);
            if (data && Array.isArray(data.rows) && data.rows.length > 0) {
                return data;
            }
        } catch (e) {
            console.log("Cache read error:", e);
        }
        return null;
    },

    /**
     * Retrieves cached tree dataset for a URL from embedded script tag or localStorage.
     *
     * @param {string} [url] - Target sheet URL
     * @returns {Object|null} Cached tree dataset or null if not found
     *
     * @example
     * const data = TreeDataCache.get('https://docs.google.com/spreadsheets/d/123');
     *
     * @example
     * const fallbackData = TreeDataCache.get();
     */
    get(url) {
        const embedded = this._getEmbeddedTreeData(url);
        if (embedded) return embedded;
        return this._getLocalStorageTreeData(this.getKey(url));
    },

    /**
     * Serializes and writes tree dataset into localStorage under the given URL key.
     *
     * @param {string} url - Target sheet URL
     * @param {Array<Object>} rows - Parsed genealogical rows
     * @param {Object} sheetTags - Mapping of sheet IDs to tags/names
     * @returns {void}
     *
     * @example
     * TreeDataCache.set('https://docs.google.com/spreadsheets/d/123', rawRows, { '123': 'Main' });
     *
     * @example
     * TreeDataCache.set(sheetUrl, parsedData, tags);
     */
    set(url, rows, sheetTags) {
        try {
            const data = { rows, sheetTags, timestamp: Date.now() };
            localStorage.setItem(this.getKey(url), JSON.stringify(data));
        } catch (e) {
            console.log("Cache write error:", e);
        }
    },

    /**
     * Clears cached tree datasets for a specific URL or purges all family tree cache entries.
     *
     * @param {string} [url] - Specific sheet URL to purge; if omitted, clears all ft_cache_ entries
     * @returns {void}
     *
     * @example
     * TreeDataCache.clear('https://docs.google.com/spreadsheets/d/123');
     *
     * @example
     * TreeDataCache.clear();
     */
    clear(url) {
        try {
            if (url) {
                localStorage.removeItem(this.getKey(url));
            } else {
                Object.keys(localStorage).forEach(k => {
                    if (k.startsWith('ft_cache_')) localStorage.removeItem(k);
                });
            }
        } catch (e) {}
    }
};

/**
 * Constructs the Google Spreadsheet CSV export URL for direct downloads or named tabs.
 *
 * @param {string} sheetId - Google Spreadsheet document identifier.
 * @param {string} sheetName - Optional named sheet tab (e.g. 'Links').
 * @param {boolean} bypassCache - Whether to append cache-busting timestamp parameter.
 * @returns {string} Fully qualified export URL.
 *
 * @example
 * buildGoogleSheetCsvUrl('1AbC', '', false)
 * // => 'https://docs.google.com/spreadsheets/d/1AbC/export?format=csv'
 *
 * @example
 * buildGoogleSheetCsvUrl('1AbC', 'Links', false)
 * // => 'https://docs.google.com/spreadsheets/d/1AbC/gviz/tq?tqx=out:csv&sheet=Links'
 */
const buildGoogleSheetCsvUrl = (sheetId, sheetName = '', bypassCache = false) => {
    let url = sheetName
        ? `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(sheetName)}`
        : `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv`;
    if (bypassCache) url += `${url.includes('?') ? '&' : '?'}_cb=${Date.now()}`;
    return url;
};

/**
 * Attempts a fallback fetch using the Google Visualization Query endpoint if direct export fails or returns HTML.
 *
 * @param {string} sheetId - Google Spreadsheet document identifier.
 * @param {boolean} [bypassCache=false] - Whether to append cache-busting parameters.
 * @param {number} [timeoutMs=8000] - Request timeout in milliseconds.
 * @returns {Promise<string|null>} CSV text content if valid, otherwise null.
 *
 * @example
 * await fetchFallbackGvizCsv('1AbC', false, 8000);
 * // => 'Name,Father,Mother\nPaul,Joseph,Mary'
 *
 * @example
 * await fetchFallbackGvizCsv('nonexistent_id', true, 5000);
 * // => null
 */
const fetchFallbackGvizCsv = async (sheetId, bypassCache = false, timeoutMs = 8000) => {
    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
        const fallbackUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:csv${bypassCache ? `&_cb=${Date.now()}` : ''}`;
        const fetchOptions = { signal: controller.signal };
        if (bypassCache) {
            fetchOptions.cache = 'no-store';
        }
        const fbRes = await fetch(fallbackUrl, fetchOptions);
        clearTimeout(timeoutId);
        if (fbRes.ok) {
            const fbText = await fbRes.text();
            if (fbText && !fbText.trim().startsWith('<html')) return fbText;
        }
    } catch (_) {}
    return null;
};

/**
 * Checks whether CSV text content contains standard genealogical header keywords.
 *
 * @param {string|null} text - Raw CSV text line.
 * @returns {boolean} True if header keywords match.
 *
 * @example
 * hasGenealogicalHeaders('Name,Father,Mother\nPaul,Joseph,Mary')
 * // => true
 *
 * @example
 * hasGenealogicalHeaders('Index,Timestamp,Score\n1,12345,99')
 * // => false
 */
const hasGenealogicalHeaders = (text) => {
    if (!text) return false;
    const lower = text.toLowerCase();
    return lower.includes('name') && (lower.includes('mother') || lower.includes('mom') || lower.includes('father') || lower.includes('hus') || lower.includes('spouse') || lower.includes('family'));
};

/**
 * Recursively flattens a hierarchical sheet node tree into displayable lines with ASCII branching prefixes.
 *
 * @param {Object} node - Hierarchical sheet node { id, tag, status, count, children }
 * @param {string} [prefix=''] - Parent indentation prefix
 * @param {boolean} [isLast=true] - Whether this node is the last sibling
 * @param {number} [depth=0] - Current tree recursion depth
 * @returns {Array<{id: string, prefix: string, tag: string, status: string, count: number}>}
 *
 * @example
 * flattenSheetTree({ id: 's1', tag: 'Root', status: 'success', count: 12, children: [] })
 * // => [{ id: 's1', prefix: '', tag: 'Root', status: 'success', count: 12 }]
 *
 * @example
 * flattenSheetTree({ id: 's1', tag: 'Root', children: [{ id: 's2', tag: 'Branch', children: [] }] })
 * // => [{ id: 's1', prefix: '', ... }, { id: 's2', prefix: '└── ', ... }]
 */
function flattenSheetTree(node, prefix = '', isLast = true, depth = 0) {
    const nodePrefix = depth === 0 ? '' : (isLast ? '└── ' : '├── ');
    const childPrefix = prefix + (depth === 0 ? '' : (isLast ? '    ' : '│   '));
    const fullPrefix = prefix + nodePrefix;
    const line = {
        id: node.id,
        prefix: fullPrefix,
        tag: node.tag,
        status: node.status,
        count: node.count
    };
    const childLines = (node.children || []).flatMap((c, idx) => 
        flattenSheetTree(c, childPrefix, idx === node.children.length - 1, depth + 1)
    );
    return [line, ...childLines];
}

/**
 * Renders the JSX message for a sheet tree log entry based on its crawl status.
 *
 * @param {JSX.Element} sheetLink - Sheet hyperlink anchor element
 * @param {Object} item - Tree line descriptor with status and extracted profile count
 * @returns {JSX.Element} Formatted message node
 *
 * @example
 * _renderSheetLogStatusMessage(<a href="#">Sheet</a>, { status: 'loading', count: 0 });
 * // => <span>...</span>
 *
 * @example
 * _renderSheetLogStatusMessage(<a href="#">Sheet</a>, { status: 'success', count: 15 });
 * // => <span>...</span>
 */
function _renderSheetLogStatusMessage(sheetLink, item) {
    if (item.status === 'loading') {
        return <span>{sheetLink} <span className="text-slate-400 animate-pulse">...</span></span>;
    }
    const countColor = item.status === 'success' ? 'text-slate-500' : 'text-orange-500';
    return <span>{sheetLink} <span className={`${countColor} font-normal text-[11px]`}>({item.count || 0} profiles)</span></span>;
}

/**
 * Transforms flattened sheet tree nodes into formatted React log entry objects.
 *
 * @param {Array<{id: string, tag: string, status: string, count: number, prefix: string}>} lines - Flattened tree lines
 * @returns {Array<{id: string, time: string, msg: JSX.Element, type: string, prefix: string}>} Array of formatted log entries
 *
 * @example
 * buildSheetTreeLogItems([{ id: 's1', tag: 'Main Sheet', status: 'success', count: 12, prefix: '' }])
 * // => [{ id: 's1', time: '14:20:00', msg: <span>...</span>, type: 'success', prefix: '' }]
 *
 * @example
 * buildSheetTreeLogItems([{ id: 's2', tag: 'Branch', status: 'loading', count: 0, prefix: '└── ' }])
 * // => [{ id: 's2', type: 'info', prefix: '└── ', ... }]
 */
function buildSheetTreeLogItems(lines) {
    return lines.map(item => {
        const sheetLink = (
            <a 
                href={`https://docs.google.com/spreadsheets/d/${item.id}/edit`} 
                target="_blank" rel="noopener noreferrer" 
                className="text-blue-600 hover:text-blue-800 font-semibold underline decoration-blue-300 underline-offset-2"
                title={item.id}
            >
                {item.tag}
            </a>
        );

        return {
            id: item.id,
            time: new Date().toLocaleTimeString([], { hour12: false }),
            msg: _renderSheetLogStatusMessage(sheetLink, item),
            type: item.status === 'loading' ? 'info' : item.status,
            prefix: item.prefix
        };
    });
}

/**
 * Merges updated sheet tree log items into the previous logs array, preserving non-tree logs.
 *
 * @param {Array<Object>} prevLogs - Existing log entries
 * @param {Array<Object>} treeLogItems - Newly generated tree log entries
 * @returns {Array<Object>} Merged log entries
 *
 * @example
 * mergeTreeLogEntries([{ id: 'init', msg: 'start' }], [{ id: 's1', msg: 'sheet' }])
 * // => [{ id: 'init', msg: 'start' }, { id: 's1', msg: 'sheet' }]
 *
 * @example
 * mergeTreeLogEntries([], [{ id: 's1', msg: 'sheet' }])
 * // => [{ id: 's1', msg: 'sheet' }]
 */
function mergeTreeLogEntries(prevLogs, treeLogItems) {
    const treeIds = new Set(treeLogItems.map(tl => tl.id));
    const nonTreeLogs = prevLogs.filter(l => !treeIds.has(l.id));
    return [...nonTreeLogs, ...treeLogItems];
}

/**
 * Deterministically sorts row objects by source sheet ID and row number.
 *
 * @param {Array<Object>} rows - Raw person record rows
 * @returns {Array<Object>} Sorted row objects
 *
 * @example
 * sortSpreadsheetRows([{ _sourceId: 'B', _sheetRow: 2 }, { _sourceId: 'A', _sheetRow: 5 }])
 * // => [{ _sourceId: 'A', _sheetRow: 5 }, { _sourceId: 'B', _sheetRow: 2 }]
 *
 * @example
 * sortSpreadsheetRows([{ _sourceId: 'A', _sheetRow: 8 }, { _sourceId: 'A', _sheetRow: 3 }])
 * // => [{ _sourceId: 'A', _sheetRow: 3 }, { _sourceId: 'A', _sheetRow: 8 }]
 */
function sortSpreadsheetRows(rows) {
    return rows.sort((a, b) => 
        (a._sourceId || '').localeCompare(b._sourceId || '') || 
        (a._sheetRow || 0) - (b._sheetRow || 0)
    );
}

/**
 * Renders an interactive, clickable person link that dispatches a 'focusPerson' event to center on the person.
 *
 * @param {string|number} personId - ID of person to focus
 * @param {string} personName - Label name for the link
 * @param {string} [title='Click to focus on this person'] - Hover tooltip
 * @param {string} [extraClass=''] - Additional CSS classes
 * @returns {JSX.Element} Interactive link element
 *
 * @example
 * renderPersonFocusLink('p1', 'Alice', 'Click to focus')
 * // => <span onClick={...} className="..." title="Click to focus">Alice</span>
 *
 * @example
 * renderPersonFocusLink('p2', 'Bob', 'Focus Bob', 'ml-2')
 * // => <span onClick={...} className="... ml-2" title="Focus Bob">Bob</span>
 */
function renderPersonFocusLink(personId, personName, title = 'Click to focus on this person', extraClass = '') {
    return (
        <span 
            onClick={() => window.dispatchEvent(new CustomEvent('focusPerson', { detail: personId }))} 
            className={`text-blue-600 hover:text-blue-800 underline decoration-blue-300 font-semibold cursor-pointer inline ${extraClass}`}
            title={title}
        >
            {personName}
        </span>
    );
}

/**
 * Renders an external link badge that opens a specific row in Google Sheets.
 *
 * @param {string} sheetId - Google Sheets document ID
 * @param {number|string} row - Spreadsheet row number
 * @param {string} [sheetName='Sheet'] - Display sheet label
 * @param {string} [extraClass=''] - Additional styling classes
 * @returns {JSX.Element|null}
 *
 * @example
 * renderSheetRowBadge('1abc...', 42, 'Main Sheet')
 * // => <a href="https://docs.google.com/spreadsheets/d/1abc.../edit?gid=0#gid=0&range=42:42" ...>Main Sheet Row 42 ↗</a>
 *
 * @example
 * renderSheetRowBadge('', 10)
 * // => null
 */
function renderSheetRowBadge(sheetId, row, sheetName = 'Sheet', extraClass = '') {
    if (!row || !sheetId) return null;
    return (
        <a 
            href={`https://docs.google.com/spreadsheets/d/${sheetId}/edit?gid=0#gid=0&range=${row}:${row}`}
            target="_blank" rel="noopener noreferrer"
            className={`inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-sans font-medium hover:bg-blue-50 text-slate-600 hover:text-blue-600 border border-slate-200 shadow-2xs transition-colors align-middle ${extraClass}`}
            title={`Open Row ${row} in ${sheetName}`}
        >
            {sheetName} Row {row} ↗
        </a>
    );
}

/**
 * Resolves spreadsheet row number, sheet ID, and badge component for a person node.
 *
 * @param {Object} p - Person node
 * @param {string} startId - Default sheet ID
 * @param {Object} sheetTags - Sheet ID to display label mapping
 * @param {Object} [sheetNames={}] - Sheet ID to sheet name mapping
 * @param {string} [extraClass='bg-slate-100 ml-1'] - CSS class for badge
 * @returns {{ pRow: number|null, pSheetId: string, pSheetName: string, pRowBadge: React.ReactNode }}
 *
 * @example
 *   _resolvePersonSheetBadge({ sheetRow: 12, _sourceId: 's1' }, 's1', { s1: 'Main' }, {});
 *   // => { pRow: 12, pSheetId: 's1', pSheetName: 'Main', pRowBadge: <Badge ...> }
 *
 * @example
 *   _resolvePersonSheetBadge({ sheetRow: 99999, _sheetRow: 45 }, 's2', {}, { s2: 'Branch' });
 *   // => { pRow: 45, pSheetId: 's2', pSheetName: 'Branch', pRowBadge: <Badge ...> }
 */
function _resolvePersonSheetBadge(p, startId, sheetTags, sheetNames = {}, extraClass = 'bg-slate-100 ml-1') {
    const pRow = (p.sheetRow < 99999 ? p.sheetRow : p._sheetRow) || (p._allSourceRefs?.[0]?.row);
    const pSheetId = (p._sourceId && p._sourceId !== 'default') ? p._sourceId : startId;
    const pSheetName = sheetTags[pSheetId] || sheetNames?.[pSheetId] || 'Sheet';
    const pRowBadge = renderSheetRowBadge(pSheetId, pRow, pSheetName, extraClass);
    return { pRow, pSheetId, pSheetName, pRowBadge };
}

/**
 * Renders an inconsistency log item with person link, sheet row badge, and diagnostic text.
 *
 * @param {Object} inc - Inconsistency audit item
 * @param {string} startId - Default sheet ID
 * @param {Object} sheetTags - Sheet ID to display label mapping
 * @param {Object} [sheetNames={}] - Sheet ID to sheet name mapping
 * @param {string} [textClass='text-slate-700'] - Container text CSS classes
 * @param {React.ReactNode} [textNode=null] - Optional customized message node (defaults to inc.text)
 * @returns {React.ReactNode}
 *
 * @example
 *   _renderAuditInconsistencyItem({ p: { id: 'p1', name: 'John' }, text: 'Age mismatch' }, 's1', { s1: 'Main' }, {});
 *
 * @example
 *   _renderAuditInconsistencyItem(inc, 's1', tags, names, 'text-rose-600', <b>Custom Warning</b>);
 */
function _renderAuditInconsistencyItem(inc, startId, sheetTags, sheetNames, textClass = 'text-slate-700', textNode = null) {
    const linkNode = renderPersonFocusLink(inc.p.id, inc.p.name, 'Click to focus');
    const { pRowBadge } = _resolvePersonSheetBadge(inc.p, startId, sheetTags, sheetNames);
    return (
        <span className={`whitespace-normal leading-relaxed text-[12px] block mt-0.5 ${textClass}`}>
            {linkNode} {pRowBadge} <span className="text-slate-400 font-sans mx-1">—</span> {textNode || inc.text}
        </span>
    );
}

/**
 * Renders a compact chip for a partner profile in the multi-partner audit log.
 *
 * @param {string} partnerId - Partner person ID
 * @param {FamilyTree} newTree - Tree domain instance
 * @param {string} startId - Default sheet ID
 * @param {Object} sheetTags - Sheet ID to display label mapping
 * @returns {React.ReactNode}
 *
 * @example
 *   _renderMultiplePartnerPill('p1', tree, 's1', { s1: 'Main' });
 *
 * @example
 *   _renderMultiplePartnerPill('p2', tree, 's2', {});
 */
function _renderMultiplePartnerPill(partnerId, newTree, startId, sheetTags) {
    const partner = newTree.get(partnerId);
    const pName = partner ? partner.name : partnerId;
    const datePart = [
        partner?.yob ? `b. ${partner.yob}` : '',
        partner?.death ? `d. ${partner.death}` : ''
    ].filter(Boolean).join(', ');

    const partRow = (partner?.sheetRow < 99999 ? partner.sheetRow : partner?._sheetRow) || (partner?._allSourceRefs?.[0]?.row);
    const partSheetId = (partner?._sourceId && partner?._sourceId !== 'default') ? partner._sourceId : startId;
    const partSheetName = sheetTags[partSheetId] || newTree.sheetNames?.[partSheetId] || 'Sheet';
    const partRowBadge = partRow ? (
        <a 
            href={`https://docs.google.com/spreadsheets/d/${partSheetId}/edit?gid=0#gid=0&range=${partRow}:${partRow}`}
            target="_blank" rel="noopener noreferrer"
            className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-sans font-medium bg-white hover:bg-blue-50 text-slate-600 hover:text-blue-600 border border-slate-200 shadow-2xs transition-colors"
            title={`Open Row ${partRow} in ${partSheetName}`}
        >
            {partSheetName} Row {partRow} ↗
        </a>
    ) : null;

    return (
        <span key={partnerId} className="inline-flex items-center flex-wrap gap-1 bg-amber-50/80 px-2 py-0.5 rounded-md border border-amber-200/70 text-slate-700 shadow-2xs">
            {renderPersonFocusLink(partnerId, pName, 'Click to focus partner', 'font-medium')}
            {datePart && <span className="text-[11px] text-slate-500">({datePart})</span>}
            {partRowBadge}
        </span>
    );
}

/**
 * Renders a candidate selection chip for an ambiguous relationship in the audit log.
 *
 * @param {Object} c - Candidate match descriptor
 * @param {number} cIdx - Index of candidate in list
 * @param {boolean} isUsed - Whether this candidate is currently linked in the tree
 * @param {FamilyTree} newTree - Tree domain instance
 * @param {string} startId - Default sheet ID
 * @param {Object} sheetTags - Sheet ID to display label mapping
 * @returns {React.ReactNode}
 *
 * @example
 *   _renderAmbiguityCandidatePill({ id: 'p1', name: 'Mary', sheetRow: 15 }, 0, true, tree, 's1', tags);
 *
 * @example
 *   _renderAmbiguityCandidatePill({ id: 'p2', name: 'Mary Ann', sheetRow: 22 }, 1, false, tree, 's1', tags);
 */
/**
 * Resolves candidate identity, sheet provenance, and formatted dates for ambiguity pills.
 *
 * @param {Object} c - Candidate descriptor
 * @param {Object} newTree - Tree instance containing node definitions
 * @param {string} startId - Fallback source sheet identifier
 * @param {Object} sheetTags - Mapping of sheet IDs to sheet tag display names
 * @returns {{ candName: string, cRow: (number|string|undefined), cSheetId: string, cSheetName: string, datePart: string }} Resolved candidate details
 *
 * @example
 * const res = _resolveAmbiguityCandidateDetails({ id: 'p1', name: 'John' }, tree, 's1', {});
 * // returns { candName: 'John', cRow: undefined, cSheetId: 's1', cSheetName: 'Sheet', datePart: '' }
 *
 * @example
 * const res = _resolveAmbiguityCandidateDetails({ id: 'p2', yob: 1940, sheetRow: 15 }, tree, 's1', { s1: 'Main' });
 * // returns { candName: 'Unknown', cRow: 15, cSheetId: 's1', cSheetName: 'Main', datePart: 'b. 1940' }
 */
function _resolveAmbiguityCandidateDetails(c, newTree, startId, sheetTags) {
    const candNode = newTree.get(c.id);
    const candName = c.name || candNode?.name || 'Unknown';
    const cRow = c.sheetRow || (candNode?.sheetRow < 99999 ? candNode.sheetRow : candNode?._sheetRow);
    const cSheetId = (c.sheetId && c.sheetId !== 'default') ? c.sheetId : (candNode?._sourceId || startId);
    const cSheetName = sheetTags[cSheetId] || newTree.sheetNames?.[cSheetId] || 'Sheet';
    const datePart = [
        c.yob ? `b. ${c.yob}` : (candNode?.yob ? `b. ${candNode.yob}` : ''),
        c.death ? `d. ${c.death}` : (candNode?.death ? `d. ${candNode.death}` : '')
    ].filter(Boolean).join(', ');
    return { candName, cRow, cSheetId, cSheetName, datePart };
}

/**
 * Renders an interactive candidate pill for resolving person ambiguity in the logs.
 *
 * @param {Object} c - Candidate match descriptor
 * @param {number} cIdx - Index of candidate in list
 * @param {boolean} isUsed - Whether this candidate is currently linked in the tree
 * @param {FamilyTree} newTree - Tree domain instance
 * @param {string} startId - Default sheet ID
 * @param {Object} sheetTags - Sheet ID to display label mapping
 * @returns {React.ReactNode}
 *
 * @example
 *   _renderAmbiguityCandidatePill({ id: 'p1', name: 'Mary', sheetRow: 15 }, 0, true, tree, 's1', tags);
 *
 * @example
 *   _renderAmbiguityCandidatePill({ id: 'p2', name: 'Mary Ann', sheetRow: 22 }, 1, false, tree, 's1', tags);
 */
function _renderAmbiguityCandidatePill(c, cIdx, isUsed, newTree, startId, sheetTags) {
    const { candName, cRow, cSheetId, cSheetName, datePart } =
        _resolveAmbiguityCandidateDetails(c, newTree, startId, sheetTags);

    const pillClass = isUsed
        ? "inline-flex items-center flex-wrap gap-1 bg-orange-100/90 px-2 py-0.5 rounded-md border border-orange-300 text-slate-800 shadow-2xs"
        : "inline-flex items-center flex-wrap gap-1 bg-amber-50/80 px-2 py-0.5 rounded-md border border-amber-200/70 text-slate-700";

    const cRowBadge = cRow ? (
        <a 
            href={`https://docs.google.com/spreadsheets/d/${cSheetId}/edit?gid=0#gid=0&range=${cRow}:${cRow}`}
            target="_blank" rel="noopener noreferrer"
            className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-sans font-medium bg-white hover:bg-blue-50 text-slate-600 hover:text-blue-600 border border-slate-200 shadow-2xs transition-colors"
            title={`Open Row ${cRow} in ${cSheetName}`}
        >
            {cSheetName} Row {cRow} ↗
        </a>
    ) : null;

    return (
        <span key={c.id || cIdx} className={pillClass}>
            {renderPersonFocusLink(c.id, candName, `Click to focus candidate${isUsed ? ' (currently used in tree)' : ''}`, 'font-medium')}
            {datePart && <span className="text-[11px] text-slate-500">({datePart})</span>}
            {cRowBadge}
        </span>
    );
}

/**
 * Logs details of profiles merged from duplicate spreadsheet rows into the activity log.
 *
 * @param {Array<{ p: Person, duplicatedRefs: Array<{ sheetId: string, row: number }> }>} dupes - Merged duplicate profile records.
 * @param {Object<string, string>} sheetTags - Mapping of sheet IDs to sheet tag display names.
 * @param {Function} appendLog - Logger append callback.
 *
 * @example
 * logMergedDupes(
 *     [{ p: person1, duplicatedRefs: [{ sheetId: 's1', row: 12 }] }],
 *     { s1: 'Branch A' },
 *     appendLog
 * );
 *
 * @example
 * // With empty duplicates list (no-op)
 * logMergedDupes([], {}, appendLog);
 */
function logMergedDupes(dupes, sheetTags, appendLog) {
    if (!dupes || dupes.length === 0) return;
    appendLog(`Merged duplicate row entries for ${dupes.length} profiles:`, 'info');
    dupes.forEach(({ p, duplicatedRefs }) => {
        const linkNode = renderPersonFocusLink(p.id, p.name);
        const sourceLinks = (
            <span className="inline-flex flex-wrap gap-1.5 ml-2 align-middle">
                {duplicatedRefs.map((ref, idx) => (
                    <React.Fragment key={`${ref.sheetId}-${ref.row}-${idx}`}>
                        {renderSheetRowBadge(ref.sheetId, ref.row, sheetTags[ref.sheetId] || 'Sheet', 'bg-slate-100')}
                    </React.Fragment>
                ))}
            </span>
        );
        appendLog(<span className="whitespace-normal leading-relaxed text-[12px] block mt-0.5 text-slate-600">Combined {duplicatedRefs.length} entries for {linkNode} {sourceLinks}</span>, 'info', `${p.id}-merge-log`, '  • ');
    });
}

/**
 * Sorts partner IDs in ascending chronological order by birth year and sheet row order.
 *
 * @param {Array<string>} partnerIds - Array of partner profile IDs
 * @param {FamilyTree} tree - Genealogy tree model
 * @returns {Array<string>} Sorted partner IDs
 *
 * @example
 * const sorted = sortPartnerIdsChronologically(['p2', 'p1'], tree);
 *
 * @example
 * const sorted = sortPartnerIdsChronologically([], tree);
 * // => []
 */
function sortPartnerIdsChronologically(partnerIds, tree) {
    return [...(partnerIds || [])].sort((aId, bId) => {
        const a = tree?.get(aId);
        const b = tree?.get(bId);
        const aYob = a?.yob || a?.bestYob || a?._inferredYob || 0;
        const bYob = b?.yob || b?.bestYob || b?._inferredYob || 0;
        if (aYob && bYob && aYob !== bYob) return aYob - bYob;
        const aRow = (a?.sheetRow < 99999 ? a.sheetRow : a?._sheetRow) || 0;
        const bRow = (b?.sheetRow < 99999 ? b.sheetRow : b?._sheetRow) || 0;
        return aRow - bRow;
    });
}

/**
 * Logs warnings for profiles associated with multiple partners, sorting partners chronologically by YOB or row.
 *
 * @param {Array<Object>} multiplePartners - List of multiple partner inconsistency objects.
 * @param {FamilyTree} newTree - Unified family tree instance.
 * @param {string} startId - Root sheet identifier.
 * @param {Object<string, string>} sheetTags - Mapping of sheet IDs to sheet tags.
 * @param {Function} appendLog - Logger append callback.
 *
 * @example
 * logMultiplePartnerInconsistencies(
 *     [{ p: personWithTwoPartners }],
 *     tree,
 *     'root-sheet-id',
 *     { 'root-sheet-id': 'Root' },
 *     appendLog
 * );
 *
 * @example
 * // When no multiple partners exist (no-op)
 * logMultiplePartnerInconsistencies([], tree, 'root', {}, appendLog);
 */
function logMultiplePartnerInconsistencies(multiplePartners, newTree, startId, sheetTags, appendLog) {
    if (!multiplePartners || multiplePartners.length === 0) return;
    appendLog(`Found ${multiplePartners.length} profile(s) with multiple partners:`, 'warning');
    multiplePartners.forEach((inc, idx) => {
        const linkNode = renderPersonFocusLink(inc.p.id, inc.p.name, 'Click to focus');
        const { pRowBadge } = _resolvePersonSheetBadge(inc.p, startId, sheetTags, newTree.sheetNames);
        const sortedPartners = sortPartnerIdsChronologically(inc.p.partners, newTree);
        const partnerNodes = sortedPartners.map(partnerId => 
            _renderMultiplePartnerPill(partnerId, newTree, startId, sheetTags)
        );

        appendLog(
            <span className="whitespace-normal leading-relaxed text-[12px] block mt-0.5 text-slate-700">
                {linkNode} {pRowBadge} <span className="text-slate-400 font-sans mx-1">—</span> <span className="font-medium text-slate-600">{inc.p.partners.length} partners:</span>
                <span className="inline-flex flex-wrap gap-1.5 mt-1 ml-1 align-middle">
                    {partnerNodes}
                </span>
            </span>,
            'warning',
            `multi-partner-${idx}`,
            '  • '
        );
    });
}

/**
 * Identifies the active candidate currently chosen in the tree and orders ambiguity candidates
 * with the chosen candidate placed first.
 *
 * @param {Object} amb - Ambiguity record containing candidate nodes
 * @param {Person} person - Person node for whom the ambiguity was recorded
 * @param {FamilyTree} tree - Tree instance containing person records
 * @returns {{ usedCandidate: Object, sortedCandidates: Array<Object> }}
 *
 * @example
 * _orderAmbiguityCandidates({ relation: 'father', candidates: [c1, c2] }, person, tree);
 * // => { usedCandidate: c2, sortedCandidates: [c2, c1] }
 *
 * @example
 * _orderAmbiguityCandidates({ relation: 'spouse', candidates: [c1] }, person, tree);
 * // => { usedCandidate: c1, sortedCandidates: [c1] }
 */
function _orderAmbiguityCandidates(amb, person, tree) {
    const usedCandidate = amb.candidates.find(c => FamilyTree._isCandidateUsed(c, amb, person, tree)) || amb.candidates[0];
    const sortedCandidates = usedCandidate
        ? [usedCandidate, ...amb.candidates.filter(c => c !== usedCandidate)]
        : amb.candidates;
    return { usedCandidate, sortedCandidates };
}

/**
 * Logs an ambiguity entry that contains multiple candidates with individual candidate pills.
 *
 * @param {Object} params - Ambiguity logging context
 * @param {Object} params.inc - Inconsistency record containing person and ambiguity details
 * @param {number} params.idx - Unique index of the ambiguity record
 * @param {React.ReactNode} params.linkNode - Focusable link element for the person
 * @param {React.ReactNode} params.pRowBadge - Sheet identifier badge for the person
 * @param {FamilyTree} params.newTree - Tree instance containing person records
 * @param {string} params.startId - Root spreadsheet ID
 * @param {Object} params.sheetTags - Mapping of sheet IDs to metadata
 * @param {Function} params.appendLog - Function to append formatted log entries
 *
 * @example
 * _logAmbiguityWithCandidates({ inc, idx: 0, linkNode, pRowBadge: badge, newTree: tree, startId: 's1', sheetTags: {}, appendLog });
 *
 * @example
 * _logAmbiguityWithCandidates({ inc, idx: 1, linkNode, pRowBadge: badge, newTree: tree, startId: 's2', sheetTags: {}, appendLog });
 */
function _logAmbiguityWithCandidates({ inc, idx, linkNode, pRowBadge, newTree, startId, sheetTags, appendLog }) {
    const amb = inc.amb;
    const relDesc = amb.relation ? `${amb.relation} '${amb.query || ''}'` : `'${amb.query || ''}'`;
    const { usedCandidate, sortedCandidates } = _orderAmbiguityCandidates(amb, inc.p, newTree);
    const candidateElements = sortedCandidates.map((c, cIdx) =>
        _renderAmbiguityCandidatePill(c, cIdx, c === usedCandidate, newTree, startId, sheetTags)
    );

    appendLog(
        <span className="whitespace-normal leading-relaxed text-[12px] block mt-0.5 text-slate-700">
            {linkNode} {pRowBadge} <span className="text-slate-400 font-sans mx-1">—</span> <span className="text-amber-800 font-medium">Multiple candidates for {relDesc}:</span>
            <span className="inline-flex flex-wrap gap-1.5 mt-1 ml-1 align-middle">
                {candidateElements}
            </span>
        </span>,
        'warning',
        `amb-${idx}`,
        '  • '
    );
}

/**
 * Formats and appends a single ambiguous relationship entry to the activity log.
 *
 * @param {object} inc - Inconsistency entry with person and ambiguity candidates
 * @param {number} idx - Index of the ambiguity entry
 * @param {FamilyTree} newTree - Tree instance containing person records
 * @param {string} startId - Root spreadsheet ID
 * @param {object} sheetTags - Mapping of sheet IDs to metadata
 * @param {function} appendLog - Function to append formatted log entries
 *
 * @example
 * logSingleAmbiguity({ p: { id: 'p1', name: 'John' }, text: 'Ambiguous' }, 0, tree, 's1', {}, appendLog);
 *
 * @example
 * logSingleAmbiguity({ p: { id: 'p2', name: 'Mary' }, amb: { relation: 'father', candidates: [] } }, 1, tree, 's1', {}, appendLog);
 */
function logSingleAmbiguity(inc, idx, newTree, startId, sheetTags, appendLog) {
    const linkNode = renderPersonFocusLink(inc.p.id, inc.p.name, 'Click to focus');
    const { pRowBadge } = _resolvePersonSheetBadge(inc.p, startId, sheetTags, newTree.sheetNames);

    if (inc.amb && inc.amb.candidates && inc.amb.candidates.length > 0) {
        _logAmbiguityWithCandidates({ inc, idx, linkNode, pRowBadge, newTree, startId, sheetTags, appendLog });
    } else {
        const rawText = inc.text || '';
        appendLog(
            <span className="whitespace-normal leading-relaxed text-[12px] block mt-0.5 text-slate-700">
                {linkNode} {pRowBadge} <span className="text-slate-400 font-sans mx-1">—</span> {rawText}
            </span>,
            inc.type,
            `amb-${idx}`,
            '  • '
        );
    }
}

/**
 * Logs warnings for ambiguous parent or spouse relationships with multiple candidate choices.
 *
 * @param {Array<Object>} ambiguities - List of ambiguity inconsistency records.
 * @param {FamilyTree} newTree - Unified family tree instance.
 * @param {string} startId - Root sheet identifier.
 * @param {Object<string, string>} sheetTags - Mapping of sheet IDs to sheet tags.
 * @param {Function} appendLog - Logger append callback.
 *
 * @example
 * logAmbiguityInconsistencies(
 *     [{ p: childNode, amb: { relation: 'Father', query: 'John', candidates: [c1, c2] } }],
 *     tree,
 *     'root-sheet-id',
 *     { 'root-sheet-id': 'Root' },
 *     appendLog
 * );
 *
 * @example
 * // When no ambiguities exist (no-op)
 * logAmbiguityInconsistencies([], tree, 'root', {}, appendLog);
 */
function logAmbiguityInconsistencies(ambiguities, newTree, startId, sheetTags, appendLog) {
    if (!ambiguities || ambiguities.length === 0) return;
    appendLog(`Found ${ambiguities.length} ambiguous relationship(s):`, 'warning');
    ambiguities.forEach((inc, idx) => {
        logSingleAmbiguity(inc, idx, newTree, startId, sheetTags, appendLog);
    });
}

/**
 * Appends a grouped list of audit inconsistencies to the activity log with formatted labels.
 *
 * @param {object} params
 * @param {Array<object>} params.items - Inconsistency items belonging to this category
 * @param {string} params.headerMsg - Header summary message to log
 * @param {string} [params.logType] - Log level ('error' | 'warning' | 'info')
 * @param {string} params.keyPrefix - Unique key prefix for log item tracking
 * @param {string} params.colorClass - CSS text color class for item display
 * @param {Function} [params.textFormatter] - Custom formatter returning a string or JSX node
 * @param {string} params.startId - Root spreadsheet identifier
 * @param {object} params.sheetTags - Sheet tags dictionary
 * @param {object} params.sheetNames - Sheet names dictionary
 * @param {Function} params.appendLog - Logger append callback
 *
 * @example
 * _logInconsistencyGroup({
 *   items: [{ text: 'Invalid YOB', type: 'error' }],
 *   headerMsg: 'Found 1 critical error:',
 *   logType: 'error',
 *   keyPrefix: 'err',
 *   colorClass: 'text-red-700',
 *   startId: 'sheet1',
 *   sheetTags: {},
 *   sheetNames: {},
 *   appendLog: (msg, type) => console.log(type, msg)
 * });
 *
 * @example
 * // No-op when items is empty
 * _logInconsistencyGroup({ items: [], headerMsg: 'None', appendLog: () => {} });
 */
function _logInconsistencyGroup({
    items,
    headerMsg,
    logType,
    keyPrefix,
    colorClass,
    textFormatter,
    startId,
    sheetTags,
    sheetNames,
    appendLog
}) {
    if (!items || items.length === 0) return;
    appendLog(headerMsg, logType);
    items.forEach((inc, idx) => {
        const textContent = textFormatter ? textFormatter(inc) : inc.text;
        appendLog(
            _renderAuditInconsistencyItem(inc, startId, sheetTags, sheetNames, colorClass, textContent),
            logType || inc.type,
            `${keyPrefix}-${idx}`,
            '  • '
        );
    });
}

/**
 * Logs partitioned non-ambiguity audit warnings and errors (critical errors, unresolved spreadsheet claims,
 * chronological/biological warnings, and near-duplicate spelling warnings).
 *
 * @param {Array<Object>} otherInconsistencies - Filtered inconsistency records.
 * @param {string} startId - Root sheet identifier.
 * @param {Object<string, string>} sheetTags - Mapping of sheet IDs to sheet tags.
 * @param {FamilyTree} newTree - Unified family tree instance.
 * @param {Function} appendLog - Logger append callback.
 *
 * @example
 * logCategorizedAuditInconsistencies(
 *     [
 *         { type: 'error', text: 'Parent younger than child', p: node1 },
 *         { category: 'spelling', text: "Spelling 'Annu' is almost the same as 'Anu'", p: node2 }
 *     ],
 *     'root',
 *     { root: 'Root' },
 *     tree,
 *     appendLog
 * );
 *
 * @example
 * // With clean tree (no-op)
 * logCategorizedAuditInconsistencies([], 'root', {}, tree, appendLog);
 */
function logCategorizedAuditInconsistencies(otherInconsistencies, startId, sheetTags, newTree, appendLog) {
    if (!otherInconsistencies || otherInconsistencies.length === 0) return;

    const criticalErrors = otherInconsistencies.filter(inc => inc.type === 'error');
    const unresolvedClaims = otherInconsistencies.filter(inc => inc.category === 'unresolved_claim');
    const spellingWarnings = otherInconsistencies.filter(inc => inc.category === 'spelling');
    const bioWarnings = otherInconsistencies.filter(inc => inc.type !== 'error' && inc.category !== 'unresolved_claim' && inc.category !== 'spelling');

    const baseParams = { startId, sheetTags, sheetNames: newTree.sheetNames, appendLog };
    const amberFmt = inc => <span className="text-amber-800 font-medium">{inc.text}</span>;
    const groups = [
        { items: criticalErrors, headerMsg: `Found ${criticalErrors.length} critical data error(s):`, logType: 'error', keyPrefix: 'err-inc', colorClass: 'text-red-700', textFormatter: inc => <span className="font-semibold text-red-800">{inc.text}</span> },
        { items: unresolvedClaims, headerMsg: `Found ${unresolvedClaims.length} unresolved spreadsheet claim(s):`, logType: 'warning', keyPrefix: 'unresolved-claim', colorClass: 'text-slate-700', textFormatter: amberFmt },
        { items: bioWarnings, headerMsg: `Found ${bioWarnings.length} chronological/biological warning(s):`, logType: 'warning', keyPrefix: 'bio-warn', colorClass: 'text-slate-700', textFormatter: inc => inc.text },
        { items: spellingWarnings, headerMsg: `Found ${spellingWarnings.length} spelling warning(s):`, logType: 'warning', keyPrefix: 'spell-warn', colorClass: 'text-slate-700', textFormatter: amberFmt },
    ];
    groups.forEach(g => _logInconsistencyGroup({ ...baseParams, ...g }));
}

/**
 * Logs warnings for unreachable or disconnected subtrees in the activity log with their root name, YOB, and size.
 *
 * @param {Array<{ root: Person, size: number }>} subtrees - Array of unreachable subtree descriptor objects.
 * @param {Function} appendLog - Logger append callback.
 *
 * @example
 * logDisconnectedSubtrees(
 *     [{ root: orphanRootNode, size: 3 }],
 *     appendLog
 * );
 *
 * @example
 * // When no disconnected subtrees exist (no-op)
 * logDisconnectedSubtrees([], appendLog);
 */
function logDisconnectedSubtrees(subtrees, appendLog) {
    if (!subtrees || subtrees.length === 0) return;
    appendLog(`Found ${subtrees.length} disconnected subtree(s):`, 'warning');
    subtrees.forEach((rt, idx) => {
        const linkNode = renderPersonFocusLink(rt.root.id, rt.root.name);
        const yearStr = rt.root.yob ? `b. ${rt.root.yob}` : 'Unknown year';
        const sizeStr = `${rt.size} ${rt.size === 1 ? 'person' : 'people'}`;
        appendLog(<span className="whitespace-normal leading-relaxed text-[11.5px] block mt-0.5 text-slate-600">{linkNode} <span className="text-slate-400 font-sans mx-1">—</span> {yearStr} <span className="text-slate-400 font-sans mx-1">—</span> <b>{sizeStr}</b></span>, 'warning', `unreachable-${idx}`, '  • ');
    });
}

/**
 * Logs the comprehensive validation, audit, and diagnostic results of a built family tree,
 * formatting timing metrics, merged duplicates, partner counts, relationship ambiguities,
 * biological inconsistencies, and disconnected subtrees into interactive UI log entries.
 *
 * @param {Object} params
 * @param {FamilyTree} params.newTree - Built tree instance
 * @param {string} params.startId - Root Google Sheet ID
 * @param {Object<string, string>} params.sheetTags - Sheet ID to display name mapping
 * @param {Function} params.appendLog - Logger append callback
 * @param {number} params.allRowsCount - Total rows parsed across all sheets
 * @param {number} params.visitedCount - Total sheets loaded
 * @param {Object} params.timing - Timing metrics { fetchTimeSec, buildTimeMs, totalTimeSec }
 *
 * @example
 * logTreeAuditResults({
 *     newTree: tree,
 *     startId: 'sheet1',
 *     sheetTags: { sheet1: 'Root' },
 *     appendLog: (msg, type) => {},
 *     allRowsCount: 50,
 *     visitedCount: 1,
 *     timing: { fetchTimeSec: '0.45', buildTimeMs: 15, totalTimeSec: '0.47' }
 * });
 *
 * @example
 * // With multiple sheets and clean tree
 * logTreeAuditResults({
 *     newTree: cleanTree,
 *     startId: 'root',
 *     sheetTags: { root: 'Root', branch1: 'Branch' },
 *     appendLog,
 *     allRowsCount: 120,
 *     visitedCount: 2,
 *     timing: { fetchTimeSec: '1.20', buildTimeMs: 25, totalTimeSec: '1.23' }
 * });
 */
function logTreeAuditResults({ newTree, startId, sheetTags, appendLog, allRowsCount, visitedCount, timing }) {
    const { inconsistencies, dupes, subtrees } = newTree.audit();
    const { fetchTimeSec, buildTimeMs, totalTimeSec } = timing;

    // Log exact timing breakdown
    appendLog(
        <span>⏱️ <b>Fetch time:</b> {fetchTimeSec}s ({visitedCount} sheets) | <b>Build time:</b> {buildTimeMs}ms ({allRowsCount} profiles) | <b>Total:</b> {totalTimeSec}s</span>, 
        'success'
    );
    appendLog(`Family Tree loaded successfully (${allRowsCount} profiles, ${visitedCount} sheets)!`, 'success');

    logMergedDupes(dupes, sheetTags, appendLog);

    if (inconsistencies.length > 0) {
        const ambiguities = inconsistencies.filter(inc => inc.category === 'ambiguity' || inc.text?.startsWith('Ambiguity:'));
        const multiplePartners = inconsistencies.filter(inc => inc.category === 'multiple_partners' || inc.text?.includes('Has multiple partners'));
        const otherInconsistencies = inconsistencies.filter(inc => !ambiguities.includes(inc) && !multiplePartners.includes(inc));

        logMultiplePartnerInconsistencies(multiplePartners, newTree, startId, sheetTags, appendLog);
        logAmbiguityInconsistencies(ambiguities, newTree, startId, sheetTags, appendLog);
        logCategorizedAuditInconsistencies(otherInconsistencies, startId, sheetTags, newTree, appendLog);
    } else {
        appendLog(`Tree audit passed. No chronological inconsistencies found.`, 'success');
    }

    logDisconnectedSubtrees(subtrees, appendLog);
}

/**
 * Computes a deterministic string fingerprint of parsed spreadsheet rows to detect data changes.
 *
 * @param {Array<Object>} rows - Parsed genealogical rows
 * @returns {string} Semicolon- and pipe-delimited normalized fingerprint
 *
 * @example
 * computeDataFingerprint([{ name: 'Alice', gender: 'F' }])
 * // => 'gender:F;name:Alice'
 *
 * @example
 * computeDataFingerprint([])
 * // => ''
 */
function computeDataFingerprint(rows) {
    if (!rows || rows.length === 0) return '';
    return rows.map(r => {
        const entries = Object.entries(r).sort(([a], [b]) => a.localeCompare(b));
        return entries.map(([k, v]) => `${k}:${String(v != null ? v : '').trim()}`).join(';');
    }).join('|');
}

/**
 * Fetches CSV text for a specific Google Sheet tab with timeout and fallback to GViz.
 *
 * @param {string} sheetId - Google Sheets document ID
 * @param {string} [sheetName=''] - Tab/sheet name (e.g. 'Links' or 'Data')
 * @param {number} [timeoutMs=6000] - Request timeout in milliseconds
 * @param {boolean} [bypassCache=false] - Whether to bypass browser cache
 * @returns {Promise<string|null>} CSV text or null if failed
 *
 * @example
 * const csv = await fetchCSVData('1abc...', 'Links', 5000);
 *
 * @example
 * const defaultCsv = await fetchCSVData('1abc...', '', 8000, true);
 */
async function fetchCSVData(sheetId, sheetName = '', timeoutMs = 8000, bypassCache = false) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    const url = buildGoogleSheetCsvUrl(sheetId, sheetName, bypassCache);
    try {
        const fetchOptions = { signal: controller.signal };
        if (bypassCache) {
            fetchOptions.cache = 'no-store';
        }
        const response = await fetch(url, fetchOptions);
        clearTimeout(timeoutId);
        if (!response.ok) {
            return sheetName ? null : fetchFallbackGvizCsv(sheetId, bypassCache, timeoutMs);
        }
        const text = await response.text();
        if (!text || text.trim().startsWith('<html')) {
            return sheetName ? null : fetchFallbackGvizCsv(sheetId, bypassCache, timeoutMs);
        }
        return text;
    } catch (err) {
        clearTimeout(timeoutId);
        if (!sheetName) {
            return fetchFallbackGvizCsv(sheetId, bypassCache, timeoutMs);
        }
        return null;
    }
}

/**
 * Extracts linked Google Spreadsheet IDs and optional display labels from CSV text.
 *
 * @param {string} text - Raw CSV text
 * @param {string} currentSheetId - ID of current sheet to avoid self-linking
 * @returns {Array<{ id: string, tag: string|null }>} List of extracted sheet links
 *
 * @example
 * extractLinkedSheetIds('"Chalissery",https://docs.google.com/spreadsheets/d/1abc12345678901234567890123456789012345/edit', 'curr')
 * // => [{ id: '1abc12345678901234567890123456789012345', tag: 'Chalissery' }]
 *
 * @example
 * extractLinkedSheetIds('', 'curr')
 * // => []
 */
function extractLinkedSheetIds(text, currentSheetId) {
    if (!text) return [];
    const foundLinks = [];
    const lines = text.split('\n').filter(l => l.trim().length > 0);
    for (const line of lines) {
        const idMatches = [...line.matchAll(/[a-zA-Z0-9-_]{35,60}/g)].map(m => m[0]);
        for (const match of idMatches) {
            if (match !== currentSheetId && !foundLinks.some(l => l.id === match)) {
                const firstColMatch = line.match(/^(?:"([^"]*)"|([^,]*))/);
                const firstCol = firstColMatch ? (firstColMatch[1] || firstColMatch[2] || '').trim() : '';
                const tag = (firstCol && !firstCol.includes('http') && !firstCol.match(/[a-zA-Z0-9-_]{35,60}/)) ? firstCol : null;
                foundLinks.push({ id: match, tag });
            }
        }
    }
    return foundLinks;
}

/**
 * Extracts and parses genealogical profile rows from CSV text by detecting header columns.
 *
 * @param {string} text - Raw CSV text from sheet
 * @param {string} currentSheetId - Source Google Sheet ID
 * @returns {Array<Object>} Parsed data rows with _sourceId and _sheetRow metadata
 *
 * @example
 * extractGenealogicalRows('Name,Gender,Father\nThomas,M,Ouseph', 'sheet1')
 * // => [{ name: 'Thomas', gender: 'M', father: 'Ouseph', _sourceId: 'sheet1', _sheetRow: 2, ... }]
 *
 * @example
 * extractGenealogicalRows('', 'sheet1')
 * // => []
 */
function extractGenealogicalRows(text, currentSheetId) {
    if (!text) return [];

    // Fast path: parse directly with CSVParser if headers match, avoiding slicing across multi-line quoted cells
    if (hasGenealogicalHeaders(text)) {
        try {
            const parsed = CSVParser.parse(text);
            if (parsed.length > 0 && hasGenealogicalHeaders(Object.keys(parsed[0]).join(','))) {
                return tagParsedRowMetadata(parsed, currentSheetId, 0, 2);
            }
        } catch (_) {}
    }

    const rawLines = text.split('\n');
    const lines = rawLines.filter(l => l.trim().length > 0);

    for (let i = 0; i < Math.min(lines.length, 15); i++) {
        if (hasGenealogicalHeaders(lines[i])) {
            const rawIndex = rawLines.indexOf(lines[i]);
            const parsed = CSVParser.parse(rawLines.slice(rawIndex).join('\n'));
            if (parsed.length > 0) {
                return tagParsedRowMetadata(parsed, currentSheetId, rawIndex, i + 2);
            }
        }
    }
    return [];
}

/**
 * Tags sheet source identifier and serializes initial sheet row tracking on parsed CSV rows.
 *
 * @param {Array<Object>} rows - Parsed CSV row objects.
 * @param {string} sheetId - Spreadsheet identifier.
 * @param {number} [rowOffset=0] - Additional offset to add to parsed _sheetRow.
 * @param {number} [defaultRowFallback=2] - Fallback row number if row has no _sheetRow.
 * @returns {Array<Object>} The mutated rows array.
 *
 * @example
 * tagParsedRowMetadata([{ _sheetRow: 3 }], 'sheet1', 10, 2);
 * // => [{ _sourceId: 'sheet1', _sheetRow: 13, _sheetRows: '{"sheet1":13}' }]
 *
 * @example
 * tagParsedRowMetadata([{ name: 'John' }], 'sheet2', 0, 5);
 * // => [{ name: 'John', _sourceId: 'sheet2', _sheetRow: 5, _sheetRows: '{"sheet2":5}' }]
 */
function tagParsedRowMetadata(rows, sheetId, rowOffset = 0, defaultRowFallback = 2) {
    rows.forEach(r => {
        r._sourceId = sheetId;
        if (rowOffset > 0) {
            r._sheetRow = (r._sheetRow || 0) + rowOffset;
        }
        if (!r._sheetRows) {
            const sheetRows = {};
            sheetRows[r._sourceId || 'default'] = r._sheetRow || defaultRowFallback;
            r._sheetRows = JSON.stringify(sheetRows);
        }
    });
    return rows;
}

/**
 * Probes primary and fallback tabs of a Google Sheet in parallel, extracting data rows and outgoing links.
 *
 * @param {string} sheetId - Google Sheets document ID
 * @param {boolean} [bypassCache=false] - Whether to bypass HTTP cache
 * @param {string} [sheetTag=''] - Optional branch sheet tag name to probe as tab
 * @returns {Promise<{ sheetId: string, rows: Array<Object>, links: Array<{ id: string, tag: string|null }>, extractedCount: number }>}
 *
 * @example
 * const res = await fetchSingleSheetParallel('1abc...', false);
 * // => { sheetId: '1abc...', rows: [...], links: [...], extractedCount: 50 }
 *
 * @example
 * const resWithTag = await fetchSingleSheetParallel('1abc...', true, 'Branch');
 * // => { sheetId: '1abc...', rows: [...], links: [...], extractedCount: 20 }
 */
async function fetchSingleSheetParallel(sheetId, bypassCache = false, sheetTag = '') {
    // Fast probe: check default tab and 'Links' in parallel first
    const primaryTabs = ['', 'Links'];
    const primaryResults = await Promise.all(primaryTabs.map(async tab => {
        const text = await fetchCSVData(sheetId, tab, 8000, bypassCache);
        return { tab, text };
    }));

    let tabResults = [...primaryResults];

    const hasDataInPrimary = primaryResults.some(({ text }) => hasGenealogicalHeaders(text));

    // If no data rows found in primary tabs, probe fallback tabs in parallel
    if (!hasDataInPrimary) {
        const cleanTag = sheetTag && !['Root sheet', 'Data sheet'].includes(sheetTag) ? sheetTag.trim() : '';
        const fallbackTabs = ['Data', 'Family', 'Sheet1'];
        if (cleanTag && !fallbackTabs.includes(cleanTag)) {
            fallbackTabs.unshift(cleanTag);
        }
        const fallbackResults = await Promise.all(fallbackTabs.map(async tab => {
            const text = await fetchCSVData(sheetId, tab, 8000, bypassCache);
            return { tab, text };
        }));
        tabResults = [...tabResults, ...fallbackResults];
    }

    const { rows, links, extractedCount } = processFetchedTabResults(tabResults, sheetId);
    return { sheetId, rows, links, extractedCount };
}

/**
 * Processes fetched CSV tab contents, extracting unique outgoing sheet links
 * and first available genealogical data rows.
 *
 * @example
 * processFetchedTabResults([{ tab: '', text: 'ID,Name\n1,John' }], 'sheet123');
 * // => { rows: [...], links: [], extractedCount: 1 }
 *
 * @example
 * processFetchedTabResults([], 'sheet123');
 * // => { rows: [], links: [], extractedCount: 0 }
 *
 * @param {Array<{ tab: string, text: string }>} tabResults - Fetched tab outputs
 * @param {string} sheetId - Current sheet identifier
 * @returns {{ rows: Array<Object>, links: Array<{ id: string, tag: string|null }>, extractedCount: number }}
 */
function processFetchedTabResults(tabResults, sheetId) {
    let rows = [];
    const links = [];
    let extractedCount = 0;

    for (const { tab, text } of tabResults) {
        if (!text) continue;

        const tabLinks = extractLinkedSheetIds(text, sheetId);
        for (const tl of tabLinks) {
            if (!links.some(l => l.id === tl.id)) links.push(tl);
        }

        if (rows.length === 0) {
            const parsedRows = extractGenealogicalRows(text, sheetId);
            if (parsedRows.length > 0) {
                rows = parsedRows;
                extractedCount = parsedRows.length;
            }
        }
    }

    return { rows, links, extractedCount };
}

/**
 * Extracts a Google Spreadsheet ID token (35-60 alphanumeric characters with hyphens or underscores)
 * from a given URL or raw identifier string.
 *
 * @param {string} url - Input Google Sheets URL or raw sheet ID string.
 * @returns {string|null} Extracted spreadsheet ID string, or null if invalid.
 *
 * @example
 * extractSheetIdFromUrl("https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms/edit");
 * // => "1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms"
 *
 * @example
 * extractSheetIdFromUrl("invalid-short-url");
 * // => null
 */
function extractSheetIdFromUrl(url) {
    if (!url) return null;
    const match = url.match(/[a-zA-Z0-9-_]{35,60}/);
    return match ? match[0] : null;
}

/**
 * Attempts to load and construct a family tree instance from the local TreeDataCache for instant first paint.
 *
 * @param {string} sheetUrl - Target spreadsheet URL.
 * @param {Function} appendLog - Callback to append log messages.
 * @returns {FamilyTree|null} Cached tree instance, or null if not cached or construction fails.
 *
 * @example
 * const cached = loadTreeFromCache("https://docs.google.com/spreadsheets/d/1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms", appendLog);
 *
 * @example
 * const noCache = loadTreeFromCache("https://invalid-url", appendLog);
 * // => null
 */
function loadTreeFromCache(sheetUrl, appendLog) {
    const tCacheStart = performance.now();
    const cached = TreeDataCache.get(sheetUrl);
    if (cached && cached.rows && cached.rows.length > 0) {
        try {
            const cachedBuilder = new FamilyTreeBuilder(cached.rows, cached.sheetTags || {});
            const cachedTree = cachedBuilder.build();
            const cacheDurationMs = Math.round(performance.now() - tCacheStart);
            appendLog(<span>⚡ Loaded <b>{cached.rows.length} profiles</b> instantly from cache in <b>{cacheDurationMs}ms</b>. Synchronizing live data in background...</span>, 'info');
            return cachedTree;
        } catch (e) {
            console.log("Cached tree build failed:", e);
        }
    }
    return null;
}

/**
 * Registers unvisited linked sheet IDs into the sheet tree node and tags mapping.
 *
 * @param {Array<{ id: string, tag?: string }>} links - Newly discovered links.
 * @param {Set<string>} visited - Set of visited sheet IDs.
 * @param {Object} sheetTags - Target map of sheet IDs to tags.
 * @param {Object} parentNode - The parent tree node to attach child sheet descriptors to.
 *
 * @example
 * registerUnvisitedSheetLinks([{ id: 'sheet-2', tag: 'Spouse sheet' }], visited, sheetTags, rootTreeNode);
 *
 * @example
 * registerUnvisitedSheetLinks([], visited, sheetTags, rootTreeNode);
 */
function registerUnvisitedSheetLinks(links, visited, sheetTags, parentNode) {
    const unvisitedLinks = links.filter(l => !visited.has(l.id));
    unvisitedLinks.forEach(l => {
        visited.add(l.id);
        const tag = l.tag || 'Data sheet';
        sheetTags[l.id] = tag;
        parentNode.children.push({
            id: l.id,
            tag,
            status: 'loading',
            count: 0,
            children: []
        });
    });
}

/**
 * Builds and sets an initial preliminary tree if streaming root rows without cache.
 *
 * @param {Array<Object>} rows - Current accumulated rows.
 * @param {Object} sheetTags - Mapping of sheet IDs to tags.
 * @param {Function} setTree - State setter for the family tree.
 *
 * @example
 * renderPreliminaryRootTree(allRows, sheetTags, setTree);
 *
 * @example
 * renderPreliminaryRootTree([], {}, setTree);
 */
function renderPreliminaryRootTree(rows, sheetTags, setTree) {
    try {
        const tempBuilder = new FamilyTreeBuilder(rows, sheetTags);
        const tempTree = tempBuilder.build();
        setTree(tempTree);
    } catch (e) {}
}

/**
 * Updates node status, registers unvisited sheet links, and invokes preliminary root callback.
 *
 * @param {object} params - Parameters object.
 * @param {object} params.node - Target sheet node.
 * @param {object} params.res - Sheet fetch result.
 * @param {boolean} params.isRoot - Whether node is root sheet.
 * @param {Set<string>} params.visited - Visited sheet IDs set.
 * @param {object} params.sheetTags - Sheet tags lookup map.
 * @param {boolean} params.background - Whether running in background.
 * @param {boolean} params.hasLoadedFromCache - Whether loaded from cache.
 * @param {Function|null} params.onPreliminaryRoot - Preliminary callback.
 * @param {Array<object>} params.allRows - Accumulated row objects.
 *
 * @example
 * handleSheetNodeResults({
 *   node: { id: 's1', count: 0 },
 *   res: { extractedCount: 10, links: [] },
 *   isRoot: true,
 *   visited: new Set(['s1']),
 *   sheetTags: {},
 *   background: false,
 *   hasLoadedFromCache: false,
 *   onPreliminaryRoot: () => {},
 *   allRows: []
 * });
 *
 * @example
 * handleSheetNodeResults({
 *   node: { id: 's2', count: 0 },
 *   res: { extractedCount: 0, links: [] },
 *   isRoot: false,
 *   visited: new Set(),
 *   sheetTags: {},
 *   background: true,
 *   hasLoadedFromCache: true,
 *   onPreliminaryRoot: null,
 *   allRows: []
 * });
 */
function handleSheetNodeResults({
    node, res, isRoot, visited, sheetTags, background, hasLoadedFromCache, onPreliminaryRoot, allRows
}) {
    node.count = res.extractedCount;
    node.status = res.extractedCount > 0 ? 'success' : 'warning';
    if (!background && !hasLoadedFromCache && isRoot && allRows.length > 0 && onPreliminaryRoot) {
        onPreliminaryRoot(allRows);
    }
    registerUnvisitedSheetLinks(res.links, visited, sheetTags, node);
}

/**
 * Crawls a tree of linked Google Sheets starting from rootTreeNode, loading and aggregating all rows.
 *
 * Traverses sheet nodes recursively, fetching sheets in parallel, registering
 * extracted child links into the tree, and reporting progress via onRefreshTreeInLogs.
 *
 * @param {Object} options - Configuration options for crawling linked spreadsheets
 * @param {Object} options.rootTreeNode - Root sheet tree node with id and children array
 * @param {Set<string>} options.visited - Set of visited sheet IDs to avoid cycles
 * @param {Object} options.sheetTags - Map from sheet ID to sheet display tag/name
 * @param {boolean} [options.skipCache=false] - Whether to bypass local cache
 * @param {boolean} [options.background=false] - Whether this is a silent background sync
 * @param {boolean} [options.hasLoadedFromCache=false] - Whether preliminary cache data was loaded
 * @param {Function} [options.onPreliminaryRoot] - Callback invoked with root rows for preliminary tree render
 * @param {Function} [options.onRefreshTreeInLogs] - Callback to update the live tree representation in logs
 * @returns {Promise<Array<Object>>} Aggregated raw row objects across all traversed sheets
 *
 * @example
 * const rows = await crawlLinkedSpreadsheets({
 *   rootTreeNode: { id: 'root', tag: 'Main', children: [] },
 *   visited: new Set(),
 *   sheetTags: { root: 'Main' }
 * });
 *
 * @example
 * const rows = await crawlLinkedSpreadsheets({
 *   rootTreeNode: { id: 'sheet2', tag: 'Sub', children: [] },
 *   visited: new Set(),
 *   sheetTags: { sheet2: 'Sub' },
 *   skipCache: true,
 *   background: false
 * });
 */
async function crawlLinkedSpreadsheets(options) {
    const {
        rootTreeNode, visited, sheetTags, skipCache = false, background = false,
        hasLoadedFromCache = false, onPreliminaryRoot = null, onRefreshTreeInLogs = null
    } = options;
    let allRows = [];

    const processSheetNode = async (node, isRoot = false) => {
        visited.add(node.id);
        node.status = 'loading';
        if (onRefreshTreeInLogs) onRefreshTreeInLogs();

        let res = await fetchSingleSheetParallel(node.id, background || skipCache, node.tag);
        if (!isRoot && res.extractedCount === 0 && res.links.length === 0) {
            const retryRes = await fetchSingleSheetParallel(node.id, true, node.tag);
            if (retryRes.extractedCount > 0 || retryRes.links.length > 0) {
                res = retryRes;
            }
        }

        if (res.rows && res.rows.length > 0) allRows = [...allRows, ...res.rows];
        handleSheetNodeResults({
            node, res, isRoot, visited, sheetTags, background, hasLoadedFromCache, onPreliminaryRoot, allRows
        });
        if (onRefreshTreeInLogs) onRefreshTreeInLogs();

        if (node.children.length > 0) {
            await Promise.all(node.children.map(child => processSheetNode(child, false)));
        }
        if (onRefreshTreeInLogs) onRefreshTreeInLogs();
    };

    await processSheetNode(rootTreeNode, true);
    return allRows;
}

/**
 * Manages application activity logs, including entry formatting, timestamps, and live log updates.
 *
 * @returns {{
 *   logs: Array<Object>,
 *   setLogs: React.Dispatch<React.SetStateAction<Array<Object>>>,
 *   appendLog: Function,
 *   updateLog: Function
 * }}
 *
 * @example
 * const { logs, appendLog, updateLog } = useAppLogs();
 * appendLog("Loaded dataset", "success");
 *
 * @example
 * const { logs, setLogs } = useAppLogs();
 */
function useAppLogs() {
    const [logs, setLogs] = useState([]);

    const appendLog = useCallback((msg, type = 'info', id = null, prefix = '') => {
        const logId = id || Date.now() + Math.random().toString();
        setLogs(prev => [...prev, { id: logId, time: new Date().toLocaleTimeString([], { hour12: false }), msg, type, prefix }]);
        return logId;
    }, []);

    const updateLog = useCallback((id, msg, type = 'info') => {
        setLogs(prev => prev.map(log => log.id === id ? { ...log, msg, type } : log));
    }, []);

    return { logs, setLogs, appendLog, updateLog };
}

/**
 * Applies a newly constructed family tree model to state, handling background updates,
 * focus reset, and logging of validation/audit metrics.
 *
 * @param {Object} params
 * @param {FamilyTree} params.newTree - The freshly built family tree instance
 * @param {boolean} params.background - Whether this update was run as a background revalidation
 * @param {Function|null} params.onBackgroundUpdate - Optional callback for custom background updates
 * @param {Function} params.setTree - State setter for the active tree
 * @param {Function} params.setFocusId - State setter for the active person focus
 * @param {string} params.startId - Root sheet identifier
 * @param {Object} params.sheetTags - Map of sheet IDs to human-readable names
 * @param {Function} params.appendLog - Activity logger function
 * @param {number} params.allRowsCount - Total rows parsed across all sheets
 * @param {number} params.visitedCount - Total number of sheets visited
 * @param {{ fetchTimeSec: string, buildTimeMs: number, totalTimeSec: string }} params.timing - Fetch and build performance metrics
 * @returns {void}
 *
 * @example
 * applyConstructedTree({
 *   newTree: treeInstance,
 *   background: false,
 *   onBackgroundUpdate: null,
 *   setTree,
 *   setFocusId,
 *   startId: 'sheet-123',
 *   sheetTags: { 'sheet-123': 'Root sheet' },
 *   appendLog: (msg, type) => console.log(msg),
 *   allRowsCount: 150,
 *   visitedCount: 1,
 *   timing: { fetchTimeSec: '0.45', buildTimeMs: 12, totalTimeSec: '0.46' }
 * });
 *
 * @example
 * applyConstructedTree({
 *   newTree: treeInstance,
 *   background: true,
 *   onBackgroundUpdate: (t) => console.log('Updated', t),
 *   setTree,
 *   setFocusId,
 *   startId: 'sheet-123',
 *   sheetTags: {},
 *   appendLog: () => {},
 *   allRowsCount: 0,
 *   visitedCount: 1,
 *   timing: { fetchTimeSec: '0.1', buildTimeMs: 2, totalTimeSec: '0.1' }
 * });
 */
function applyConstructedTree({
    newTree, background, onBackgroundUpdate, setTree, setFocusId,
    startId, sheetTags, appendLog, allRowsCount, visitedCount, timing
}) {
    if (background) {
        if (typeof onBackgroundUpdate === 'function') {
            onBackgroundUpdate(newTree);
        } else {
            setTree(prev => {
                if (prev?.rootId && newTree.get(prev.rootId)) {
                    newTree.rootId = prev.rootId;
                }
                return newTree;
            });
            setFocusId(prev => (prev && newTree.get(prev) ? prev : null));
        }
    } else {
        setTree(newTree);
        setFocusId(null);
        logTreeAuditResults({
            newTree, startId, sheetTags, appendLog,
            allRowsCount, visitedCount, timing
        });
    }
}

/**
 * Coordinates recursive discovery and parallel crawling of linked spreadsheet trees,
 * reporting real-time hierarchical progress into the audit logs.
 *
 * @param {Object} options
 * @param {string} options.startId - Root sheet identifier
 * @param {boolean} options.skipCache - Whether to bypass local storage cache
 * @param {boolean} options.background - Whether run is an unobtrusive background refresh
 * @param {boolean} options.hasLoadedFromCache - Whether initial data came from cache
 * @param {Function} options.setLogs - State setter for audit logs
 * @param {Function} options.setTree - State setter for preliminary tree updates
 * @returns {Promise<{ allRows: Array<Object>, visited: Set<string>, sheetTags: Object }>}
 *
 * @example
 * const { allRows, visited, sheetTags } = await executeSpreadsheetCrawl({
 *   startId: 'sheet1',
 *   skipCache: false,
 *   background: false,
 *   hasLoadedFromCache: false,
 *   setLogs: () => {},
 *   setTree: () => {}
 * });
 *
 * @example
 * const { allRows } = await executeSpreadsheetCrawl({
 *   startId: 'sheetRoot',
 *   skipCache: true,
 *   background: true,
 *   hasLoadedFromCache: true,
 *   setLogs: setLogState,
 *   setTree: setTreeState
 * });
 */
async function executeSpreadsheetCrawl({
    startId, skipCache, background, hasLoadedFromCache, setLogs, setTree
}) {
    const visited = new Set();
    const sheetTags = { [startId]: 'Root sheet' };
    const rootTreeNode = { id: startId, tag: 'Root sheet', status: 'loading', count: 0, children: [] };

    const refreshTreeInLogs = () => {
        if (background) return;
        const lines = flattenSheetTree(rootTreeNode);
        setLogs(prev => mergeTreeLogEntries(prev, buildSheetTreeLogItems(lines)));
    };

    const allRows = await crawlLinkedSpreadsheets({
        rootTreeNode, visited, sheetTags, skipCache, background, hasLoadedFromCache,
        onPreliminaryRoot: (rootRows) => renderPreliminaryRootTree(rootRows, sheetTags, setTree),
        onRefreshTreeInLogs: refreshTreeInLogs
    });
    return { allRows, visited, sheetTags };
}

/**
 * Checks whether rows match the previous fingerprint during background synchronization.
 *
 * @param {Array<Object>} allRows - Extracted spreadsheet profile rows
 * @param {boolean} background - Whether background sync is active
 * @param {React.MutableRefObject<string>} lastDataFingerprintRef - Ref storing hash of last imported dataset
 * @returns {boolean} True if data is unchanged in background sync, false otherwise
 *
 * @example
 * const unchanged = checkDataFingerprintUnchanged(rows, true, { current: 'hash123' });
 *
 * @example
 * const unchanged = checkDataFingerprintUnchanged(rows, false, { current: '' });
 */
function checkDataFingerprintUnchanged(allRows, background, lastDataFingerprintRef) {
    sortSpreadsheetRows(allRows);
    const newFingerprint = computeDataFingerprint(allRows);
    if (background && lastDataFingerprintRef.current && lastDataFingerprintRef.current === newFingerprint) {
        return true;
    }
    lastDataFingerprintRef.current = newFingerprint;
    return false;
}

/**
 * Constructs a FamilyTree instance from spreadsheet rows and measures build and total timing.
 *
 * @param {Array<Object>} allRows - Extracted spreadsheet profile rows
 * @param {Object} sheetTags - Map of sheet IDs to sheet tags/names
 * @param {number} tFetchStart - Fetch start timestamp from performance.now()
 * @returns {{ newTree: FamilyTree, buildTimeMs: number, totalTimeSec: string }}
 *
 * @example
 * const { newTree, buildTimeMs, totalTimeSec } = buildAndMeasureTreeModel(rows, tags, performance.now() - 500);
 *
 * @example
 * const { newTree } = buildAndMeasureTreeModel([], {}, performance.now());
 */
function buildAndMeasureTreeModel(allRows, sheetTags, tFetchStart) {
    const tBuildStart = performance.now();
    const builder = new FamilyTreeBuilder(allRows, sheetTags);
    const newTree = builder.build();
    const tBuildEnd = performance.now();
    const buildTimeMs = Math.round(tBuildEnd - tBuildStart);
    const totalTimeSec = ((tBuildEnd - tFetchStart) / 1000).toFixed(2);
    return { newTree, buildTimeMs, totalTimeSec };
}

/**
 * Orchestrates parallel spreadsheet crawling, determinism sorting, cache caching, and tree construction.
 *
 * Logs introductory diagnostic details when starting a direct URL tree import.
 *
 * @param {Function} appendLog - Activity log append callback
 * @param {string} startId - Initial root spreadsheet identifier
 * @param {boolean} hasLoadedFromCache - Whether tree data was already loaded from local cache
 * @param {boolean} background - Whether the crawl runs as a background operation
 *
 * @example
 * logUrlImportStart(appendLog, 'root123', false, false);
 *
 * @example
 * logUrlImportStart(appendLog, 'root123', true, false);
 */
function logUrlImportStart(appendLog, startId, hasLoadedFromCache, background) {
    if (!hasLoadedFromCache && !background && appendLog) {
        appendLog('Initializing parallel import from URL...', 'info');
        appendLog(`Root ID: ${startId}`, 'success');
    }
}

/**
 * Orchestrates the full lifecycle of importing and compiling a family tree from a root Google Sheets URL.
 *
 * Fetches all linked spreadsheets concurrently, detects content differences, parses genealogical models,
 * caches the resulting dataset, and applies UI state transitions.
 *
 * @param {Object} options
 * @param {string} options.startId - Root sheet identifier
 * @param {string} options.sheetUrl - Complete source spreadsheet URL
 * @param {boolean} options.skipCache - Whether to bypass local cache
 * @param {boolean} options.background - Whether import is executed in silent background sync mode
 * @param {boolean} options.hasLoadedFromCache - Whether previous data was successfully hydrated from cache
 * @param {Function} [options.onBackgroundUpdate] - Optional callback triggered on background updates
 * @param {React.MutableRefObject} options.lastDataFingerprintRef - Ref storing previous data fingerprint
 * @param {FamilyTree} options.tree - Current active family tree model instance
 * @param {Function} options.setTree - State setter for active tree model
 * @param {Function} options.setFocusId - State setter for focused person node ID
 * @param {Function} options.setLogs - State setter for application event logs
 * @param {Function} options.appendLog - Function to record a single log entry
 * @returns {Promise<{ changed: boolean, rootId: string|null }>} Result indicating change status and root ID
 *
 * @example
 * const res = await executeUrlTreeImport({
 *   startId: 'sheet123',
 *   sheetUrl: 'https://docs.google.com/spreadsheets/d/sheet123',
 *   skipCache: false,
 *   background: false,
 *   hasLoadedFromCache: false,
 *   lastDataFingerprintRef: { current: null },
 *   tree: null,
 *   setTree: () => {},
 *   setFocusId: () => {},
 *   setLogs: () => {},
 *   appendLog: () => {}
 * });
 *
 * @example
 * const res = await executeUrlTreeImport({
 *   startId: 'sheet456',
 *   sheetUrl: 'https://docs.google.com/spreadsheets/d/sheet456',
 *   skipCache: true,
 *   background: true,
 *   hasLoadedFromCache: true,
 *   lastDataFingerprintRef: { current: 'abc' },
 *   tree: currentTree,
 *   setTree: updateTree,
 *   setFocusId: updateFocus,
 *   setLogs: updateLogs,
 *   appendLog: addLog
 * });
 */
async function executeUrlTreeImport({
    startId, sheetUrl, skipCache, background, hasLoadedFromCache,
    onBackgroundUpdate, lastDataFingerprintRef, tree, setTree, setFocusId, setLogs, appendLog
}) {
    const tFetchStart = performance.now();
    logUrlImportStart(appendLog, startId, hasLoadedFromCache, background);

    const { allRows, visited, sheetTags } = await executeSpreadsheetCrawl({
        startId, skipCache, background, hasLoadedFromCache, setLogs, setTree
    });

    const fetchTimeSec = ((performance.now() - tFetchStart) / 1000).toFixed(2);
    if (allRows.length === 0) throw new Error(`No valid data found across ${visited.size} linked spreadsheets checked.`);
    
    if (checkDataFingerprintUnchanged(allRows, background, lastDataFingerprintRef)) {
        return { changed: false, rootId: tree.rootId };
    }

    const { newTree, buildTimeMs, totalTimeSec } = buildAndMeasureTreeModel(allRows, sheetTags, tFetchStart);
    TreeDataCache.set(sheetUrl, allRows, sheetTags);

    applyConstructedTree({
        newTree, background, onBackgroundUpdate, setTree, setFocusId,
        startId, sheetTags, appendLog, allRowsCount: allRows.length,
        visitedCount: visited.size, timing: { fetchTimeSec, buildTimeMs, totalTimeSec }
    });

    return { changed: true, rootId: newTree.rootId };
}

/**
 * Attempts to load and apply a cached family tree for the given Google Sheets URL.
 *
 * @param {string} sheetUrl - Google Sheets URL to check in cache.
 * @param {Function} appendLog - Logger append callback.
 * @param {Function} setTree - State setter for family tree.
 * @returns {boolean} Whether a cached tree was found and applied.
 *
 * @example
 * const applied = tryApplyCachedTree('https://docs.google.com/...', console.log, () => {});
 *
 * @example
 * const applied = tryApplyCachedTree('https://sheets.google.com/...', () => {}, () => {});
 */
function tryApplyCachedTree(sheetUrl, appendLog, setTree) {
    const cachedTree = loadTreeFromCache(sheetUrl, appendLog);
    if (cachedTree) {
        setTree(cachedTree);
        return true;
    }
    return false;
}

/**
 * Resets loading, error, and log state when starting a non-background spreadsheet fetch.
 *
 * @param {Object} params
 * @param {boolean} params.background - Whether fetch is executing in background.
 * @param {Function} params.setIsLoading - Loading state setter.
 * @param {Function} params.setErrorMsg - Error message setter.
 * @param {Function} params.setLogs - Logs array setter.
 *
 * @example
 * resetFetchStatus({ background: false, setIsLoading, setErrorMsg, setLogs });
 *
 * @example
 * resetFetchStatus({ background: true, setIsLoading, setErrorMsg, setLogs });
 */
function resetFetchStatus({ background, setIsLoading, setErrorMsg, setLogs }) {
    if (!background) {
        setIsLoading(true);
        setErrorMsg('');
        setLogs([]);
    }
}

/**
 * Extracts and validates a Google Sheet ID from a URL, updating error state on invalid input.
 *
 * @param {string} sheetUrl - Remote spreadsheet URL.
 * @param {boolean} background - Whether fetch is in background.
 * @param {Function} setErrorMsg - Error message setter.
 * @param {Function} setIsLoading - Loading state setter.
 * @returns {string|null} Valid sheet ID or null.
 *
 * @example
 * const id = validateAndExtractSheetId('https://docs.google.com/spreadsheets/d/abc/edit', false, setErrorMsg, setIsLoading);
 *
 * @example
 * const invalid = validateAndExtractSheetId('invalid-url', true, setErrorMsg, setIsLoading);
 */
function validateAndExtractSheetId(sheetUrl, background, setErrorMsg, setIsLoading) {
    const startId = extractSheetIdFromUrl(sheetUrl);
    if (!startId && !background) {
        setErrorMsg("Invalid Google Sheets URL. Could not find a valid ID.");
        setIsLoading(false);
    }
    return startId || null;
}

/**
 * Prepares environment state, extracts sheet identifier, and attempts cache loading before network tree fetch.
 *
 * @param {Object} params
 * @param {string} params.sheetUrl - Google Sheets URL.
 * @param {Object} [params.options={}] - Fetch configuration options.
 * @param {Function} params.setIsLoading - State setter for loading status.
 * @param {Function} params.setErrorMsg - State setter for error message.
 * @param {Function} params.setLogs - State setter for log entries.
 * @param {Function} params.appendLog - Function to record log entry.
 * @param {Function} params.setTree - State setter for active tree dataset.
 * @returns {Object|null} Fetch parameters object, or null if start ID is invalid.
 *
 * @example
 * prepareDatasetFetch({
 *   sheetUrl: 'https://docs.google.com/spreadsheets/d/12345/edit',
 *   options: {},
 *   setIsLoading: () => {},
 *   setErrorMsg: () => {},
 *   setLogs: () => {},
 *   appendLog: () => {},
 *   setTree: () => {}
 * });
 *
 * @example
 * prepareDatasetFetch({
 *   sheetUrl: 'invalid-url',
 *   options: { background: true },
 *   setIsLoading: () => {},
 *   setErrorMsg: () => {},
 *   setLogs: () => {},
 *   appendLog: () => {},
 *   setTree: () => {}
 * });
 * // => null
 */
function prepareDatasetFetch({
    sheetUrl, options = {}, setIsLoading, setErrorMsg, setLogs, appendLog, setTree
}) {
    const { skipCache = false, background = false, onBackgroundUpdate = null } = options;
    if (!background) {
        setIsLoading(true);
        setErrorMsg('');
        setLogs([]);
    }
    const startId = extractSheetIdFromUrl(sheetUrl);
    if (!startId) {
        if (!background) {
            setErrorMsg("Invalid Google Sheets URL. Could not find a valid ID.");
            setIsLoading(false);
        }
        return null;
    }
    const hasLoadedFromCache = (!skipCache && !background)
        ? tryApplyCachedTree(sheetUrl, appendLog, setTree)
        : false;
    return { startId, skipCache, background, onBackgroundUpdate, hasLoadedFromCache };
}

/**
 * Initiates an end-to-end dataset fetch for a Google Sheet URL, handling cache, background polling, and tree updates.
 *
 * @param {Object} params - Parameter bundle
 * @param {string} params.sheetUrl - Target Google Sheets URL
 * @param {Object} [params.options={}] - Fetch configuration options
 * @param {boolean} [params.options.skipCache=false] - Whether to bypass cache
 * @param {boolean} [params.options.background=false] - Whether running as background refresh
 * @param {Function|null} [params.options.onBackgroundUpdate=null] - Callback invoked when background update finds newer data
 * @param {Function} params.setIsLoading - Loading state toggle
 * @param {Function} params.setErrorMsg - Error message setter
 * @param {Function} params.setLogs - Audit logs setter
 * @param {Function} params.appendLog - Log appending helper
 * @param {FamilyTree} params.tree - Active FamilyTree model instance
 * @param {Function} params.setTree - Tree state setter
 * @param {Function} params.setFocusId - Selected person ID setter
 * @param {React.MutableRefObject<string>} params.lastDataFingerprintRef - Ref storing last applied data fingerprint
 * @returns {Promise<boolean>} True if dataset was successfully fetched and applied
 *
 * @example
 * await fetchDatasetFromUrl({
 *   sheetUrl: 'https://docs.google.com/spreadsheets/d/123/edit',
 *   options: { skipCache: true },
 *   setIsLoading: () => {},
 *   setErrorMsg: () => {},
 *   setLogs: () => {},
 *   appendLog: () => {},
 *   tree: new FamilyTree(),
 *   setTree: () => {},
 *   setFocusId: () => {},
 *   lastDataFingerprintRef: { current: '' }
 * });
 *
 * @example
 * const success = await fetchDatasetFromUrl({
 *   sheetUrl: 'invalid-url',
 *   options: { background: true },
 *   setIsLoading: () => {},
 *   setErrorMsg: () => {},
 *   setLogs: () => {},
 *   appendLog: () => {},
 *   tree: new FamilyTree(),
 *   setTree: () => {},
 *   setFocusId: () => {},
 *   lastDataFingerprintRef: { current: 'abc' }
 * });
 */
async function fetchDatasetFromUrl({
    sheetUrl, options = {}, setIsLoading, setErrorMsg, setLogs,
    appendLog, tree, setTree, setFocusId, lastDataFingerprintRef
}) {
    const prep = prepareDatasetFetch({
        sheetUrl, options, setIsLoading, setErrorMsg, setLogs, appendLog, setTree
    });
    if (!prep) return false;
    const { startId, skipCache, background, onBackgroundUpdate, hasLoadedFromCache } = prep;
    try {
        return await executeUrlTreeImport({
            startId, sheetUrl, skipCache, background, hasLoadedFromCache,
            onBackgroundUpdate, lastDataFingerprintRef, tree, setTree,
            setFocusId, setLogs, appendLog
        });
    } catch (err) {
        if (!background) setErrorMsg(err.message);
        return false;
    } finally {
        if (!background) setIsLoading(false);
    }
}

/**
 * React hook managing genealogy dataset state, spreadsheet fetching, audit logs, and focus selection.
 *
 * Provides functions to fetch and parse Google Sheets data from URLs, apply preliminary
 * and complete tree datasets, record load logs, and track selection state.
 *
 * @returns {{
 *   tree: FamilyTree,
 *   setTree: React.Dispatch<React.SetStateAction<FamilyTree>>,
 *   focusId: string|null,
 *   setFocusId: React.Dispatch<React.SetStateAction<string|null>>,
 *   isLoading: boolean,
 *   errorMsg: string,
 *   logs: Array<object>,
 *   setLogs: React.Dispatch<React.SetStateAction<Array<object>>>,
 *   appendLog: Function,
 *   updateLog: Function,
 *   fetchFromUrl: (sheetUrl: string, options?: { skipCache?: boolean, background?: boolean, onBackgroundUpdate?: Function|null }) => Promise<boolean>
 * }}
 *
 * @example
 * const { tree, focusId, setFocusId, isLoading, fetchFromUrl } = useAncestryData();
 *
 * @example
 * const { tree, logs, errorMsg, appendLog } = useAncestryData();
 */
function useAncestryData() {
    const [tree, setTree] = useState(new FamilyTree());
    const [focusId, setFocusId] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [errorMsg, setErrorMsg] = useState('');
    const { logs, setLogs, appendLog, updateLog } = useAppLogs();

    const lastDataFingerprintRef = useRef('');

    const fetchFromUrl = useCallback(async (sheetUrl, options = {}) => {
        return fetchDatasetFromUrl({
            sheetUrl,
            options,
            setIsLoading,
            setErrorMsg,
            setLogs,
            appendLog,
            tree,
            setTree,
            setFocusId,
            lastDataFingerprintRef
        });
    }, [appendLog, setLogs, tree]);

    return {
        tree, setTree, focusId, setFocusId,
        isLoading, errorMsg, setErrorMsg, logs, appendLog,
        fetchFromUrl
    };
}

/**
 * Calculates the horizontal and vertical scale change factors between two zoom levels,
 * accounting for non-linear vertical pixels-per-year (ppy) scaling.
 *
 * @param {number} oldZ - Previous camera zoom level
 * @param {number} newZ - Target camera zoom level
 * @param {Function} getPpy - Pixels-per-year resolution function
 * @returns {{ scaleChangeX: number, scaleChangeY: number }}
 *
 * @example
 * calculateZoomScaleChanges(1, 2, (z) => 8)
 * // => { scaleChangeX: 2, scaleChangeY: 2 }
 *
 * @example
 * calculateZoomScaleChanges(1, 1, () => 8)
 * // => { scaleChangeX: 1, scaleChangeY: 1 }
 */
function calculateZoomScaleChanges(oldZ, newZ, getPpy) {
    const oldPpy = getPpy(oldZ);
    const newPpy = getPpy(newZ);
    const scaleChangeX = newZ / oldZ;
    const effectiveScaleY_old = oldPpy * oldZ;
    const effectiveScaleY_new = newPpy * newZ;
    const scaleChangeY = effectiveScaleY_new / effectiveScaleY_old;
    return { scaleChangeX, scaleChangeY };
}

/**
 * Calculates updated camera coordinates and zoom during a two-finger pinch gesture,
 * scaling around the focal point while accounting for variable vertical pixels-per-year.
 *
 * @param {Object} params
 * @param {number} params.newDist - Current distance between two touch points
 * @param {Object} params.newMid - Current midpoint { x, y } in client coordinates
 * @param {Object} params.pinchState - Initial pinch state { dist, mid, cam }
 * @param {DOMRect|Object} params.containerRect - Bounding client rect of container
 * @param {Function} params.getBounds - Returns viewport camera bounds { minX, maxX, minY, maxY, minZ }
 * @param {Function} params.getPpy - Returns pixels-per-year for a given zoom level
 * @returns {{x: number, y: number, z: number}} New camera position and zoom
 *
 * @example
 * // Pinching outwards from 100px to 150px distance:
 * computePinchCamera({
 *   newDist: 150,
 *   newMid: { x: 200, y: 300 },
 *   pinchState: { dist: 100, mid: { x: 200, y: 300 }, cam: { x: 0, y: 0, z: 1 } },
 *   containerRect: { left: 0, top: 0 },
 *   getBounds: (z) => ({ minZ: 0.1 }),
 *   getPpy: (z) => 8
 * })
 * // => { x: -100, y: -150, z: 1.5 }
 *
 * @example
 * computePinchCamera({
 *   newDist: 100,
 *   newMid: { x: 200, y: 300 },
 *   pinchState: { dist: 100, mid: { x: 200, y: 300 }, cam: { x: 10, y: 20, z: 1 } },
 *   containerRect: null,
 *   getBounds: () => ({ minZ: 0.1 }),
 *   getPpy: () => 8
 * })
 */
function computePinchCamera({ newDist, newMid, pinchState, containerRect, getBounds, getPpy }) {
    const scaleFactor = newDist / pinchState.dist;
    const contLeft = containerRect ? containerRect.left : 0;
    const contTop = containerRect ? containerRect.top : 0;
    const focalX = pinchState.mid.x - contLeft;
    const focalY = pinchState.mid.y - contTop;
    const panDeltaX = newMid.x - pinchState.mid.x;
    const panDeltaY = newMid.y - pinchState.mid.y;

    const baseCam = pinchState.cam;
    const targetZ = baseCam.z * scaleFactor;
    const bounds = getBounds(targetZ);
    const clampedZ = Math.max(bounds.minZ, Math.min(targetZ, 3));

    const { scaleChangeX, scaleChangeY } = calculateZoomScaleChanges(baseCam.z, clampedZ, getPpy);

    const newX = focalX - (focalX - baseCam.x) * scaleChangeX + panDeltaX;
    const newY = focalY - (focalY - baseCam.y) * scaleChangeY + panDeltaY;

    return { x: newX, y: newY, z: clampedZ };
}

/**
 * Computes updated camera coordinates when zooming in or out centered at a specific pointer position,
 * adjusting for variable vertical pixels-per-year scaling.
 *
 * @param {Object} params
 * @param {number} params.pointerX - Cursor X relative to container
 * @param {number} params.pointerY - Cursor Y relative to container
 * @param {{x: number, y: number, z: number}} params.cam - Current camera position and zoom
 * @param {number} params.deltaZ - Zoom delta multiplier exponent (-deltaY * sensitivity)
 * @param {Function} params.getBounds - Camera boundary function
 * @param {Function} params.getPpy - Pixels-per-year calculation function
 * @returns {{x: number, y: number, z: number}}
 *
 * @example
 * computeZoomAtPointer({
 *   pointerX: 400,
 *   pointerY: 300,
 *   cam: { x: 0, y: 0, z: 1 },
 *   deltaZ: 0.1,
 *   getBounds: () => ({ minZ: 0.1 }),
 *   getPpy: () => 8
 * })
 * // => { x: -42.1, y: -31.5, z: 1.105 }
 *
 * @example
 * computeZoomAtPointer({
 *   pointerX: 0,
 *   pointerY: 0,
 *   cam: { x: 0, y: 0, z: 1 },
 *   deltaZ: 0,
 *   getBounds: () => ({ minZ: 0.1 }),
 *   getPpy: () => 8
 * })
 * // => { x: 0, y: 0, z: 1 }
 */
function computeZoomAtPointer({ pointerX, pointerY, cam, deltaZ, getBounds, getPpy }) {
    const newZ = cam.z * Math.exp(deltaZ);
    const bounds = getBounds(newZ);
    const clampedZ = Math.max(bounds.minZ, Math.min(newZ, 3));
    
    const { scaleChangeX, scaleChangeY } = calculateZoomScaleChanges(cam.z, clampedZ, getPpy);
    
    const newX = pointerX - (pointerX - cam.x) * scaleChangeX;
    const newY = pointerY - (pointerY - cam.y) * scaleChangeY;
    
    return { x: newX, y: newY, z: clampedZ };
}

/**
 * Computes the unscaled coordinate bounding box enclosing an array of person node elements
 * relative to the family tree canvas container.
 *
 * @param {Array<string|number>} ids - List of person IDs to include in the bounding box
 * @param {HTMLElement|null} treeElement - Root tree DOM element for coordinate scaling
 * @returns {{minX: number, maxX: number, minY: number, maxY: number, foundCount: number}|null}
 *
 * @example
 * // Two nodes spanning x from 100 to 190 and y from 200 to 276:
 * computePeopleBoundingBox(['p1', 'p2'], treeDiv);
 * // => { minX: 100, maxX: 190, minY: 200, maxY: 276, foundCount: 2 }
 *
 * @example
 * computePeopleBoundingBox([], treeDiv);
 * // => null
 */
function computePeopleBoundingBox(ids, treeElement) {
    if (!treeElement || !ids || ids.length === 0) return null;
    const treeRect = treeElement.getBoundingClientRect();
    const currentScale = treeElement.offsetWidth ? (treeRect.width / treeElement.offsetWidth) : 1;
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    let foundCount = 0;

    for (const id of ids) {
        const node = document.getElementById(`node-${id}`);
        if (node) {
            foundCount++;
            const nodeRect = node.getBoundingClientRect();
            minX = Math.min(minX, (nodeRect.left - treeRect.left) / currentScale);
            maxX = Math.max(maxX, (nodeRect.right - treeRect.left) / currentScale);
            minY = Math.min(minY, (nodeRect.top - treeRect.top) / currentScale);
            maxY = Math.max(maxY, (nodeRect.bottom - treeRect.top) / currentScale);
        }
    }
    return { minX, maxX, minY, maxY, foundCount };
}

/**
 * Resolves camera zoom level for framed bounding boxes.
 *
 * Preserves preferred zoom if specified, anchors single-person focus to comfortable reading zoom (0.80)
 * if currently outside [0.75, 0.95], or fits multi-node clusters within usable viewport dimensions.
 *
 * @param {Object} params
 * @param {number|null} [params.preferredZ] - Explicit override zoom
 * @param {number} [params.foundCount=1] - Number of target nodes framed in the box
 * @param {number} [params.currentZ=1] - Existing camera zoom level
 * @param {number} [params.usableContW=1000] - Viewport width excluding timeline offset
 * @param {number} [params.neededW=1000] - Target width with horizontal margins
 * @param {number} [params.contH=800] - Viewport height
 * @param {number} [params.neededH=800] - Target height with vertical margins
 * @returns {number} Resolved zoom level (clamped between 0.08 and 0.85 for multi-node fit)
 *
 * @example
 * resolveFramedZoom({ preferredZ: 1.2 })
 * // => 1.2
 *
 * @example
 * resolveFramedZoom({ foundCount: 1, currentZ: 0.5 })
 * // => 0.80
 *
 * @example
 * resolveFramedZoom({ foundCount: 5, usableContW: 1000, neededW: 2000, contH: 800, neededH: 1000 })
 * // => 0.5
 */
function resolveFramedZoom({
    preferredZ = null,
    foundCount = 1,
    currentZ = 1,
    usableContW = 1000,
    neededW = 1000,
    contH = 800,
    neededH = 800
}) {
    if (preferredZ !== null && preferredZ !== undefined) {
        return preferredZ;
    }
    if (foundCount === 1) {
        return (currentZ >= 0.75 && currentZ <= 0.95) ? currentZ : 0.80;
    }
    const maxZ_X = usableContW / neededW;
    const maxZ_Y = contH / neededH;
    return Math.min(0.85, Math.max(0.08, Math.min(maxZ_X, maxZ_Y)));
}

/**
 * Calculates the horizontal camera translation (X) so that the focused tree or box
 * is visually centered within the available viewport width.
 *
 * Centering calculation accounts for timeline gutter offset, and centers the entire
 * tree if it fits within the usable viewport width.
 *
 * @example
 * resolveFramedCameraX(840, 48, 550, 0.8, 155) // => 224
 *
 * @example
 * resolveFramedCameraX(840, 48, 1200, 1, 600) // => -132
 *
 * @param {number} usableContW - Usable container width
 * @param {number} timelineWidth - Left timeline width offset
 * @param {number} treeW - Unscaled tree width
 * @param {number} finalZ - Target camera zoom factor
 * @param {number} boxCenterX - Center X of the framed bounding box
 * @returns {number} Camera X position
 */
function resolveFramedCameraX(usableContW, timelineWidth, treeW, finalZ, boxCenterX) {
    const visualCenterX = timelineWidth + usableContW / 2;
    const isTreeFitting = treeW > 0 && (treeW * finalZ <= usableContW);
    return isTreeFitting
        ? timelineWidth + (usableContW - treeW * finalZ) / 2
        : visualCenterX - (boxCenterX * finalZ);
}

/**
 * Resolves bounding dimensions and padding needs for framing a target box.
 *
 * @param {Object} options
 * @param {Object} options.box - Target bounding box { minX, maxX, minY, maxY }.
 * @param {number} [options.minBoxW=90] - Minimum box width clamp.
 * @param {number} [options.minBoxH=76] - Minimum box height clamp.
 * @param {number} [options.targetPadX=100] - Horizontal padding.
 * @param {number} [options.targetPadY=120] - Vertical padding.
 * @param {number} [options.contW=1000] - Container viewport width.
 * @param {number} [options.timelineWidth=48] - Left timeline width offset.
 * @returns {{ boxCenterX: number, boxCenterY: number, usableContW: number, neededW: number, neededH: number }}
 *
 * @example
 * resolveFramedBoxMetrics({ box: { minX: 0, maxX: 100, minY: 0, maxY: 80 }, minBoxW: 90, minBoxH: 76, targetPadX: 100, targetPadY: 120, contW: 1000, timelineWidth: 48 });
 * // => { boxCenterX: 50, boxCenterY: 40, usableContW: 952, neededW: 300, neededH: 320 }
 *
 * @example
 * resolveFramedBoxMetrics({ box: { minX: 10, maxX: 20, minY: 10, maxY: 20 }, contW: 800 });
 * // => { boxCenterX: 15, boxCenterY: 15, ... }
 */
function resolveFramedBoxMetrics({
    box,
    minBoxW = 90,
    minBoxH = 76,
    targetPadX = 100,
    targetPadY = 120,
    contW = 1000,
    timelineWidth = 48
}) {
    const boxW = Math.max(minBoxW, box.maxX - box.minX);
    const boxH = Math.max(minBoxH, box.maxY - box.minY);
    const boxCenterX = (box.minX + box.maxX) / 2;
    const boxCenterY = (box.minY + box.maxY) / 2;
    const usableContW = Math.max(100, contW - timelineWidth);
    const neededW = boxW + targetPadX * 2;
    const neededH = boxH + targetPadY * 2;
    return { boxCenterX, boxCenterY, usableContW, neededW, neededH };
}

/**
 * Calculates the target camera position (x, y) and zoom (z) to neatly frame a bounding box
 * centered in the available viewport.
 *
 * @param {Object} params
 * @param {{minX: number, maxX: number, minY: number, maxY: number, foundCount: number}} params.box - Target bounding box
 * @param {number} params.contW - Viewport width
 * @param {number} params.contH - Viewport height
 * @param {number|null} [params.preferredZ] - Explicit preferred zoom level, if any
 * @param {number} params.currentZ - Current camera zoom level
 * @param {number} [params.timelineWidth=48] - Left timeline gutter offset
 * @param {number} [params.targetPadX=100] - Horizontal padding around framed box
 * @param {number} [params.targetPadY=120] - Vertical padding around framed box
 * @param {number} [params.minBoxW=90] - Minimum width of framed bounding box
 * @param {number} [params.minBoxH=76] - Minimum height of framed bounding box
 * @returns {{x: number, y: number, z: number}}
 *
 * @example
 * computeFramedCamera({
 *   box: { minX: 0, maxX: 200, minY: 0, maxY: 300, foundCount: 1 },
 *   contW: 1000,
 *   contH: 800,
 *   preferredZ: null,
 *   currentZ: 0.8
 * })
 * // => { x: 424, y: 280, z: 0.8 }
 *
 * @example
 * computeFramedCamera({
 *   box: { minX: 0, maxX: 100, minY: 0, maxY: 100, foundCount: 1 },
 *   contW: 800,
 *   contH: 600,
 *   preferredZ: 1.0,
 *   currentZ: 1.0
 * })
 */
function computeFramedCamera({
    box, contW, contH, preferredZ = null, currentZ = 1,
    timelineWidth = 48, targetPadX = 100, targetPadY = 120,
    minBoxW = 90, minBoxH = 76, treeW = null
}) {
    const { boxCenterX, boxCenterY, usableContW, neededW, neededH } = resolveFramedBoxMetrics({
        box, minBoxW, minBoxH, targetPadX, targetPadY, contW, timelineWidth
    });

    const finalZ = resolveFramedZoom({
        preferredZ, foundCount: box.foundCount, currentZ,
        usableContW, neededW, contH, neededH
    });

    return {
        x: resolveFramedCameraX(usableContW, timelineWidth, treeW, finalZ, boxCenterX),
        y: (contH * 0.50) - (boxCenterY * finalZ),
        z: finalZ
    };
}

/**
 * Calculates fit-to-screen target camera zoom and (x, y) coordinates.
 *
 * @param {Object} params
 * @param {number} params.treeW - Tree unscaled width
 * @param {number} params.usableContW - Usable container width
 * @param {number} [params.timelineWidth=48] - Timeline offset
 * @param {number} [params.paddingX=8] - Horizontal padding
 * @param {number} [params.topMargin=16] - Top margin offset
 * @returns {{x: number, y: number, z: number}}
 *
 * @example
 * computeFitToScreenCamera({ treeW: 1000, usableContW: 800, timelineWidth: 48 })
 * // => { x: 56, y: 16, z: 0.784 }
 *
 * @example
 * computeFitToScreenCamera({ treeW: 0, usableContW: 800 })
 * // => { x: 0, y: 16, z: 1 }
 */
function computeFitToScreenCamera({ treeW, usableContW, timelineWidth = 48, paddingX = 8, topMargin = 16 }) {
    if (treeW <= 0) return { x: 0, y: topMargin, z: 1 };
    const targetZ = Math.max(0.05, Math.min((usableContW - paddingX * 2) / treeW, 1));
    const scaledW = treeW * targetZ;
    const targetX = scaledW <= usableContW
        ? timelineWidth + (usableContW - scaledW) / 2
        : timelineWidth + paddingX;
    return { x: targetX, y: topMargin, z: targetZ };
}

/**
 * Calculates dynamically stretched pixels-per-year for timeline scaling based on viewport height and tree year span.
 *
 * @param {Object} treeStats - Family tree statistics (rootNodeYob, maxYear, minYear)
 * @param {number} contH - Container/viewport height
 * @param {number} z - Camera zoom scale
 * @param {number} [topMargin=16] - Top margin offset
 * @param {number} [bottomMargin=0] - Bottom margin offset
 * @returns {number} Calculated pixels-per-year (at least nativePpy = 8)
 *
 * @example
 * computeDynamicPpy({ minYear: 1900, maxYear: 2000, rootNodeYob: 1900 }, 800, 1)
 * // => 8
 *
 * @example
 * computeDynamicPpy(null, 800, 1)
 * // => 8
 */
function computeDynamicPpy(treeStats, contH, z, topMargin = 16, bottomMargin = 0) {
    const nativePpy = 8;
    if (!treeStats || !treeStats.minYear) return nativePpy;
    const spanYears = Math.max(5, treeStats.maxYear - treeStats.rootNodeYob);
    const stretchedPpy = ((contH - bottomMargin - topMargin) / z - 86) / spanYears;
    return Math.max(nativePpy, stretchedPpy);
}

/**
 * Computes boundary clamp limits for canvas camera panning and zooming.
 *
 * @param {Object} params
 * @param {number} params.treeW - Tree unscaled width
 * @param {number} params.treeH - Tree unscaled height
 * @param {number} params.contW - Viewport width
 * @param {number} params.contH - Viewport height
 * @param {number} params.z - Camera zoom scale
 * @param {number} [params.timelineWidth=48] - Left timeline offset
 * @param {number} [params.paddingX=8] - Panning horizontal margin
 * @param {number} [params.topMargin=16] - Panning top margin
 * @param {number} [params.bottomMargin=0] - Panning bottom margin
 * @returns {{ minX: number, maxX: number, minY: number, maxY: number, minZ: number, centeredX: number }}
 *
 * @example
 * computeCameraBounds({ treeW: 1000, treeH: 600, contW: 800, contH: 600, z: 1, timelineWidth: 48 })
 * // => { minX: -208, maxX: 56, minY: 16, maxY: 16, minZ: 0.736, centeredX: 48 }
 *
 * @example
 * computeCameraBounds({ treeW: 200, treeH: 200, contW: 800, contH: 600, z: 1 })
 * // => { minX: 324, maxX: 324, minY: 16, maxY: 16, minZ: 1, centeredX: 324 }
 */
function computeCameraBounds({
    treeW,
    treeH,
    contW,
    contH,
    z,
    timelineWidth = 48,
    paddingX = 8,
    topMargin = 16,
    bottomMargin = 0
}) {
    const usableContW = Math.max(100, contW - timelineWidth);
    const usableH = Math.max(100, contH - topMargin - bottomMargin);

    const minZ = Math.max(0.05, Math.min((usableContW - paddingX * 2) / Math.max(1, treeW), 1));
    const scaledW = treeW * z;
    const scaledH = treeH * z;

    const centeredX = timelineWidth + (usableContW - scaledW) / 2;

    let minX = scaledW <= usableContW ? centeredX : contW - scaledW - paddingX;
    let maxX = scaledW <= usableContW ? centeredX : timelineWidth + paddingX;
    let minY = scaledH <= usableH ? topMargin : contH - scaledH - bottomMargin;
    let maxY = scaledH <= usableH ? topMargin : topMargin;

    return { minX, maxX, minY, maxY, minZ, centeredX };
}

/**
 * Resolves the actual layout width of the tree DOM element, taking into account compact tree view if present.
 *
 * @param {HTMLElement|null} treeElement - The root tree DOM container.
 * @returns {number} Width in pixels, or 0 if element is not mounted.
 *
 * @example
 * getTreeElementWidth(document.getElementById('tree-view'));
 * // => 1420
 *
 * @example
 * getTreeElementWidth(null);
 * // => 0
 */
function getTreeElementWidth(treeElement) {
    if (!treeElement) return 0;
    const compactTree = treeElement.querySelector?.('.compact-tree-view');
    return compactTree
        ? (compactTree.offsetWidth || parseFloat(compactTree.style.width) || treeElement.scrollWidth)
        : treeElement.scrollWidth;
}

/**
 * Computes the Euclidean distance and midpoint between two 2D coordinates.
 *
 * @param {{ x: number, y: number }} p1 - First coordinate.
 * @param {{ x: number, y: number }} p2 - Second coordinate.
 * @returns {{ dist: number, mid: { x: number, y: number } }} Distance and midpoint.
 *
 * @example
 * calculateTwoPointGeometry({ x: 0, y: 0 }, { x: 3, y: 4 });
 * // => { dist: 5, mid: { x: 1.5, y: 2 } }
 *
 * @example
 * calculateTwoPointGeometry({ x: 10, y: 10 }, { x: 10, y: 20 });
 * // => { dist: 10, mid: { x: 10, y: 15 } }
 */
function calculateTwoPointGeometry(p1, p2) {
    const dist = Math.hypot(p2.x - p1.x, p2.y - p1.y);
    const mid = { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 };
    return { dist, mid };
}

/**
 * Resolves container viewport dimensions accounting for sidebar state, window bounds, and standalone mode.
 *
 * @param {Object} options
 * @param {HTMLElement|null} options.container - Container DOM element.
 * @param {boolean} [options.isSidebarOpen=false] - Whether sidebar is open.
 * @param {number} [options.sidebarWidth=360] - Width of sidebar in pixels.
 * @param {boolean} [options.forceFullWindow=false] - If true, ignores sidebar and uses full window.
 * @returns {{ contW: number, contH: number }} Viewport width and height.
 *
 * @example
 * resolveViewportDimensions({ isSidebarOpen: false });
 * // => { contW: 1024, contH: 768 }
 *
 * @example
 * resolveViewportDimensions({ isSidebarOpen: true, sidebarWidth: 400 });
 * // => { contW: 624, contH: 768 }
 */
function resolveViewportDimensions({
    container,
    isSidebarOpen = false,
    sidebarWidth = 360,
    forceFullWindow = false
}) {
    const hasWindow = typeof window !== 'undefined';
    const effectiveContW = (isSidebarOpen && hasWindow)
        ? (window.innerWidth - (sidebarWidth || 360))
        : (container ? container.clientWidth : (hasWindow ? window.innerWidth : 1000));
    const contW = (forceFullWindow && hasWindow) ? window.innerWidth : effectiveContW;
    const contH = (forceFullWindow || !isSidebarOpen) && hasWindow
        ? window.innerHeight
        : (container ? container.clientHeight : (hasWindow ? window.innerHeight : 800));
    return { contW, contH };
}

/**
 * Attaches touch event listeners for pinch-to-zoom to the canvas container and returns a cleanup callback.
 *
 * @param {HTMLElement} container - Canvas container element.
 * @param {Function} onTouchStart - Touch start event handler.
 * @param {Function} onTouchMove - Touch move event handler.
 * @param {Function} onTouchEnd - Touch end event handler.
 * @returns {() => void} Cleanup function removing attached listeners.
 *
 * @example
 * const cleanup = bindCanvasTouchEvents(container, () => {}, () => {}, () => {});
 *
 * @example
 * const cleanup = bindCanvasTouchEvents(document.body, () => {}, () => {}, () => {});
 */
function bindCanvasTouchEvents(container, onTouchStart, onTouchMove, onTouchEnd) {
    container.addEventListener('touchstart', onTouchStart, { passive: false });
    container.addEventListener('touchmove', onTouchMove, { passive: false });
    container.addEventListener('touchend', onTouchEnd);
    container.addEventListener('touchcancel', onTouchEnd);
    return () => {
        container.removeEventListener('touchstart', onTouchStart);
        container.removeEventListener('touchmove', onTouchMove);
        container.removeEventListener('touchend', onTouchEnd);
        container.removeEventListener('touchcancel', onTouchEnd);
    };
}

/**
 * Calculates distance and midpoint geometry between the first two touch points of a touch event.
 *
 * @param {TouchList|Touch[]} touches - Active touch points list.
 * @returns {{ dist: number, mid: { x: number, y: number } }} Distance and midpoint coordinates.
 *
 * @example
 * const geom = getTouchPinchGeometry(e.touches);
 *
 * @example
 * const geom = getTouchPinchGeometry([t1, t2]);
 */
function getTouchPinchGeometry(touches) {
    const p1 = { x: touches[0].clientX, y: touches[0].clientY };
    const p2 = { x: touches[1].clientX, y: touches[1].clientY };
    return calculateTwoPointGeometry(p1, p2);
}

/**
 * Processes a 2-finger touch pinch movement and calculates the clamped next camera state.
 *
 * @param {Object} params
 * @param {TouchList} params.touches - Active touch list
 * @param {Object} params.touchPinch - Current active pinch reference state
 * @param {Element} params.container - Viewport container element
 * @param {Function} params.getBounds - Camera bounds getter
 * @param {Function} params.getPpy - Pixels-per-year getter
 * @param {Function} params.clampCamera - Coordinate clamping function
 * @returns {Object|null} Clamped next camera state, or null if pinch is invalid
 *
 * @example
 * const next = processTouchPinchMove({ touches, touchPinch, container, getBounds, getPpy, clampCamera });
 *
 * @example
 * const next = processTouchPinchMove({ touches: [], touchPinch: null });
 * // => null
 */
function processTouchPinchMove({ touches, touchPinch, container, getBounds, getPpy, clampCamera }) {
    if (!touches || touches.length !== 2 || !touchPinch || touchPinch.dist <= 10) return null;
    const { dist: newDist, mid: newMid } = getTouchPinchGeometry(touches);
    const containerRect = container.getBoundingClientRect();
    const nextCam = computePinchCamera({
        newDist, newMid, pinchState: touchPinch, containerRect, getBounds, getPpy
    });
    return clampCamera(nextCam);
}

/**
 * Initializes touch pinch tracking state from a two-finger touch event and triggers interaction callback.
 *
 * @param {TouchList} touches - TouchList with two active touches
 * @param {Object} cameraRef - React ref holding current camera coordinates
 * @param {Function} [onInteract] - Optional interaction callback
 * @returns {Object} Initial pinch state containing distance, midpoint, and snapshot camera
 *
 * @example
 * const pinch = initTouchPinchState(e.touches, cameraRef, onInteract);
 * // => { dist: 120, mid: { x: 100, y: 150 }, cam: { x: 0, y: 0, z: 1 } }
 *
 * @example
 * const pinch = initTouchPinchState(e.touches, { current: { x: 10, y: 20, z: 1.5 } });
 * // => { dist: 85, mid: { x: 50, y: 75 }, cam: { x: 10, y: 20, z: 1.5 } }
 */
function initTouchPinchState(touches, cameraRef, onInteract) {
    const { dist, mid } = getTouchPinchGeometry(touches);
    if (onInteract) onInteract();
    return { dist, mid, cam: { ...cameraRef.current } };
}

/**
 * Registers multi-touch pinch-to-zoom and pan gesture listeners on the tree canvas container.
 *
 * @param {object} params
 * @param {HTMLElement} params.container - Canvas viewport container element
 * @param {Function} params.onInteract - Callback invoked when user interacts with canvas
 * @param {React.MutableRefObject} params.cameraRef - Ref storing current camera coordinates
 * @param {Function} params.setCamera - Camera state setter
 * @param {Function} params.clampCamera - Boundary clamping function
 * @param {Function} params.getBounds - Dynamic camera boundaries getter
 * @param {Function} params.getPpy - Dynamic pixels-per-year getter
 * @returns {Function} Cleanup function removing attached event listeners
 *
 * @example
 * useEffect(() => {
 *     return setupCanvasTouchListeners({
 *         container: containerRef.current,
 *         onInteract,
 *         cameraRef,
 *         setCamera,
 *         clampCamera,
 *         getBounds,
 *         getPpy
 *     });
 * }, [clampCamera, getBounds, getPpy, onInteract]);
 *
 * @example
 * const cleanup = setupCanvasTouchListeners({ container: null });
 * // returns empty no-op function
 */
function setupCanvasTouchListeners({
    container, onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy
}) {
    if (!container) return () => {};
    let touchPinch = null;

    const onTouchStart = (e) => {
        if (e.touches.length !== 2) return;
        e.preventDefault();
        touchPinch = initTouchPinchState(e.touches, cameraRef, onInteract);
    };

    const onTouchMove = (e) => {
        const nextCam = processTouchPinchMove({
            touches: e.touches, touchPinch, container, getBounds, getPpy, clampCamera
        });
        if (nextCam) {
            e.preventDefault();
            setCamera(nextCam);
        }
    };

    const onTouchEnd = (e) => { if (e.touches.length < 2) touchPinch = null; };

    return bindCanvasTouchEvents(container, onTouchStart, onTouchMove, onTouchEnd);
}

/**
 * Resolves viewport dimensions and updates camera coordinates to enclose a bounding box of people.
 *
 * @param {object} params
 * @param {object} params.box - Computed bounding box of people nodes
 * @param {HTMLElement} params.treeElement - Inner tree DOM element
 * @param {HTMLElement} params.container - Outer canvas container DOM element
 * @param {boolean} params.isSidebarOpen - Whether the sidebar is currently open
 * @param {number} params.sidebarWidth - Width of the sidebar in pixels
 * @param {number|null} params.preferredZ - Optional forced zoom level
 * @param {number} params.targetPadX - Horizontal padding in pixels
 * @param {number} params.targetPadY - Vertical padding in pixels
 * @param {Function} params.setCamera - State setter for camera coordinates
 * @param {Function} params.clampCamera - Function clamping camera coordinates to viewport bounds
 *
 * @example
 * applyFramedCamera({
 *   box: { minX: 0, maxX: 400, minY: 0, maxY: 300, foundCount: 2 },
 *   treeElement: document.getElementById('tree'),
 *   container: document.getElementById('canvas'),
 *   isSidebarOpen: false,
 *   sidebarWidth: 360,
 *   preferredZ: 1,
 *   targetPadX: 50,
 *   targetPadY: 50,
 *   setCamera: (fn) => {},
 *   clampCamera: (cam) => cam
 * });
 *
 * @example
 * // Apply camera centering with auto zoom
 * applyFramedCamera({
 *   box: { minX: 10, maxX: 500, minY: 20, maxY: 600, foundCount: 5 },
 *   treeElement: document.getElementById('tree'),
 *   container: document.getElementById('canvas'),
 *   isSidebarOpen: true,
 *   sidebarWidth: 400,
 *   preferredZ: null,
 *   targetPadX: 100,
 *   targetPadY: 120,
 *   setCamera: (fn) => {},
 *   clampCamera: (cam) => cam
 * });
 */
function applyFramedCamera({
    box, treeElement, container, isSidebarOpen, sidebarWidth,
    preferredZ, targetPadX, targetPadY, setCamera, clampCamera
}) {
    const { contW: effectiveContW, contH } = resolveViewportDimensions({
        container, isSidebarOpen, sidebarWidth, forceFullWindow: false
    });
    const currentTreeW = getTreeElementWidth(treeElement);

    setCamera(cam => {
        const nextCam = computeFramedCamera({
            box, contW: effectiveContW, contH, preferredZ,
            currentZ: cam.z, targetPadX, targetPadY, treeW: currentTreeW
        });
        return clampCamera(nextCam);
    });
}

/**
 * Resolves configuration parameters with default values for polling and framing people nodes.
 *
 * @param {number|Object|null} options - Optional preferred zoom level number or options object.
 * @returns {{
 *   preferredZ: number|null,
 *   targetPadX: number,
 *   targetPadY: number,
 *   maxAttempts: number,
 *   intervalMs: number,
 *   initialDelay: number
 * }} Normalized polling configuration options.
 *
 * @example
 *   resolveFramePeopleOptions(1.5);
 *   // returns { preferredZ: 1.5, targetPadX: 100, targetPadY: 120, maxAttempts: 35, intervalMs: 35, initialDelay: 25 }
 *
 * @example
 *   resolveFramePeopleOptions({ targetPadX: 80, maxAttempts: 20 });
 *   // returns { preferredZ: null, targetPadX: 80, targetPadY: 120, maxAttempts: 20, intervalMs: 35, initialDelay: 25 }
 */
function resolveFramePeopleOptions(options) {
    const preferredZ = typeof options === 'number' ? options : options?.preferredZ ?? null;
    const targetPadX = options?.targetPadX ?? 100;
    const targetPadY = options?.targetPadY ?? 120;
    const maxAttempts = options?.maxAttempts ?? 35;
    const intervalMs = options?.intervalMs ?? 35;
    const initialDelay = options?.initialDelay ?? 25;

    return { preferredZ, targetPadX, targetPadY, maxAttempts, intervalMs, initialDelay };
}

/**
 * Attempts to locate target people in the tree and apply framed camera coordinates.
 *
 * @param {Object} params
 * @param {string[]} params.ids - Array of person profile IDs to frame.
 * @param {HTMLElement|null} params.treeElement - DOM element of tree container.
 * @param {HTMLElement|null} params.container - DOM element of viewport container.
 * @param {boolean} params.isSidebarOpen - Whether sidebar details panel is open.
 * @param {number} params.sidebarWidth - Width of sidebar in pixels.
 * @param {number} params.preferredZ - Preferred zoom level.
 * @param {number} params.targetPadX - Target horizontal padding.
 * @param {number} params.targetPadY - Target vertical padding.
 * @param {Function} params.setCamera - State setter for camera coordinates.
 * @param {Function} params.clampCamera - Clamping function for camera coordinates.
 * @returns {boolean} True if framing was successfully applied.
 *
 * @example
 * attemptFramePeople({ ids: ['p1'], treeElement: el, container: c, isSidebarOpen: false, sidebarWidth: 360, preferredZ: 1, targetPadX: 40, targetPadY: 40, setCamera: () => {}, clampCamera: c => c });
 *
 * @example
 * attemptFramePeople({ ids: [], treeElement: null, container: null, isSidebarOpen: false, sidebarWidth: 360, preferredZ: 1, targetPadX: 40, targetPadY: 40, setCamera: () => {}, clampCamera: c => c });
 */
function attemptFramePeople({
    ids, treeElement, container, isSidebarOpen, sidebarWidth,
    preferredZ, targetPadX, targetPadY, setCamera, clampCamera
}) {
    if (!treeElement || !container) return false;
    const box = computePeopleBoundingBox(ids, treeElement);
    if (box && box.foundCount < ids.length) return false;
    if (box && box.foundCount > 0) {
        applyFramedCamera({
            box, treeElement, container, isSidebarOpen,
            sidebarWidth, preferredZ, targetPadX, targetPadY, setCamera, clampCamera
        });
        return true;
    }
    return false;
}

/**
 * Executes a polling retry loop to frame a collection of person node IDs in the canvas
 * once their DOM elements are rendered and their bounding boxes are measurable.
 *
 * @param {Object} params
 * @param {string[]} params.ids - Array of person IDs to frame.
 * @param {Object|number|null} [params.options] - Configuration options or preferred zoom level.
 * @param {React.RefObject} params.treeRef - Ref to family tree container element.
 * @param {React.RefObject} params.containerRef - Ref to canvas viewport container element.
 * @param {boolean} [params.isSidebarOpen=false] - Whether sidebar is open.
 * @param {number} [params.sidebarWidth=360] - Width of sidebar in pixels.
 * @param {Function} params.setCamera - State setter for camera.
 * @param {Function} params.clampCamera - Clamping function for camera coordinates.
 * @returns {number|null} Initial timer ID from setTimeout or null if empty ids.
 *
 * @example
 * const timerId = pollFramePeople({
 *     ids: ['p1', 'p2'],
 *     options: { preferredZ: 1.0 },
 *     treeRef,
 *     containerRef,
 *     isSidebarOpen: false,
 *     sidebarWidth: 360,
 *     setCamera,
 *     clampCamera
 * });
 *
 * @example
 * // With custom attempts and delay
 * pollFramePeople({
 *     ids: ['root'],
 *     options: { maxAttempts: 10, intervalMs: 20, initialDelay: 10 },
 *     treeRef,
 *     containerRef,
 *     isSidebarOpen: true,
 *     sidebarWidth: 400,
 *     setCamera,
 *     clampCamera
 * });
 */
function pollFramePeople({
    ids, options = null, treeRef, containerRef,
    isSidebarOpen = false, sidebarWidth = 360, setCamera, clampCamera
}) {
    if (!ids || ids.length === 0) return null;
    const { preferredZ, targetPadX, targetPadY, maxAttempts, intervalMs, initialDelay } = resolveFramePeopleOptions(options);

    let attempts = 0;
    const tryFrame = () => {
        attempts++;
        const framed = attemptFramePeople({
            ids, treeElement: treeRef.current, container: containerRef.current, isSidebarOpen,
            sidebarWidth, preferredZ, targetPadX, targetPadY, setCamera, clampCamera
        });
        if (!framed && attempts < maxAttempts) {
            setTimeout(tryFrame, intervalMs);
        }
    };

    return setTimeout(tryFrame, initialDelay);
}

/**
 * Performs a single measurement and camera update to refine canvas fit-to-screen geometry.
 *
 * @param {Object} params
 * @param {React.RefObject} params.treeRef - Ref to family tree container element.
 * @param {React.RefObject} params.containerRef - Ref to canvas viewport container element.
 * @param {Function} params.setCamera - State setter for camera.
 * @param {boolean} [params.isSidebarOpen=false] - Whether sidebar is open.
 * @param {number} [params.sidebarWidth=360] - Width of sidebar in pixels.
 * @param {boolean} [params.forceFullWindow=false] - Whether to use full window dimensions.
 * @param {number} [params.timelineWidth=48] - Width offset for timeline bar.
 * @param {number} [params.paddingX=8] - Horizontal padding.
 * @param {number} [params.topMargin=16] - Top margin offset.
 *
 * @example
 * performFitToScreenRefinement({
 *     treeRef: { current: null },
 *     containerRef: { current: null },
 *     setCamera: () => {}
 * });
 *
 * @example
 * performFitToScreenRefinement({
 *     treeRef: { current: document.createElement('div') },
 *     containerRef: { current: document.createElement('div') },
 *     setCamera: (cam) => console.log(cam),
 *     isSidebarOpen: true
 * });
 */
function performFitToScreenRefinement({
    treeRef, containerRef, setCamera, isSidebarOpen = false, sidebarWidth = 360,
    forceFullWindow = false, timelineWidth = 48, paddingX = 8, topMargin = 16
}) {
    if (!treeRef?.current || !containerRef?.current) return;
    const dims = resolveViewportDimensions({
        container: containerRef.current, isSidebarOpen, sidebarWidth, forceFullWindow
    });
    const updatedTreeW = getTreeElementWidth(treeRef.current);
    if (updatedTreeW > 0) {
        const usableContW = Math.max(100, dims.contW - timelineWidth);
        setCamera(computeFitToScreenCamera({
            treeW: updatedTreeW, usableContW, timelineWidth, paddingX, topMargin
        }));
    }
}

/**
 * Schedules two-stage delayed camera refinement passes (at 50ms and 350ms)
 * after a fit-to-screen invocation to allow re-render and CSS transitions to settle.
 *
 * @param {Object} params
 * @param {React.RefObject} params.treeRef - Ref to family tree container element.
 * @param {React.RefObject} params.containerRef - Ref to canvas viewport container element.
 * @param {Function} params.setCamera - State setter for camera.
 * @param {boolean} [params.isSidebarOpen=false] - Whether sidebar is open.
 * @param {number} [params.sidebarWidth=360] - Width of sidebar in pixels.
 * @param {boolean} [params.forceFullWindow=false] - Whether to use full window dimensions.
 * @param {number} [params.timelineWidth=48] - Width offset for timeline bar.
 * @param {number} [params.paddingX=8] - Horizontal padding.
 * @param {number} [params.topMargin=16] - Top margin offset.
 * @returns {Array<number>} Array of timeout IDs.
 *
 * @example
 * const timerIds = scheduleFitToScreenRefinement({
 *     treeRef,
 *     containerRef,
 *     setCamera,
 *     isSidebarOpen: true,
 *     sidebarWidth: 360,
 *     forceFullWindow: false,
 *     timelineWidth: 48,
 *     paddingX: 8,
 *     topMargin: 16
 * });
 *
 * @example
 * // Cleanup refinement timers if needed
 * const timers = scheduleFitToScreenRefinement({
 *     treeRef,
 *     containerRef,
 *     setCamera
 * });
 * timers.forEach(clearTimeout);
 */
function scheduleFitToScreenRefinement(params) {
    const refine = () => performFitToScreenRefinement(params);
    const t1 = setTimeout(refine, 50);
    const t2 = setTimeout(refine, 350);
    return [t1, t2];
}

/**
 * Sets up a ResizeObserver on the canvas container and tree elements to re-clamp
 * camera coordinates when the container viewport resizes (e.g. window resize or sidebar toggle),
 * while ignoring layout-induced tree dimension changes.
 *
 * @param {Object} params
 * @param {React.RefObject} params.containerRef - Ref to container element.
 * @param {React.RefObject} params.treeRef - Ref to tree element.
 * @param {Function} params.setCamera - State setter for camera.
 * @param {Function} params.clampCamera - Clamping function for camera coordinates.
 * @returns {Function} Cleanup function to cancel pending rAF and disconnect ResizeObserver.
 *
 * @example
 * const cleanup = setupCanvasResizeObserver({
 *     containerRef,
 *     treeRef,
 *     setCamera,
 *     clampCamera
 * });
 * // On cleanup:
 * cleanup();
 *
 * @example
 * useEffect(() => {
 *     return setupCanvasResizeObserver({
 *         containerRef,
 *         treeRef,
 *         setCamera,
 *         clampCamera
 *     });
 * }, [clampCamera]);
 */
function setupCanvasResizeObserver({
    containerRef,
    treeRef,
    setCamera,
    clampCamera
}) {
    if (typeof ResizeObserver === 'undefined') return () => {};
    let rafId;
    const ro = new ResizeObserver((entries) => {
        const isContainerResize = !entries || entries.some(entry => entry.target === containerRef.current);
        if (!isContainerResize) return;
        if (rafId) cancelAnimationFrame(rafId);
        rafId = requestAnimationFrame(() => {
            setCamera(cam => clampCamera(cam));
        });
    });

    if (containerRef.current) ro.observe(containerRef.current);
    if (treeRef.current) ro.observe(treeRef.current);

    return () => {
        if (rafId) cancelAnimationFrame(rafId);
        ro.disconnect();
    };
}

/**
 * Hook generating a wheel event listener to handle zoom-at-pointer interactions on the canvas.
 *
 * @param {object} params
 * @param {Function} [params.onInteract] - Callback invoked on interaction
 * @param {React.RefObject<HTMLElement>} params.containerRef - Ref to outer canvas container DOM node
 * @param {React.Dispatch<React.SetStateAction<object>>} params.setCamera - State setter for camera coordinates
 * @param {(cam: object) => object} params.clampCamera - Coordinate clamping function
 * @param {Function} params.getBounds - Returns canvas boundary dimensions
 * @param {Function} params.getPpy - Returns current pixels-per-year zoom scale
 * @returns {(e: React.WheelEvent) => void} Wheel event handler
 *
 * @example
 * const handleWheel = useCanvasWheelZoom({ onInteract, containerRef, setCamera, clampCamera, getBounds, getPpy });
 *
 * @example
 * <div onWheel={handleWheel} />
 */
function useCanvasWheelZoom({ onInteract, containerRef, setCamera, clampCamera, getBounds, getPpy }) {
    return useCallback((e) => {
        if (e.target.closest('.interactive-element')) return;
        if (onInteract) onInteract();
        
        const cont = containerRef.current ? containerRef.current.getBoundingClientRect() : { left: 0, top: 0 };
        const pointerX = e.clientX - cont.left;
        const pointerY = e.clientY - cont.top;
        const zoomSensitivity = 0.002;
        const deltaZ = -e.deltaY * zoomSensitivity;
        
        setCamera(cam => {
            const nextCam = computeZoomAtPointer({
                pointerX,
                pointerY,
                cam,
                deltaZ,
                getBounds,
                getPpy
            });
            return clampCamera(nextCam);
        });
    }, [clampCamera, getBounds, onInteract, getPpy, setCamera, containerRef]);
}

/**
 * Dispatches pointer move updates, either updating multi-touch pinch zoom geometry
 * or panning the camera according to single-finger / single-mouse dragging.
 *
 * @param {object} params
 * @param {React.PointerEvent} params.e - Native pointermove event
 * @param {React.MutableRefObject<Map<number, {x: number, y: number}>>} params.activePointersRef - Active pointers map
 * @param {React.MutableRefObject<object|null>} params.pointerPinchRef - Multi-touch pinch tracking state
 * @param {boolean} params.isDragging - Whether single pointer drag is active
 * @param {{x: number, y: number}} params.dragStart - Drag origin coordinates
 * @param {React.RefObject<HTMLElement>} params.containerRef - Canvas container ref
 * @param {Function} params.getBounds - Boundary calculator
 * @param {Function} params.getPpy - Pixels-per-year calculator
 * @param {React.Dispatch<React.SetStateAction<object>>} params.setCamera - Camera setter
 * @param {Function} params.clampCamera - Boundary clamper
 *
 * @example
 * processPointerMove({
 *   e: { pointerId: 1, clientX: 100, clientY: 100 },
 *   activePointersRef: { current: new Map() },
 *   pointerPinchRef: { current: null },
 *   isDragging: false,
 *   dragStart: { x: 0, y: 0 },
 *   containerRef: { current: null },
 *   getBounds: () => ({}),
 *   getPpy: () => 10,
 *   setCamera: () => {},
 *   clampCamera: c => c
 * });
 *
 * @example
 * processPointerMove({
 *   e: { pointerId: 1, clientX: 200, clientY: 200 },
 *   activePointersRef: { current: new Map([[1, { x: 100, y: 100 }]]) },
 *   pointerPinchRef: { current: null },
 *   isDragging: true,
 *   dragStart: { x: 0, y: 0 },
 *   containerRef: { current: null },
 *   getBounds: () => ({}),
 *   getPpy: () => 10,
 *   setCamera: () => {},
 *   clampCamera: c => c
 * });
 */
function processPointerMove({
    e, activePointersRef, pointerPinchRef, isDragging, dragStart,
    containerRef, getBounds, getPpy, setCamera, clampCamera
}) {
    if (!activePointersRef.current.has(e.pointerId)) return;
    activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointersRef.current.size === 2 && pointerPinchRef.current && pointerPinchRef.current.dist > 10) {
        const [p1, p2] = Array.from(activePointersRef.current.values());
        const { dist: newDist, mid: newMid } = calculateTwoPointGeometry(p1, p2);
        const containerRect = containerRef.current ? containerRef.current.getBoundingClientRect() : { left: 0, top: 0 };
        const nextCam = computePinchCamera({
            newDist, newMid, pinchState: pointerPinchRef.current,
            containerRect, getBounds, getPpy
        });
        setCamera(clampCamera(nextCam));
    } else if (activePointersRef.current.size === 1 && isDragging) {
        setCamera(cam => clampCamera({ ...cam, x: e.clientX - dragStart.x, y: e.clientY - dragStart.y }));
    }
}

/**
 * Handles pointer release or cancellation by clearing pointer tracking state,
 * adjusting the active pinch anchor, or ending drag interactions.
 *
 * @param {object} params
 * @param {React.PointerEvent} params.e - Native pointerup event
 * @param {React.MutableRefObject<Map<number, {x: number, y: number}>>} params.activePointersRef - Active pointers map
 * @param {React.MutableRefObject<object|null>} params.pointerPinchRef - Multi-touch pinch tracking state
 * @param {React.MutableRefObject<object>} params.cameraRef - Current camera coordinates ref
 * @param {Function} params.setDragStart - Setter for drag origin
 * @param {Function} params.setIsDragging - Setter for drag state
 *
 * @example
 * processPointerUp({
 *   e: { pointerId: 1, currentTarget: null },
 *   activePointersRef: { current: new Map() },
 *   pointerPinchRef: { current: null },
 *   cameraRef: { current: { x: 0, y: 0, z: 1 } },
 *   setDragStart: () => {},
 *   setIsDragging: () => {}
 * });
 *
 * @example
 * processPointerUp({
 *   e: { pointerId: 2, currentTarget: null },
 *   activePointersRef: { current: new Map([[1, { x: 0, y: 0 }]]) },
 *   pointerPinchRef: { current: null },
 *   cameraRef: { current: { x: 0, y: 0, z: 1 } },
 *   setDragStart: () => {},
 *   setIsDragging: () => {}
 * });
 */
function processPointerUp({
    e,
    activePointersRef,
    pointerPinchRef,
    cameraRef,
    setDragStart,
    setIsDragging
}) {
    activePointersRef.current.delete(e.pointerId);
    try {
        if (e.pointerId && e.currentTarget) {
            e.currentTarget.releasePointerCapture(e.pointerId);
        }
    } catch (err) {}

    if (activePointersRef.current.size < 2) {
        pointerPinchRef.current = null;
    }
    if (activePointersRef.current.size === 1) {
        const remaining = activePointersRef.current.values().next().value;
        setDragStart({ x: remaining.x - cameraRef.current.x, y: remaining.y - cameraRef.current.y });
    } else if (activePointersRef.current.size === 0) {
        setIsDragging(false);
    }
}

/**
 * Evaluates whether an incoming pointerdown event should be ignored for canvas dragging or pinching.
 *
 * @param {PointerEvent} e - DOM pointer down event.
 * @param {number} activePointerCount - Current number of active tracked pointers.
 * @returns {boolean} True if the pointer event should be ignored.
 *
 * @example
 * shouldIgnorePointerDown({ button: 1, pointerType: 'mouse' }, 0);
 * // => true
 *
 * @example
 * shouldIgnorePointerDown({ button: 0, pointerType: 'mouse', target: { closest: () => null } }, 0);
 * // => false
 */
function shouldIgnorePointerDown(e, activePointerCount) {
    if (e.button !== undefined && e.button !== 0 && e.pointerType === 'mouse') return true;
    if (activePointerCount === 0) {
        if (e.target?.closest?.('.interactive-element') || e.target?.closest?.('.person-node')) return true;
    }
    return false;
}

/**
 * Initializes single-pointer drag or two-pointer pinch gesture tracking state on pointer down.
 *
 * @param {Object} params
 * @param {PointerEvent} params.e - DOM pointer event.
 * @param {React.MutableRefObject<Map>} params.activePointersRef - Active pointers tracking map.
 * @param {React.MutableRefObject<Object>} params.pointerPinchRef - Ref tracking two-point pinch state.
 * @param {React.MutableRefObject<Object>} params.cameraRef - Ref storing latest camera position and zoom.
 * @param {Function} params.setIsDragging - Setter for dragging state boolean.
 * @param {Function} params.setDragStart - Setter for drag start anchor coordinates.
 *
 * @example
 * initializePointerGestureState({
 *   e: { clientX: 100, clientY: 200 },
 *   activePointersRef: { current: new Map([[1, { x: 100, y: 200 }]]) },
 *   pointerPinchRef: { current: null },
 *   cameraRef: { current: { x: 0, y: 0, z: 1 } },
 *   setIsDragging: () => {},
 *   setDragStart: () => {}
 * });
 *
 * @example
 * initializePointerGestureState({
 *   e: { clientX: 150, clientY: 250 },
 *   activePointersRef: { current: new Map([[1, { x: 100, y: 200 }], [2, { x: 150, y: 250 }]]) },
 *   pointerPinchRef: { current: null },
 *   cameraRef: { current: { x: 0, y: 0, z: 1 } },
 *   setIsDragging: () => {},
 *   setDragStart: () => {}
 * });
 */
function initializePointerGestureState({
    e,
    activePointersRef,
    pointerPinchRef,
    cameraRef,
    setIsDragging,
    setDragStart
}) {
    if (activePointersRef.current.size === 1) {
        setIsDragging(true);
        setDragStart({ x: e.clientX - cameraRef.current.x, y: e.clientY - cameraRef.current.y });
    } else if (activePointersRef.current.size === 2) {
        const [p1, p2] = Array.from(activePointersRef.current.values());
        const { dist, mid } = calculateTwoPointGeometry(p1, p2);
        pointerPinchRef.current = {
            dist,
            mid,
            cam: { ...cameraRef.current }
        };
    }
}

/**
 * Processes a pointer down event for the canvas, managing pointer capture, tracking active pointers,
 * single-pointer drag initialization, and two-pointer pinch gesture setup.
 *
 * @param {Object} options
 * @param {PointerEvent} options.e - Native DOM pointer down event.
 * @param {React.MutableRefObject<Map<number, {x: number, y: number}>>} options.activePointersRef - Active pointers tracking ref.
 * @param {React.MutableRefObject<Object|null>} options.pointerPinchRef - Multi-touch pinch state ref.
 * @param {React.MutableRefObject<Object>} options.cameraRef - Current camera state ref.
 * @param {Function} options.setIsDragging - State setter for isDragging boolean.
 * @param {Function} options.setDragStart - State setter for drag start coordinates.
 * @param {Function} [options.onInteract] - Callback invoked when interaction starts.
 *
 * @example
 *   processPointerDown({
 *     e: mockPointerEvent,
 *     activePointersRef: { current: new Map() },
 *     pointerPinchRef: { current: null },
 *     cameraRef: { current: { x: 0, y: 0, z: 1 } },
 *     setIsDragging: () => {},
 *     setDragStart: () => {},
 *     onInteract: () => {}
 *   });
 *
 * @example
 *   processPointerDown({
 *     e: touchPointerEvent,
 *     activePointersRef,
 *     pointerPinchRef,
 *     cameraRef,
 *     setIsDragging: setDragging,
 *     setDragStart: setStart
 *   });
 */
function processPointerDown({
    e,
    activePointersRef,
    pointerPinchRef,
    cameraRef,
    setIsDragging,
    setDragStart,
    onInteract
}) {
    if (shouldIgnorePointerDown(e, activePointersRef.current.size)) return;

    try {
        e.currentTarget.setPointerCapture(e.pointerId);
    } catch (err) {}

    activePointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    initializePointerGestureState({
        e,
        activePointersRef,
        pointerPinchRef,
        cameraRef,
        setIsDragging,
        setDragStart
    });

    if (onInteract) onInteract();
}

/**
 * Hook providing memoized pointer event callbacks for canvas drag and pinch gestures.
 *
 * @param {Object} params
 * @param {React.RefObject} params.activePointersRef - Active pointers tracking map ref.
 * @param {React.RefObject} params.pointerPinchRef - Pointer pinch state ref.
 * @param {React.RefObject} params.cameraRef - Current camera coordinates ref.
 * @param {Function} params.setIsDragging - Dragging state setter.
 * @param {Function} params.setDragStart - Drag start coordinates setter.
 * @param {boolean} params.isDragging - Whether dragging is active.
 * @param {{x: number, y: number}} params.dragStart - Drag start position.
 * @param {Function} params.onInteract - Interaction callback.
 * @param {React.RefObject} params.containerRef - Viewport container ref.
 * @param {Function} params.getBounds - Viewport bounds resolver.
 * @param {Function} params.getPpy - Current pixels-per-year resolver.
 * @param {Function} params.setCamera - Camera setter.
 * @param {Function} params.clampCamera - Camera clamping function.
 * @returns {{handlePointerDown: Function, handlePointerMove: Function, handlePointerUp: Function}}
 *
 * @example
 * const callbacks = useCanvasPointerCallbacks({ ...params });
 *
 * @example
 * const { handlePointerDown, handlePointerMove, handlePointerUp } = useCanvasPointerCallbacks({ ...params });
 */
function useCanvasPointerCallbacks({
    activePointersRef, pointerPinchRef, cameraRef, setIsDragging, setDragStart,
    isDragging, dragStart, onInteract, containerRef, getBounds, getPpy, setCamera, clampCamera
}) {
    const handlePointerDown = useCallback((e) => {
        processPointerDown({
            e, activePointersRef, pointerPinchRef, cameraRef,
            setIsDragging, setDragStart, onInteract
        });
    }, [onInteract, cameraRef]);
    
    const handlePointerMove = useCallback((e) => {
        processPointerMove({
            e, activePointersRef, pointerPinchRef, isDragging, dragStart,
            containerRef, getBounds, getPpy, setCamera, clampCamera
        });
    }, [isDragging, dragStart, clampCamera, getBounds, getPpy, setCamera, containerRef]);
    
    const handlePointerUp = useCallback((e) => {
        processPointerUp({
            e, activePointersRef, pointerPinchRef, cameraRef, setDragStart, setIsDragging
        });
    }, [cameraRef]);

    return { handlePointerDown, handlePointerMove, handlePointerUp };
}

/**
 * Custom hook to manage canvas pointer and wheel drag/pinch/zoom gestures.
 * Handles mouse and multi-touch pointer tracking, pinch-to-zoom calculation,
 * pointer capture lifecycle, and wheel-based zooming around cursor position.
 *
 * @param {Object} options
 * @param {Function} [options.onInteract] - Callback invoked whenever user gestures begin or zoom occurs.
 * @param {React.MutableRefObject<Object>} options.cameraRef - Ref storing the latest camera state {x, y, z}.
 * @param {Function} options.setCamera - React state setter for camera {x, y, z}.
 * @param {Function} options.clampCamera - Function to constrain camera coordinates within boundaries.
 * @param {Function} options.getBounds - Function to calculate canvas camera bounds for a given zoom level.
 * @param {Function} options.getPpy - Function to calculate pixels per year for a given zoom level.
 * @param {React.RefObject<HTMLElement>} options.containerRef - Ref to the canvas container element.
 * @returns {{
 *   isDragging: boolean,
 *   handlePointerDown: Function,
 *   handlePointerMove: Function,
 *   handlePointerUp: Function,
 *   handleWheel: Function
 * }}
 *
 * @example
 * const { isDragging, handlePointerDown, handlePointerMove, handlePointerUp, handleWheel } = useCanvasPointerGestures({
 *   onInteract: () => console.log('gesture started'),
 *   cameraRef,
 *   setCamera,
 *   clampCamera,
 *   getBounds,
 *   getPpy,
 *   containerRef
 * });
 *
 * @example
 * // Bind returned gesture event handlers to canvas viewport
 * <div
 *   ref={containerRef}
 *   onPointerDown={handlePointerDown}
 *   onPointerMove={handlePointerMove}
 *   onPointerUp={handlePointerUp}
 *   onWheel={handleWheel}
 * />
 */
function useCanvasPointerGestures({
    onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy, containerRef
}) {
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
    const activePointersRef = useRef(new Map());
    const pointerPinchRef = useRef(null);

    const { handlePointerDown, handlePointerMove, handlePointerUp } = useCanvasPointerCallbacks({
        activePointersRef, pointerPinchRef, cameraRef, setIsDragging, setDragStart,
        isDragging, dragStart, onInteract, containerRef, getBounds, getPpy, setCamera, clampCamera
    });

    const handleWheel = useCanvasWheelZoom({
        onInteract, containerRef, setCamera, clampCamera, getBounds, getPpy
    });

    return { isDragging, handlePointerDown, handlePointerMove, handlePointerUp, handleWheel };
}

/**
 * Calculates estimated vertical tree height in pixels based on generational span and target pixels-per-year.
 *
 * @param {Object|null} treeStats - Tree chronological and demographic statistics.
 * @param {number} targetPpy - Target pixels per year at current zoom.
 * @returns {number} Estimated height in pixels.
 *
 * @example
 * computeTreeSpanHeight({ minYear: 1900, maxYear: 2000, rootNodeYob: 1920 }, 15)
 * // => 1286
 *
 * @example
 * computeTreeSpanHeight(null, 15)
 * // => 836
 */
function computeTreeSpanHeight(treeStats, targetPpy) {
    const spanYears = treeStats && treeStats.minYear ? Math.max(5, treeStats.maxYear - treeStats.rootNodeYob) : 50;
    return (spanYears * targetPpy) + 86;
}

/**
 * Calculates bounding box and pan limits for the canvas camera based on container and tree dimensions.
 *
 * @param {Object} options
 * @param {HTMLElement|null} options.treeElement - The tree DOM element.
 * @param {HTMLElement|null} options.container - The container DOM element.
 * @param {boolean} options.isSidebarOpen - Whether the sidebar is expanded.
 * @param {number} options.sidebarWidth - Width of the sidebar in pixels.
 * @param {boolean} options.forceFullWindow - Whether to force measuring against the full window.
 * @param {Object|null} options.treeStats - Tree chronological and demographic stats.
 * @param {number} options.targetPpy - Pixels per year at current zoom.
 * @param {number} options.z - Current zoom scale factor.
 * @returns {Object} Camera bounds containing minX, maxX, minY, maxY, minZ, and centeredX.
 *
 * @example
 * calculateViewportCameraBounds({
 *   treeElement: null,
 *   container: null,
 *   isSidebarOpen: false,
 *   sidebarWidth: 360,
 *   forceFullWindow: false,
 *   treeStats: null,
 *   targetPpy: 10,
 *   z: 1
 * });
 *
 * @example
 * calculateViewportCameraBounds({
 *   treeElement: document.createElement('div'),
 *   container: document.createElement('div'),
 *   isSidebarOpen: true,
 *   sidebarWidth: 400,
 *   forceFullWindow: false,
 *   treeStats: { minYear: 1900, maxYear: 2000, rootNodeYob: 1920 },
 *   targetPpy: 15,
 *   z: 0.8
 * });
 */
function calculateViewportCameraBounds({
    treeElement, container, isSidebarOpen, sidebarWidth, forceFullWindow, treeStats, targetPpy, z
}) {
    if (!treeElement) return { minX: -5000, maxX: 5000, minY: -5000, maxY: 5000, minZ: 0.05, centeredX: 0 };

    const { contW, contH } = resolveViewportDimensions({ container, isSidebarOpen, sidebarWidth, forceFullWindow });
    const treeW = getTreeElementWidth(treeElement);
    const treeH = computeTreeSpanHeight(treeStats, targetPpy);

    // 48px left timeline generation bar offset (0 in standalone mode)
    const isStandalone = isStandaloneExportMode();
    const TIMELINE_WIDTH = isStandalone ? 0 : 48;

    return computeCameraBounds({ treeW, treeH, contW, contH, z, timelineWidth: TIMELINE_WIDTH });
}

/**
 * Clamps camera x, y, and z coordinates within computed viewport boundary constraints.
 *
 * @param {{x: number, y: number, z: number}} cam - Input camera coordinate vector.
 * @param {Function} getBounds - Function returning viewport boundaries for a given zoom level.
 * @returns {{x: number, y: number, z: number}} Clamped camera coordinate vector.
 *
 * @example
 * clampCameraCoordinates({ x: 100, y: 50, z: 1 }, (z) => ({ minX: 0, maxX: 500, minY: 0, maxY: 500, minZ: 0.1 }));
 *
 * @example
 * clampCameraCoordinates({ x: -1000, y: 10000, z: 0.01 }, (z) => ({ minX: -500, maxX: 500, minY: -500, maxY: 500, minZ: 0.05 }));
 */
function clampCameraCoordinates(cam, getBounds) {
    const bounds = getBounds(cam.z);
    const z = Math.max(bounds.minZ, Math.min(cam.z, 3)); 
    const finalBounds = getBounds(z);
    return {
        x: Math.max(finalBounds.minX, Math.min(finalBounds.maxX, cam.x)),
        y: Math.max(finalBounds.minY, Math.min(finalBounds.maxY, cam.y)),
        z
    };
}

/**
 * Hook providing dynamic pixels-per-year calculation, camera pan/zoom boundary computation,
 * and coordinate clamping for the interactive canvas viewport.
 *
 * @param {object} params
 * @param {object|null} params.treeStats - Tree generational statistics (minYear, maxYear, rootNodeYob)
 * @param {boolean} [params.isSidebarOpen=false] - Whether details sidebar is open
 * @param {number} [params.sidebarWidth=360] - Width of details sidebar in pixels
 * @param {React.RefObject} params.containerRef - Ref to outer canvas container DOM node
 * @param {React.RefObject} params.treeRef - Ref to inner tree element DOM node
 * @returns {{ getPpy: Function, getBounds: Function, clampCamera: Function }}
 *
 * @example
 *   const { getPpy, getBounds, clampCamera } = useCanvasCameraBounds({
 *       treeStats: { minYear: 1900, maxYear: 2020, rootNodeYob: 1900 },
 *       isSidebarOpen: false,
 *       sidebarWidth: 360,
 *       containerRef,
 *       treeRef
 *   });
 *
 * @example
 *   const { clampCamera } = useCanvasCameraBounds({
 *       treeStats: null,
 *       isSidebarOpen: true,
 *       sidebarWidth: 400,
 *       containerRef: { current: null },
 *       treeRef: { current: null }
 *   });
 */
function useCanvasCameraBounds({ treeStats, isSidebarOpen = false, sidebarWidth = 360, containerRef, treeRef }) {
    const getPpy = useCallback((z, forceFullWindow = false) => {
        const contH = (forceFullWindow || !isSidebarOpen) && typeof window !== 'undefined'
            ? window.innerHeight
            : (containerRef.current ? containerRef.current.clientHeight : (typeof window !== 'undefined' ? window.innerHeight : 800));
        return computeDynamicPpy(treeStats, contH, z);
    }, [treeStats, isSidebarOpen, containerRef]);

    const getBounds = useCallback((z, forceFullWindow = false) => {
        const targetPpy = getPpy(z, forceFullWindow);
        return calculateViewportCameraBounds({
            treeElement: treeRef.current,
            container: containerRef.current,
            isSidebarOpen,
            sidebarWidth,
            forceFullWindow,
            treeStats,
            targetPpy,
            z
        });
    }, [treeStats, getPpy, isSidebarOpen, sidebarWidth, containerRef, treeRef]);

    const clampCamera = useCallback((cam) => clampCameraCoordinates(cam, getBounds), [getBounds]);

    return { getPpy, getBounds, clampCamera };
}

/**
 * Calculates fit-to-screen metrics including timeline bar adjustments and usable viewport width.
 *
 * @param {Object} options
 * @param {HTMLElement|null} options.container - Canvas container element.
 * @param {boolean} options.isSidebarOpen - Whether sidebar is open.
 * @param {number} options.sidebarWidth - Sidebar width in pixels.
 * @param {boolean} options.forceFullWindow - Whether to force measuring full window.
 * @returns {Object} Framing layout metrics containing usableContW, timelineWidth, paddingX, topMargin.
 *
 * @example
 * resolveFitToScreenMetrics({ container: null, isSidebarOpen: false, sidebarWidth: 360, forceFullWindow: false });
 *
 * @example
 * resolveFitToScreenMetrics({ container: document.createElement('div'), isSidebarOpen: true, sidebarWidth: 400, forceFullWindow: true });
 */
function resolveFitToScreenMetrics({ container, isSidebarOpen, sidebarWidth, forceFullWindow }) {
    const { contW } = resolveViewportDimensions({
        container,
        isSidebarOpen,
        sidebarWidth,
        forceFullWindow
    });

    const isStandalone = isStandaloneExportMode();
    const TIMELINE_WIDTH = isStandalone ? 0 : 48;
    const usableContW = Math.max(100, contW - TIMELINE_WIDTH);
    return {
        usableContW,
        timelineWidth: TIMELINE_WIDTH,
        paddingX: 8,
        topMargin: 16
    };
}

/**
 * Computes and applies initial fit-to-screen camera framing, returning metrics for scheduling refinements.
 *
 * @param {Object} params
 * @param {HTMLElement} params.treeElement - DOM node containing the tree canvas.
 * @param {HTMLElement} params.container - Outer canvas container DOM element.
 * @param {boolean} [params.isSidebarOpen] - Whether details sidebar is open.
 * @param {number} [params.sidebarWidth] - Sidebar width in pixels.
 * @param {boolean} [params.forceFullWindow] - Whether to ignore sidebar width.
 * @param {Function} params.setCamera - State setter for camera coordinates.
 * @returns {Object|null} Resolved fit-to-screen metrics or null if tree width is non-positive.
 *
 * @example
 * const metrics = applyInitialFitToScreen({ treeElement, container, setCamera });
 *
 * @example
 * applyInitialFitToScreen({ treeElement, container, isSidebarOpen: true, sidebarWidth: 360, setCamera });
 */
function applyInitialFitToScreen({ treeElement, container, isSidebarOpen, sidebarWidth, forceFullWindow, setCamera }) {
    const treeW = getTreeElementWidth(treeElement);
    if (treeW <= 0) return null;

    const metrics = resolveFitToScreenMetrics({
        container,
        isSidebarOpen,
        sidebarWidth,
        forceFullWindow
    });

    setCamera(computeFitToScreenCamera({
        treeW,
        usableContW: metrics.usableContW,
        timelineWidth: metrics.timelineWidth,
        paddingX: metrics.paddingX,
        topMargin: metrics.topMargin
    }));

    return metrics;
}

/**
 * Calculates and applies fit-to-screen camera framing for the tree canvas.
 *
 * Resolves available viewport dimensions minus optional timeline rulers,
 * calculates zoom scale matching the tree element width, updates camera position,
 * and schedules secondary refinement checks for asynchronous rendering.
 *
 * @param {object} options - Framing configuration options.
 * @param {React.RefObject} options.treeRef - Ref to the inner tree container element.
 * @param {React.RefObject} options.containerRef - Ref to the outer canvas container.
 * @param {object|null} options.treeStats - Chronological stats and bounds of the active tree.
 * @param {boolean} options.isSidebarOpen - Whether the sidebar details panel is expanded.
 * @param {number} options.sidebarWidth - Width of the sidebar in pixels.
 * @param {boolean} [options.forceFullWindow=false] - Whether to ignore sidebar and measure full window.
 * @param {Function} options.setCamera - Camera state updater function.
 *
 * @example
 *   executeFitToScreen({
 *     treeRef,
 *     containerRef,
 *     treeStats: { rootNodeYob: 1900 },
 *     isSidebarOpen: true,
 *     sidebarWidth: 360,
 *     setCamera: () => {}
 *   });
 *
 * @example
 *   executeFitToScreen({
 *     treeRef: { current: null },
 *     containerRef: { current: null },
 *     treeStats: null,
 *     isSidebarOpen: false,
 *     sidebarWidth: 0,
 *     forceFullWindow: true,
 *     setCamera: () => {}
 *   });
 */
function executeFitToScreen({
    treeRef, containerRef, treeStats, isSidebarOpen, sidebarWidth, forceFullWindow = false, setCamera
}) {
    const treeElement = treeRef.current;
    const cont = containerRef.current;
    if (!treeElement || !cont || !treeStats) return;

    const metrics = applyInitialFitToScreen({
        treeElement, container: cont, isSidebarOpen, sidebarWidth, forceFullWindow, setCamera
    });
    if (!metrics) return;

    scheduleFitToScreenRefinement({
        treeRef, containerRef, setCamera, isSidebarOpen, sidebarWidth, forceFullWindow,
        timelineWidth: metrics.timelineWidth, paddingX: metrics.paddingX, topMargin: metrics.topMargin
    });
}

/**
 * Constructs viewport framing options for centering the camera on an individual person node.
 *
 * @param {number|null} targetZ - Preferred target zoom level, or null for automatic default.
 * @returns {Object} Camera framing polling options.
 *
 * @example
 * buildPersonCenterFramingOptions(1.2);
 *
 * @example
 * buildPersonCenterFramingOptions(null);
 */
function buildPersonCenterFramingOptions(targetZ = null) {
    return {
        preferredZ: targetZ,
        targetPadX: 0,
        targetPadY: 0,
        maxAttempts: 15,
        intervalMs: 40,
        initialDelay: 15
    };
}

/**
 * Hook providing viewport navigation and framing callbacks for focusing individuals,
 * multi-person clusters, and fitting the entire tree to the screen.
 *
 * @param {object} params
 * @param {React.RefObject<HTMLElement>} params.treeRef - Ref to the inner tree DOM node
 * @param {React.RefObject<HTMLElement>} params.containerRef - Ref to the outer canvas container DOM node
 * @param {object|null} params.treeStats - Generational metrics and bounds for fitting logic
 * @param {boolean} params.isSidebarOpen - Whether the sidebar panel is expanded
 * @param {number} params.sidebarWidth - Width in pixels allocated for the sidebar
 * @param {React.Dispatch<React.SetStateAction<object>>} params.setCamera - Camera state setter
 * @param {(cam: object) => object} params.clampCamera - Boundary clamping function
 * @returns {{
 *   framePeople: (ids: Array<string>, options?: object|null) => void,
 *   centerOnPerson: (id: string, targetZ?: number|null) => void,
 *   fitToScreen: (forceFullWindow?: boolean) => void
 * }}
 *
 * @example
 * const { framePeople, centerOnPerson } = useCanvasCameraFraming({
 *   treeRef,
 *   containerRef,
 *   treeStats,
 *   isSidebarOpen: false,
 *   sidebarWidth: 360,
 *   setCamera,
 *   clampCamera
 * });
 * centerOnPerson('person-123');
 *
 * @example
 * const { fitToScreen } = useCanvasCameraFraming({
 *   treeRef,
 *   containerRef,
 *   treeStats,
 *   isSidebarOpen: true,
 *   sidebarWidth: 400,
 *   setCamera,
 *   clampCamera
 * });
 * fitToScreen(true);
 */
function useCanvasCameraFraming({
    treeRef, containerRef, treeStats, isSidebarOpen, sidebarWidth, setCamera, clampCamera
}) {
    const framePeople = useCallback((ids, options = null) => {
        pollFramePeople({
            ids, options, treeRef, containerRef, isSidebarOpen, sidebarWidth, setCamera, clampCamera
        });
    }, [clampCamera, isSidebarOpen, sidebarWidth, treeRef, containerRef, setCamera]);

    const centerOnPerson = useCallback((id, targetZ = null) => {
        if (!id) return;
        framePeople([id], buildPersonCenterFramingOptions(targetZ));
    }, [framePeople]);

    const fitToScreen = useCallback((forceFullWindow = false) => {
        executeFitToScreen({
            treeRef, containerRef, treeStats, isSidebarOpen, sidebarWidth, forceFullWindow, setCamera
        });
    }, [treeStats, isSidebarOpen, sidebarWidth, setCamera, treeRef, containerRef]);

    return { framePeople, centerOnPerson, fitToScreen };
}

/**
 * Hook synchronizing canvas boundary clamping on layout changes, sidebar toggles,
 * and DOM resize observer events.
 *
 * @param {object} params
 * @param {React.Dispatch<React.SetStateAction<object>>} params.setCamera - Camera state setter
 * @param {(cam: object) => object} params.clampCamera - Boundary clamping function
 * @param {boolean} params.isSidebarOpen - Whether the sidebar is visible
 * @param {number} params.sidebarWidth - Width of the sidebar in pixels
 * @param {object|null} params.treeStats - Generational tree metrics
 * @param {React.RefObject<HTMLElement>} params.containerRef - Ref to container DOM node
 * @param {React.RefObject<HTMLElement>} params.treeRef - Ref to tree content DOM node
 *
 * @example
 * useCanvasAutoClamp({
 *   setCamera,
 *   clampCamera,
 *   isSidebarOpen: false,
 *   sidebarWidth: 360,
 *   treeStats,
 *   containerRef,
 *   treeRef
 * });
 *
 * @example
 * useCanvasAutoClamp({
 *   setCamera,
 *   clampCamera,
 *   isSidebarOpen: true,
 *   sidebarWidth: 420,
 *   treeStats: null,
 *   containerRef,
 *   treeRef
 * });
 */
function useCanvasAutoClamp({
    setCamera,
    clampCamera,
    isSidebarOpen,
    sidebarWidth,
    treeStats,
    containerRef,
    treeRef
}) {
    useEffect(() => {
        setCamera(cam => clampCamera(cam));
        const t1 = setTimeout(() => setCamera(cam => clampCamera(cam)), 100);
        const t2 = setTimeout(() => setCamera(cam => clampCamera(cam)), 350);
        return () => {
            clearTimeout(t1);
            clearTimeout(t2);
        };
    }, [isSidebarOpen, sidebarWidth, treeStats, clampCamera, setCamera]);

    useEffect(() => {
        return setupCanvasResizeObserver({
            containerRef,
            treeRef,
            setCamera,
            clampCamera
        });
    }, [clampCamera, containerRef, treeRef, setCamera]);
}

/**
 * Manages core camera coordinates state and a synchronized reference for gesture handlers.
 *
 * @returns {{ camera: { x: number, y: number, z: number }, setCamera: React.Dispatch<React.SetStateAction<{ x: number, y: number, z: number }>>, cameraRef: React.RefObject<{ x: number, y: number, z: number }> }}
 *
 * @example
 * const { camera, setCamera, cameraRef } = useCanvasCameraState();
 *
 * @example
 * const { camera } = useCanvasCameraState();
 */
function useCanvasCameraState() {
    const [camera, setCamera] = useState({ x: 0, y: 0, z: 1 });
    const cameraRef = useRef(camera);
    useEffect(() => {
        cameraRef.current = camera;
    }, [camera]);
    return { camera, setCamera, cameraRef };
}

/**
 * Synchronizes native mobile touch event listeners for pinch-to-zoom gestures on the canvas container.
 *
 * @param {Object} params
 * @param {React.RefObject<HTMLDivElement>} params.containerRef - Ref to interactive canvas container element.
 * @param {Function} [params.onInteract] - Optional interaction callback.
 * @param {React.RefObject<Object>} params.cameraRef - Ref storing current camera coordinates.
 * @param {Function} params.setCamera - State setter for camera coordinates.
 * @param {Function} params.clampCamera - Boundary clamping function.
 * @param {Function} params.getBounds - Function computing camera boundaries.
 * @param {Function} params.getPpy - Function returning current pixels-per-year.
 *
 * @example
 * useCanvasTouchLifecycle({ containerRef, onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy });
 *
 * @example
 * useCanvasTouchLifecycle({ containerRef, cameraRef, setCamera, clampCamera, getBounds, getPpy });
 */
function useCanvasTouchLifecycle({ containerRef, onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy }) {
    useEffect(() => {
        return setupCanvasTouchListeners({
            container: containerRef.current, onInteract, cameraRef,
            setCamera, clampCamera, getBounds, getPpy
        });
    }, [clampCamera, getBounds, getPpy, onInteract]);
}

/**
 * Hook providing comprehensive pan, zoom, pinch gestures, coordinate clamping,
 * and person/tree framing controls for the family tree interactive viewport.
 *
 * @param {Function} [onInteract] - Callback invoked when the user interacts with the canvas
 * @param {object} [treeStats] - Cached tree bounding dimensions and generation years
 * @param {boolean} [isSidebarOpen=false] - Whether the sidebar details panel is expanded
 * @param {number} [sidebarWidth=360] - Width of sidebar in pixels to adjust viewport padding
 * @returns {{
 *   camera: { x: number, y: number, z: number },
 *   setCamera: React.Dispatch<React.SetStateAction<{ x: number, y: number, z: number }>>,
 *   containerRef: React.RefObject<HTMLDivElement>,
 *   treeRef: React.RefObject<HTMLDivElement>,
 *   isDragging: boolean,
 *   handlePointerDown: Function,
 *   handlePointerMove: Function,
 *   handlePointerUp: Function,
 *   handleWheel: Function,
 *   fitToScreen: Function,
 *   framePeople: Function,
 *   zoomIn: Function,
 *   zoomOut: Function,
 *   resetZoom: Function,
 *   clampCamera: Function
 * }}
 *
 * @example
 * const canvas = useCanvasControls(handleUserInteraction, treeStats, isSidebarOpen, 360);
 *
 * @example
 * const { camera, setCamera, containerRef, treeRef, fitToScreen } = useCanvasControls();
 */
function useCanvasControls(onInteract, treeStats, isSidebarOpen = false, sidebarWidth = 360) {
    const { camera, setCamera, cameraRef } = useCanvasCameraState();
    const containerRef = useRef(null);
    const treeRef = useRef(null);

    const { getPpy, getBounds, clampCamera } = useCanvasCameraBounds({
        treeStats, isSidebarOpen, sidebarWidth, containerRef, treeRef
    });

    const gestures = useCanvasPointerGestures({
        onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy, containerRef
    });

    useCanvasTouchLifecycle({
        containerRef, onInteract, cameraRef, setCamera, clampCamera, getBounds, getPpy
    });

    const { framePeople, centerOnPerson, fitToScreen } = useCanvasCameraFraming({
        treeRef, containerRef, treeStats, isSidebarOpen, sidebarWidth, setCamera, clampCamera
    });

    useCanvasAutoClamp({
        setCamera, clampCamera, isSidebarOpen, sidebarWidth, treeStats, containerRef, treeRef
    });

    return {
        camera, setCamera, clampCamera, containerRef, treeRef,
        centerOnPerson, framePeople, fitToScreen, getPpy, ...gestures
    };
}

/**
 * Loads stored sidebar width from localStorage or falls back to initialWidth.
 * Clamps width between 280px and 1000px.
 *
 * @param {number} [initialWidth=360]
 * @returns {number}
 *
 * @example
 * loadStoredSidebarWidth(360)
 * // => 360
 *
 * @example
 * loadStoredSidebarWidth(400)
 * // => 400
 */
function loadStoredSidebarWidth(initialWidth = 360) {
    try {
        const saved = localStorage.getItem('familyTree_sidebarWidth');
        return saved ? Math.max(280, Math.min(parseInt(saved, 10), 1000)) : initialWidth;
    } catch (e) {
        return initialWidth;
    }
}

/**
 * Clamps dragged sidebar width within viewport bounds [280, windowWidth - 100].
 *
 * @param {number} startWidth - Initial sidebar width at drag start
 * @param {number} deltaX - Horizontal drag displacement (startX - clientX)
 * @param {number} [windowWidth] - Total window width (defaults to window.innerWidth)
 * @returns {number} Clamped sidebar width
 *
 * @example
 * clampSidebarWidth(360, 50, 1024)
 * // => 410
 *
 * @example
 * clampSidebarWidth(360, -200, 1024)
 * // => 280
 */
function clampSidebarWidth(startWidth, deltaX, windowWidth = (typeof window !== 'undefined' ? window.innerWidth : 1024)) {
    return Math.max(280, Math.min(startWidth + deltaX, windowWidth - 100));
}

/**
 * Attaches pointermove and pointerup listeners to resize and persist sidebar width during drag.
 *
 * @param {number} startX - Initial pointer X coordinate at drag start
 * @param {number} startWidth - Initial sidebar width in pixels
 * @param {Function} setSidebarWidth - State setter for sidebar width
 * @param {Function} setIsResizingSidebar - State setter for resizing flag
 *
 * @example
 * setupSidebarDragListeners(200, 360, setSidebarWidth, setIsResizingSidebar);
 *
 * @example
 * setupSidebarDragListeners(500, 420, (w) => console.log(w), (resizing) => {});
 */
function setupSidebarDragListeners(startX, startWidth, setSidebarWidth, setIsResizingSidebar) {
    const handlePointerMove = (moveEvent) => {
        const newWidth = clampSidebarWidth(startWidth, startX - moveEvent.clientX);
        setSidebarWidth(newWidth);
    };

    const handlePointerUp = (upEvent) => {
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        setIsResizingSidebar(false);

        const finalWidth = clampSidebarWidth(startWidth, startX - upEvent.clientX);
        try {
            localStorage.setItem('familyTree_sidebarWidth', String(Math.round(finalWidth)));
        } catch (err) {}
    };

    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
}

/**
 * Hook to manage sidebar width dragging, resizing constraints, cursor states,
 * and persistence to localStorage.
 *
 * @param {number} [initialWidth=360] - Default sidebar width in pixels
 * @returns {Object} { sidebarWidth, setSidebarWidth, isResizingSidebar, handleResizeStart }
 *
 * @example
 * const { sidebarWidth, isResizingSidebar, handleResizeStart } = useSidebarResize(360);
 *
 * @example
 * const { sidebarWidth, setSidebarWidth } = useSidebarResize();
 */
function useSidebarResize(initialWidth = 360) {
    const [sidebarWidth, setSidebarWidth] = useState(() => loadStoredSidebarWidth(initialWidth));
    const [isResizingSidebar, setIsResizingSidebar] = useState(false);

    const handleResizeStart = useCallback((e) => {
        e.preventDefault();
        e.stopPropagation();
        setIsResizingSidebar(true);
        setupSidebarDragListeners(e.clientX, sidebarWidth, setSidebarWidth, setIsResizingSidebar);
    }, [sidebarWidth]);

    return { sidebarWidth, setSidebarWidth, isResizingSidebar, handleResizeStart };
}

// ============================================================================
// MODULE 6: UI COMPONENTS (Presentational & Interactive)
// ============================================================================

/**
 * Resolves CSS theme classes (card background/border, date badge background, job text color)
 * based on person's gender.
 *
 * @param {string} [gender] - Gender code ('M', 'F', or undefined/other)
 * @returns {{ bgClass: string, dateBg: string, jobColor: string }}
 *
 * @example
 * getPersonCardTheme('M')
 * // => { bgClass: 'bg-sky-100 border-sky-300 text-sky-950', dateBg: 'bg-sky-200/80 text-sky-900', jobColor: 'text-sky-800' }
 *
 * @example
 * getPersonCardTheme('F')
 * // => { bgClass: 'bg-rose-100 border-rose-300 text-rose-950', dateBg: 'bg-rose-200/80 text-rose-900', jobColor: 'text-rose-800' }
 */
function getPersonCardTheme(gender) {
    if (gender === 'M') {
        return {
            bgClass: 'bg-sky-100 border-sky-300 text-sky-950',
            dateBg: 'bg-sky-200/80 text-sky-900',
            jobColor: 'text-sky-800'
        };
    }
    if (gender === 'F') {
        return {
            bgClass: 'bg-rose-100 border-rose-300 text-rose-950',
            dateBg: 'bg-rose-200/80 text-rose-900',
            jobColor: 'text-rose-800'
        };
    }
    return {
        bgClass: 'bg-slate-100 border-slate-300 text-slate-900',
        dateBg: 'bg-slate-300/50 text-slate-800',
        jobColor: 'text-slate-700'
    };
}

/**
 * Renders the birth/death date pill badge on a person card with deduced styling and tooltips.
 *
 * @param {Object} props
 * @param {Object} props.person - The person node instance
 * @param {string} props.dateBg - CSS background class for the date badge
 * @returns {React.ReactNode|null}
 *
 * @example
 * <PersonCardDateBadge person={person} dateBg="bg-sky-200/80 text-sky-900" />
 *
 * @example
 * <PersonCardDateBadge person={femaleNode} dateBg="bg-rose-200/80 text-rose-900" />
 */
const PersonCardDateBadge = React.memo(({ person, dateBg }) => {
    if (!person || (!person.yob && !person._inferredYob && !person.death)) return null;

    const cardInfo = typeof person.getCardDateString === 'function'
        ? person.getCardDateString()
        : null;
    const cardText = cardInfo?.cardText;
    if (!cardText) return null;

    return (
        <p
            className={`text-[9px] mt-1 font-semibold px-1 py-0.5 rounded shrink-0 border border-black/5 ${dateBg} ${cardInfo.isDeduced ? 'italic opacity-90' : ''}`}
            title={cardInfo.titleText}
        >
            {cardText}
        </p>
    );
});

/**
 * Collapse/expand toggle button anchored to the bottom border of a parent person card.
 *
 * @param {Object} props
 * @param {string} props.personId - The ID of the person to toggle
 * @param {boolean} props.isCollapsed - Whether the person's subtree is currently collapsed
 * @param {Function} props.onToggle - Callback invoked with personId when clicked
 * @returns {React.ReactNode}
 *
 * @example
 * <PersonCollapseButton personId="P1" isCollapsed={false} onToggle={layout.toggleCollapse} />
 *
 * @example
 * <PersonCollapseButton personId="P2" isCollapsed={true} onToggle={handleSubtreeToggle} />
 */
const PersonCollapseButton = React.memo(({ personId, isCollapsed, onToggle }) => (
    <button
        onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggle(personId); }}
        onPointerDown={(e) => e.stopPropagation()}
        className="absolute -bottom-2.5 left-1/2 -translate-x-1/2 z-30 w-5 h-5 bg-white border border-slate-300 rounded-full flex items-center justify-center text-slate-500 hover:text-blue-600 hover:border-blue-400 hover:bg-blue-50 transition-colors shadow-sm cursor-pointer interactive-element"
        title={isCollapsed ? "Expand branch" : "Collapse branch"}
    >
        {isCollapsed ? <Icons.Plus /> : <Icons.Minus />}
    </button>
));

/**
 * Resolves the CSS highlight and ring classes for a person card based on focus, AI highlight, and filter match state.
 *
 * @param {Object} params
 * @param {boolean} params.isFocused - Whether the person is currently focused
 * @param {boolean} params.isAiHighlighted - Whether the person is highlighted by AI chat
 * @param {boolean} params.isFilterHighlighted - Whether the person matches the active directory/search filter
 * @param {string} [params.filterHighlightClass] - Custom highlight ring class for the filter match
 * @returns {string} Tailwind CSS class string
 *
 * @example
 * resolvePersonHighlightClasses({ isFocused: true, isAiHighlighted: false, isFilterHighlighted: false })
 * // => 'ring-2 ring-blue-600 !border-blue-600 shadow-lg scale-105 z-30'
 *
 * @example
 * resolvePersonHighlightClasses({ isFocused: false, isAiHighlighted: true, isFilterHighlighted: false })
 * // => 'ai-profile-highlight ring-4 ring-blue-500 !border-blue-600 shadow-2xl !z-30'
 */
function resolvePersonHighlightClasses({ isFocused, isAiHighlighted, isFilterHighlighted, filterHighlightClass }) {
    if (isFocused) {
        return 'ring-2 ring-blue-600 !border-blue-600 shadow-lg scale-105 z-30';
    }
    if (isAiHighlighted) {
        return 'ai-profile-highlight ring-4 ring-blue-500 !border-blue-600 shadow-2xl !z-30';
    }
    if (isFilterHighlighted) {
        return `filter-match-highlight ${filterHighlightClass || 'ring-2 ring-blue-500 !border-blue-500'} shadow-lg scale-105 z-20`;
    }
    return 'hover:shadow-lg hover:scale-[1.02]';
}

/**
 * Renders the pulsing ✦ badge when a person card is highlighted by AI context.
 *
 * @returns {React.ReactNode} Pulsing AI highlight badge element
 *
 * @example
 * <PersonAiBadge />
 *
 * @example
 * {isAiHighlighted && <PersonAiBadge />}
 */
const PersonAiBadge = React.memo(() => (
    <span className="absolute -top-2.5 -right-2 flex h-5 w-5 z-30 pointer-events-none">
        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span>
        <span className="relative inline-flex rounded-full h-5 w-5 bg-gradient-to-tr from-blue-600 to-indigo-600 border-2 border-white items-center justify-center text-[9px] text-white font-black shadow-md">✦</span>
    </span>
));

/**
 * Renders an indicator badge in the top-left corner of a person card when
 * unexpanded family lineage exists for this person.
 *
 * @returns {React.ReactNode} Lineage indicator badge icon
 *
 * @example
 * <PersonHiddenLineageBadge />
 *
 * @example
 * {hasHiddenLineage && <PersonHiddenLineageBadge />}
 */
const PersonHiddenLineageBadge = React.memo(() => (
    <div className="absolute top-1 left-1 text-blue-600 bg-blue-100/90 border border-blue-200 p-[3px] rounded-md z-20 shadow-sm" title="Family lineage available. Click to view.">
        <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22V10"/><path d="M12 10 4 2"/><path d="M12 10l8-8"/><path d="M4 6V2h4"/><path d="M20 6V2h-4"/></svg>
    </div>
));

/**
 * Renders textual profile details (name, date badge, job, nickname, and location) inside a person node card.
 *
 * @param {object} props - Component properties.
 * @param {object} props.person - Person data record.
 * @param {string} props.dateBg - Tailwind background class for date badge.
 * @param {string} props.jobColor - Tailwind text color class for occupation label.
 * @returns {React.ReactElement} Bio details elements.
 *
 * @example
 * <PersonBioDetails person={samplePerson} dateBg="bg-blue-100" jobColor="text-blue-700" />
 *
 * @example
 * <PersonBioDetails person={{ name: 'John', _isUnknown: false }} dateBg="bg-slate-100" jobColor="text-slate-600" />
 */
const PersonBioDetails = React.memo(({ person, dateBg, jobColor }) => {
    const location = (person.place || person.location || '').trim();
    const hasLocation = Boolean(location && (typeof Person === 'undefined' || !Person.isInvalidLocation || !Person.isInvalidLocation(location)));

    return (
        <>
            <h3 className={`font-bold text-[11px] leading-[1.1] break-words w-full px-0.5 ${person._isUnknown ? 'italic opacity-60' : ''}`}>{person.name}</h3>
            <PersonCardDateBadge person={person} dateBg={dateBg} />
            {person.job && <p className={`text-[8.5px] font-medium leading-tight mt-1 shrink-0 break-words w-full ${jobColor}`}>{person.job}</p>}
            {!person.job && hasLocation && <p className="text-[8.5px] font-normal leading-tight mt-1 shrink-0 break-words w-full opacity-75" title={location}>{location}</p>}
            {person.nick && <p className="text-[8.5px] italic leading-tight mt-0.5 shrink-0 break-words w-full opacity-75">"{person.nick}"</p>}
            {person.job && !person.nick && hasLocation && <p className="text-[8.5px] font-normal leading-tight mt-0.5 shrink-0 break-words w-full opacity-75" title={location}>{location}</p>}
        </>
    );
});

/**
 * Interactive genealogical profile card component rendered inside the 2D tree canvas.
 * Displays person's name, deduced/known dates, occupations, nicknames, and branch collapse/expand triggers.
 *
 * @param {Object} props
 * @param {Object} props.person - The person node object to display
 * @param {boolean} [props.isPartner] - Whether this node is rendered as a spouse/partner
 * @param {Object} props.layout - Global layout config containing focusId, highlights, and callbacks
 * @param {boolean} [props.hasHiddenLineage] - Whether this person has an ancestor lineage that can be navigated
 * @param {boolean} [props.hasChildren] - Whether this person has biological/adopted children in the tree
 * @param {boolean} [props.isCollapsed] - Whether this person's descendant branch is currently folded
 * @returns {React.ReactNode|null}
 *
 * @example
 * <PersonNode
 *   person={personObj}
 *   isPartner={false}
 *   layout={{ focusId: 'P1', onFocus: (id) => {}, toggleCollapse: (id) => {} }}
 *   hasHiddenLineage={false}
 *   hasChildren={true}
 *   isCollapsed={false}
 * />
 *
 * @example
 * <PersonNode
 *   person={partnerObj}
 *   isPartner={true}
 *   layout={{ focusId: null, onFocus: fn, toggleCollapse: fn }}
 *   hasHiddenLineage={true}
 *   hasChildren={false}
 *   isCollapsed={false}
 * />
 */
const PersonNode = React.memo(({ person, isPartner, layout, hasHiddenLineage, hasChildren, isCollapsed }) => {
    if (!person) return null;
    const isFocused = layout.focusId === person.id;
    const isAiHighlighted = layout.aiHighlightedIds && layout.aiHighlightedIds.has(person.id);
    const isFilterHighlighted = Boolean(layout.filterHighlightedIds && layout.filterHighlightedIds.has(person.id));
    
    const { bgClass, dateBg, jobColor } = getPersonCardTheme(person.gender);
    const ghostStyles = person.isGhost ? '!border-dashed opacity-80 !shadow-none' : 'border-solid shadow-md';
    const highlightClasses = resolvePersonHighlightClasses({
        isFocused,
        isAiHighlighted,
        isFilterHighlighted,
        filterHighlightClass: layout.filterHighlightClass
    });

    return (
        <div 
            id={`node-${person.id}`}
            onClick={(e) => { e.stopPropagation(); layout.onFocus(person.id); }}
            className={`person-node whitespace-normal relative w-[90px] min-h-[76px] h-fit shrink-0 rounded-xl p-1.5 cursor-pointer transition-all duration-300 z-10 flex flex-col items-center justify-center text-center border-2 group
                ${highlightClasses}
                ${bgClass} ${ghostStyles}`}
        >
            {isAiHighlighted && <PersonAiBadge />}
            {hasHiddenLineage && <PersonHiddenLineageBadge />}
            <PersonBioDetails person={person} dateBg={dateBg} jobColor={jobColor} />
            {hasChildren && (
                <PersonCollapseButton 
                    personId={person.id} 
                    isCollapsed={isCollapsed} 
                    onToggle={layout.toggleCollapse} 
                />
            )}
        </div>
    );
});

// ============================================================================
// HIERARCHICAL 2D TREE LAYOUT ENGINE (Interval Profile Contour Compaction)
// ============================================================================

const TREE_NODE_WIDTH = 90;
const TREE_NODE_HEIGHT = 76;
const TREE_PARTNER_GAP = 10;
const TREE_PARTNER_TOTAL = TREE_NODE_WIDTH + TREE_PARTNER_GAP;
const TREE_SIBLING_GAP = 24;

/**
 * Centralized design tokens and layout geometry metrics for the genealogical tree visualization.
 */
const UI_THEME_METRICS = Object.freeze({
    nodeWidth: TREE_NODE_WIDTH,
    nodeHeight: TREE_NODE_HEIGHT,
    partnerGap: TREE_PARTNER_GAP,
    partnerTotal: TREE_PARTNER_TOTAL,
    siblingGap: TREE_SIBLING_GAP,
    cardPad: 10,
    timelineWidth: 48,
});
FamilyTree.UI_THEME_METRICS = UI_THEME_METRICS;
FamilyTreeBuilder.UI_THEME_METRICS = UI_THEME_METRICS;
FamilyTree.PersonBioDetails = PersonBioDetails;
if (typeof window !== 'undefined') {
    window.PersonBioDetails = PersonBioDetails;
}
/**
 * 2D Interval Profile Contour structure for non-overlapping spatial compaction of tree subtrees.
 * Discretizes subtree bounding boxes into 5px horizontal layers to compute minimum horizontal gaps.
 * 
 * @example
 * const c1 = new IntervalContour();
 * c1.addBox(0, 90, 0, 76);
 * const dist = c1.computeDistance(c2, 24);
 * 
 * @example
 * const c2 = c1.clone();
 * c2.shift(100);
 * c1.merge(c2);
 */
class IntervalContour {
    /**
     * Initializes an empty interval contour with an empty layer map.
     *
     * @example
     * const contour = new IntervalContour();
     *
     * @example
     * const subContour = new IntervalContour();
     */
    constructor() {
        this.layers = new Map(); // layerIdx (every 5px in Y) -> { minX, maxX }
    }

    /**
     * Computes the discretized start and end layer indices for a vertical coordinate span.
     *
     * @param {number} y1 - First vertical boundary
     * @param {number} y2 - Second vertical boundary
     * @returns {{ start: number, end: number }} Inclusive layer index range
     *
     * @example
     * IntervalContour._toLayerBounds(0, 76);
     * // => { start: -1, end: 16 }
     *
     * @example
     * IntervalContour._toLayerBounds(100, 150);
     * // => { start: 19, end: 30 }
     */
    static _toLayerBounds(y1, y2) {
        const start = Math.floor((Math.min(y1, y2) - 4) / 5);
        const end = Math.floor((Math.max(y1, y2) + 4) / 5);
        return { start, end };
    }

    /**
     * Updates or inserts a horizontal span for a specified layer index in the layers map.
     *
     * @param {Map<number, { minX: number, maxX: number }>} layers - The target layers map
     * @param {number} layerIdx - Discretized vertical layer index
     * @param {number} minX - Left horizontal coordinate
     * @param {number} maxX - Right horizontal coordinate
     *
     * @example
     * const layers = new Map();
     * IntervalContour._updateLayer(layers, 0, 10, 50);
     * // layers.get(0) => { minX: 10, maxX: 50 }
     *
     * @example
     * IntervalContour._updateLayer(layers, 0, 5, 60);
     * // layers.get(0) => { minX: 5, maxX: 60 }
     */
    static _updateLayer(layers, layerIdx, minX, maxX) {
        if (!layers.has(layerIdx)) {
            layers.set(layerIdx, { minX, maxX });
        } else {
            const cur = layers.get(layerIdx);
            cur.minX = Math.min(cur.minX, minX);
            cur.maxX = Math.max(cur.maxX, maxX);
        }
    }

    /**
     * Creates a deep clone of this contour with identical layer spans.
     *
     * @returns {IntervalContour} Cloned contour instance
     *
     * @example
     * const clone = contour.clone();
     *
     * @example
     * const c2 = new IntervalContour();
     * c2.addBox(10, 20, 30, 40);
     * const c3 = c2.clone();
     */
    clone() {
        const c = new IntervalContour();
        for (const [l, span] of this.layers.entries()) {
            c.layers.set(l, { minX: span.minX, maxX: span.maxX });
        }
        return c;
    }

    /**
     * Integrates a bounding box into this contour profile across its vertical layers.
     *
     * @param {number} x1 - First horizontal coordinate
     * @param {number} x2 - Second horizontal coordinate
     * @param {number} y1 - First vertical coordinate
     * @param {number} y2 - Second vertical coordinate
     *
     * @example
     * const c = new IntervalContour();
     * c.addBox(0, 90, 0, 76);
     *
     * @example
     * c.addBox(-45, 45, 100, 176);
     */
    addBox(x1, x2, y1, y2) {
        const { start, end } = IntervalContour._toLayerBounds(y1, y2);
        const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
        for (let l = start; l <= end; l++) {
            IntervalContour._updateLayer(this.layers, l, minX, maxX);
        }
    }

    /**
     * Shifts all layer spans horizontally by dx pixels.
     *
     * @param {number} dx - Horizontal displacement
     *
     * @example
     * contour.shift(50);
     *
     * @example
     * contour.shift(-25);
     */
    shift(dx) {
        if (!dx) return;
        for (const span of this.layers.values()) {
            span.minX += dx;
            span.maxX += dx;
        }
    }

    /**
     * Merges another interval contour into this contour by expanding layer spans.
     *
     * @param {IntervalContour} other - Contour to merge into this instance
     *
     * @example
     * c1.merge(c2);
     *
     * @example
     * const c3 = new IntervalContour();
     * c3.merge(c1);
     */
    merge(other) {
        if (!other) return;
        for (const [l, oSpan] of other.layers.entries()) {
            IntervalContour._updateLayer(this.layers, l, oSpan.minX, oSpan.maxX);
        }
    }

    /**
     * Computes the minimum horizontal shift required to position another contour to the right
     * of this contour without overlapping, maintaining at least minGap clearance.
     *
     * @param {IntervalContour} other - Contour to clear to the right
     * @param {number} [minGap=24] - Minimum clearance gap in pixels
     * @returns {number} Required horizontal offset
     *
     * @example
     * const dist = c1.computeDistance(c2, 24);
     *
     * @example
     * const gap = c1.computeDistance(c2);
     */
    computeDistance(other, minGap = 24) {
        if (!other) return minGap;
        let maxD = minGap;
        for (const [l, oSpan] of other.layers.entries()) {
            if (this.layers.has(l)) {
                const tSpan = this.layers.get(l);
                const req = tSpan.maxX - oSpan.minX + minGap;
                if (req > maxD) maxD = req;
            }
        }
        return maxD;
    }
}

/**
 * Computes spatial layout, node coordinates, partner alignments, and connector geometry for a family subtree.
 *
 * Recursively positions unit members (parents, partners, co-spouses) and child branches,
 * packing subtrees horizontally using IntervalContour clearance to prevent card and bus-bar overlaps.
 *
 * @param {Person} person - Subtree root person node
 * @param {FamilyTree} tree - Populated tree data model
 * @param {object} layoutConfig - Layout options (collapsed nodes, timeline scale, ppy, rootNodeYob)
 * @param {Set<string>} visitedSet - Set of visited node IDs to guard against cyclical graph loops
 * @param {number} [depth=0] - Recursion generation depth from tree root
 * @returns {object|null} Subtree layout structure containing members, child layouts, contours, and bounding box
 *
 * @example
 * const subtree = layoutSubtree(rootPerson, tree, layoutConfig, new Set());
 *
 * @example
 * const branch = layoutSubtree(childPerson, tree, layoutConfig, visitedSet, depth + 1);
 */
function layoutSubtree(person, tree, layoutConfig, visitedSet, depth = 0) {
    if (!person || visitedSet.has(person.id)) return null;

    const { siblingGap, branchGap, isCollapsed, nodeYob, targetY } = FamilyTree._computeSubtreeGeometry(person, tree, layoutConfig, depth);

    const localVisited = new Set(visitedSet);
    localVisited.add(person.id);

    const { partners, coSpouseEntries, partnerChildMap, isMultiSpouseSplit } =
        FamilyTree._resolveSubtreeUnitChildren(person, tree, layoutConfig, isCollapsed, localVisited);

    const sortedPartners = [...partners].sort((a, b) => a.bestYob - b.bestYob);

    const { familyMembers, bloodlineIndex } = FamilyTree._orderFamilyMembers(person, sortedPartners, coSpouseEntries, isMultiSpouseSplit);
    const isSyntheticSiblingUnit = familyMembers.length > 0 && familyMembers.every(m => FamilyTree.isSyntheticSiblingParent(m));

    // Map each member's info
    const memberLayouts = FamilyTree._buildMemberLayouts(
        familyMembers, bloodlineIndex, partnerChildMap, { nodeYob, targetY, isCollapsed, layoutConfig, tree }
    );

    const commonParams = { person, targetY, memberLayouts, tree, layoutConfig, localVisited, branchGap, depth };
    return !isMultiSpouseSplit
        ? FamilyTree._layoutSingleSpouseSubtree({ ...commonParams, bloodlineIndex, isSyntheticSiblingUnit })
        : FamilyTree._layoutMultiSpouseSubtree({ ...commonParams, siblingGap });
}

/**
 * Generates an SVG path string for connecting two adjacent spouses.
 * 
 * @param {number} x1 - Right edge of spouse 1 card
 * @param {number} y1 - Vertical midpoint of spouse 1 card
 * @param {number} x2 - Left edge of spouse 2 card
 * @param {number} y2 - Vertical midpoint of spouse 2 card
 * @returns {string} SVG path d attribute string
 *
 * @example
 * _generateSpouseBridgePath(100, 50, 120, 50);
 * // => "M 100 50 L 120 50"
 *
 * @example
 * _generateSpouseBridgePath(100, 50, 120, 70);
 * // => "M 100 50 C 110 50, 110 70, 120 70"
 */
function _generateSpouseBridgePath(x1, y1, x2, y2) {
    if (y1 === y2) {
        return `M ${x1} ${y1} L ${x2} ${y2}`;
    }
    const midX = (x1 + x2) / 2;
    return `M ${x1} ${y1} C ${midX} ${y1}, ${midX} ${y2}, ${x2} ${y2}`;
}

/**
 * Generates an SVG path string for a single child drop stem from parent bus bar down to child card top.
 * 
 * @param {number} parentDropX - Horizontal center of parent card
 * @param {number} busBarY - Bus bar horizontal line altitude
 * @param {number} childDropX - Horizontal center of child card
 * @param {number} childCardTopY - Top Y coordinate of child card
 * @returns {string} SVG path d attribute string
 *
 * @example
 * _generateSingleChildStemPath(100, 50, 100, 120);
 * // => "M 100 50 L 100 120"
 *
 * @example
 * _generateSingleChildStemPath(100, 50, 140, 120);
 * // => "M 100 50 L 132 50 Q 140 50 140 58 L 140 120"
 */
function _generateSingleChildStemPath(parentDropX, busBarY, childDropX, childCardTopY) {
    if (Math.abs(parentDropX - childDropX) < 1) {
        return `M ${parentDropX} ${busBarY} L ${childDropX} ${childCardTopY}`;
    }
    const isLeft = childDropX < parentDropX;
    const R = Math.min(8, Math.abs(parentDropX - childDropX) / 2, Math.max(0, (childCardTopY - busBarY) / 2));
    if (R > 0) {
        return `M ${parentDropX} ${busBarY} L ${childDropX + (isLeft ? R : -R)} ${busBarY} Q ${childDropX} ${busBarY} ${childDropX} ${busBarY + R} L ${childDropX} ${childCardTopY}`;
    }
    return `M ${parentDropX} ${busBarY} L ${childDropX} ${busBarY} L ${childDropX} ${childCardTopY}`;
}

/**
 * Generates an SVG path string for the multi-child rounded bus-bar.
 * 
 * @param {number} firstDropX - Center X of first (leftmost) child
 * @param {number} firstTopY - Top Y of first child card
 * @param {number} lastDropX - Center X of last (rightmost) child
 * @param {number} lastTopY - Top Y of last child card
 * @param {number} busBarY - Bus bar altitude
 * @returns {string} SVG path d attribute string
 *
 * @example
 * _generateBusBarPath(50, 120, 150, 120, 80);
 * // => "M 50 120 L 50 88 Q 50 80 58 80 L 142 80 Q 150 80 150 88 L 150 120"
 *
 * @example
 * _generateBusBarPath(100, 100, 100, 100, 100);
 * // => "M 100 100 L 100 100 L 100 100 L 100 100"
 */
function _generateBusBarPath(firstDropX, firstTopY, lastDropX, lastTopY, busBarY) {
    const R = Math.min(8, (lastDropX - firstDropX) / 2, Math.max(0, (firstTopY - busBarY) / 2), Math.max(0, (lastTopY - busBarY) / 2));
    if (R > 0) {
        return `M ${firstDropX} ${firstTopY} L ${firstDropX} ${busBarY + R} Q ${firstDropX} ${busBarY} ${firstDropX + R} ${busBarY} L ${lastDropX - R} ${busBarY} Q ${lastDropX} ${busBarY} ${lastDropX} ${busBarY + R} L ${lastDropX} ${lastTopY}`;
    }
    return `M ${firstDropX} ${firstTopY} L ${firstDropX} ${busBarY} L ${lastDropX} ${busBarY} L ${lastDropX} ${lastTopY}`;
}

/**
 * Flattens a recursive subtree layout hierarchy into flat node positioning records,
 * branch toggle buttons, SVG connection paths, and bounding box dimensions.
 *
 * @param {Object} rootSubtree - Root subtree layout node produced by layoutSubtree
 * @returns {{
 *   nodes: Array<Object>,
 *   buttons: Array<Object>,
 *   paths: Array<Object>,
 *   width: number,
 *   height: number,
 *   minX: number,
 *   minY: number
 * }}
 *
 * @example
 * const layout = flattenTreeLayout(rootSubtree);
 * console.log(layout.nodes.length, layout.width, layout.height);
 *
 * @example
 * const emptyLayout = flattenTreeLayout(null);
 * // => { nodes: [], buttons: [], paths: [], width: 0, height: 0, minX: 0, minY: 0 }
 */
function flattenTreeLayout(rootSubtree) {
    if (!rootSubtree) return { nodes: [], buttons: [], paths: [], width: 0, height: 0, minX: 0, minY: 0 };

    const nodes = [], buttons = [], paths = [];

    /**
     * Traverses member layouts recursively to collect positioned node cards and edge paths.
     *
     * @param {Object} sub - Subtree layout descriptor
     * @param {number} originX - Base horizontal offset coordinate
     *
     * @example
     * traverse(rootSubtree, 0);
     *
     * @example
     * traverse(childSubtree, 250);
     */
    function traverse(sub, originX) {
        FamilyTree._generateSpouseBridges(sub.memberLayouts, originX, sub.isSyntheticSiblingUnit, paths);
        sub.memberLayouts.forEach(mInfo => {
            const cardAbsX = originX + mInfo.cardX, cardAbsY = mInfo.targetY;
            if (!sub.isSyntheticSiblingUnit) {
                nodes.push(FamilyTree._buildFlattenedNode(mInfo, cardAbsX, cardAbsY));
            }
            FamilyTree._generateChildConnections({
                mInfo, originX, cardAbsX, cardAbsY, isSyntheticSiblingUnit: sub.isSyntheticSiblingUnit, paths, traverse
            });
        });
    }

    traverse(rootSubtree, 0);
    return { nodes, buttons, paths, ...FamilyTree._computeLayoutBounds(nodes, paths) };
}

FamilyTreeBuilder._computeLayoutFn = function(tree, layout) {
    if (!tree || !tree.root) return null;
    const normalized = FamilyTreeBuilder.normalizeLayoutConfig ? FamilyTreeBuilder.normalizeLayoutConfig(tree, layout) : layout;
    const sub = layoutSubtree(tree.root, tree, normalized, new Set());
    return flattenTreeLayout(sub);
};
FamilyTreeBuilder.computeLayout = FamilyTreeBuilder._computeLayoutFn;

/**
 * Renders the SVG connector layer containing orthogonal paths between ancestors, spouses, and descendants.
 *
 * @param {Object} props
 * @param {Array<{ d: string }>} props.paths - Array of path descriptors with SVG d path strings
 * @param {number} props.padX - Horizontal coordinate offset
 * @param {number} props.padY - Vertical coordinate offset
 * @param {number} props.totalW - Total canvas width in pixels
 * @param {number} props.totalH - Total canvas height in pixels
 * @returns {React.ReactNode}
 *
 * @example
 * <CompactTreeConnectorSvg paths={layoutData.paths} padX={10} padY={10} totalW={800} totalH={600} />
 *
 * @example
 * <CompactTreeConnectorSvg paths={[]} padX={0} padY={0} totalW={100} totalH={100} />
 */
const CompactTreeConnectorSvg = React.memo(({ paths, padX, padY, totalW, totalH }) => (
    <svg 
        className="absolute top-0 left-0 w-full h-full pointer-events-none z-0 overflow-visible"
        style={{ width: `${totalW}px`, height: `${totalH}px` }}
    >
        <g transform={`translate(${padX}, ${padY})`}>
            {paths.map((p, idx) => (
                <path 
                    key={`path-${idx}`} 
                    d={p.d} 
                    stroke="#cbd5e1" 
                    strokeWidth="2" 
                    fill="none" 
                    strokeLinecap="round"
                    strokeLinejoin="round"
                />
            ))}
        </g>
    </svg>
));

/**
 * Renders an absolutely positioned person card container within the compact tree canvas.
 *
 * @param {object} props
 * @param {object} props.node - Layout node containing person and coordinates
 * @param {number} props.padX - Horizontal canvas padding offset
 * @param {number} props.padY - Vertical canvas padding offset
 * @param {object} props.layout - Layout configuration and callbacks
 * @returns {React.ReactNode} Positioned node wrapper element
 *
 * @example
 * <CompactTreeNodeItem node={layoutNode} padX={10} padY={10} layout={layoutConfig} />
 *
 * @example
 * <CompactTreeNodeItem node={{ person: p, x: 100, y: 50 }} padX={0} padY={0} layout={layoutConfig} />
 */
const CompactTreeNodeItem = ({ node, padX, padY, layout }) => (
    <div 
        className="absolute z-10"
        style={{ left: `${node.x + padX}px`, top: `${node.y + padY}px` }}
    >
        <PersonNode 
            person={node.person} 
            isPartner={node.isPartner} 
            layout={layout} 
            hasHiddenLineage={node.hasHiddenLineage} 
            hasChildren={node.hasChildren}
            isCollapsed={node.isCollapsed}
        />
    </div>
);

/**
 * Renders the compact 2D SVG canvas layout of the genealogical tree,
 * containing orthogonal path connectors and positioned PersonNode cards.
 *
 * @param {Object} props
 * @param {FamilyTree} props.tree - The genealogical tree model
 * @param {Object} props.layout - Viewport layout state including focusId, collapse sets, and callbacks
 * @returns {React.ReactNode|null}
 *
 * @example
 * <CompactTreeView tree={familyTreeInstance} layout={layoutConfig} />
 *
 * @example
 * <CompactTreeView tree={tree} layout={{ focusId: 'p1', collapsedNodes: new Set() }} />
 */
const CompactTreeView = React.memo(({ tree, layout }) => {
    const layoutData = useMemo(() => {
        return FamilyTreeBuilder.computeLayout(tree, layout);
    }, [tree, layout]);

    if (!layoutData || layoutData.nodes.length === 0) return null;

    const CARD_PAD = 10;
    const padX = CARD_PAD - layoutData.minX;
    const padY = CARD_PAD - layoutData.minY;
    const totalW = layoutData.width + CARD_PAD * 2;
    const totalH = layoutData.height + CARD_PAD * 2;

    return (
        <div className="compact-tree-view relative" style={{ width: `${totalW}px`, height: `${totalH}px` }}>
            <CompactTreeConnectorSvg 
                paths={layoutData.paths}
                padX={padX}
                padY={padY}
                totalW={totalW}
                totalH={totalH}
            />

            {/* Person Card Nodes */}
            {layoutData.nodes.map(n => (
                <CompactTreeNodeItem 
                    key={n.person.id}
                    node={n}
                    padX={padX}
                    padY={padY}
                    layout={layout}
                />
            ))}
        </div>
    );
});


// ============================================================================
// GENEALOGY INFERENCE ENGINE (Instant, Deterministic Local Q&A)
// ============================================================================

/**
 * Local deterministic Q&A inference engine capable of directly parsing natural language
 * genealogical questions, resolving relationships, superlatives, occupations, and demographics.
 *
 * @example
 * const engine = new GenealogyEngine(familyTree);
 *
 * @example
 * const answer = engine.answer("Who is the oldest person in Kerala?");
 */
class GenealogyEngine {
    /**
     * Stop words filtered during entity extraction from natural language genealogical queries.
     * @type {Set<string>}
     */
    static QUERY_STOP_WORDS = new Set([
        'who', 'what', 'when', 'where', 'how', 'why', 'is', 'are', 'was', 'were', 'the', 'and', 'with', 'from', 'in', 'at', 'on', 'of', 'for', 'to',
        'has', 'have', 'had', 'his', 'her', 'their', 'its', 'starting', 'starts', 'start', 'begins', 'begin', 'letter', 'name', 'names',
        'husband', 'wife', 'spouse', 'partner', 'married', 'marry',
        'father', 'mother', 'parent', 'parents', 'dad', 'mom',
        'child', 'children', 'son', 'daughter', 'kids', 'kid',
        'sibling', 'siblings', 'brother', 'sister', 'brothers', 'sisters',
        'grandfather', 'grandmother', 'grandparent', 'grandparents', 'grandpa', 'grandma',
        'grandchild', 'grandchildren', 'grandson', 'granddaughter',
        'uncle', 'aunt', 'nephew', 'niece', 'cousin', 'cousins',
        'tell', 'about', 'find', 'show', 'list', 'related', 'relationship', 'between', 'tree', 'family',
        'born', 'died', 'lived', 'live', 'living', 'work', 'worked', 'job', 'career', 'place', 'location',
        'oldest', 'youngest', 'many', 'people', 'person'
    ]);

    /**
     * Vocabulary that signals a particular query intent, grouped by the question being asked.
     *
     * Extracted from long inline `q.includes(...) || q.includes(...)` chains so the vocabulary
     * for each intent can be read, extended, and reviewed as data rather than as control flow.
     *
     * @type {Object<string, ReadonlyArray<string>>}
     */
    static QUERY_INTENT_KEYWORDS = Object.freeze({
        // "who works as a nurse?" - profession lookups, including common professions by name.
        JOB: Object.freeze(['who', 'work', 'job', 'career', 'doctor', 'engineer', 'teacher', 'priest', 'nun', 'nurse', 'advocate', 'list']),
        // "who are in the Mechery family?" - family/branch membership lookups.
        FAMILY: Object.freeze(['family', 'members', 'branch', 'who is from', 'who are in']),
        // "who lived the longest?" - maximum lifespan.
        LONGEST_LIFESPAN: Object.freeze(['lived the longest', 'longest life', 'longest lifespan', 'maximum age']),
        // "who is the earliest ancestor?" - root of the pedigree.
        EARLIEST_ANCESTOR: Object.freeze(['earliest ancestor', 'first ancestor', 'root ancestor']),
        // Ambiguous phrasings that mean "earliest ancestor" only when not scoped to a place.
        OLDEST_PERSON: Object.freeze(['oldest person', 'oldest ancestor']),
        // "who is the oldest living person?" - superlative among the living.
        OLDEST_LIVING: Object.freeze(['oldest living', 'eldest living']),
        // "who is the youngest?" - most recent birth.
        YOUNGEST: Object.freeze(['youngest', 'latest birth', 'newest baby']),
        // "who has the most children?" - largest sibling group.
        MOST_CHILDREN: Object.freeze(['most children', 'largest family', 'most kids'])
    });

    /**
     * Reports whether a lowercased query mentions any phrase from a keyword list.
     *
     * @param {string} qLower - Lowercased query text
     * @param {ReadonlyArray<string>} keywords - Phrases that signal the intent
     * @returns {boolean} True when at least one phrase appears in the query
     *
     * @example
     * GenealogyEngine._mentionsAny('who are the nurses', GenealogyEngine.QUERY_INTENT_KEYWORDS.JOB);
     * // => true
     *
     * @example
     * GenealogyEngine._mentionsAny('show the tree', GenealogyEngine.QUERY_INTENT_KEYWORDS.YOUNGEST);
     * // => false
     */
    static _mentionsAny(qLower, keywords) {
        return keywords.some(keyword => qLower.includes(keyword));
    }

    /**
     * Creates a GenealogyEngine instance initialized with the given family tree.
     *
     * @param {Object} tree - Family tree instance
     *
     * @example
     * const engine = new GenealogyEngine(tree);
     *
     * @example
     * const localEngine = new GenealogyEngine(activeFamilyTree);
     */
    constructor(tree) {
        this.tree = tree;
    }

    /**
     * Normalizes a text string by lowercasing, stripping quotes, and removing punctuation.
     *
     * @param {string} str - Raw string to clean
     * @returns {string} Sanitized string
     *
     * @example
     * engine.clean("John's"); // => "johns"
     *
     * @example
     * engine.clean("Mary, Joseph!"); // => "mary  joseph"
     */
    clean(str) {
        if (!str) return '';
        return String(str)
            .toLowerCase()
            .replace(/["“”'‘’]/g, '')
            .replace(/[?.,!;:()\[\]{}]/g, ' ')
            .trim();
    }

    /**
     * Sorts an array of persons by birth year ascending, placing unknown birth years at the end.
     * 
     * @param {Object[]} people - List of person nodes
     * @returns {Object[]} Sorted list
     * 
     * @example
     * engine._sortByYob([{ yob: 1980 }, { yob: 1950 }]);
     * // => [{ yob: 1950 }, { yob: 1980 }]
     *
     * @example
     * engine._sortByYob([{ yob: null }, { yob: 1920 }]);
     * // => [{ yob: 1920 }, { yob: null }]
     */
    _sortByYob(people) {
        return people.sort((a, b) => (a.yob || 9999) - (b.yob || 9999));
    }

    /**
     * Searches for exact primary name or exact nickname matches.
     * 
     * @param {Object[]} all - All concrete persons
     * @param {string} q - Cleaned query name
     * @returns {Object[]} Matching persons or empty array
     * 
     * @example
     * engine._findExactNameOrNickMatches(allPeople, 'mary');
     *
     * @example
     * engine._findExactNameOrNickMatches(allPeople, 'unknown_name');
     * // => []
     */
    _findExactNameOrNickMatches(all, q) {
        const exactName = all.filter(p => this.clean(p.name) === q);
        const exactNick = all.filter(p => {
            if (this.clean(p.name) === q) return false;
            if (p.nick) {
                const nicks = p.nick.split(',').map(n => this.clean(n));
                return nicks.includes(q) || this.clean(p.nick) === q;
            }
            return false;
        });

        if (exactName.length > 0 || exactNick.length > 0) {
            return [...this._sortByYob(exactName), ...this._sortByYob(exactNick)];
        }
        return [];
    }

    /**
     * Searches for first-name, nickname token, or substring matches.
     * 
     * @param {Object[]} all - All concrete persons
     * @param {string} q - Cleaned query name
     * @returns {Object[]} Matching persons or empty array
     * 
     * @example
     * engine._findPartialOrSubstringMatches(allPeople, 'john');
     *
     * @example
     * engine._findPartialOrSubstringMatches(allPeople, 'paul');
     */
    _findPartialOrSubstringMatches(all, q) {
        const byFirst = all.filter(p => this.clean(p.name.split(/\s+/)[0]) === q);
        if (byFirst.length > 0) return this._sortByYob(byFirst);

        const byNickWord = all.filter(p => {
            if (!p.nick) return false;
            const nicks = p.nick.split(',').map(n => this.clean(n));
            return nicks.some(n => n.split(/\s+/).includes(q));
        });
        if (byNickWord.length > 0) return this._sortByYob(byNickWord);

        if (q.length >= 3) {
            const substring = all.filter(p => this.clean(p.name).includes(q) || (p.nick && this.clean(p.nick).includes(q)));
            return this._sortByYob(substring);
        }
        return [];
    }

    /**
     * Finds all concrete persons in the tree matching the given name query via exact, nickname, or partial match.
     *
     * @param {string} nameQuery - Name to search for
     * @returns {Object[]} Array of matching person nodes
     *
     * @example
     * const matches = engine.findAllMatchingPeople('Mary');
     *
     * @example
     * const empty = engine.findAllMatchingPeople('');
     * // => []
     */
    findAllMatchingPeople(nameQuery) {
        if (!nameQuery) return [];
        const q = this.clean(nameQuery);
        if (!q) return [];
        const all = this.tree.all.filter(p => !p.isGhost && !p._isUnknown);

        const exact = this._findExactNameOrNickMatches(all, q);
        if (exact.length > 0) return exact;

        return this._findPartialOrSubstringMatches(all, q);
    }

    /**
     * Normalizes query string for entity extraction by stripping possessives and punctuation,
     * returning non-stopword tokens.
     * 
     * @param {string} query - Natural language query
     * @returns {string[]} Candidate non-stop words
     * 
     * @example
     * engine._extractCandidateQueryWords("Who is Mary's son?");
     * // => ['mary']
     *
     * @example
     * engine._extractCandidateQueryWords("Tell me about George and Paul");
     * // => ['george', 'paul']
     */
    _extractCandidateQueryWords(query) {
        const normalized = String(query)
            .replace(/["“”'‘’]s\b/gi, ' ')
            .replace(/['’]s\b/gi, ' ')
            .replace(/["“”'‘’]/g, ' ')
            .replace(/[?.,!;:()\[\]{}]/g, ' ');
        const qClean = normalized.toLowerCase().trim();
        const words = qClean.split(/\s+/).filter(w => w.length >= 2);
        return words.filter(w => !GenealogyEngine.QUERY_STOP_WORDS.has(w));
    }

    /**
     * Extracts person domain entities referenced within a natural language query string.
     *
     * @param {string} query - Natural language query
     * @returns {Object[]} Unique matching person records
     *
     * @example
     * const people = engine.extractPeopleFromQuery("How is Paul related to John?");
     *
     * @example
     * const none = engine.extractPeopleFromQuery("");
     * // => []
     */
    extractPeopleFromQuery(query) {
        if (!query) return [];
        const candidateWords = this._extractCandidateQueryWords(query);
        const found = [];
        const addMatches = (matches) => {
            for (const m of matches) {
                if (!found.some(existing => existing.id === m.id)) {
                    found.push(m);
                }
            }
        };

        if (candidateWords.length > 1) {
            addMatches(this.findAllMatchingPeople(candidateWords.join(' ')));
        }
        for (const word of candidateWords) {
            addMatches(this.findAllMatchingPeople(word));
        }
        return found;
    }

    /**
     * Generates a markdown link string for a person profile node.
     *
     * @param {Object|null} person - Person node
     * @returns {string} Markdown link string or empty string
     *
     * @example
     * engine.link(personNode); // => "[Paul](P1)"
     *
     * @example
     * engine.link(null); // => ""
     */
    link(person) {
        if (!person) return '';
        return `[${person.name}](${person.id})`;
    }

    /**
     * Determines the relationship label if p1 and p2 are in a grandparent/grandchild relationship.
     * 
     * @param {Object} p1 - First person
     * @param {Object} p2 - Second person
     * @param {Object[]} p1Parents - Parents of p1
     * @returns {string|null} Formatted relationship string or null
     * 
     * @example
     * engine._getGrandparentRelationship(grandchild, grandpa, [father]);
     * // => "the grandchild of [Grandpa](id)"
     *
     * @example
     * engine._getGrandparentRelationship(unrelated1, unrelated2, []);
     * // => null
     */
    _getGrandparentRelationship(p1, p2, p1Parents) {
        for (const parent of p1Parents) {
            if (parent.momId === p2.id || parent.fatherId === p2.id) {
                return `the grandchild of ${this.link(p2)}`;
            }
        }
        for (const childId of p1.children) {
            const child = this.tree.get(childId);
            if (child && (child.children.includes(p2.id) || p2.momId === child.id || p2.fatherId === child.id)) {
                return `the grandparent of ${this.link(p2)}`;
            }
        }
        return null;
    }

    /**
     * Determines the relationship label if p1 and p2 are avuncular (uncle/aunt/nephew/niece) or first cousins.
     * 
     * @param {Object} p1 - First person
     * @param {Object} p2 - Second person
     * @param {Object[]} p1Parents - Parents of p1
     * @param {Object[]} p1Siblings - Siblings of p1
     * @returns {string|null} Formatted relationship string or null
     * 
     * @example
     * engine._getAvuncularOrCousinRelationship(nephew, uncle, [father], []);
     * // => "the niece/nephew of [Uncle](id)"
     *
     * @example
     * engine._getAvuncularOrCousinRelationship(cousin1, cousin2, [parent1], []);
     * // => "a first cousin of [Cousin2](id)"
     */
    _getAvuncularOrCousinRelationship(p1, p2, p1Parents, p1Siblings) {
        for (const parent of p1Parents) {
            const parentSiblings = this.tree.getSiblings(parent.id);
            if (parentSiblings.some(s => s.id === p2.id)) return `the niece/nephew of ${this.link(p2)}`;
        }
        for (const sib of p1Siblings) {
            if (sib.children.includes(p2.id)) return `the aunt/uncle of ${this.link(p2)}`;
        }
        for (const parent of p1Parents) {
            const parentSiblings = this.tree.getSiblings(parent.id);
            for (const pSib of parentSiblings) {
                if (pSib.children.includes(p2.id)) return `a first cousin of ${this.link(p2)}`;
            }
        }
        return null;
    }

    /**
     * Determines whether p1 and p2 share a direct nuclear relationship (spouse, parent, child, or sibling).
     *
     * @param {Object} p1 - First person
     * @param {Object} p2 - Second person
     * @param {Object[]} p1Siblings - Sibling profiles of p1
     * @returns {string|null} Formatted relationship string or null if not directly related
     *
     * @example
     *   _getDirectKinship(pSpouseA, pSpouseB, []) // "the spouse of [SpouseB](id)"
     * @example
     *   _getDirectKinship(pChild, pParent, []) // "the child of [Parent](id)"
     */
    _getDirectKinship(p1, p2, p1Siblings) {
        if (p1.partners.includes(p2.id) || p2.partners.includes(p1.id)) {
            return `the spouse of ${this.link(p2)}`;
        }
        if (p1.children.includes(p2.id) || p2.momId === p1.id || p2.fatherId === p1.id) {
            return `the parent of ${this.link(p2)}`;
        }
        if (p2.children.includes(p1.id) || p1.momId === p2.id || p1.fatherId === p2.id) {
            return `the child of ${this.link(p2)}`;
        }
        if (p1Siblings.some(s => s.id === p2.id)) {
            return `a sibling of ${this.link(p2)}`;
        }
        return null;
    }

    /**
     * Computes the human-readable genealogical kinship relationship from person p1 to person p2.
     *
     * @param {Object} p1 - First person node
     * @param {Object} p2 - Second person node
     * @returns {string} Human-readable relationship label
     *
     * @example
     * engine.getRelationship(childNode, parentNode);
     * // => "the child of [Parent](id)"
     *
     * @example
     * engine.getRelationship(personNode, personNode);
     * // => "the same person"
     */
    getRelationship(p1, p2) {
        if (p1.id === p2.id) return "the same person";

        const p1Siblings = this.tree.getSiblings(p1.id);
        const directRel = this._getDirectKinship(p1, p2, p1Siblings);
        if (directRel) return directRel;

        const p1Parents = [p1.momId, p1.fatherId].map(id => this.tree.get(id)).filter(Boolean);
        const grandparentRel = this._getGrandparentRelationship(p1, p2, p1Parents);
        if (grandparentRel) return grandparentRel;

        const collateralRel = this._getAvuncularOrCousinRelationship(p1, p2, p1Parents, p1Siblings);
        if (collateralRel) return collateralRel;

        return `related in the family tree to ${this.link(p2)}`;
    }

    /**
     * Resolves the primary subject person name to display in relationship query responses.
     * Extracts non-stop words from the query or defaults to the first matched person's name.
     *
     * @param {string} query - Raw natural language query
     * @param {Object[]} matchedPeople - Array of matched Person objects
     * @returns {string} Capitalized display query name
     *
     * @example
     *   _resolveDisplayQueryName("Who is Rosy's husband?", [{ name: 'Rosy' }]) // "Rosy"
     * @example
     *   _resolveDisplayQueryName("Tell me about George", [{ name: 'George' }]) // "George"
     */
    _resolveDisplayQueryName(query, matchedPeople) {
        const queryWords = this.clean(query).replace(/['’]s\b/gi, ' ').split(/\s+/).filter(w => w.length >= 2);
        const queryStopWords = new Set(['who', 'what', 'when', 'where', 'how', 'why', 'is', 'are', 'was', 'were', 'the', 'and', 'with', 'from', 'in', 'at', 'on', 'of', 'for', 'to', 'has', 'have', 'child', 'children', 'son', 'daughter', 'kids', 'husband', 'wife', 'spouse', 'partner', 'parents', 'father', 'mother', 'sibling', 'brother', 'sister']);
        const searchedName = queryWords.find(w => !queryStopWords.has(w)) || (matchedPeople.length > 0 ? matchedPeople[0].name : '');
        return searchedName ? (searchedName.charAt(0).toUpperCase() + searchedName.slice(1)) : (matchedPeople[0]?.name || '');
    }

    /**
     * Attempts to directly answer natural language genealogical questions without LLM invocation.
     * 
     * Supported query categories:
     * 1. Direct relationship between two people (e.g. "How is Paul related to John?")
     * 2. Location residents and superlatives (e.g. "Who is the oldest person in Palakkad?")
     * 3. Professions and occupations (e.g. "Who are the engineers?")
     * 4. Family branch membership (e.g. "Members of the Mechery family")
     * 5. Spousal queries (e.g. "Who is Rosy's husband?")
     * 6. Parental queries (e.g. "Who are Antu's parents?")
     * 7. Children and offspring (e.g. "Tell me about George's children")
     * 8. Sibling queries (e.g. "Who are Mary's siblings?")
     * 9. Grandparent queries (e.g. "Grandparents of Thomas")
     * 10. Superlatives across tree (e.g. "Oldest living person", "Longest lifespan")
     * 11. Calendar year inquiries (e.g. "Who was born in 1950?")
     * 12. Single person profile summaries (e.g. "Tell me about Joseph")
     * 13. Overall tree stats / count
     * 
     * @param {string} query - Natural language query string
     * @returns {string|null} Markdown-formatted direct answer or null
     *
     * @example
     * engine.tryDirectAnswer("Who is Rosy's husband?");
     * // => "**Rosy's** husband is Antu."
     * 
     * @example
     * engine.tryDirectAnswer("How is Paul related to John?");
     * // => "[Paul](id) is the brother of [John](id)."
     */
    tryDirectAnswer(query) {
        const q = (query || '').trim();
        const qLower = q.toLowerCase();
        if (!q) return null;

        const relAnswer = this._answerTwoPersonRelationship(qLower);
        if (relAnswer) return relAnswer;

        const matchedPeople = this.extractPeopleFromQuery(q);
        const person = matchedPeople.length > 0 ? matchedPeople[0] : null;
        const displayQueryName = this._resolveDisplayQueryName(q, matchedPeople);

        return this._answerLocationQuery(qLower) ||
               this._answerJobQuery(qLower) ||
               this._answerFamilyQuery(qLower) ||
               this._answerSpouseQuery(qLower, matchedPeople, displayQueryName) ||
               this._answerParentsQuery(qLower, matchedPeople, displayQueryName) ||
               this._answerChildrenQuery(qLower, matchedPeople, displayQueryName) ||
               this._answerSiblingsQuery(qLower, matchedPeople, displayQueryName) ||
               this._answerGrandparentsQuery(qLower, person) ||
               this._answerSuperlativeQuery(qLower) ||
               this._answerYearQuery(qLower) ||
               this._answerSinglePersonSummary(qLower, person) ||
               this._answerTreeStatsQuery(qLower) ||
               null;
    }

    /**
     * Answers queries determining the relationship between two explicitly named individuals.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Relationship answer string or null
     *
     * @example
     * engine._answerTwoPersonRelationship("how is paul related to john");
     *
     * @example
     * engine._answerTwoPersonRelationship("relationship between mary and rose");
     */
    _answerTwoPersonRelationship(qLower) {
        const relMatch = qLower.match(/(?:how is|relationship between|relate)\s+([a-zA-Z0-9\s]+?)\s+(?:related to|and|to)\s+([a-zA-Z0-9\s?]+)/i);
        if (relMatch) {
            const name1 = relMatch[1].replace(/['’]s|\?/g, '').trim();
            const name2 = relMatch[2].replace(/['’]s|\?/g, '').trim();
            const list1 = this.findAllMatchingPeople(name1);
            const list2 = this.findAllMatchingPeople(name2);
            if (list1.length > 0 && list2.length > 0) {
                const p1 = list1[0];
                const p2 = list2[0];
                return `${this.link(p1)} is ${this.getRelationship(p1, p2)}.`;
            }
        }
        return null;
    }

    /**
     * Searches for a matching entity attribute value (place, job, family) within a query string.
     * Values are prioritized by length descending to match specific multi-word phrases first.
     *
     * @param {string} attrName - Profile attribute property name (e.g. 'place', 'job', 'family')
     * @param {string} qLower - Lowercase normalized query string
     * @param {boolean} [matchPlural=false] - Whether to allow trailing plural suffixes ('s', 'es')
     * @returns {string|null} Matched attribute value or null
     *
     * @example
     * engine._matchAttributeInQuery('place', 'who lives in chalakudy');
     * // => 'Chalakudy'
     *
     * @example
     * engine._matchAttributeInQuery('job', 'who are the teachers', true);
     * // => 'Teacher'
     */
    _matchAttributeInQuery(attrName, qLower, matchPlural = false) {
        const values = Array.from(new Set(this.tree.all.map(p => p[attrName]).filter(Boolean).map(v => v.trim())));
        values.sort((a, b) => b.length - a.length);

        for (const val of values) {
            const valLower = val.toLowerCase();
            const escaped = valLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const pattern = matchPlural ? `\\b${escaped}(?:s|es)?\\b` : `\\b${escaped}\\b`;
            const regex = new RegExp(pattern, 'i');
            if (regex.test(qLower) || qLower.includes(valLower)) {
                return val;
            }
        }
        return null;
    }

    /**
     * Formats an AI assistant response identifying the oldest resident in a place along with any other residents.
     *
     * @param {string} matchedPlace - Name of the matched geographic location
     * @param {Array<Object>} residents - List of domain person objects residing in this place
     * @param {function(Object): string} linkFn - Markdown link formatter for person profiles
     * @returns {string} Formatted markdown response
     *
     * @example
     * GenealogyEngine._formatOldestResidentAnswer('Kottayam', residents, p => `[${p.name}](...)`);
     *
     * @example
     * GenealogyEngine._formatOldestResidentAnswer('Thrissur', [p1, p2], p => `[${p.name}](${p.id})`);
     */
    static _formatOldestResidentAnswer(matchedPlace, residents, linkFn) {
        const sortedOldest = [...residents].sort((a, b) => (a.yob || a._inferredYob || 9999) - (b.yob || b._inferredYob || 9999));
        const oldest = sortedOldest[0];
        const others = sortedOldest.slice(1);
        let resStr = `The oldest recorded person in **${matchedPlace}** is **${linkFn(oldest)}** (born in **${oldest.yob || 'unknown'}**${oldest.death ? `, d. ${oldest.death}` : ''}${oldest.job ? `, ${oldest.job}` : ''}${oldest.family ? `, ${oldest.family} family` : ''}).`;
        if (others.length > 0) {
            resStr += `\n\n**Other residents in ${matchedPlace} (${others.length}):**\n` + 
                others.map(p => `• **${linkFn(p)}**${p.yob ? ` (b. ${p.yob}${p.death ? ` - d. ${p.death}` : ''})` : ''}${p.job ? ` • ${p.job}` : ''}${p.family ? ` • ${p.family}` : ''}`).join('\n');
        }
        return resStr;
    }

    /**
     * Formats an AI assistant response identifying the youngest resident in a place along with any other residents.
     *
     * @param {string} matchedPlace - Name of the matched geographic location
     * @param {Array<Object>} residents - List of domain person objects residing in this place
     * @param {function(Object): string} linkFn - Markdown link formatter for person profiles
     * @returns {string} Formatted markdown response
     *
     * @example
     * GenealogyEngine._formatYoungestResidentAnswer('Chicago', residents, p => `[${p.name}](...)`);
     *
     * @example
     * GenealogyEngine._formatYoungestResidentAnswer('London', [youngest, older], p => `[${p.name}](${p.id})`);
     */
    static _formatYoungestResidentAnswer(matchedPlace, residents, linkFn) {
        const sortedYoungest = [...residents].sort((a, b) => (b.yob || b._inferredYob || -9999) - (a.yob || a._inferredYob || -9999));
        const youngest = sortedYoungest[0];
        const others = sortedYoungest.slice(1);
        let resStr = `The youngest recorded person in **${matchedPlace}** is **${linkFn(youngest)}** (born in **${youngest.yob || 'unknown'}**${youngest.job ? `, ${youngest.job}` : ''}${youngest.family ? `, ${youngest.family} family` : ''}).`;
        if (others.length > 0) {
            resStr += `\n\n**Other residents in ${matchedPlace} (${others.length}):**\n` + 
                others.map(p => `• **${linkFn(p)}**${p.yob ? ` (b. ${p.yob})` : ''}${p.job ? ` • ${p.job}` : ''}${p.family ? ` • ${p.family}` : ''}`).join('\n');
        }
        return resStr;
    }

    /**
     * Formats an AI assistant response listing all recorded residents of a location sorted by year of birth.
     *
     * @param {string} matchedPlace - Name of the matched geographic location
     * @param {Array<Object>} residents - List of domain person objects residing in this place
     * @param {function(Object): string} linkFn - Markdown link formatter for person profiles
     * @returns {string} Formatted markdown response
     *
     * @example
     * GenealogyEngine._formatAllResidentsAnswer('Pala', residents, p => `[${p.name}](...)`);
     *
     * @example
     * GenealogyEngine._formatAllResidentsAnswer('Seattle', [p1, p2], p => `[${p.name}](${p.id})`);
     */
    static _formatAllResidentsAnswer(matchedPlace, residents, linkFn) {
        const sorted = [...residents].sort((a, b) => (a.yob || 9999) - (b.yob || 9999));
        const list = sorted.map(p => `• **${linkFn(p)}**${p.yob ? ` (b. ${p.yob}${p.death ? ` - d. ${p.death}` : ''})` : ''}${p.job ? ` • ${p.job}` : ''}${p.family ? ` • ${p.family}` : ''}`).join('\n');
        return `Found **${residents.length}** person(s) recorded in **${matchedPlace}**:\n\n${list}`;
    }

    /**
     * Answers queries regarding residents or superlatives within a specific geographic place.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Markdown response or null if place not matched
     *
     * @example
     * engine._answerLocationQuery('who is the oldest person in thrissur');
     *
     * @example
     * engine._answerLocationQuery('who all are in chalakudy');
     */
    _answerLocationQuery(qLower) {
        const matchedPlace = this._matchAttributeInQuery('place', qLower);
        if (!matchedPlace) return null;

        const plLower = matchedPlace.toLowerCase();
        const residents = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.place && p.place.toLowerCase().includes(plLower));
        if (residents.length === 0) return null;

        if (qLower.includes('oldest') || qLower.includes('earliest') || qLower.includes('first') || qLower.includes('elder') || qLower.includes('eldest')) {
            return AIAssistant._formatOldestResidentAnswer(matchedPlace, residents, p => this.link(p));
        }

        if (qLower.includes('youngest') || qLower.includes('latest') || qLower.includes('newest')) {
            return AIAssistant._formatYoungestResidentAnswer(matchedPlace, residents, p => this.link(p));
        }

        return AIAssistant._formatAllResidentsAnswer(matchedPlace, residents, p => this.link(p));
    }

    /**
     * Answers queries inquiring about people working in a specific job or profession.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Markdown response listing workers or null
     *
     * @example
     * engine._answerJobQuery('who are the engineers');
     *
     * @example
     * engine._answerJobQuery('list doctors');
     */
    _answerJobQuery(qLower) {
        const matchedJob = this._matchAttributeInQuery('job', qLower, true);
        if (!matchedJob || !GenealogyEngine._mentionsAny(qLower, GenealogyEngine.QUERY_INTENT_KEYWORDS.JOB)) return null;

        const jLower = matchedJob.toLowerCase();
        const workers = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.job && p.job.toLowerCase().includes(jLower));
        if (workers.length === 0) return null;

        const list = workers.map(p => `• **${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''}${p.place ? ` • ${p.place}` : ''}${p.family ? ` • ${p.family}` : ''}`).join('\n');
        return `Found **${workers.length}** person(s) working as **${matchedJob}**:\n\n${list}`;
    }

    /**
     * Answers queries inquiring about members belonging to a specific family or branch.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Markdown response listing family members or null
     *
     * @example
     * engine._answerFamilyQuery('who are in the mechery family');
     *
     * @example
     * engine._answerFamilyQuery('members of the alappat family');
     */
    _answerFamilyQuery(qLower) {
        const matchedFamily = this._matchAttributeInQuery('family', qLower);
        if (!matchedFamily || !GenealogyEngine._mentionsAny(qLower, GenealogyEngine.QUERY_INTENT_KEYWORDS.FAMILY)) return null;

        const fLower = matchedFamily.toLowerCase();
        const members = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.family && p.family.toLowerCase().includes(fLower));
        if (members.length === 0) return null;

        const list = members.map(p => `• **${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''}${p.place ? ` • ${p.place}` : ''}${p.job ? ` • ${p.job}` : ''}`).join('\n');
        return `Found **${members.length}** member(s) of the **${matchedFamily}** family:\n\n${list}`;
    }

    /**
     * Formats a person label with nickname and birth year for query disambiguation lists.
     * 
     * @param {Object} p - Person node
     * @param {string} displayQueryName - Query search name for nickname comparison
     * @returns {string} Formatted label markdown
     * 
     * @example
     *   _formatPersonQueryLabel(person, 'John')
     *   // => "**[John Paul](id)** (b. 1960, \"Johnny\")"
     * 
     * @example
     *   _formatPersonQueryLabel(personWithNickMatch, 'Johnny')
     *   // => "**[John](id)** (aka \"Johnny\", b. 1960)"
     */
    _formatPersonQueryLabel(p, displayQueryName) {
        const isNickMatch = this.clean(p.name) !== this.clean(displayQueryName);
        return isNickMatch 
            ? `**${this.link(p)}** (aka "${p.nick}", b. ${p.yob || '?'})` 
            : `**${this.link(p)}** (b. ${p.yob || '?'}${p.nick ? `, "${p.nick}"` : ''})`;
    }

    /**
     * Answers queries about spouse or partners for a single matched individual.
     * 
     * @param {Object} p - Matched person record
     * @param {string} qLower - Lowercase query string
     * @returns {string} Formatted markdown response
     * 
     * @example
     *   _answerSinglePersonSpouseQuery(marriedPerson, 'who is the husband?')
     *   // => "**[Mary](id)'s** husband is [John](id)."
     * 
     * @example
     *   _answerSinglePersonSpouseQuery(unmarriedPerson, 'who is the spouse?')
     *   // => "**[Paul](id)** has no recorded spouse or partner in the family tree."
     */
    _answerSinglePersonSpouseQuery(p, qLower) {
        if (p.partners && p.partners.length > 0) {
            const spouses = p.partners.map(id => this.tree.get(id)).filter(Boolean);
            const label = spouses.length > 1 ? 'partners are' : (qLower.includes('husband') ? 'husband is' : (qLower.includes('wife') ? 'wife is' : 'spouse is'));
            return `**${this.link(p)}'s** ${label} ${spouses.map(s => this.link(s)).join(', ')}.`;
        }
        return `**${this.link(p)}** has no recorded spouse or partner in the family tree.`;
    }

    /**
     * Formats spouse information for multiple matched individuals sharing a query name.
     * 
     * @param {Object[]} matchedPeople - Matching person records
     * @param {string} displayQueryName - Query name for display
     * @returns {string} Formatted markdown list
     * 
     * @example
     *   _formatMultiPersonSpouseList([p1, p2], 'John')
     *   // => "Found **2** people matching \"**John**\":\n\n• ..."
     * 
     * @example
     *   _formatMultiPersonSpouseList([p1], 'Mary')
     *   // => "Found **1** people matching \"**Mary**\":\n\n• ..."
     */
    _formatMultiPersonSpouseList(matchedPeople, displayQueryName) {
        const results = matchedPeople.map(p => {
            const label = this._formatPersonQueryLabel(p, displayQueryName);
            if (p.partners && p.partners.length > 0) {
                const spouses = p.partners.map(id => this.tree.get(id)).filter(Boolean);
                return `• ${label}: Spouse is ${spouses.map(s => this.link(s)).join(', ')}`;
            }
            return `• ${label}: No spouse recorded.`;
        });
        return `Found **${matchedPeople.length}** people matching "**${displayQueryName}**":\n\n${results.join('\n')}`;
    }

    /**
     * Answers spousal queries (husband, wife, partner) for matched people.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object[]} matchedPeople - Array of matching Person objects
     * @param {string} displayQueryName - Query name for display
     * @returns {string|null} Markdown response or null
     *
     * @example
     * engine._answerSpouseQuery('who is rosy wife', [rosy], 'Rosy');
     *
     * @example
     * engine._answerSpouseQuery('husband of mary', [mary1, mary2], 'Mary');
     */
    _answerSpouseQuery(qLower, matchedPeople, displayQueryName) {
        if (qLower.includes('husband') || qLower.includes('wife') || qLower.includes('spouse') || qLower.includes('partner') || qLower.includes('married')) {
            if (matchedPeople.length === 1) {
                return this._answerSinglePersonSpouseQuery(matchedPeople[0], qLower);
            }
            if (matchedPeople.length > 1) {
                return this._formatMultiPersonSpouseList(matchedPeople, displayQueryName);
            }
        }
        return null;
    }

    /**
     * Answers parent queries for a single matched individual.
     *
     * @param {Object} p - Matched person record
     * @param {string} qLower - Lowercase query string
     * @returns {string} Formatted response
     *
     * @example
     * engine._answerSinglePersonParentsQuery(person, 'father of john');
     * // => "**[John](id)'s** father is [Dad](dadId)."
     *
     * @example
     * engine._answerSinglePersonParentsQuery(personWithoutParents, 'who are parents');
     * // => "**[John](id)** has no recorded parents in the tree."
     */
    _answerSinglePersonParentsQuery(p, qLower) {
        const mom = p.momId ? this.tree.get(p.momId) : null;
        const dad = p.fatherId ? this.tree.get(p.fatherId) : null;

        if (qLower.includes('father') || qLower.includes('dad')) {
            return dad ? `**${this.link(p)}'s** father is ${this.link(dad)}.` : `**${this.link(p)}'s** father is not recorded in the tree.`;
        }
        if (qLower.includes('mother') || qLower.includes('mom')) {
            return mom ? `**${this.link(p)}'s** mother is ${this.link(mom)}.` : `**${this.link(p)}'s** mother is not recorded in the tree.`;
        }

        const parents = [dad, mom].filter(Boolean);
        if (parents.length > 0) {
            return `**${this.link(p)}'s** parents are ${parents.map(par => this.link(par)).join(' and ')}.`;
        }
        return `**${this.link(p)}** has no recorded parents in the tree.`;
    }

    /**
     * Formats parent information for multiple matched individuals sharing a query name.
     * 
     * @param {Object[]} matchedPeople - Matching person records
     * @param {string} displayQueryName - Query name for display
     * @returns {string} Formatted markdown list
     *
     * @example
     * engine._formatMultiPersonParentsList([p1, p2], 'John');
     * // => "Found **2** people matching \"**John**\":\n\n• ..."
     *
     * @example
     * engine._formatMultiPersonParentsList([p1], 'Mary');
     * // => "Found **1** people matching \"**Mary**\":\n\n• ..."
     */
    _formatMultiPersonParentsList(matchedPeople, displayQueryName) {
        const results = matchedPeople.map(p => {
            const label = this._formatPersonQueryLabel(p, displayQueryName);
            const mom = p.momId ? this.tree.get(p.momId) : null;
            const dad = p.fatherId ? this.tree.get(p.fatherId) : null;
            const par = [dad, mom].filter(Boolean);
            if (par.length > 0) {
                return `• ${label}: Parents are ${par.map(pr => this.link(pr)).join(' and ')}`;
            }
            return `• ${label}: No parents recorded.`;
        });
        return `Found **${matchedPeople.length}** people matching "**${displayQueryName}**":\n\n${results.join('\n')}`;
    }

    /**
     * Answers queries about parents (mother, father, or both) for matched people.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object[]} matchedPeople - Array of matched person profiles
     * @param {string} displayQueryName - Query display name
     * @returns {string|null} Formatted response or null
     *
     * @example
     * engine._answerParentsQuery('who is father of antu', [antu], 'Antu');
     * // => "**[Antu](id)'s** father is [George](dadId)."
     *
     * @example
     * engine._answerParentsQuery('who are cousins of antu', [antu], 'Antu');
     * // => null
     */
    _answerParentsQuery(qLower, matchedPeople, displayQueryName) {
        if (qLower.includes('father') || qLower.includes('dad') || qLower.includes('mother') || qLower.includes('mom') || qLower.includes('parent')) {
            if (matchedPeople.length === 1) {
                return this._answerSinglePersonParentsQuery(matchedPeople[0], qLower);
            }
            if (matchedPeople.length > 1) {
                return this._formatMultiPersonParentsList(matchedPeople, displayQueryName);
            }
        }
        return null;
    }

    /**
     * Answers queries about children for a single matched individual.
     * 
     * @param {Object} p - Matched person record
     * @returns {string} Formatted markdown response
     * 
     * @example
     *   _answerSinglePersonChildrenQuery(personWithKids)
     *   // => "**[John](id)** (b. 1950) has **2** recorded children:\n\n• ..."
     * 
     * @example
     *   _answerSinglePersonChildrenQuery(personWithoutKids)
     *   // => "**[Mary](id)** (b. 1960) has no recorded children in the tree."
     */
    _answerSinglePersonChildrenQuery(p) {
        const children = (p.children || []).map(id => this.tree.get(id)).filter(Boolean);
        if (children.length > 0) {
            const list = children.map(c => `• ${this.link(c)}${c.yob ? ` (b. ${c.yob})` : ''}${c.job ? ` • ${c.job}` : ''}`).join('\n');
            return `**${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''} has **${children.length}** recorded child${children.length > 1 ? 'ren' : ''}:\n\n${list}`;
        }
        return `**${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''} has no recorded children in the tree.`;
    }

    /**
     * Formats children information for multiple matched individuals sharing a query name.
     * 
     * @param {Object[]} matchedPeople - Matching person records
     * @param {string} displayQueryName - Query name for display
     * @returns {string} Formatted markdown list
     * 
     * @example
     *   _formatMultiPersonChildrenList([p1, p2], 'John')
     *   // => "Found **2** people matching \"**John**\":\n\n• ..."
     * 
     * @example
     *   _formatMultiPersonChildrenList([p1], 'Mary')
     *   // => "Found **1** people matching \"**Mary**\":\n\n• ..."
     */
    _formatMultiPersonChildrenList(matchedPeople, displayQueryName) {
        const sections = matchedPeople.map(p => {
            const label = this._formatPersonQueryLabel(p, displayQueryName);
            const children = (p.children || []).map(id => this.tree.get(id)).filter(Boolean);
            if (children.length > 0) {
                const list = children.map(c => `  • ${this.link(c)}${c.yob ? ` (b. ${c.yob})` : ''}${c.job ? ` • ${c.job}` : ''}`).join('\n');
                return `• ${label} has **${children.length}** child${children.length > 1 ? 'ren' : ''}:\n${list}`;
            }
            return `• ${label} has no recorded children.`;
        });

        return `Found **${matchedPeople.length}** people matching "**${displayQueryName}**":\n\n${sections.join('\n\n')}`;
    }

    /**
     * Answers queries about children (sons, daughters, kids) for matched people.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object[]} matchedPeople - Array of matched person profiles
     * @param {string} displayQueryName - Query display name
     * @returns {string|null} Formatted response or null
     *
     * @example
     * engine._answerChildrenQuery('who are children of john', [john], 'John');
     * // => "**[John](id)** (b. 1950) has **2** recorded children:\n\n• ..."
     *
     * @example
     * engine._answerChildrenQuery('tell me about job', [john], 'John');
     * // => null
     */
    _answerChildrenQuery(qLower, matchedPeople, displayQueryName) {
        if (qLower.includes('child') || qLower.includes('son') || qLower.includes('daughter') || qLower.includes('kid')) {
            if (matchedPeople.length === 1) {
                return this._answerSinglePersonChildrenQuery(matchedPeople[0]);
            }
            if (matchedPeople.length > 1) {
                return this._formatMultiPersonChildrenList(matchedPeople, displayQueryName);
            }
        }
        return null;
    }

    /**
     * Answers queries about siblings for a single matched individual.
     * 
     * @param {Object} p - Matched person record
     * @returns {string} Formatted markdown response
     * 
     * @example
     *   _answerSinglePersonSiblingsQuery(personWithSibs)
     *   // => "**[John](id)** has **2** recorded siblings:\n\n• ..."
     * 
     * @example
     *   _answerSinglePersonSiblingsQuery(onlyChild)
     *   // => "**[Mary](id)** has no recorded siblings in the tree."
     */
    _answerSinglePersonSiblingsQuery(p) {
        const sibs = this.tree.getSiblings(p.id);
        if (sibs.length > 0) {
            const list = sibs.map(s => `• ${this.link(s)}${s.yob ? ` (b. ${s.yob})` : ''}`).join('\n');
            return `**${this.link(p)}** has **${sibs.length}** recorded sibling${sibs.length > 1 ? 's' : ''}:\n\n${list}`;
        }
        return `**${this.link(p)}** has no recorded siblings in the tree.`;
    }

    /**
     * Formats sibling information for multiple matched individuals sharing a query name.
     * 
     * @param {Object[]} matchedPeople - Matching person records
     * @param {string} displayQueryName - Query name for display
     * @returns {string} Formatted markdown list
     * 
     * @example
     *   _formatMultiPersonSiblingsList([p1, p2], 'John')
     *   // => "Found **2** people matching \"**John**\":\n\n• ..."
     * 
     * @example
     *   _formatMultiPersonSiblingsList([p1], 'Mary')
     *   // => "Found **1** people matching \"**Mary**\":\n\n• ..."
     */
    _formatMultiPersonSiblingsList(matchedPeople, displayQueryName) {
        const results = matchedPeople.map(p => {
            const label = this._formatPersonQueryLabel(p, displayQueryName);
            const sibs = this.tree.getSiblings(p.id);
            if (sibs.length > 0) {
                return `• ${label} has **${sibs.length}** sibling${sibs.length > 1 ? 's' : ''}: ${sibs.map(s => this.link(s)).join(', ')}`;
            }
            return `• ${label}: No siblings recorded.`;
        });
        return `Found **${matchedPeople.length}** people matching "**${displayQueryName}**":\n\n${results.join('\n')}`;
    }

    /**
     * Answers queries about siblings (brothers, sisters) for matched people.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object[]} matchedPeople - Array of matched person profiles
     * @param {string} displayQueryName - Query display name
     * @returns {string|null} Formatted response or null
     *
     * @example
     * engine._answerSiblingsQuery('who are siblings of mary', [mary], 'Mary');
     * // => "**[Mary](id)** has **2** recorded siblings:\n\n• ..."
     *
     * @example
     * engine._answerSiblingsQuery('who is spouse of mary', [mary], 'Mary');
     * // => null
     */
    _answerSiblingsQuery(qLower, matchedPeople, displayQueryName) {
        if (qLower.includes('sibling') || qLower.includes('brother') || qLower.includes('sister')) {
            if (matchedPeople.length === 1) {
                return this._answerSinglePersonSiblingsQuery(matchedPeople[0]);
            }
            if (matchedPeople.length > 1) {
                return this._formatMultiPersonSiblingsList(matchedPeople, displayQueryName);
            }
        }
        return null;
    }

    /**
     * Collects recorded grandparent profiles for a given person.
     *
     * @param {Object} person - Domain person profile
     * @returns {Object[]} List of grandparent Person profiles
     *
     * @example
     * engine._collectGrandparents(person);
     * // => [grandpaPerson, grandmaPerson]
     *
     * @example
     * engine._collectGrandparents(rootPerson);
     * // => []
     */
    _collectGrandparents(person) {
        if (!person) return [];
        const parents = [person.momId, person.fatherId].map(id => this.tree.get(id)).filter(Boolean);
        const grandparents = [];
        parents.forEach(p => {
            if (p.fatherId && this.tree.get(p.fatherId)) grandparents.push(this.tree.get(p.fatherId));
            if (p.momId && this.tree.get(p.momId)) grandparents.push(this.tree.get(p.momId));
        });
        return grandparents;
    }

    /**
     * Answers grandparent queries for a given person.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object|null} person - Target person profile
     * @returns {string|null} Formatted response or null if query does not match
     *
     * @example
     * engine._answerGrandparentsQuery('who are grandparents of thomas', thomasPerson);
     * // => "Recorded grandparents for **[Thomas](id)**:\n\n• ..."
     *
     * @example
     * engine._answerGrandparentsQuery('tell me about siblings', thomasPerson);
     * // => null
     */
    _answerGrandparentsQuery(qLower, person) {
        if (qLower.includes('grandparent') || qLower.includes('grandfather') || qLower.includes('grandmother') || qLower.includes('grandpa') || qLower.includes('grandma')) {
            if (person) {
                const grandparents = this._collectGrandparents(person);
                if (grandparents.length > 0) {
                    const list = grandparents.map(gp => `• ${this.link(gp)}`).join('\n');
                    return `Recorded grandparents for **${this.link(person)}**:\n\n${list}`;
                }
                return `No grandparents are recorded for **${this.link(person)}**.`;
            }
        }
        return null;
    }

    /**
     * Finds and summarizes the oldest living person in the tree.
     * 
     * @returns {string|null} Summary text or null
     *
     * @example
     * engine._getOldestLivingSummary();
     * // => "The oldest living person in the tree is **[Paul](id)** (born in **1930**, age **~96**)."
     *
     * @example
     * emptyEngine._getOldestLivingSummary();
     * // => null
     */
    _getOldestLivingSummary() {
        const currentYear = new Date().getFullYear();
        const living = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && !p.death && p.yob).sort((a, b) => a.yob - b.yob);
        if (living.length > 0) {
            const oldestLiving = living[0];
            const age = currentYear - oldestLiving.yob;
            return `The oldest living person in the tree is **${this.link(oldestLiving)}** (born in **${oldestLiving.yob}**, age **~${age}**${oldestLiving.place ? `, living in ${oldestLiving.place}` : ''}${oldestLiving.job ? `, ${oldestLiving.job}` : ''}).`;
        }
        return null;
    }

    /**
     * Finds and summarizes the person with the longest recorded lifespan.
     * 
     * @returns {string|null} Summary text or null
     *
     * @example
     * engine._getLongestLifespanSummary();
     * // => "The person with the longest recorded lifespan is **[Mary](id)** (1900 - 2005, **105 years**)."
     *
     * @example
     * emptyEngine._getLongestLifespanSummary();
     * // => null
     */
    _getLongestLifespanSummary() {
        const currentYear = new Date().getFullYear();
        const withAge = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.yob).map(p => {
            const span = p.death ? (p.death - p.yob) : (currentYear - p.yob);
            return { person: p, span };
        }).filter(item => item.span > 0 && item.span < 130).sort((a, b) => b.span - a.span);

        if (withAge.length > 0) {
            const top = withAge[0];
            return `The person with the longest recorded lifespan is **${this.link(top.person)}** (${top.person.yob}${top.person.death ? ` - ${top.person.death}` : ''}, **${top.span} years**).`;
        }
        return null;
    }

    /**
     * Finds and summarizes the earliest recorded ancestor.
     * 
     * @returns {string|null} Summary text or null
     *
     * @example
     * engine._getEarliestAncestorSummary();
     * // => "The earliest recorded ancestor is **[Joseph](id)** (born in **1850**)."
     *
     * @example
     * emptyEngine._getEarliestAncestorSummary();
     * // => null
     */
    _getEarliestAncestorSummary() {
        const pool = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.yob).sort((a, b) => a.yob - b.yob);
        if (pool.length > 0) {
            const target = pool[0];
            return `The earliest recorded ancestor is **${this.link(target)}** (born in **${target.yob}**${target.place ? `, living in ${target.place}` : ''}${target.job ? `, ${target.job}` : ''}).`;
        }
        return null;
    }

    /**
     * Finds and summarizes the youngest recorded person.
     * 
     * @returns {string|null} Summary text or null
     *
     * @example
     * engine._getYoungestPersonSummary();
     * // => "The youngest recorded person in the tree is **[Baby](id)** (born in **2024**)."
     *
     * @example
     * emptyEngine._getYoungestPersonSummary();
     * // => null
     */
    _getYoungestPersonSummary() {
        const sortedYoungest = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.yob).sort((a, b) => b.yob - a.yob);
        if (sortedYoungest.length > 0) {
            const youngest = sortedYoungest[0];
            return `The youngest recorded person in the tree is **${this.link(youngest)}** (born in **${youngest.yob}**${youngest.place ? `, in ${youngest.place}` : ''}).`;
        }
        return null;
    }

    /**
     * Finds and summarizes the person with the most children recorded.
     * 
     * @returns {string|null} Summary text or null
     *
     * @example
     * engine._getMostChildrenSummary();
     * // => "**[Father](id)** has the most recorded children (**12**):\n\n• ..."
     *
     * @example
     * emptyEngine._getMostChildrenSummary();
     * // => null
     */
    _getMostChildrenSummary() {
        const withKids = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.children && p.children.length > 0).sort((a, b) => b.children.length - a.children.length);
        if (withKids.length > 0) {
            const top = withKids[0];
            const kids = top.children.map(id => this.tree.get(id)).filter(Boolean);
            return `**${this.link(top)}** has the most recorded children (**${kids.length}**):\n\n` + kids.map(k => `• ${this.link(k)}`).join('\n');
        }
        return null;
    }

    /**
     * Dispatches superlative queries across the family tree (oldest living, longest lifespan, earliest ancestor, youngest, most children).
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Formatted answer or null
     *
     * @example
     * engine._answerSuperlativeQuery('who is oldest living person');
     * // => "The oldest living person in the tree is..."
     *
     * @example
     * engine._answerSuperlativeQuery('who has the most children');
     * // => "**[Father](id)** has the most recorded children..."
     */
    _answerSuperlativeQuery(qLower) {
        const INTENTS = GenealogyEngine.QUERY_INTENT_KEYWORDS;
        const mentions = keywords => GenealogyEngine._mentionsAny(qLower, keywords);

        if (mentions(INTENTS.OLDEST_LIVING)) return this._getOldestLivingSummary();
        if (mentions(INTENTS.LONGEST_LIFESPAN)) return this._getLongestLifespanSummary();

        // "oldest person" alone means the earliest ancestor, but "oldest person IN Kottayam" is a
        // place-scoped query that _answerLocationQuery owns, so the bare phrasing is excluded here.
        const isPlaceScoped = qLower.includes(' in ');
        if (mentions(INTENTS.EARLIEST_ANCESTOR) || (mentions(INTENTS.OLDEST_PERSON) && !isPlaceScoped)) {
            return this._getEarliestAncestorSummary();
        }

        if (mentions(INTENTS.YOUNGEST)) return this._getYoungestPersonSummary();
        if (mentions(INTENTS.MOST_CHILDREN)) return this._getMostChildrenSummary();
        return null;
    }

    /**
     * Formats an answer listing all individuals who passed away in the specified calendar year.
     *
     * @param {number} year - Four-digit calendar year
     * @returns {string|null} Formatted markdown list of deceased individuals or null if none
     *
     * @example
     *   _formatYearDiedAnswer(1985) // "Found **2** person(s) who passed away in **1985**:\n\n• **[John](id)** (b. 1910)"
     * @example
     *   _formatYearDiedAnswer(1750) // null
     */
    _formatYearDiedAnswer(year) {
        const diedList = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.death === year);
        if (diedList.length > 0) {
            return `Found **${diedList.length}** person(s) who passed away in **${year}**:\n\n` + diedList.map(p => `• **${this.link(p)}** (b. ${p.yob || '?'})`).join('\n');
        }
        return null;
    }

    /**
     * Formats an answer listing all individuals born in the specified calendar year.
     *
     * @param {number} year - Four-digit calendar year
     * @returns {string|null} Formatted markdown list of individuals born in that year or null if none
     *
     * @example
     *   _formatYearBornAnswer(1950) // "Found **1** person(s) born in **1950**:\n\n• **[Paul](id)** in Kochi • Engineer"
     * @example
     *   _formatYearBornAnswer(1700) // null
     */
    _formatYearBornAnswer(year) {
        const bornList = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p.yob === year);
        if (bornList.length > 0) {
            return `Found **${bornList.length}** person(s) born in **${year}**:\n\n` + bornList.map(p => `• **${this.link(p)}**${p.place ? ` in ${p.place}` : ''}${p.job ? ` • ${p.job}` : ''}`).join('\n');
        }
        return null;
    }

    /**
     * Answers queries asking who was born or passed away in a specific 4-digit calendar year.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Formatted answer or null
     *
     * @example
     * engine._answerYearQuery('who died in 1985');
     * // => "Found **2** person(s) who passed away in **1985**:\n\n• ..."
     *
     * @example
     * engine._answerYearQuery('who was born in 1950');
     * // => "Found **1** person(s) born in **1950**:\n\n• ..."
     */
    _answerYearQuery(qLower) {
        const yearMatch = qLower.match(/\b(18\d\d|19\d\d|20\d\d)\b/);
        if (yearMatch) {
            const year = parseInt(yearMatch[1], 10);
            if (qLower.includes('died') || qLower.includes('death')) {
                return this._formatYearDiedAnswer(year);
            }
            if (qLower.includes('born') || qLower.includes('birth')) {
                return this._formatYearBornAnswer(year);
            }
        }
        return null;
    }

    /**
     * Compiles an array of profile bullet points (lifespan, family, career, location, parents, spouses, children, siblings).
     * 
     * @param {Object} person - Target person node
     * @returns {string[]} Bullet lines describing person
     * 
     * @example
     *   _buildPersonSummaryDetails(person)
     *   // => ["• **Lifespan**: 1950 - 2020", "• **Career**: Engineer"]
     * 
     * @example
     *   _buildPersonSummaryDetails(childlessPerson)
     *   // => ["• **Lifespan**: 1990 - Present"]
     */
    _buildPersonSummaryDetails(person) {
        const { dateStr, extraStr } = person.getDateStrings();
        const parents = [person.fatherId, person.momId].map(id => this.tree.get(id)).filter(Boolean);
        const spouses = person.partners.map(id => this.tree.get(id)).filter(Boolean);
        const children = person.children.map(id => this.tree.get(id)).filter(Boolean);
        const sibs = this.tree.getSiblings(person.id);

        const details = [];
        if (dateStr) details.push(`• **Lifespan**: ${dateStr}${extraStr ? ` (${extraStr})` : ''}`);
        if (person.family) details.push(`• **Family**: ${person.family}`);
        if (person.job) details.push(`• **Career**: ${person.job}`);
        if (person.place) details.push(`• **Location**: ${person.place}`);
        if (parents.length > 0) details.push(`• **Parents**: ${parents.map(p => this.link(p)).join(', ')}`);
        if (spouses.length > 0) details.push(`• **Spouse**: ${spouses.map(s => this.link(s)).join(', ')}`);
        if (children.length > 0) details.push(`• **Children** (${children.length}): ${children.map(c => this.link(c)).join(', ')}`);
        if (sibs.length > 0) details.push(`• **Siblings** (${sibs.length}): ${sibs.map(s => this.link(s)).join(', ')}`);
        return details;
    }

    /**
     * Answers queries requesting a biographical summary/profile of a single individual.
     *
     * @param {string} qLower - Lowercase query string
     * @param {Object|null} person - Target person profile
     * @returns {string|null} Formatted markdown profile summary or null
     *
     * @example
     * engine._answerSinglePersonSummary('tell me about joseph', josephPerson);
     * // => "### [Joseph](id)\n\n• **Lifespan**: 1920 - 2010..."
     *
     * @example
     * engine._answerSinglePersonSummary('who are the engineers', null);
     * // => null
     */
    _answerSinglePersonSummary(qLower, person) {
        if (person && (qLower.startsWith('tell me about') || qLower.startsWith('who is') || qLower.startsWith('profile of')) && !qLower.includes(' and ')) {
            const details = this._buildPersonSummaryDetails(person);
            return `### ${this.link(person)}\n\n${details.join('\n')}`;
        }
        return null;
    }

    /**
     * Formats an overview summary of the entire family tree, including total individuals,
     * time span, and approximate number of generations.
     *
     * @returns {string} Markdown-formatted family tree overview summary
     *
     * @example
     *   _formatTreeOverviewSummary()
     *   // => "### Family Tree Overview\n\n• **Total Individuals**: 120 people..."
     *
     * @example
     *   _formatTreeOverviewSummary()
     *   // Returns structured stats markdown block
     */
    _formatTreeOverviewSummary() {
        const stats = this.tree.getStats();
        const total = this.tree.all.filter(p => !p.isGhost && !p._isUnknown).length;
        return `### Family Tree Overview\n\n• **Total Individuals**: ${total} people\n• **Time Span**: ${stats.minYear} – ${stats.maxYear}\n• **Generations**: ~${stats.generationsCount} generations`;
    }

    /**
     * Answers general family tree count and statistical summary queries.
     *
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Formatted markdown tree statistics or null
     *
     * @example
     * engine._answerTreeStatsQuery('how many people in the tree');
     * // => "### Family Tree Overview\n\n• **Total Individuals**: 120..."
     *
     * @example
     * engine._answerTreeStatsQuery('tell me about antu');
     * // => null
     */
    _answerTreeStatsQuery(qLower) {
        if (qLower.includes('how many') || qLower.includes('total') || qLower.includes('count') || qLower.includes('stats')) {
            return this._formatTreeOverviewSummary();
        }
        return null;
    }

    /**
     * Formats a markdown list of multiple matched people profiles with year of birth, place, and job.
     *
     * @param {Object[]} matchedPeople - Array of matched person records (3 or more)
     * @returns {string} Formatted markdown list of matched people
     *
     * @example
     *   _formatMultipleMatchedPeopleList([p1, p2, p3])
     *   // => "Found **3** people matching your query:\n\n• **[P1](id)** (b. 1950)..."
     *
     * @example
     *   _formatMultipleMatchedPeopleList(allPeople)
     *   // Returns list of all matching candidates
     */
    _formatMultipleMatchedPeopleList(matchedPeople) {
        const list = matchedPeople.map(p => `• **${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''}${p.place ? ` in ${p.place}` : ''}${p.job ? ` • ${p.job}` : ''}`).join('\n');
        return `Found **${matchedPeople.length}** people matching your query:\n\n${list}`;
    }

    /**
     * Answers queries referencing one, two, or multiple specific individuals.
     * 
     * @param {Object[]} matchedPeople - People matched in the query
     * @returns {string} Formatted response
     * 
     * @example
     * engine._answerMatchedPeopleQuery([p1]);
     * // => "Here is the record for [P1]..."
     *
     * @example
     * engine._answerMatchedPeopleQuery([p1, p2]);
     * // => "[P1] is the spouse of [P2]."
     */
    _answerMatchedPeopleQuery(matchedPeople) {
        if (matchedPeople.length === 1) {
            const person = matchedPeople[0];
            const details = this._buildPersonSummaryDetails(person);
            return `Here is the record for **${this.link(person)}** in the family tree:\n\n${details.join('\n')}`;
        }
        if (matchedPeople.length === 2) {
            const p1 = matchedPeople[0];
            const p2 = matchedPeople[1];
            return `**${this.link(p1)}** is ${this.getRelationship(p1, p2)}.`;
        }
        return this._formatMultipleMatchedPeopleList(matchedPeople);
    }

    /**
     * Checks if a query mentions a known attribute (e.g. location or job) and formats
     * a markdown bulleted list of matching individuals.
     *
     * @param {string} attrName - Target person attribute ('place' or 'job')
     * @param {string} qLower - Lowercase query string
     * @param {function(number, string): string} headerPattern - Header format callback before the list
     * @param {function(Person): string} secondaryInfoFormatter - Formatter for secondary attribute info
     * @returns {string|null} Markdown summary or null if no attribute matched
     *
     * @example
     *   engine._formatAttributeFallbackResponse('place', 'who is in thrissur', (count, val) => `Found **${count}** people in **${val}**:`, p => p.job ? ` • ${p.job}` : '')
     *   // => "Found **3** people in **Thrissur**:\n\n• **Alice**..."
     *
     * @example
     *   engine._formatAttributeFallbackResponse('job', 'who is a doctor', (count, val) => `Found **${count}** person(s) working as **${val}**:`, p => p.place ? ` in ${p.place}` : '')
     *   // => "Found **1** person(s) working as **Doctor**:\n\n• **Bob**..."
     */
    _formatAttributeFallbackResponse(attrName, qLower, headerPattern, secondaryInfoFormatter) {
        const values = Array.from(new Set(this.tree.all.map(p => p[attrName]).filter(Boolean).map(val => val.trim())));
        for (const val of values) {
            if (qLower.includes(val.toLowerCase())) {
                const matches = this.tree.all.filter(p => !p.isGhost && !p._isUnknown && p[attrName] && p[attrName].toLowerCase().includes(val.toLowerCase()));
                if (matches.length > 0) {
                    const list = matches.map(p => `• **${this.link(p)}**${p.yob ? ` (b. ${p.yob})` : ''}${secondaryInfoFormatter(p)}`).join('\n');
                    return `${headerPattern(matches.length, val)}\n\n${list}`;
                }
            }
        }
        return null;
    }

    /**
     * Checks if a query mentions a known location and returns matching residents.
     * 
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Residents summary or null
     *
     * @example
     *   engine._answerLocationFallback('who lives in thrissur')
     *   // => "Found **5** people in **Thrissur**:\n\n• **Alice**..."
     *
     * @example
     *   engine._answerLocationFallback('unknown place')
     *   // => null
     */
    _answerLocationFallback(qLower) {
        return this._formatAttributeFallbackResponse(
            'place',
            qLower,
            (count, val) => `Found **${count}** people in **${val}**:`,
            p => (p.job ? ` • ${p.job}` : '')
        );
    }

    /**
     * Checks if a query mentions a known profession and returns matching individuals.
     * 
     * @param {string} qLower - Lowercase query string
     * @returns {string|null} Workers summary or null
     *
     * @example
     *   engine._answerJobFallback('who works as engineer')
     *   // => "Found **2** person(s) working as **Engineer**:\n\n• **Bob**..."
     *
     * @example
     *   engine._answerJobFallback('astronaut')
     *   // => null
     */
    _answerJobFallback(qLower) {
        return this._formatAttributeFallbackResponse(
            'job',
            qLower,
            (count, val) => `Found **${count}** person(s) working as **${val}**:`,
            p => (p.place ? ` in ${p.place}` : '')
        );
    }

    /**
     * Builds the default guided response for unrecognized queries, describing total individuals,
     * generations, year bounds, and sample questions based on prominent places in the tree.
     *
     * @returns {string} Formatted markdown guided assistance summary
     *
     * @example
     *   _buildDefaultHelpfulSummary()
     *   // => "The family tree contains **120 individuals** across ~**4 generations**..."
     *
     * @example
     *   _buildDefaultHelpfulSummary()
     *   // Returns default query prompt suggestions
     */
    _buildDefaultHelpfulSummary() {
        const places = Array.from(new Set(this.tree.all.map(p => p.place).filter(Boolean).map(pl => pl.trim())));
        const stats = this.tree.getStats();
        const total = this.tree.all.filter(p => !p.isGhost && !p._isUnknown).length;
        return `The family tree contains **${total} individuals** across ~**${stats.generationsCount} generations** (${stats.minYear} – ${stats.maxYear}).\n\nTry asking:\n• *"Who is the oldest person in ${places[0] || 'the tree'}?"*\n• *"Who all are in ${places[1] || 'California'}?"*\n• *"Who are the children of Brijitha?"*\n• *"Who is the earliest ancestor?"*`;
    }

    /**
     * Resolves an answer for any natural language genealogical query using deterministic rules,
     * entity extraction, location/job matching, or default guided prompts.
     *
     * @param {string} query - Natural language query
     * @returns {string} Formatted markdown response
     *
     * @example
     * engine.fallbackAnswer('Who is Rosy\'s husband?');
     * // => "**Rosy's** husband is Antu."
     *
     * @example
     * engine.fallbackAnswer('unknown inquiry');
     * // => "The family tree contains **120 individuals**..."
     */
    fallbackAnswer(query) {
        const direct = this.tryDirectAnswer(query);
        if (direct) return direct;

        const q = (query || '').trim();
        const qLower = q.toLowerCase();
        
        // 1. Check if any people in tree are mentioned in query
        const matchedPeople = this.extractPeopleFromQuery(q);
        if (matchedPeople.length > 0) {
            return this._answerMatchedPeopleQuery(matchedPeople);
        }

        // 2. Check if any location is mentioned
        const locAnswer = this._answerLocationFallback(qLower);
        if (locAnswer) return locAnswer;

        // 3. Check if any job is mentioned
        const jobAnswer = this._answerJobFallback(qLower);
        if (jobAnswer) return jobAnswer;

        // 4. Default helpful tree summary
        return this._buildDefaultHelpfulSummary();
    }

    /**
     * Public entrypoint to query the genealogical engine for direct answers.
     *
     * @param {string} query - Natural language question
     * @returns {string} Answer response string
     *
     * @example
     * engine.answer('How many people in the tree?');
     * // => "### Family Tree Overview..."
     *
     * @example
     * engine.answer('Tell me about Joseph');
     * // => "### [Joseph](id)..."
     */
    answer(query) {
        return this.fallbackAnswer(query);
    }
}

/**
 * Extracts a lightweight, structured JSON-serializable context of all real family tree profiles.
 *
 * Excludes ghost and unknown nodes. Maps relatives to their names for prompt embedding.
 *
 * @param {FamilyTree} tree - Active family tree model
 * @returns {Array<Object>} Structured context array
 *
 * @example
 * const context = buildTreeAIContext(tree);
 * // => [{ id: 'Paul_1940_1', name: 'Paul', father: 'Joseph', ... }]
 *
 * @example
 * const emptyContext = buildTreeAIContext(null);
 * // => []
 */
function buildTreeAIContext(tree) {
    if (!tree || !tree.all) return [];
    return tree.all.filter(p => !p.isGhost && !p._isUnknown).map(p => ({
        id: p.id,
        name: p.name,
        nick: p.nick || undefined,
        gender: p.gender || undefined,
        yob: p.yob || p._inferredYob || undefined,
        death: p.death || undefined,
        age: p.age || (p.yob && !p.death ? (new Date().getFullYear() - p.yob) : undefined),
        family: p.family || undefined,
        job: p.job || undefined,
        place: p.place || undefined,
        father: tree.get(p.fatherId)?.name || undefined,
        mother: tree.get(p.momId)?.name || undefined,
        spouses: (p.partners || []).map(pid => tree.get(pid)?.name).filter(Boolean),
        children: (p.children || []).map(cid => tree.get(cid)?.name).filter(Boolean)
    }));
}

/**
 * Builds the system prompt grounding Gemini models in the active family tree dataset.
 *
 * @param {Array<Object>} treeContext - Structured tree context
 * @returns {string} System prompt string
 *
 * @example
 * const prompt = buildGenealogySystemPrompt(treeContext);
 *
 * @example
 * const emptyPrompt = buildGenealogySystemPrompt([]);
 */
function buildGenealogySystemPrompt(treeContext) {
    return `You are an expert genealogist answering questions about the user's family tree.
The entire family tree dataset is provided below as a structured JSON array of individual profiles.

Answer the user's question accurately, concisely, and insightfully based strictly on this dataset.
Do not hallucinate relationships or facts not in the tree.

CRITICAL INSTRUCTIONS FOR NAMES AND IDS:
Whenever you mention a specific person in your response, you MUST format their name as a markdown link using their exact "id" from the JSON as the URL.
Format: [Person Name](exact_id_here)
Example: [Nila](Nila_2015_92)
This allows the user to click any name to instantly highlight and focus their card in the interactive tree diagram.

Use **bold** for key facts, dates, and locations.
Use clean markdown bullet points when listing multiple individuals.

Family Tree Data:
${JSON.stringify(treeContext, null, 2)}`;
}

/**
 * Resolves priority endpoint URLs for Gemini API requests based on environment setting.
 *
 * @param {string} [envSetting='auto'] - 'auto' | 'prod'
 * @returns {Array<string>} Prioritized list of base API URLs
 *
 * @example
 * getGeminiEndpoints('auto');
 * // => ['https://generativelanguage.googleapis.com/v1beta']
 *
 * @example
 * getGeminiEndpoints('prod');
 * // => ['https://generativelanguage.googleapis.com/v1beta']
 */
function getGeminiEndpoints(envSetting = 'auto') {
    return ['https://generativelanguage.googleapis.com/v1beta'];
}

/**
 * Helper to render delimited inline markdown spans (e.g. bold or italic).
 *
 * @param {Array<string>} parts - Text split by delimiter regex
 * @param {Object} spanStyle - Span formatting specification ({ delimiter, className, tag })
 * @param {string} keyPrefix - React key prefix
 * @param {object} tree - Family tree model
 * @param {Function} onFocusPerson - Navigation callback
 * @returns {React.ReactNode[]} Rendered span elements
 *
 * @example
 * _renderDelimitedSpan(['**bold**'], { delimiter: '**', className: 'font-bold text-slate-900', tag: 'b' }, 'k1', tree, fn);
 * // => [<strong key="k1-b-0" className="...">bold</strong>]
 *
 * @example
 * _renderDelimitedSpan(['*italic*'], { delimiter: '*', className: 'italic text-slate-800', tag: 'i' }, 'k2', tree, fn);
 * // => [<em key="k2-i-0" className="...">italic</em>]
 */
function _renderDelimitedSpan(parts, spanStyle, keyPrefix, tree, onFocusPerson) {
    const { delimiter, className, tag } = spanStyle;
    const isStrong = tag === 'b';
    return parts.map((part, i) => {
        if (part.startsWith(delimiter) && part.endsWith(delimiter)) {
            const inner = part.slice(delimiter.length, -delimiter.length);
            const content = parseAiMarkdownText(inner, `${keyPrefix}-${tag}-${i}`, tree, onFocusPerson);
            return isStrong ? (
                <strong key={`${keyPrefix}-${tag}-${i}`} className={className}>{content}</strong>
            ) : (
                <em key={`${keyPrefix}-${tag}-${i}`} className={className}>{content}</em>
            );
        }
        return parseAiMarkdownText(part, `${keyPrefix}-t-${i}`, tree, onFocusPerson);
    });
}

/**
 * Parses and renders clickable person profile links from markdown link syntax.
 *
 * @param {Array<string>} linkParts - Text split by link regex
 * @param {string} keyPrefix - React key prefix
 * @param {object} tree - Family tree model
 * @param {Function} onFocusPerson - Navigation callback
 * @returns {React.ReactNode[]} Rendered link buttons or plain text fragments
 *
 * @example
 * _renderPersonLinks(['[George](p_123)'], 'k1', tree, fn);
 * // => [<button key="k1-l-0" ...>George</button>]
 *
 * @example
 * _renderPersonLinks(['plain text without link'], 'k2', tree, fn);
 * // => [<React.Fragment key="k2-frag-0">plain text without link</React.Fragment>]
 */
function _renderPersonLinks(linkParts, keyPrefix, tree, onFocusPerson) {
    return linkParts.map((part, i) => {
        const linkMatch = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
        if (linkMatch) {
            const linkText = linkMatch[1].replace(/\*/g, '');
            const targetId = linkMatch[2];
            const isValid = !!(tree && tree.get && tree.get(targetId));
            if (isValid && typeof onFocusPerson === 'function') {
                return (
                    <button
                        key={`${keyPrefix}-l-${i}`}
                        onClick={(e) => { e.preventDefault(); onFocusPerson(targetId); }}
                        className="inline text-blue-700 hover:text-blue-900 bg-blue-100/50 hover:bg-blue-200 px-1 rounded transition-colors font-semibold cursor-pointer align-baseline shadow-sm border border-blue-200/50"
                        title={`Focus on ${linkText}`}
                    >
                        {linkText}
                    </button>
                );
            }
            return <strong key={`${keyPrefix}-l-${i}`} className="text-slate-800 font-semibold">{linkText}</strong>;
        }
        return <React.Fragment key={`${keyPrefix}-frag-${i}`}>{part}</React.Fragment>;
    });
}

/**
 * Formats inline markdown styling (bold, italics, and person profile links).
 *
 * @param {string} text - Inline text content to format
 * @param {string} [keyPrefix=''] - Unique key prefix for React reconciliation
 * @param {object} [tree=null] - Family tree model to validate person IDs
 * @param {Function} [onFocusPerson=null] - Callback when person link is clicked
 * @returns {React.ReactNode} Formatted React elements or raw string
 *
 * @example
 * parseAiMarkdownText('**George** is the father of *Paul*', 'k1', tree, fn)
 * // => [<strong key="k1-b-0">George</strong>, ' is the father of ', <em key="k1-i-0">Paul</em>]
 *
 * @example
 * parseAiMarkdownText('Focus on [George](p_123)', 'k2', tree, fn)
 * // => ['Focus on ', <button key="k2-l-0" onClick=...>George</button>]
 */
function parseAiMarkdownText(text, keyPrefix = '', tree = null, onFocusPerson = null) {
    if (!text) return null;

    const boldParts = text.split(/(\*\*(?:.*?)\*\*)/g);
    if (boldParts.length > 1) {
        return _renderDelimitedSpan(boldParts, { delimiter: '**', className: 'font-bold text-slate-900', tag: 'b' }, keyPrefix, tree, onFocusPerson);
    }

    const italicParts = text.split(/(\*(?:.*?)\*)/g);
    if (italicParts.length > 1) {
        return _renderDelimitedSpan(italicParts, { delimiter: '*', className: 'italic text-slate-800', tag: 'i' }, keyPrefix, tree, onFocusPerson);
    }

    const linkParts = text.split(/(\[[^\]]+\]\([^)]+\))/g);
    if (linkParts.length > 1) {
        return _renderPersonLinks(linkParts, keyPrefix, tree, onFocusPerson);
    }

    return text;
}

/**
 * Renders a markdown header block with level-appropriate typography.
 *
 * @param {Array<string>} headerMatch - Regex match array for header
 * @param {number} lineIndex - Line index for keying
 * @param {Function} parseInlineText - Inline parser callback
 * @returns {React.ReactNode} Rendered header element
 *
 * @example
 * _renderMarkdownHeader(['# Header', '#', 'Header'], 0, parseFn);
 * // => <div key="h-0" className="...">Header</div>
 *
 * @example
 * _renderMarkdownHeader(['## Subtitle', '##', 'Subtitle'], 1, parseFn);
 * // => <div key="h-1" className="...">Subtitle</div>
 */
function _renderMarkdownHeader(headerMatch, lineIndex, parseInlineText) {
    const level = headerMatch[1].length;
    const content = parseInlineText(headerMatch[2], `line-${lineIndex}`);
    let headerClass = "font-bold text-slate-800 mb-2 mt-3";
    if (level === 1) headerClass += " text-lg border-b pb-1";
    else if (level === 2) headerClass += " text-[15px]";
    else headerClass += " text-[14px]";
    return <div key={`h-${lineIndex}`} className={headerClass}>{content}</div>;
}

/**
 * Renders a markdown list item with nested indentation styling.
 *
 * @param {Array<string>} listMatch - Regex match array for list item
 * @param {number} lineIndex - Line index for keying
 * @param {Function} parseInlineText - Inline parser callback
 * @returns {React.ReactNode} Rendered <li> element
 *
 * @example
 * _renderMarkdownListItem(['* Item', '', 'Item'], 0, parseFn);
 * // => <li key="li-0" className="...">...</li>
 *
 * @example
 * _renderMarkdownListItem(['  * Subitem', '  ', 'Subitem'], 1, parseFn);
 * // => <li key="li-1" className="...">...</li>
 */
function _renderMarkdownListItem(listMatch, lineIndex, parseInlineText) {
    const isNested = listMatch[1].length > 0;
    const className = `leading-relaxed ${isNested ? 'ml-5 list-[circle] text-[13px] text-slate-700 my-0.5' : 'font-medium mt-1.5 pl-1'}`;
    return (
        <li key={`li-${lineIndex}`} className={className}>
            {parseInlineText(listMatch[2], `line-${lineIndex}`)}
        </li>
    );
}

/**
 * Renders a non-list markdown line as either a header or paragraph element.
 *
 * @param {string} line - Raw markdown line text
 * @param {number} lineIndex - Line index for key generation
 * @param {Function} parseInlineText - Inline parser function
 * @returns {React.ReactNode} Rendered React element
 *
 * @example
 * _renderMarkdownNonListElement('## Title', 2, parseFn);
 * // => <div key="h-2" ...>Title</div>
 *
 * @example
 * _renderMarkdownNonListElement('Regular paragraph text', 3, parseFn);
 * // => <div key="p-3" ...>Regular paragraph text</div>
 */
function _renderMarkdownNonListElement(line, lineIndex, parseInlineText) {
    const headerMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headerMatch) {
        return _renderMarkdownHeader(headerMatch, lineIndex, parseInlineText);
    }
    return (
        <div key={`p-${lineIndex}`} className="mb-2 last:mb-0 leading-relaxed">
            {parseInlineText(line, `line-${lineIndex}`)}
        </div>
    );
}

/**
 * Transforms a multi-line markdown message into formatted headings, lists, and paragraphs.
 *
 * @param {string} text - Multiline response text from assistant or user
 * @param {Function} parseInlineText - Function to parse inline formatting within each block
 * @returns {React.ReactNode[]} Array of structured React elements
 *
 * @example
 * renderAiMarkdownMessage('# Header\n* Item 1\n* Item 2', parseFn);
 * // => [<div key="h-0" className="...">Header</div>, <ul key="ul-end" className="...">...</ul>]
 *
 * @example
 * renderAiMarkdownMessage('Single body paragraph', parseFn);
 * // => [<div key="p-0" className="...">Single body paragraph</div>]
 */
function renderAiMarkdownMessage(text, parseInlineText) {
    const lines = (text || '').split('\n');
    const elements = [];
    let inList = false;
    let listItems = [];
    const flushList = (key) => {
        if (inList) {
            elements.push(<ul key={key} className="list-disc pl-5 mb-2 space-y-1">{listItems}</ul>);
            listItems = [];
            inList = false;
        }
    };
    lines.forEach((line, i) => {
        if (!line.trim()) {
            flushList(`ul-${i}`);
            elements.push(<div key={`br-${i}`} className="h-2" />);
            return;
        }
        const listMatch = line.match(/^(\s*)(?:\*|-|•)\s+(.*)$/);
        if (listMatch) {
            inList = true;
            listItems.push(_renderMarkdownListItem(listMatch, i, parseInlineText));
        } else {
            flushList(`ul-${i}-close`);
            elements.push(_renderMarkdownNonListElement(line, i, parseInlineText));
        }
    });
    flushList('ul-end');
    return elements;
}


/**
 * Renders the expandable developer diagnostics console for AI requests.
 *
 * @param {object} props
 * @param {boolean} props.showDiag - Visibility flag
 * @param {Function} props.setShowDiag - Visibility toggle
 * @param {string[]} props.aiDiagnostics - List of diagnostic log messages
 * @returns {React.ReactNode} Rendered diagnostics drawer or null
 *
 * @example
 * <AiDiagnosticsDrawer showDiag={true} setShowDiag={fn} aiDiagnostics={['Probing...']} />
 *
 * @example
 * <AiDiagnosticsDrawer showDiag={false} setShowDiag={fn} aiDiagnostics={[]} />
 */
const AiDiagnosticsDrawer = ({ showDiag, setShowDiag, aiDiagnostics }) => {
    if (!showDiag || !aiDiagnostics || aiDiagnostics.length === 0) return null;
    return (
        <div className="p-3 bg-slate-900 text-slate-200 border-b border-slate-700 text-xs flex flex-col gap-1.5 shrink-0 max-h-56 overflow-y-auto font-mono">
            <div className="flex items-center justify-between font-bold text-amber-400 text-[11px]">
                <span>🐞 LIVE AI DIAGNOSTICS LOGS</span>
                <button onClick={() => setShowDiag(false)} className="text-slate-400 hover:text-white text-xs">✕</button>
            </div>
            {aiDiagnostics.map((log, lIdx) => (
                <div key={lIdx} className="text-[10.5px] leading-snug border-b border-slate-800/80 pb-0.5 last:border-0">{log}</div>
            ))}
        </div>
    );
};
