/**
 * Resolves the appropriate Leaflet map zoom level for a place string based on geographic scope.
 * 
 * @param {string} place - Place name string
 * @returns {number} Leaflet zoom level (e.g. 4 for country, 8 for state, 12 for city)
 * 
 * @example
 * getZoomForLocation('India');
 * // => 5
 * 
 * @example
 * getZoomForLocation('Chicago');
 * // => 12
 */
const getZoomForLocation = (place) => {
    if (!place) return 10;
    const norm = place.toLowerCase().trim();
    if (LOCATION_ZOOM_LEVELS[norm]) return LOCATION_ZOOM_LEVELS[norm];
    for (const [k, v] of Object.entries(LOCATION_ZOOM_LEVELS)) {
        if (norm.includes(k) || k.includes(norm)) return v;
    }
    return 14;
};

/**
 * Pans and zooms a Leaflet map instance to a named location.
 *
 * Looks up existing map marker coordinates first, falling back to pre-geocoded coordinates.
 *
 * @param {Object} mapInstance - Leaflet map instance
 * @param {Array<Object>} markers - Rendered map markers
 * @param {string} place - Target location name
 * @param {number} [duration=0.8] - Animation duration in seconds
 * 
 * @example
 * flyMapToPlace(mapInstance, markers, 'Kochi');
 * 
 * @example
 * flyMapToPlace(mapInstance, markers, 'San Jose', 1.2);
 */
function flyMapToPlace(mapInstance, markers, place, duration = 0.8) {
    if (!mapInstance || !place) return;
    const zoom = getZoomForLocation(place);
    const norm = place.toLowerCase().trim();
    const item = markers ? markers.find(m => m.place && m.place.toLowerCase().trim() === norm) : null;
    const coords = item ? item.coords : resolveLocationCoords(place);
    if (coords) {
        mapInstance.flyTo(coords, zoom, { duration });
    }
}

/**
 * Groups living/known people in the family tree by valid location.
 *
 * Excludes ghosts, unknown placeholders, and invalid location names.
 * Returns groups ordered descending by resident count.
 *
 * @param {FamilyTree} tree - Active family tree model
 * @returns {Array<{place: string, people: Array<Person>, count: number}>} Grouped locations
 * 
 * @example
 * computePlaceGroups(tree);
 * // => [{ place: 'Kochi', people: [...], count: 12 }, { place: 'Thrissur', people: [...], count: 8 }]
 * 
 * @example
 * computePlaceGroups(null);
 * // => []
 */
function computePlaceGroups(tree) {
    if (!tree || !tree.all) return [];
    const groups = {};
    tree.all.forEach(p => {
        if (p.place && p.place.trim() && !p.isGhost && !p._isUnknown) {
            const place = p.place.trim();
            if (!FamilyTreeBuilder.isInvalidLocation(place)) {
                if (!groups[place]) groups[place] = [];
                groups[place].push(p);
            }
        }
    });
    return Object.entries(groups)
        .map(([place, people]) => ({ place, people, count: people.length }))
        .sort((a, b) => b.count - a.count);
}

/**
 * Retrieves or initializes an accumulator node in the location hierarchy tree.
 *
 * @param {Object} parentMap - Parent dictionary container.
 * @param {string} key - Node identifier key.
 * @param {Function} factory - Constructor callback for creating initial node state.
 * @returns {Object} Node record.
 *
 * @example
 * const node = _getOrCreateHierarchyNode(countryMap, 'India', () => ({ name: 'India', flag: '📍', count: 0, locations: [], states: {} }));
 * // => { name: 'India', flag: '📍', count: 0, locations: [], states: {} }
 * 
 * @example
 * _getOrCreateHierarchyNode(cNode.states, 'Kerala', () => ({ name: 'Kerala', count: 0, locations: [], districts: {} }));
 * // => { name: 'Kerala', count: 0, locations: [], districts: {} }
 */
function _getOrCreateHierarchyNode(parentMap, key, factory) {
    if (!parentMap[key]) {
        parentMap[key] = factory();
    }
    return parentMap[key];
}

/**
 * Inserts a location group into a state hierarchy node or its nested district node.
 *
 * @param {Object} cNode - Parent country hierarchy node
 * @param {string} state - State name
 * @param {string|null} district - Optional district name
 * @param {Object} group - Place group record with count and place string
 *
 * @example
 * _insertStateLocation(cNode, 'Kerala', 'Thrissur', { place: 'Ollur', count: 5 });
 *
 * @example
 * _insertStateLocation(cNode, 'California', null, { place: 'California', count: 2 });
 */
function _insertStateLocation(cNode, state, district, group) {
    const sNode = _getOrCreateHierarchyNode(cNode.states, state, () => ({
        name: state, count: 0, locations: [], districts: {}
    }));
    sNode.count += group.count;

    if (!district) {
        sNode.locations.push(group);
        return;
    }

    const dNode = _getOrCreateHierarchyNode(sNode.districts, district, () => ({
        name: district, count: 0, locations: []
    }));
    dNode.count += group.count;
    dNode.locations.push(group);
}

/**
 * Inserts a place group record into the country -> state -> district accumulator map.
 * 
 * @param {Object} countryMap - Country accumulator map
 * @param {Object} group - Place group record
 * 
 * @example
 * _insertLocationIntoHierarchy(map, { place: 'Ollur, Thrissur, Kerala, India', count: 5 });
 * 
 * @example
 * _insertLocationIntoHierarchy(map, { place: 'London, United Kingdom', count: 3 });
 */
function _insertLocationIntoHierarchy(countryMap, group) {
    const { country, state, district } = resolvePlaceHierarchy(group.place);
    const flag = COUNTRY_FLAGS[country] || '📍';

    const cNode = _getOrCreateHierarchyNode(countryMap, country, () => ({
        name: country, flag, count: 0, locations: [], states: {}
    }));
    cNode.count += group.count;

    if (!state) {
        cNode.locations.push(group);
        return;
    }

    _insertStateLocation(cNode, state, district, group);
}

/**
 * Formats and sorts a district hierarchy node and its contained locations by resident count.
 * 
 * @param {Object} d - District record containing name, count, and locations
 * @param {Function} sortFn - Count comparator function
 * @returns {Object} Formatted district node
 * 
 * @example
 *   _formatHierarchyDistrictNode(dist, (a, b) => b.count - a.count);
 * 
 * @example
 *   _formatHierarchyDistrictNode({ name: 'Thrissur', count: 5, locations: [] }, (a, b) => b.count - a.count);
 */
function _formatHierarchyDistrictNode(d, sortFn) {
    return {
        ...d,
        locations: d.locations.sort(sortFn)
    };
}

/**
 * Formats and sorts a state hierarchy node, its contained districts, and direct locations by resident count.
 * 
 * @param {Object} s - State record containing name, count, locations, and districts map
 * @param {Function} sortFn - Count comparator function
 * @returns {Object} Formatted state node
 * 
 * @example
 *   _formatHierarchyStateNode(state, (a, b) => b.count - a.count);
 * 
 * @example
 *   _formatHierarchyStateNode({ name: 'Kerala', count: 10, locations: [], districts: {} }, (a, b) => b.count - a.count);
 */
function _formatHierarchyStateNode(s, sortFn) {
    return {
        ...s,
        locations: s.locations.sort(sortFn),
        districts: Object.values(s.districts)
            .sort(sortFn)
            .map(d => _formatHierarchyDistrictNode(d, sortFn))
    };
}

/**
 * Converts country accumulator map into a sorted nested array sorted by resident count descending.
 * 
 * @param {Object} countryMap - Populated country accumulator map
 * @returns {Array<Object>} Sorted nested hierarchy array
 * 
 * @example
 *   _formatLocationHierarchy(map)
 *   // => [{ name: 'India', count: 10, states: [...] }]
 * 
 * @example
 *   _formatLocationHierarchy({})
 *   // => []
 */
function _formatLocationHierarchy(countryMap) {
    const sortByCount = (a, b) => b.count - a.count;
    return Object.values(countryMap)
        .sort(sortByCount)
        .map(c => ({
            ...c,
            locations: c.locations.sort(sortByCount),
            states: Object.values(c.states)
                .sort(sortByCount)
                .map(s => _formatHierarchyStateNode(s, sortByCount))
        }));
}

/**
 * Builds a hierarchical tree (country -> state -> district -> locations) from place groups.
 *
 * Resolves each place against LOCATION_GEO_HIERARCHY and attaches corresponding country flags.
 * Groups are filtered by an optional search query string.
 *
 * @param {Array<Object>} placeGroups - Flat list of place groups
 * @param {string} [searchQuery=''] - Optional filter substring
 * @returns {Array<Object>} Nested hierarchy of countries, states, and districts
 * 
 * @example
 * buildLocationHierarchy(placeGroups, 'kerala');
 * // => [{ name: 'India', count: 12, states: [...] }]
 * 
 * @example
 * buildLocationHierarchy([], '');
 * // => []
 */
function buildLocationHierarchy(placeGroups, searchQuery = '') {
    const countryMap = {};
    const q = (searchQuery || '').toLowerCase().trim();

    placeGroups.forEach(group => {
        if (q && !group.place.toLowerCase().includes(q)) return;
        _insertLocationIntoHierarchy(countryMap, group);
    });

    return _formatLocationHierarchy(countryMap);
}

/**
 * Generic helper to group people by a specified text attribute (optionally splitting multiple tokens),
 * filtering against a search query, and sorting descending by member count.
 *
 * @param {FamilyTree} tree - The family tree model.
 * @param {string} attrName - Profile property name (e.g. 'job', 'family').
 * @param {string} [searchQuery=''] - Optional substring filter.
 * @param {boolean} [splitTokens=false] - Whether comma-separated values should be split into individual tokens.
 * @returns {Array<{ [attrName]: string, people: Array<Person>, count: number }>} Grouped and sorted list.
 *
 * @example
 * groupPeopleByAttribute(tree, 'family', 'chalissery', false);
 * // => [{ family: 'Chalissery', people: [...], count: 18 }]
 * 
 * @example
 * groupPeopleByAttribute(tree, 'job', 'engineer', true);
 * // => [{ job: 'Engineer', people: [...], count: 5 }]
 */
function groupPeopleByAttribute(tree, attrName, searchQuery = '', splitTokens = false) {
    if (!tree || !tree.all) return [];
    const groups = {};
    tree.all.forEach(p => {
        const val = p[attrName];
        if (val && typeof val === 'string' && val.trim() && !p.isGhost && !p._isUnknown) {
            const tokens = splitTokens ? parseCommaDelimitedTokens(val) : [val.trim()];
            tokens.forEach(tok => {
                if (!groups[tok]) groups[tok] = [];
                groups[tok].push(p);
            });
        }
    });
    const q = (searchQuery || '').toLowerCase().trim();
    return Object.entries(groups)
        .map(([key, people]) => ({ [attrName]: key, people, count: people.length }))
        .filter(g => !q || g[attrName].toLowerCase().includes(q))
        .sort((a, b) => b.count - a.count);
}

/**
 * Groups people by career/job titles parsed from comma-separated tokens.
 *
 * @param {FamilyTree} tree - Active family tree model
 * @param {string} [searchQuery=''] - Optional filter substring
 * @returns {Array<{job: string, people: Array<Person>, count: number}>} Filtered and sorted jobs
 * 
 * @example
 * computeJobGroups(tree, 'doctor');
 * // => [{ job: 'Doctor', people: [...], count: 3 }]
 * 
 * @example
 * computeJobGroups(tree, '');
 * // => [{ job: 'Engineer', people: [...], count: 6 }, ...]
 */
function computeJobGroups(tree, searchQuery = '') {
    return groupPeopleByAttribute(tree, 'job', searchQuery, true);
}

/**
 * Groups people by family name / house name.
 *
 * @param {FamilyTree} tree - Active family tree model
 * @param {string} [searchQuery=''] - Optional filter substring
 * @returns {Array<{family: string, people: Array<Person>, count: number}>} Filtered and sorted families
 * 
 * @example
 * computeFamilyGroups(tree, 'chalissery');
 * // => [{ family: 'Chalissery', people: [...], count: 18 }]
 * 
 * @example
 * computeFamilyGroups(tree, '');
 * // => [{ family: 'Maramattathil', people: [...], count: 24 }, ...]
 */
function computeFamilyGroups(tree, searchQuery = '') {
    return groupPeopleByAttribute(tree, 'family', searchQuery, false);
}

/**
 * Renders an individual leaf location item button within the directory hierarchy.
 *
 * @param {object} props
 * @param {string} props.place - Raw place identifier string
 * @param {string} props.displayName - Cleaned display name for the place
 * @param {number} props.count - Number of people in this location
 * @param {boolean} props.isSelected - Whether this location is currently selected/active
 * @param {React.RefObject} props.activeItemRef - Ref to attach if selected for auto-scrolling
 * @param {Function} props.onSelect - Callback invoked when the location button is clicked
 * @returns {React.ReactNode}
 *
 * @example
 * <DirectoryLeafLocationItem
 *   place="Kochi, Kerala, India"
 *   displayName="Kochi"
 *   count={12}
 *   isSelected={true}
 *   activeItemRef={activeItemRef}
 *   onSelect={() => handleSelectLocation("Kochi, Kerala, India")}
 * />
 *
 * @example
 * <DirectoryLeafLocationItem
 *   place="London, UK"
 *   displayName="London"
 *   count={3}
 *   isSelected={false}
 *   activeItemRef={null}
 *   onSelect={() => handleSelectLocation("London, UK")}
 * />
 */
const DirectoryLeafLocationItem = ({
    place,
    displayName,
    count,
    isSelected,
    activeItemRef,
    onSelect
}) => (
    <button
        key={place}
        ref={isSelected ? activeItemRef : null}
        onClick={onSelect}
        className={`w-full flex items-center justify-between px-2 py-1 rounded-lg text-left transition-all cursor-pointer ${isSelected ? 'bg-rose-50 border border-rose-200 text-rose-900 font-bold shadow-2xs' : 'hover:bg-slate-100/80 border border-transparent text-slate-700'}`}
    >
        <span className="text-xs truncate">{displayName}</span>
        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full shrink-0 ${isSelected ? 'bg-rose-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
            {count}
        </span>
    </button>
);

/**
 * Resolves CSS class names for flat directory region buttons based on geographical hierarchy level.
 *
 * @param {'country'|'state'|'district'} [level='state'] - Geographic hierarchy level
 * @returns {{ paddingClass: string, textClass: string, countClass: string, defaultColor: string }} Style classes
 *
 * @example
 * const styles = resolveFlatRegionStyling('country');
 *
 * @example
 * const styles = resolveFlatRegionStyling('district');
 */
function resolveFlatRegionStyling(level = 'state') {
    if (level === 'country') {
        return {
            paddingClass: "px-2.5 py-1.5 rounded-lg",
            textClass: "text-xs font-bold",
            countClass: "text-[10px] font-bold px-2 py-0.5",
            defaultColor: "text-slate-800 hover:bg-slate-100/90"
        };
    }
    if (level === 'district') {
        return {
            paddingClass: "px-1.5 py-0.5 rounded",
            textClass: "text-[11px] font-medium",
            countClass: "text-[9px] px-1.5 py-0.5",
            defaultColor: "text-slate-700 hover:bg-slate-100/70"
        };
    }
    return {
        paddingClass: "px-2 py-1 rounded-lg",
        textClass: "text-xs font-semibold",
        countClass: "text-[10px] font-bold px-1.5 py-0.5",
        defaultColor: "text-slate-700 hover:bg-slate-100/80"
    };
}

/**
 * Renders a clickable flat region item button for countries, states, or districts
 * that do not have nested sub-regions.
 *
 * @param {object} props
 * @param {string} props.name - Region name
 * @param {string} [props.flag] - Optional country flag emoji
 * @param {number} props.count - Member count in this region
 * @param {boolean} props.isSelected - Whether region is currently selected
 * @param {React.RefObject} [props.activeItemRef] - Ref for scrolling active item into view
 * @param {Function} props.onClick - Selection callback
 * @param {'country'|'state'|'district'} [props.level='state'] - Hierarchy level for typography and sizing
 * @returns {React.ReactNode}
 *
 * @example
 * <DirectoryFlatRegionButton name="Goa" count={3} isSelected={false} onClick={() => {}} level="state" />
 *
 * @example
 * <DirectoryFlatRegionButton name="India" flag="🇮🇳" count={25} isSelected={true} onClick={() => {}} level="country" />
 */
const DirectoryFlatRegionButton = ({
    name, flag, count, isSelected, activeItemRef, onClick, level = 'state'
}) => {
    const { paddingClass, textClass, countClass, defaultColor } = resolveFlatRegionStyling(level);

    return (
        <button
            key={name}
            ref={isSelected ? activeItemRef : null}
            onClick={onClick}
            className={`w-full flex items-center justify-between ${paddingClass} text-left transition-all cursor-pointer ${
                isSelected
                    ? 'bg-rose-50 border border-rose-200 text-rose-900 font-bold shadow-2xs'
                    : `border border-transparent ${defaultColor}`
            }`}
        >
            <div className="flex items-center gap-1.5 min-w-0">
                {flag && <span className="text-sm">{flag}</span>}
                <span className={`${textClass} truncate`}>{name}</span>
            </div>
            <span className={`${countClass} rounded-full shrink-0 ${
                isSelected
                    ? 'bg-rose-600 text-white'
                    : (level === 'district' ? 'text-slate-400 bg-slate-100' : 'bg-slate-100 text-slate-500')
            }`}>
                {count}
            </span>
        </button>
    );
};

/**
 * Renders the interactive header row for a collapsible region (country, state, or district)
 * within the location directory, featuring an expand/collapse toggle and active styling.
 *
 * @param {object} props
 * @param {string} props.name - Region name
 * @param {string} [props.flag] - Optional flag emoji
 * @param {number} props.count - People count in this region
 * @param {boolean} props.isCollapsed - Current collapse state
 * @param {boolean} props.isActive - Whether region is active/highlighted
 * @param {Function} props.onToggleCollapse - Click handler for expand/collapse button
 * @param {Function} props.onSelectRegion - Click handler for whole region header
 * @param {React.RefObject} [props.activeItemRef] - Scroll-into-view ref
 * @param {'country'|'state'|'district'} [props.level='state'] - Hierarchy level for typography and sizing
 * @returns {React.ReactNode}
 *
 * @example
 * <DirectoryCollapsibleRegionHeader name="Kerala" count={15} isCollapsed={false} isActive={true} onToggleCollapse={() => {}} onSelectRegion={() => {}} level="state" />
 *
 * @example
 * <DirectoryCollapsibleRegionHeader name="India" flag="🇮🇳" count={25} isCollapsed={true} isActive={false} onToggleCollapse={() => {}} onSelectRegion={() => {}} level="country" />
 */
const REGION_LEVEL_STYLES = Object.freeze({
    country: {
        paddingClass: "px-2 py-1.5 rounded-lg hover:bg-slate-100/90",
        textClass: "text-xs font-bold text-slate-800",
        countClass: "text-[10px] font-bold",
        btnClass: "text-slate-400 hover:text-slate-700 text-[10px] w-3.5 h-3.5 transition-transform",
        inactiveBadgeClass: "bg-slate-100 text-slate-600 group-hover:bg-slate-200"
    },
    district: {
        paddingClass: "px-1.5 py-0.5 rounded hover:bg-slate-100/70",
        textClass: "text-[11px] font-medium text-slate-600",
        countClass: "text-[9px]",
        btnClass: "text-slate-300 hover:text-slate-600 text-[8px] w-2.5 h-2.5",
        inactiveBadgeClass: "text-slate-400 bg-slate-100"
    },
    state: {
        paddingClass: "px-1.5 py-1 rounded-md hover:bg-slate-100/80",
        textClass: "text-xs font-semibold text-slate-700",
        countClass: "text-[9.5px] font-semibold",
        btnClass: "text-slate-400 hover:text-slate-700 text-[9px] w-3 h-3",
        inactiveBadgeClass: "bg-slate-100/80 text-slate-500"
    }
});

/**
 * Computes responsive padding, typography, button, and badge CSS classes
 * for collapsible region headers in the location directory hierarchy.
 *
 * @param {'country'|'state'|'district'} [level='state'] - Hierarchy level determining typography and sizing.
 * @param {boolean} [isActive=false] - Whether the region is currently selected/active.
 * @returns {{
 *   paddingClass: string,
 *   textClass: string,
 *   countClass: string,
 *   btnClass: string,
 *   badgeClass: string
 * }} CSS class specifications for the header and its child elements.
 *
 * @example
 * resolveCollapsibleRegionStyling('country', false);
 * // returns {
 * //   paddingClass: "px-2 py-1.5 rounded-lg hover:bg-slate-100/90",
 * //   textClass: "text-xs font-bold text-slate-800",
 * //   countClass: "text-[10px] font-bold",
 * //   btnClass: "text-slate-400 hover:text-slate-700 text-[10px] w-3.5 h-3.5 transition-transform",
 * //   badgeClass: "bg-slate-100 text-slate-600 group-hover:bg-slate-200"
 * // }
 *
 * @example
 * resolveCollapsibleRegionStyling('state', true);
 * // returns {
 * //   paddingClass: "px-1.5 py-1 rounded-md hover:bg-slate-100/80",
 * //   textClass: "text-xs font-semibold text-slate-700",
 * //   countClass: "text-[9.5px] font-semibold",
 * //   btnClass: "text-slate-400 hover:text-slate-700 text-[9px] w-3 h-3",
 * //   badgeClass: "bg-rose-600 text-white"
 * // }
 */
function resolveCollapsibleRegionStyling(level = 'state', isActive = false) {
    const config = REGION_LEVEL_STYLES[level] || REGION_LEVEL_STYLES.state;
    return {
        paddingClass: config.paddingClass,
        textClass: config.textClass,
        countClass: config.countClass,
        btnClass: config.btnClass,
        badgeClass: isActive ? 'bg-rose-600 text-white' : config.inactiveBadgeClass
    };
}

/**
 * Renders the toggle button, optional flag, and name label for a collapsible directory region header.
 *
 * @param {Object} props
 * @param {Function} props.onToggleCollapse - Collapse toggle handler.
 * @param {string} props.btnClass - CSS classes for the toggle button.
 * @param {boolean} props.isCollapsed - Whether region is collapsed.
 * @param {string} [props.flag] - Optional flag emoji.
 * @param {string} props.textClass - CSS classes for the name text.
 * @param {string} props.name - Region name.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryRegionTitle onToggleCollapse={() => {}} btnClass="text-xs" isCollapsed={false} flag="🇮🇳" textClass="font-medium" name="Kerala" />
 *
 * @example
 * <DirectoryRegionTitle onToggleCollapse={() => {}} btnClass="text-xs" isCollapsed={true} textClass="font-medium" name="Ernakulam" />
 */
const DirectoryRegionTitle = ({
    onToggleCollapse, btnClass, isCollapsed, flag, textClass, name
}) => (
    <div className="flex items-center gap-1 min-w-0">
        <button
            onClick={onToggleCollapse}
            className={`${btnClass} flex items-center justify-center rounded`}
            title={isCollapsed ? "Expand" : "Collapse"}
        >
            {isCollapsed ? '▶' : '▼'}
        </button>
        {flag && <span className="text-sm">{flag}</span>}
        <span className={`${textClass} truncate`}>{name}</span>
    </div>
);

/**
 * Renders an expandable region header row for countries, states, or districts in the location directory.
 *
 * @param {Object} props - Component properties
 * @returns {React.ReactNode} Collapsible region header element
 *
 * @example
 * <DirectoryCollapsibleRegionHeader name="Kerala" count={42} isCollapsed={false} level="state" {...props} />
 *
 * @example
 * <DirectoryCollapsibleRegionHeader name="India" flag="🇮🇳" count={120} isCollapsed={true} level="country" {...props} />
 */
const DirectoryCollapsibleRegionHeader = ({
    name, flag, count, isCollapsed, isActive, onToggleCollapse, onSelectRegion, activeItemRef, level = 'state'
}) => {
    const { paddingClass, textClass, countClass, btnClass, badgeClass } = resolveCollapsibleRegionStyling(level, isActive);

    return (
        <div 
            ref={isActive ? activeItemRef : null} onClick={onSelectRegion}
            className={`flex items-center justify-between ${paddingClass} cursor-pointer group transition-colors select-none ${
                isActive ? 'bg-rose-50 text-rose-900 font-bold border border-rose-200 shadow-2xs' : 'border border-transparent'
            }`}
        >
            <DirectoryRegionTitle
                onToggleCollapse={onToggleCollapse} btnClass={btnClass}
                isCollapsed={isCollapsed} flag={flag} textClass={textClass} name={name}
            />
            <span className={`${countClass} px-1.5 py-0.5 rounded-full shrink-0 ${badgeClass}`}>
                {count}
            </span>
        </div>
    );
};

/**
 * Renders a collapsible region branch in the directory tree, containing the interactive header
 * and its nested child nodes when expanded.
 *
 * @param {Object} props
 * @param {string} props.name - Region name.
 * @param {string} [props.flag] - Optional flag emoji.
 * @param {number} props.count - People count within this region.
 * @param {boolean} props.isCollapsed - Current collapse state.
 * @param {boolean} props.isActive - Whether the region is currently selected.
 * @param {Function} props.onToggleCollapse - Toggle collapse callback.
 * @param {Function} props.onSelectRegion - Region selection callback.
 * @param {React.RefObject} [props.activeItemRef] - Scroll-into-view ref.
 * @param {'country'|'state'|'district'} [props.level='state'] - Hierarchy depth level.
 * @param {React.ReactNode} [props.children] - Child nodes rendered when expanded.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryCollapsibleRegionBranch
 *   name="Kerala"
 *   count={15}
 *   isCollapsed={false}
 *   isActive={true}
 *   onToggleCollapse={() => {}}
 *   onSelectRegion={() => {}}
 *   level="state"
 * >
 *   <div>State child content</div>
 * </DirectoryCollapsibleRegionBranch>
 *
 * @example
 * <DirectoryCollapsibleRegionBranch
 *   name="India"
 *   flag="🇮🇳"
 *   count={25}
 *   isCollapsed={true}
 *   isActive={false}
 *   onToggleCollapse={() => {}}
 *   onSelectRegion={() => {}}
 *   level="country"
 * >
 *   <div>Country child content</div>
 * </DirectoryCollapsibleRegionBranch>
 */
const DirectoryCollapsibleRegionBranch = ({
    name,
    flag,
    count,
    isCollapsed,
    isActive,
    onToggleCollapse,
    onSelectRegion,
    activeItemRef,
    level = 'state',
    children
}) => (
    <div key={name} className="flex flex-col">
        <DirectoryCollapsibleRegionHeader
            name={name}
            flag={flag}
            count={count}
            isCollapsed={isCollapsed}
            isActive={isActive}
            onToggleCollapse={onToggleCollapse}
            onSelectRegion={onSelectRegion}
            activeItemRef={activeItemRef}
            level={level}
        />
        {!isCollapsed && children}
    </div>
);

/**
 * Renders an individual district node within the location directory hierarchy,
 * including its collapsible toggle or direct action button, and child location items.
 *
 * @param {object} props
 * @param {object} props.districtNode - District node containing name, count, locations
 * @param {string} props.stateKey - Parent state key path (e.g. 'India/Kerala')
 * @param {object} props.collapsedNodes - Map of collapsed path keys
 * @param {Function} props.toggleCollapse - Collapse state toggler
 * @param {string|null} props.activePlaceName - Currently active place filter value
 * @param {Function} props.isPlaceMatch - Predicate matching location names
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view
 * @param {Function} props.handleSelectRegion - Region selection callback
 * @param {Function} props.handleSelectLocation - Leaf location selection callback
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names
 * @param {string} props.stateName - Parent state name
 * @param {string} props.countryName - Parent country name
/**
 * Determines whether a directory hierarchy region (country, state, district) should be
 * marked as active based on direct name matching or parent fallback resolution.
 *
 * @param {string} regionName - Name of the geographic region
 * @param {Array<{place: string}>} regionPlaces - All place locations nested under the region
 * @param {string|null} activePlaceName - Currently active place query filter
 * @param {Function} isPlaceMatch - Predicate checking whether a location matches the active filter
 * @param {'country'|'state'|'district'} hierarchyField - Field key on resolvePlaceHierarchy result
 * @returns {boolean} True if the region is currently active
 *
 * @example
 * isDirectoryRegionActive('Kerala', [{ place: 'Kochi' }], 'Kerala', () => false, 'state');
 * // => true
 *
 * @example
 * isDirectoryRegionActive('India', [{ place: 'Delhi' }], 'Delhi', (a, b) => a === b, 'country');
 * // => false
 */
function isDirectoryRegionActive(regionName, regionPlaces, activePlaceName, isPlaceMatch, hierarchyField) {
    if (!activePlaceName) return false;
    const normActive = activePlaceName.toLowerCase().trim();
    const normRegion = regionName.toLowerCase().trim();
    if (normActive === normRegion) return true;
    const hasMatchingChild = regionPlaces.some(p => isPlaceMatch(p.place, activePlaceName));
    if (hasMatchingChild) return false;
    const resolvedField = resolvePlaceHierarchy(activePlaceName)[hierarchyField];
    return resolvedField?.toLowerCase().trim() === normRegion;
}

/**
 * Flattens all nested place records under a country hierarchy node.
 *
 * @param {object} countryNode - Country directory node
 * @returns {Array<object>} Flattened array of all place locations
 *
 * @example
 * getAllCountryPlaces({ locations: [{ place: 'Delhi' }], states: [] });
 * // => [{ place: 'Delhi' }]
 *
 * @example
 * getAllCountryPlaces({ locations: [], states: [{ locations: [{ place: 'Kochi' }], districts: [] }] });
 * // => [{ place: 'Kochi' }]
 */
function getAllCountryPlaces(countryNode) {
    return [
        ...countryNode.locations,
        ...countryNode.states.flatMap(s => [
            ...s.locations,
            ...s.districts.flatMap(d => d.locations)
        ])
    ];
}

/**
 * Flattens all nested place records under a state hierarchy node.
 *
 * @param {object} stateNode - State directory node
 * @returns {Array<object>} Flattened array of all place locations
 *
 * @example
 * getAllStatePlaces({ locations: [{ place: 'Kochi' }], districts: [] });
 * // => [{ place: 'Kochi' }]
 *
 * @example
 * getAllStatePlaces({ locations: [], districts: [{ locations: [{ place: 'Aluva' }] }] });
 * // => [{ place: 'Aluva' }]
 */
function getAllStatePlaces(stateNode) {
    return [
        ...stateNode.locations,
        ...stateNode.districts.flatMap(d => d.locations)
    ];
}

/**
 * Renders the child locations list for an expanded district directory node.
 *
 * @param {object} props
 * @param {Array<object>} props.childDistLocations - Distinct child locations under the district
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names
 * @param {string} props.stateName - Parent state name
 * @param {string} props.districtName - Current district name
 * @param {string} props.countryName - Parent country name
 * @param {string|null} props.activePlaceName - Currently active place filter value
 * @param {Function} props.isPlaceMatch - Predicate matching location names
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view
 * @param {Function} props.handleSelectLocation - Leaf location selection callback
 * @returns {React.ReactNode}
 *
 * @example
 * <DirectoryDistrictChildrenList childDistLocations={[]} cleanLocationDisplayName={p => p} stateName="Kerala" districtName="Ernakulam" countryName="India" activePlaceName={null} isPlaceMatch={() => false} activeItemRef={{ current: null }} handleSelectLocation={() => {}} />
 *
 * @example
 * <DirectoryDistrictChildrenList childDistLocations={[{ place: 'Kochi', count: 5 }]} cleanLocationDisplayName={p => p} stateName="Kerala" districtName="Ernakulam" countryName="India" activePlaceName="Kochi" isPlaceMatch={(a, b) => a === b} activeItemRef={{ current: null }} handleSelectLocation={() => {}} />
 */
const DirectoryDistrictChildrenList = ({
    childDistLocations,
    cleanLocationDisplayName,
    stateName,
    districtName,
    countryName,
    activePlaceName,
    isPlaceMatch,
    activeItemRef,
    handleSelectLocation
}) => (
    <div className="border-l border-slate-200 ml-2 pl-2 py-0.5 space-y-0.5 mt-0.5">
        {childDistLocations.map(locGroup => (
            <DirectoryLeafLocationItem
                key={locGroup.place}
                place={locGroup.place}
                displayName={cleanLocationDisplayName(locGroup.place, stateName, districtName, countryName)}
                count={locGroup.count}
                isSelected={Boolean(activePlaceName && isPlaceMatch(locGroup.place, activePlaceName))}
                activeItemRef={activeItemRef}
                onSelect={() => handleSelectLocation(locGroup.place)}
            />
        ))}
    </div>
);

/**
 * Filters leaf locations under a hierarchy region node to exclude locations with the same name as the region itself.
 *
 * @param {Array<Object>} locations - List of location objects with a place string property.
 * @param {string} regionName - Name of the parent region to exclude duplicate leaf items.
 * @returns {Array<Object>} Filtered list of distinct sub-locations.
 *
 * @example
 *   filterDistinctChildLocations([{ place: 'Kerala' }, { place: 'Kochi' }], 'Kerala');
 *   // returns [{ place: 'Kochi' }]
 *
 * @example
 *   filterDistinctChildLocations([{ place: 'India' }], 'India');
 *   // returns []
 */
function filterDistinctChildLocations(locations, regionName) {
    if (!locations || !regionName) return [];
    const normalizedRegion = regionName.toLowerCase().trim();
    return locations.filter(loc => loc.place.toLowerCase().trim() !== normalizedRegion);
}

/**
 * Computes collapse, active state, and child locations for a district hierarchy node.
 *
 * @param {Object} options
 * @param {Object} options.districtNode - District node object with name and locations.
 * @param {string} options.stateKey - Hierarchical key for the parent state.
 * @param {Object} options.collapsedNodes - Map of collapsed state by node key.
 * @param {string|null} options.activePlaceName - Active place name filter.
 * @param {Function} options.isPlaceMatch - Place matching predicate function.
 * @returns {{
 *   districtKey: string,
 *   isDistrictCollapsed: boolean,
 *   isDistrictActive: boolean,
 *   childDistLocations: Array<Object>,
 *   hasDistChildLocations: boolean
 * }} Computed district node state and child items.
 *
 * @example
 *   resolveDistrictNodeState({
 *     districtNode: { name: 'Ernakulam', locations: [] },
 *     stateKey: 'India/Kerala',
 *     collapsedNodes: {},
 *     activePlaceName: null,
 *     isPlaceMatch: () => false
 *   });
 *
 * @example
 *   resolveDistrictNodeState({
 *     districtNode: { name: 'Thrissur', locations: [{ place: 'Chalakudy' }] },
 *     stateKey: 'India/Kerala',
 *     collapsedNodes: { 'India/Kerala/Thrissur': true },
 *     activePlaceName: 'Chalakudy',
 *     isPlaceMatch: (a, b) => a === b
 *   });
 */
function resolveDistrictNodeState({
    districtNode,
    stateKey,
    collapsedNodes,
    activePlaceName,
    isPlaceMatch
}) {
    const districtKey = `${stateKey}/${districtNode.name}`;
    const isDistrictCollapsed = !!collapsedNodes[districtKey];
    const isDistrictActive = isDirectoryRegionActive(
        districtNode.name,
        districtNode.locations,
        activePlaceName,
        isPlaceMatch,
        'district'
    );
    const childDistLocations = filterDistinctChildLocations(districtNode.locations, districtNode.name);
    const hasDistChildLocations = childDistLocations.length > 0;

    return {
        districtKey,
        isDistrictCollapsed,
        isDistrictActive,
        childDistLocations,
        hasDistChildLocations
    };
}

/**
 * Renders an expandable district branch in the directory tree with child locations.
 *
 * @param {object} props
 * @param {object} props.districtNode - District tree node
 * @param {boolean} props.isDistrictCollapsed - Whether district is collapsed
 * @param {boolean} props.isDistrictActive - Whether district is actively selected
 * @param {Function} props.toggleCollapse - Collapse toggle handler
 * @param {string} props.districtKey - Unique composite key for district
 * @param {Function} props.handleSelectRegion - Region selection callback
 * @param {React.RefObject} props.activeItemRef - Ref to scroll active item into view
 * @param {object} props.childListProps - Props passed to DirectoryDistrictChildrenList
 * @returns {React.ReactNode}
 *
 * @example
 *   <DirectoryDistrictBranch districtNode={{ name: 'Ernakulam' }} isDistrictCollapsed={false} isDistrictActive={true} toggleCollapse={() => {}} districtKey="k" handleSelectRegion={() => {}} activeItemRef={{ current: null }} childListProps={{}} />
 *
 * @example
 *   <DirectoryDistrictBranch districtNode={{ name: 'Thrissur' }} isDistrictCollapsed={true} isDistrictActive={false} toggleCollapse={() => {}} districtKey="k2" handleSelectRegion={() => {}} activeItemRef={{ current: null }} childListProps={{}} />
 */
const DirectoryDistrictBranch = ({
    districtNode, isDistrictCollapsed, isDistrictActive, toggleCollapse,
    districtKey, handleSelectRegion, activeItemRef, childListProps
}) => (
    <DirectoryCollapsibleRegionBranch
        name={districtNode.name} count={districtNode.count} isCollapsed={isDistrictCollapsed}
        isActive={Boolean(isDistrictActive)} onToggleCollapse={(e) => toggleCollapse(districtKey, e)}
        onSelectRegion={() => handleSelectRegion(districtNode.name, districtNode.locations)}
        activeItemRef={activeItemRef} level="district"
    >
        <DirectoryDistrictChildrenList {...childListProps} />
    </DirectoryCollapsibleRegionBranch>
);

/**
 * Renders an individual district node within the location directory hierarchy,
 * including its collapsible toggle or direct action button, and child location items.
 *
 * @param {object} props
 * @param {object} props.districtNode - District node containing name, count, locations
 * @param {string} props.stateKey - Parent state key path (e.g. 'India/Kerala')
 * @param {object} props.collapsedNodes - Map of collapsed path keys
 * @param {Function} props.toggleCollapse - Collapse state toggler
 * @param {string|null} props.activePlaceName - Currently active place filter value
 * @param {Function} props.isPlaceMatch - Predicate matching location names
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view
 * @param {Function} props.handleSelectRegion - Region selection callback
 * @param {Function} props.handleSelectLocation - Leaf location selection callback
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names
 * @param {string} props.stateName - Parent state name
 * @param {string} props.countryName - Parent country name
 * @returns {React.ReactNode} Formatted district hierarchy element
 *
 * @example
 * <DirectoryDistrictNode districtNode={{ name: 'Ernakulam', count: 10, locations: [] }} stateKey="India/Kerala" collapsedNodes={{}} toggleCollapse={() => {}} activePlaceName={null} isPlaceMatch={() => false} activeItemRef={{ current: null }} handleSelectRegion={() => {}} handleSelectLocation={() => {}} cleanLocationDisplayName={p => p} stateName="Kerala" countryName="India" />
 *
 * @example
 * <DirectoryDistrictNode districtNode={{ name: 'Thrissur', count: 5, locations: [{ place: 'Chalakudy', count: 2 }] }} stateKey="India/Kerala" collapsedNodes={{ 'India/Kerala/Thrissur': false }} toggleCollapse={() => {}} activePlaceName="Chalakudy" isPlaceMatch={(a, b) => a === b} activeItemRef={{ current: null }} handleSelectRegion={() => {}} handleSelectLocation={() => {}} cleanLocationDisplayName={p => p} stateName="Kerala" countryName="India" />
 */
const DirectoryDistrictNode = ({
    districtNode, stateKey, collapsedNodes, toggleCollapse, activePlaceName, isPlaceMatch,
    activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName, stateName, countryName
}) => {
    const { districtKey, isDistrictCollapsed, isDistrictActive, childDistLocations, hasDistChildLocations } =
        resolveDistrictNodeState({ districtNode, stateKey, collapsedNodes, activePlaceName, isPlaceMatch });

    if (!hasDistChildLocations) {
        return (
            <DirectoryFlatRegionButton
                name={districtNode.name} count={districtNode.count}
                isSelected={Boolean(activePlaceName && isPlaceMatch(districtNode.name, activePlaceName))}
                activeItemRef={activeItemRef} onClick={() => handleSelectRegion(districtNode.name, districtNode.locations)}
                level="district"
            />
        );
    }

    return (
        <DirectoryDistrictBranch
            districtNode={districtNode} isDistrictCollapsed={isDistrictCollapsed}
            isDistrictActive={isDistrictActive} toggleCollapse={toggleCollapse}
            districtKey={districtKey} handleSelectRegion={handleSelectRegion}
            activeItemRef={activeItemRef}
            childListProps={{
                childDistLocations, cleanLocationDisplayName, stateName, districtName: districtNode.name,
                countryName, activePlaceName, isPlaceMatch, activeItemRef, handleSelectLocation
            }}
        />
    );
};

/**
 * Renders the expanded child locations and nested district subtrees for a state directory node.
 *
 * @param {Object} props
 * @param {Array<Object>} props.childStateLocations - Direct leaf location items under the state.
 * @param {Object} props.stateNode - Current state hierarchy node.
 * @param {string} props.stateKey - Composite state key identifier.
 * @param {string} props.countryName - Parent country name.
 * @param {Object} props.collapsedNodes - Map of collapsed path keys.
 * @param {Function} props.toggleCollapse - Collapse state toggler.
 * @param {string|null} props.activePlaceName - Currently active place filter value.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view.
 * @param {Function} props.handleSelectRegion - Region selection callback.
 * @param {Function} props.handleSelectLocation - Leaf location selection callback.
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names.
 * @returns {React.ReactElement} Formatted child locations and district nodes container.
 *
 * @example
 * <DirectoryStateChildrenList
 *   childStateLocations={[]}
 *   stateNode={{ name: 'Kerala', districts: [] }}
 *   stateKey="India/Kerala"
 *   countryName="India"
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={(p) => p}
 * />
 *
 * @example
 * <DirectoryStateChildrenList
 *   childStateLocations={[{ place: 'Kochi', count: 5 }]}
 *   stateNode={{ name: 'Kerala', districts: [{ name: 'Ernakulam', locations: [] }] }}
 *   stateKey="India/Kerala"
 *   countryName="India"
 *   collapsedNodes={{ 'India/Kerala/Ernakulam': true }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="Kochi"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={(r) => console.log(r)}
 *   handleSelectLocation={(l) => console.log(l)}
 *   cleanLocationDisplayName={(p) => p}
 * />
 */
/**
 * Renders the collection of child district nodes within an expanded state directory node.
 *
 * @param {Object} props
 * @param {Array<Object>} props.districts - Array of district hierarchy nodes.
 * @param {string} props.stateKey - Composite state key identifier.
 * @param {string} props.stateName - Name of the parent state.
 * @param {string} props.countryName - Name of the parent country.
 * @param {Object} props.collapsedNodes - Map of collapsed node keys.
 * @param {Function} props.toggleCollapse - Node collapse toggle callback.
 * @param {string|null} props.activePlaceName - Currently selected place name filter.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to active DOM node.
 * @param {Function} props.handleSelectRegion - Region selection callback.
 * @param {Function} props.handleSelectLocation - Location selection callback.
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryStateDistrictsList
 *   districts={[]}
 *   stateKey="India/Kerala"
 *   stateName="Kerala"
 *   countryName="India"
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 *
 * @example
 * <DirectoryStateDistrictsList
 *   districts={[{ name: 'Thrissur', locations: [] }]}
 *   stateKey="India/Kerala"
 *   stateName="Kerala"
 *   countryName="India"
 *   collapsedNodes={{ 'India/Kerala/Thrissur': false }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="Thrissur"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 */
const DirectoryStateDistrictsList = ({
    districts, stateKey, stateName, countryName, collapsedNodes, toggleCollapse,
    activePlaceName, isPlaceMatch, activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
}) => (
    <>
        {districts.map(districtNode => (
            <DirectoryDistrictNode
                key={districtNode.name} districtNode={districtNode} stateKey={stateKey}
                collapsedNodes={collapsedNodes} toggleCollapse={toggleCollapse}
                activePlaceName={activePlaceName} isPlaceMatch={isPlaceMatch}
                activeItemRef={activeItemRef} handleSelectRegion={handleSelectRegion}
                handleSelectLocation={handleSelectLocation} cleanLocationDisplayName={cleanLocationDisplayName}
                stateName={stateName} countryName={countryName}
            />
        ))}
    </>
);

/**
 * Renders child leaf location items and district subtrees for a state node.
 *
 * @param {object} props - Component properties.
 * @returns {React.ReactNode}
 *
 * @example
 * <DirectoryStateChildrenList childStateLocations={[]} stateNode={{ name: 'Kerala', districts: [] }} stateKey="India/Kerala" countryName="India" collapsedNodes={{}} toggleCollapse={() => {}} activePlaceName={null} isPlaceMatch={() => false} activeItemRef={{ current: null }} handleSelectRegion={() => {}} handleSelectLocation={() => {}} cleanLocationDisplayName={p => p} />
 *
 * @example
 * <DirectoryStateChildrenList childStateLocations={[{ place: 'Kochi', count: 3 }]} stateNode={{ name: 'Kerala', districts: [] }} stateKey="India/Kerala" countryName="India" collapsedNodes={{}} toggleCollapse={() => {}} activePlaceName="Kochi" isPlaceMatch={(a, b) => a === b} activeItemRef={{ current: null }} handleSelectRegion={() => {}} handleSelectLocation={() => {}} cleanLocationDisplayName={p => p} />
 */
const DirectoryStateChildrenList = ({
    childStateLocations, stateNode, stateKey, countryName, collapsedNodes,
    toggleCollapse, activePlaceName, isPlaceMatch, activeItemRef,
    handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
}) => {
    const districtsProps = {
        districts: stateNode.districts, stateKey, stateName: stateNode.name, countryName,
        collapsedNodes, toggleCollapse, activePlaceName, isPlaceMatch, activeItemRef,
        handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
    };
    return (
        <div className="border-l border-slate-200 ml-2.5 pl-2 py-0.5 space-y-0.5 mt-0.5">
            {childStateLocations.map(locGroup => (
                <DirectoryLeafLocationItem
                    key={locGroup.place} place={locGroup.place}
                    displayName={cleanLocationDisplayName(locGroup.place, stateNode.name, null, countryName)}
                    count={locGroup.count} isSelected={Boolean(activePlaceName && isPlaceMatch(locGroup.place, activePlaceName))}
                    activeItemRef={activeItemRef} onSelect={() => handleSelectLocation(locGroup.place)}
                />
            ))}
            <DirectoryStateDistrictsList {...districtsProps} />
        </div>
    );
};

/**
 * Computes collapse, active state, all places, and child locations for a state hierarchy node.
 *
 * @param {Object} options
 * @param {Object} options.stateNode - State node object with name, locations, and districts.
 * @param {string} options.countryName - Parent country name.
 * @param {Object} options.collapsedNodes - Map of collapsed state by node key.
 * @param {string|null} options.activePlaceName - Active place name filter.
 * @param {Function} options.isPlaceMatch - Place matching predicate function.
 * @returns {{
 *   stateKey: string,
 *   isStateCollapsed: boolean,
 *   allStatePlaces: Array<Object>,
 *   isStateActive: boolean,
 *   childStateLocations: Array<Object>,
 *   hasStateDistricts: boolean,
 *   hasStateChildLocations: boolean
 * }} Computed state node layout state.
 *
 * @example
 *   resolveStateNodeState({
 *     stateNode: { name: 'Kerala', locations: [], districts: [] },
 *     countryName: 'India',
 *     collapsedNodes: {},
 *     activePlaceName: null,
 *     isPlaceMatch: () => false
 *   });
 *
 * @example
 *   resolveStateNodeState({
 *     stateNode: { name: 'Texas', locations: [{ place: 'Austin' }], districts: [] },
 *     countryName: 'USA',
 *     collapsedNodes: { 'USA/Texas': true },
 *     activePlaceName: 'Austin',
 *     isPlaceMatch: (a, b) => a === b
 *   });
 */
function resolveStateNodeState({
    stateNode, countryName, collapsedNodes, activePlaceName, isPlaceMatch
}) {
    const stateKey = `${countryName}/${stateNode.name}`;
    const isStateCollapsed = !!collapsedNodes[stateKey];
    const allStatePlaces = getAllStatePlaces(stateNode);
    const isStateActive = isDirectoryRegionActive(stateNode.name, allStatePlaces, activePlaceName, isPlaceMatch, 'state');
    const childStateLocations = filterDistinctChildLocations(stateNode.locations, stateNode.name);

    return {
        stateKey, isStateCollapsed, allStatePlaces, isStateActive, childStateLocations,
        hasStateDistricts: stateNode.districts.length > 0,
        hasStateChildLocations: childStateLocations.length > 0
    };
}

/**
 * Renders a flat button for a leaf-level state directory node without child districts or locations.
 *
 * @param {Object} props
 * @param {Object} props.stateNode - State hierarchy node.
 * @param {string|null} props.activePlaceName - Currently active place name.
 * @param {Function} props.isPlaceMatch - Matching function for place names.
 * @param {React.RefObject} props.activeItemRef - Ref for active item scrolling.
 * @param {Function} props.handleSelectRegion - Selection handler.
 * @param {Array<string>} props.allStatePlaces - All place names under the state.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryLeafStateButton stateNode={stateNode} activePlaceName="Kerala" isPlaceMatch={isPlaceMatch} activeItemRef={ref} handleSelectRegion={handleSelectRegion} allStatePlaces={['Kochi']} />
 *
 * @example
 * <DirectoryLeafStateButton stateNode={stateNode} activePlaceName={null} isPlaceMatch={isPlaceMatch} activeItemRef={ref} handleSelectRegion={handleSelectRegion} allStatePlaces={[]} />
 */
const DirectoryLeafStateButton = ({
    stateNode, activePlaceName, isPlaceMatch, activeItemRef, handleSelectRegion, allStatePlaces
}) => (
    <DirectoryFlatRegionButton
        name={stateNode.name} count={stateNode.count}
        isSelected={Boolean(activePlaceName && isPlaceMatch(stateNode.name, activePlaceName))}
        activeItemRef={activeItemRef} onClick={() => handleSelectRegion(stateNode.name, allStatePlaces)}
        level="state"
    />
);

/**
 * Renders the collapsible branch container for a state directory node.
 *
 * @param {object} props
 * @param {object} props.stateNode - Current state node
 * @param {string} props.stateKey - Composite key identifying the state
 * @param {boolean} props.isStateCollapsed - Whether the state node is collapsed
 * @param {boolean} props.isStateActive - Whether the state node is currently active
 * @param {Function} props.toggleCollapse - Collapse toggle handler
 * @param {Function} props.handleSelectRegion - Region selection handler
 * @param {string[]} props.allStatePlaces - All places within the state
 * @param {React.RefObject} props.activeItemRef - Ref to scroll active item into view
 * @param {object} props.childrenProps - Props passed to DirectoryStateChildrenList
 * @returns {React.ReactNode}
 *
 * @example
 *   <DirectoryStateBranch stateNode={{ name: 'Kerala', count: 5 }} stateKey="India/Kerala" isStateCollapsed={false} isStateActive={true} toggleCollapse={() => {}} handleSelectRegion={() => {}} allStatePlaces={[]} activeItemRef={{ current: null }} childrenProps={{}} />
 *
 * @example
 *   <DirectoryStateBranch stateNode={{ name: 'California', count: 2 }} stateKey="US/California" isStateCollapsed={true} isStateActive={false} toggleCollapse={() => {}} handleSelectRegion={() => {}} allStatePlaces={['LA']} activeItemRef={{ current: null }} childrenProps={{}} />
 */
const DirectoryStateBranch = ({
    stateNode, stateKey, isStateCollapsed, isStateActive, toggleCollapse,
    handleSelectRegion, allStatePlaces, activeItemRef, childrenProps
}) => (
    <DirectoryCollapsibleRegionBranch
        name={stateNode.name} count={stateNode.count} isCollapsed={isStateCollapsed}
        isActive={Boolean(isStateActive)} onToggleCollapse={(e) => toggleCollapse(stateKey, e)}
        onSelectRegion={() => handleSelectRegion(stateNode.name, allStatePlaces)}
        activeItemRef={activeItemRef} level="state"
    >
        <DirectoryStateChildrenList {...childrenProps} />
    </DirectoryCollapsibleRegionBranch>
);

/**
 * Renders an individual state node within the location directory hierarchy,
 * including its child locations or nested districts.
 *
 * @param {object} props
 * @param {object} props.stateNode - State node containing name, count, locations, districts
 * @param {string} props.countryName - Parent country name
 * @param {object} props.collapsedNodes - Map of collapsed path keys
 * @param {Function} props.toggleCollapse - Collapse state toggler
 * @param {string|null} props.activePlaceName - Currently active place filter value
 * @param {Function} props.isPlaceMatch - Predicate matching location names
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view
 * @param {Function} props.handleSelectRegion - Region selection callback
 * @param {Function} props.handleSelectLocation - Leaf location selection callback
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names
 * @returns {React.ReactNode} Formatted state hierarchy element
 *
 * @example
 * <DirectoryStateNode
 *   stateNode={{ name: 'California', count: 10, locations: [], districts: [] }}
 *   countryName="United States"
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={(p) => p}
 * />
 *
 * @example
 * <DirectoryStateNode
 *   stateNode={{ name: 'Kerala', count: 42, locations: [{ place: 'Kochi', count: 12 }], districts: [] }}
 *   countryName="India"
 *   collapsedNodes={{ 'India/Kerala': false }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="Kochi"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={(r) => console.log(r)}
 *   handleSelectLocation={(l) => console.log(l)}
 *   cleanLocationDisplayName={(p) => p}
 * />
 */
const DirectoryStateNode = ({
    stateNode, countryName, collapsedNodes, toggleCollapse, activePlaceName, isPlaceMatch,
    activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
}) => {
    const {
        stateKey, isStateCollapsed, allStatePlaces, isStateActive,
        childStateLocations, hasStateDistricts, hasStateChildLocations
    } = resolveStateNodeState({ stateNode, countryName, collapsedNodes, activePlaceName, isPlaceMatch });

    if (!hasStateDistricts && !hasStateChildLocations) {
        return (
            <DirectoryLeafStateButton
                stateNode={stateNode} activePlaceName={activePlaceName} isPlaceMatch={isPlaceMatch}
                activeItemRef={activeItemRef} handleSelectRegion={handleSelectRegion} allStatePlaces={allStatePlaces}
            />
        );
    }

    return (
        <DirectoryStateBranch
            stateNode={stateNode} stateKey={stateKey} isStateCollapsed={isStateCollapsed}
            isStateActive={Boolean(isStateActive)} toggleCollapse={toggleCollapse}
            handleSelectRegion={handleSelectRegion} allStatePlaces={allStatePlaces}
            activeItemRef={activeItemRef}
            childrenProps={{
                childStateLocations, stateNode, stateKey, countryName, collapsedNodes, toggleCollapse,
                activePlaceName, isPlaceMatch, activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
            }}
        />
    );
};

/**
 * Renders the expanded child locations and nested state subtrees for a country directory node.
 *
 * @param {Object} props
 * @param {Array<Object>} props.childCountryLocations - Direct leaf location items under the country.
 * @param {Object} props.countryNode - Current country hierarchy node.
 * @param {Object} props.collapsedNodes - Map of collapsed path keys.
 * @param {Function} props.toggleCollapse - Collapse state toggler.
 * @param {string|null} props.activePlaceName - Currently active place filter value.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view.
 * @param {Function} props.handleSelectRegion - Region selection callback.
 * @param {Function} props.handleSelectLocation - Leaf location selection callback.
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names.
 * @returns {React.ReactElement} Formatted child locations and state nodes container.
 *
 * @example
 * <DirectoryCountryChildrenList
 *   childCountryLocations={[]}
 *   countryNode={{ name: 'India', states: [] }}
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={(p) => p}
 * />
 *
 * @example
 * <DirectoryCountryChildrenList
 *   childCountryLocations={[{ place: 'New Delhi', count: 12 }]}
 *   countryNode={{ name: 'India', states: [{ name: 'Kerala', locations: [], districts: [] }] }}
 *   collapsedNodes={{ 'India/Kerala': true }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="New Delhi"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={(r) => console.log(r)}
 *   handleSelectLocation={(l) => console.log(l)}
 *   cleanLocationDisplayName={(p) => p}
 * />
 */
/**
 * Renders the collection of child state nodes within an expanded country directory node.
 *
 * @param {Object} props
 * @param {Array<Object>} props.states - Array of state hierarchy nodes.
 * @param {string} props.countryName - Name of the parent country.
 * @param {Object} props.collapsedNodes - Map of collapsed node keys.
 * @param {Function} props.toggleCollapse - Node collapse toggle callback.
 * @param {string|null} props.activePlaceName - Currently selected place name filter.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to active DOM node.
 * @param {Function} props.handleSelectRegion - Region selection callback.
 * @param {Function} props.handleSelectLocation - Location selection callback.
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryCountryStatesList
 *   states={[]}
 *   countryName="India"
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 *
 * @example
 * <DirectoryCountryStatesList
 *   states={[{ name: 'Kerala', count: 10, locations: [], districts: [] }]}
 *   countryName="India"
 *   collapsedNodes={{ 'India/Kerala': false }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="Kerala"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 */
const DirectoryCountryStatesList = ({
    states,
    countryName,
    collapsedNodes,
    toggleCollapse,
    activePlaceName,
    isPlaceMatch,
    activeItemRef,
    handleSelectRegion,
    handleSelectLocation,
    cleanLocationDisplayName
}) => (
    <>
        {states.map(stateNode => (
            <DirectoryStateNode
                key={stateNode.name}
                stateNode={stateNode}
                countryName={countryName}
                collapsedNodes={collapsedNodes}
                toggleCollapse={toggleCollapse}
                activePlaceName={activePlaceName}
                isPlaceMatch={isPlaceMatch}
                activeItemRef={activeItemRef}
                handleSelectRegion={handleSelectRegion}
                handleSelectLocation={handleSelectLocation}
                cleanLocationDisplayName={cleanLocationDisplayName}
            />
        ))}
    </>
);

/**
 * Renders direct child leaf location items belonging to a country node in the directory hierarchy.
 *
 * @param {Object} props - Component properties
 * @param {Array<Object>} props.locations - List of leaf location items with place and count.
 * @param {string} props.countryName - Name of the parent country.
 * @param {string|null} props.activePlaceName - Currently selected place name filter.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to active DOM node.
 * @param {Function} props.handleSelectLocation - Location selection callback.
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryCountryLeafLocations
 *   locations={[]}
 *   countryName="India"
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 *
 * @example
 * <DirectoryCountryLeafLocations
 *   locations={[{ place: 'Kochi', count: 5 }]}
 *   countryName="India"
 *   activePlaceName="Kochi"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={p => p}
 * />
 */
const DirectoryCountryLeafLocations = ({
    locations,
    countryName,
    activePlaceName,
    isPlaceMatch,
    activeItemRef,
    handleSelectLocation,
    cleanLocationDisplayName
}) => (
    <>
        {locations.map(locGroup => (
            <DirectoryLeafLocationItem
                key={locGroup.place}
                place={locGroup.place}
                displayName={cleanLocationDisplayName(locGroup.place, null, null, countryName)}
                count={locGroup.count}
                isSelected={Boolean(activePlaceName && isPlaceMatch(locGroup.place, activePlaceName))}
                activeItemRef={activeItemRef}
                onSelect={() => handleSelectLocation(locGroup.place)}
            />
        ))}
    </>
);

/**
 * Renders child leaf locations and state subtrees belonging to a country node in the directory.
 *
 * @param {Object} props - Component properties
 * @returns {React.ReactNode} Rendered country child elements
 *
 * @example
 * <DirectoryCountryChildrenList countryNode={node} childCountryLocations={[]} {...props} />
 *
 * @example
 * <DirectoryCountryChildrenList countryNode={usaNode} childCountryLocations={locs} {...props} />
 */
const DirectoryCountryChildrenList = ({
    childCountryLocations, countryNode, collapsedNodes, toggleCollapse, activePlaceName,
    isPlaceMatch, activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
}) => (
    <div className="border-l-2 border-slate-200 ml-3.5 pl-2 py-0.5 space-y-1 mt-0.5">
        <DirectoryCountryLeafLocations
            locations={childCountryLocations} countryName={countryNode.name} activePlaceName={activePlaceName}
            isPlaceMatch={isPlaceMatch} activeItemRef={activeItemRef} handleSelectLocation={handleSelectLocation}
            cleanLocationDisplayName={cleanLocationDisplayName}
        />
        <DirectoryCountryStatesList
            states={countryNode.states} countryName={countryNode.name} collapsedNodes={collapsedNodes}
            toggleCollapse={toggleCollapse} activePlaceName={activePlaceName} isPlaceMatch={isPlaceMatch}
            activeItemRef={activeItemRef} handleSelectRegion={handleSelectRegion} handleSelectLocation={handleSelectLocation}
            cleanLocationDisplayName={cleanLocationDisplayName}
        />
    </div>
);

/**
 * Computes collapse, active state, all places, and child locations for a country hierarchy node.
 *
 * @param {Object} options
 * @param {Object} options.countryNode - Country node object with name, locations, and states.
 * @param {Object} options.collapsedNodes - Map of collapsed state by node key.
 * @param {string|null} options.activePlaceName - Active place name filter.
 * @param {Function} options.isPlaceMatch - Place matching predicate function.
 * @returns {{
 *   isCountryCollapsed: boolean,
 *   allCountryPlaces: Array<Object>,
 *   isCountryActive: boolean,
 *   childCountryLocations: Array<Object>,
 *   hasCountryStates: boolean,
 *   hasCountryChildLocations: boolean
 * }} Computed country node layout state.
 *
 * @example
 *   resolveCountryNodeState({
 *     countryNode: { name: 'India', locations: [], states: [] },
 *     collapsedNodes: {},
 *     activePlaceName: null,
 *     isPlaceMatch: () => false
 *   });
 *
 * @example
 *   resolveCountryNodeState({
 *     countryNode: { name: 'USA', locations: [{ place: 'New York' }], states: [] },
 *     collapsedNodes: { USA: true },
 *     activePlaceName: 'New York',
 *     isPlaceMatch: (a, b) => a === b
 *   });
 */
function resolveCountryNodeState({
    countryNode,
    collapsedNodes,
    activePlaceName,
    isPlaceMatch
}) {
    const isCountryCollapsed = !!collapsedNodes[countryNode.name];
    const allCountryPlaces = getAllCountryPlaces(countryNode);
    const isCountryActive = isDirectoryRegionActive(
        countryNode.name,
        allCountryPlaces,
        activePlaceName,
        isPlaceMatch,
        'country'
    );
    const childCountryLocations = filterDistinctChildLocations(countryNode.locations, countryNode.name);
    const hasCountryStates = countryNode.states.length > 0;
    const hasCountryChildLocations = childCountryLocations.length > 0;

    return {
        isCountryCollapsed,
        allCountryPlaces,
        isCountryActive,
        childCountryLocations,
        hasCountryStates,
        hasCountryChildLocations
    };
}

/**
 * Leaf country button rendered when a country hierarchy node has neither states nor child locations.
 *
 * @param {Object} props
 * @param {Object} props.countryNode - Country hierarchy node.
 * @param {string|null} props.activePlaceName - Currently active place filter value.
 * @param {Function} props.isPlaceMatch - Predicate matching location names.
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view.
 * @param {Function} props.handleSelectRegion - Region selection callback.
 * @param {Array<Object>} props.allCountryPlaces - All places in country.
 * @returns {React.ReactElement}
 *
 * @example
 * <DirectoryLeafCountryButton countryNode={node} activePlaceName={null} isPlaceMatch={() => false} activeItemRef={{}} handleSelectRegion={() => {}} allCountryPlaces={[]} />
 *
 * @example
 * <DirectoryLeafCountryButton countryNode={usa} activePlaceName="USA" isPlaceMatch={(a, b) => a === b} activeItemRef={{}} handleSelectRegion={() => {}} allCountryPlaces={[]} />
 */
const DirectoryLeafCountryButton = ({
    countryNode, activePlaceName, isPlaceMatch, activeItemRef, handleSelectRegion, allCountryPlaces
}) => (
    <DirectoryFlatRegionButton
        name={countryNode.name} flag={countryNode.flag} count={countryNode.count}
        isSelected={Boolean(activePlaceName && isPlaceMatch(countryNode.name, activePlaceName))}
        activeItemRef={activeItemRef} onClick={() => handleSelectRegion(countryNode.name, allCountryPlaces)}
        level="country"
    />
);

/**
 * Renders an expandable country branch containing state groups and child locations.
 *
 * @param {object} props
 * @param {object} props.countryNode - Country tree node
 * @param {boolean} props.isCountryCollapsed - Whether the country section is collapsed
 * @param {boolean} props.isCountryActive - Whether the country is actively selected
 * @param {Function} props.toggleCollapse - Collapse toggle handler
 * @param {Function} props.handleSelectRegion - Region selection handler
 * @param {string[]} props.allCountryPlaces - All places in the country
 * @param {React.RefObject} props.activeItemRef - Ref to scroll active item into view
 * @param {object} props.childrenProps - Props passed to DirectoryCountryChildrenList
 * @returns {React.ReactNode}
 *
 * @example
 *   <DirectoryCountryBranch countryNode={{ name: 'India' }} isCountryCollapsed={false} isCountryActive={true} toggleCollapse={() => {}} handleSelectRegion={() => {}} allCountryPlaces={[]} activeItemRef={{ current: null }} childrenProps={{}} />
 *
 * @example
 *   <DirectoryCountryBranch countryNode={{ name: 'US' }} isCountryCollapsed={true} isCountryActive={false} toggleCollapse={() => {}} handleSelectRegion={() => {}} allCountryPlaces={['A']} activeItemRef={{ current: null }} childrenProps={{}} />
 */
const DirectoryCountryBranch = ({
    countryNode, isCountryCollapsed, isCountryActive, toggleCollapse,
    handleSelectRegion, allCountryPlaces, activeItemRef, childrenProps
}) => (
    <DirectoryCollapsibleRegionBranch
        name={countryNode.name} flag={countryNode.flag} count={countryNode.count}
        isCollapsed={isCountryCollapsed} isActive={Boolean(isCountryActive)}
        onToggleCollapse={(e) => toggleCollapse(countryNode.name, e)}
        onSelectRegion={() => handleSelectRegion(countryNode.name, allCountryPlaces)}
        activeItemRef={activeItemRef} level="country"
    >
        <DirectoryCountryChildrenList {...childrenProps} />
    </DirectoryCollapsibleRegionBranch>
);

/**
 * Renders an individual country node in the directory hierarchy,
 * including its flag, name, count, direct cities, and child state subtrees.
 *
 * @param {object} props
 * @param {object} props.countryNode - Country hierarchy node
 * @param {object} props.collapsedNodes - Map of collapsed path keys
 * @param {Function} props.toggleCollapse - Collapse state toggler
 * @param {string|null} props.activePlaceName - Currently active place filter value
 * @param {Function} props.isPlaceMatch - Predicate matching location names
 * @param {React.RefObject} props.activeItemRef - Ref to scroll into view
 * @param {Function} props.handleSelectRegion - Region selection callback
 * @param {Function} props.handleSelectLocation - Leaf location selection callback
 * @param {Function} props.cleanLocationDisplayName - Formatter for location display names
 * @returns {React.ReactNode} Formatted country hierarchy element
 *
 * @example
 * <DirectoryCountryNode
 *   countryNode={{ name: 'India', flag: '🇮🇳', count: 50, states: [], locations: [] }}
 *   collapsedNodes={{}}
 *   toggleCollapse={() => {}}
 *   activePlaceName={null}
 *   isPlaceMatch={() => false}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={() => {}}
 *   handleSelectLocation={() => {}}
 *   cleanLocationDisplayName={(p) => p}
 * />
 *
 * @example
 * <DirectoryCountryNode
 *   countryNode={{ name: 'United States', flag: '🇺🇸', count: 12, states: [], locations: [] }}
 *   collapsedNodes={{ 'United States': false }}
 *   toggleCollapse={(k) => console.log(k)}
 *   activePlaceName="California"
 *   isPlaceMatch={(a, b) => a === b}
 *   activeItemRef={{ current: null }}
 *   handleSelectRegion={(r) => console.log(r)}
 *   handleSelectLocation={(l) => console.log(l)}
 *   cleanLocationDisplayName={(p) => p}
 * />
 */
const DirectoryCountryNode = ({
    countryNode, collapsedNodes, toggleCollapse, activePlaceName, isPlaceMatch,
    activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
}) => {
    const {
        isCountryCollapsed, allCountryPlaces, isCountryActive,
        childCountryLocations, hasCountryStates, hasCountryChildLocations
    } = resolveCountryNodeState({ countryNode, collapsedNodes, activePlaceName, isPlaceMatch });

    if (!hasCountryStates && !hasCountryChildLocations) {
        return (
            <DirectoryLeafCountryButton
                countryNode={countryNode} activePlaceName={activePlaceName} isPlaceMatch={isPlaceMatch}
                activeItemRef={activeItemRef} handleSelectRegion={handleSelectRegion} allCountryPlaces={allCountryPlaces}
            />
        );
    }

    return (
        <DirectoryCountryBranch
            countryNode={countryNode} isCountryCollapsed={isCountryCollapsed}
            isCountryActive={Boolean(isCountryActive)} toggleCollapse={toggleCollapse}
            handleSelectRegion={handleSelectRegion} allCountryPlaces={allCountryPlaces}
            activeItemRef={activeItemRef}
            childrenProps={{
                childCountryLocations, countryNode, collapsedNodes, toggleCollapse, activePlaceName,
                isPlaceMatch, activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
            }}
        />
    );
};

