/**
 * Cleans and formats a raw place name for display in the directory selector,
 * stripping redundant state/district/country parent suffixes.
 *
 * @param {string} place - Raw place name
 * @param {string|null} [parentState=null] - Parent state name
 * @param {string|null} [parentDistrict=null] - Parent district name
 * @param {string|null} [parentCountry=null] - Parent country name
 * @returns {string} Cleaned place display name
 *
 * @example
 * cleanLocationDisplayName('Kochi, Kerala', 'Kerala')
 * // => 'Kochi'
 *
 * @example
 * cleanLocationDisplayName('Seattle, WA')
 * // => 'Seattle'
 */
function cleanLocationDisplayName(place, parentState = null, parentDistrict = null, parentCountry = null) {
    if (!place || FamilyTreeBuilder.isInvalidLocation(place)) return '';
    const p = place.trim();
    const norm = p.toLowerCase();
    
    // Explicit known cleanups
    if (norm.includes('seattle')) return 'Seattle';
    if (norm.includes('naples')) return 'Naples';
    
    const parts = p.split(',').map(s => s.trim()).filter(Boolean);
    return parts.length > 0 ? parts[0] : p;
}

/**
 * Checks if two location strings match by exact equality, comma-separated token inclusion, or substring inclusion.
 *
 * @param {?string} itemPlace - Place string from person or location node
 * @param {?string} filterPlace - Filter or query place string
 * @returns {boolean} True if the places are considered matching
 *
 * @example
 * isPlaceMatch("Kochi, Ernakulam", "Kochi");
 * // => true
 *
 * @example
 * isPlaceMatch("New York", "London");
 * // => false
 */
function isPlaceMatch(itemPlace, filterPlace) {
    if (!itemPlace || !filterPlace) return false;
    const i = itemPlace.toLowerCase().trim();
    const f = filterPlace.toLowerCase().trim();
    if (i === f) return true;
    const iParts = i.split(',').map(s => s.trim());
    if (iParts.includes(f)) return true;
    const fParts = f.split(',').map(s => s.trim());
    if (fParts.includes(i)) return true;
    return i.includes(f) || f.includes(i);
}

/**
 * Resolves the active directory tab ('place' | 'job' | 'family') from activeFilter or fallback tab.
 *
 * @param {?{filterType?: string, tab?: string}} activeFilter - Current filter state
 * @param {string} [fallbackTab='place'] - Default fallback tab
 * @returns {'place'|'job'|'family'} Resolved tab identifier
 *
 * @example
 * resolveActiveDirectoryTab({ filterType: 'job', value: 'Doctor' });
 * // => 'job'
 *
 * @example
 * resolveActiveDirectoryTab(null, 'place');
 * // => 'place'
 */
function resolveActiveDirectoryTab(activeFilter, fallbackTab = 'place') {
    if (activeFilter?.filterType && ['place', 'job', 'family'].includes(activeFilter.filterType)) {
        return activeFilter.filterType;
    }
    if (activeFilter?.filterType === 'directory' && activeFilter.tab) {
        return activeFilter.tab;
    }
    return fallbackTab || 'place';
}

/**
 * Uncollapses hierarchical location ancestor keys (country, state, district)
 * corresponding to an active place or matching place groups.
 *
 * @param {Object<string, boolean>} collapsedNodes - Map of collapsed node keys
 * @param {string|null} activePlaceName - Name of currently active place filter
 * @param {Array<{place: string}>} placeGroups - Grouped place records
 * @param {Function} [matcher=isPlaceMatch] - Matcher function between two place strings
 * @returns {Object<string, boolean>} Updated collapsed nodes map
 *
 * @example
 * uncollapseLocationHierarchy({ 'India': true, 'India/Kerala': true }, 'Kochi', [{ place: 'Kochi' }])
 * // => {} (uncollapses 'India' and 'India/Kerala')
 *
 * @example
 * uncollapseLocationHierarchy({ 'India': true }, null, [])
 * // => { 'India': true }
 */
function uncollapseLocationHierarchy(collapsedNodes, activePlaceName, placeGroups, matcher = isPlaceMatch) {
    if (!activePlaceName) return collapsedNodes;
    const next = { ...collapsedNodes };
    const directH = resolvePlaceHierarchy(activePlaceName);
    if (directH.country) delete next[directH.country];
    if (directH.country && directH.state) delete next[`${directH.country}/${directH.state}`];
    if (directH.country && directH.state && directH.district) delete next[`${directH.country}/${directH.state}/${directH.district}`];

    placeGroups.forEach(group => {
        if (matcher(group.place, activePlaceName)) {
            const h = resolvePlaceHierarchy(group.place);
            if (h.country) delete next[h.country];
            if (h.country && h.state) delete next[`${h.country}/${h.state}`];
            if (h.country && h.state && h.district) delete next[`${h.country}/${h.state}/${h.district}`];
        }
    });
    return next;
}

/**
 * Resolves item count and descriptive plural noun label for the active directory tab.
 *
 * @param {string} currentTab - Active directory tab ('place', 'job', or 'family').
 * @param {Array<object>} placeGroups - Computed place groupings.
 * @param {Array<object>} jobGroups - Computed career groupings.
 * @param {Array<object>} familyGroups - Computed family branch groupings.
 * @returns {{ currentTotalCount: number, countLabel: string }} Current count and label.
 *
 * @example
 *   getDirectoryTabStats('place', [{ id: 1 }], [], []);
 *   // returns { currentTotalCount: 1, countLabel: 'places' }
 *
 * @example
 *   getDirectoryTabStats('job', [], [{ id: 'Engineer' }, { id: 'Doctor' }], []);
 *   // returns { currentTotalCount: 2, countLabel: 'careers' }
 */
function getDirectoryTabStats(currentTab, placeGroups, jobGroups, familyGroups) {
    const currentTotalCount = currentTab === 'place' ? placeGroups.length : (currentTab === 'job' ? jobGroups.length : familyGroups.length);
    const countLabel = currentTab === 'place' ? 'places' : (currentTab === 'job' ? 'careers' : 'families');
    return { currentTotalCount, countLabel };
}

/**
 * Creates dispatch callbacks for selecting places, regions, jobs, and family names in the quick directory.
 *
 * @param {object} options - Options object.
 * @param {Function} options.onFilterBy - Primary filter dispatch callback.
 * @param {Function} [options.onFlyToLocation] - Optional callback to pan/fly map to a specific location.
 * @param {Function} [options.onFlyToRegion] - Optional callback to pan/fly map to a bounding region.
 * @returns {{
 *   handleSelectLocation: Function,
 *   handleSelectRegion: Function,
 *   handleSelectJob: Function,
 *   handleSelectFamily: Function
 * }} Collection of category selection handlers.
 *
 * @example
 *   const handlers = createDirectorySelectionHandlers({
 *     onFilterBy: (type, val) => console.log(type, val),
 *     onFlyToLocation: (loc) => map.flyTo(loc)
 *   });
 *   handlers.handleSelectLocation('Kerala, India');
 *
 * @example
 *   const handlers = createDirectorySelectionHandlers({
 *     onFilterBy: () => {}
 *   });
 *   handlers.handleSelectJob('Physician');
 */
function createDirectorySelectionHandlers({ onFilterBy, onFlyToLocation, onFlyToRegion }) {
    const handleSelectLocation = (place) => {
        const cleanPlace = cleanLocationDisplayName(place);
        onFilterBy('place', cleanPlace);
        if (onFlyToLocation) onFlyToLocation(place);
    };

    const handleSelectRegion = (regionName, regionPlaces) => {
        onFilterBy('place', regionName);
        if (onFlyToRegion) onFlyToRegion(regionName, regionPlaces);
    };

    const handleSelectJob = (job) => {
        onFilterBy('job', job);
    };

    const handleSelectFamily = (family) => {
        onFilterBy('family', family);
    };

    return {
        handleSelectLocation,
        handleSelectRegion,
        handleSelectJob,
        handleSelectFamily
    };
}

/**
 * Hook computing grouped directory collections (places hierarchy, jobs, and family branches)
 * filtered by the current directory tab and search query string.
 *
 * @param {object} params
 * @param {FamilyTree} params.tree - Family tree domain model
 * @param {string} params.currentTab - Active directory tab ('place' | 'job' | 'family')
 * @param {string} params.searchQuery - User-entered search filter query
 * @returns {{
 *   placeGroups: Array<object>,
 *   locationHierarchyTree: Array<object>,
 *   jobGroups: Array<object>,
 *   familyGroups: Array<object>
 * }}
 *
 * @example
 * const { placeGroups, locationHierarchyTree } = useDirectoryGroupData({
 *   tree,
 *   currentTab: 'place',
 *   searchQuery: 'Kerala'
 * });
 *
 * @example
 * const { jobGroups, familyGroups } = useDirectoryGroupData({
 *   tree,
 *   currentTab: 'job',
 *   searchQuery: 'Engineer'
 * });
 */
function useDirectoryGroupData({ tree, currentTab, searchQuery }) {
    const placeGroups = useMemo(() => computePlaceGroups(tree), [tree]);

    const locationHierarchyTree = useMemo(() => {
        const q = (currentTab === 'place' ? searchQuery : '').toLowerCase().trim();
        return buildLocationHierarchy(placeGroups, q);
    }, [placeGroups, searchQuery, currentTab]);

    const jobGroups = useMemo(() => {
        const q = (currentTab === 'job' ? searchQuery : '').toLowerCase().trim();
        return computeJobGroups(tree, q);
    }, [tree, searchQuery, currentTab]);

    const familyGroups = useMemo(() => {
        const q = (currentTab === 'family' ? searchQuery : '').toLowerCase().trim();
        return computeFamilyGroups(tree, q);
    }, [tree, searchQuery, currentTab]);

    return { placeGroups, locationHierarchyTree, jobGroups, familyGroups };
}

/**
 * Hook to automatically scroll the currently active directory item into view after selection changes.
 *
 * @param {React.RefObject} activeItemRef - DOM ref to the active directory list element.
 * @param {Array<any>} dependencies - Array of trigger dependencies (place, job, family, tab).
 *
 * @example
 * const ref = { current: document.createElement('div') };
 * useDirectoryAutoScroll(ref, ['Kerala', 'place']);
 *
 * @example
 * useDirectoryAutoScroll({ current: null }, []);
 */
function useDirectoryAutoScroll(activeItemRef, dependencies) {
    useEffect(() => {
        if (activeItemRef.current) {
            const timer = setTimeout(() => {
                activeItemRef.current?.scrollIntoView({
                    behavior: 'smooth',
                    block: 'center'
                });
            }, 100);
            return () => clearTimeout(timer);
        }
    }, dependencies);
}

/**
 * Hook managing tree node collapse states in the directory selector and auto-scrolling
 * the active highlighted location, job, or family node into view.
 *
 * @param {object} params
 * @param {string|null} params.activePlaceName - Currently active place name
 * @param {string|null} params.activeJobName - Currently active job name
 * @param {string|null} params.activeFamilyName - Currently active family name
 * @param {string} params.currentTab - Active tab identifier
 * @param {Array<object>} params.placeGroups - Computed place groupings for uncollapsing paths
 * @returns {{
 *   collapsedNodes: object,
 *   activeItemRef: React.RefObject<HTMLElement>,
 *   toggleCollapse: (nodeKey: string, e?: React.SyntheticEvent) => void
 * }}
 *
 * @example
 * const { collapsedNodes, activeItemRef, toggleCollapse } = useDirectoryCollapseAndScroll({
 *   activePlaceName: 'Thrissur',
 *   activeJobName: null,
 *   activeFamilyName: null,
 *   currentTab: 'place',
 *   placeGroups: []
 * });
 * toggleCollapse('Asia/India');
 *
 * @example
 * const { activeItemRef } = useDirectoryCollapseAndScroll({
 *   activePlaceName: null,
 *   activeJobName: 'Doctor',
 *   activeFamilyName: null,
 *   currentTab: 'job',
 *   placeGroups: []
 * });
 */
function useDirectoryCollapseAndScroll({
    activePlaceName,
    activeJobName,
    activeFamilyName,
    currentTab,
    placeGroups
}) {
    const [collapsedNodes, setCollapsedNodes] = useState({});
    const activeItemRef = useRef(null);

    useEffect(() => {
        if (activePlaceName) {
            setCollapsedNodes(prev => uncollapseLocationHierarchy(prev, activePlaceName, placeGroups, isPlaceMatch));
        }
    }, [activePlaceName, placeGroups]);

    useDirectoryAutoScroll(activeItemRef, [activePlaceName, activeJobName, activeFamilyName, currentTab]);

    const toggleCollapse = (nodeKey, e) => {
        if (e) e.stopPropagation();
        setCollapsedNodes(prev => ({
            ...prev,
            [nodeKey]: !prev[nodeKey]
        }));
    };

    return { collapsedNodes, activeItemRef, toggleCollapse };
}

/**
 * Synchronizes and manages the active tab selection within the directory view.
 *
 * @param {object|null} activeFilter - Active tree filter specification.
 * @param {string} [initialTab='place'] - Default tab fallback.
 * @returns {[string, Function]} Current tab identifier and its setter function.
 *
 * @example
 *   const [tab, setTab] = useDirectoryTabState(null, 'job');
 *
 * @example
 *   const [tab, setTab] = useDirectoryTabState({ filterType: 'place', value: 'Kerala' }, 'place');
 */
function useDirectoryTabState(activeFilter, initialTab = 'place') {
    const [currentTab, setCurrentTab] = useState(() => resolveActiveDirectoryTab(activeFilter, initialTab));

    useEffect(() => {
        const resolved = resolveActiveDirectoryTab(activeFilter, null);
        if (resolved) {
            setCurrentTab(resolved);
        }
    }, [activeFilter?.filterType, activeFilter?.tab]);

    return [currentTab, setCurrentTab];
}

/**
 * Resolves active directory filter values for place, job, and family from an active filter state.
 *
 * @param {object|null} activeFilter - Active tree filter specification.
 * @returns {{ activePlaceName: string|null, activeJobName: string|null, activeFamilyName: string|null }}
 *   Resolved active names for directory tab categories.
 *
 * @example
 *   const { activePlaceName } = resolveActiveDirectoryFilterNames({ filterType: 'place', value: 'Paris' });
 *
 * @example
 *   const { activeJobName } = resolveActiveDirectoryFilterNames({ filterType: 'job', value: 'Architect' });
 */
function resolveActiveDirectoryFilterNames(activeFilter) {
    return {
        activePlaceName: activeFilter?.filterType === 'place' ? activeFilter.value : null,
        activeJobName: activeFilter?.filterType === 'job' ? activeFilter.value : null,
        activeFamilyName: activeFilter?.filterType === 'family' ? activeFilter.value : null
    };
}

/**
 * Hook managing directory tabs, location hierarchy tree computations, career/family groupings,
 * active item scrolling, and selection callbacks for QuickDirectorySelector.
 *
 * @param {object} options
 * @param {FamilyTree} options.tree - Genealogical family tree instance
 * @param {object|null} options.activeFilter - Currently active filter specification
 * @param {Function} options.onFilterBy - Callback to activate category or attribute filter
 * @param {Function} [options.onFlyToLocation] - Optional callback to fly map to specific place
 * @param {Function} [options.onFlyToRegion] - Optional callback to fly map to broad region
 * @param {string} [options.initialTab='place'] - Default directory tab identifier
 * @returns {{
 *   currentTab: string,
 *   setCurrentTab: Function,
 *   searchQuery: string,
 *   setSearchQuery: Function,
 *   collapsedNodes: object,
 *   locationHierarchyTree: Array<object>,
 *   jobGroups: Array<object>,
 *   familyGroups: Array<object>,
 *   activePlaceName: string|null,
 *   activeJobName: string|null,
 *   activeFamilyName: string|null,
 *   activeItemRef: React.RefObject,
 *   toggleCollapse: Function,
 *   handleSelectLocation: Function,
 *   handleSelectRegion: Function,
 *   handleSelectJob: Function,
 *   handleSelectFamily: Function,
 *   currentTotalCount: number,
 *   countLabel: string
 * }}
 *
 * @example
 *   const dir = useQuickDirectoryData({ tree, activeFilter: null, onFilterBy: () => {} });
 *
 * @example
 *   const dir = useQuickDirectoryData({
 *       tree,
 *       activeFilter: { filterType: 'job', value: 'Teacher' },
 *       onFilterBy: handleFilter,
 *       initialTab: 'job'
 *   });
 */
function useQuickDirectoryData({
    tree, activeFilter, onFilterBy, onFlyToLocation, onFlyToRegion, initialTab = 'place'
}) {
    const [currentTab, setCurrentTab] = useDirectoryTabState(activeFilter, initialTab);
    const [searchQuery, setSearchQuery] = useState('');

    const { placeGroups, locationHierarchyTree, jobGroups, familyGroups } =
        useDirectoryGroupData({ tree, currentTab, searchQuery });

    const { activePlaceName, activeJobName, activeFamilyName } = resolveActiveDirectoryFilterNames(activeFilter);

    const { collapsedNodes, activeItemRef, toggleCollapse } = useDirectoryCollapseAndScroll({
        activePlaceName, activeJobName, activeFamilyName, currentTab, placeGroups
    });

    const { handleSelectLocation, handleSelectRegion, handleSelectJob, handleSelectFamily } =
        createDirectorySelectionHandlers({ onFilterBy, onFlyToLocation, onFlyToRegion });

    const { currentTotalCount, countLabel } = getDirectoryTabStats(currentTab, placeGroups, jobGroups, familyGroups);

    return {
        currentTab, setCurrentTab, searchQuery, setSearchQuery,
        collapsedNodes, locationHierarchyTree, jobGroups, familyGroups,
        activePlaceName, activeJobName, activeFamilyName, activeItemRef,
        toggleCollapse, handleSelectLocation, handleSelectRegion,
        handleSelectJob, handleSelectFamily, currentTotalCount, countLabel
    };
}

/**
 * Renders the scrollable tab body for the directory selector, switching between
 * places, jobs, and families tabs based on the active selection.
 *
 * @param {Object} props - Component properties.
 * @param {string} props.currentTab - Active directory tab ('place' | 'job' | 'family').
 * @param {boolean} [props.inSidebar=false] - Whether rendered inside the sidebar.
 * @param {Array} props.locationHierarchyTree - Hierarchical place node structures.
 * @param {Set} props.collapsedNodes - Set of collapsed node path keys.
 * @param {Function} props.toggleCollapse - Callback to toggle collapsed node state.
 * @param {string|null} props.activePlaceName - Name of currently active place filter.
 * @param {React.RefObject} props.activeItemRef - Ref to scroll active item into view.
 * @param {Function} props.handleSelectRegion - Handler to select region filter.
 * @param {Function} props.handleSelectLocation - Handler to select specific location filter.
 * @param {Array} props.jobGroups - Grouped career entries.
 * @param {string|null} props.activeJobName - Name of currently active job filter.
 * @param {Function} props.handleSelectJob - Handler to select job filter.
 * @param {Array} props.familyGroups - Grouped family branch entries.
 * @param {string|null} props.activeFamilyName - Name of currently active family filter.
 * @param {Function} props.handleSelectFamily - Handler to select family branch filter.
 * @returns {React.ReactElement} The rendered scrollable directory content container.
 *
 * @example
 * <DirectoryTabsContent
 *   currentTab="job"
 *   jobGroups={[{ name: 'Teacher', count: 4, people: [] }]}
 *   activeJobName="Teacher"
 *   handleSelectJob={(job) => console.log(job)}
 * />
 *
 * @example
 * <DirectoryTabsContent
 *   currentTab="place"
 *   inSidebar={true}
 *   locationHierarchyTree={[]}
 *   collapsedNodes={new Set()}
 *   toggleCollapse={(k) => console.log(k)}
 * />
 */
const DirectoryTabsContent = ({
    currentTab, inSidebar = false, locationHierarchyTree, collapsedNodes, toggleCollapse,
    activePlaceName, activeItemRef, handleSelectRegion, handleSelectLocation,
    jobGroups, activeJobName, handleSelectJob, familyGroups, activeFamilyName, handleSelectFamily
}) => {
    const placesProps = {
        locationHierarchyTree, collapsedNodes, toggleCollapse, activePlaceName,
        isPlaceMatch, activeItemRef, handleSelectRegion, handleSelectLocation, cleanLocationDisplayName
    };
    const jobsProps = { jobGroups, activeJobName, activeItemRef, handleSelectJob };
    const familiesProps = { familyGroups, activeFamilyName, activeItemRef, handleSelectFamily };

    return (
        <div className={inSidebar ? "flex-1 overflow-y-auto custom-scrollbar px-4 py-2 space-y-1 pb-24" : "flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1"}>
            {currentTab === 'place' && <DirectoryPlacesTab {...placesProps} />}
            {currentTab === 'job' && <DirectoryJobsTab {...jobsProps} />}
            {currentTab === 'family' && <DirectoryFamiliesTab {...familiesProps} />}
        </div>
    );
};

/**
 * Renders the quick directory selector panel or sidebar view for navigating places,
 * occupations, and family branches across the tree.
 *
 * @param {Object} props - Component properties.
 * @param {Object} props.tree - Current genealogy tree data model.
 * @param {Object|null} props.activeFilter - Active filter state.
 * @param {Function} props.onFilterBy - Callback to apply selected filter.
 * @param {Function} props.onFlyToLocation - Callback to center map on location.
 * @param {Function} props.onFlyToRegion - Callback to center map on region.
 * @param {boolean} props.showMap - Whether map view is active.
 * @param {Function} props.onClose - Callback to close selector panel.
 * @param {boolean} [props.inSidebar=false] - Whether selector renders in sidebar.
 * @param {string} [props.initialTab='place'] - Initial active directory tab.
 * @returns {React.ReactElement} The rendered quick directory selector element.
 *
 * @example
 * <QuickDirectorySelector
 *   tree={{ people: {} }}
 *   activeFilter={null}
 *   onFilterBy={(type, val) => console.log(type, val)}
 *   onClose={() => console.log('closed')}
 * />
 *
 * @example
 * <QuickDirectorySelector
 *   tree={treeData}
 *   inSidebar={true}
 *   initialTab="job"
 *   onFilterBy={handleFilter}
 * />
 */
const QuickDirectorySelector = ({ 
    tree, activeFilter, onFilterBy, onFlyToLocation, onFlyToRegion, showMap, onClose,
    inSidebar = false, initialTab = 'place'
}) => {
    const dirData = useQuickDirectoryData({ tree, activeFilter, onFilterBy, onFlyToLocation, onFlyToRegion, initialTab });

    const headerProps = {
        currentTab: dirData.currentTab,
        onSelectTab: tab => { dirData.setCurrentTab(tab); dirData.setSearchQuery(''); },
        currentTotalCount: dirData.currentTotalCount, countLabel: dirData.countLabel,
        searchQuery: dirData.searchQuery, setSearchQuery: dirData.setSearchQuery, inSidebar, onClose
    };

    const stopPropagation = e => e.stopPropagation();

    return (
        <div 
            className={inSidebar 
                ? "flex flex-col h-full w-full pt-[68px] overflow-hidden bg-white interactive-element" 
                : "interactive-element quick-directory-selector export-ignore absolute top-20 left-4 z-30 w-76 max-h-[calc(100vh-140px)] bg-white/95 backdrop-blur-md rounded-2xl shadow-xl border border-slate-200/80 flex flex-col overflow-hidden animate-fade-in pointer-events-auto select-auto"
            }
            data-export-ignore="true"
            onPointerDown={stopPropagation} onPointerMove={stopPropagation} onPointerUp={stopPropagation}
            onWheel={stopPropagation} onClick={stopPropagation} onMouseDown={stopPropagation}
            onMouseUp={stopPropagation} onTouchStart={stopPropagation}
        >
            <DirectoryHeader {...headerProps} />
            <DirectoryTabsContent {...dirData} inSidebar={inSidebar} />
        </div>
    );
};

/**
 * Injects the Leaflet CSS stylesheet into the document head if not already loaded.
 *
 * @example
 * ensureLeafletStyles();
 * // => Appends <link id="leaflet-css" ...> to document.head if missing
 *
 * @example
 * ensureLeafletStyles();
 * // => No-op if stylesheet already loaded
 */
const ensureLeafletStyles = () => {
    if (!document.getElementById('leaflet-css')) {
        const link = document.createElement('link');
        link.id = 'leaflet-css';
        link.rel = 'stylesheet';
        link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
        document.head.appendChild(link);
    }
};

/**
 * Generates inline HTML markup for a Leaflet custom location pin marker.
 *
 * @param {string} place - The location label to display on the marker pin
 * @param {number} count - The count of individuals associated with this location
 * @param {boolean} isSelected - Whether this marker represents the currently active filter
 * @returns {string} HTML string representing the styled marker bubble
 *
 * @example
 * _buildMapMarkerHtml('Kochi', 42, true)
 * // => '<div style="display:flex;align-items:center;...background:#e11d48...<span>📍 Kochi</span>...'
 *
 * @example
 * _buildMapMarkerHtml('Thrissur', 15, false)
 * // => '<div style="display:flex;align-items:center;...background:#2563eb...<span>📍 Thrissur</span>...'
 */
function _buildMapMarkerHtml(place, count, isSelected) {
    const bg = isSelected ? '#e11d48' : '#2563eb';
    const padding = isSelected ? '6px 12px' : '4px 9px';
    const shadow = isSelected
        ? '0 0 0 4px rgba(225,29,72,0.3), 0 6px 18px rgba(0,0,0,0.35)'
        : '0 4px 14px rgba(0,0,0,0.3)';
    return `
            <div style="display:flex;align-items:center;justify-content:center;background:${bg};color:white;border-radius:9999px;padding:${padding};font-size:11.5px;font-weight:bold;box-shadow:${shadow};border:2px solid white;white-space:nowrap;cursor:pointer;transform:translate(-50%, -50%);transition:all 0.2s ease;">
                <span>📍 ${place}</span>
                <span style="background:rgba(255,255,255,0.28);border-radius:9999px;padding:0.5px 5px;margin-left:4px;font-size:10px;">${count}</span>
            </div>
        `;
}

/**
 * Creates an HTML divIcon instance for a Leaflet geographical marker.
 *
 * @param {object} L - The global Leaflet namespace object.
 * @param {string} place - The location label to display on the marker pin.
 * @param {number} count - The count of individuals associated with this location.
 * @param {boolean} isSelected - Whether this marker represents the currently active filter.
 * @returns {object} Leaflet divIcon object configured with custom styling.
 *
 * @example
 * createMapMarkerIcon(L, 'Kochi', 42, true)
 * // => L.divIcon with rose background (#e11d48) and enlarged padding
 *
 * @example
 * createMapMarkerIcon(L, 'Thrissur', 15, false)
 * // => L.divIcon with blue background (#2563eb) and standard padding
 */
const createMapMarkerIcon = (L, place, count, isSelected) => {
    return L.divIcon({
        className: 'custom-map-marker',
        html: _buildMapMarkerHtml(place, count, isSelected),
        iconSize: [0, 0],
        iconAnchor: [0, 0]
    });
};

/**
 * Adjusts the map view to either focus on an active location marker or fit all bounds.
 *
 * @param {object} map - Leaflet map instance.
 * @param {Array<{place: string, coords: [number, number], marker: object}>} markers - Registered map markers.
 * @param {string|null} activePlaceName - Currently selected place name, if any.
 * @param {Array<[number, number]>} bounds - Coordinates representing all plotted markers.
 *
 * @example
 * adjustMapViewToBounds(map, [{ place: 'Kochi', coords: [9.93, 76.26] }], 'Kochi', [[9.93, 76.26]])
 * // => Focuses map on [9.93, 76.26] at specific location zoom level
 *
 * @example
 * adjustMapViewToBounds(map, markers, null, [[9.93, 76.26], [10.52, 76.21]])
 * // => Executes map.fitBounds with padding and maxZoom 12
 */
const adjustMapViewToBounds = (map, markers, activePlaceName, bounds) => {
    if (activePlaceName) {
        const target = (markers || []).find(m => m.place.toLowerCase().trim() === activePlaceName.toLowerCase().trim());
        if (target) {
            map.setView(target.coords, getZoomForLocation(activePlaceName));
            return;
        }
    }
    if (bounds && bounds.length > 0) {
        const maxZoom = activePlaceName ? getZoomForLocation(activePlaceName) : 12;
        map.fitBounds(bounds, { padding: [80, 80], maxZoom });
    }
};

/**
 * Instantiates and binds Leaflet markers for a list of grouped locations on the map.
 *
 * @param {Object} options
 * @param {Object} options.L - Global Leaflet namespace.
 * @param {Object} options.map - Leaflet map instance.
 * @param {Array<{ place: string, count: number }>} options.placeGroups - Grouped location statistics.
 * @param {string|null} options.activePlaceName - Currently focused place name, if any.
 * @param {Function} options.onFilterBy - Callback invoked when a marker pin is clicked.
 * @returns {{ markers: Array<{ place: string, coords: [number, number], marker: Object }>, bounds: Array<[number, number]> }} Created marker records and bounding coordinates.
 *
 * @example
 * const { markers, bounds } = createAndBindMapMarkers({
 *   L, map, placeGroups: [{ place: 'Thrissur', count: 12 }],
 *   activePlaceName: 'Thrissur', onFilterBy: (t, v) => {}
 * });
 *
 * @example
 * const { markers } = createAndBindMapMarkers({
 *   L, map, placeGroups: [], activePlaceName: null, onFilterBy: () => {}
 * });
 */
function createAndBindMapMarkers({ L, map, placeGroups, activePlaceName, onFilterBy }) {
    const markers = [];
    const bounds = [];

    for (const group of placeGroups) {
        const coords = resolveLocationCoords(group.place);
        if (coords) {
            bounds.push(coords);
            const isSelected = activePlaceName && activePlaceName.toLowerCase().trim() === group.place.toLowerCase().trim();
            const icon = createMapMarkerIcon(L, group.place, group.count, isSelected);
            const marker = L.marker(coords, { icon }).addTo(map);
            marker.on('click', () => {
                onFilterBy('place', group.place);
                map.flyTo(coords, getZoomForLocation(group.place), { duration: 0.8 });
            });
            markers.push({ place: group.place, coords, marker });
        }
    }
    return { markers, bounds };
}

/**
 * Refreshes custom HTML divIcons for existing markers to reflect selection states and counts.
 *
 * @param {Object} options
 * @param {Object} options.L - Global Leaflet namespace.
 * @param {Array<{ place: string, marker: Object }>} options.markers - Active marker entries.
 * @param {Array<{ place: string, count: number }>} options.placeGroups - Place counts.
 * @param {string|null} options.activePlaceName - Selected location name.
 *
 * @example
 * updateMarkerIcons({ L: window.L, markers, placeGroups, activePlaceName: 'Thrissur' });
 *
 * @example
 * updateMarkerIcons({ L: null, markers: [] });
 */
function updateMarkerIcons({ L, markers, placeGroups, activePlaceName }) {
    if (!L || !markers) return;
    markers.forEach(({ place, marker }) => {
        const isSelected = activePlaceName && activePlaceName.toLowerCase().trim() === place.toLowerCase().trim();
        const count = placeGroups.find(g => g.place === place)?.count || 0;
        marker.setIcon(createMapMarkerIcon(L, place, count, isSelected));
    });
}

/**
 * Smoothly navigates the Leaflet map to frame a geographical region or multiple place coordinates.
 *
 * @param {Object} options
 * @param {Object} options.L - Global Leaflet namespace.
 * @param {Object} options.map - Leaflet map instance.
 * @param {string} options.regionName - Geographical region name.
 * @param {Array<{ place: string }>} [options.regionPlaces] - Places belonging to the region.
 *
 * @example
 * flyMapToRegion({ L: window.L, map, regionName: 'Kerala', regionPlaces: [{ place: 'Kochi' }, { place: 'Thrissur' }] });
 *
 * @example
 * flyMapToRegion({ L: window.L, map, regionName: 'India', regionPlaces: [] });
 */
function flyMapToRegion({ L, map, regionName, regionPlaces }) {
    if (!map || !L) return;
    const zoom = getZoomForLocation(regionName);
    let coordsList = (regionPlaces || [])
        .map(p => resolveLocationCoords(p.place))
        .filter(Boolean);
    if (coordsList.length === 0) {
        const regionCoords = resolveLocationCoords(regionName);
        if (regionCoords) coordsList = [regionCoords];
    }
    if (coordsList.length === 1) {
        map.flyTo(coordsList[0], zoom, { duration: 0.8 });
    } else if (coordsList.length > 1) {
        const bounds = L.latLngBounds(coordsList);
        map.fitBounds(bounds, { padding: [60, 60], maxZoom: zoom });
    }
}

/**
 * Instantiates and configures a Leaflet map with standard tiles and bottom-right zoom control.
 *
 * @param {HTMLElement} container - DOM element container for the map.
 * @param {Object} L - Global Leaflet library instance.
 * @param {[number, number]} [center=[10.3071, 76.3333]] - Initial map center coordinate [lat, lng].
 * @param {number} [zoom=9] - Initial zoom level.
 * @returns {Object} Configured Leaflet map instance.
 *
 * @example
 * const map = setupLeafletMapInstance(containerRef.current, window.L);
 *
 * @example
 * const map = setupLeafletMapInstance(containerRef.current, window.L, [9.93, 76.26], 11);
 */
function setupLeafletMapInstance(container, L, center = [10.3071, 76.3333], zoom = 9) {
    const map = L.map(container, {
        zoomControl: false,
        attributionControl: false
    }).setView(center, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(map);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '© OpenStreetMap'
    }).addTo(map);

    return map;
}

/**
 * Hook tracking the last selected map location and re-activating place filters
 * when the user re-opens the map view without an active filter.
 *
 * @param {object} params
 * @param {object|null} params.activeFilter - Active filter object ({ filterType, value })
 * @param {boolean} params.showMap - Whether the map view is currently displayed
 * @param {Function} params.onFilterBy - Filter activation callback
 * @returns {{
 *   activePlaceName: string|null,
 *   lastSelectedPlace: string|null
 * }}
 *
 * @example
 * const { activePlaceName } = useMapActivePlaceTracking({
 *   activeFilter: { filterType: 'place', value: 'Thrissur' },
 *   showMap: true,
 *   onFilterBy: () => {}
 * });
 *
 * @example
 * const { activePlaceName } = useMapActivePlaceTracking({
 *   activeFilter: null,
 *   showMap: false,
 *   onFilterBy: () => {}
 * });
 */
function useMapActivePlaceTracking({ activeFilter, showMap, onFilterBy }) {
    const [lastSelectedPlace, setLastSelectedPlace] = useState(null);

    // Track active place when explicitly set
    useEffect(() => {
        if (activeFilter?.filterType === 'place' && activeFilter.value) {
            setLastSelectedPlace(activeFilter.value);
        }
    }, [activeFilter]);

    // When returning to map view without an active filter, re-activate the last selected place if available
    const prevShowMapRef = useRef(showMap);
    useEffect(() => {
        if (!prevShowMapRef.current && showMap) {
            if (!activeFilter && lastSelectedPlace) {
                onFilterBy('place', lastSelectedPlace);
            }
        }
        prevShowMapRef.current = showMap;
    }, [showMap, activeFilter, lastSelectedPlace, onFilterBy]);

    const activePlaceName = activeFilter?.filterType === 'place' ? activeFilter.value : lastSelectedPlace;

    return { activePlaceName, lastSelectedPlace };
}

/**
 * Asynchronously loads Leaflet resources and instantiates the map instance with markers.
 *
 * @param {object} options
 * @param {React.MutableRefObject<object|null>} options.mapContainerRef - Ref to container DOM element
 * @param {React.MutableRefObject<object|null>} options.mapInstanceRef - Ref to active Leaflet Map
 * @param {React.MutableRefObject<Array<object>>} options.markersRef - Ref to active map markers array
 * @param {Array<object>} options.placeGroups - Groups of places with geolocation coordinates
 * @param {string|null} options.activePlaceName - Currently selected place name
 * @param {Function} options.onFilterBy - Filter callback when a marker is clicked
 * @param {() => boolean} options.isStillMounted - Checker returning whether the component is still mounted
 * @returns {Promise<void>}
 *
 * @example
 * await performLeafletInitialization({
 *   mapContainerRef: { current: null },
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] },
 *   placeGroups: [],
 *   activePlaceName: null,
 *   onFilterBy: () => {},
 *   isStillMounted: () => false
 * });
 *
 * @example
 * await performLeafletInitialization({
 *   mapContainerRef: { current: document.createElement('div') },
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] },
 *   placeGroups: [{ place: 'Kochi', count: 1 }],
 *   activePlaceName: 'Kochi',
 *   onFilterBy: () => {},
 *   isStillMounted: () => true
 * });
 */
async function performLeafletInitialization({
    mapContainerRef, mapInstanceRef, markersRef,
    placeGroups, activePlaceName, onFilterBy, isStillMounted
}) {
    if (mapInstanceRef.current) return;
    try {
        ensureLeafletStyles();
        await ScriptLoader.load('https://unpkg.com/leaflet@1.9.4/dist/leaflet.js');

        if (!isStillMounted() || !mapContainerRef.current || !window.L || mapInstanceRef.current) return;

        const L = window.L;
        const map = setupLeafletMapInstance(mapContainerRef.current, L);
        mapInstanceRef.current = map;
        const { markers, bounds } = createAndBindMapMarkers({
            L, map, placeGroups, activePlaceName, onFilterBy
        });
        markersRef.current = markers;

        adjustMapViewToBounds(map, markersRef.current, activePlaceName, bounds);
    } catch (err) {
        console.error("Map initialization failed:", err);
    }
}

/**
 * Hook asynchronously loading the Leaflet library and CSS stylesheet, creating the map
 * instance, plotting geographic markers for place groups, and fitting initial bounds.
 *
 * @param {object} params
 * @param {boolean} params.showMap - Whether map view is open
 * @param {Array<object>} params.placeGroups - Aggregated place groups with coordinates
 * @param {string|null} params.activePlaceName - Highlighted place name
 * @param {Function} params.onFilterBy - Marker click selection callback
 * @param {React.RefObject<HTMLElement>} params.mapContainerRef - Ref to map container div
 * @param {React.MutableRefObject<object|null>} params.mapInstanceRef - Ref holding Leaflet Map
 * @param {React.MutableRefObject<Array<object>>} params.markersRef - Ref holding plotted markers
 *
 * @example
 * useLeafletMapInitializer({
 *   showMap: true,
 *   placeGroups: [],
 *   activePlaceName: 'Kochi',
 *   onFilterBy: () => {},
 *   mapContainerRef: { current: null },
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] }
 * });
 *
 * @example
 * useLeafletMapInitializer({
 *   showMap: false,
 *   placeGroups: [],
 *   activePlaceName: null,
 *   onFilterBy: () => {},
 *   mapContainerRef: { current: null },
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] }
 * });
 */
function useLeafletMapInitializer({
    showMap, placeGroups, activePlaceName, onFilterBy,
    mapContainerRef, mapInstanceRef, markersRef
}) {
    useEffect(() => {
        let isMounted = true;
        if (!showMap && !mapInstanceRef.current) return;

        const timer = setTimeout(() => {
            performLeafletInitialization({
                mapContainerRef, mapInstanceRef, markersRef,
                placeGroups, activePlaceName, onFilterBy,
                isStillMounted: () => isMounted
            });
        }, 50);

        return () => {
            isMounted = false;
            clearTimeout(timer);
        };
    }, [showMap, placeGroups, activePlaceName, onFilterBy, mapContainerRef, mapInstanceRef, markersRef]);
}

/**
 * Hook synchronizing marker icons with current selection, panning/flying to active place,
 * and invalidating map container size on layout or sidebar width transitions.
 *
 * @param {object} params
 * @param {React.MutableRefObject<object|null>} params.mapInstanceRef - Ref to Leaflet Map instance
 * @param {React.MutableRefObject<Array<object>>} params.markersRef - Ref to plotted markers
 * @param {Array<object>} params.placeGroups - Aggregated place groups
 * @param {string|null} params.activePlaceName - Highlighted place name
 * @param {boolean} params.showMap - Whether map is visible
 * @param {number} params.sidebarWidth - Width of details sidebar
 * @param {boolean} params.isSidebarVisible - Whether sidebar is shown
 *
 * @example
 * useLeafletMarkerSync({
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] },
 *   placeGroups: [],
 *   activePlaceName: 'Thrissur',
 *   showMap: true,
 *   sidebarWidth: 360,
 *   isSidebarVisible: false
 * });
 *
 * @example
 * useLeafletMarkerSync({
 *   mapInstanceRef: { current: null },
 *   markersRef: { current: [] },
 *   placeGroups: [],
 *   activePlaceName: null,
 *   showMap: false,
 *   sidebarWidth: 360,
 *   isSidebarVisible: true
 * });
 */
function useLeafletMarkerSync({
    mapInstanceRef, markersRef, placeGroups,
    activePlaceName, showMap, sidebarWidth, isSidebarVisible
}) {
    useEffect(() => {
        if (!mapInstanceRef.current || !window.L) return;
        updateMarkerIcons({ L: window.L, markers: markersRef.current, placeGroups, activePlaceName });
        if (activePlaceName && showMap) {
            flyMapToPlace(mapInstanceRef.current, markersRef.current, activePlaceName);
        }
    }, [activePlaceName, placeGroups, showMap, mapInstanceRef, markersRef]);

    useEffect(() => {
        if (mapInstanceRef.current && showMap) {
            const timer = setTimeout(() => {
                mapInstanceRef.current?.invalidateSize();
            }, 60);
            return () => clearTimeout(timer);
        }
    }, [showMap, sidebarWidth, isSidebarVisible, mapInstanceRef]);
}

/**
 * Custom hook to initialize and manage Leaflet map instance lifecycle,
 * geographic marker synchronization, flyTo panning, and container resize invalidation.
 *
 * @param {Object} options
 * @param {FamilyTree} options.tree - Family tree dataset
 * @param {Object|null} options.activeFilter - Current active filter { filterType, value }
 * @param {Function} options.onFilterBy - Callback invoked when clicking on a marker
 * @param {boolean} options.showMap - Whether the map view is currently visible
 * @param {number} options.sidebarWidth - Width of the collapsible sidebar in pixels
 * @param {boolean} options.isSidebarVisible - Whether any sidebar is visible
 * @returns {{
 *   mapContainerRef: React.RefObject<HTMLDivElement>,
 *   mapInstanceRef: React.MutableRefObject<Object>,
 *   markersRef: React.MutableRefObject<Array>,
 *   activePlaceName: string|null,
 *   placeGroups: Map
 * }}
 *
 * @example
 * const { mapContainerRef } = useLeafletMap({
 *   tree,
 *   activeFilter,
 *   onFilterBy,
 *   showMap,
 *   sidebarWidth,
 *   isSidebarVisible
 * });
 *
 * @example
 * // Bind container ref to Leaflet map mount DOM element
 * <div ref={mapContainerRef} className="absolute inset-0 z-0 w-full h-full" />
 */
function useLeafletMap({ tree, activeFilter, onFilterBy, showMap, sidebarWidth, isSidebarVisible }) {
    const mapContainerRef = useRef(null);
    const mapInstanceRef = useRef(null);
    const markersRef = useRef([]);

    const { activePlaceName } = useMapActivePlaceTracking({ activeFilter, showMap, onFilterBy });
    const placeGroups = useMemo(() => computePlaceGroups(tree), [tree]);

    useLeafletMapInitializer({
        showMap, placeGroups, activePlaceName, onFilterBy,
        mapContainerRef, mapInstanceRef, markersRef
    });

    useLeafletMarkerSync({
        mapInstanceRef, markersRef, placeGroups, activePlaceName,
        showMap, sidebarWidth, isSidebarVisible
    });

    return { mapContainerRef, mapInstanceRef, markersRef, activePlaceName, placeGroups };
}

